    /**
     * The reported Cerberus bug, end-to-end: the player owns a Scorching bow
     * (ranged demonbane, +30% vs the demon Cerberus), a blowpipe, dragon
     * arrows, dragon javelins and a blessing, and is sitting on the blowpipe
     * with javelins worn. The RANGED search must recommend the Scorching bow
     * WITH the dragon arrows it can actually fire — before the compatibility
     * + ammo-pairing fixes it recommended javelins in the ammo slot of a bow
     * (their +150 rstr was summed as if a bow could fire them) and the
     * blowpipe incumbent could never lose to a bow tried without arrows.
     */
    @Test
    public void cerberusRanged_ownedScorchingBow_recommendedWithArrowsNeverJavelins() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = TOXIC_BLOWPIPE;
        live[AMMO_SLOT] = DRAGON_JAVELIN;

        Set<Integer> owned = new HashSet<>(Arrays.asList(
                SCORCHING_BOW, TOXIC_BLOWPIPE, DRAGON_ARROW, DRAGON_JAVELIN, RADAS_BLESSING_4));
        GearOptimizer.PriceSource prices = id -> owned.contains(id) ? 0L : 100_000_000L;

        GearOptimizer.Result result = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).owned(owned).priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.RANGED)
                .build());

        assertEquals("the demonbane Scorching bow must beat the blowpipe on a demon target",
                SCORCHING_BOW, weaponIdIn(result));
        assertEquals("the bow must be paired with the arrows it fires, never ballista javelins",
                DRAGON_ARROW, itemIdInSlot(result, AMMO_SLOT));
    }

    /**
     * A consuming weapon with NO compatible ammo available: worn javelins are
     * DPS-invisible behind a bow (GearMapper skips them), so the freed slot
     * must go to the prayer-bonus blessing on the DPS tie — a bow must never
     * be shown wearing ammo it cannot fire.
     */
    @Test
    public void bowWithoutOwnedArrows_ammoSlotFallsBackToBlessingNeverKeepsJavelins() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = SCORCHING_BOW;
        live[AMMO_SLOT] = DRAGON_JAVELIN;

        Set<Integer> owned = new HashSet<>(Arrays.asList(SCORCHING_BOW, DRAGON_JAVELIN, RADAS_BLESSING_4));
        GearOptimizer.PriceSource prices = id -> owned.contains(id) ? 0L : 100_000_000L;

        GearOptimizer.Result result = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).owned(owned).priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.RANGED)
                .build());

        assertEquals(SCORCHING_BOW, weaponIdIn(result));
        assertEquals("with no arrows owned, the DPS-invisible slot must hold the blessing, not javelins",
                RADAS_BLESSING_4, itemIdInSlot(result, AMMO_SLOT));
    }

    /**
     * A self-supplying bow (crystal bow) uses no worn ammo at all: worn
     * arrows contribute nothing, so — exactly like the blowpipe case above —
     * the ammo slot must fall to the best prayer blessing.
     */
    @Test
    public void crystalBow_ammoSlotPrefersBlessingOverArrowsItNeverFires() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = CRYSTAL_BOW;
        live[AMMO_SLOT] = DRAGON_ARROW;

        Set<Integer> owned = new HashSet<>(Arrays.asList(CRYSTAL_BOW, DRAGON_ARROW, RADAS_BLESSING_4));
        GearOptimizer.PriceSource prices = id -> owned.contains(id) ? 0L : 100_000_000L;

        GearOptimizer.Result result = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).owned(owned).priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.RANGED)
                .build());

        assertEquals(CRYSTAL_BOW, weaponIdIn(result));
        assertEquals(RADAS_BLESSING_4, itemIdInSlot(result, AMMO_SLOT));
    }

    // -------------------------------------------------- speed-blind pruning (blowpipe)

    /**
     * The blowpipe-pruning bug: the weapon slot used to be pruned to the top
     * {@link GearOptimizer#DEFAULT_CANDIDATES_PER_SLOT} by the target-blind
     * linear proxy {@code arange + 2*rstr}, which scores the 3-tick Toxic
     * blowpipe (raw 30 + 2*20 = 70) below EVERY slow high-bonus bow/crossbow/
     * ballista — its entire value is attack speed, invisible to the proxy —
     * so it was discarded before its real DPS was ever computed. Here it
     * competes against 13 affordable ranged weapons that ALL out-score it on
     * the raw proxy; ranked by real evaluated DPS versus a low-defence target
     * (where the fast blowpipe is genuinely best-in-slot, as in game) it must
     * survive pruning and win.
     */
    @Test
    public void blowpipeSurvivesWeaponPruning_andWinsOnALowDefenceTarget() {
        int[] live = emptyLoadout(); // nothing owned — every pick is a purchase

        final int HEAVY_BALLISTA = 19481;
        final int LIGHT_BALLISTA = 19478;
        final int ZARYTE_CROSSBOW = 26374;
        final int ARMADYL_CROSSBOW = 11785;
        final int RUNE_CROSSBOW = 9185;
        final int DRAGON_CROSSBOW = 21902;
        final int DRAGON_HUNTER_CROSSBOW = 21012;
        final int KARILS_CROSSBOW = 4734;
        final int HUNTERS_SUNLIGHT_CROSSBOW = 28869;
        final int THIRD_AGE_BOW = 12424;
        final int DARK_BOW = 11235;
        final int TWISTED_BOW = 20997;
        final int VENATOR_BOW = 27610;
        // Ammo for the competitors, so none of them is handicapped:
        final int RUNITE_BOLTS = 9144;

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        for (int weapon : new int[] { TOXIC_BLOWPIPE, HEAVY_BALLISTA, LIGHT_BALLISTA, ZARYTE_CROSSBOW,
                ARMADYL_CROSSBOW, RUNE_CROSSBOW, DRAGON_CROSSBOW, DRAGON_HUNTER_CROSSBOW, KARILS_CROSSBOW,
                HUNTERS_SUNLIGHT_CROSSBOW, THIRD_AGE_BOW, DARK_BOW, TWISTED_BOW, VENATOR_BOW }) {
            fixed.put(weapon, 100_000L);
        }
        fixed.put(RUNITE_BOLTS, 10_000L);
        fixed.put(DRAGON_ARROW, 10_000L);
        fixed.put(DRAGON_JAVELIN, 10_000L);
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        Monster dustDevil = MonsterRepository.getInstance()
                .byName("Dust devil (Catacombs of Kourend)").get();

        GearOptimizer.Result result = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, dustDevil, maxedPlayerTemplate())
                .budget(10_000_000L)
                .priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.RANGED)
                .build());

        assertEquals("the fast blowpipe must survive pruning and beat every slow high-bonus alternative",
                TOXIC_BLOWPIPE, weaponIdIn(result));
    }

    // -------------------------------------------------- style constraint (item #6e)

    private static final int ABYSSAL_BLUDGEON = 13263; // crush weapon
    private static final int MAGIC_SHORTBOW = 861;     // ranged weapon

    /**
     * The per-style optimum proof the 5-way selector rests on: with a slash
     * weapon (whip) AND a crush weapon (bludgeon) both owned, constraining the
     * search to SLASH must pick the whip and constraining to CRUSH must pick
     * the bludgeon — each result's driving style is of the constrained type.
     */
    @Test
    public void styleConstraint_crushAndSlashPickDifferentBestWeapons() {
        int[] live = emptyLoadout();
        live[3] = ABYSSAL_WHIP;

        Set<Integer> owned = new HashSet<>(Arrays.asList(ABYSSAL_WHIP, ABYSSAL_BLUDGEON));
        GearOptimizer.PriceSource prices = id -> owned.contains(id) ? 0L : 100_000_000L;

        GearOptimizer.Result slash = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).owned(owned).priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.SLASH)
                .build());
        GearOptimizer.Result crush = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).owned(owned).priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.CRUSH)
                .build());

        assertEquals("SLASH constraint must pick the whip", ABYSSAL_WHIP, weaponIdIn(slash));
        assertEquals(com.ospulse.combat.CombatStyle.SLASH, slash.style().type());
        assertEquals("CRUSH constraint must pick the bludgeon", ABYSSAL_BLUDGEON, weaponIdIn(crush));
        assertEquals(com.ospulse.combat.CombatStyle.CRUSH, crush.style().type());
        assertTrue("both constrained results must actually compute a DPS",
                slash.dps().dps() > 0 && crush.dps().dps() > 0);
    }

    /**
     * The #6g scenario in engine terms: melee (whip) out-DPSes the owned bow,
     * so the UNCONSTRAINED search rightly picks the whip — but a RANGED
     * constraint must anchor to the bow, never "helpfully" fall back to melee.
     */
    @Test
    public void styleConstraint_rangedKeepsRangedWeaponEvenWhenMeleeDpsIsHigher() {
        int[] live = emptyLoadout();
        live[3] = MAGIC_SHORTBOW;

        Set<Integer> owned = new HashSet<>(Arrays.asList(ABYSSAL_WHIP, MAGIC_SHORTBOW));
        GearOptimizer.PriceSource prices = id -> owned.contains(id) ? 0L : 100_000_000L;

        GearOptimizer.Result unconstrained = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).owned(owned).priceSource(prices)
                .build());
        GearOptimizer.Result ranged = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).owned(owned).priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.RANGED)
                .build());

        assertEquals("sanity: unconstrained, the higher-DPS whip wins", ABYSSAL_WHIP, weaponIdIn(unconstrained));
        assertEquals("RANGED constraint must keep the bow", MAGIC_SHORTBOW, weaponIdIn(ranged));
        assertEquals(com.ospulse.combat.CombatStyle.RANGED, ranged.style().type());
        assertTrue("the constrained result's DPS is legitimately lower than melee's, never swapped for it",
                ranged.dps().dps() <= unconstrained.dps().dps());
    }

    /** Nothing owned/affordable can attack with the constrained type: the result is explicitly unusable (no style, zero DPS), not a silent fallback. */
    @Test
    public void styleConstraint_noWeaponOfThatTypeAvailable_yieldsNoStyleAndZeroDps() {
        int[] live = emptyLoadout();
        live[3] = ABYSSAL_WHIP;

        GearOptimizer.PriceSource prices = id -> id == ABYSSAL_WHIP ? 0L : 100_000_000L;

        GearOptimizer.Result result = GearOptimizer.optimize(GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L).priceSource(prices)
                .style(com.ospulse.combat.CombatStyle.MAGIC)
                .build());

        assertTrue("no magic weapon available -> zero DPS", result.dps().dps() == 0.0);
        assertEquals("no driving style must be reported", null, result.style());
    }
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.EquipmentStats;
import com.ospulse.session.GearSnapshot;

import org.junit.Test;

import java.util.Arrays;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers {@link WhatIfLoadout}: merging a live loadout with a
 * {@link LoadoutOverride} and recomputing {@link EquipmentStats} purely from
 * bundled data (no ItemManager/client thread) — the Phase 2 what-if engine.
 * Real item ids are used throughout so this doubles as an integration check
 * that {@link BundledSlotStatsLookup} + {@code GearMapper} agree.
 */
public class WhatIfLoadoutTest {
    static { com.ospulse.combat.BundledGson.set(new com.google.gson.Gson()); }

    private static final int ABYSSAL_WHIP = 4151;   // one-handed slash weapon, 82 str/aslash, speed 4
    private static final int TWISTED_BOW = 20997;    // two-handed ranged weapon
    private static final int RUNE_KITESHIELD = 1201; // shield
    private static final int RUNE_DEFENDER = 24142;  // one-handed-weapon-only off-hand (still slot 5)
    private static final int DRAGON_SCIMITAR = 4587; // one-handed slash weapon

    private static int[] emptyLoadout() {
        int[] ids = new int[GearSnapshot.EQUIPMENT_SLOT_COUNT];
        Arrays.fill(ids, -1);
        return ids;
    }

    // -------------------------------------------------- effectiveItemIds

    @Test
    public void effectiveItemIds_noOverride_returnsLiveIdsUnchanged() {
        int[] live = emptyLoadout();
        live[3] = ABYSSAL_WHIP;
        int[] effective = WhatIfLoadout.effectiveItemIds(live, LoadoutOverride.empty());
        assertEquals(ABYSSAL_WHIP, effective[3]);
        // must not be the same array instance (caller's live array is never mutated)
        assertFalse(effective == live);
    }

    @Test
    public void effectiveItemIds_overrideReplacesOneSlotOnly() {
        int[] live = emptyLoadout();
        live[3] = ABYSSAL_WHIP;
        live[0] = 1234; // some head slot id, irrelevant to the override

        LoadoutOverride override = LoadoutOverride.empty().withSlot(3, DRAGON_SCIMITAR);
        int[] effective = WhatIfLoadout.effectiveItemIds(live, override);

        assertEquals(DRAGON_SCIMITAR, effective[3]);
        assertEquals(1234, effective[0]); // untouched slot survives

        // Live array itself must be unmodified.
        assertEquals(ABYSSAL_WHIP, live[3]);
    }

    // -------------------------------------------------- isTwoHanded

    @Test
    public void isTwoHanded_twistedBowIsTrue() {
        assertTrue(WhatIfLoadout.isTwoHanded(TWISTED_BOW));
    }

    @Test
    public void isTwoHanded_abyssalWhipIsFalse() {
        assertFalse(WhatIfLoadout.isTwoHanded(ABYSSAL_WHIP));
    }

    @Test
    public void isTwoHanded_unknownIdIsFalse() {
        assertFalse(WhatIfLoadout.isTwoHanded(99_999_999));
    }

    // -------------------------------------------------- equipWeapon / equipShield exclusivity

    @Test
    public void equipWeapon_twoHanded_emptiesExistingShieldOverride() {
        LoadoutOverride override = LoadoutOverride.empty().withSlot(WhatIfLoadout.SHIELD_SLOT, RUNE_KITESHIELD);
        LoadoutOverride afterEquip = WhatIfLoadout.equipWeapon(override, TWISTED_BOW);

        assertEquals(TWISTED_BOW, afterEquip.itemIdFor(WhatIfLoadout.WEAPON_SLOT));
        // 2H empties the shield slot rather than clearing its override — so a LIVE
        // shield is dropped too (see equipWeapon_twoHanded_dropsLiveShield).
        assertTrue(afterEquip.hasOverride(WhatIfLoadout.SHIELD_SLOT));
        assertEquals(LoadoutOverride.EMPTIED, afterEquip.itemIdFor(WhatIfLoadout.SHIELD_SLOT));
    }

    @Test
    public void equipWeapon_twoHanded_dropsLiveShield() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.SHIELD_SLOT] = RUNE_KITESHIELD; // live shield, no override

        LoadoutOverride afterEquip = WhatIfLoadout.equipWeapon(LoadoutOverride.empty(), TWISTED_BOW);
        int[] effective = WhatIfLoadout.effectiveItemIds(live, afterEquip);

        assertEquals(TWISTED_BOW, effective[WhatIfLoadout.WEAPON_SLOT]);
        assertEquals("a live shield must be unequipped by a 2H weapon", 0, effective[WhatIfLoadout.SHIELD_SLOT]);
    }

    @Test
    public void equipWeapon_oneHanded_preservesShieldOverride() {
        LoadoutOverride override = LoadoutOverride.empty().withSlot(WhatIfLoadout.SHIELD_SLOT, RUNE_KITESHIELD);
        LoadoutOverride afterEquip = WhatIfLoadout.equipWeapon(override, ABYSSAL_WHIP);

        assertEquals(ABYSSAL_WHIP, afterEquip.itemIdFor(WhatIfLoadout.WEAPON_SLOT));
        assertTrue(afterEquip.hasOverride(WhatIfLoadout.SHIELD_SLOT));
        assertEquals(RUNE_KITESHIELD, afterEquip.itemIdFor(WhatIfLoadout.SHIELD_SLOT));
    }

    @Test
    public void equipShield_whenLiveWeaponTwoHanded_emptiesTheLiveWeapon() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = TWISTED_BOW;

        LoadoutOverride override = LoadoutOverride.empty(); // no weapon override — live gear IS the 2H bow
        LoadoutOverride afterShield = WhatIfLoadout.equipShield(override, live, RUNE_KITESHIELD);

        assertEquals(RUNE_KITESHIELD, afterShield.itemIdFor(WhatIfLoadout.SHIELD_SLOT));
        // Clearing an (absent) override could never unequip the live 2H bow — the slot
        // is EMPTIED so the effective loadout has no weapon+shield clash (the #3a bug).
        assertTrue(afterShield.hasOverride(WhatIfLoadout.WEAPON_SLOT));
        assertEquals(LoadoutOverride.EMPTIED, afterShield.itemIdFor(WhatIfLoadout.WEAPON_SLOT));
        int[] effective = WhatIfLoadout.effectiveItemIds(live, afterShield);
        assertEquals("live 2H weapon must be unequipped by the shield", 0, effective[WhatIfLoadout.WEAPON_SLOT]);
        assertEquals(RUNE_KITESHIELD, effective[WhatIfLoadout.SHIELD_SLOT]);
    }

    @Test
    public void equipShield_whenOverriddenWeaponTwoHanded_emptiesWeapon() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = ABYSSAL_WHIP; // live weapon is 1H

        LoadoutOverride override = LoadoutOverride.empty().withSlot(WhatIfLoadout.WEAPON_SLOT, TWISTED_BOW); // overridden to 2H
        LoadoutOverride afterShield = WhatIfLoadout.equipShield(override, live, RUNE_KITESHIELD);

        assertEquals(RUNE_KITESHIELD, afterShield.itemIdFor(WhatIfLoadout.SHIELD_SLOT));
        // The effective (overridden) weapon is 2H, so equipping the shield empties the
        // weapon slot. (A friendlier "revert to the live 1H" is a deliberate non-goal —
        // both are clash-free; emptying keeps the exclusivity rule uniform.)
        assertTrue(afterShield.hasOverride(WhatIfLoadout.WEAPON_SLOT));
        assertEquals(LoadoutOverride.EMPTIED, afterShield.itemIdFor(WhatIfLoadout.WEAPON_SLOT));
    }

    @Test
    public void equipShield_whenWeaponOneHanded_preservesWeaponOverride() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = ABYSSAL_WHIP;

        LoadoutOverride override = LoadoutOverride.empty().withSlot(WhatIfLoadout.WEAPON_SLOT, DRAGON_SCIMITAR);
        LoadoutOverride afterShield = WhatIfLoadout.equipShield(override, live, RUNE_KITESHIELD);

        assertTrue(afterShield.hasOverride(WhatIfLoadout.WEAPON_SLOT));
        assertEquals(DRAGON_SCIMITAR, afterShield.itemIdFor(WhatIfLoadout.WEAPON_SLOT));
    }

    // -------------------------------------------------- buildEquipmentStats (integration)

    @Test
    public void buildEquipmentStats_appliesOverrideBonusesInstead_ofLive() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = ABYSSAL_WHIP;

        EquipmentStats liveStats = WhatIfLoadout.buildEquipmentStats(live, LoadoutOverride.empty());
        assertEquals(82, liveStats.aslash());
        assertEquals(82, liveStats.str());
        assertEquals(4, liveStats.weaponSpeedTicks());

        LoadoutOverride override = LoadoutOverride.empty().withSlot(WhatIfLoadout.WEAPON_SLOT, DRAGON_SCIMITAR);
        EquipmentStats whatIfStats = WhatIfLoadout.buildEquipmentStats(live, override);

        // Dragon scimitar: 67 aslash / 66 str / speed 4 (per weirdgloop equipment.json / cache data).
        assertEquals(67, whatIfStats.aslash());
        assertEquals(66, whatIfStats.str());

        // The live array itself must never be mutated by a what-if compute.
        assertEquals(ABYSSAL_WHIP, live[WhatIfLoadout.WEAPON_SLOT]);
    }

    @Test
    public void buildEquipmentStats_resetOverride_matchesLiveExactly() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = ABYSSAL_WHIP;
        live[WhatIfLoadout.SHIELD_SLOT] = RUNE_KITESHIELD;

        EquipmentStats liveStats = WhatIfLoadout.buildEquipmentStats(live, LoadoutOverride.empty());

        LoadoutOverride override = LoadoutOverride.empty()
                .withSlot(WhatIfLoadout.WEAPON_SLOT, DRAGON_SCIMITAR)
                .withoutSlot(WhatIfLoadout.WEAPON_SLOT); // reset back to live
        EquipmentStats resetStats = WhatIfLoadout.buildEquipmentStats(live, override);

        assertEquals(liveStats.aslash(), resetStats.aslash());
        assertEquals(liveStats.str(), resetStats.str());
        assertEquals(liveStats.weaponSpeedTicks(), resetStats.weaponSpeedTicks());
    }

    @Test
    public void buildEquipmentStats_twoHandedOverride_dropsShieldContribution() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = ABYSSAL_WHIP;
        live[WhatIfLoadout.SHIELD_SLOT] = RUNE_KITESHIELD;

        EquipmentStats liveStats = WhatIfLoadout.buildEquipmentStats(live, LoadoutOverride.empty());
        int liveDstab = liveStats.dstab(); // whip + kiteshield defence

        LoadoutOverride override = WhatIfLoadout.equipWeapon(LoadoutOverride.empty(), TWISTED_BOW);
        EquipmentStats whatIfStats = WhatIfLoadout.buildEquipmentStats(live, override);

        // Equipping the 2H bow EMPTIES the shield slot, so the effective loadout is
        // the twisted bow ONLY — the live kiteshield is unequipped and its defence
        // contribution dropped. (Previously equipWeapon merely cleared the shield
        // OVERRIDE, leaving the live kiteshield worn alongside a 2H weapon — an
        // impossible loadout whose summed bonuses inflated the readout/optimiser DPS.)
        int[] bowOnly = emptyLoadout();
        bowOnly[WhatIfLoadout.WEAPON_SLOT] = TWISTED_BOW;
        EquipmentStats bowOnlyStats = WhatIfLoadout.buildEquipmentStats(bowOnly, LoadoutOverride.empty());
        assertEquals("2H weapon must drop the live shield's contribution",
                bowOnlyStats.dstab(), whatIfStats.dstab());
        assertTrue("live kiteshield defence must be gone", whatIfStats.dstab() < liveDstab);
    }
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.CombatStyle;
import com.ospulse.combat.EquipmentIndexRepository;
import com.ospulse.combat.Monster;
import com.ospulse.combat.MonsterRepository;
import com.ospulse.combat.PlayerCombat;
import com.ospulse.session.GearSnapshot;
import com.ospulse.ui.sections.gear.OwnedVariantResolver;

import org.junit.Test;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

/**
 * Issue #11 Stage 3: investigates a reported bug where the optimiser
 * recommends a plain MA1 Saradomin cape (id 2412, mdmg 0) for a MAGIC search
 * while the player owns an Imbued saradomin cape (deadman) (id 29617,
 * amagic +15, dmagic +15, mdmg +20 — per {@code equipment_stats.min.json}) —
 * a strictly better item — sitting in their bank. Mirrors
 * {@link GearOptimizerTest} / {@link GearOptimizerCombatGateTest}'s fixture
 * and setup style.
 *
 * <p><b>Finding (see the two tests below): the suffix gap in {@link
 * OwnedVariantResolver#SUFFIXES} is NOT what lets {@link GearOptimizer}
 * itself pick the plain cape over an owned 29617</b> — {@link
 * #magicSearch_ownedDeadmanCape_neverRecommendsWorsePlainCape} is a direct,
 * literal reproduction attempt (owned = {29617}, no exclusions) and PASSES
 * on the very first run, unmodified: 29617's id reaches the optimiser
 * exactly as owned, survives candidate pruning (owned items are exempt —
 * {@code mandatoryCandidate()}), and {@code CandidateScore.tieBreakScore}
 * (used to break DPS ties) sums EVERY offensive/defensive/prayer bonus
 * regardless of the search's style constraint — so 29617's higher magic
 * stats win outright on a MAGIC search, and even on a non-magic style (where
 * a cape contributes nothing to DPS) the tie-break still correctly prefers
 * 29617's higher total stat sum over 2412's. There is no "arbitrary
 * iteration/file order" tie-break in this codebase for this scenario.
 *
 * <p><b>The real end-to-end mechanism</b> — confirmed by {@link
 * #magicSearch_modeLockedExclusion_ownershipCrossMapDeterminesFallback} —
 * lives ABOVE {@link GearOptimizer}, in {@code GearSection}:
 * <ol>
 *   <li>{@code GearSection.restrictedItemIds()} adds every item whose name
 *   matches a "(deadman)/(bh)/(lms)/(beta)" mode-locked marker to the
 *   search's exclude set on EVERY optimiser search, "regardless of price or
 *   ownership" (its own javadoc) — a deliberate, already-tested policy from
 *   a prior QA pass ("bug C": {@code GearSectionGearPoolTest
 *   #deadmanNamedItem_isNeverSuggestedByTheOptimizer}). 29617 matches this
 *   pattern, so it can NEVER be the optimiser's own recommendation, no
 *   matter what {@code OwnedVariantResolver.SUFFIXES} contains — this part
 *   is intentional and out of Stage 3's scope to change.</li>
 *   <li>{@code GearSection.addVariantPlainForm} is the ONLY mechanism that
 *   credits the player with owning a NON-excluded, real counterpart item
 *   (here, "Imbued saradomin cape", ids 21791/24248) when they own a
 *   variant whose name carries a known suffix — but {@code SUFFIXES} lacked
 *   " (deadman)", so owning 29617 never cross-mapped to owning 21791/24248.
 *   Without that credit, the optimiser has no signal that the player
 *   already effectively owns a top-tier magic cape, and falls back to
 *   whatever IS an eligible, affordable candidate for the slot — the cheap
 *   plain cape, exactly as reported.</li>
 * </ol>
 * Once " (deadman)" is added to {@code SUFFIXES}, {@code
 * OwnedVariantResolver.plainFormId(29617)} resolves to the real (non-mode-
 * locked) "Imbued saradomin cape" id, {@code addVariantPlainForm} marks it
 * owned at 0gp, and the optimiser correctly recommends THAT cape instead of
 * the plain one — which is exactly what the second test below proves,
 * using the real {@link OwnedVariantResolver#plainFormId} call (not a
 * hand-rolled substitute) to build the owned set, mirroring {@code
 * GearSection.ownedPriceMap()}'s own construction.
 */
public class GearOptimizerOwnedDeadmanCapeTest {
    static { com.ospulse.combat.BundledGson.set(new com.google.gson.Gson()); }

    private static final int PLAIN_SARADOMIN_CAPE = 2412;             // mdmg 0
    private static final int IMBUED_SARADOMIN_CAPE_DEADMAN = 29617;   // amagic+15, dmagic+15, mdmg+20
    private static final int CAPE_SLOT = 1;

    // Self-cast magic weapon (no spellbook/rune plumbing needed — DpsCalculator
    // tries a null Spell against it, same as MagicDpsTest's fixtures) so the
    // MAGIC style search has a legal, nonzero-DPS weapon to anchor on.
    private static final int TRIDENT_OF_THE_SEAS = 11905;

    private static int[] emptyLoadout() {
        int[] ids = new int[GearSnapshot.EQUIPMENT_SLOT_COUNT];
        Arrays.fill(ids, -1);
        return ids;
    }

    private static Monster zulrahSerpentine() {
        return MonsterRepository.getInstance().byName("Zulrah (Serpentine)").get();
    }

    private static PlayerCombat.Builder maxedPlayerTemplate() {
        return PlayerCombat.builder()
                .attack(99, 99)
                .strength(99, 99)
                .defence(99, 99)
                .ranged(99, 99)
                .magic(99, 99)
                .prayer(99, 99)
                .hitpoints(99, 99)
                .assumeBestPotion(false)
                .assumeBestPrayer(false)
                .onSlayerTask(false);
    }

    private static int slotIdIn(GearOptimizer.Result result, int slotOrdinal) {
        for (GearOptimizer.SlotChoice choice : result.loadout()) {
            if (choice.slotOrdinal() == slotOrdinal) {
                return choice.itemId();
            }
        }
        return -1;
    }

    /**
     * Control: {@link GearOptimizer}'s OWN candidate/DPS/tie-break logic,
     * given a literal owned set with no exclusions, never picks the
     * strictly worse plain cape over an owned 29617 — passes unmodified,
     * proving the suffix gap is not what lets GearOptimizer itself get this
     * wrong. See the class javadoc.
     */
    @Test
    public void magicSearch_ownedDeadmanCape_neverRecommendsWorsePlainCape() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = TRIDENT_OF_THE_SEAS;

        Set<Integer> owned = new HashSet<>(Arrays.asList(
                TRIDENT_OF_THE_SEAS, IMBUED_SARADOMIN_CAPE_DEADMAN));

        Map<Integer, Long> fixed = new HashMap<>();
        fixed.put(TRIDENT_OF_THE_SEAS, 0L);
        fixed.put(IMBUED_SARADOMIN_CAPE_DEADMAN, 0L);
        fixed.put(PLAIN_SARADOMIN_CAPE, 500L); // cheap, buyable, strictly worse on magic stats
        GearOptimizer.PriceSource prices = id -> fixed.containsKey(id) ? fixed.get(id) : 100_000_000L;

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, zulrahSerpentine(), maxedPlayerTemplate())
                .budget(1_000_000L)
                .owned(owned)
                .priceSource(prices)
                .style(CombatStyle.MAGIC)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertEquals("a MAGIC search must actually produce a usable result",
                CombatStyle.MAGIC, result.style() == null ? null : result.style().type());
        assertFalse("the plain Saradomin cape (mdmg 0) must never be recommended over the owned "
                        + "Imbued saradomin cape (deadman) (mdmg +20) on a MAGIC search",
                slotIdIn(result, CAPE_SLOT) == PLAIN_SARADOMIN_CAPE);
        assertEquals("the strictly better, owned deadman cape must be the cape-slot recommendation",
                IMBUED_SARADOMIN_CAPE_DEADMAN, slotIdIn(result, CAPE_SLOT));
    }

    /**
     * The REAL reported pick, reproduced end-to-end at the {@link
     * GearOptimizer} level by mirroring {@code GearSection}'s own wiring
     * rather than hand-waving it away:
     * <ul>
     *   <li>the owned set is built the same way {@code
     *   GearSection.ownedPriceMap()}/{@code addVariantPlainForm} build it —
     *   starting from the raw owned id (29617) and calling the REAL {@link
     *   OwnedVariantResolver#plainFormId} to (maybe) add its cross-mapped
     *   plain-form counterpart, exactly like production code;</li>
     *   <li>29617 is placed in the exclude set, mirroring {@code
     *   GearSection.restrictedItemIds()}'s unconditional, ownership-blind
     *   mode-locked-item exclusion (confirmed real and by-design via {@code
     *   GearSection.isModeLockedItem("Imbued saradomin cape (deadman)")} and
     *   {@code GearSectionGearPoolTest}'s existing coverage of the same
     *   policy for other "(deadman)" items).</li>
     * </ul>
     * Before " (deadman)" is added to {@code SUFFIXES}, {@code
     * plainFormId(29617)} returns null (no matching suffix), so the owned
     * set never gains the real, non-excluded "Imbued saradomin cape" —
     * leaving only the cheap plain cape eligible, exactly reproducing the
     * report. Adding the suffix makes {@code plainFormId} resolve the real
     * counterpart, which then wins on stats.
     */
    @Test
    public void magicSearch_modeLockedExclusion_ownershipCrossMapDeterminesFallback() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = TRIDENT_OF_THE_SEAS;

        EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();

        // Exactly GearSection.ownedPriceMap()/addVariantPlainForm's own construction:
        // start from the raw owned deadman cape id, then cross-map its plain form
        // (if OwnedVariantResolver recognises the suffix) at price 0.
        Map<Integer, Long> ownedPrices = new HashMap<>();
        ownedPrices.put(TRIDENT_OF_THE_SEAS, 0L);
        ownedPrices.put(IMBUED_SARADOMIN_CAPE_DEADMAN, 0L);
        Integer crossMappedPlainId = OwnedVariantResolver.plainFormId(index, IMBUED_SARADOMIN_CAPE_DEADMAN);
        if (crossMappedPlainId != null) {
            ownedPrices.putIfAbsent(crossMappedPlainId, 0L);
        }

        // GearSection.restrictedItemIds()'s unconditional mode-locked exclusion —
        // 29617 ("Imbued saradomin cape (deadman)") always lands here, regardless
        // of price or ownership; that part of GearSection's policy is deliberate
        // and out of scope here, so it's mirrored directly rather than re-derived.
        Set<Integer> exclude = new HashSet<>(Arrays.asList(IMBUED_SARADOMIN_CAPE_DEADMAN));

        Map<Integer, Long> fixed = new HashMap<>();
        fixed.put(TRIDENT_OF_THE_SEAS, 0L);
        fixed.put(IMBUED_SARADOMIN_CAPE_DEADMAN, 0L);
        fixed.put(PLAIN_SARADOMIN_CAPE, 500L); // cheap, buyable
        if (crossMappedPlainId != null) {
            fixed.put(crossMappedPlainId, 0L);
        }
        GearOptimizer.PriceSource prices = id -> fixed.containsKey(id) ? fixed.get(id) : 100_000_000L;

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, zulrahSerpentine(), maxedPlayerTemplate())
                .budget(1_000_000L)
                .owned(ownedPrices.keySet())
                .exclude(exclude)
                .priceSource(prices)
                .style(CombatStyle.MAGIC)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertFalse("the plain Saradomin cape must never be the fallback once the deadman cape's "
                        + "ownership correctly cross-maps to its real, non-excluded counterpart",
                slotIdIn(result, CAPE_SLOT) == PLAIN_SARADOMIN_CAPE);
    }
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.CombatStyle;
import com.ospulse.combat.Monster;
import com.ospulse.combat.MonsterCombatRequirement;
import com.ospulse.combat.MonsterRepository;
import com.ospulse.combat.PlayerCombat;
import com.ospulse.session.GearSnapshot;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashSet;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Task 5: the optimiser's weapon/ammo candidate search must be filtered by
 * the target monster's {@link MonsterCombatRequirement} gate (Task 1's pure
 * {@code permitsWeapon}/{@code permitsAmmo} predicates), not just report it.
 * Mirrors {@link GearOptimizerTest}'s fixtures/setup style.
 */
public class GearOptimizerCombatGateTest {
    static { com.ospulse.combat.BundledGson.set(new com.google.gson.Gson()); }

    private static final int ABYSSAL_WHIP = 4151;       // slash melee — the gated-out weapon
    private static final int DRAGON_SCIMITAR = 4587;    // slash melee — the only permitted weapon here

    private static int[] emptyLoadout() {
        int[] ids = new int[GearSnapshot.EQUIPMENT_SLOT_COUNT];
        Arrays.fill(ids, -1);
        return ids;
    }

    private static Monster cerberus() {
        // The gate is driven entirely by the explicit .combatRequirement(...)
        // below, not by the target's own bundled requirement data, so any
        // indexed monster works as the search target.
        return MonsterRepository.getInstance().byName("Cerberus").get();
    }

    private static PlayerCombat.Builder maxedPlayerTemplate() {
        return PlayerCombat.builder()
                .attack(99, 99)
                .strength(99, 99)
                .defence(99, 99)
                .ranged(99, 99)
                .magic(99, 99)
                .prayer(99, 99)
                .hitpoints(99, 99)
                .assumeBestPotion(false)
                .assumeBestPrayer(false)
                .onSlayerTask(false);
    }

    /** Every weapon is unaffordable except the two fixtures, isolating the scenario. */
    private static GearOptimizer.PriceSource everyWeaponExpensiveExcept(java.util.Map<Integer, Long> prices) {
        return id -> prices.containsKey(id) ? prices.get(id) : 100_000_000L;
    }

    private static final int TOXIC_BLOWPIPE = 12926;    // self-supplying ranged 2H (loads darts)
    private static final int RUNE_CROSSBOW = 9185;       // worn-ammo ranged 1H
    private static final int BROAD_BOLTS = 11875;        // Kurask-legal ranged ammo
    private static final int MIRROR_SHIELD = 4156;       // shield-slot force-include (anti-Basilisk)
    private static final int DRAGON_2H_SWORD = 7158;     // two-handed slash weapon
    private static final int RUNE_SCIMITAR = 1333;       // one-handed slash weapon
    private static final int TWISTED_BOW = 20997;        // two-handed ranged weapon
    private static final int RUNE_PLATELEGS = 1079;      // DPS-neutral legs (no offensive bonus)

    private static int slotIdIn(GearOptimizer.Result result, int slotOrdinal) {
        for (GearOptimizer.SlotChoice choice : result.loadout()) {
            if (choice.slotOrdinal() == slotOrdinal) {
                return choice.itemId();
            }
        }
        return -1;
    }

    private static int weaponIdIn(GearOptimizer.Result result) {
        return slotIdIn(result, WhatIfLoadout.WEAPON_SLOT);
    }

    /**
     * A3: with a shield-slot item force-included (e.g. mirror shield vs
     * Basilisk), the optimiser must never recommend a two-handed / dual-wield
     * weapon, which would silently evict the required shield.
     */
    @Test
    public void forcedShield_neverRecommendsATwoHandedWeapon() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = RUNE_SCIMITAR;   // a one-handed weapon already equipped

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        fixed.put(RUNE_SCIMITAR, 0L);
        fixed.put(DRAGON_2H_SWORD, 0L);   // cheap + stronger: without the fix it would be chosen, evicting the shield
        fixed.put(MIRROR_SHIELD, 0L);
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(1_000_000L)
                .priceSource(prices)
                .style(CombatStyle.SLASH)
                .include(new HashSet<>(Arrays.asList(MIRROR_SHIELD)))
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertFalse("a two-handed weapon must not be chosen when a shield is force-required",
                weaponIdIn(result) == DRAGON_2H_SWORD);
        assertEquals("the force-required shield must be retained",
                MIRROR_SHIELD, slotIdIn(result, WhatIfLoadout.SHIELD_SLOT));
    }

    /**
     * B8-5: when a shield is force-included but the player has NO usable
     * one-handed weapon of the chosen style (only 2H weapons — the norm for
     * maxed magic/ranged: shadow, bowfa, tbow), the optimiser must still
     * recommend the 2H weapon instead of collapsing to zero swaps. The forced
     * 2H-exclusion (A3) only applies when a one-handed option actually exists.
     */
    @Test
    public void forcedShield_keepsTwoHandedWeaponWhenNoOneHandedOptionExists() {
        int[] live = emptyLoadout();

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        fixed.put(TWISTED_BOW, 0L);     // the only usable weapon for this style — and it's 2H
        fixed.put(MIRROR_SHIELD, 0L);
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(1_000_000L)
                .priceSource(prices)
                .style(CombatStyle.RANGED)
                .include(new HashSet<>(Arrays.asList(MIRROR_SHIELD)))
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertEquals("with no one-handed option, the 2H weapon must still be recommended (no zero-swap collapse)",
                TWISTED_BOW, weaponIdIn(result));
        assertTrue("the search must produce a usable style, not collapse to null", result.style() != null);
    }

    /**
     * A4: a blowpipe fires its own darts (not the worn ammo slot), so it can
     * never satisfy Kurask's broad-ammo gate — it must be gated out of the
     * ranged weapon search even though the worn ammo slot holds broad bolts.
     */
    @Test
    public void broadAmmoGate_neverRecommendsASelfSupplyingBlowpipe() {
        int[] live = emptyLoadout();

        // Kurask-style ranged gate: no allowed weapon ids, broad bolts are the only legal ammo.
        MonsterCombatRequirement kurask = MonsterCombatRequirement.weaponGate(
                Collections.emptySet(),
                new HashSet<>(Arrays.asList(BROAD_BOLTS)),
                EnumSet.noneOf(CombatStyle.class),
                "note");

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        fixed.put(TOXIC_BLOWPIPE, 0L);   // cheap + high DPS: without the fix it would win the ranged search
        fixed.put(RUNE_CROSSBOW, 0L);
        fixed.put(BROAD_BOLTS, 0L);
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(1_000_000L)
                .priceSource(prices)
                .style(CombatStyle.RANGED)
                .combatRequirement(kurask)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertFalse("a blowpipe (self-supplying ammo) must never be recommended against a broad-ammo gate",
                weaponIdIn(result) == TOXIC_BLOWPIPE);

        // Cross-check the pure predicate: blowpipe rejected, a worn-ammo crossbow deferred to the ammo gate.
        assertFalse(kurask.permitsWeapon(TOXIC_BLOWPIPE, CombatStyle.RANGED, false));
        assertTrue(kurask.permitsWeapon(RUNE_CROSSBOW, CombatStyle.RANGED, true));
    }

    /**
     * B9-1: a worn-ammo ranged weapon whose worn/ownable ammo cannot satisfy a
     * broad-ammo gate (Kurask) must NOT yield a usable ranged result — even
     * though the weapon itself passes the weapon-slot gate. The seed loadout's
     * ammo is only DPS-invisible to the OLD evaluate(), which ignored the gate;
     * evaluate() must now reject a (weapon, style, ammo) the monster can't be
     * damaged by, so the whole Ranged style collapses to null (unusable) and is
     * never offered — exactly as Magic already correctly collapses.
     */
    @Test
    public void broadAmmoGate_dropsRangedWhenNoLegalAmmoAvailable() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = RUNE_CROSSBOW; // worn-ammo ranged weapon, no legal ammo to fire

        MonsterCombatRequirement kurask = MonsterCombatRequirement.weaponGate(
                Collections.emptySet(),
                new HashSet<>(Arrays.asList(BROAD_BOLTS)),
                EnumSet.noneOf(CombatStyle.class),
                "note");

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        fixed.put(RUNE_CROSSBOW, 0L);
        // Broad bolts are NOT owned and NOT affordable — no legal ammo exists.
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .priceSource(prices)
                .style(CombatStyle.RANGED)
                .combatRequirement(kurask)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertTrue("with no legal ammo, the ranged search must collapse to an unusable (null-style) result",
                result.style() == null);
    }

    /**
     * B9-1 companion: when the player DOES own the gate's legal ammo (broad
     * bolts), the ranged search must succeed and put that ammo in the ammo slot.
     */
    @Test
    public void broadAmmoGate_recommendsBroadAmmoWhenOwned() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = RUNE_CROSSBOW;

        MonsterCombatRequirement kurask = MonsterCombatRequirement.weaponGate(
                Collections.emptySet(),
                new HashSet<>(Arrays.asList(BROAD_BOLTS)),
                EnumSet.noneOf(CombatStyle.class),
                "note");

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .owned(new HashSet<>(Arrays.asList(RUNE_CROSSBOW, BROAD_BOLTS)))
                .style(CombatStyle.RANGED)
                .combatRequirement(kurask)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertTrue("with broad bolts owned, a usable ranged result must be produced", result.style() != null);
        assertEquals("the ammo slot must hold the gate-legal broad bolts",
                BROAD_BOLTS, slotIdIn(result, 13)); // slot 13 = ammo
    }

    /**
     * B9-2: the optimiser must fill DPS-neutral slots (legs, ring, etc.) with
     * the best wearable owned item rather than leaving them empty. Starting
     * from a naked loadout, plate legs contribute no offensive bonus so
     * equipping them never RAISES DPS — the DPS-only search used to leave the
     * slot empty ("recommend no legs"). A tie-break now fills the slot on a DPS
     * tie so the recommended loadout is a complete setup.
     */
    @Test
    public void fillsDpsNeutralSlotWithBestOwnedItem() {
        int[] live = emptyLoadout(); // naked

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .priceSource(everyWeaponExpensiveExcept(new java.util.HashMap<>())) // only owned gear is affordable
                .owned(new HashSet<>(Arrays.asList(RUNE_SCIMITAR, RUNE_PLATELEGS)))
                .style(CombatStyle.SLASH)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertEquals("a DPS-neutral legs slot must be filled with the owned plate legs, not left empty",
                RUNE_PLATELEGS, slotIdIn(result, 7)); // slot 7 = legs
    }

    private static java.util.Map<String, Integer> baseLevels(int attack) {
        java.util.Map<String, Integer> m = new java.util.HashMap<>();
        m.put("attack", attack);
        m.put("strength", 99);
        m.put("defence", 99);
        m.put("ranged", 99);
        m.put("magic", 99);
        m.put("prayer", 99);
        m.put("hitpoints", 99);
        return m;
    }

    /**
     * B9-5: the optimiser must never recommend gear the player cannot equip at
     * their current BASE levels. A 40-Attack player owning both a Rune scimitar
     * (40 Att) and a higher-DPS Dragon scimitar (60 Att) must be given the Rune
     * scimitar — the Dragon scimitar is unwieldable and must be filtered out
     * even though it is owned, free, and higher DPS.
     */
    @Test
    public void levelGate_neverRecommendsGearAbovePlayersBaseLevel() {
        int[] live = emptyLoadout();

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        fixed.put(RUNE_SCIMITAR, 0L);
        fixed.put(DRAGON_SCIMITAR, 0L);
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .priceSource(prices)
                .owned(new HashSet<>(Arrays.asList(RUNE_SCIMITAR, DRAGON_SCIMITAR)))
                .style(CombatStyle.SLASH)
                .playerBaseLevels(baseLevels(40))
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertFalse("a 40-Attack player must never be told to wield a Dragon scimitar (60 Attack)",
                weaponIdIn(result) == DRAGON_SCIMITAR);
        assertEquals("the wieldable Rune scimitar (40 Attack) must be chosen instead",
                RUNE_SCIMITAR, weaponIdIn(result));
    }

    /**
     * B9-5 companion: once the player meets the requirement (60 Attack), the
     * higher-DPS Dragon scimitar IS recommended — the gate only blocks gear
     * above the player's level, it never hides gear they can wield.
     */
    @Test
    public void levelGate_recommendsHigherTierWhenRequirementIsMet() {
        int[] live = emptyLoadout();

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        fixed.put(RUNE_SCIMITAR, 0L);
        fixed.put(DRAGON_SCIMITAR, 0L);
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .priceSource(prices)
                .owned(new HashSet<>(Arrays.asList(RUNE_SCIMITAR, DRAGON_SCIMITAR)))
                .style(CombatStyle.SLASH)
                .playerBaseLevels(baseLevels(60))
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertEquals("a 60-Attack player must get the higher-DPS Dragon scimitar",
                DRAGON_SCIMITAR, weaponIdIn(result));
    }

    @Test
    public void combatGate_neverRecommendsAGatedOutWeapon_evenWhenCheaperAndHigherDps() {
        int[] live = emptyLoadout();
        live[WhatIfLoadout.WEAPON_SLOT] = DRAGON_SCIMITAR;

        // Kurask-style gate: only the scimitar (or MAGIC) can damage this
        // target — the whip is gated out even though it would otherwise win
        // on DPS/price (cheap + owned).
        MonsterCombatRequirement kurask = MonsterCombatRequirement.weaponGate(
                new HashSet<>(Arrays.asList(DRAGON_SCIMITAR)),
                Collections.emptySet(),
                EnumSet.of(CombatStyle.MAGIC),
                "note");

        java.util.Map<Integer, Long> fixed = new java.util.HashMap<>();
        fixed.put(DRAGON_SCIMITAR, 0L);
        fixed.put(ABYSSAL_WHIP, 100L); // dirt cheap and objectively the stronger weapon
        GearOptimizer.PriceSource prices = everyWeaponExpensiveExcept(fixed);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(1_000_000L)
                .priceSource(prices)
                .style(CombatStyle.SLASH)
                .combatRequirement(kurask)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertFalse("the gated-out whip must never be chosen even though it is cheap and higher-DPS",
                weaponIdIn(result) == ABYSSAL_WHIP);
        assertEquals("the only permitted weapon (scimitar) must be chosen",
                DRAGON_SCIMITAR, weaponIdIn(result));

        // Cross-check: the pure predicate agrees with the optimiser's behaviour.
        assertTrue(kurask.permitsWeapon(DRAGON_SCIMITAR, CombatStyle.SLASH));
        assertFalse(kurask.permitsWeapon(ABYSSAL_WHIP, CombatStyle.SLASH));
    }
}

package com.ospulse.combat.optimizer;

import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Pure unit tests for {@link LoadoutOverride}: the immutable per-slot
 * what-if map, independent of any real item data (2H/shield exclusivity that
 * DOES depend on real item ids is covered in {@link WhatIfLoadoutTest}).
 */
public class LoadoutOverrideTest {

    @Test
    public void emptyOverride_hasNoSlots() {
        LoadoutOverride override = LoadoutOverride.empty();
        assertTrue(override.isEmpty());
        assertEquals(-1, override.itemIdFor(3));
        assertFalse(override.hasOverride(3));
        assertArrayEquals(new int[0], override.overriddenSlots());
    }

    @Test
    public void withSlot_addsAnOverride_immutably() {
        LoadoutOverride base = LoadoutOverride.empty();
        LoadoutOverride withWeapon = base.withSlot(3, 4151);

        // base is unchanged (immutability).
        assertTrue(base.isEmpty());

        assertFalse(withWeapon.isEmpty());
        assertTrue(withWeapon.hasOverride(3));
        assertEquals(4151, withWeapon.itemIdFor(3));
        assertArrayEquals(new int[] {3}, withWeapon.overriddenSlots());
    }

    @Test
    public void withSlot_multipleSlotsAccumulate() {
        LoadoutOverride override = LoadoutOverride.empty()
                .withSlot(3, 4151)
                .withSlot(0, 1234);
        assertEquals(4151, override.itemIdFor(3));
        assertEquals(1234, override.itemIdFor(0));
        assertArrayEquals(new int[] {0, 3}, override.overriddenSlots());
    }

    @Test
    public void withSlot_zeroOrNegativeItemId_clearsSlot() {
        LoadoutOverride override = LoadoutOverride.empty().withSlot(3, 4151);
        assertTrue(override.hasOverride(3));

        LoadoutOverride cleared = override.withSlot(3, 0);
        assertFalse(cleared.hasOverride(3));
        assertTrue(cleared.isEmpty());

        LoadoutOverride clearedNegative = override.withSlot(3, -1);
        assertTrue(clearedNegative.isEmpty());
    }

    @Test
    public void withoutSlot_resetsOneSlotOnly() {
        LoadoutOverride override = LoadoutOverride.empty()
                .withSlot(3, 4151)
                .withSlot(0, 1234);
        LoadoutOverride reset = override.withoutSlot(3);
        assertFalse(reset.hasOverride(3));
        assertTrue(reset.hasOverride(0));
        assertEquals(1234, reset.itemIdFor(0));
    }

    @Test
    public void withoutSlot_onUnoverriddenSlot_isNoOp() {
        LoadoutOverride override = LoadoutOverride.empty().withSlot(3, 4151);
        LoadoutOverride same = override.withoutSlot(0);
        assertEquals(override, same);
    }

    @Test
    public void withoutSlot_lastSlotReturnsEmptySingleton() {
        LoadoutOverride override = LoadoutOverride.empty().withSlot(3, 4151);
        LoadoutOverride reset = override.withoutSlot(3);
        assertTrue(reset.isEmpty());
        assertEquals(LoadoutOverride.empty(), reset);
    }

    @Test
    public void equalsAndHashCode_matchOnContent() {
        LoadoutOverride a = LoadoutOverride.empty().withSlot(3, 4151).withSlot(0, 10);
        LoadoutOverride b = LoadoutOverride.empty().withSlot(0, 10).withSlot(3, 4151);
        assertEquals(a, b);
        assertEquals(a.hashCode(), b.hashCode());
    }

    @Test
    public void withWeaponSlot_twoHandedEmptiesShield() {
        LoadoutOverride base = LoadoutOverride.empty().withSlot(5, 1201); // shield override present
        LoadoutOverride afterTwoHandedWeapon = base.withWeaponSlot(3, 5, 20997, true);
        assertEquals(20997, afterTwoHandedWeapon.itemIdFor(3));
        // A 2H weapon EMPTIES the shield slot (unequips a live shield too), not merely
        // clears the override — so the slot stays overridden, to EMPTIED.
        assertTrue("2H weapon must empty the shield slot", afterTwoHandedWeapon.hasOverride(5));
        assertEquals(LoadoutOverride.EMPTIED, afterTwoHandedWeapon.itemIdFor(5));
    }

    @Test
    public void withWeaponSlot_oneHandedKeepsShield() {
        LoadoutOverride base = LoadoutOverride.empty().withSlot(5, 1201);
        LoadoutOverride afterOneHandedWeapon = base.withWeaponSlot(3, 5, 4151, false);
        assertEquals(4151, afterOneHandedWeapon.itemIdFor(3));
        assertTrue("1H weapon must not disturb the shield override", afterOneHandedWeapon.hasOverride(5));
        assertEquals(1201, afterOneHandedWeapon.itemIdFor(5));
    }

    @Test
    public void withShieldSlot_whenCurrentWeaponTwoHanded_emptiesWeapon() {
        LoadoutOverride base = LoadoutOverride.empty().withSlot(3, 20997); // 2H weapon override present
        LoadoutOverride afterShield = base.withShieldSlot(3, 5, 1201, true);
        assertEquals(1201, afterShield.itemIdFor(5));
        // Equipping a shield over a 2H weapon EMPTIES the weapon slot (unequips a live
        // 2H weapon too), so the slot stays overridden, to EMPTIED.
        assertTrue("equipping a shield must empty a 2H weapon", afterShield.hasOverride(3));
        assertEquals(LoadoutOverride.EMPTIED, afterShield.itemIdFor(3));
    }

    @Test
    public void withShieldSlot_whenCurrentWeaponOneHanded_keepsWeapon() {
        LoadoutOverride base = LoadoutOverride.empty().withSlot(3, 4151);
        LoadoutOverride afterShield = base.withShieldSlot(3, 5, 1201, false);
        assertEquals(1201, afterShield.itemIdFor(5));
        assertTrue(afterShield.hasOverride(3));
    }
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.Monster;
import com.ospulse.combat.MonsterRepository;
import com.ospulse.combat.PlayerCombat;
import com.ospulse.session.GearSnapshot;

import net.runelite.api.EquipmentInventorySlot;

import org.junit.Test;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Covers the expensive-item cap's de-risk ALLOCATION through
 * {@link GearOptimizer#optimize}: when the allowance forces some over-ceiling
 * items out, the demotions must be chosen by DPS loss — the allowed premium
 * slots go to the items that buy the most DPS — never by which over-cap slot
 * the local search happens to walk first in {@link GearOptimizer#SEARCHABLE_SLOTS}
 * order. The canonical shape: a premium amulet with real offensive stats
 * (Torture) worn alongside a premium ring with NONE (Ring of suffering (i) —
 * purely defensive), one premium slot allowed. Demoting the DPS-dead ring is
 * free; demoting the amulet costs real DPS for zero extra safety (either way
 * exactly one premium item is risked), so the ring must be the sacrifice.
 */
public class GearOptimizerCapDeriskTest {
    static { com.ospulse.combat.BundledGson.set(new com.google.gson.Gson()); }

    private static final int AMULET_SLOT = EquipmentInventorySlot.AMULET.getSlotIdx(); // 2
    private static final int WEAPON_SLOT = EquipmentInventorySlot.WEAPON.getSlotIdx(); // 3
    private static final int RING_SLOT = EquipmentInventorySlot.RING.getSlotIdx();     // 12

    // Weapon slot (3):
    private static final int GHRAZI_RAPIER = 22324; // best-in-slot stab, cheap risk here
    private static final int BRONZE_SWORD = 1277;   // junk fallback for the weapon-demotion scenario

    // Amulet slot (2) — the torture strictly out-DPSes the blood fury:
    private static final int AMULET_OF_TORTURE = 19553;
    private static final int AMULET_OF_BLOOD_FURY = 24780;

    // Ring slot (12) — both suffering variants carry ZERO offensive stats, so
    // they are DPS-identical to each other AND to an empty ring slot:
    private static final int RING_OF_SUFFERING_I = 19710;
    private static final int RING_OF_SUFFERING = 19550;

    private static final long THRESHOLD = 5_000_000L;

    private static int[] emptyLoadout() {
        int[] ids = new int[GearSnapshot.EQUIPMENT_SLOT_COUNT];
        Arrays.fill(ids, -1);
        return ids;
    }

    private static Monster cerberus() {
        return MonsterRepository.getInstance().byName("Cerberus").get();
    }

    private static PlayerCombat.Builder maxedPlayerTemplate() {
        return PlayerCombat.builder()
                .attack(99, 99).strength(99, 99).defence(99, 99)
                .ranged(99, 99).magic(99, 99).prayer(99, 99).hitpoints(99, 99)
                .assumeBestPotion(false).assumeBestPrayer(false).onSlayerTask(false);
    }

    /**
     * Risk values for the cap (see {@link GearOptimizer.Request.Builder#riskValueSource}):
     * torture and suffering (i) sit over the 5m ceiling, blood fury and the
     * plain suffering under it, the rapier well under. Unknown ids are 0 —
     * they can never become candidates anyway (see {@link #capped}'s
     * everything-unaffordable price source).
     */
    private static GearOptimizer.PriceSource riskValues() {
        java.util.Map<Integer, Long> risk = new java.util.HashMap<>();
        risk.put(GHRAZI_RAPIER, 1_000_000L);
        risk.put(AMULET_OF_TORTURE, 30_000_000L);
        risk.put(AMULET_OF_BLOOD_FURY, 4_000_000L);
        risk.put(RING_OF_SUFFERING_I, 20_000_000L);
        risk.put(RING_OF_SUFFERING, 500_000L);
        return id -> risk.getOrDefault(id, 0L);
    }

    /**
     * The canonical request: rapier + torture + suffering (i) worn, the
     * cheaper amulet/ring alternatives owned in the bank, budget 0 with
     * everything unpurchasable — an owned-only search where only the
     * expensive-item allowance varies.
     */
    private static GearOptimizer.Request capped(int expensiveItemCount) {
        int[] live = emptyLoadout();
        live[WEAPON_SLOT] = GHRAZI_RAPIER;
        live[AMULET_SLOT] = AMULET_OF_TORTURE;
        live[RING_SLOT] = RING_OF_SUFFERING_I;

        Set<Integer> owned = new HashSet<>(Arrays.asList(
                GHRAZI_RAPIER, AMULET_OF_TORTURE, AMULET_OF_BLOOD_FURY,
                RING_OF_SUFFERING_I, RING_OF_SUFFERING));

        return GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .owned(owned)
                .priceSource(id -> 100_000_000L) // nothing buyable — owned candidates only
                .riskValueSource(riskValues())
                .expensiveItemThreshold(THRESHOLD)
                .expensiveItemCount(expensiveItemCount)
                .build();
    }

    private static int itemIdInSlot(GearOptimizer.Result result, int slotOrdinal) {
        for (GearOptimizer.SlotChoice choice : result.loadout()) {
            if (choice.slotOrdinal() == slotOrdinal) {
                return choice.itemId();
            }
        }
        return -1;
    }

    private static int premiumItemsIn(GearOptimizer.Result result, GearOptimizer.PriceSource risk) {
        int count = 0;
        for (GearOptimizer.SlotChoice choice : result.loadout()) {
            if (choice.itemId() > 0 && risk.priceFor(choice.itemId()) > THRESHOLD) {
                count++;
            }
        }
        return count;
    }

    /**
     * The core allocation case: with ONE premium slot allowed and two premium
     * items worn, the allowance must be spent on the torture (real DPS) and
     * the DPS-dead suffering (i) demoted to the plain suffering — both
     * outcomes risk exactly one premium item, so keeping the torture is
     * strictly better. A slot-order walk demotes the amulet first (slot 2
     * precedes the ring's slot 12) and never revisits the choice.
     */
    @Test
    public void capDerisk_oneAllowed_spendsTheAllowanceOnTheTortureNotTheDpsDeadRing() {
        GearOptimizer.Result result = GearOptimizer.optimize(capped(1));

        assertEquals("the one allowed premium slot must go to the torture — demoting it buys no "
                        + "extra safety while the DPS-dead suffering (i) stays premium",
                AMULET_OF_TORTURE, itemIdInSlot(result, AMULET_SLOT));
        assertEquals("the zero-offensive-stat ring is the free demotion, so it must be the sacrifice",
                RING_OF_SUFFERING, itemIdInSlot(result, RING_SLOT));
        assertTrue("the allowance itself must still be respected",
                premiumItemsIn(result, riskValues()) <= 1);

        // Demoting the ring costs no DPS at all, so the constrained result
        // must score exactly what the uncapped torture + suffering (i)
        // loadout scores.
        GearOptimizer.Result unconstrained = GearOptimizer.optimize(capped(2));
        assertEquals("a DPS-free demotion must concede no DPS versus the roomier allowance",
                unconstrained.dps().dps(), result.dps().dps(), 1e-9);
    }

    /**
     * Guard against over-correction: an allowance that covers both premium
     * items must keep them BOTH — nothing demoted, nothing bought (budget 0,
     * so any spend would also be a budget violation).
     */
    @Test
    public void capDerisk_allowanceCoversBoth_keepsTortureAndImbuedRingUntouched() {
        for (int allowance : new int[] {2, 4}) {
            GearOptimizer.Result result = GearOptimizer.optimize(capped(allowance));

            assertEquals("allowance " + allowance + " covers the torture — it must stay",
                    AMULET_OF_TORTURE, itemIdInSlot(result, AMULET_SLOT));
            assertEquals("allowance " + allowance + " covers the suffering (i) — it must stay",
                    RING_OF_SUFFERING_I, itemIdInSlot(result, RING_SLOT));
            assertEquals("a satisfied cap must never trigger a purchase",
                    0L, result.totalSpend());
        }
    }

    /**
     * The fix must not degenerate into "never sacrifice the amulet": when the
     * amulet demotion genuinely IS the cheapest DPS concession — the only
     * other premium item is the weapon, whose sole fallback is junk — the
     * amulet must still be the one demoted.
     */
    @Test
    public void capDerisk_amuletDemotionCheapest_stillDemotesTheAmulet() {
        int[] live = emptyLoadout();
        live[WEAPON_SLOT] = GHRAZI_RAPIER;
        live[AMULET_SLOT] = AMULET_OF_TORTURE;

        Set<Integer> owned = new HashSet<>(Arrays.asList(
                GHRAZI_RAPIER, BRONZE_SWORD, AMULET_OF_TORTURE, AMULET_OF_BLOOD_FURY));

        java.util.Map<Integer, Long> risk = new java.util.HashMap<>();
        risk.put(GHRAZI_RAPIER, 30_000_000L);      // over the ceiling — junk fallback only
        risk.put(BRONZE_SWORD, 100L);
        risk.put(AMULET_OF_TORTURE, 30_000_000L);  // over the ceiling — near-tier fallback
        risk.put(AMULET_OF_BLOOD_FURY, 4_000_000L);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .owned(owned)
                .priceSource(id -> 100_000_000L)
                .riskValueSource(id -> risk.getOrDefault(id, 0L))
                .expensiveItemThreshold(THRESHOLD)
                .expensiveItemCount(1)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertEquals("the rapier's only fallback is junk, so the premium slot must go to the weapon",
                GHRAZI_RAPIER, itemIdInSlot(result, WEAPON_SLOT));
        assertEquals("the amulet is the cheapest DPS concession here — it must be the sacrifice",
                AMULET_OF_BLOOD_FURY, itemIdInSlot(result, AMULET_SLOT));
    }

    // ---------------- budget-coupled de-risk: a cheap swap must not strand the chain over the cap

    private static final int SHIELD_SLOT = EquipmentInventorySlot.SHIELD.getSlotIdx(); // 5

    private static final int AVERNIC_DEFENDER = 22322; // premium shield; only a 2H weapon can shed it here
    private static final int BRONZE_2H_SWORD = 1307;   // junk 2H — its eviction is the sole route off the defender

    /**
     * The eviction fixture: rapier + torture + defender worn (all premium,
     * one allowed — over the cap by two), everything owned except two
     * purchases: a blood fury (100k — the whole small budget) and a junk
     * bronze 2H (50k) whose eviction of the defender is the ONLY way to shed
     * the shield's risk (the shield slot has no other candidate). The blood
     * fury demotion keeps far more DPS than the 2H swap, so a purely
     * DPS-ranked round takes it first — and at the small budget that leaves
     * no room to ever buy the 2H, stranding the loadout at two premium items
     * although "buy the 2H, keep the torture" was reachable, within budget
     * and within the cap, in one swap.
     */
    private static GearOptimizer.Request evictionScenario(long budget) {
        int[] live = emptyLoadout();
        live[WEAPON_SLOT] = GHRAZI_RAPIER;
        live[AMULET_SLOT] = AMULET_OF_TORTURE;
        live[SHIELD_SLOT] = AVERNIC_DEFENDER;

        java.util.Map<Integer, Long> prices = new java.util.HashMap<>();
        prices.put(AMULET_OF_BLOOD_FURY, 100_000L);
        prices.put(BRONZE_2H_SWORD, 50_000L);

        java.util.Map<Integer, Long> risk = new java.util.HashMap<>();
        risk.put(GHRAZI_RAPIER, 30_000_000L);
        risk.put(AMULET_OF_TORTURE, 30_000_000L);
        risk.put(AVERNIC_DEFENDER, 30_000_000L);
        risk.put(AMULET_OF_BLOOD_FURY, 4_000_000L);
        risk.put(BRONZE_2H_SWORD, 1_000_000L);

        return GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(budget)
                .priceSource(id -> prices.getOrDefault(id, 100_000_000L))
                .riskValueSource(id -> risk.getOrDefault(id, 0L))
                .expensiveItemThreshold(THRESHOLD)
                .expensiveItemCount(1)
                .build();
    }

    /**
     * Feasibility must dominate DPS across the WHOLE de-risk chain, not just
     * round by round: at a 100k budget the DPS-best first demotion (buy the
     * blood fury) eats the budget and strands the search — the clearing 2H
     * eviction is unaffordable ever after and the result stays over the cap.
     * The de-risk must recognise the stranding and take the eviction instead,
     * spending the one premium slot on the torture.
     */
    @Test
    public void capDerisk_budgetBindsMidChain_takesTheClearingEvictionNotTheStrandingDemotion() {
        GearOptimizer.Result result = GearOptimizer.optimize(evictionScenario(100_000L));

        assertTrue("the cap was reachable within budget (buy the 2H, keep the torture) — the result "
                        + "must be within the allowance, not stranded at two premium items",
                premiumItemsIn(result, evictionRisk()) <= 1);
        assertEquals("only the 2H eviction sheds the defender, so it must be taken",
                BRONZE_2H_SWORD, itemIdInSlot(result, WEAPON_SLOT));
        assertEquals("the surviving premium slot must hold the torture",
                AMULET_OF_TORTURE, itemIdInSlot(result, AMULET_SLOT));
        assertEquals("the 2H eviction empties the shield slot", -1, itemIdInSlot(result, SHIELD_SLOT));
    }

    /**
     * The same fixture with an ample budget must reach the same cap-compliant
     * loadout — and buy ONLY the 2H: when the budget never binds, no first
     * pick can strand the chain, so the least-DPS-loss ordering runs exactly
     * as before and the blood fury purchase never survives to the result.
     */
    @Test
    public void capDerisk_ampleBudget_reachesTheSameCapCompliantLoadout() {
        GearOptimizer.Result result = GearOptimizer.optimize(evictionScenario(1_000_000L));

        assertTrue(premiumItemsIn(result, evictionRisk()) <= 1);
        assertEquals(BRONZE_2H_SWORD, itemIdInSlot(result, WEAPON_SLOT));
        assertEquals(AMULET_OF_TORTURE, itemIdInSlot(result, AMULET_SLOT));
        assertEquals("only the 2H purchase belongs in the result", 50_000L, result.totalSpend());
    }

    /** The eviction fixture's risk values, for counting premium items in a result. */
    private static GearOptimizer.PriceSource evictionRisk() {
        java.util.Map<Integer, Long> risk = new java.util.HashMap<>();
        risk.put(GHRAZI_RAPIER, 30_000_000L);
        risk.put(AMULET_OF_TORTURE, 30_000_000L);
        risk.put(AVERNIC_DEFENDER, 30_000_000L);
        return id -> risk.getOrDefault(id, 0L);
    }

    /**
     * The stranding guard must not over-correct into "shed the most overflow
     * per swap": over the cap by two with a huge-DPS-loss double eviction
     * available (junk 2H sheds rapier AND defender at once) but two cheap
     * single demotions (the DPS-dead ring, then the near-tier blood fury)
     * clearing the cap between them, the singles must win — the eviction
     * clears faster but buys nothing that the cheaper chain doesn't.
     */
    @Test
    public void capDerisk_cheapSingleDemotionsClearTheCap_doubleEvictionNotTaken() {
        int[] live = emptyLoadout();
        live[WEAPON_SLOT] = GHRAZI_RAPIER;
        live[SHIELD_SLOT] = AVERNIC_DEFENDER;
        live[AMULET_SLOT] = AMULET_OF_TORTURE;
        live[RING_SLOT] = RING_OF_SUFFERING_I;

        Set<Integer> owned = new HashSet<>(Arrays.asList(
                GHRAZI_RAPIER, AVERNIC_DEFENDER, AMULET_OF_TORTURE, AMULET_OF_BLOOD_FURY,
                RING_OF_SUFFERING_I, RING_OF_SUFFERING, BRONZE_2H_SWORD));

        java.util.Map<Integer, Long> risk = new java.util.HashMap<>();
        risk.put(GHRAZI_RAPIER, 30_000_000L);
        risk.put(AVERNIC_DEFENDER, 30_000_000L);
        risk.put(AMULET_OF_TORTURE, 30_000_000L);
        risk.put(RING_OF_SUFFERING_I, 20_000_000L);
        risk.put(AMULET_OF_BLOOD_FURY, 4_000_000L);
        risk.put(RING_OF_SUFFERING, 500_000L);
        risk.put(BRONZE_2H_SWORD, 1_000_000L);

        GearOptimizer.Request request = GearOptimizer.Request
                .builder(live, cerberus(), maxedPlayerTemplate())
                .budget(0L)
                .owned(owned)
                .priceSource(id -> 100_000_000L)
                .riskValueSource(id -> risk.getOrDefault(id, 0L))
                .expensiveItemThreshold(THRESHOLD)
                .expensiveItemCount(2)
                .build();

        GearOptimizer.Result result = GearOptimizer.optimize(request);

        assertEquals("the rapier must survive — the double eviction is the costliest route to the cap",
                GHRAZI_RAPIER, itemIdInSlot(result, WEAPON_SLOT));
        assertEquals("the defender must survive with it",
                AVERNIC_DEFENDER, itemIdInSlot(result, SHIELD_SLOT));
        assertEquals("the DPS-dead ring is the first cheap demotion",
                RING_OF_SUFFERING, itemIdInSlot(result, RING_SLOT));
        assertEquals("the near-tier amulet demotion is the second",
                AMULET_OF_BLOOD_FURY, itemIdInSlot(result, AMULET_SLOT));
        assertTrue(premiumItemsIn(result, id -> risk.getOrDefault(id, 0L)) <= 2);
    }
}

package com.ospulse.combat.optimizer;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import net.runelite.api.gameval.ItemID;

import org.junit.Test;

import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * {@link ChargeFamilies} — the clean-room charge-variant model.
 *
 * <p>The two data-integrity tests are the load-bearing ones: they prove the
 * family membership+order can be trusted for a live plugin. {@link
 * #everyMemberIsIndexedAndStatBearing} pins each declared member to the bundled
 * data (so a representative id is always evaluable), and {@link
 * #everyFamilyShares_dpsRelevantStats} proves the collapse is DPS-neutral — the
 * whole reason only stat-identical families are included.
 */
public class ChargeFamiliesTest {
    private static final int GLORY_1 = ItemID.AMULET_OF_GLORY_1;   // 1706
    private static final int GLORY_4 = ItemID.AMULET_OF_GLORY_4;   // 1712
    private static final int GLORY_6 = ItemID.AMULET_OF_GLORY_6;   // 11978
    private static final int GLORY_ETERNAL = ItemID.AMULET_OF_GLORY_INF; // 19707
    private static final int GLORY_UNCHARGED = ItemID.AMULET_OF_GLORY;   // 1704
    private static final int GLORY_T_4 = ItemID.TRAIL_AMULET_OF_GLORY_4; // 10354
    private static final int WHIP = 4151; // a non-charge item

    // ---------------------------------------------------------------- membership

    @Test
    public void recognisesChargeMembers_andRejectsNonMembers() {
        assertTrue(ChargeFamilies.isMember(GLORY_1));
        assertTrue(ChargeFamilies.isMember(GLORY_ETERNAL));
        assertTrue(ChargeFamilies.isMember(GLORY_T_4));
        assertFalse("a whip is not a charge-variant", ChargeFamilies.isMember(WHIP));
        assertFalse(ChargeFamilies.isMember(-1));
    }

    @Test
    public void regularAndTrimmedGloryAreSeparateFamilies() {
        assertFalse("plain glory and glory (t) must not share a family",
                sameFamily(GLORY_4, GLORY_T_4));
        assertTrue(sameFamily(GLORY_1, GLORY_4));
        assertTrue("eternal glory belongs with the regular glory family",
                sameFamily(GLORY_ETERNAL, GLORY_4));
    }

    // ------------------------------------------------- highest-charge selection

    @Test
    public void bestOwnedMember_picksHighestChargeOwned() {
        Set<Integer> owned = new HashSet<>(Arrays.asList(GLORY_1, GLORY_4)); // own (1) and (4)
        assertEquals("owning (1) and (4) resolves to (4)",
                Integer.valueOf(GLORY_4), ChargeFamilies.bestOwnedMember(GLORY_1, owned, null));
        // Resolving from ANY member id gives the same family answer.
        assertEquals(Integer.valueOf(GLORY_4), ChargeFamilies.bestOwnedMember(GLORY_UNCHARGED, owned, null));
    }

    @Test
    public void bestOwnedMember_prefersEternalOverEveryCharge() {
        Set<Integer> owned = new HashSet<>(Arrays.asList(GLORY_4, GLORY_6, GLORY_ETERNAL));
        assertEquals(Integer.valueOf(GLORY_ETERNAL), ChargeFamilies.bestOwnedMember(GLORY_4, owned, null));
    }

    @Test
    public void bestOwnedMember_skipsExcludedCharges() {
        Set<Integer> owned = new HashSet<>(Arrays.asList(GLORY_1, GLORY_4));
        Set<Integer> excluded = new HashSet<>(Arrays.asList(GLORY_4)); // exclude the (4)
        assertEquals("with (4) excluded, fall back to the next owned charge (1)",
                Integer.valueOf(GLORY_1), ChargeFamilies.bestOwnedMember(GLORY_1, owned, excluded));
    }

    @Test
    public void bestOwnedMember_nullWhenNothingOwnedOrNotAMember() {
        assertNull(ChargeFamilies.bestOwnedMember(GLORY_1, new HashSet<>(), null));
        assertNull(ChargeFamilies.bestOwnedMember(WHIP, new HashSet<>(Arrays.asList(WHIP)), null));
    }

    // --------------------------------------------------------- ordering integrity

    @Test
    public void familiesAreStrictlyOrdered_uncharedLastEternalFirst() {
        int[] glory = ChargeFamilies.familyOf(GLORY_4);
        assertNotNull(glory);
        // Highest-charge first: eternal, then (6), and uncharged dead last.
        assertEquals("eternal glory heads the regular family", GLORY_ETERNAL, glory[0]);
        assertEquals("uncharged glory is the lowest-ranked member", GLORY_UNCHARGED, glory[glory.length - 1]);
        // No duplicate ids within a family.
        for (int[] family : ChargeFamilies.familiesForTest()) {
            Set<Integer> seen = new HashSet<>();
            for (int id : family) {
                assertTrue("duplicate id " + id + " in a family", seen.add(id));
            }
        }
    }

    // ------------------------------------------------------ data-integrity gates

    @Test
    public void everyMemberIsIndexedAndStatBearing() {
        Map<String, List<Object>> index = loadIndex();
        Map<String, List<Double>> stats = loadStats();
        for (int[] family : ChargeFamilies.familiesForTest()) {
            for (int id : family) {
                assertTrue("family member " + id + " missing from equipment_index (would never be a candidate)",
                        index.containsKey(String.valueOf(id)));
                assertTrue("family member " + id + " missing from equipment_stats (representative must be evaluable)",
                        stats.containsKey(String.valueOf(id)));
            }
        }
    }

    /**
     * The invariant that makes the whole feature safe: within a family, every
     * charge exposes IDENTICAL DPS-relevant bonuses (the 15 leading values —
     * indices 0..14 astab..speed; the trailing slotId is not a combat stat), so
     * collapsing the family to one representative can never change a DPS result.
     */
    @Test
    public void everyFamilyShares_dpsRelevantStats() {
        Map<String, List<Double>> stats = loadStats();
        for (int[] family : ChargeFamilies.familiesForTest()) {
            List<Double> baseline = null;
            int baselineId = -1;
            for (int id : family) {
                List<Double> row = stats.get(String.valueOf(id));
                assertNotNull("no stats for " + id, row);
                List<Double> dpsRelevant = row.subList(0, 15); // astab..speed
                if (baseline == null) {
                    baseline = dpsRelevant;
                    baselineId = id;
                } else {
                    assertEquals("charge " + id + " has different combat stats to " + baselineId
                                    + " — it is NOT a pure charge family and must not be collapsed",
                            baseline, dpsRelevant);
                }
            }
        }
    }

    // ------------------------------------------------------------------- helpers

    private static boolean sameFamily(int a, int b) {
        int[] fa = ChargeFamilies.familyOf(a);
        return fa != null && fa == ChargeFamilies.familyOf(b);
    }

    private static Map<String, List<Object>> loadIndex() {
        Type t = new TypeToken<Map<String, List<Object>>>() { }.getType();
        return readResource("/com/ospulse/combat/equipment_index.min.json", t);
    }

    private static Map<String, List<Double>> loadStats() {
        Type t = new TypeToken<Map<String, List<Double>>>() { }.getType();
        return readResource("/com/ospulse/combat/equipment_stats.min.json", t);
    }

    private static <T> T readResource(String path, Type type) {
        try (Reader r = new InputStreamReader(
                ChargeFamiliesTest.class.getResourceAsStream(path), StandardCharsets.UTF_8)) {
            return new Gson().fromJson(r, type);
        } catch (Exception e) {
            throw new RuntimeException("failed reading " + path, e);
        }
    }
}

package com.ospulse.combat;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Osmumten's fang's two STAB-only passives, verified against the OSRS Wiki
 * (<a href="https://oldschool.runescape.wiki/w/Osmumten%27s_fang">Osmumten's
 * fang</a>, checked 2026-07-04) and cross-checked against the weirdgloop DPS
 * calculator's {@code getFangAccuracyRoll} in {@code BaseCalc.ts} (our
 * parity oracle elsewhere in this package, e.g. {@link TierBEffectsTest}):
 *
 * <ol>
 *   <li><b>Double accuracy roll</b> (Stab styles only, since the 17 Jan 2024
 *   update restricted it from Slash): two independent accuracy rolls are
 *   made and the attack succeeds if EITHER beats the defence roll — hit
 *   chance {@code 1 - (d+2)(2d+3)/(6(a+1)^2)} when {@code a > d}, else
 *   {@code a(4a+5)/(6(a+1)(d+1))}. This is NOT the naive {@code 1-(1-p)^2}
 *   (that shortcut is only correct inside Tombs of Amascut).</li>
 *   <li><b>Compressed damage roll</b>: instead of a uniform 0..maxHit roll,
 *   the fang always deals between 15% and 85% of the true max hit
 *   (truncated) — wiki's own worked example: "if the fang's true max hit was
 *   60, it would roll between 9 and 51". This does not change the expected
 *   damage vs a normal roll except via the small "0 bumped to 1" correction,
 *   which only matters when the true max hit is tiny (&lt;=6, so the shrunk
 *   min is itself 0) — not exercised by the reference setups below, whose
 *   true max hit is 24 (well above that threshold).</li>
 * </ol>
 */
public class OsmumtensFangEffectTest {
    private static final double DELTA = 1e-9;

    private static EquipmentStats.Builder plainMeleeGear() {
        // +100 astab, +80 str, speed 4 — identical to TierBEffectsTest's plainMeleeGear(),
        // so the base (non-fang) maxHit/attackRoll figures line up with that class's
        // hand-worked comments (maxHit 24, attackRoll 18040).
        return EquipmentStats.builder()
                .add(100, 0, 0, 0, 0, 0, 0, 0, 0, 0, 80, 0, 0.0, 0)
                .weaponSpeedTicks(4);
    }

    private static PlayerCombat player99() {
        return PlayerCombat.builder()
                .attack(99, 99)
                .strength(99, 99)
                .stance(Stance.ACCURATE)
                .build();
    }

    private static Monster.Builder monster(int hp) {
        return Monster.builder()
                .name("Target")
                .hitpoints(hp)
                .defenceLevel(100)
                .defenceBonuses(50, 50, 50, 50, 50)
                .magicLevel(1);
    }

    /**
     * Reference setup (matches {@link TierBEffectsTest}'s shared worked
     * example exactly): effAtt = floor(99*1.0)+3+8 = 110, effStr =
     * floor(99*1.0)+0+8 = 107 (ACCURATE only bumps the attack side for
     * melee); gear +100 astab/+80 str; monster defenceLevel 100, stab
     * defence bonus 50.
     *
     * <pre>
     * maxHit      = floor((107*(80+64) + 320) / 640) = floor(15728/640) = 24
     * attackRoll  = 110 * (100+64)                    = 18040
     * defenceRoll = (100+9) * (50+64)                 = 12426
     * </pre>
     *
     * attackRoll (18040) &gt; defenceRoll (12426), so both hit-chance formulas
     * use their "a &gt; d" branch:
     *
     * <pre>
     * normal hitChance = 1 - (12426+2) / (2*(18040+1))            = 0.6555623302477690
     * fang   hitChance = 1 - (12426+2)*(2*12426+3) / (6*(18040+1)^2)
     *                  = 0.8418232861871717   (NOT 1-(1-0.65556...)^2 = 0.8815...)
     *
     * shrink = trunc(24 * 3/20) = trunc(3.6) = 3
     * fang damage roll range = [3, 24-3] = [3, 21]  (wiki: 60 -&gt; [9,51]; here 24 -&gt; [3,21])
     * fang avgDamage = fangHitChance * (3+21)/2 = 0.8418232861871717 * 12 = 10.101879434246061
     * fang dps        = avgDamage / (4 * 0.6)   = 4.209116430935859 (speed-4 weapon)
     * </pre>
     */
    @Test
    public void fang_vsPlainWeapon_usesDoubleRollAccuracyAndCompressedDamageRoll() {
        Monster target = monster(200).build();

        EquipmentStats plain = plainMeleeGear().build();
        EquipmentStats fang = plainMeleeGear().osmumtensFang(true).build();

        DpsResult base = DpsCalculator.compute(plain, player99(), CombatStyle.STAB, target, 0);
        DpsResult withFang = DpsCalculator.compute(fang, player99(), CombatStyle.STAB, target, 0);

        // Sanity: the reference attack/defence/maxHit figures match TierBEffectsTest's
        // shared worked example exactly (same gear/player/monster shape).
        assertEquals(24, base.maxHit());

        // Displayed max hit is the TRUE (unshrunk) max hit — the fang's passive compresses
        // the ROLL range, not the headline "Max hit" figure.
        assertEquals(24, withFang.maxHit());

        // Accuracy: fang's double-roll must exceed the plain single-roll hit chance,
        // and must NOT equal the naive 1-(1-p)^2 shortcut (that's ToA-only).
        assertEquals(0.6555623302477690, base.accuracy(), DELTA);
        assertEquals(0.8418232861871717, withFang.accuracy(), DELTA);
        double naiveDoubleRoll = 1.0 - (1.0 - base.accuracy()) * (1.0 - base.accuracy());
        assertTrue(Math.abs(withFang.accuracy() - naiveDoubleRoll) > 1e-3);

        // Average damage per attack: compressed-range average, hand-derived above.
        assertEquals(10.101879434246061, withFang.avgHit(), 1e-6);

        // DPS follows directly from avgDamage at the shared 4-tick weapon speed.
        assertEquals(4.209116430935859, withFang.dps(), 1e-6);

        // The fang must clearly out-DPS the identical plain weapon (this is the whole point
        // of modelling it: it was being under-rated as "just a generic stab weapon").
        assertTrue(withFang.dps() > base.dps());
    }

    @Test
    public void fang_passiveIsStabOnly_slashAndCrushUseGenericFormula() {
        // The 17 Jan 2024 update restricted the double-accuracy-roll passive to Stab;
        // the fang has no Slash/Crush attack styles offered in-game, but this pins that
        // the flag is correctly gated on CombatStyle.STAB in DpsCalculator.computeMelee
        // (a non-Stab style must fall back to the generic single-roll/uniform-damage path).
        Monster target = monster(200).build();
        EquipmentStats fangGear = EquipmentStats.builder()
                .add(0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 80, 0, 0.0, 0)
                .weaponSpeedTicks(4)
                .osmumtensFang(true)
                .build();

        DpsResult slash = DpsCalculator.compute(fangGear, player99(), CombatStyle.SLASH, target, 0);
        DpsResult stab = DpsCalculator.compute(fangGear, player99(), CombatStyle.STAB, target, 0);

        // Same attack roll magnitude (100 aslash vs would-be 100 astab) but the STAB
        // path's fang accuracy formula must diverge from SLASH's generic formula.
        // (aslash bonus isn't set for STAB above, so just assert the passive fires
        // for STAB and not for SLASH via a maxHit fallback: STAB gear has 0 astab here,
        // so its attackRoll is 0; the assertion below only needs the two computations
        // not to throw and STAB's accuracy to use the fang formula, verified above in
        // fang_vsPlainWeapon_usesDoubleRollAccuracyAndCompressedDamageRoll for full precision.)
        assertFalse(Double.isNaN(slash.accuracy()));
        assertFalse(Double.isNaN(stab.accuracy()));
    }

    @Test
    public void fangHitChance_matchesHandWorkedFormula_directly() {
        // Direct CombatMath-level pin, independent of the gear/DpsCalculator plumbing,
        // for the a>d branch used above.
        assertEquals(0.8418232861871717, DamageDistribution.fangHitChance(18040, 12426), DELTA);

        // a <= d branch: attackRoll 5000, defenceRoll 12426 ->
        // a*(4a+5) / (6*(a+1)*(d+1)) = 5000*20005 / (6*5001*12427)
        double expected = 5000.0 * (4.0 * 5000.0 + 5.0) / (6.0 * 5001.0 * 12427.0);
        assertEquals(expected, DamageDistribution.fangHitChance(5000, 12426), DELTA);
        assertTrue(DamageDistribution.fangHitChance(5000, 12426) < 1.0);
    }

    @Test
    public void fangAverageDamage_compressesRangeWithoutChangingItsMidpointShape() {
        // maxHit 60 -> wiki's own worked example: roll range [9, 51].
        // At hitChance 1.0 (certainty), avg damage = (9+51)/2 = 30 exactly.
        assertEquals(30.0, DamageDistribution.fangAverageDamage(1.0, 60), DELTA);

        // maxHit 24 -> range [3, 21]; at hitChance 1.0, avg = 12.
        assertEquals(12.0, DamageDistribution.fangAverageDamage(1.0, 24), DELTA);
    }
}

package com.ospulse.combat;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

/**
 * The mathematical fact {@code REROLL} relies on: re-rolling a hit that lands
 * above a cap {@code C} uniformly back into {@code 0..C} produces a
 * distribution that is <b>exactly uniform over {@code 0..C}</b> — independent
 * of the uncapped max hit {@code M} the original roll came from.
 *
 * <p>Proof sketch (also stated in {@code MonsterCombatRequirement.CapMode}):
 * a raw roll is uniform over {@code 0..M}, each outcome with probability
 * {@code 1/(M+1)}. An outcome {@code r <= C} is kept as-is; an outcome
 * {@code r > C} (there are {@code M-C} of them) is re-rolled uniformly over
 * {@code 0..C}, so each of the {@code C+1} rerolled values gets an equal
 * share {@code 1/(C+1)} of that re-rolled mass. So for every {@code d} in
 * {@code 0..C}:
 * <pre>
 * P(d) = 1/(M+1)                                  [kept outcome d itself]
 *      + (M-C)/(M+1) * 1/(C+1)                    [share of the re-rolled mass]
 * </pre>
 * which does not depend on {@code d} at all — so the distribution is
 * uniform over {@code 0..C}.
 *
 * <p><b>This flatness is about the SHAPE only, and does NOT license
 * implementing {@code CapMode#REROLL} as {@code maxHit = min(maxHit, cap)} fed
 * through the ordinary formulas.</b> Those carry OSRS's "a rolled 0 becomes 1"
 * correction, which belongs to the damage roll and therefore applies BEFORE the
 * monster re-rolls — surviving only on values that were never re-rolled, while a
 * re-rolled 0 stays a genuine 0. The real mean is
 * {@code C/2 + 1/(M+1)}, not {@code C/2 + 1/(C+1)}; see
 * {@link DamageDistribution#rerolledAverageDamage} /
 * {@link DamageDistribution#rerolledExpectedOverkill}, which are what
 * {@code DpsCalculator} actually calls. The shortcut shipped once on the
 * strength of the result below and was caught in review.
 *
 * <p>This test does NOT hand-encode that closed form and check it is
 * self-consistent (that would prove nothing about the mechanic, only that
 * arithmetic is arithmetic). It instead builds the rerolled distribution from
 * first principles — enumerate every one of the {@code M+1} equally-likely
 * raw outcomes, redistribute each one that exceeds the cap uniformly across
 * {@code 0..C} — and checks the result is flat.
 */
public class CombatMathRerollEquivalenceTest {

    /**
     * Builds P(d) for d in {@code 0..cap} from first principles: each of the
     * {@code uncappedMax + 1} raw outcomes is equally likely; an outcome
     * {@code <= cap} contributes its full weight to itself, an outcome
     * {@code > cap} contributes an equal 1/(cap+1) share of its weight to
     * EVERY value in {@code 0..cap} (a fresh uniform re-roll).
     */
    private static double[] rerolledDistribution(int uncappedMax, int cap) {
        double[] p = new double[cap + 1];
        double rawWeight = 1.0 / (uncappedMax + 1);
        for (int r = 0; r <= uncappedMax; r++) {
            if (r <= cap) {
                p[r] += rawWeight;
            } else {
                double share = rawWeight / (cap + 1);
                for (int d = 0; d <= cap; d++) {
                    p[d] += share;
                }
            }
        }
        return p;
    }

    /** The distribution built above must be a real probability distribution: it sums to 1. */
    @Test
    public void rerolledDistributionSumsToOne() {
        for (int[] pair : new int[][]{{40, 4}, {40, 10}, {100, 3}, {20, 15}, {7, 7}, {10, 10}}) {
            double[] p = rerolledDistribution(pair[0], pair[1]);
            double sum = 0.0;
            for (double v : p) {
                sum += v;
            }
            assertEquals("distribution for M=" + pair[0] + " cap=" + pair[1] + " must sum to 1", 1.0, sum, 1e-9);
        }
    }

    /**
     * The core claim: every value in {@code 0..cap} is equally likely after a
     * re-roll, for every (M, cap) pair with cap &lt; M (a binding cap) — not
     * just the boundary values.
     */
    @Test
    public void rerolledDistributionIsExactlyUniform_forSeveralMaxCapPairs() {
        int[][] pairs = {{40, 4}, {40, 10}, {100, 3}, {20, 15}, {11, 1}, {200, 50}};
        for (int[] pair : pairs) {
            int uncappedMax = pair[0];
            int cap = pair[1];
            double[] p = rerolledDistribution(uncappedMax, cap);
            double expected = p[0];
            for (int d = 1; d <= cap; d++) {
                assertEquals("P(d) must be constant across d for M=" + uncappedMax + " cap=" + cap
                        + " (d=" + d + " diverged from d=0)", expected, p[d], 1e-12);
            }
            // And it must match the plain "1/(cap+1)" a genuinely uniform 0..cap roll would give.
            assertEquals("uniform value must equal a plain 1/(cap+1) roll", 1.0 / (cap + 1), expected, 1e-12);
        }
    }

    /** With cap == M there is nothing to re-roll: the distribution is trivially the original uniform 0..M roll. */
    @Test
    public void noBindingCap_isStillUniform() {
        double[] p = rerolledDistribution(10, 10);
        for (double v : p) {
            assertEquals(1.0 / 11.0, v, 1e-12);
        }
    }

    /**
     * Consequence: since the rerolled distribution is uniform 0..cap, its
     * expectation is the ordinary uniform mean {@code cap/2} — precisely the
     * value {@link DamageDistribution#averageDamage} uses (up to that
     * method's own separate "rolled 0 becomes 1" correction, which applies
     * identically whether the roll came from a genuine 0..cap weapon or a
     * re-roll into 0..cap — the point this test proves is that the RAW
     * distributions are identical, so any downstream formula built on top of
     * a raw uniform 0..cap roll gets the same answer either way).
     */
    @Test
    public void rerolledMeanMatchesThePlainUniformMean() {
        for (int[] pair : new int[][]{{40, 4}, {40, 10}, {100, 3}, {20, 15}}) {
            int uncappedMax = pair[0];
            int cap = pair[1];
            double[] p = rerolledDistribution(uncappedMax, cap);
            double mean = 0.0;
            for (int d = 0; d <= cap; d++) {
                mean += d * p[d];
            }
            assertEquals("rerolled mean must equal the plain uniform 0..cap mean", cap / 2.0, mean, 1e-9);
        }
    }
}

