        DpsResult r = DpsCalculator.compute(plainGear(), mage99(), CombatStyle.MAGIC, probeTarget(), 30);
        assertEquals(30, r.maxHit());
        assertEquals(2.6594028081734744, r.dps(), DELTA);
    }
}

package com.ospulse.combat;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;

import org.junit.Test;

/**
 * Tests {@link SpecWeaponSelector#select} against the design spec §8
 * selection rule, using REAL {@link SpecWeapon#CATALOG} entries (so a
 * catalog edit that breaks the rule's assumptions — e.g. removing every
 * DEFENCE_DRAIN entry — shows up here) with a synthetic {@link
 * SpecWeaponSelector.DpsProbe} so the ranking logic is tested independently
 * of the real DPS pipeline.
 */
public class SpecWeaponSelectorTest {
    static {
        BundledGson.set(new com.google.gson.Gson());
    }

    private static final int DRAGON_CLAWS = 13652;
    private static final int DRAGON_DAGGER = 1231;
    private static final int TOXIC_BLOWPIPE = 12926;
    private static final int DRAGON_WARHAMMER = 13576;
    private static final int BANDOS_GODSWORD = 11804;
    private static final int SARADOMIN_GODSWORD = 11806;
    private static final int ZARYTE_CROSSBOW = 26374;
    private static final int VOIDWAKER = 27690;
    private static final int VOIDWAKER_DEADMAN = 29607; // alias of VOIDWAKER, mode-locked by name

    private static Monster monsterWithDefence(int defenceLevel) {
        return Monster.builder().name("Test monster").hitpoints(100).defenceLevel(defenceLevel)
                .defenceBonuses(0, 0, 0, 0, 0).magicLevel(1).build();
    }

    /** A fixed max hit + accuracy for every candidate, keyed by item id; unknown ids return null (not computable). */
    private static SpecWeaponSelector.DpsProbe fixedProbe(java.util.Map<Integer, DpsResult> byItemId) {
        return weapon -> byItemId.get(weapon.itemId());
    }

    private static DpsResult result(int maxHit, double accuracy) {
        return new DpsResult(maxHit, accuracy, 0, 0, 0, 0, false);
    }

    @Test
    public void emptyWhenNothingOwned() {
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, Collections.emptySet(), fixedProbe(Collections.emptyMap()));
        assertFalse(rec.isPresent());
    }

    @Test
    public void emptyWhenTargetIsNull() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                null, null, owned, fixedProbe(Collections.emptyMap()));
        assertFalse(rec.isPresent());
    }

    @Test
    public void utilityRoleIsNeverRecommendedEvenWhenItScoresHighest() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(ZARYTE_CROSSBOW, DRAGON_CLAWS));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(ZARYTE_CROSSBOW, result(1000, 1.0)); // absurdly high, would win on any damage metric
        byId.put(DRAGON_CLAWS, result(20, 0.5));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(DRAGON_CLAWS, rec.get().itemId());
    }

    /** Round-2 director decision (step 5 fallback): HEAL is recommended when it is the only owned+legal spec at all. */
    @Test
    public void healRoleIsSelectedAsAFallbackWhenItIsTheOnlyOwnedSpec() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(SARADOMIN_GODSWORD));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(SARADOMIN_GODSWORD, result(40, 0.8));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(SARADOMIN_GODSWORD, rec.get().itemId());
    }

    /** HEAL is a last resort only — an owned DAMAGE spec always outranks it, never the other way round. */
    @Test
    public void healRoleNeverOutranksAnOwnedDamageSpec() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(SARADOMIN_GODSWORD, DRAGON_CLAWS));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(SARADOMIN_GODSWORD, result(90, 0.99)); // absurdly high, would win on any damage metric
        byId.put(DRAGON_CLAWS, result(10, 0.2));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(DRAGON_CLAWS, rec.get().itemId());
    }

    @Test
    public void picksBestDamageScoreWhenDefenceIsLow() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS, DRAGON_DAGGER));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        // Dragon claws (50% cost): tiny hit so its damage/cost score is low.
        byId.put(DRAGON_CLAWS, result(1, 0.01));
        // Dragon dagger (25% cost): big hit so its damage/cost score wins.
        byId.put(DRAGON_DAGGER, result(80, 0.9));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(DRAGON_DAGGER, rec.get().itemId());
    }

    @Test
    public void defenceDrainOwnedAndTargetHighDefenceWinsOverAHigherScoringDamageSpec() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS, DRAGON_WARHAMMER));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_CLAWS, result(90, 0.95)); // would clearly win on damage/cost alone
        byId.put(DRAGON_WARHAMMER, result(10, 0.3));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(SpecWeaponSelector.HIGH_DEFENCE_THRESHOLD), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals("rule 2 must take priority over rule 3 at/above the threshold",
                DRAGON_WARHAMMER, rec.get().itemId());
    }

    @Test
    public void fallsBackToDamageWhenNoDefenceDrainOwnedEvenAtHighDefence() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_CLAWS, result(40, 0.6));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(SpecWeaponSelector.HIGH_DEFENCE_THRESHOLD + 50), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(DRAGON_CLAWS, rec.get().itemId());
    }

    @Test
    public void belowThresholdIgnoresDefenceDrainEvenIfOwned() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS, DRAGON_WARHAMMER));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_CLAWS, result(40, 0.6));
        byId.put(DRAGON_WARHAMMER, result(90, 0.99));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(SpecWeaponSelector.HIGH_DEFENCE_THRESHOLD - 1), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals("below threshold, rule 3 (best DAMAGE) applies even with a DEFENCE_DRAIN owned",
                DRAGON_CLAWS, rec.get().itemId());
    }

    @Test
    public void illegalWeaponUnderTheCombatRequirementIsExcluded() {
        // A Zulrah-style gate: only RANGED (via allowedStyles) or a specific
        // ranged item id may damage this target — dragon claws (SLASH) and
        // dragon dagger (SLASH per its own spec style) are both excluded,
        // leaving toxic blowpipe (RANGED) as the only eligible DAMAGE spec.
        MonsterCombatRequirement rangedOnly = MonsterCombatRequirement.weaponGate(
                Collections.emptySet(), Collections.emptySet(), EnumSet.of(CombatStyle.RANGED), "Ranged/Magic only");
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS, TOXIC_BLOWPIPE));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_CLAWS, result(90, 0.95));
        byId.put(TOXIC_BLOWPIPE, result(20, 0.5));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), rangedOnly, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(TOXIC_BLOWPIPE, rec.get().itemId());
    }

    @Test
    public void emptyWhenEveryOwnedCandidateIsIllegal() {
        MonsterCombatRequirement rangedOnly = MonsterCombatRequirement.weaponGate(
                Collections.emptySet(), Collections.emptySet(), EnumSet.of(CombatStyle.RANGED), "Ranged/Magic only");
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS, BANDOS_GODSWORD));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), rangedOnly, owned, fixedProbe(Collections.emptyMap()));
        assertFalse(rec.isPresent());
    }

    @Test
    public void ownedAliasIdCountsAsOwnership() {
        // 28039 is one of Dragon claws' cosmetic-recolour alias ids.
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(28039));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_CLAWS, result(40, 0.6));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(DRAGON_CLAWS, rec.get().itemId());
    }

    // ---- PR #25 finding 1: ownership does not imply equippability -----------------------

    /**
     * Voidwaker requires 75 Attack (verified against {@code
     * equipment_requirements.min.json}). Owning one at a lower Attack level
     * must not surface it — {@link EquipmentRequirementsRepository#canEquip}
     * is the exact seam {@code GearOptimizer} already uses for this, not a
     * second requirements table.
     */
    @Test
    public void equipLevelRequirementIsEnforcedEvenWhenOwned() {
        int voidwaker = 27690;
        assertEquals("test assumes Voidwaker's real requirement — if this fails the bundled data changed",
                Integer.valueOf(75), EquipmentRequirementsRepository.getInstance().requirementsFor(voidwaker).get("attack"));

        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(voidwaker));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(voidwaker, result(40, 0.6));
        java.util.Map<String, Integer> tooLowAttack = Collections.singletonMap("attack", 60);

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(), tooLowAttack, -1, fixedProbe(byId));
        assertFalse("60 Attack cannot equip a 75-Attack Voidwaker", rec.isPresent());
    }

    /** Same setup as above, but with a level that DOES meet the requirement — proves the gate isn't just always rejecting. */
    @Test
    public void equipLevelRequirementAllowsTheWeaponOnceMet() {
        int voidwaker = 27690;
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(voidwaker));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(voidwaker, result(40, 0.6));
        java.util.Map<String, Integer> sufficientAttack = Collections.singletonMap("attack", 75);

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(), sufficientAttack, -1, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(voidwaker, rec.get().itemId());
    }

    // ---- Round 2 finding (c): equip level must be resolved across the weapon family ------

    /**
     * The catalog's canonical Dragon dagger id (1231) has NO row in
     * {@code equipment_requirements.min.json} — a data-shape gap found in
     * review — while alias ids 1215/5698 carry the real 60 Attack
     * requirement. Checking the canonical id alone (as {@link
     * EquipmentRequirementsRepository#canEquip} does when given just {@link
     * #DRAGON_DAGGER}) fails OPEN and lets a sub-60-Attack player be
     * recommended it. The fix resolves the requirement across the whole
     * family (canonical + every alias) at the spec-catalog level.
     */
    @Test
    public void equipLevelRequirementIsResolvedAcrossTheWeaponFamilyEvenWhenTheCanonicalIdHasNoRow() {
        assertEquals("test assumes the canonical id's data gap — if this fails the bundled data changed",
                null, EquipmentRequirementsRepository.getInstance().requirementsFor(DRAGON_DAGGER));
        assertEquals("test assumes an alias carries the real requirement — if this fails the bundled data changed",
                Integer.valueOf(60), EquipmentRequirementsRepository.getInstance().requirementsFor(1215).get("attack"));

        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_DAGGER));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_DAGGER, result(40, 0.6));
        java.util.Map<String, Integer> tooLowAttack = Collections.singletonMap("attack", 30);

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(), tooLowAttack, -1, fixedProbe(byId));
        assertFalse("30 Attack cannot equip a 60-Attack Dragon dagger, even though the canonical id's own row is missing",
                rec.isPresent());
    }

    /** Same setup as above, but with a level that DOES meet the family's real requirement. */
    @Test
    public void equipLevelRequirementResolvedAcrossTheFamilyAllowsTheWeaponOnceMet() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_DAGGER));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_DAGGER, result(40, 0.6));
        java.util.Map<String, Integer> sufficientAttack = Collections.singletonMap("attack", 60);

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(), sufficientAttack, -1, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(DRAGON_DAGGER, rec.get().itemId());
    }

    // ---- Round-3 finding: restriction must apply to the actually-owned family member -----

    /**
     * When the ONLY owned id in the family is the restricted alias (e.g. a
     * mode-locked Voidwaker (deadman) 29607), the canonical 27690 was never
     * actually owned — {@link SpecWeapon#isOwned} succeeds family-wide, but
     * the restriction check must reject THIS weapon rather than checking the
     * canonical id (which is unrestricted) and letting an item the player
     * does not own through.
     */
    @Test
    public void restrictionAppliesToTheActuallyOwnedFamilyMember() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(VOIDWAKER_DEADMAN));
        Set<Integer> restrictions = new HashSet<>(java.util.Arrays.asList(VOIDWAKER_DEADMAN));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(VOIDWAKER, result(40, 0.6));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(), restrictions,
                Collections.emptyMap(), -1, fixedProbe(byId));
        assertFalse("the only owned id (29607) is restricted — no unrestricted owned id exists, "
                        + "so an ordinary Voidwaker the player never owned must not be recommended",
                rec.isPresent());
    }

    /**
     * Preserves the ordinary-owner case: a player who owns the canonical
     * 27690 itself must still get the recommendation even though the
     * (unowned) deadman alias 29607 is restricted — restriction must not
     * become family-wide again.
     */
    @Test
    public void restrictedAliasDoesNotSuppressAnActuallyOwnedCanonicalId() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(VOIDWAKER));
        Set<Integer> restrictions = new HashSet<>(java.util.Arrays.asList(VOIDWAKER_DEADMAN));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(VOIDWAKER, result(40, 0.6));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(), restrictions,
                Collections.emptyMap(), -1, fixedProbe(byId));
        assertTrue("the owned canonical id is itself unrestricted, so it must still be recommended",
                rec.isPresent());
        assertEquals(VOIDWAKER, rec.get().itemId());
    }

    // ---- PR #25 finding 2: ranged specs need worn-ammo validation ------------------------

    /**
     * A Kurask/Turoth-shaped gate (real shape, from {@code
     * monster_combat_requirements.json}: leaf-bladed weapons, broad ammo
     * (both broad arrows AND broad bolts), or Magic Dart): no
     * broadly-allowed style, a small leaf-bladed-weapon exception list, and
     * a broad-ammo allowlist. {@code permitsWeapon} alone accepts ANY
     * worn-ammo-firing ranged weapon here (it can't see which ammo is
     * actually loaded) — {@code permitsAmmo} is what actually enforces
     * "broad ammo only".
     */
    private static MonsterCombatRequirement kuraskShapedAmmoGate() {
        int broadArrows = 4160;
        int broadBolts = 11875;
        int leafBladedSword = 4158;
        return MonsterCombatRequirement.weaponGate(
                new HashSet<>(java.util.Arrays.asList(leafBladedSword)),
                new HashSet<>(java.util.Arrays.asList(broadArrows, broadBolts)),
                Collections.emptySet(),
                "Only leaf-bladed weapons, broad ammo, or Magic Dart can harm it.");
    }

    /** Magic shortbow (861) — a DAMAGE-role RANGED spec that fires worn ammo (ARROW class), unlike the UTILITY-role Zaryte crossbow. */
    private static final int MAGIC_SHORTBOW = 861;

    @Test
    public void rangedSpecOwningWrongWornAmmoIsNotRecommended() {
        int regularArrow = 893; // "Rune arrow" — not in the gate's allowedAmmoIds
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(MAGIC_SHORTBOW));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(MAGIC_SHORTBOW, result(90, 0.99));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), kuraskShapedAmmoGate(), owned, Collections.emptySet(),
                Collections.emptyMap(), regularArrow, fixedProbe(byId));
        assertFalse("permitsWeapon() alone would accept this — permitsAmmo() must reject the non-broad arrow",
                rec.isPresent());
    }

    @Test
    public void rangedSpecWithCorrectBroadAmmoIsRecommended() {
        int broadArrows = 4160; // matches kuraskShapedAmmoGate()'s allowedAmmoIds
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(MAGIC_SHORTBOW));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(MAGIC_SHORTBOW, result(90, 0.99));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), kuraskShapedAmmoGate(), owned, Collections.emptySet(),
                Collections.emptyMap(), broadArrows, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(MAGIC_SHORTBOW, rec.get().itemId());
    }

    /** A self-supplying ranged weapon (no worn ammo) is unaffected by the ammo gate either way — it was already excluded by permitsWeapon. */
    @Test
    public void selfSupplyingRangedSpecIgnoresWornAmmoValidation() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(TOXIC_BLOWPIPE));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(TOXIC_BLOWPIPE, result(90, 0.99));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), kuraskShapedAmmoGate(), owned, Collections.emptySet(),
                Collections.emptyMap(), -1, fixedProbe(byId));
        assertFalse("a dart-firing blowpipe cannot hit a broad-ammo-gated target regardless of worn ammo",
                rec.isPresent());
    }

    // ---- Round 2 finding (b): ammo must match the WEAPON, not just the target ------------

    /**
     * Kurask's real gate permits BOTH broad arrows and broad bolts (see
     * {@link #kuraskShapedAmmoGate}) — that is a target-side allowlist, not a
     * promise that any weapon can fire any allowed ammo. A Magic shortbow
     * only ever fires the ARROW class ({@link AmmoCompatibility#consumedClass}),
     * so broad BOLTS worn behind it must still be rejected even though
     * {@code permitsWeapon}/{@code permitsAmmo} both pass — the bow physically
     * cannot load a bolt.
     */
    @Test
    public void rangedSpecWithWrongAmmoClassForTheWeaponIsRejectedEvenWhenTheTargetAllowsIt() {
        int broadBolts = 11875; // in kuraskShapedAmmoGate()'s allowedAmmoIds, but wrong CLASS for a bow
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(MAGIC_SHORTBOW));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(MAGIC_SHORTBOW, result(90, 0.99));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), kuraskShapedAmmoGate(), owned, Collections.emptySet(),
                Collections.emptyMap(), broadBolts, fixedProbe(byId));
        assertFalse("a Magic shortbow cannot fire broad bolts even though Kurask's gate allows the ammo class",
                rec.isPresent());
    }

    /**
     * The bigger hole from the finding: MOST targets have no combat
     * requirement at all (unrestricted), so {@code requirement == null}
     * skipped the ammo check entirely. Weapon/ammo compatibility is a
     * property of the weapon and must be enforced regardless of whether the
     * monster gates ammo.
     */
    @Test
    public void rangedSpecWithWrongAmmoClassForTheWeaponIsRejectedEvenAtAnUnrestrictedTarget() {
        int broadBolts = 11875; // BOLT class; Magic shortbow only fires ARROW
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(MAGIC_SHORTBOW));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(MAGIC_SHORTBOW, result(90, 0.99));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(),
                Collections.emptyMap(), broadBolts, fixedProbe(byId));
        assertFalse("no monster requirement at all must not exempt weapon/ammo compatibility",
                rec.isPresent());
    }

    /** Sanity check: the SAME unrestricted target still recommends the shortbow when the worn ammo actually matches. */
    @Test
    public void rangedSpecWithCorrectAmmoClassIsRecommendedAtAnUnrestrictedTarget() {
        int runeArrow = 893; // ARROW class — matches Magic shortbow's consumedClass
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(MAGIC_SHORTBOW));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(MAGIC_SHORTBOW, result(90, 0.99));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(),
                Collections.emptyMap(), runeArrow, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(MAGIC_SHORTBOW, rec.get().itemId());
    }

    // ---- PR #25 finding 4: "Exclude from suggestions" must be honoured -------------------

    /**
     * Excluding the higher-scoring owned spec must remove it from
     * consideration entirely (not just demote it) and let the next-best
     * owned+legal spec take over — the exact two-part assertion the
     * "Exclude from suggestions" feature (shipped stage 4, reporter's
     * explicit request) already guarantees for ordinary optimiser
     * candidates via {@code GearOptimizer.Request.exclude}.
     */
    @Test
    public void excludedSpecIsRemovedAndADifferentSpecIsChosenInstead() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS, DRAGON_DAGGER));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        // Dragon claws would clearly win on damage/cost if not excluded.
        byId.put(DRAGON_CLAWS, result(90, 0.95));
        byId.put(DRAGON_DAGGER, result(20, 0.5));

        Optional<SpecWeaponRecommendation> unexcluded = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, Collections.emptySet(), Collections.emptyMap(), -1, fixedProbe(byId));
        assertEquals("sanity check: claws must win before exclusion", DRAGON_CLAWS, unexcluded.get().itemId());

        Set<Integer> excluded = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS));
        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, excluded, Collections.emptyMap(), -1, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals("excluding claws must let dagger take over, not just leave nothing recommended",
                DRAGON_DAGGER, rec.get().itemId());
    }

    /** Excluding a cosmetic recolour (alias id) excludes the whole weapon, mirroring {@link #ownedAliasIdCountsAsOwnership}. */
    @Test
    public void excludingAnAliasIdExcludesTheWholeWeapon() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(DRAGON_CLAWS));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(DRAGON_CLAWS, result(40, 0.6));
        Set<Integer> excludedByAlias = new HashSet<>(java.util.Arrays.asList(28039)); // Dragon claws (or)

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(50), null, owned, excludedByAlias, Collections.emptyMap(), -1, fixedProbe(byId));
        assertFalse(rec.isPresent());
    }

    // ---- PR #25 finding: 30305 "Arclight (inactive)" must not be an alias of Arclight ----

    private static final int ARCLIGHT = 19675;
    private static final int ARCLIGHT_INACTIVE = 30305; // charge-state variant, NOT a cosmetic recolour — see SpecWeapon javadoc

    /** Catalog guard: re-adding 30305 to Arclight's aliases must break this test. */
    @Test
    public void arclightInactiveIsNotAnOwnedAliasOfArclight() {
        SpecWeapon arclight = findCatalogEntry(ARCLIGHT);
        assertFalse("30305 (Arclight (inactive)) is a charge-state variant, not a cosmetic recolour of the SAME "
                        + "physical weapon — it must not be in Arclight's ownedAliasIds()",
                arclight.ownedAliasIds().contains(ARCLIGHT_INACTIVE));
    }

    /**
     * Owning ONLY the inactive charge-state variant must not recommend the
     * (unowned, better-stats) charged Arclight. Arclight is DEFENCE_DRAIN, so
     * the target defence must be at/above {@link SpecWeaponSelector#HIGH_DEFENCE_THRESHOLD}
     * for the role to be considered at all — otherwise an empty result would
     * prove nothing about the alias fix specifically.
     */
    @Test
    public void owningOnlyArclightInactiveDoesNotRecommendArclight() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(ARCLIGHT_INACTIVE));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(ARCLIGHT, result(90, 0.95)); // absurdly high — would win if 30305 wrongly counted as owning it

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(SpecWeaponSelector.HIGH_DEFENCE_THRESHOLD), null, owned, fixedProbe(byId));
        assertFalse("owning only the inactive charge-state variant (30305) must not recommend the charged Arclight "
                        + "the player does not own",
                rec.isPresent());
    }

    /** Sanity check: owning the actual charged Arclight (19675) still produces a recommendation as before. */
    @Test
    public void owningArclightItselfStillRecommendsIt() {
        Set<Integer> owned = new HashSet<>(java.util.Arrays.asList(ARCLIGHT));
        java.util.Map<Integer, DpsResult> byId = new java.util.HashMap<>();
        byId.put(ARCLIGHT, result(40, 0.6));

        Optional<SpecWeaponRecommendation> rec = SpecWeaponSelector.select(
                monsterWithDefence(SpecWeaponSelector.HIGH_DEFENCE_THRESHOLD), null, owned, fixedProbe(byId));
        assertTrue(rec.isPresent());
        assertEquals(ARCLIGHT, rec.get().itemId());
    }

    private static SpecWeapon findCatalogEntry(int itemId) {
        for (SpecWeapon weapon : SpecWeapon.CATALOG) {
            if (weapon.itemId() == itemId) {
                return weapon;
            }
        }
        throw new AssertionError("no catalog entry with itemId " + itemId);
    }
}

package com.ospulse.combat;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Weapon-requirement metadata on {@link Spell}: Iban Blast is castable ONLY
 * with Iban's staff (regular id 1409, the other charged id 1410, or the
 * upgraded Iban's staff (u) 12658) — see the OSRS Wiki's Iban Blast page.
 * Every other spell in the enum has no weapon requirement and is castable
 * with any weapon (the ranking method still separately filters by whether the
 * weapon is even a magic weapon at all; this is just the extra per-spell gate).
 */
public class SpellTest {
    private static final int IBANS_STAFF = 1409;
    private static final int IBANS_STAFF_OTHER_CHARGED_ID = 1410;
    private static final int IBANS_STAFF_U = 12658;
    private static final int DRAGON_HUNTER_WAND = 24422;
    private static final int STAFF_OF_FIRE = 1387;

    @Test
    public void ibanBlastIsCastableOnlyWithIbansStaffVariants() {
        assertTrue(Spell.IBAN_BLAST.isCastableWith(IBANS_STAFF));
        assertTrue(Spell.IBAN_BLAST.isCastableWith(IBANS_STAFF_OTHER_CHARGED_ID));
        assertTrue(Spell.IBAN_BLAST.isCastableWith(IBANS_STAFF_U));
    }

    @Test
    public void ibanBlastIsNotCastableWithOtherStaves() {
        assertFalse(Spell.IBAN_BLAST.isCastableWith(DRAGON_HUNTER_WAND));
        assertFalse(Spell.IBAN_BLAST.isCastableWith(STAFF_OF_FIRE));
        assertFalse(Spell.IBAN_BLAST.isCastableWith(-1));
    }

    @Test
    public void spellsWithNoWeaponRequirementAreCastableWithAnyWeapon() {
        assertTrue(Spell.FIRE_SURGE.isCastableWith(STAFF_OF_FIRE));
        assertTrue(Spell.FIRE_SURGE.isCastableWith(DRAGON_HUNTER_WAND));
        assertTrue(Spell.FIRE_SURGE.isCastableWith(-1));
        assertTrue(Spell.ICE_BARRAGE.isCastableWith(STAFF_OF_FIRE));
    }

    /**
     * {@link Spell#twinflameEligible()} — Bolt/Blast/Wave across all four
     * elements only, and NOT the name-substring trap the reference JS
     * implementation falls into (Iban Blast).
     */
    @Test
    public void twinflameEligible_boltBlastWaveAcrossAllFourElements() {
        assertTrue(Spell.WIND_BOLT.twinflameEligible());
        assertTrue(Spell.WATER_BOLT.twinflameEligible());
        assertTrue(Spell.EARTH_BOLT.twinflameEligible());
        assertTrue(Spell.FIRE_BOLT.twinflameEligible());
        assertTrue(Spell.WIND_BLAST.twinflameEligible());
        assertTrue(Spell.WATER_BLAST.twinflameEligible());
        assertTrue(Spell.EARTH_BLAST.twinflameEligible());
        assertTrue(Spell.FIRE_BLAST.twinflameEligible());
        assertTrue(Spell.WIND_WAVE.twinflameEligible());
        assertTrue(Spell.WATER_WAVE.twinflameEligible());
        assertTrue(Spell.EARTH_WAVE.twinflameEligible());
        assertTrue(Spell.FIRE_WAVE.twinflameEligible());
    }

    @Test
    public void twinflameEligible_falseForStrikeAndSurge() {
        assertFalse(Spell.WIND_STRIKE.twinflameEligible());
        assertFalse(Spell.FIRE_STRIKE.twinflameEligible());
        assertFalse(Spell.WIND_SURGE.twinflameEligible());
        assertFalse(Spell.FIRE_SURGE.twinflameEligible());
    }

    @Test
    public void twinflameEligible_falseForIbanBlast_nameSubstringTrap() {
        // Iban Blast's display name contains "Blast" - the reference JS
        // implementation's name.includes('Blast') gate would wrongly match it.
        // It has no Element/Tier, so twinflameEligible() must be false.
        assertFalse(Spell.IBAN_BLAST.twinflameEligible());
        assertEquals(null, Spell.IBAN_BLAST.element());
        assertEquals(null, Spell.IBAN_BLAST.tier());
    }

    @Test
    public void twinflameEligible_falseForNonElementalSpells() {
        assertFalse(Spell.CRUMBLE_UNDEAD.twinflameEligible());
        assertFalse(Spell.SARADOMIN_STRIKE.twinflameEligible());
        assertFalse(Spell.CLAWS_OF_GUTHIX.twinflameEligible());
        assertFalse(Spell.FLAMES_OF_ZAMORAK.twinflameEligible());
        assertFalse(Spell.ICE_BARRAGE.twinflameEligible());
        assertFalse(Spell.SMOKE_RUSH.twinflameEligible());
    }
}

package com.ospulse.combat;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Pure-math tests for {@link TwinflameSecondHit}, independent of any
 * DpsCalculator scenario. The core claim under test: the exact expected
 * second-hit damage is {@code hitChance * E[floor(0.4*D)]}, which is NOT the
 * same as {@code hitChance * floor(0.4 * E[D])} nor {@code 0.4 *
 * hitChance*E[D]} — the floor must be applied per-outcome, before averaging.
 */
public class TwinflameSecondHitMathTest {
    private static final double DELTA = 1e-9;

    /**
     * Reconstructs the expected second-hit average from first principles,
     * independently of {@link TwinflameSecondHit}'s implementation: every raw
     * roll 0..maxHit is equally likely ({@code 1/(maxHit+1)} each), a raw roll
     * of 0 is bumped to a landed damage of 1 (the standard "rolled 0 becomes
     * 1 on a hit" rule), and the second hit is {@code floor(0.4 * landed)}.
     * This does not reuse the production formula's grouped probabilities
     * (P(1)=2/(maxHit+1), P(d)=1/(maxHit+1) for d=2..maxHit) — it enumerates
     * every one of the {@code maxHit+1} raw outcomes individually.
     */
    private static double bruteForceSecondHitAverage(double hitChance, int maxHit) {
        int outcomes = maxHit + 1;
        double sum = 0.0;
        for (int raw = 0; raw <= maxHit; raw++) {
            int landed = raw == 0 ? 1 : raw;
            sum += Math.floor(landed * 0.4);
        }
        return hitChance * (sum / outcomes);
    }

    @Test
    public void secondHitAverage_matchesBruteForceEnumeration_acrossVariousMaxHits() {
        int[] maxHits = {1, 4, 5, 8, 12, 16, 20, 24, 44};
        double[] hitChances = {1.0, 0.85, 0.53, 0.1};
        for (int maxHit : maxHits) {
            for (double hitChance : hitChances) {
                double expected = bruteForceSecondHitAverage(hitChance, maxHit);
                double actual = TwinflameSecondHit.secondHitAverage(hitChance, maxHit);
                assertEquals("maxHit=" + maxHit + " hitChance=" + hitChance, expected, actual, DELTA);
            }
        }
    }

    @Test
    public void secondHitAverage_isNotTheNaiveFortyPercentOfExpectedFirstHit() {
        // Fire Bolt tier: maxHit=12. Naive (rejected) shortcut: 0.4 * averageDamage.
        // Exact: hitChance * sum(floor(0.4*d) * P(d)) - these must differ for a hit chance of 1.
        int maxHit = 12;
        double hitChance = 1.0;
        double naiveShortcut = 0.4 * DamageDistribution.averageDamage(hitChance, maxHit);
        double exact = TwinflameSecondHit.secondHitAverage(hitChance, maxHit);
        assertTrue("the floored exact expectation must differ from the naive 0.4x-of-average shortcut",
                Math.abs(naiveShortcut - exact) > 1e-6);
    }

    @Test
    public void secondHitAverage_zeroMaxHitIsZero() {
        assertEquals(0.0, TwinflameSecondHit.secondHitAverage(0.9, 0), DELTA);
    }

    @Test
    public void cappedSecondHitAverage_capAtOrAboveMaxHitDelegatesToUncapped() {
        double hitChance = 0.7;
        int maxHit = 20;
        assertEquals(TwinflameSecondHit.secondHitAverage(hitChance, maxHit),
                TwinflameSecondHit.cappedSecondHitAverage(hitChance, maxHit, maxHit), DELTA);
        assertEquals(TwinflameSecondHit.secondHitAverage(hitChance, maxHit),
                TwinflameSecondHit.cappedSecondHitAverage(hitChance, maxHit, maxHit + 5), DELTA);
    }

    @Test
    public void cappedSecondHitAverage_handComputedExample() {
        // uncappedMaxHit=10, cap=4, hitChance=1.0. Raw rolls 0..10, each weight 1/11.
        // Landed damage: raw 0 -> 1; else raw. Visible first hit = min(landed, 4).
        // second hit = floor(0.4 * visibleFirst).
        // raw=0 -> landed=1 -> visible=1 -> second=0
        // raw=1 -> landed=1 -> visible=1 -> second=0
        // raw=2 -> landed=2 -> visible=2 -> second=0
        // raw=3 -> landed=3 -> visible=3 -> second=1 (floor(1.2)=1)
        // raw=4..10 (7 outcomes) -> landed>=4 -> visible=4 -> second=1 (floor(1.6)=1)
        // sum = 0+0+0+1+1*7 = 8; average = 8/11
        double expected = 8.0 / 11.0;
        double actual = TwinflameSecondHit.cappedSecondHitAverage(1.0, 10, 4);
        assertEquals(expected, actual, DELTA);
    }

    @Test
    public void cappedSecondHitAverage_capAtOrBelowZeroIsZero() {
        assertEquals(0.0, TwinflameSecondHit.cappedSecondHitAverage(0.8, 10, 0), DELTA);
    }

    // ---- Overkill (combined-hitsplat model) --------------------------------------------

    /**
     * Independent brute-force reference for {@link
     * TwinflameSecondHit#combinedExpectedOverkill}: a plain recursive
     * expectation over remaining hitpoints, built directly from the raw
     * 0..maxHit roll enumeration (same style as {@link
     * #bruteForceSecondHitAverage}) rather than reusing the production
     * recurrence's grouped probabilities.
     */
    private static double bruteForceCombinedOverkill(int maxHit, int targetHitpoints) {
        double[] over = new double[targetHitpoints + 1];
        int outcomes = maxHit + 1;
        for (int h = 1; h <= targetHitpoints; h++) {
            double sum = 0.0;
            for (int raw = 0; raw <= maxHit; raw++) {
                int landed = raw == 0 ? 1 : raw;
                int combined = landed + (int) Math.floor(landed * 0.4);
                sum += (combined >= h) ? (combined - h) : over[h - combined];
            }
            over[h] = sum / outcomes;
        }
        return over[targetHitpoints];
    }

    @Test
    public void combinedExpectedOverkill_matchesBruteForceEnumeration_smallScale() {
        int[] maxHits = {3, 5, 8, 12};
        int[] hitpoints = {1, 2, 3, 7, 15};
        for (int maxHit : maxHits) {
            for (int hp : hitpoints) {
                double expected = bruteForceCombinedOverkill(maxHit, hp);
                double actual = TwinflameSecondHit.combinedExpectedOverkill(maxHit, hp);
                assertEquals("maxHit=" + maxHit + " hp=" + hp, expected, actual, DELTA);
            }
        }
    }

    @Test
    public void combinedExpectedOverkill_zeroMaxHitOrZeroHpIsZero() {
        assertEquals(0.0, TwinflameSecondHit.combinedExpectedOverkill(0, 10), DELTA);
        assertEquals(0.0, TwinflameSecondHit.combinedExpectedOverkill(10, 0), DELTA);
    }

    @Test
    public void cappedCombinedExpectedOverkill_capAtOrAboveMaxHitDelegatesToUncapped() {
        int maxHit = 20;
        int hp = 50;
        assertEquals(TwinflameSecondHit.combinedExpectedOverkill(maxHit, hp),
                TwinflameSecondHit.cappedCombinedExpectedOverkill(maxHit, maxHit, hp), DELTA);
    }

    @Test
    public void cappedCombinedExpectedOverkill_isNoGreaterThanUncapped() {
        // Capping each hitsplat can only shrink or leave unchanged the damage dealt,
        // so overkill (damage wasted past the kill) can only shrink or stay the same too.
        int maxHit = 30;
        int hp = 40;
        double uncapped = TwinflameSecondHit.combinedExpectedOverkill(maxHit, hp);
        double capped = TwinflameSecondHit.cappedCombinedExpectedOverkill(maxHit, 10, hp);
        assertTrue(capped <= uncapped);
    }
}

package com.ospulse.combat;

import org.junit.Test;

import java.util.EnumSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Emberlight's +70% vs-demon accuracy/damage bonus: it must (1) raise max hit
 * to exactly floor(base * 17/10) and raise DPS against a demon, (2) do nothing
 * against a non-demon, and (3) STACK with the on-task slayer helm bonus as a
 * separate sequential floor step (unlike salve vs slayer, which are one
 * non-stacking slot).
 *
 * <p>⚠️ IN-GAME VERIFIED 2026-07-07: Emberlight + slayer + Piety + super combat
 * on Cerberus = 62 max hit (stacking). GearScape's 52 (highest-wins) is WRONG.
 * Do NOT flip these back to no-stack — this mechanic flip-flopped repeatedly and
 * the live-game reading is the tie-breaker.
 */
public class DemonbaneEffectTest {

    /** A representative max-melee STAB loadout; demonbaneWeapon set by the caller. */
    private static EquipmentStats gear(DemonbaneWeapon demonbane, SlayerHeadgear slayer) {
        return EquipmentStats.builder()
                .add(140, 0, 0, 0, 0, 0, 0, 0, 0, 0, 130, 0, 0.0, 0)
                .weaponSpeedTicks(4)
                .demonbaneWeapon(demonbane)
                .slayerHeadgear(slayer)
                .build();
    }

    private static PlayerCombat player(boolean onTask) {
        return PlayerCombat.builder()
                .attack(99, 99).strength(99, 99).defence(99, 99).ranged(99, 99).magic(99, 99)
                .prayer(99, 99).hitpoints(99, 99)
                .stance(Stance.AGGRESSIVE)
                .onSlayerTask(onTask)
                .build();
    }

    private static Monster monster(Set<MonsterAttribute> attributes) {
        return Monster.builder()
                .name("Test")
                .hitpoints(600)
                .defenceLevel(100)
                .defenceBonuses(50, 100, 25, 65, 100) // Cerberus-like
                .magicLevel(220)
                .attributes(attributes)
                .build();
    }

    private static DpsResult compute(EquipmentStats gear, PlayerCombat player, Monster target) {
        return DpsCalculator.compute(gear, player, CombatStyle.STAB, target, 20);
    }

    @Test
    public void emberlight_vsDemon_raisesMaxHitBySeventyPercentAndDps() {
        Monster demon = monster(EnumSet.of(MonsterAttribute.DEMON));
        DpsResult base = compute(gear(DemonbaneWeapon.NONE, SlayerHeadgear.NONE), player(false), demon);
        DpsResult ember = compute(gear(DemonbaneWeapon.EMBERLIGHT, SlayerHeadgear.NONE), player(false), demon);

        int expectedMaxHit = (int) new Fraction(17, 10).applyFloor(base.maxHit());
        assertEquals("max hit must be floor(base * 1.7) vs a demon", expectedMaxHit, ember.maxHit());
        assertTrue("demonbane must raise DPS vs a demon (" + ember.dps() + " vs " + base.dps() + ")",
                ember.dps() > base.dps());
    }

    @Test
    public void emberlight_vsNonDemon_hasNoEffect() {
        Monster notDemon = monster(EnumSet.noneOf(MonsterAttribute.class));
        DpsResult base = compute(gear(DemonbaneWeapon.NONE, SlayerHeadgear.NONE), player(false), notDemon);
        DpsResult ember = compute(gear(DemonbaneWeapon.EMBERLIGHT, SlayerHeadgear.NONE), player(false), notDemon);

        assertEquals("no demonbane bonus vs a non-demon", base.maxHit(), ember.maxHit());
        assertEquals("no demonbane bonus vs a non-demon", base.dps(), ember.dps(), 1e-9);
    }

    @Test
    public void emberlight_stacksWithSlayerHelm_sequentialFloorSteps() {
        Monster demon = monster(EnumSet.of(MonsterAttribute.DEMON));
        // Melee demonbane is the weapon's OWN passive, applied as a separate floor
        // step AFTER the salve/slayer target-bonus slot — it STACKS with the
        // on-task slayer helm: floor(floor(base * 7/6) * 17/10). IN-GAME VERIFIED
        // (Cerberus, Emberlight + slayer + Piety + super combat = 62); GearScape's
        // non-stacking 52 is wrong. DO NOT flip back to highest-wins.
        DpsResult noBonuses = compute(gear(DemonbaneWeapon.NONE, SlayerHeadgear.NONE), player(false), demon);
        DpsResult withSlayerToo = compute(gear(DemonbaneWeapon.EMBERLIGHT, SlayerHeadgear.STANDARD), player(true), demon);

        long slotStep = new Fraction(7, 6).applyFloor(noBonuses.maxHit());
        int expected = (int) new Fraction(17, 10).applyFloor(slotStep);
        assertEquals("slayer helm 7/6 then demonbane 17/10, each its own floor",
                expected, withSlayerToo.maxHit());

        DpsResult demonbaneOnly = compute(gear(DemonbaneWeapon.EMBERLIGHT, SlayerHeadgear.NONE), player(false), demon);
        assertTrue("adding the on-task helm must strictly raise DPS over demonbane alone",
                withSlayerToo.dps() > demonbaneOnly.dps());
    }

    @Test
    public void burningClaws_vsDemon_raisesMaxHitByFivePercentAndDps() {
        // Burning claws (item id 29577, cache-verified): melee (slash), +5%
        // accuracy AND damage vs demons -> Fraction(21, 20).
        Monster demon = monster(EnumSet.of(MonsterAttribute.DEMON));
        DpsResult base = compute(gear(DemonbaneWeapon.NONE, SlayerHeadgear.NONE), player(false), demon);
        DpsResult claws = compute(gear(DemonbaneWeapon.BURNING_CLAWS, SlayerHeadgear.NONE), player(false), demon);

        int expectedMaxHit = (int) new Fraction(21, 20).applyFloor(base.maxHit());
        assertEquals("max hit must be floor(base * 1.05) vs a demon", expectedMaxHit, claws.maxHit());
        assertTrue("Burning claws must raise DPS vs a demon (" + claws.dps() + " vs " + base.dps() + ")",
                claws.dps() > base.dps());
    }

    @Test
    public void burningClaws_vsNonDemon_hasNoEffect() {
        Monster notDemon = monster(EnumSet.noneOf(MonsterAttribute.class));
        DpsResult base = compute(gear(DemonbaneWeapon.NONE, SlayerHeadgear.NONE), player(false), notDemon);
        DpsResult claws = compute(gear(DemonbaneWeapon.BURNING_CLAWS, SlayerHeadgear.NONE), player(false), notDemon);

        assertEquals("no demonbane bonus vs a non-demon", base.maxHit(), claws.maxHit());
        assertEquals("no demonbane bonus vs a non-demon", base.dps(), claws.dps(), 1e-9);
    }

    @Test
    public void burningClaws_appliesOnAllMeleeStyles() {
        // The claws' style family marker is SLASH, but per the wired melee
        // demonbane rule (DemonbaneWeapon#appliesTo), the passive applies to
        // ALL melee styles (STAB/SLASH/CRUSH), matching the sword line.
        Monster demon = monster(EnumSet.of(MonsterAttribute.DEMON));
        assertTrue(DemonbaneWeapon.BURNING_CLAWS.appliesTo(CombatStyle.STAB));
        assertTrue(DemonbaneWeapon.BURNING_CLAWS.appliesTo(CombatStyle.SLASH));
        assertTrue(DemonbaneWeapon.BURNING_CLAWS.appliesTo(CombatStyle.CRUSH));
        assertTrue("sanity: gear still usable for a CRUSH-style calc",
                compute(gear(DemonbaneWeapon.BURNING_CLAWS, SlayerHeadgear.NONE), player(false), demon).maxHit() > 0);
    }

    @Test
    public void burningClaws_stacksWithSlayerHelm_sequentialFloorSteps() {
        Monster demon = monster(EnumSet.of(MonsterAttribute.DEMON));
        // Burning claws (+5%, 21/20) stacks as its own floor step on top of the
        // on-task slayer helm: floor(floor(base * 7/6) * 21/20).
        DpsResult noBonuses = compute(gear(DemonbaneWeapon.NONE, SlayerHeadgear.NONE), player(false), demon);
        DpsResult withSlayerToo = compute(gear(DemonbaneWeapon.BURNING_CLAWS, SlayerHeadgear.STANDARD), player(true), demon);

        long slotStep = new Fraction(7, 6).applyFloor(noBonuses.maxHit());
        int expected = (int) new Fraction(21, 20).applyFloor(slotStep);
        assertEquals("slayer helm 7/6 then demonbane 21/20, each its own floor",
                expected, withSlayerToo.maxHit());
    }
}

package com.ospulse.combat;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Covers {@link AmmoCompatibility}: the ammo-slot name classifier, the
 * weapon-side consumed-class resolution (incl. the data quirks: ballistae
 * are categorised "crossbow" but fire javelins; the crystal-bow family and
 * blowpipes use no worn ammo), and the contributes rule that keeps e.g.
 * javelin ranged strength from ever counting behind a bow. All ids verified
 * against the bundled equipment_index.min.json.
 */
public class AmmoCompatibilityTest {
    static { com.ospulse.combat.BundledGson.set(new com.google.gson.Gson()); }

    // Ammo-slot fixtures
    private static final int DRAGON_ARROW = 11212;
    private static final int RUNE_BRUTAL = 4803;
    private static final int RUNITE_BOLTS = 9144;
    private static final int DRAGON_JAVELIN = 19484;
    private static final int HARRALANDER_TAR = 10145;
    private static final int RADAS_BLESSING_4 = 22947;

    // Weapon-slot fixtures
    private static final int MAGIC_SHORTBOW = 861;
    private static final int RUNE_CROSSBOW = 9185;
    private static final int HEAVY_BALLISTA = 19481;
    private static final int LIGHT_BALLISTA = 19478;
    private static final int TOXIC_BLOWPIPE = 12926;
    private static final int CRYSTAL_BOW = 23983;
    private static final int BOW_OF_FAERDHINEN = 25865;
    private static final int CRAWS_BOW = 22550;
    private static final int WEBWEAVER_BOW = 27652;
    private static final int ECLIPSE_ATLATL = 29000;
    private static final int BLACK_SALAMANDER = 10148;
    private static final int RED_CHINCHOMPA = 10034;
    private static final int DRAGON_DART = 11230; // weapon-slot thrown, not ammo
    private static final int ABYSSAL_WHIP = 4151;
    private static final int SCORCHING_BOW = 29591;

    @Test
    public void classify_coversEveryAmmoClassByName() {
