			section.setBudgetTextForTest("0"); // owned-only, nothing else owned -> whip must stay
			section.runOptimizerSyncForTest();

			assertEquals(ABYSSAL_WHIP, weaponIdInResult(section.lastOptimizerResultForTest()));
			assertEquals(1, section.optimizerSwapRowCountForTest());
		});
	}

	// Imbued saradomin cape (deadman) 29617 -> credited plain 21791. A tradeable
	// cosmetic can be worth a DIFFERENT amount from its ordinary counterpart, and
	// the expensive-item cap prices the id the optimiser retains — the credited
	// plain one — while the panel tells the player to wear the deadman cape.
	private static final int SARADOMIN_CAPE_DEADMAN = 29617;
	private static final int SARADOMIN_CAPE_PLAIN = 21791;

	/**
	 * The expensive-item cap must charge for the item the player is actually
	 * told to RISK. Owning only the deadman cape credits the plain id at price
	 * 0 (`addVariantPlainForm`), and the optimiser keeps that plain id in the
	 * loadout — so `capRiskValueOf` looked it up and counted the ORDINARY
	 * cape's gp, not the cosmetic the display resolves to and the player will
	 * lose on death. With the user's threshold between the two values, a
	 * wilderness/PvP search silently breaks their own expensive-item limit.
	 *
	 * <p>Asserted on the composed risk source rather than through a full
	 * de-risk search, because that is the exact function the cap calls and it
	 * makes the failure unambiguous.
	 */
	@Test
	public void creditedPlainId_isRiskPricedAtTheHeldVariantsValue()
	{
		onEdt(() ->
		{
			java.util.Map<Integer, Long> riskValues = new java.util.HashMap<>();
			riskValues.put(SARADOMIN_CAPE_DEADMAN, 40_000_000L);
			riskValues.put(SARADOMIN_CAPE_PLAIN, 1_000L);

			List<ItemStack> holdings = new ArrayList<>();
			holdings.add(new ItemStack(SARADOMIN_CAPE_DEADMAN, "Imbued saradomin cape (deadman)", 1, 40_000_000L));
			WealthSnapshot wealth = WealthSnapshot.builder().topHoldings(holdings).build();

			GearSection section = new GearSection(NO_STORE, null, null, null, null,
				(ids, onResolved) -> onResolved.accept(new GearSection.PriceLookup(
					java.util.Map.of(), java.util.Set.of(), riskValues, java.util.Set.of())));
			section.apply(snapshotWith(gearFor(loadout(BRONZE_SWORD)), wealth));
			pickCerberus(section);
			section.setBudgetTextForTest("0");
			section.runOptimizerSyncForTest();

			GearOptimizer.PriceSource risk = section.lastRiskValueSourceForTest();
			assertTrue("the risk source must be wired when the resolver supplies risk data", risk != null);
			assertEquals("the credited plain cape must be risk-priced at the HELD deadman cape's value, "
					+ "not the ordinary cape's — the player risks what they actually wear",
				40_000_000L, risk.priceFor(SARADOMIN_CAPE_PLAIN));
			assertEquals("an id with no credit behind it still prices itself",
				40_000_000L, risk.priceFor(SARADOMIN_CAPE_DEADMAN));
		});
	}

	/**
	 * Companion to the test above, and the rule the credit map has to share
	 * with the display: an EXCLUDED variant is never reverse-resolved, so the
	 * panel and preview keep telling the player to use the plain item — and
	 * the cap must therefore price the plain item, the one actually equipped.
	 * Charging the excluded variant's risk enforces the limit against gear the
	 * player has told the panel not to use, rejecting a valid setup or waving
	 * through an over-threshold one depending on which side of the threshold
	 * the two values land.
	 */
	@Test
	public void excludedVariant_leavesTheCreditedPlainItemPricedAsItself()
	{
		onEdt(() ->
		{
			java.util.Map<Integer, Long> riskValues = new java.util.HashMap<>();
			riskValues.put(SARADOMIN_CAPE_DEADMAN, 40_000_000L);
			riskValues.put(SARADOMIN_CAPE_PLAIN, 1_000L);

			List<ItemStack> holdings = new ArrayList<>();
			holdings.add(new ItemStack(SARADOMIN_CAPE_DEADMAN, "Imbued saradomin cape (deadman)", 1, 40_000_000L));
			WealthSnapshot wealth = WealthSnapshot.builder().topHoldings(holdings).build();

			GearSection section = new GearSection(NO_STORE, null, null, null, null,
				(ids, onResolved) -> onResolved.accept(new GearSection.PriceLookup(
					java.util.Map.of(), java.util.Set.of(), riskValues, java.util.Set.of())));
			section.apply(snapshotWith(gearFor(loadout(BRONZE_SWORD)), wealth));
			pickCerberus(section);
			section.excludeItemFromSuggestionsForTest(SARADOMIN_CAPE_DEADMAN);
			section.setBudgetTextForTest("0");
			section.runOptimizerSyncForTest();

			GearOptimizer.PriceSource risk = section.lastRiskValueSourceForTest();
			assertTrue("the risk source must be wired when the resolver supplies risk data", risk != null);
			assertEquals("an excluded variant is never displayed, so its credit must not price the plain "
					+ "item the player will actually equip",
				1_000L, risk.priceFor(SARADOMIN_CAPE_PLAIN));
		});
	}

	/**
	 * The load-bearing layer of the same rule, one below the two tests above.
	 * The credit's justification is that the player effectively HAS the plain
	 * item because they hold the variant — so excluding the variant withdraws
	 * the backing and the credit must go with it. Otherwise the exclusion
	 * manufactures a free item out of nothing: the optimiser recommends the
	 * plain cape at zero spend when the bank contains no cape at all, and the
	 * highlighter points at an id that cannot be there.
	 *
	 * <p>Asserted on the ownership map itself, since that is where the credit
	 * is granted and every downstream surface reads it.
	 */
	@Test
	public void excludedVariant_grantsNoSyntheticOwnershipOfThePlainItem()
	{
		onEdt(() ->
		{
			List<ItemStack> holdings = new ArrayList<>();
			holdings.add(new ItemStack(SARADOMIN_CAPE_DEADMAN, "Imbued saradomin cape (deadman)", 1, 40_000_000L));
			WealthSnapshot wealth = WealthSnapshot.builder().topHoldings(holdings).build();

			GearSection section = new GearSection(NO_STORE, null, null);
			section.apply(snapshotWith(gearFor(loadout(BRONZE_SWORD)), wealth));
			pickCerberus(section);

			assertTrue("fixture sanity: the credit must exist BEFORE the exclusion, or the test proves "
					+ "nothing about withdrawing it",
				section.ownedPriceMapForTest().containsKey(SARADOMIN_CAPE_PLAIN));

			section.excludeItemFromSuggestionsForTest(SARADOMIN_CAPE_DEADMAN);

			assertTrue("excluding the only backing variant must withdraw the synthetic credit — the plain "
					+ "cape is in no bank and must not be free",
				!section.ownedPriceMapForTest().containsKey(SARADOMIN_CAPE_PLAIN));
			assertTrue("the excluded variant itself is still genuinely owned; exclusion means "
					+ "\"never suggest\", not \"pretend it is gone\"",
				section.ownedPriceMapForTest().containsKey(SARADOMIN_CAPE_DEADMAN));
		});
	}

	/**
	 * The wiring for {@link com.ospulse.ui.sections.gear.RiskCreditPolicy} —
	 * the policy's own guards are unit-tested, this proves it actually reaches
	 * the search. Holding only the deadman cape credits the plain id as owned
	 * and free, and the credit makes it inherit the variant's 40M risk; with a
	 * 10M threshold and no expensive items allowed, that single candidate is
	 * owned-but-over-cap and the optimiser can only drop the slot. Withdrawing
	 * the credit restores the alternative the budget can actually afford: buy
	 * an ordinary cape at 2M, risking 1M.
	 *
	 * <p>Uses a Wilderness target (Finding 2 fix): the credit-withdrawal check
	 * is now gated by {@code riskCapApplies()} exactly like {@code
	 * Request.expensiveItemThreshold} already was, so a non-Wilderness target
	 * (this test used Cerberus before the fix) leaves the credit alone
	 * regardless of the threshold/count fields — see {@link
	 * #nonWildernessTarget_withOverrideOff_leavesTheRiskCreditAlone} below,
	 * which covers that case with this test's exact fixture otherwise.
	 */
	@Test
	public void riskyHeldVariant_lettingTheOrdinaryCounterpartBeBoughtInstead()
	{
		onEdt(() ->
		{
			java.util.Map<Integer, Long> riskValues = new java.util.HashMap<>();
			riskValues.put(SARADOMIN_CAPE_DEADMAN, 40_000_000L);
			riskValues.put(SARADOMIN_CAPE_PLAIN, 1_000_000L);
			java.util.Map<Integer, Long> prices = new java.util.HashMap<>();
			prices.put(SARADOMIN_CAPE_PLAIN, 2_000_000L);

			List<ItemStack> holdings = new ArrayList<>();
			holdings.add(new ItemStack(SARADOMIN_CAPE_DEADMAN, "Imbued saradomin cape (deadman)", 1, 40_000_000L));
			WealthSnapshot wealth = WealthSnapshot.builder().topHoldings(holdings).build();

			GearSection section = new GearSection(NO_STORE, null, null, null, null,
				(ids, onResolved) -> onResolved.accept(new GearSection.PriceLookup(
					prices, java.util.Set.of(), riskValues, java.util.Set.of())));
			section.apply(snapshotWith(gearFor(loadout(BRONZE_SWORD)), wealth));
			pickChaosElemental(section); // Wilderness target -> riskCapApplies() is true
			section.setBudgetTextForTest("5M");
			section.setExpensiveThresholdTextForTest("10M");
			section.setExpensiveCountTextForTest("0");
			section.runOptimizerSyncForTest();

			GearOptimizer.PriceSource risk = section.lastRiskValueSourceForTest();
			assertTrue("the risk source must be wired", risk != null);
			assertEquals("with the credit withdrawn the counterpart prices itself again, or the cap would "
					+ "still see the variant's risk and the purchase would be pointless",
				1_000_000L, risk.priceFor(SARADOMIN_CAPE_PLAIN));
		});
	}

	/**
	 * Finding 2 (P2): {@code buildRequest} evaluated the credit-withdrawal
	 * check ({@code RiskCreditPolicy.withdrawnForSaferPurchase}) against the
	 * UNgated persisted threshold/count, while only {@code
	 * Request.expensiveItemThreshold} itself was gated by {@code
	 * riskCapApplies()}. So outside the Wilderness with the "Any target"
	 * override off — the exact fixture as {@link
	 * #riskyHeldVariant_lettingTheOrdinaryCounterpartBeBoughtInstead} above,
	 * same target (Cerberus), same threshold/count/budget — the credit was
	 * STILL withdrawn even though the cap the withdrawal exists to serve was
	 * never active for this search. The credit must survive: with the gate
	 * closed the cap behaves as threshold 0 ("disabled") everywhere it is
	 * consulted, not just on the Request's own field.
	 */
	@Test
	public void nonWildernessTarget_withOverrideOff_leavesTheRiskCreditAlone()
	{
		onEdt(() ->
		{
			java.util.Map<Integer, Long> riskValues = new java.util.HashMap<>();
			riskValues.put(SARADOMIN_CAPE_DEADMAN, 40_000_000L);
			riskValues.put(SARADOMIN_CAPE_PLAIN, 1_000_000L);
			java.util.Map<Integer, Long> prices = new java.util.HashMap<>();
			prices.put(SARADOMIN_CAPE_PLAIN, 2_000_000L);

			List<ItemStack> holdings = new ArrayList<>();
			holdings.add(new ItemStack(SARADOMIN_CAPE_DEADMAN, "Imbued saradomin cape (deadman)", 1, 40_000_000L));
			WealthSnapshot wealth = WealthSnapshot.builder().topHoldings(holdings).build();

			GearSection section = new GearSection(NO_STORE, null, null, null, null,
				(ids, onResolved) -> onResolved.accept(new GearSection.PriceLookup(
					prices, java.util.Set.of(), riskValues, java.util.Set.of())));
			section.apply(snapshotWith(gearFor(loadout(BRONZE_SWORD)), wealth));
			pickCerberus(section); // non-Wilderness, override left off -> riskCapApplies() is false
			section.setBudgetTextForTest("5M");
			section.setExpensiveThresholdTextForTest("10M");
			section.setExpensiveCountTextForTest("0");
			section.runOptimizerSyncForTest();

			assertFalse("fixture sanity: the gate must actually be closed for this scenario to test anything",
				section.riskCapAppliesForTest());

			GearOptimizer.PriceSource risk = section.lastRiskValueSourceForTest();
			assertTrue("the risk source must be wired", risk != null);
			assertEquals("outside the Wilderness with the override off the cap is inactive, so the credit "
					+ "must stand even though the threshold/count fields still describe an active-looking cap",
				40_000_000L, risk.priceFor(SARADOMIN_CAPE_PLAIN));
		});
	}

	/**
	 * The boundary where the optimiser's cap stops being able to bind at all:
	 * an allowance covering every one of the 11 SEARCHABLE slots. The credit
	 * must survive it, since withdrawing to satisfy a constraint that cannot
	 * bind would spend the player's budget on a plain copy for nothing.
	 *
	 * <p><b>What actually makes this pass today is the allowance guard</b>
	 * (11 &gt; 0), not the shared activation predicate — reverting
	 * {@code GearOptimizer.expensiveCapActive} back to a 14-equipment-slot
	 * lookalike leaves this green, and that is worth stating rather than
	 * implying the test proves more than it does. The shared predicate is
	 * kept because the two definitions genuinely disagree for an allowance of
	 * 11-13, so a duplicated copy would start lying the moment the allowance
	 * guard is ever loosened. One definition, in the class that owns the cap.
	 */
	@Test
	public void allowanceCoveringEverySearchableSlot_leavesTheCreditAlone()
	{
		onEdt(() ->
		{
			java.util.Map<Integer, Long> riskValues = new java.util.HashMap<>();
			riskValues.put(SARADOMIN_CAPE_DEADMAN, 40_000_000L);
			riskValues.put(SARADOMIN_CAPE_PLAIN, 1_000_000L);
			java.util.Map<Integer, Long> prices = new java.util.HashMap<>();
			prices.put(SARADOMIN_CAPE_PLAIN, 2_000_000L);

			List<ItemStack> holdings = new ArrayList<>();
			holdings.add(new ItemStack(SARADOMIN_CAPE_DEADMAN, "Imbued saradomin cape (deadman)", 1, 40_000_000L));
			WealthSnapshot wealth = WealthSnapshot.builder().topHoldings(holdings).build();

			GearSection section = new GearSection(NO_STORE, null, null, null, null,
				(ids, onResolved) -> onResolved.accept(new GearSection.PriceLookup(
					prices, java.util.Set.of(), riskValues, java.util.Set.of())));
			section.apply(snapshotWith(gearFor(loadout(BRONZE_SWORD)), wealth));
			pickCerberus(section);
			section.setBudgetTextForTest("5M");
			section.setExpensiveThresholdTextForTest("100k");
			// 11 == GearOptimizer.SEARCHABLE_SLOTS.length: the cap cannot bind.
			section.setExpensiveCountTextForTest("11");
			section.runOptimizerSyncForTest();

			assertEquals("with the cap unable to bind, the credit must stand — the plain id still reports "
					+ "the held variant's risk because it is still credited, not bought",
				40_000_000L, section.lastRiskValueSourceForTest().priceFor(SARADOMIN_CAPE_PLAIN));
		});
	}
}

package com.ospulse.ui.sections;

import com.ospulse.session.SessionSnapshot;
import com.ospulse.ui.CollapsibleSection;

import net.runelite.api.Client;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayManager;

import org.junit.Before;
import org.junit.Test;

import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;

/**
 * Regression coverage for the "Net worth change" reset/toggle interaction:
 * each of the four components (Profit, GE flip, GE positions, Bank) must
 * rebase independently, so resetting the row and then flipping a component's
 * include/exclude toggle (in either order) never produces a phantom jump.
 *
 * <p>Before the fix, {@code resetState}/reset captured ONE aggregate baseline
 * (the raw total at reset time, with whatever components happened to be
 * toggled on then already baked in) and the displayed total was {@code
 * (rawTotal - excludedComponents) - aggregateBaseline}. Subtracting a
 * toggle-filtered total from a baseline captured under a DIFFERENT toggle
 * configuration jumps by exactly the flipped component's value the moment a
 * toggle changes after a reset (or the moment a reset happens while a
 * component is already excluded).
 */
public class SessionSectionTest
{
	private CollapsibleSection.CollapseStore store;
	private SessionSection section;

	@Before
	public void setUp()
	{
		store = new CollapsibleSection.CollapseStore()
		{
			@Override
			public boolean isCollapsed(String key)
			{
				return false;
			}

			@Override
			public void setCollapsed(String key, boolean collapsed)
			{
			}
		};
		Plugin plugin = mock(Plugin.class);
		Client client = mock(Client.class);
		OverlayManager overlayManager = mock(OverlayManager.class);
		section = new SessionSection(store, plugin, client, overlayManager);
	}

	/** Category id for the "Net worth change" row's right-click reset menu. */
	private static final String CAT_NET_WORTH_DELTA = "session:netWorthDelta";

	private static SessionSnapshot snapshotWith(long netProfit, long geRealizedPnl,
		long gePositions, long bankDelta)
	{
		return new SessionSnapshot(
			0L, 1000L, netProfit, 0L, geRealizedPnl, netProfit + geRealizedPnl + gePositions + bankDelta,
			true, Collections.emptyList(), Collections.emptyMap(), 0L, null,
			Collections.emptyList(), Collections.emptyList(),
			Collections.emptyList(), 0L, null, 0L, Collections.emptyList(), 0L,
			gePositions, bankDelta);
	}

	@Test
	public void resetThenTogglingGePositionsOffStaysRebasedAtZero()
	{
		// Profit 0, GE flip 0, GE positions +80k (toggle ON, default), Bank 0.
		section.apply(snapshotWith(0L, 0L, 80_000L, 0L));
		assertEquals(80_000L, section.netWorthChangeForTest());

		// Reset the row: with nothing else changing, it must read 0 right after.
		section.resetCategoryForTest(CAT_NET_WORTH_DELTA);
		section.apply(snapshotWith(0L, 0L, 80_000L, 0L));
		assertEquals(0L, section.netWorthChangeForTest());

		// Untick GE positions: the bug subtracted the full 80k from a baseline
		// that already had the 80k baked in, jumping to -80k. It must instead
		// stay at 0 (GE positions' own contribution, raw - itsBaseline, is
		// removed from the total entirely, not double-subtracted).
		section.setGePositionsToggleForTest(false);
		assertEquals("unticking a component right after reset must not jump the total",
			0L, section.netWorthChangeForTest());

		// Re-tick it: back to 0 as well (nothing changed since reset).
		section.setGePositionsToggleForTest(true);
		assertEquals(0L, section.netWorthChangeForTest());
	}

	@Test
	public void togglingBankOffThenResetStaysRebasedAtZeroWhenToggledBackOn()
	{
		// Profit 0, GE flip 0, GE positions 0, Bank +50k.
		section.apply(snapshotWith(0L, 0L, 0L, 50_000L));

		// Untick Bank BEFORE resetting: the displayed total (Profit+GEflip
		// only, Bank excluded) is 0 even though Bank's raw value is +50k.
		section.setBankToggleForTest(false);
		assertEquals(0L, section.netWorthChangeForTest());

		// Reset while Bank is toggled off.
		section.resetCategoryForTest(CAT_NET_WORTH_DELTA);
		section.apply(snapshotWith(0L, 0L, 0L, 50_000L));
		assertEquals(0L, section.netWorthChangeForTest());

		// Re-tick Bank: its own baseline was captured at reset time (50k)
		// regardless of it being excluded then, so it must also read 0 now
		// (raw 50k - baseline 50k), not jump by the full 50k.
		section.setBankToggleForTest(true);
		assertEquals("re-including a component that was excluded at reset time "
				+ "must not jump the total",
			0L, section.netWorthChangeForTest());
	}

	@Test
	public void componentsMoveAfterResetShowOnlyTheDelta()
	{
		section.apply(snapshotWith(0L, 0L, 80_000L, 50_000L));
		section.resetCategoryForTest(CAT_NET_WORTH_DELTA);
		section.apply(snapshotWith(0L, 0L, 80_000L, 50_000L));
		assertEquals(0L, section.netWorthChangeForTest());

		// GE positions rises by 20k, Bank rises by 10k after the reset.
		section.apply(snapshotWith(0L, 0L, 100_000L, 60_000L));
		assertEquals(30_000L, section.netWorthChangeForTest());

		// Toggling Bank off afterwards removes only Bank's OWN delta (10k),
		// leaving GE positions' 20k delta intact.
		section.setBankToggleForTest(false);
		assertEquals(20_000L, section.netWorthChangeForTest());
	}
}

package com.ospulse.ui.sections;

import com.ospulse.combat.CombatStyle;
import com.ospulse.combat.EquipmentStats;
import com.ospulse.combat.optimizer.GearOptimizer;
import com.ospulse.combat.optimizer.LoadoutOverride;
import com.ospulse.combat.optimizer.WhatIfLoadout;
import com.ospulse.model.ItemStack;
import com.ospulse.session.GearSnapshot;
import com.ospulse.session.SessionSnapshot;
import com.ospulse.ui.CollapsibleSection;
import com.ospulse.wealth.WealthSnapshot;

import org.junit.Test;

import javax.swing.ListModel;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Items #6e/#6g: the Best-setup optimiser's 5-way damage-type selector.
 * <ul>
 *   <li>it DEFAULTS to the equipped weapon's current combat style (a bow
 *       detects Ranged, never an implicit melee search — the #6g bug);</li>
 *   <li>a user pick overrides detection until the weapon changes;</li>
 *   <li>the search is genuinely constrained (result weapon/style match);</li>
 *   <li>"Preview these swaps" locks the readout to the optimised style;</li>
 *   <li>not-owned suggestions render a gp price label (owned ones don't);</li>
 *   <li>the worn-grid tooltip says preview/not-owned over preview content
 *       (#6f second site) and live otherwise.</li>
 * </ul>
 */
public class GearSectionOptimizerStyleTest
{
	static { com.ospulse.combat.BundledGson.set(new com.google.gson.Gson()); }
	private static void onEdt(Runnable body)
	{
		try
		{
			SwingUtilities.invokeAndWait(body);
		}
		catch (InvocationTargetException e)
		{
			Throwable cause = e.getCause();
			if (cause instanceof Error)
			{
				throw (Error) cause;
			}
			if (cause instanceof RuntimeException)
			{
				throw (RuntimeException) cause;
			}
			throw new RuntimeException(cause);
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
			throw new RuntimeException(e);
		}
	}

	private static final CollapsibleSection.CollapseStore NO_STORE = new CollapsibleSection.CollapseStore()
	{
		@Override
		public boolean isCollapsed(String key)
		{
			return false;
		}

		@Override
		public void setCollapsed(String key, boolean collapsed)
		{
		}
	};

	private static final int BRONZE_SWORD = 1277;
	private static final int DRAGON_SCIMITAR = 4587;
	private static final int ABYSSAL_WHIP = 4151;
	private static final int ABYSSAL_BLUDGEON = 13263;
	private static final int MAGIC_SHORTBOW = 861;
	private static final int RADAS_BLESSING_4 = 22947; // ammo slot, no ranged strength but +2 prayer
	private static final int MASORI_MASK = 27226;       // plain base form the optimiser's ownership map aliases to
	private static final int MASORI_MASK_F = 27235;     // the actual owned fortified variant

	// P1 (issue #11 Stage 3 follow-up): self-cast magic weapon (no spellbook/rune
	// plumbing needed, mirrors GearOptimizerOwnedDeadmanCapeTest's fixture) plus the
	// Deadman-mode Imbued saradomin cape — mode-locked (GearSection.isModeLockedItem),
	// so restrictedItemIds() always excludes it, yet its ownership legitimately
	// credits the real, non-mode-locked "Imbued saradomin cape" via OwnedVariantResolver.
	private static final int TRIDENT_OF_THE_SEAS = 11905;
	private static final int IMBUED_SARADOMIN_CAPE_DEADMAN = 29617;
	/**
	 * The ordinary counterpart 29617's ownership credits — the magic-75-gated
	 * id, not the ungated same-named duplicate 24248 (see
	 * {@code OwnedVariantResolver.resolveByStatMatch}).
	 */
	private static final int IMBUED_SARADOMIN_CAPE_PLAIN = 21791;
	private static final int CAPE_SLOT = 1;

	private static int[] loadout(int weaponId)
	{
		int[] ids = new int[GearSnapshot.EQUIPMENT_SLOT_COUNT];
		Arrays.fill(ids, -1);
		ids[3] = weaponId;
		return ids;
	}

	private static GearSnapshot gearFor(int[] itemIds)
	{
		EquipmentStats stats = WhatIfLoadout.buildEquipmentStats(itemIds, LoadoutOverride.empty());
		return GearSnapshot.builder()
			.equippedItemIds(itemIds)
			.attack(99, 99)
			.strength(99, 99)
			.defence(99, 99)
			.ranged(99, 99)
			.magic(99, 99)
			.prayer(77, 77)
			.hitpoints(99, 99)
			.equipmentStats(stats)
			.build();
	}

	private static SessionSnapshot snapshotWith(GearSnapshot gear, WealthSnapshot wealth)
	{
		return new SessionSnapshot(0L, 0L, 0L, 0L, 0L, 0L, false,
			null, null, 0L, wealth, null, null, null, 0L, gear, 0L, null, 0L);
	}

	private static WealthSnapshot wealthWith(int... itemIds)
	{
		List<ItemStack> holdings = new ArrayList<>();
		for (int id : itemIds)
		{
			holdings.add(new ItemStack(id, "item " + id, 1, 100_000L));
		}
		return WealthSnapshot.builder().topHoldings(holdings).build();
	}

	private static int indexOf(ListModel<String> model, String name)
	{
		for (int i = 0; i < model.getSize(); i++)
		{
			if (model.getElementAt(i).equals(name))
			{
				return i;
			}
		}
		return -1;
	}

	private static void pickCerberus(GearSection section)
	{
		section.searchFieldForTest().setText("cerberus");
		int index = indexOf(section.monsterListForTest().getModel(), "Cerberus");
		assertTrue("Cerberus must appear in the filtered list", index >= 0);
		section.monsterListForTest().setSelectedIndex(index);
	}

	private static int weaponIdInResult(GearOptimizer.Result result)
	{
		for (GearOptimizer.SlotChoice choice : result.loadout())
		{
			if (choice.slotOrdinal() == WhatIfLoadout.WEAPON_SLOT)
			{
				return choice.itemId();
			}
		}
		return -1;
	}

