import com.ospulse.wealth.WealthSnapshot;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.anyMap;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.reset;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Guards the once-per-tick economic-commit discipline: eager container/loot
 * events must NOT advance the engine baseline or drain movement signals — only
 * the authoritative per-tick {@link SessionTracker#onTick()} commits.
 *
 * <p>Without this, a single game tick whose inventory effects span several
 * {@code ItemContainerChanged} events — die-then-reclaim, search-all bird nests,
 * drop/destroy spanning ticks — fragments into several mis-attributed
 * transactions: the {@code died} signal drains on the first event and the
 * baseline snaps forward, so reclaimed gear books as fresh loot (the live
 * phantom-53.9M-profit-on-death report) and follow-up nest searches are lost.
 */
public class SessionTrackerTest
{
	static { com.ospulse.combat.BundledGson.set(new com.google.gson.Gson()); }

	/** Bird nest contents — the auto-search case that fires no LootReceived. */
	private static final int SNAPDRAGON_SEED_ID = 5300;
	private static final long SNAPDRAGON_SEED_UNIT = 40_000L;
	/** An ordinary NPC drop, which RuneLite's Loot Tracker does report. */
	private static final int BONES_ID = 526;
	private static final long BONES_UNIT = 100L;

	private Client client;
	private ItemManager itemManager;
	private SessionEngine engine;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		itemManager = mock(ItemManager.class);
		OSPulseConfig config = mock(OSPulseConfig.class);
		ConfigManager configManager = mock(ConfigManager.class);
		engine = spy(new SessionEngine());

		when(client.getItemContainer(any())).thenReturn(null);
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[0]);
		when(config.verboseDiagnostics()).thenReturn(false);
		when(config.includeFishBarrel()).thenReturn(false);
		when(config.includePouches()).thenReturn(false);

		tracker = new SessionTracker(client, itemManager, config, configManager, new Gson(), engine);
		tracker.onLogin();
		tracker.onTick();   // first tick bootstraps the session (engine.startSession), then returns
		reset(engine);      // ignore bootstrap interactions; assert only on post-bootstrap events
	}

	/**
	 * Teaches the mocked {@link ItemManager} about one item so the tracker's
	 * valuation can canonicalize, name and price it — the path
	 * {@link SessionTracker#onLootReceived} takes to build both the feed row and
	 * the {@code LootReceipt} the diff correlation matches against.
	 */
	private void priceItem(int itemId, String name, int unitValue)
	{
		ItemComposition comp = mock(ItemComposition.class);
		when(comp.isTradeable()).thenReturn(true);
		when(comp.getName()).thenReturn(name);
		when(comp.getHaPrice()).thenReturn(0);
		when(itemManager.canonicalize(itemId)).thenReturn(itemId);
		when(itemManager.getItemComposition(itemId)).thenReturn(comp);
		when(itemManager.getItemPrice(itemId)).thenReturn(unitValue);
	}

	/** The published feed's group for {@code source}, or null when absent. */
	private SourceLoot sourceNamed(String source)
	{
		for (SourceLoot s : tracker.getLatest().getLootSources())
		{
			if (s.getSource().equals(source))
			{
				return s;
			}
		}
		return null;
	}

	/**
	 * Stubs the engine's per-update residue accessor so a tick observes exactly
	 * these unexplained inventory appearances. Successive lists are returned on
	 * successive ticks, mirroring the engine clearing the residue each update.
	 */
	private void engineReportsDiffLoot(List<DiffLoot> first, Object... rest)
	{
		doReturn(first, rest).when(engine).lastUpdateDiffLoot();
	}

	/**
	 * THE CORE REGRESSION (bird nests searched by an auto mechanism): the wealth
	 * appears in the inventory but RuneLite's Loot Tracker never fires, so no
	 * {@code LootReceived} and no receipt exists. The engine's own diff already
	 * books it as LOOT; the feed must show it too, under a stable constant key.
	 */
	@Test
	public void unattributedInventoryAppearLandsInTheFeedUnderTheUnattributedSource()
	{
		engineReportsDiffLoot(Collections.singletonList(
			new DiffLoot(SNAPDRAGON_SEED_ID, "Snapdragon seed", 1L, SNAPDRAGON_SEED_UNIT)));

		tracker.onTick();

		SourceLoot s = sourceNamed(SessionTracker.UNATTRIBUTED_LOOT_SOURCE);
		assertNotNull("an inventory appear with no LootReceived must reach the feed", s);
		assertEquals(SNAPDRAGON_SEED_UNIT, s.getTotalValue());
		assertEquals(1, s.getItems().size());
		assertEquals("Snapdragon seed", s.getItems().get(0).getName());
		assertEquals(1L, s.getItems().get(0).getQuantity());
		assertNull("it must not be conflated with RuneLite's empty-source Unknown",
			sourceNamed(SessionTracker.UNKNOWN_LOOT_SOURCE));
	}

	/**
	 * THE CRITICAL RISK. A normal kill is seen TWICE: once as a {@code
	 * LootReceived} (which books the feed row) and once as the same tick's
	 * inventory appear (which the engine books as LOOT). The diff residue must be
	 * netted against the tick's receipts or every kill double-counts in the feed.
	 */
	@Test
	public void aKillWithAMatchingLootReceivedIsAttributedToTheNpcExactlyOnce()
	{
		priceItem(BONES_ID, "Bones", (int) BONES_UNIT);
		// Same tick: the drop event, then the inventory diff that carries it.
		tracker.onLootReceived("Goblin", 1, Collections.singletonList(
			new net.runelite.client.game.ItemStack(BONES_ID, 3)));
		engineReportsDiffLoot(Collections.singletonList(
			new DiffLoot(BONES_ID, "Bones", 3L, BONES_UNIT)));

		tracker.onTick();

		SourceLoot goblin = sourceNamed("Goblin");
		assertNotNull("the receipt still books the kill under its NPC source", goblin);
		assertEquals("the kill is worth 3 bones, NOT 6 — the diff must not re-book it",
			3 * BONES_UNIT, goblin.getTotalValue());
		assertEquals(3L, goblin.getItems().get(0).getQuantity());
		assertNull("the matched appear must not also land under the unattributed key",
			sourceNamed(SessionTracker.UNATTRIBUTED_LOOT_SOURCE));
	}

	/**
	 * Undercount guard: several unattributed appears in a row (nest after nest)
	 * must each register. They aggregate under the one stable key — a per-tick
	 * key would break the panel's persisted collapse/hide identity — but their
	 * quantities must accumulate, never collapse onto the last one seen.
	 */
	@Test
	public void rapidUnattributedAppearsEachRegisterInsteadOfCollapsing()
	{
		engineReportsDiffLoot(
			Collections.singletonList(new DiffLoot(SNAPDRAGON_SEED_ID, "Snapdragon seed", 1L, SNAPDRAGON_SEED_UNIT)),
			Collections.singletonList(new DiffLoot(SNAPDRAGON_SEED_ID, "Snapdragon seed", 2L, SNAPDRAGON_SEED_UNIT)),
			Collections.singletonList(new DiffLoot(SNAPDRAGON_SEED_ID, "Snapdragon seed", 1L, SNAPDRAGON_SEED_UNIT)));

		tracker.onTick();
		tracker.onTick();
		tracker.onTick();

		SourceLoot s = sourceNamed(SessionTracker.UNATTRIBUTED_LOOT_SOURCE);
		assertNotNull(s);
		assertEquals("all four seeds accumulate", 4L, s.getItems().get(0).getQuantity());
		assertEquals(4 * SNAPDRAGON_SEED_UNIT, s.getTotalValue());
		assertEquals("each search counts as its own drop", 3L, s.getCount());
	}

	/**
	 * Existing behaviour preserved: a {@code LootReceived} carrying a source still
	 * aggregates exactly as it does today, with no engine diff residue involved.
	 */
	@Test
	public void lootReceivedWithASourceStillAggregatesAsBefore()
	{
		priceItem(BONES_ID, "Bones", (int) BONES_UNIT);
		engineReportsDiffLoot(Collections.<DiffLoot>emptyList());

		tracker.onLootReceived("Goblin", 1, Collections.singletonList(
			new net.runelite.client.game.ItemStack(BONES_ID, 2)));
		tracker.onLootReceived("Goblin", 1, Collections.singletonList(
			new net.runelite.client.game.ItemStack(BONES_ID, 5)));
		tracker.onTick();

		SourceLoot goblin = sourceNamed("Goblin");
		assertNotNull(goblin);
		assertEquals(7L, goblin.getItems().get(0).getQuantity());
		assertEquals(7 * BONES_UNIT, goblin.getTotalValue());
		assertEquals("two kills", 2L, goblin.getCount());
	}

	/**
	 * A tick whose diff carries MORE than the receipt reported (a kill and an
	 * auto-search of the same id landing together) nets the receipt out and books
	 * only the genuine remainder — the netting is per-quantity, not all-or-nothing
	 * on an exact tuple match, so neither side double-counts nor disappears.
	 */
	@Test
	public void anAppearLargerThanItsReceiptBooksOnlyTheUnreceiptedRemainder()
	{
		priceItem(BONES_ID, "Bones", (int) BONES_UNIT);
		tracker.onLootReceived("Goblin", 1, Collections.singletonList(
			new net.runelite.client.game.ItemStack(BONES_ID, 2)));
		engineReportsDiffLoot(Collections.singletonList(
			new DiffLoot(BONES_ID, "Bones", 5L, BONES_UNIT)));

		tracker.onTick();

		assertEquals("the receipted 2 stay with the NPC",
			2 * BONES_UNIT, sourceNamed("Goblin").getTotalValue());
		SourceLoot un = sourceNamed(SessionTracker.UNATTRIBUTED_LOOT_SOURCE);
		assertNotNull("the unreceipted 3 are still real wealth and must be shown", un);
		assertEquals(3L, un.getItems().get(0).getQuantity());
	}

	/**
	 * Bot-review finding (P1): RuneLite's {@code LootReceived} for an ordinary
	 * ground drop fires when the NPC dies (the drop appears), while the
	 * inventory diff is only observed on whatever later tick the player
	 * actually walks over and picks it up — the two events are NOT guaranteed
	 * to land on the same tick the way {@link
	 * #aKillWithAMatchingLootReceivedIsAttributedToTheNpcExactlyOnce} assumes.
	 * The per-tick netting map in {@link SessionTracker#attributeDiffLoot} is
	 * rebuilt fresh from each tick's own {@code MovementSignals}, so a receipt
	 * booked on tick 1 cannot net against a diff that only appears on tick 2 —
	 * the delayed pickup would double-count as {@code Inventory (unattributed)}
	 * on top of the row {@code onLootReceived} already booked under the NPC.
	 */
	@Test
	public void aDelayedPickupOfAnEarlierGroundDropDoesNotDoubleCountItInTheFeed()
	{
		priceItem(BONES_ID, "Bones", (int) BONES_UNIT);

		// Tick 1: the NPC dies and LootReceived fires immediately — nothing has
		// reached the inventory yet, so this tick's diff is empty.
		tracker.onLootReceived("Goblin", 1, Collections.singletonList(
			new net.runelite.client.game.ItemStack(BONES_ID, 3)));
		engineReportsDiffLoot(Collections.<DiffLoot>emptyList());
		tracker.onTick();

		// Tick 2 (several ticks later in the real client): the player walks
		// over and picks up the same drop. No LootReceived fires this tick.
		engineReportsDiffLoot(Collections.singletonList(
			new DiffLoot(BONES_ID, "Bones", 3L, BONES_UNIT)));
		tracker.onTick();

		SourceLoot goblin = sourceNamed("Goblin");
		assertNotNull(goblin);
		assertEquals("the kill is still worth exactly 3 bones, not 6",
			3 * BONES_UNIT, goblin.getTotalValue());
		assertNull("the delayed pickup of the SAME drop must not also land as unattributed",
			sourceNamed(SessionTracker.UNATTRIBUTED_LOOT_SOURCE));
	}

	/**
	 * Round-2 bot-review Finding A: {@code outstandingReceipts} is the FIFO
	 * pool {@link #aDelayedPickupOfAnEarlierGroundDropDoesNotDoubleCountItInTheFeed}
	 * relies on to net a delayed pickup against the receipt booked several
	 * ticks earlier — but {@link SessionTracker#resetSession()} clears {@code
	 * lootBySource} (so the NPC's feed row is gone) without also clearing
	 * {@code outstandingReceipts}. If the receipt is still pending when the
	 * player hits the panel's reset button, the delayed pickup that lands in
	 * the FRESH session nets against the stale entry and is silently
	 * swallowed — the fresh session's loot feed never shows it at all.
	 */
	@Test
	public void resetSessionClearsOutstandingReceiptsSoAPostResetPickupIsNotSwallowed()
	{
		priceItem(BONES_ID, "Bones", (int) BONES_UNIT);

		// Tick 1: the kill's LootReceived fires but the pickup hasn't landed
		// yet — the receipt is parked in outstandingReceipts, still unmatched.
		tracker.onLootReceived("Goblin", 1, Collections.singletonList(
			new net.runelite.client.game.ItemStack(BONES_ID, 3)));
		engineReportsDiffLoot(Collections.<DiffLoot>emptyList());
		tracker.onTick();

		// The player resets the session (panel button) before the pickup lands.
		tracker.resetSession();

		// Now, in the FRESH session, the delayed pickup finally lands.
		engineReportsDiffLoot(Collections.singletonList(
			new DiffLoot(BONES_ID, "Bones", 3L, BONES_UNIT)));
		tracker.onTick();

		SourceLoot un = sourceNamed(SessionTracker.UNATTRIBUTED_LOOT_SOURCE);
		assertNotNull("the fresh session must see this pickup as real loot, not silently "
			+ "swallow it against a stale pre-reset receipt", un);
		assertEquals(3L, un.getItems().get(0).getQuantity());
		assertNull("the pre-reset NPC's row must not reappear either — it was cleared",
			sourceNamed("Goblin"));
	}

	/**
	 * Same finding, the other clearing site: {@link
	 * SessionTracker#bootstrapSession} (a genuine login after logout) also
	 * clears {@code lootBySource} without clearing {@code outstandingReceipts}.
	 */
	@Test
	public void reloginClearsOutstandingReceiptsSoAPostLoginPickupIsNotSwallowed()
	{
		priceItem(BONES_ID, "Bones", (int) BONES_UNIT);

		tracker.onLootReceived("Goblin", 1, Collections.singletonList(
			new net.runelite.client.game.ItemStack(BONES_ID, 3)));
		engineReportsDiffLoot(Collections.<DiffLoot>emptyList());
		tracker.onTick();

		// The player logs out and back in before the pickup lands.
		tracker.onLogout();
		tracker.onLogin();
		tracker.onTick(); // bootstraps the fresh session

		// The delayed pickup lands after the relogin.
		engineReportsDiffLoot(Collections.singletonList(
			new DiffLoot(BONES_ID, "Bones", 3L, BONES_UNIT)));
		tracker.onTick();

		SourceLoot un = sourceNamed(SessionTracker.UNATTRIBUTED_LOOT_SOURCE);
		assertNotNull("the fresh post-login session must see this pickup as real loot, "
			+ "not silently swallow it against a stale pre-login receipt", un);
		assertEquals(3L, un.getItems().get(0).getQuantity());
	}

	/**
	 * A BANK-id container change drives the eager refresh path without involving
	 * the fish-barrel inventory/equipment diff (which only handles INVENTORY /
	 * EQUIPMENT ids).
	 */
	private void eagerContainerEvent()
	{
		tracker.onItemContainerChanged(InventoryID.BANK.getId(), null);
	}

	@Test
	public void eagerContainerEventsDoNotCommitAnEconomicTransaction()
	{
		eagerContainerEvent();
		eagerContainerEvent();
		verify(engine, never()).update(any(WealthSnapshot.class), any(GeAttributions.class),
			any(MovementSignals.class), anyLong());
	}

	@Test
	public void diedSignalSurvivesMultipleEagerEventsUntilTheTickCommit()
	{
		// A death whose inventory + equipment clears arrive as several container
		// events within one tick, with the death recorded once.
		eagerContainerEvent();
		tracker.recordDeath();
		eagerContainerEvent();
		eagerContainerEvent();

		// The eager events must not have drained `died` nor advanced the baseline.
		verify(engine, never()).update(any(WealthSnapshot.class), any(GeAttributions.class),
			any(MovementSignals.class), anyLong());

		tracker.onTick();

		ArgumentCaptor<MovementSignals> signals = ArgumentCaptor.forClass(MovementSignals.class);
		verify(engine, times(1)).update(any(WealthSnapshot.class), any(GeAttributions.class),
			signals.capture(), anyLong());
		assertTrue("death survives the eager container events and commits exactly once on the tick",
			signals.getValue().diedThisTick());
	}

	/**
	 * Review finding 5: eager (non-commit) events must call {@link
	 * SessionEngine#snapshot} with {@code commit == false} — a read-only
	 * preview — so the engine's bookkeeping (start net worth / baseline /
	 * stale-bank-drop tracking) only ever advances on the tick's one
	 * authoritative {@code commit == true} call. Before the fix, {@code
	 * snapshot} had no {@code commit} parameter at all and unconditionally
	 * folded/reconciled/synced on every call, preview or not.
	 */
	@Test
	public void eagerContainerEventsPreviewSnapshotOnly_tickCommitsTheSnapshot()
	{
		eagerContainerEvent();
		eagerContainerEvent();

		verify(engine, times(2)).snapshot(any(WealthSnapshot.class), anyLong(),
			anyList(), anyList(), anyMap(), anyLong(), anyLong(), eq(false));
		verify(engine, never()).snapshot(any(WealthSnapshot.class), anyLong(),
			anyList(), anyList(), anyMap(), anyLong(), anyLong(), eq(true));

		tracker.onTick();

		verify(engine, times(1)).snapshot(any(WealthSnapshot.class), anyLong(),
			anyList(), anyList(), anyMap(), anyLong(), anyLong(), eq(true));
	}

	/**
	 * Regression: {@link SessionTracker#buildSnapshot} used to re-wrap the
	 * engine's {@link SessionSnapshot} through the backward-compatible
	 * constructor overload that defaults GE positions / Bank to {@code 0L},
	 * silently stripping the engine-computed values before
	 * {@code SessionSection} could ever read {@code getGePositions()} /
	 * {@code getBankDelta()} — the session panel's GE positions and Bank rows
	 * (and their toggles) showed 0 in the live game even though the engine
	 * unit tests, which call {@link SessionEngine#snapshot} directly and
	 * never touch this wrapping seam, kept passing. Proven here by stubbing
	 * the engine's tick-commit snapshot with known nonzero values and
	 * asserting the tracker's published snapshot still carries them.
	 */
	@Test
	public void tickCommitPreservesGePositionsAndBankFromTheEngineSnapshot()
	{
		SessionSnapshot canned = new SessionSnapshot(
			0L, 1000L, 0L, 0L, 0L, 130_000L, true,
			java.util.Collections.emptyList(), java.util.Collections.emptyMap(), 0L,
			WealthSnapshot.builder().build(),
			java.util.Collections.emptyList(), java.util.Collections.emptyList(),
			java.util.Collections.emptyList(), 0L, null, 0L,
			java.util.Collections.emptyList(), 0L,
			80_000L, 50_000L);
		// doReturn/when (not when/thenReturn) — engine is a spy, and
		// when(engine.snapshot(...)) would execute the REAL method with the
		// raw matcher placeholders as arguments before Mockito can register
		// the stub, throwing inside the real implementation.
		doReturn(canned).when(engine).snapshot(any(WealthSnapshot.class), anyLong(),
			anyList(), anyList(), anyMap(), anyLong(), anyLong(), eq(true));

		tracker.onTick();

		SessionSnapshot published = tracker.getLatest();
		assertEquals("GE positions must survive SessionTracker's snapshot wrapping",
			80_000L, published.getGePositions());
		assertEquals("Bank must survive SessionTracker's snapshot wrapping",
			50_000L, published.getBankDelta());
		assertEquals("Net worth change must survive the wrapping too",
			130_000L, published.getNetWorthDelta());
	}
}

package com.ospulse.integration;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class GeValuationTest
{
	// ------------------------------------------------------------------- buy

	@Test
	public void buyOfferValueIsFullEscrowWhenNothingBought()
	{
		// 10 @ 1m offered, none bought yet -> all 10m still escrowed.
		assertEquals(10_000_000L, GeValuation.buyOfferValue(1_000_000L, 10L, 0L));
	}

	@Test
	public void buyOfferValueCountsOnlyTheUnboughtEscrow()
	{
		// 10 @ 1m, 4 bought so far -> only the 6 not-yet-bought are still
		// escrowed (6m). The 4 bought are collectable and must NOT be counted,
		// otherwise a mid-offer collect would double-count them against the
		// inventory and inflate net worth.
		assertEquals(6_000_000L, GeValuation.buyOfferValue(1_000_000L, 10L, 4L));
	}

	@Test
	public void buyOfferValueIsZeroWhenFullyBought()
	{
		// Everything bought -> the whole order is now collectable, nothing locked.
		assertEquals(0L, GeValuation.buyOfferValue(1_000_000L, 10L, 10L));
	}

	@Test
	public void buyOfferValueClampsIfSoldExceedsTotal()
	{
		// Defensive: quantitySold should never exceed totalQuantity, but if it
		// did, remaining escrow clamps to 0 rather than going negative.
		assertEquals(0L, GeValuation.buyOfferValue(1_000_000L, 10L, 12L));
	}

	// ------------------------------------------------------------------ sell

	@Test
	public void sellOfferValueCountsRemainingUnsoldAtMarket()
	{
		// 10 total, 4 sold, 6 unsold @ 900k current market -> 5.4m still locked.
		// Proceeds from the 4 sold are collectable and deliberately excluded.
		assertEquals(900_000L * 6L, GeValuation.sellOfferValue(900_000L, 10L, 4L));
	}

	@Test
	public void sellOfferValueIsZeroWhenFullySold()
	{
		// Nothing unsold remains in the exchange; proceeds are collectable.
		assertEquals(0L, GeValuation.sellOfferValue(900_000L, 10L, 10L));
	}

	@Test
	public void sellOfferValueClampsRemainingToZero()
	{
		assertEquals(0L, GeValuation.sellOfferValue(900_000L, 10L, 12L));
	}
}

package com.ospulse.integration;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BankRecommendationHighlighterTest
{
    private BankTagsService tags;
    private TagManager tagManager;
    private ConfigManager configManager;
    private ClientThread clientThread;
    private BankRecommendationHighlighter highlighter;

    /** A single-entry slot-ordinal -> item-id loadout. */
    private static Map<Integer, Integer> slot(int slotOrdinal, int itemId)
    {
        Map<Integer, Integer> m = new LinkedHashMap<>();
        m.put(slotOrdinal, itemId);
        return m;
    }

    @Before
    public void setUp()
    {
        tags = mock(BankTagsService.class);
        tagManager = mock(TagManager.class);
        configManager = mock(ConfigManager.class);
        clientThread = mock(ClientThread.class);
        // Run any client-thread runnable synchronously.
        doAnswer(inv -> { ((Runnable) inv.getArgument(0)).run(); return null; })
            .when(clientThread).invoke(any(Runnable.class));
        highlighter = new BankRecommendationHighlighter(tags, tagManager, configManager, clientThread);
    }

    @Test
    public void showInBankTagsIdsAndOpensTag()
    {
        Map<Integer, Integer> loadout = new LinkedHashMap<>();
        loadout.put(3, 4151);   // weapon
        loadout.put(0, 11802);  // head
        highlighter.showInBank(loadout);

        verify(tagManager).removeTag(BankRecommendationHighlighter.RESERVED_TAG);
        verify(tagManager).addTag(4151, BankRecommendationHighlighter.RESERVED_TAG, false);
        verify(tagManager).addTag(11802, BankRecommendationHighlighter.RESERVED_TAG, false);
        verify(tags).openBankTag(eq(BankRecommendationHighlighter.RESERVED_TAG), anyInt());
        assertTrue(highlighter.isArmed());
    }

    @Test
    public void writesEquipmentGridLayoutCsv()
    {
        Map<Integer, Integer> loadout = new LinkedHashMap<>();
        loadout.put(3, 4151);    // weapon -> grid idx 16
        loadout.put(0, 11802);   // head   -> grid idx 1
        highlighter.showInBank(loadout);

        ArgumentCaptor<String> csv = ArgumentCaptor.forClass(String.class);
        verify(configManager).setConfiguration(eq("banktags"), startsWith("layout_"), csv.capture());
        String[] cells = csv.getValue().split(",", -1);
        assertEquals(35, cells.length);
        assertEquals("11802", cells[1]);   // head at (1,2)
        assertEquals("4151", cells[16]);   // weapon at (3,1)
        assertEquals("-1", cells[0]);      // empty cell sentinel
    }

    @Test
    public void openTagDoesNotSuppressLayout()
    {
        highlighter.showInBank(slot(3, 4151));
        ArgumentCaptor<Integer> opts = ArgumentCaptor.forClass(Integer.class);
        verify(tags).openBankTag(eq(BankRecommendationHighlighter.RESERVED_TAG), opts.capture());
        assertEquals("layout must render (OPTION_NO_LAYOUT must NOT be set)",
            0, opts.getValue() & BankTagsService.OPTION_NO_LAYOUT);
    }

    @Test
    public void clearRemovesTagLayoutAndCloses()
    {
        highlighter.showInBank(slot(3, 4151));
        reset(tagManager, tags, configManager);
        highlighter.clear();
        verify(tagManager).removeTag(BankRecommendationHighlighter.RESERVED_TAG);
        verify(configManager).unsetConfiguration(eq("banktags"), startsWith("layout_"));
        verify(tags).closeBankTag();
        assertFalse(highlighter.isArmed());
    }

    /**
     * The Bank Tag Layouts hub plugin re-lays-out any open non-tab bank tag it
     * considers layout-enabled AFTER core Bank Tags renders our equipment grid
     * (ScriptPostFired BANKMAIN_BUILD @priority -1 vs core's ScriptPreFired
     * BANKMAIN_FINISHBUILDING), repacking the items densely from slot 0 — the
     * exact "layout ignored" bug. Its interop escape hatch is the literal
     * marker "DISABLED" in banktaglayouts.layout_&lt;tag&gt;
     * (BankTagLayoutsPlugin.LAYOUT_EXPLICITLY_DISABLED), which makes its
     * getBankOrder() return null so core Bank Tags keeps the grid.
     */
    @Test
    public void disablesBankTagLayoutsHijackOfReservedTag()
    {
        highlighter.showInBank(slot(3, 4151));
        verify(configManager).setConfiguration(
            eq("banktaglayouts"), eq("layout_ospulse-recommended"), eq("DISABLED"));
    }

    @Test
    public void reapplyRewritesBankTagLayoutsDisabledMarker()
    {
        // The marker must be re-asserted on every re-apply (bank re-open /
        // panel resume) so a mid-session BTL "enable layout" click can't stick.
        highlighter.showInBank(slot(3, 4151));
        reset(tagManager, tags, configManager);
        highlighter.reapplyIfArmed();
        verify(configManager).setConfiguration(
            eq("banktaglayouts"), eq("layout_ospulse-recommended"), eq("DISABLED"));
    }

    @Test
    public void clearRemovesBankTagLayoutsMarker()
    {
        highlighter.showInBank(slot(3, 4151));
        reset(tagManager, tags, configManager);
        highlighter.clear();
        verify(configManager).unsetConfiguration(eq("banktaglayouts"), eq("layout_ospulse-recommended"));
    }

    @Test
    public void suspendClosesButStaysArmed()
    {
        highlighter.showInBank(slot(3, 4151));
        reset(tagManager, tags, configManager);
        highlighter.suspend();
        verify(tags).closeBankTag();
        assertTrue("suspend must not disarm — the panel can re-activate later", highlighter.isArmed());
        verifyNoInteractions(tagManager);
    }

    @Test
    public void reShowReplacesRatherThanAccumulates()
    {
        highlighter.showInBank(slot(3, 4151));
        highlighter.showInBank(slot(3, 11802));
        verify(tagManager, times(2)).removeTag(BankRecommendationHighlighter.RESERVED_TAG);
        verify(tagManager).addTag(11802, BankRecommendationHighlighter.RESERVED_TAG, false);
    }

    @Test
    public void reapplyIfArmedReappliesReservedTagWhenArmed()
    {
        highlighter.showInBank(slot(3, 4151));
        reset(tagManager, tags, configManager);

        highlighter.reapplyIfArmed();

        verify(tagManager).removeTag(BankRecommendationHighlighter.RESERVED_TAG);
        verify(tagManager).addTag(4151, BankRecommendationHighlighter.RESERVED_TAG, false);
        verify(tags).openBankTag(eq(BankRecommendationHighlighter.RESERVED_TAG), anyInt());
    }

    @Test
    public void reapplyIfArmedNoOpWhenNotArmed()
    {
        highlighter.reapplyIfArmed();
        verifyNoInteractions(tagManager, tags);

        highlighter.showInBank(slot(3, 4151));
        highlighter.clear();
        reset(tagManager, tags, configManager);
        highlighter.reapplyIfArmed();
        verifyNoInteractions(tagManager, tags);
    }

    @Test
    public void reapplyIfArmedDefensivelyClosesWhenSuspended()
    {
        highlighter.showInBank(slot(3, 4151));
        highlighter.suspend();
        reset(tagManager, tags, configManager);

        highlighter.reapplyIfArmed();

        // Must not resurrect the recommendation, but must not silently trust
        // stale core Bank Tags search state left over from suspend()'s
        // closeBankTag() either — it re-closes defensively (item #5).
        verify(tags).closeBankTag();
        verifyNoInteractions(tagManager);
        assertTrue("suspend must not disarm", highlighter.isArmed());
    }

    /**
     * Regression for item #5: switching the OSPulse panel off while the bank is
     * open correctly hides the recommendation (suspend()), but the FIRST bank
     * close+reopen afterwards used to flicker it back into view once before
     * self-correcting on a second reopen. The first suspended bank-open must
     * not re-open the tag.
     */
    @Test
    public void firstBankOpenAfterSuspendDoesNotResurrectRecommendation()
    {
        highlighter.showInBank(slot(3, 4151));
        highlighter.suspend();
        reset(tagManager, tags, configManager);

        highlighter.reapplyIfArmed();

        verify(tagManager, never()).addTag(anyInt(), eq(BankRecommendationHighlighter.RESERVED_TAG), anyBoolean());
        verify(tags, never()).openBankTag(eq(BankRecommendationHighlighter.RESERVED_TAG), anyInt());
        assertTrue("suspend must not disarm", highlighter.isArmed());
    }

    @Test
    public void resumeClearsSuspendedAndReapplies()
    {
        highlighter.showInBank(slot(3, 4151));
        highlighter.suspend();
        reset(tagManager, tags, configManager);

        highlighter.resume();

        verify(tagManager).removeTag(BankRecommendationHighlighter.RESERVED_TAG);
        verify(tagManager).addTag(4151, BankRecommendationHighlighter.RESERVED_TAG, false);
        verify(tags).openBankTag(eq(BankRecommendationHighlighter.RESERVED_TAG), anyInt());

        // and a subsequent bank-open re-apply now goes through again
        reset(tagManager, tags, configManager);
        highlighter.reapplyIfArmed();
        verify(tags).openBankTag(eq(BankRecommendationHighlighter.RESERVED_TAG), anyInt());
    }

    @Test
    public void showInBankClearsStaleSuspendedFlag()
    {
        highlighter.showInBank(slot(3, 4151));
        highlighter.suspend();
        reset(tagManager, tags, configManager);

        // Arming fresh while suspended (e.g. user re-selects gear from the inactive
        // panel state) must not leave reapplyIfArmed permanently blocked.
        highlighter.showInBank(slot(0, 11802));
        reset(tagManager, tags, configManager);
        highlighter.reapplyIfArmed();
        verify(tags).openBankTag(eq(BankRecommendationHighlighter.RESERVED_TAG), anyInt());
    }

    /** Full equipment loadout covering every {@code SLOT_TO_GRID} entry, item id = grid index * 10 for readability. */
    private static Map<Integer, Integer> fullEquipmentLoadout()
    {
        Map<Integer, Integer> m = new LinkedHashMap<>();
        m.put(0, 10);    // HEAD   -> idx 1  -> id 10
        m.put(1, 80);    // CAPE   -> idx 8  -> id 80
        m.put(2, 90);    // AMULET -> idx 9  -> id 90
        m.put(13, 100);  // AMMO   -> idx 10 -> id 100
        m.put(3, 160);   // WEAPON -> idx 16 -> id 160
        m.put(4, 170);   // BODY   -> idx 17 -> id 170
        m.put(5, 180);   // SHIELD -> idx 18 -> id 180
        m.put(7, 250);   // LEGS   -> idx 25 -> id 250
        m.put(9, 320);   // GLOVES -> idx 32 -> id 320
        m.put(10, 330);  // BOOTS  -> idx 33 -> id 330
        m.put(12, 340);  // RING   -> idx 34 -> id 340
        return m;
    }

    @Test
    public void consumablesLaidOutBeneathEquipmentGridWithoutOverwritingIt()
    {
        highlighter.showInBank(fullEquipmentLoadout(), Arrays.asList(9001, 9002));

        ArgumentCaptor<String> csv = ArgumentCaptor.forClass(String.class);
        verify(configManager).setConfiguration(eq("banktags"), startsWith("layout_"), csv.capture());
        String[] cells = csv.getValue().split(",", -1);

        // Every equipment cell keeps exactly the value it had before consumables existed.
        int[] equipmentIndices = {1, 8, 9, 10, 16, 17, 18, 25, 32, 33, 34};
        int[] equipmentIds = {10, 80, 90, 100, 160, 170, 180, 250, 320, 330, 340};
        for (int i = 0; i < equipmentIndices.length; i++)
        {
            assertEquals("equipment cell " + equipmentIndices[i] + " must be untouched by consumables",
                String.valueOf(equipmentIds[i]), cells[equipmentIndices[i]]);
        }

        // Consumables start on a fresh row beneath the equipment block (index 5*8 = 40).
        assertEquals(42, cells.length);
        assertEquals("9001", cells[40]);
        assertEquals("9002", cells[41]);
    }

    @Test
    public void consumableIdsAreTaggedSoTheyPassTheBankTagFilter()
    {
        highlighter.showInBank(slot(3, 4151), Arrays.asList(9001, 9002));

        verify(tagManager).addTag(4151, BankRecommendationHighlighter.RESERVED_TAG, false);
        verify(tagManager).addTag(9001, BankRecommendationHighlighter.RESERVED_TAG, false);
        verify(tagManager).addTag(9002, BankRecommendationHighlighter.RESERVED_TAG, false);
    }

    @Test
    public void idPresentInBothGearAndConsumablesTaggedOnceAndNotDuplicatedInLayout()
    {
        // 4151 is recommended gear (weapon slot) AND (hypothetically) also listed
        // as a consumable — must be tagged exactly once and must not also occupy
        // a consumables-row cell.
        highlighter.showInBank(slot(3, 4151), Arrays.asList(4151, 555));

        verify(tagManager, times(1)).addTag(eq(4151), eq(BankRecommendationHighlighter.RESERVED_TAG), eq(false));
        verify(tagManager).addTag(555, BankRecommendationHighlighter.RESERVED_TAG, false);

        ArgumentCaptor<String> csv = ArgumentCaptor.forClass(String.class);
        verify(configManager).setConfiguration(eq("banktags"), startsWith("layout_"), csv.capture());
        String[] cells = csv.getValue().split(",", -1);
        assertEquals("4151", cells[16]);   // weapon, unaffected
        assertEquals(41, cells.length);    // only 555 survived into the consumables row
        assertEquals("555", cells[40]);
    }

    @Test
    public void oneArgOverloadProducesIdenticalCsvToTwoArgWithEmptyConsumables()
    {
        Map<Integer, Integer> loadout = fullEquipmentLoadout();

        highlighter.showInBank(loadout);
        ArgumentCaptor<String> csv1 = ArgumentCaptor.forClass(String.class);
        verify(configManager).setConfiguration(eq("banktags"), startsWith("layout_"), csv1.capture());

        BankRecommendationHighlighter other =
            new BankRecommendationHighlighter(tags, tagManager, configManager, clientThread);
        reset(tagManager, tags, configManager);
        other.showInBank(loadout, java.util.Collections.emptyList());
        ArgumentCaptor<String> csv2 = ArgumentCaptor.forClass(String.class);
        verify(configManager).setConfiguration(eq("banktags"), startsWith("layout_"), csv2.capture());

        assertEquals("1-arg overload must behave identically to the 2-arg overload with no consumables",
            csv1.getValue(), csv2.getValue());
        String[] cells = csv1.getValue().split(",", -1);
        assertEquals(35, cells.length);
    }

    @Test
    public void oneArgOverloadNeverTagsAnyConsumables()
    {
        highlighter.showInBank(slot(3, 4151));

        // Only the single gear item is ever tagged — no consumables path engaged.
        verify(tagManager, times(1)).addTag(anyInt(), eq(BankRecommendationHighlighter.RESERVED_TAG), eq(false));
        verify(tagManager).addTag(4151, BankRecommendationHighlighter.RESERVED_TAG, false);
    }

    @Test
    public void nullServicesNoOp()
    {
        BankRecommendationHighlighter h = new BankRecommendationHighlighter(null, null, null, clientThread);
        h.showInBank(slot(3, 4151)); // must not throw
        assertFalse(h.isArmed());
    }
}

package com.ospulse.integration;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;

import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for {@link FishBarrelTracker}'s catch-message / inventory-delta /
 * widget-resync inference. Uses a Mockito-stubbed {@link Client} standing in
 * for the live game client (see the {@code testImplementation} note in
 * build.gradle for why: {@code Client} has 200+ methods, impractical to
 * hand-stub, and only a handful matter per scenario here).
 */
public class FishBarrelTrackerTest
{
	private Client client;
	private FishBarrelTracker tracker;
	private int tick;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		tick = 0;
		when(client.getTickCount()).thenAnswer(inv -> tick);
		// Empty inventory/equipment by default; individual tests override.
		// Build both stand-in containers BEFORE stubbing (Mockito's "unfinished
		// stubbing" state is thread-local and doesn't tolerate a nested
		// mock()/when() call as an argument expression inside an outer when()).
		ItemContainer emptyInventory = emptyContainer();
		ItemContainer emptyEquipment = emptyContainer();
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(emptyInventory);
		when(client.getItemContainer(InventoryID.EQUIPMENT)).thenReturn(emptyEquipment);

		tracker = new FishBarrelTracker(client);
		tracker.reset();
		tracker.primeContainers();
	}

	private static ItemContainer emptyContainer()
	{
		ItemContainer container = mock(ItemContainer.class);
		when(container.getItems()).thenReturn(new Item[0]);
		return container;
	}

	private static ItemContainer containerWith(Item... items)
	{
		ItemContainer container = mock(ItemContainer.class);
		when(container.getItems()).thenReturn(items);
		return container;
	}

	/** Puts an open fish barrel in the stubbed inventory so barrel-gated checks pass. */
	private void openBarrelInInventory()
	{
		ItemContainer withBarrel = containerWith(new Item(ItemID.FISH_BARREL_OPEN, 1));
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(withBarrel);
		tracker.onItemContainerChanged(InventoryID.INVENTORY.getId(), withBarrel);
	}

	// ------------------------------------------------------------- basic catch

	@Test
	public void singleCatchMessageCreditsOneFishToBarrel()
	{
		openBarrelInInventory();

		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();

		// A clean per-tick credit only confirms the DELTA, not the running
		// total — mirrors molo-pl's own onGameTick, which never clears its
		// "unknown" flag from an ordinary catch either. The count is still
		// tracked (and grows) while unknown; only a Check resync, an Empty, or
		// hitting Full positively confirms the whole barrel. See
		// FishBarrelTracker#onTick's javadoc note on this.
		assertTrue(tracker.isUnknown());
		assertEquals(Map.of(ItemID.RAW_SHARK, 1), tracker.holdingSnapshot());
	}

	@Test
	public void multipleCatchesAccumulateAcrossTicks()
	{
		openBarrelInInventory();

		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();
		tick++;
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();
		tick++;
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a lobster.");
		tracker.onTick();

		assertEquals(Integer.valueOf(2), tracker.holdingSnapshot().get(ItemID.RAW_SHARK));
		assertEquals(Integer.valueOf(1), tracker.holdingSnapshot().get(ItemID.RAW_LOBSTER));
	}

	@Test
	public void checkResyncAfterCatchesConfirmsTheAccumulatedCount()
	{
		// The realistic end-to-end flow: fresh login (unknown), a run of clean
		// catches (still unknown, per molo-pl's semantics), then the player
		// right-clicks "Check" and the resulting widget text confirms the
		// tracker's running count was right all along.
		openBarrelInInventory();
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();
		tick++;
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();
		assertTrue(tracker.isUnknown());

		tracker.onBarrelMenuAction(ItemID.FISH_BARREL_OPEN, "Check");
		Widget widget = mock(Widget.class);
		when(widget.getText()).thenReturn(String.join("<br>", "The barrel contains:", "2 x Raw shark"));
		when(client.getWidget(193, 2)).thenReturn(widget);
		tracker.onWidgetLoaded(193);

		assertFalse(tracker.isUnknown());
		assertEquals(Map.of(ItemID.RAW_SHARK, 2), tracker.holdingSnapshot());
	}

	@Test
	public void catchWithoutOpenBarrelIsIgnored()
	{
		// No barrel (open or closed) in inventory/equipment at all: SPAM catch
		// messages aren't attributable to a barrel and must be ignored.
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();

		assertTrue(tracker.holdingSnapshot().isEmpty());
	}

	// ------------------------------------------------------------- double catch

	@Test
	public void radaBlessingDoublesTheLastCaughtSpecies()
	{
		openBarrelInInventory();

		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onChatMessage(ChatMessageType.SPAM, "Rada's blessing enabled you to catch an extra fish.");
		tracker.onTick();

		// A resolved double-catch is just another attributable credit this
		// tick — doesn't confirm the whole barrel any more than a single catch
		// does (see #singleCatchMessageCreditsOneFishToBarrel).
		assertEquals(Integer.valueOf(2), tracker.holdingSnapshot().get(ItemID.RAW_SHARK));
	}

	@Test
	public void spiritFlakesDoublesTheLastCaughtSpecies()
	{
		openBarrelInInventory();

		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a lobster.");
		tracker.onChatMessage(ChatMessageType.SPAM, "The spirit flakes enabled you to catch an extra fish.");
		tracker.onTick();

		assertEquals(Integer.valueOf(2), tracker.holdingSnapshot().get(ItemID.RAW_LOBSTER));
	}

	@Test
	public void cormorantCatchCannotBeAttributedAndMarksUnknown()
	{
		openBarrelInInventory();

		tracker.onChatMessage(ChatMessageType.SPAM, "Your cormorant returns with its catch.");
		tracker.onTick();

		assertTrue(tracker.isUnknown());
	}

	// ------------------------------------------------------------- infernal harpoon

	@Test
	public void cookingXpDropOffsetsOneCatchFromBarrelCredit()
	{
		openBarrelInInventory();

		// Two catches, one auto-cooked by an infernal harpoon before reaching the
		// barrel: only one fish should land in the barrel.
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onCookingXpGained();
		tracker.onTick();

		assertEquals(Integer.valueOf(1), tracker.holdingSnapshot().get(ItemID.RAW_SHARK));
	}

	// ------------------------------------------------------------- empty to bank

	@Test
	public void emptyToBankClearsHolding()
	{
		openBarrelInInventory();
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();
		assertFalse(tracker.holdingSnapshot().isEmpty());

		tracker.onBarrelMenuAction(ItemID.FISH_BARREL_OPEN, "Empty to bank");
		tracker.onTick();

		assertTrue(tracker.holdingSnapshot().isEmpty());
		assertFalse(tracker.isUnknown());
	}

	@Test
	public void bankEmptyChatMessageClearsHolding()
	{
		openBarrelInInventory();
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();

		tracker.onChatMessage(ChatMessageType.GAMEMESSAGE, "You empty all of your containers into the bank.");

		assertTrue(tracker.holdingSnapshot().isEmpty());
		assertFalse(tracker.isUnknown());
	}

	@Test
	public void bankFullMessageMarksUnknown()
	{
		openBarrelInInventory();
		tracker.onChatMessage(ChatMessageType.GAMEMESSAGE, "Your bank could not hold your fish.");
		assertTrue(tracker.isUnknown());
	}

	// ------------------------------------------------------------- unknown-state freeze / resync

	@Test
	public void freshTrackerStartsUnknown()
	{
		assertTrue(tracker.isUnknown());
	}

	@Test
	public void widgetResyncRestoresKnownStateWithExactContents()
	{
		openBarrelInInventory();
		// Force into an unknown state (cormorant catch can't be attributed).
		tracker.onChatMessage(ChatMessageType.SPAM, "Your cormorant returns with its catch.");
		tracker.onTick();
		assertTrue(tracker.isUnknown());

		tracker.onBarrelMenuAction(ItemID.FISH_BARREL_OPEN, "Check");

		Widget widget = mock(Widget.class);
		when(widget.getText()).thenReturn(String.join("<br>", "The barrel contains:", "12 x Raw shark"));
		when(client.getWidget(193, 2)).thenReturn(widget);

		tracker.onWidgetLoaded(193);

		assertFalse(tracker.isUnknown());
		assertEquals(Map.of(ItemID.RAW_SHARK, 12), tracker.holdingSnapshot());
	}

	@Test
	public void widgetLoadedForUnrelatedGroupIsIgnored()
	{
		openBarrelInInventory();
		tracker.onBarrelMenuAction(ItemID.FISH_BARREL_OPEN, "Check");

		tracker.onWidgetLoaded(42); // not the Check interface's group id

		Mockito.verify(client, Mockito.never()).getWidget(193, 2);
	}

	@Test
	public void checkResyncOutsideActionWindowIsIgnored()
	{
		openBarrelInInventory();
		// No "Check" menu action recorded recently.
		tracker.onWidgetLoaded(193);

		Mockito.verify(client, Mockito.never()).getWidget(eq(193), eq(2));
	}

	// ------------------------------------------------------------- reset

	@Test
	public void resetClearsHoldingAndReturnsToUnknown()
	{
		openBarrelInInventory();
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();
		assertFalse(tracker.holdingSnapshot().isEmpty());

		tracker.reset();

		assertTrue(tracker.holdingSnapshot().isEmpty());
		assertTrue(tracker.isUnknown());
	}

	// ------------------------------------------------- caught-to-barrel feed

	@Test
	public void drainCaughtToBarrelReturnsThisTickCatchesThenClears()
	{
		openBarrelInInventory();
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();

		// The session tracker drains this once per tick to synthesise the
		// storage-routed loot receipts that lift Loot + net worth.
		assertEquals(Map.of(ItemID.RAW_SHARK, 1), tracker.drainCaughtToBarrel());
		// A second drain in the same tick yields nothing (already consumed).
		assertTrue(tracker.drainCaughtToBarrel().isEmpty());
	}

	@Test
	public void cookedCatchIsExcludedFromTheBarrelFeed()
	{
		openBarrelInInventory();
		// Two catches, one auto-cooked by an infernal harpoon: only one raw fish
		// actually reaches the barrel, so only one is booked as loot.
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onCookingXpGained();
		tracker.onTick();

		assertEquals(Map.of(ItemID.RAW_SHARK, 1), tracker.drainCaughtToBarrel());
	}

	@Test
	public void catchesOverflowingToInventoryAreNotInTheBarrelFeed()
	{
		// Barrel full: a catch lands in the inventory instead of the barrel, so
		// it must NOT be fed as storage-routed loot — the engine's normal
		// inventory diff books it, and double-booking here would over-count Loot.
		openBarrelInInventory();
		ItemContainer barrelPlusShark = containerWith(
			new Item(ItemID.FISH_BARREL_OPEN, 1), new Item(ItemID.RAW_SHARK, 1));
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(barrelPlusShark);
		tracker.onItemContainerChanged(InventoryID.INVENTORY.getId(), barrelPlusShark);
		tracker.onChatMessage(ChatMessageType.SPAM, "You catch a shark.");
		tracker.onTick();

		assertTrue("a catch that overflowed to the inventory is not barrel loot",
			tracker.drainCaughtToBarrel().isEmpty());
	}
}

package com.ospulse.integration;

import com.ospulse.ge.GeOfferState;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Verifies every RuneLite {@link GrandExchangeOfferState} maps to the
 * equivalent pure domain {@link GeOfferState}, and that nothing in the
 * RuneLite enum is left unhandled.
 */
public class GeOfferStateMapperTest
{
	@Test
	public void mapsEveryStateExplicitly()
	{
		assertEquals(GeOfferState.EMPTY, GeOfferStateMapper.map(GrandExchangeOfferState.EMPTY));
		assertEquals(GeOfferState.BUYING, GeOfferStateMapper.map(GrandExchangeOfferState.BUYING));
		assertEquals(GeOfferState.BOUGHT, GeOfferStateMapper.map(GrandExchangeOfferState.BOUGHT));
		assertEquals(GeOfferState.SELLING, GeOfferStateMapper.map(GrandExchangeOfferState.SELLING));
		assertEquals(GeOfferState.SOLD, GeOfferStateMapper.map(GrandExchangeOfferState.SOLD));
		assertEquals(GeOfferState.CANCELLED_BUY, GeOfferStateMapper.map(GrandExchangeOfferState.CANCELLED_BUY));
		assertEquals(GeOfferState.CANCELLED_SELL, GeOfferStateMapper.map(GrandExchangeOfferState.CANCELLED_SELL));
	}

	@Test
	public void nullMapsToEmpty()
	{
		assertEquals(GeOfferState.EMPTY, GeOfferStateMapper.map(null));
	}

	@Test
	public void everyRuneLiteStateProducesANonNullMapping()
	{
		for (GrandExchangeOfferState state : GrandExchangeOfferState.values())
		{
			assertNotNull(GeOfferStateMapper.map(state));
		}
	}
}

package com.ospulse.integration;

import org.junit.Test;

import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for the fish barrel "Check" interface text parser. Pure/stateless:
 * no RuneLite runtime dependency.
 */
public class FishBarrelWidgetParserTest
{
	private final Map<String, Integer> fishTypesByName = FishBarrelTracker.fishTypesByName();

	@Test
	public void invalidMessageReturnsNull()
	{
		assertNull(FishBarrelWidgetParser.parse("Hello, World!", fishTypesByName));
	}

	@Test
	public void entryWithoutHeaderReturnsNull()
	{
		assertNull(FishBarrelWidgetParser.parse("28 x Raw swordfish", fishTypesByName));
	}

	@Test
	public void blankOrNullMessageReturnsNull()
	{
		assertNull(FishBarrelWidgetParser.parse(null, fishTypesByName));
		assertNull(FishBarrelWidgetParser.parse("   ", fishTypesByName));
	}

	@Test
	public void emptyBarrelParsesToEmptyMap()
	{
		Map<Integer, Integer> parsed = FishBarrelWidgetParser.parse("The barrel is empty.", fishTypesByName);
		assertEquals(Map.of(), parsed);
	}

	@Test
	public void singleEntryParsesToItemIdAndQuantity()
	{
		Map<Integer, Integer> parsed = FishBarrelWidgetParser.parse(
			String.join("<br>", "The barrel contains:", "27 x Raw anglerfish"), fishTypesByName);

		assertEquals(Map.of(net.runelite.api.gameval.ItemID.RAW_ANGLERFISH, 27), parsed);
	}

	@Test
	public void multiEntryParsesEverySpecies()
	{
		Map<Integer, Integer> parsed = FishBarrelWidgetParser.parse(String.join("<br>",
			"The barrel contains:",
			"1 x Raw anglerfish, 2 x Raw monkfish, 3 x Raw",
			"shrimps, 1 x Raw anchovies, 1 x Raw salmon, 1 x Raw",
			"cod, 1 x Raw tuna, 1 x Raw bass"), fishTypesByName);

		int total = parsed.values().stream().mapToInt(Integer::intValue).sum();
		assertEquals(11, total);
		assertEquals(Integer.valueOf(1), parsed.get(net.runelite.api.gameval.ItemID.RAW_ANGLERFISH));
		assertEquals(Integer.valueOf(2), parsed.get(net.runelite.api.gameval.ItemID.RAW_MONKFISH));
		assertEquals(Integer.valueOf(3), parsed.get(net.runelite.api.gameval.ItemID.RAW_SHRIMP));
		assertEquals(Integer.valueOf(1), parsed.get(net.runelite.api.gameval.ItemID.RAW_ANCHOVIES));
		assertEquals(Integer.valueOf(1), parsed.get(net.runelite.api.gameval.ItemID.RAW_SALMON));
		assertEquals(Integer.valueOf(1), parsed.get(net.runelite.api.gameval.ItemID.RAW_COD));
		assertEquals(Integer.valueOf(1), parsed.get(net.runelite.api.gameval.ItemID.RAW_TUNA));
		assertEquals(Integer.valueOf(1), parsed.get(net.runelite.api.gameval.ItemID.RAW_BASS));
	}

	@Test
	public void unrecognisedSpeciesFailsTheWholeParse()
	{
		// A species we can't map back to an item id must not silently vanish or
		// get lumped into an "unknown" bucket — the whole parse should fail so
		// the caller keeps its previous (still-attributed) state.
		Map<Integer, Integer> parsed = FishBarrelWidgetParser.parse(
			String.join("<br>", "The barrel contains:", "5 x Raw wibblefish"), fishTypesByName);
		assertNull(parsed);
	}

	@Test
	public void duplicateEntriesForSameSpeciesAreSummed()
	{
		Map<Integer, Integer> parsed = FishBarrelWidgetParser.parse(
			String.join("<br>", "The barrel contains:", "2 x Raw shark, 3 x Raw shark"), fishTypesByName);
		assertEquals(Integer.valueOf(5), parsed.get(net.runelite.api.gameval.ItemID.RAW_SHARK));
	}
}

package com.ospulse.ge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class GeReconcilerLootSaleTest
{
	private static final int SHIELD = 1201;
	private static final int SHARK = 385;

	@Test
	public void sellingWithNoBuyBasisSurfacesLootSaleAfterTax()
	{
		GeReconciler r = new GeReconciler();
		// Sell 1 shield @22,400, no prior buy -> a loot-sale, not a flip.
		r.onOfferUpdate(0, GeOfferState.SOLD, SHIELD, "Rune sq shield", 1, 1, 22_400L, 22_400L, 1000L);

		assertEquals("no flip P&L for a loot sale", 0L, r.realizedPnl());
		List<LootSale> sales = r.drainLootSales();
		assertEquals(1, sales.size());
		assertEquals(SHIELD, sales.get(0).itemId);
		assertEquals(1L, sales.get(0).quantity);
		assertEquals(21_952L, sales.get(0).netProceeds); // 22,400 - 448 tax
		assertTrue("drain clears the queue", r.drainLootSales().isEmpty());
	}

	@Test
	public void flipDoesNotSurfaceALootSale()
	{
		GeReconciler r = new GeReconciler();
		// Buy 100 sharks @800 then sell 100 @850 -> a pure flip, no loot-sale.
		r.onOfferUpdate(0, GeOfferState.BOUGHT, SHARK, "Shark", 100, 100, 80_000L, 800L, 1000L);
		r.onOfferUpdate(0, GeOfferState.EMPTY, SHARK, "Shark", 100, 100, 80_000L, 800L, 1100L);
		r.onOfferUpdate(1, GeOfferState.SOLD, SHARK, "Shark", 100, 100, 85_000L, 850L, 1200L);

		assertTrue("flip surfaces no loot sale", r.drainLootSales().isEmpty());
		assertTrue("flip P&L is positive", r.realizedPnl() > 0);
	}

	@Test
	public void partialFlipPartialLootSurfacesOnlyTheUnmatchedPortion()
	{
		GeReconciler r = new GeReconciler();
		// Bought 50 sharks; then sell 100 (50 flip + 50 looted) @850.
		r.onOfferUpdate(0, GeOfferState.BOUGHT, SHARK, "Shark", 50, 50, 40_000L, 800L, 1000L);
		r.onOfferUpdate(0, GeOfferState.EMPTY, SHARK, "Shark", 50, 50, 40_000L, 800L, 1100L);
		r.onOfferUpdate(1, GeOfferState.SOLD, SHARK, "Shark", 100, 100, 85_000L, 850L, 1200L);

		List<LootSale> sales = r.drainLootSales();
		assertEquals(1, sales.size());
		assertEquals(50L, sales.get(0).quantity); // only the unmatched (looted) half
		// net per item = 850 - 17 tax = 833; 50 * 833 = 41,650
		assertEquals(41_650L, sales.get(0).netProceeds);
	}
}

package com.ospulse.ge;

import org.junit.Before;
import org.junit.Test;

import java.util.Map;
import java.util.OptionalLong;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GeReconcilerTest
{
	private static final int WHIP = 4151;
	private static final int OLD_SCHOOL_BOND = 13190; // GE-tax exempt
	private static final int COINS = GeReconciler.COINS_ITEM_ID;

	private GeReconciler reconciler;

	@Before
	public void setUp()
	{
		reconciler = new GeReconciler();
	}

	@Test
	public void buyThenSellRealisesPnl()
	{
		// Buy 10 whips at 1,000,000 each.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		assertEquals(0L, reconciler.realizedPnl());

		// Offer slot cleared/reused for a sell of the same 10 whips at
		// 1,200,000 each.
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);

		// Sale nets the price minus 2% GE tax: 1,200,000 - (1,200,000/50=24,000)
		// = 1,176,000 per whip. (1,176,000 - 1,000,000) * 10 = 1,760,000 profit.
		assertEquals(1_760_000L, reconciler.realizedPnl());
	}

	/**
	 * Bot-review finding (P2): a sell offer's {@code pricePerItem} is the
	 * LISTED (minimum) price, but the GE can clear it at a genuinely higher
	 * price — {@code gpTransacted} carries the actual proceeds (see the
	 * {@code onOfferUpdate} comment "a sell can fill ABOVE the offer price").
	 * {@link GeReconciler#applySell} must derive the realized delta and tax
	 * from the actual incremental proceeds, not the stale listed price.
	 */
	@Test
	public void sellFillingAboveTheListedPriceRealisesActualProceeds()
	{
		// Buy 10 whips at 1,000,000 each.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);

		// Sell offer LISTS 1,000,000/ea (its minimum), but the GE actually
		// clears it at 1,200,000/ea — gpTransacted (12,000,000 for 10) is the
		// real proceeds, not quantityTransacted * pricePerItem (10,000,000).
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_000_000L, 2000L);

		// Same arithmetic as buyThenSellRealisesPnl (1,200,000/ea net of 2% tax
		// = 1,176,000; (1,176,000-1,000,000)*10 = 1,760,000 profit) — using the
		// listed price instead would compute a LOSS here, flipping the sign.
		assertEquals("realized P&L must reflect actual proceeds, not the listed price",
			1_760_000L, reconciler.realizedPnl());
		assertEquals("the slot figure must match too",
			OptionalLong.of(1_760_000L), reconciler.slotRealizedPnl(1));
	}

	@Test
	public void resetClearsRealisedPnlCostBasisAndAttribution()
	{
		// Realise some flip P&L and leave an open cost basis + attributed ids.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals(1_760_000L, reconciler.realizedPnl());

		reconciler.reset();

		// Everything is back to a fresh-session zero: no realised P&L and no
		// outstanding arrival expectation for the bought whips.
		assertEquals(0L, reconciler.realizedPnl());
		assertEquals(0L, reconciler.attributeArrival(WHIP, 10L));

		// Cost basis was cleared too: selling the same item now has no basis, so
		// it realises nothing (rather than resurrecting the pre-reset basis).
		reconciler.onOfferUpdate(0, GeOfferState.SOLD, WHIP, "Abyssal whip",
			5L, 5L, 6_000_000L, 1_200_000L, 3000L);
		assertEquals(0L, reconciler.realizedPnl());
	}

	@Test
	public void repeatedUpdatesForSameOfferDoNotDoubleCount()
	{
		// Partial fill progression on the same slot: 0 -> 3 -> 3 (repeat) -> 7 -> 10.
		reconciler.onOfferUpdate(0, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 3L, 3_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(0, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 3L, 3_000_000L, 1_000_000L, 1100L);
		reconciler.onOfferUpdate(0, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 7L, 7_000_000L, 1_000_000L, 1200L);
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1300L);

		// Now sell all 10 in one shot, repeated update included.
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2100L);

		// 10 whips sold at 1.2M, net of 2% tax (24,000/ea) -> 1,760,000 profit.
		assertEquals(1_760_000L, reconciler.realizedPnl());
	}

	@Test
	public void weightedAverageCostAcrossTwoBuys()
	{
		// Two separate buy offers in different slots: 10 @ 1,000,000, then
		// 10 more @ 1,200,000 -> avg cost 1,100,000.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 1500L);

		// Sell all 20 at 1,300,000, net of 2% tax (1,300,000/50 = 26,000/ea) ->
		// (1,274,000 - 1,100,000) * 20 = 3,480,000
		reconciler.onOfferUpdate(2, GeOfferState.SOLD, WHIP, "Abyssal whip",
			20L, 20L, 26_000_000L, 1_300_000L, 2000L);

		assertEquals(3_480_000L, reconciler.realizedPnl());
	}

	@Test
	public void slotReuseWithDifferentItemResetsTracking()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(0, GeOfferState.EMPTY, WHIP, "Abyssal whip",
			0L, 0L, 0L, 0L, 1100L);

		// Same slot, new offer for a different item; incremental should
		// start fresh from 0, not be offset by the whip's prior quantity.
		int dartId = 811;
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, dartId, "Rune dart",
			5000L, 5000L, 5000L, 1L, 1200L);

		assertEquals(10L, reconciler.attributeArrival(WHIP, 10L));
		assertEquals(5000L, reconciler.attributeArrival(dartId, 5000L));
	}

	@Test
	public void arrivalAttributionIsQuantityCappedAndConsumesTheLedger()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);

		// Partial consumption whittles the expectation down; once exhausted,
		// further arrivals of the same item are NOT attributed (genuine loot
		// beyond the bought quantity must stay loot).
		assertEquals(6L, reconciler.attributeArrival(WHIP, 6L));
		assertEquals(4L, reconciler.attributeArrival(WHIP, 10L));
		assertEquals(0L, reconciler.attributeArrival(WHIP, 10L));
	}

	@Test
	public void emptyStateDoesNotAttributeOrAffectLedger()
	{
		reconciler.onOfferUpdate(0, GeOfferState.EMPTY, 0, null,
			0L, 0L, 0L, 0L, 1000L);

		assertEquals(0L, reconciler.realizedPnl());
		assertEquals(0L, reconciler.attributeArrival(WHIP, 1L));
		assertEquals(0L, reconciler.attributeArrival(COINS, 1L));
	}

	@Test
	public void sellingWithoutGeCostBasisDoesNotCountAsFlipProfit()
	{
		// Dump 10 looted whips on the GE at 1.2M with no prior GE buy: this is
		// not a flip, so realised flip P&L stays 0 (the sale value is captured
		// in wealth-delta profit elsewhere, not here).
		reconciler.onOfferUpdate(0, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 1000L);

		assertEquals(0L, reconciler.realizedPnl());
		// It's still GE activity: the placement's inventory removal and the
		// net-of-tax coin proceeds (12M - 24,000 * 10) are both attributed,
		// keeping the sale out of the supplies and loot feeds.
		assertEquals(10L, reconciler.attributeRemoval(WHIP, 10L));
		assertEquals(11_760_000L, reconciler.attributeArrival(COINS, 20_000_000L));
	}

	@Test
	public void sellingMoreThanBoughtOnlyCountsFlippedQuantity()
	{
		// Bought 5 @ 1,000,000, then sold 10 @ 1,200,000: only the 5 that were
		// actually flipped count -> (1,176,000 net-of-tax - 1,000,000) * 5 = 880,000.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			5L, 5L, 5_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);

		assertEquals(880_000L, reconciler.realizedPnl());
	}

	@Test
	public void cancelledBuyRefundsUnfilledEscrowExactlyOnce()
	{
		// Buy partially fills 4/10, then is cancelled.
		reconciler.onOfferUpdate(0, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 4L, 4_000_000L, 1_000_000L, 1000L);
		assertEquals(4L, reconciler.attributeArrival(WHIP, 10L));

		reconciler.onOfferUpdate(0, GeOfferState.CANCELLED_BUY, WHIP, "Abyssal whip",
			10L, 4L, 4_000_000L, 1_000_000L, 1100L);

		// No new items moved on the cancellation itself, but the unfilled
		// escrow (6 x 1M) returns to the collection box as coins.
		assertEquals(0L, reconciler.attributeArrival(WHIP, 10L));
		assertEquals(6_000_000L, reconciler.attributeArrival(COINS, 10_000_000L));

		// A repeated cancelled-state event must not refund again.
		reconciler.onOfferUpdate(0, GeOfferState.CANCELLED_BUY, WHIP, "Abyssal whip",
			10L, 4L, 4_000_000L, 1_000_000L, 1200L);
		assertEquals(0L, reconciler.attributeArrival(COINS, 10_000_000L));
	}

	@Test
	public void cancelledSellReturnsUnsoldItemsToCollectionBox()
	{
		// Sell 10 placed (removal expectation), fills 4 (net-of-tax coin
		// proceeds), then cancelled: the 6 unsold whips become collectable.
		reconciler.onOfferUpdate(0, GeOfferState.SELLING, WHIP, "Abyssal whip",
			10L, 0L, 0L, 1_200_000L, 1000L);
		assertEquals(10L, reconciler.attributeRemoval(WHIP, 10L));

		reconciler.onOfferUpdate(0, GeOfferState.SELLING, WHIP, "Abyssal whip",
			10L, 4L, 4_800_000L, 1_200_000L, 1100L);
		assertEquals(4_704_000L, reconciler.attributeArrival(COINS, 10_000_000L));

		reconciler.onOfferUpdate(0, GeOfferState.CANCELLED_SELL, WHIP, "Abyssal whip",
			10L, 4L, 4_800_000L, 1_200_000L, 1200L);
		assertEquals(6L, reconciler.attributeArrival(WHIP, 10L));
	}

	@Test
	public void buyFilledUnderOfferPriceRefundsTheDifferenceAsCoins()
	{
		// Offered 10 @ 1M but matched cheaper sellers for 9M total: the 1M
		// difference is collectable as coins alongside the 10 items.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 9_000_000L, 1_000_000L, 1000L);

		assertEquals(10L, reconciler.attributeArrival(WHIP, 10L));
		assertEquals(1_000_000L, reconciler.attributeArrival(COINS, 10_000_000L));
	}

	@Test
	public void saleProceedsUseActualGpWhenFilledAboveOfferPrice()
	{
		// Offered 10 @ 1.2M but matched higher buyers for 13M total: proceeds
		// are the actual 13M minus per-item tax at the actual average price
		// (1.3M/50 = 26,000 each) -> 13M - 260,000 = 12,740,000.
		reconciler.onOfferUpdate(0, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 13_000_000L, 1_200_000L, 1000L);

		assertEquals(12_740_000L, reconciler.attributeArrival(COINS, 20_000_000L));
	}

	@Test
	public void arrivalPersistsIndefinitelyWhileOfferOccupiesItsSlot()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);

		// The completed offer sits uncollected in the collection box for ten
		// minutes: the expectation must survive until the goods are seen.
		reconciler.expireAttributions(601_000L);
		assertEquals(10L, reconciler.attributeArrival(WHIP, 10L));
	}

	@Test
	public void arrivalExpiresAfterSlotClearsPlusSettleWindow()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		// Slot cleared (collected — possibly straight to bank) at t=2000.
		reconciler.onOfferUpdate(0, GeOfferState.EMPTY, 0, null,
			0L, 0L, 0L, 0L, 2000L);

		// Past the settle window the leftover dies, so a later genuine whip
		// drop cannot be swallowed by a stale expectation.
		reconciler.expireAttributions(12_001L);
		assertEquals(0L, reconciler.attributeArrival(WHIP, 10L));
	}

	@Test
	public void arrivalStillConsumableWithinSlotClearSettleWindow()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(0, GeOfferState.EMPTY, 0, null,
			0L, 0L, 0L, 0L, 2000L);

		// The collect-to-inventory arrival lands a moment after the slot
		// clears; within the settle window it is still attributed.
		reconciler.expireAttributions(3_000L);
		assertEquals(10L, reconciler.attributeArrival(WHIP, 10L));
	}

	@Test
	public void sellPlacementRemovalExpiresAfterSettleWindow()
	{
		reconciler.onOfferUpdate(0, GeOfferState.SELLING, WHIP, "Abyssal whip",
			10L, 0L, 0L, 1_200_000L, 1000L);

		// The placement-time inventory removal lands within the same tick
		// batch; long after that any leftover must not suppress a genuine
		// removal (drop/trade) of the same item.
		reconciler.expireAttributions(11_001L);
		assertEquals(0L, reconciler.attributeRemoval(WHIP, 10L));
	}

	@Test
	public void primeSlotDoesNotAttributePreSessionFills()
	{
		// A live offer predating the session: 4/10 already bought. Priming
		// seeds the incremental tracking without attributing that history.
		reconciler.primeSlot(0, GeOfferState.BUYING, WHIP, 4L, 4_000_000L);
		reconciler.onOfferUpdate(0, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 4L, 4_000_000L, 1_000_000L, 1000L);
		assertEquals(0L, reconciler.attributeArrival(WHIP, 10L));

		// Only genuinely new fills count from here on.
		reconciler.onOfferUpdate(0, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 7L, 7_000_000L, 1_000_000L, 2000L);
		assertEquals(3L, reconciler.attributeArrival(WHIP, 10L));
	}

	@Test
	public void collectableValueCountsSaleProceedsWhileSlotOccupied()
	{
		// Sell 10 whips (fully filled) at 1.2M: proceeds net of 2% tax
		// (24,000/ea) = 11,760,000 coins sit in the collection box awaiting
		// collection while the slot is still occupied. That value must show up
		// in the collectable total so net worth doesn't dip after the fill.
		reconciler.onOfferUpdate(0, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 1000L);

		// Non-coin lookup never consulted for coins (valued at 1 internally).
		assertEquals(11_760_000L, reconciler.collectableValue(id -> 0L));
	}

	@Test
	public void collectableValueValuesBoughtItemsAtUnitValue()
	{
		// Bought 10 whips (fully filled at the offer price, no refund): the 10
		// items are collectable, valued at their market unit value.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);

		assertEquals(10_000_000L, reconciler.collectableValue(id -> id == WHIP ? 1_000_000L : 0L));
	}

	@Test
	public void collectableValueDropsToZeroOnceSlotClears()
	{
		reconciler.onOfferUpdate(0, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 1000L);
		assertEquals(11_760_000L, reconciler.collectableValue(id -> 0L));

		// Slot cleared (the player collected): the value hands back to
		// inventory/bank accounting immediately, so it must leave the
		// collectable total at once (not linger for the settle window) to avoid
		// double-counting goods now in the inventory.
		reconciler.onOfferUpdate(0, GeOfferState.EMPTY, 0, null,
			0L, 0L, 0L, 0L, 2000L);
		assertEquals(0L, reconciler.collectableValue(id -> 0L));
	}

	@Test
	public void collectableValueShrinksAsGoodsAreCollectedIntoInventory()
	{
		// Bought 10 whips; collectable starts at 10 * 1M.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		assertEquals(10_000_000L, reconciler.collectableValue(id -> 1_000_000L));

		// A partial collect of 4 whips lands in the inventory: attributeArrival
		// consumes that portion of the expectation, so the collectable total
		// shrinks by exactly the collected value — it can never persistently
		// double-count goods already pulled into the inventory.
		assertEquals(4L, reconciler.attributeArrival(WHIP, 4L));
		assertEquals(6_000_000L, reconciler.collectableValue(id -> 1_000_000L));
	}

	@Test
	public void geTaxIsCappedAtFiveMillionPerItem()
	{
		// Buy 1 @ 200M, sell 1 @ 300M. Uncapped 2% would be 6M; the tax is
		// capped at 5M/item, so net proceeds = 295M and pnl = 295M - 200M = 95M.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			1L, 1L, 200_000_000L, 200_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			1L, 1L, 300_000_000L, 300_000_000L, 2000L);

		assertEquals(95_000_000L, reconciler.realizedPnl());
	}

	@Test
	public void taxExemptItemPaysNoGeTax()
	{
		// The Old school bond is exempt from GE tax: a flat buy-and-sell at the
		// same price realises exactly zero, not a small tax-driven loss.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, OLD_SCHOOL_BOND, "Old school bond",
			1L, 1L, 8_000_000L, 8_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, OLD_SCHOOL_BOND, "Old school bond",
			1L, 1L, 8_000_000L, 8_000_000L, 2000L);

		assertEquals(0L, reconciler.realizedPnl());
	}

	@Test
	public void subFiftyGpSaleIncursNoTax()
	{
		// 2% of a sub-50 gp sale rounds down to 0, so no tax is charged:
		// buy 10 @ 40, sell 10 @ 49 -> (49 - 40) * 10 = 90 (no tax deducted).
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 400L, 40L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 490L, 49L, 2000L);

		assertEquals(90L, reconciler.realizedPnl());
	}

	@Test
	public void preSessionSoldOfferProceedsAreCollectableAndNotLoot()
	{
		// A SELL that completed BEFORE the session started (its proceeds still sit
		// uncollected in the GE box at login) must, when collected in-session, be
		// attributed as a GE transfer — net worth, not loot — and count toward the
		// collectable value meanwhile. No pre-session flip P&L is resurrected.
		// Mirrors the live bug: 4.9m of pre-session sale proceeds booked as loot.
		reconciler.primeCollectable(0, GeOfferState.SOLD, WHIP, 1_000L, 5_000_000L, 5_000L);

		long netProceeds = 5_000_000L - 100L * 1_000L; // 2% tax (5000/50 = 100) per item
		assertEquals(4_900_000L, netProceeds);
		assertEquals("uncollected proceeds count toward net worth (collectable)",
			netProceeds, reconciler.collectableValue(id -> 1L));
		assertEquals("pre-session proceeds must not resurrect flip P&L",
			0L, reconciler.realizedPnl());

		// Player collects -> coins land in inventory -> fully attributed (not loot).
		assertEquals("collected pre-session proceeds are a GE transfer, excluded from loot",
			netProceeds, reconciler.attributeArrival(GeReconciler.COINS_ITEM_ID, netProceeds));
	}

	@Test
	public void preSessionBoughtOfferItemsAreCollectableAndNotLoot()
	{
		// A BUY that completed pre-session: the bought items sit uncollected at login.
		// Collecting them in-session is a GE transfer (already-owned goods), not loot.
		reconciler.primeCollectable(0, GeOfferState.BOUGHT, WHIP, 5L, 500_000L, 100_000L);
		assertEquals(0L, reconciler.realizedPnl());
		assertEquals("collected pre-session bought items are excluded from loot",
			5L, reconciler.attributeArrival(WHIP, 5L));
	}

	// ----------------------------------------------- cost-basis export/import (relog persistence)

	@Test
	public void exportImportRoundTripPreservesCostBasisAcrossRelog()
	{
		// Session 1 (weeks ago, in GE terms): buy 10 whips, never sold this session.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);

		Map<Integer, GeReconciler.CostBasisSnapshot> exported = reconciler.exportCostBasis();

		// Relog: a fresh reconciler (as the reset session bootstrap produces)
		// restores the ledger from the exported snapshot.
		GeReconciler restored = new GeReconciler();
		restored.importCostBasis(exported);

		// Selling the weeks-old buy in the NEW session credits the full flip P&L
		// (sale - basis - tax), exactly as if it had never left memory.
		restored.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals(1_760_000L, restored.realizedPnl());
	}

	@Test
	public void importCarriesOpenCostBasisButNotRealizedPnl()
	{
		// Session 1: buy+sell whips (realises P&L this session), then separately
		// buy darts that stay open (still-unsold cost basis) at export time.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals(1_760_000L, reconciler.realizedPnl());

		int dartId = 811;
		reconciler.onOfferUpdate(2, GeOfferState.BOUGHT, dartId, "Rune dart",
			100L, 100L, 100_000L, 1_000L, 3000L);

		Map<Integer, GeReconciler.CostBasisSnapshot> exported = reconciler.exportCostBasis();

		GeReconciler restored = new GeReconciler();
		restored.importCostBasis(exported);

		// realizedPnl is per-session: NOT carried by import even though the
		// original instance had realised a gain.
		assertEquals("realizedPnl must not be carried across a relog restore",
			0L, restored.realizedPnl());

		// But the still-open dart cost basis WAS carried: selling it now in the
		// "new session" realises the correct flip P&L from the old basis.
		restored.onOfferUpdate(3, GeOfferState.SOLD, dartId, "Rune dart",
			100L, 100L, 200_000L, 2_000L, 4000L);
		// Net proceeds/item = 2,000 - 40 (2% tax) = 1,960; profit = (1,960 - 1,000) * 100.
		assertEquals(96_000L, restored.realizedPnl());
	}

	@Test
	public void relogWithoutRestoreLosesBasisButRestoreRecoversFullFlipCredit()
	{
		// Session 1 (weeks ago): buy 10 whips, never sold.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		Map<Integer, GeReconciler.CostBasisSnapshot> exported = reconciler.exportCostBasis();

		// Relog WITHOUT restoring the ledger: reset() alone wipes the basis
		// (today's bug), so selling the weeks-old buy afterwards realises nothing.
		reconciler.reset();
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals("without restore the weeks-old buy's basis is lost -> zero flip credit",
			0L, reconciler.realizedPnl());

		// Relog WITH restore (the fix): reset() a fresh reconciler, then import
		// the exported ledger right after — the weeks-old buy survives the relog.
		GeReconciler restoredSession = new GeReconciler();
		restoredSession.reset();
		restoredSession.importCostBasis(exported);
		restoredSession.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals("with restore the weeks-old buy credits its full flip P&L in the new session",
			1_760_000L, restoredSession.realizedPnl());
	}

	// ----------------------------------------------- per-slot flip P&L (GE panel signed P&L row)

	@Test
	public void slotRealizedPnlIsAbsentForAnUntouchedSlot()
	{
		// A slot that has never seen an update has no offer at all, let alone a
		// flip: absent, not zero.
		assertEquals(OptionalLong.empty(), reconciler.slotRealizedPnl(7));
	}

	@Test
	public void slotRealizedPnlIsPositiveWhenFlipSoldAboveCostBasis()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);

		// Same 1,760,000 profit as the global realizedPnl() case, but read off
		// the selling slot specifically.
		assertEquals(OptionalLong.of(1_760_000L), reconciler.slotRealizedPnl(1));
		// The buy slot never sold anything, so it never became a flip.
		assertEquals(OptionalLong.empty(), reconciler.slotRealizedPnl(0));
	}

	@Test
	public void slotRealizedPnlIsNegativeWhenFlipSoldBelowCostBasis()
	{
		// Bought at 1.2M, sold at 1.0M: a genuine loss, not just the tax bite.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 2000L);

		// Net proceeds/item = 1,000,000 - 20,000 (2% tax) = 980,000;
		// (980,000 - 1,200,000) * 10 = -2,200,000.
		assertEquals(OptionalLong.of(-2_200_000L), reconciler.slotRealizedPnl(1));
	}

	@Test
	public void slotRealizedPnlIsSmallNegativeWhenSoldAtTheSameListedPriceItWasBoughtAt()
	{
		// THE USER'S REPORTED SCENARIO: sold at exactly the price it was bought
		// at. Today's UI renders this as an alarming full-red "loss"; the only
		// real loss is the 2% GE sales tax, which should show as a small red
		// figure, not a big one.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 2000L);

		// Net proceeds/item = 1,000,000 - 20,000 (2% tax) = 980,000;
		// (980,000 - 1,000,000) * 10 = -200,000 -- small relative to the 10M
		// position, and NEGATIVE (not the absent/neutral dump case).
		OptionalLong pnl = reconciler.slotRealizedPnl(1);
		assertTrue("must be a flip (present), not a dump", pnl.isPresent());
		assertEquals(-200_000L, pnl.getAsLong());
		assertTrue("must be a small loss relative to the 10M position",
			Math.abs(pnl.getAsLong()) < 1_000_000L);
	}

	@Test
	public void slotRealizedPnlIsAbsentForADump()
	{
		// Selling with no GE cost basis (looted/bank items) is not a flip: the
		// slot must report NO P&L at all, distinguishable from a break-even
		// flip (which would report a present, small-negative value instead).
		reconciler.onOfferUpdate(0, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 1000L);

		assertFalse("a dump must not be a present P&L, even a zero one",
			reconciler.slotRealizedPnl(0).isPresent());
		assertEquals(OptionalLong.empty(), reconciler.slotRealizedPnl(0));
	}

	@Test
	public void slotRealizedPnlIsAbsentForABuyOffer()
	{
		// Still buying/bought, never sold: nothing to realise yet.
		reconciler.onOfferUpdate(0, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 4L, 4_000_000L, 1_000_000L, 1000L);
		assertEquals(OptionalLong.empty(), reconciler.slotRealizedPnl(0));

		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1100L);
		assertEquals(OptionalLong.empty(), reconciler.slotRealizedPnl(0));
	}

	@Test
	public void slotRealizedPnlGrowsAsAPartiallyFilledSellOfferFills()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);

		// First partial fill: 4/10 sold at 1.2M.
		reconciler.onOfferUpdate(1, GeOfferState.SELLING, WHIP, "Abyssal whip",
			10L, 4L, 4_800_000L, 1_200_000L, 2000L);
		// Net/item = 1,200,000 - 24,000 (2% tax) = 1,176,000; (1,176,000 -
		// 1,000,000) * 4 = 704,000.
		assertEquals(OptionalLong.of(704_000L), reconciler.slotRealizedPnl(1));

		// Fills the rest: 10/10 total.
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 3000L);
		// The slot's P&L must have grown by the incremental 6 items' worth,
		// landing on the same total as a one-shot full sell.
		assertEquals(OptionalLong.of(1_760_000L), reconciler.slotRealizedPnl(1));
	}

	@Test
	public void slotRealizedPnlOnlyCountsTheMatchedFlipPortionWhenPartlyDumping()
	{
		// Bought 5, but the sell offer is for 10 (5 flipped, 5 dumped in the
		// same increment): only the matched 5 count toward this slot's P&L.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			5L, 5L, 5_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);

		// (1,176,000 net/item - 1,000,000) * 5 matched = 880,000.
		assertEquals(OptionalLong.of(880_000L), reconciler.slotRealizedPnl(1));
	}

	@Test
	public void slotRealizedPnlResetsWhenSlotIsReusedAfterEmpty()
	{
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals(OptionalLong.of(1_760_000L), reconciler.slotRealizedPnl(1));

		// Slot 1 is collected and clears...
		reconciler.onOfferUpdate(1, GeOfferState.EMPTY, 0, null,
			0L, 0L, 0L, 0L, 3000L);
		assertEquals("a cleared slot must not keep reporting the prior offer's P&L",
			OptionalLong.empty(), reconciler.slotRealizedPnl(1));

		// ...and is reused for a brand new BUY offer of a different item: it
		// must not inherit the previous sell's 1,760,000.
		int dartId = 811;
		reconciler.onOfferUpdate(1, GeOfferState.BOUGHT, dartId, "Rune dart",
			5000L, 5000L, 5000L, 1L, 4000L);
		assertEquals("a reused slot must not inherit the previous offer's P&L",
			OptionalLong.empty(), reconciler.slotRealizedPnl(1));
	}

	@Test
	public void slotRealizedPnlResetsWhenSlotIsReusedWithoutObservedEmpty()
	{
		// Same defensive case as slotReuseWithDifferentItemResetsTracking: the
		// slot is reused for a new offer without an observed EMPTY event
		// in-between (quantityTransacted regresses to signal it).
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals(OptionalLong.of(1_760_000L), reconciler.slotRealizedPnl(1));

		// Slot 1 reused for a fresh buy of the same item without an EMPTY:
		// quantityTransacted regresses from 10 back down to 3.
		reconciler.onOfferUpdate(1, GeOfferState.BUYING, WHIP, "Abyssal whip",
			10L, 3L, 3_000_000L, 1_000_000L, 3000L);
		assertEquals("a reused slot must not inherit the previous offer's P&L",
			OptionalLong.empty(), reconciler.slotRealizedPnl(1));
	}

	@Test
	public void globalRealizedPnlIsUnaffectedByPerSlotTracking()
	{
		// Two flips in two different slots: the global total must still be the
		// plain sum, exactly as before per-slot tracking existed.
		reconciler.onOfferUpdate(0, GeOfferState.BOUGHT, WHIP, "Abyssal whip",
			10L, 10L, 10_000_000L, 1_000_000L, 1000L);
		reconciler.onOfferUpdate(1, GeOfferState.SOLD, WHIP, "Abyssal whip",
			10L, 10L, 12_000_000L, 1_200_000L, 2000L);
		assertEquals(1_760_000L, reconciler.realizedPnl());

		int dartId = 811;
		reconciler.onOfferUpdate(2, GeOfferState.BOUGHT, dartId, "Rune dart",
			100L, 100L, 100_000L, 1_000L, 3000L);
		reconciler.onOfferUpdate(3, GeOfferState.SOLD, dartId, "Rune dart",
			100L, 100L, 200_000L, 2_000L, 4000L);
		// Net/item = 2,000 - 40 (2% tax) = 1,960; profit = (1,960 - 1,000) * 100 = 96,000.
		assertEquals(1_856_000L, reconciler.realizedPnl());

		// Each slot still reports its own share.
		assertEquals(OptionalLong.of(1_760_000L), reconciler.slotRealizedPnl(1));
		assertEquals(OptionalLong.of(96_000L), reconciler.slotRealizedPnl(3));
	}
}

package com.ospulse.xp;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class LevelTableTest
{
	@Test
	public void xpForLevelMatchesKnownAnchors()
	{
		assertEquals(0L, LevelTable.xpForLevel(1));
		assertEquals(83L, LevelTable.xpForLevel(2));
		assertEquals(1_154L, LevelTable.xpForLevel(10));
		assertEquals(101_333L, LevelTable.xpForLevel(50));
		assertEquals(6_517_253L, LevelTable.xpForLevel(92));
		assertEquals(13_034_431L, LevelTable.xpForLevel(99));
	}

	@Test
	public void xpForLevelClampsOutOfRangeLevels()
	{
		assertEquals(0L, LevelTable.xpForLevel(0));
		assertEquals(0L, LevelTable.xpForLevel(-5));
		assertEquals(13_034_431L, LevelTable.xpForLevel(100));
		assertEquals(13_034_431L, LevelTable.xpForLevel(126));
	}

	@Test
	public void levelForXpReturnsHighestReachedLevel()
	{
		assertEquals(1, LevelTable.levelForXp(0L));
		assertEquals(1, LevelTable.levelForXp(82L));
		assertEquals(2, LevelTable.levelForXp(83L));
		assertEquals(9, LevelTable.levelForXp(1_153L));
		assertEquals(10, LevelTable.levelForXp(1_154L));
		assertEquals(50, LevelTable.levelForXp(101_333L));
		assertEquals(91, LevelTable.levelForXp(6_517_252L));
		assertEquals(92, LevelTable.levelForXp(6_517_253L));
		assertEquals(98, LevelTable.levelForXp(13_034_430L));
		assertEquals(99, LevelTable.levelForXp(13_034_431L));
	}

	@Test
	public void levelForXpClampsToOneAndNinetyNine()
	{
		assertEquals(1, LevelTable.levelForXp(-1L));
		assertEquals(99, LevelTable.levelForXp(200_000_000L));
	}

	@Test
	public void tableRoundTripsForEveryLevel()
	{
		for (int level = 1; level <= 99; level++)
		{
			long xp = LevelTable.xpForLevel(level);
			assertEquals("level " + level + " at its threshold",
				level, LevelTable.levelForXp(xp));
			if (level > 1)
			{
				assertEquals("one xp below level " + level,
					level - 1, LevelTable.levelForXp(xp - 1));
			}
		}
	}
}

package com.ospulse.xp;

import org.junit.Before;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class XpTrackerTest
{
	private XpTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new XpTracker();
	}

	@Test
	public void gainedIsZeroImmediatelyAfterStart()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		baseline.put("ATTACK", 500_000L);
		tracker.start(baseline);

		assertTrue(tracker.gained().isEmpty());
		assertEquals(0L, tracker.totalGained());
	}

	@Test
	public void updateComputesGainAgainstBaseline()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		tracker.start(baseline);

		tracker.update("MAGIC", 1_050_000L);

		assertEquals(50_000L, (long) tracker.gained().get("MAGIC"));
		assertEquals(50_000L, tracker.totalGained());
	}

	@Test
	public void skillNotInBaselineUsesFirstSeenValueAsBaseline()
	{
		tracker.start(new HashMap<>());

		// First observation of WOODCUTTING should NOT itself count as gain.
		tracker.update("WOODCUTTING", 2_500_000L);
		assertTrue(tracker.gained().isEmpty());

		tracker.update("WOODCUTTING", 2_500_500L);
		assertEquals(500L, (long) tracker.gained().get("WOODCUTTING"));
	}

	@Test
	public void multipleSkillsTrackedIndependently()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		baseline.put("ATTACK", 500_000L);
		tracker.start(baseline);

		tracker.update("MAGIC", 1_010_000L);
		tracker.update("ATTACK", 500_000L); // no change

		Map<String, Long> gained = tracker.gained();
		assertEquals(1, gained.size());
		assertEquals(10_000L, (long) gained.get("MAGIC"));
		assertFalse(gained.containsKey("ATTACK"));
		assertEquals(10_000L, tracker.totalGained());
	}

	@Test
	public void restartingResetsBaselineAndCurrent()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		tracker.start(baseline);
		tracker.update("MAGIC", 1_100_000L);
		assertEquals(100_000L, tracker.totalGained());

		Map<String, Long> newBaseline = new HashMap<>();
		newBaseline.put("MAGIC", 1_100_000L);
		tracker.start(newBaseline);

		assertTrue(tracker.gained().isEmpty());
		assertEquals(0L, tracker.totalGained());
	}

	@Test
	public void currentXpReflectsBaselineThenLatestObservation()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		tracker.start(baseline);

		assertEquals(1_000_000L, tracker.currentXp("MAGIC"));
		assertEquals(0L, tracker.currentXp("ATTACK")); // never seen

		tracker.update("MAGIC", 1_050_000L);
		assertEquals(1_050_000L, tracker.currentXp("MAGIC"));
	}

	@Test
	public void lastActionXpIsZeroBeforeFirstGainEvent()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		tracker.start(baseline);

		assertEquals(0L, tracker.lastActionXp("MAGIC"));

		// First observation of an unbaselined skill establishes its baseline
		// and must NOT register as an action.
		tracker.update("WOODCUTTING", 2_500_000L);
		assertEquals(0L, tracker.lastActionXp("WOODCUTTING"));
	}

	@Test
	public void lastActionXpTracksMostRecentPositiveDelta()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		tracker.start(baseline);

		tracker.update("MAGIC", 1_000_042L);
		assertEquals(42L, tracker.lastActionXp("MAGIC"));

		tracker.update("MAGIC", 1_000_142L);
		assertEquals(100L, tracker.lastActionXp("MAGIC"));

		// A no-change or negative reading must not disturb the last action.
		tracker.update("MAGIC", 1_000_142L);
		assertEquals(100L, tracker.lastActionXp("MAGIC"));
		tracker.update("MAGIC", 900_000L);
		assertEquals(100L, tracker.lastActionXp("MAGIC"));
	}

	@Test
	public void restartingClearsLastActionXp()
	{
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		tracker.start(baseline);
		tracker.update("MAGIC", 1_000_042L);
		assertEquals(42L, tracker.lastActionXp("MAGIC"));

		Map<String, Long> newBaseline = new HashMap<>();
		newBaseline.put("MAGIC", 1_000_042L);
		tracker.start(newBaseline);

		assertEquals(0L, tracker.lastActionXp("MAGIC"));
		assertEquals(1_000_042L, tracker.currentXp("MAGIC"));
	}

	@Test
	public void neverGoesNegativeForXpDrops()
	{
		// XP should never drop in OSRS, but guard against it anyway: no
		// negative entries should ever appear in gained().
		Map<String, Long> baseline = new HashMap<>();
		baseline.put("MAGIC", 1_000_000L);
		tracker.start(baseline);

		tracker.update("MAGIC", 900_000L);

		assertFalse(tracker.gained().containsKey("MAGIC"));
		assertEquals(0L, tracker.totalGained());
	}
}

package com.ospulse.session;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class LootLedgerTest
{
	private static final int SHIELD = 1201;

	@Test
	public void heldLootValuedAtPickup()
	{
		LootLedger l = new LootLedger();
		l.recordLoot(SHIELD, 1, 22_400L);
		assertEquals(22_400L, l.lootValue());
	}

	@Test
	public void saleAtPickupPriceRealisesAfterTax()
	{
		LootLedger l = new LootLedger();
		l.recordLoot(SHIELD, 1, 22_400L);
		l.realiseSale(SHIELD, 1, 21_952L); // 22,400 - 2% tax
		assertEquals(21_952L, l.lootValue());
	}

	@Test
	public void saleHigherRaisesLootLowerLowersLoot()
	{
		LootLedger high = new LootLedger();
		high.recordLoot(SHIELD, 1, 22_400L);
		high.realiseSale(SHIELD, 1, 29_400L); // sold 30k, tax 600
		assertEquals(29_400L, high.lootValue());

		LootLedger low = new LootLedger();
		low.recordLoot(SHIELD, 1, 22_400L);
		low.realiseSale(SHIELD, 1, 9_800L); // sold 10k, tax 200
		assertEquals(9_800L, low.lootValue());
	}

	@Test
	public void saleQuantityCappedAtHeldSoPreOwnedExcessIgnored()
	{
		LootLedger l = new LootLedger();
		l.recordLoot(SHIELD, 1, 22_400L);
		// Sell 2 (1 looted + 1 pre-owned) for 43,904 net total: only the 1 looted realises.
		l.realiseSale(SHIELD, 2, 43_904L);
		assertEquals("only the looted unit's proportional proceeds count", 21_952L, l.lootValue());
	}

	@Test
	public void partialSaleLeavesRemainderAtPickup()
	{
		LootLedger l = new LootLedger();
		l.recordLoot(SHIELD, 50, 10_000L); // 500k held
		l.realiseSale(SHIELD, 20, 196_000L); // sold 20 @10k, tax 200/ea -> 9,800*20
		// 20 realised at 196,000 + 30 still held at 10,000 = 300,000 -> 496,000
		assertEquals(496_000L, l.lootValue());
	}

	@Test
	public void reverseLootRemovesAtAverageAndEmptiesCleanly()
	{
		LootLedger l = new LootLedger();
		l.recordLoot(SHIELD, 2, 10_000L);
		l.reverseLoot(SHIELD, 1);
		assertEquals(10_000L, l.lootValue());
		l.reverseLoot(SHIELD, 5); // over-reverse clamps
		assertEquals(0L, l.lootValue());
	}

	@Test
	public void resetClears()
	{
		LootLedger l = new LootLedger();
		l.recordLoot(SHIELD, 1, 22_400L);
		l.realiseSale(SHIELD, 1, 21_952L);
		l.reset();
		assertEquals(0L, l.lootValue());
	}
}

package com.ospulse.session;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SupplyClassifierTest
{
	@Test
	public void doseSuffixedPotionIsConsumable()
	{
		assertTrue(SupplyClassifier.isConsumable("Super antifire potion(4)"));
	}

	@Test
	public void cannonballsAreConsumableAmmo()
	{
		// Cannonballs are burned through like any other ammunition, so they
		// belong in "supplies used", not folded into profit/loot.
		assertTrue(SupplyClassifier.isConsumable("Cannonball"));
		assertTrue(SupplyClassifier.isConsumable("Granite cannonball"));
	}

	@Test
	public void chargedJewelleryWithHigherDoseSuffixIsNotConsumable()
	{
		// Charged jewellery uses (6)/(8) charge suffixes, which look
		// superficially similar to a dose potion's "(n)" suffix but must not
		// be swept up by the generic 1-4 dose fallback pattern.
		assertFalse(SupplyClassifier.isConsumable("Amulet of glory(6)"));
	}

	@Test
	public void fishingBaitAndFeathersAreConsumable()
	{
		// Bait is burned through per catch while fishing (e.g. a feather per
		// barbarian-rod catch), so it belongs in "supplies used" — previously
		// uncounted since it is neither food, ammo, potion nor rune.
		assertTrue(SupplyClassifier.isConsumable("Feather"));
		assertTrue(SupplyClassifier.isConsumable("Feathers"));
		assertTrue(SupplyClassifier.isConsumable("Stripy feather"));
		assertTrue(SupplyClassifier.isConsumable("Fishing bait"));
		assertTrue(SupplyClassifier.isConsumable("Sandworms"));
		assertTrue(SupplyClassifier.isConsumable("Fish offcuts"));
		assertTrue(SupplyClassifier.isConsumable("Raw karambwanji"));
	}

	@Test
	public void fishingToolsAreNotMistakenForBait()
	{
		// The bait pattern must not sweep up fishing TOOLS (rods/nets/harpoons),
		// which are equipment, not a consumed tracked-wealth stack.
		assertFalse(SupplyClassifier.isConsumable("Fishing rod"));
		assertFalse(SupplyClassifier.isConsumable("Barbarian rod"));
		assertFalse(SupplyClassifier.isConsumable("Small fishing net"));
		assertFalse(SupplyClassifier.isConsumable("Dragon harpoon"));
	}
}

