		// the unrealized line drops to 0 as the basis leaves tracked wealth.
		Map<Integer, ItemStack> held = new LinkedHashMap<>();
		held.put(RUNE_ITEM, new ItemStack(RUNE_ITEM, "Nature rune", 100L, 1_000L));
