		assertEquals("net profit counts both the sack loot and the genuine loot",
			160_000L, s.getNetProfit());
		assertEquals("net worth rose by both loot events",
			160_000L, s.getNetWorthDelta());
	}

	@Test
	public void unrelatedDepositsDoNotDrainStoredLootLedger()
	{
		// I-2: while stored loot is outstanding, bank rises already explained by
		// something else — a settling in-flight deposit (lagged bank reading) or
		// a same-observation tracked drop (live deposit) — must NOT drain the
		// stored-loot ledger. If they do, a later sack-empty to the inventory
		// finds an empty ledger and re-books the herbs as fresh loot (permanent
		// profit overstatement).
		engine.startSession(snap(10_000_000L, Collections.emptyMap(), 0L, false, 0L), 0L);

		// 10 ranarr looted into the herb sack (+80k Loot, held in the ledger).
		engine.update(snap(10_000_000L, Collections.emptyMap(), 0L, false, 1_000L),
			(GeAttributions) null,
			MovementSignals.builder().lootReceived(new LootReceipt(RANARR, 10L, 8_000L)).build(), 1_000L);

		WealthSnapshot atOpen = snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 2_000L);
		engine.setBankOpen(true, atOpen, 2_000L);
		engine.snapshot(atOpen, 0L, Collections.emptyMap(), 0L, 2_000L);

		// Unrelated 100k deposit whose bank reading LAGS one observation: the
		// tracked drop is held as an in-flight expectation, and the bank rise
		// that settles it must not touch the stored-loot ledger.
		engine.update(snap(9_900_000L, Collections.emptyMap(), 20_000_000L, true, 3_000L),
			Collections.emptySet(), 3_000L);
		engine.update(snap(9_900_000L, Collections.emptyMap(), 20_100_000L, true, 4_000L),
			Collections.emptySet(), 4_000L);

		// Second unrelated 100k deposit, both halves in the SAME observation:
		// the rise is explained by the tracked drop, not by the sack.
		engine.update(snap(9_800_000L, Collections.emptyMap(), 20_200_000L, true, 5_000L),
			Collections.emptySet(), 5_000L);

		engine.setBankOpen(false, snap(9_800_000L, Collections.emptyMap(), 20_200_000L, true, 6_000L), 6_000L);

		// Empty the sack to the INVENTORY while the bank is closed: the ledger
		// still holds the 10 ranarr, so this nets out — booked once, at receipt.
		Map<Integer, ItemStack> inv = items(new ItemStack(RANARR, "Grimy ranarr", 10L, 8_000L));
		WealthSnapshot afterEmpty = snap(9_880_000L, inv, 20_200_000L, true, 20_000L);
		engine.update(afterEmpty, Collections.emptySet(), 20_000L);

		SessionSnapshot s = engine.snapshot(afterEmpty, 0L, Collections.emptyMap(), 0L, 20_000L);
		assertEquals("sack contents are booked as loot exactly once", 80_000L, s.getLootValue());
		assertEquals("net profit must not be overstated by re-booked sack loot",
			80_000L, s.getNetProfit());
		assertEquals("net worth delta reflects only the 80k sack loot",
			80_000L, s.getNetWorthDelta());
	}

	/**
	 * The core accounting identity of the LOCKED session model: "Net worth
	 * change" must equal the SUM of its four components — Profit (loot minus
	 * supplies used), GE flip (realised), GE positions (unrealised
	 * mark-to-market on open/collectable GE offers) and Bank (bankValue minus
	 * its session anchor, residual of everything else). When it drifts, value
	 * is leaking (undercount) or being booked twice (overcount).
	 */
	private static void assertIdentity(String msg, SessionSnapshot s)
	{
		assertEquals(msg + " [netWorthDelta == netProfit + geRealizedPnl + gePositions + bankDelta]",
			s.getNetWorthDelta(),
			s.getNetProfit() + s.getGeRealizedPnl() + s.getGePositions() + s.getBankDelta());
	}

	@Test
	@Ignore("I-3 (known follow-up): value-only bank-rise true-up cannot attribute a "
		+ "deposit-box materialisation across multiple outstanding stored ids. A sound "
		+ "fix needs id+qty-level storage-empty signals. See Technical note KNOWN FOLLOW-UPS.")
	public void depositBoxCrossContainerEmptyKeepsIdentity()
	{
		// Two DIFFERENT storage containers outstanding at once (herb sack + gem
		// bag). One is emptied into a DEPOSIT BOX (bank-closed, value-only bank
		// true-up), the other into the INVENTORY (qty-exact per-id drawdown).
		// The value-only bank true-up draws greedily across ids by insertion
		// order, so it can debit the WRONG container — leaving the emptied one
		// double-counted (in the bank AND still in the ledger) and breaking the
		// accounting identity.
		engine.startSession(snap(10_000_000L, Collections.emptyMap(), 0L, false, 0L), 0L);

		// Anchor the bank at 20M, then close.
		WealthSnapshot atOpen = snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 100L);
		engine.setBankOpen(true, atOpen, 100L);
		engine.snapshot(atOpen, 0L, Collections.emptyMap(), 0L, 100L);
		engine.setBankOpen(false, snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 200L), 200L);

		// Herb sack fills FIRST (10 ranarr @ 8k = 80k), so it is the first ledger
		// entry the greedy bank drawdown will hit.
		engine.update(snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 1_000L),
			(GeAttributions) null,
			MovementSignals.builder().lootReceived(new LootReceipt(RANARR, 10L, 8_000L)).build(), 1_000L);
		// Gem bag fills second (5 uncut diamonds @ 2k = 10k).
		engine.update(snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 1_500L),
			(GeAttributions) null,
			MovementSignals.builder().lootReceived(new LootReceipt(UNCUT_DIAMOND, 5L, 2_000L)).build(), 1_500L);

		// Empty ONLY the gem bag into a deposit box: +10k bank reading first
		// arrives at the next open, beyond the post-close grace window.
		WealthSnapshot nextOpen = snap(10_000_000L, Collections.emptyMap(), 20_010_000L, true, 60_000L);
		engine.setBankOpen(true, nextOpen, 60_000L);
		engine.setBankOpen(false, snap(10_000_000L, Collections.emptyMap(), 20_010_000L, true, 60_100L), 60_100L);

		// Now empty the HERB SACK into the inventory (bank closed): 10 ranarr
		// land in tracked wealth, qty-matched against the ledger.
		Map<Integer, ItemStack> inv = items(new ItemStack(RANARR, "Grimy ranarr", 10L, 8_000L));
		WealthSnapshot afterEmpty = snap(10_080_000L, inv, 20_010_000L, true, 70_000L);
		engine.update(afterEmpty, Collections.emptySet(), 70_000L);
		SessionSnapshot s = engine.snapshot(afterEmpty, 0L, Collections.emptyMap(), 0L, 70_000L);

		assertIdentity("cross-container deposit-box empty", s);
		assertEquals("both containers' contents are booked as loot exactly once",
			90_000L, s.getLootValue());
		assertEquals("net worth rose by both loot events, no double count",
			90_000L, s.getNetWorthDelta());
	}

	@Test
	public void barrelDepositBoxEmptyWithSignalIsExactUnderPriceDriftAndOverflow()
	{
		// The fish barrel emits an EXACT storage-empty signal (id + qty) when
		// emptied at a bank/deposit box. The engine parks those precise entries in
		// the materialising buffer, so the bank rise draws them exactly — even when
		// the deposited stack is valued differently from the catch price — and, being
		// bank-bound, they are NOT netted against a later OVERFLOW catch that lands in
		// the inventory (which must book as fresh loot). Without the signal a
		// value-only bank true-up left a qty-desynced residue in storedLoot that
		// swallowed the overflow catch (permanent undercount, I-3).
		engine.startSession(snap(10_000_000L, Collections.emptyMap(), 0L, false, 0L), 0L);

		// Anchor bank at 20M, then close (a deposit-box trip is a closed-bank empty).
		WealthSnapshot atOpen = snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 100L);
		engine.setBankOpen(true, atOpen, 100L);
		engine.snapshot(atOpen, 0L, Collections.emptyMap(), 0L, 100L);
		engine.setBankOpen(false, snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 200L), 200L);

		// 100 trout stored in the barrel (+6,000 Loot, held in the ledger).
		engine.update(snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 1_000L),
			(GeAttributions) null,
			MovementSignals.builder().lootReceived(new LootReceipt(LEAPING_TROUT, 100L, 60L, true)).build(), 1_000L);

		// Emptied into a deposit box with the exact-contents signal: the 100 trout
		// move to the materialising buffer, awaiting the bank rise. Bank still closed.
		engine.update(snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 2_000L),
			(GeAttributions) null,
			MovementSignals.builder().storageEmptied(LEAPING_TROUT, 100L).build(), 2_000L);
		assertIdentity("after barrel emptied to deposit box (materialising, bank not yet risen)",
			engine.snapshot(snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 2_100L),
				0L, Collections.emptyMap(), 0L, 2_100L));

		// The bank reading arrives at the next open valuing the stack at only 5,000
		// (a 1,000 reprice down between catch and deposit). The materialising buffer
		// is drawn exactly; the price delta is a revaluation, not phantom loot.
		WealthSnapshot nextOpen = snap(10_000_000L, Collections.emptyMap(), 20_005_000L, true, 60_000L);
		engine.setBankOpen(true, nextOpen, 60_000L);
		engine.setBankOpen(false, snap(10_000_000L, Collections.emptyMap(), 20_005_000L, true, 60_100L), 60_100L);
		SessionSnapshot afterDeposit = engine.snapshot(
			snap(10_000_000L, Collections.emptyMap(), 20_005_000L, true, 60_200L),
			0L, Collections.emptyMap(), 0L, 60_200L);
		assertIdentity("after deposit-box empty under price drift", afterDeposit);
		assertEquals("Loot stays the booked catch value, not the repriced bank figure",
			6_000L, afterDeposit.getLootValue());

		// A later OVERFLOW catch lands in the inventory (barrel full): genuine fresh
		// loot, NOT swallowed by the already-banked materialising entries.
		Map<Integer, ItemStack> inv = items(new ItemStack(LEAPING_TROUT, "Leaping trout", 1L, 60L));
		WealthSnapshot afterOverflow = snap(10_000_060L, inv, 20_005_000L, true, 70_000L);
		engine.update(afterOverflow, Collections.emptySet(), 70_000L);
		SessionSnapshot s = engine.snapshot(afterOverflow, 0L, Collections.emptyMap(), 0L, 70_000L);

		assertIdentity("after overflow catch lands in inventory", s);
		assertEquals("overflow catch books as fresh loot, not eaten by a stale ledger",
			6_060L, s.getLootValue());
	}

	// ------------------------------------------- diff-loot reporting seam
	//
	// The loot feed does not derive its rows from LootReceived events alone —
	// it derives them from the engine's own inventory diff, so loot that
	// RuneLite never announces still shows up. These two pin the engine side
	// of that contract directly (real engine, no stubs), because the feed is
	// only as honest as lastUpdateDiffLoot() is.

	@Test
	public void unexplainedAppearIsReportedAsDiffLoot()
	{
		WealthSnapshot initial = snap(10_000_000L, Collections.emptyMap(), 0L, false, 0L);
		engine.startSession(initial, 0L);

		// A bird nest materialises with NO LootReceipt to explain it — the
		// auto-searched-nest seam. Nothing else can account for the quantity
		// (no GE attribution, no pending vanish, no ground parcel, no
		// purchase), so the diff must book it as loot and report it out.
		Map<Integer, ItemStack> tracked = items(new ItemStack(BIRD_NEST, "Bird nest", 2L, 5_000L));
		engine.update(snap(10_010_000L, tracked, 0L, false, 1_000L),
			(GeAttributions) null, MovementSignals.NONE, 1_000L);

		List<DiffLoot> diff = engine.lastUpdateDiffLoot();
		assertEquals("the unexplained appear is reported out", 1, diff.size());
		assertEquals(BIRD_NEST, diff.get(0).itemId);
		assertEquals(2L, diff.get(0).quantity);
		assertEquals(5_000L, diff.get(0).unitValue);
	}

	@Test
	public void diffLootReportsNothingWhileTheBankIsOpen()
	{
		WealthSnapshot initial = snap(10_000_000L, Collections.emptyMap(), 20_000_000L, true, 0L);
		engine.startSession(initial, 0L);

		// Book a real diff-loot residue FIRST, so the assertion below can only
		// pass by the banking update actually clearing it. Without this the
		// list would be trivially empty and the test would prove nothing.
		Map<Integer, ItemStack> nest = items(new ItemStack(BIRD_NEST, "Bird nest", 2L, 5_000L));
		engine.update(snap(10_010_000L, nest, 20_000_000L, true, 1_000L),
			(GeAttributions) null, MovementSignals.NONE, 1_000L);
		assertEquals("precondition: the nest booked as diff loot",
			1, engine.lastUpdateDiffLoot().size());

		// Now bank. update() early-returns while banking (a withdrawal is not
		// loot), so the PREVIOUS update's residue must not be readable a
		// second time — a re-read would double-book the nest into the feed.
		engine.setBankOpen(true, snap(10_010_000L, nest, 20_000_000L, true, 2_000L), 2_000L);
		Map<Integer, ItemStack> withdrawn = items(
			new ItemStack(BIRD_NEST, "Bird nest", 2L, 5_000L),
			new ItemStack(DRAGON_BONES, "Dragon bones", 10L, 10_000L));
		engine.update(snap(10_110_000L, withdrawn, 19_900_000L, true, 3_000L),
			(GeAttributions) null, MovementSignals.NONE, 3_000L);

		assertTrue("a banking update books no diff loot",
			engine.lastUpdateDiffLoot().isEmpty());
	}

	// ------------------------------------------- episode-scoped skilling P&L
	//
	// Bottom-up accounting (Profit = Loot − Supplies) silently discards the cost
	// of any input the SupplyClassifier does not recognise: it never matched a
	// consumable pattern, and reverseLoot retracts nothing because a herb
	// withdrawn from the bank was never looted. The crafted output is then
	// credited at full GE value, so Profit can only ever go up. Inside a
	// production episode — no loot, no GE, only conversion — a scoped value
	// delta is trustworthy, so these pin that scoped number.

	private static final int CLEAN_TOADFLAX = 2998;
	private static final int VIAL_OF_WATER = 227;
	private static final int TOADFLAX_UNF = 3002;
	private static final int COAL = 453;

	/** 10 herbs @ 8,000 + 10 vials @ 5 = 80,050 of tracked inputs on top of 10M. */
	private static Map<Integer, ItemStack> herbloreInputs()
	{
		return items(
			new ItemStack(CLEAN_TOADFLAX, "Clean toadflax", 10L, 8_000L),
			new ItemStack(VIAL_OF_WATER, "Vial of water", 10L, 5L));
	}

	private static Map<Integer, ItemStack> unfPotions(long unitValue)
	{
		return items(new ItemStack(TOADFLAX_UNF, "Toadflax potion(unf)", 10L, unitValue));
	}

	private static MovementSignals crafting()
	{
		return MovementSignals.builder().productionXp().productionAnimation().build();
	}

	@Test
	public void herbloreAtALossRegistersNegativeProfit()
	{
		// THE HEADLINE REGRESSION. 80,050 of inputs become 60,000 of unf potions
		// while the price is down: a real 20,050 loss. Before the episode ledger
		// the herbs cost nothing (no classifier match, never looted) and the
		// potions credited as 60,000 of loot, so this read as +60,000 profit.
		WealthSnapshot initial = snap(10_080_050L, herbloreInputs(), 0L, false, 0L);
		engine.startSession(initial, 0L);

		WealthSnapshot crafted = snap(10_060_000L, unfPotions(6_000L), 0L, false, 1_000L);
		engine.update(crafted, (GeAttributions) null, crafting(), 1_000L);

		SessionSnapshot s = engine.snapshot(crafted, 0L, Collections.emptyMap(), 0L, 1_000L);
		assertEquals("crafting at a loss must reduce Profit", -20_050L, s.getNetProfit());
		assertEquals("a manufactured potion is not loot", 0L, s.getLootValue());
		assertIdentity("herblore at a loss", s);
	}

	@Test
	public void herbloreStep1WithNoXpStillChargesTheHerb()
	{
		// Guards the exact hole that killed the XP-gate design. Clean herb +
		// Vial of water -> unf potion awards ZERO Herblore XP, and that step is
		// where the expensive herb goes. Animation is the ONLY signal here.
		WealthSnapshot initial = snap(10_080_050L, herbloreInputs(), 0L, false, 0L);
		engine.startSession(initial, 0L);

		MovementSignals animationOnly = MovementSignals.builder().productionAnimation().build();
		WealthSnapshot crafted = snap(10_060_000L, unfPotions(6_000L), 0L, false, 1_000L);
		engine.update(crafted, (GeAttributions) null, animationOnly, 1_000L);

		SessionSnapshot s = engine.snapshot(crafted, 0L, Collections.emptyMap(), 0L, 1_000L);
		assertEquals("animation alone must open the episode — an XP-only trigger "
			+ "misses unf-making entirely", -20_050L, s.getNetProfit());
		assertIdentity("herblore step 1, no XP", s);
	}

	@Test
	public void profitableCraftingStillReadsPositive()
