package com.ospulse.combat;

/**
 * A small exact-rational helper used for the OSRS combat maths' many
 * documented gear-bonus fractions (7/6, 6/5, 23/20, ...). Using integer
 * numerator/denominator arithmetic instead of {@code double} avoids
 * floating-point representation error changing a floor() result at an exact
 * boundary (e.g. 6 * 7/6 must floor to exactly 7, not 6 via a
 * 6.999999999-style rounding artifact) — correctness of the floor steps is
 * the entire point of this package.
 */
final class Fraction {
    static final Fraction ONE = new Fraction(1, 1);

    final long numerator;
    final long denominator;

    Fraction(long numerator, long denominator) {
        if (denominator == 0) {
            throw new IllegalArgumentException("denominator cannot be 0");
        }
        this.numerator = numerator;
        this.denominator = denominator;
    }

    /** floor(value * this) using exact integer division (value assumed non-negative). */
    long applyFloor(long value) {
        return Math.floorDiv(value * numerator, denominator);
    }

    /** Combines two fractions multiplicatively (used when two multiplicative bonuses legitimately stack). */
    Fraction times(Fraction other) {
        return new Fraction(this.numerator * other.numerator, this.denominator * other.denominator);
    }

    double asDouble() {
        return (double) numerator / (double) denominator;
    }

    /** True if this fraction is exactly 1 (no bonus) — all fractions in this package are constructed in this simple canonical form. */
    boolean isOne() {
        return numerator == denominator;
    }
}

package com.ospulse.combat;

import java.util.Locale;

/**
 * The in-game weapon "type" (combat-options category) a weapon belongs to — the
 * one thing that determines which attack styles it offers (see
 * {@link WeaponStyles}). Names mirror weirdgloop {@code osrs-dps-calc}'s
 * {@code EquipmentCategory} enum; {@link #fromDataName(String)} parses the
 * lower-cased strings stored in the bundled {@code weapon_categories.min.json}.
 *
 * <p>RuneLite's {@code ItemEquipmentStats} exposes attack bonuses and speed but
 * not the category, so it is resolved purely from the weapon item id via
 * {@link WeaponCategoryRepository} — no {@code Client}/{@code ItemManager} read
 * and no client thread required, which is also why the same lookup serves
 * hypothetical (not-yet-worn) weapons for the future optimiser.
 */
public enum WeaponCategory {
    TWO_HANDED_SWORD,
    AXE,
    BANNER,
    BLADED_STAFF,
    BLASTER,
    BLUDGEON,
    BLUNT,
    BOW,
    BULWARK,
    CHINCHOMPA,
    CLAW,
    CROSSBOW,
    DAGGER,
    FLAIL,
    GUN,
    MULTI_MELEE,
    PARTISAN,
    PICKAXE,
    POLEARM,
    POLESTAFF,
    POWERED_STAFF,
    POWERED_WAND,
    SALAMANDER,
    SCYTHE,
    SLASH_SWORD,
    SPEAR,
    SPIKED,
    STAB_SWORD,
    STAFF,
    THROWN,
    UNARMED,
    WHIP;

    /**
     * Parses a lower-cased category string from the bundled data (e.g.
     * {@code "slash sword"}, {@code "2h sword"}, {@code "chinchompas"}) into an
     * enum constant, or {@code null} for an unknown/blank value (caller falls
     * back to {@link #UNARMED}).
     */
    public static WeaponCategory fromDataName(String raw) {
        if (raw == null) {
            return null;
        }
        switch (raw.trim().toLowerCase(Locale.ROOT)) {
            case "2h sword":
                return TWO_HANDED_SWORD;
            case "axe":
                return AXE;
            case "banner":
                return BANNER;
            case "bladed staff":
                return BLADED_STAFF;
            case "blaster":
                return BLASTER;
            case "bludgeon":
                return BLUDGEON;
            case "blunt":
                return BLUNT;
            case "bow":
                return BOW;
            case "bulwark":
                return BULWARK;
            case "chinchompas":
                return CHINCHOMPA;
            case "claw":
                return CLAW;
            case "crossbow":
                return CROSSBOW;
            case "dagger":
                return DAGGER;
            case "flail":
                return FLAIL;
            case "gun":
                return GUN;
            case "multi-melee":
                return MULTI_MELEE;
            case "partisan":
                return PARTISAN;
            case "pickaxe":
                return PICKAXE;
            case "polearm":
                return POLEARM;
            case "polestaff":
                return POLESTAFF;
            case "powered staff":
                return POWERED_STAFF;
            case "powered wand":
                return POWERED_WAND;
            case "salamander":
                return SALAMANDER;
            case "scythe":
                return SCYTHE;
            case "slash sword":
                return SLASH_SWORD;
            case "spear":
                return SPEAR;
            case "spiked":
                return SPIKED;
            case "stab sword":
                return STAB_SWORD;
            case "staff":
                return STAFF;
            case "thrown":
                return THROWN;
            case "unarmed":
            case "":
                return UNARMED;
            case "whip":
                return WHIP;
            default:
                return null;
        }
    }
}

package com.ospulse.combat;

/**
 * The output of a {@link DpsCalculator#compute} call.
 */
public final class DpsResult {
    private final int maxHit;
    private final double accuracy;
    private final double dps;
    private final double avgHit;
    private final double ttkSeconds;
    private final double overkillPerKill;
    private final boolean baseEstimate;

    public DpsResult(int maxHit, double accuracy, double dps, double avgHit, double ttkSeconds,
                     double overkillPerKill, boolean baseEstimate) {
        this.maxHit = maxHit;
        this.accuracy = accuracy;
        this.dps = dps;
        this.avgHit = avgHit;
        this.ttkSeconds = ttkSeconds;
        this.overkillPerKill = overkillPerKill;
        this.baseEstimate = baseEstimate;
    }

    /**
     * The standard displayed maximum hit for this setup — the conventional/
     * nominal figure the OSRS Wiki and other calculators (GearScape, etc.)
     * quote, matching {@code DpsCalculator.finishFang}'s precedent of always
     * reporting the TRUE (unshrunk) max hit "matching how the wiki/GearScape
     * display it" rather than some other in-model number.
     *
     * <p><b>Rare damage-multiplying procs are deliberately excluded from
     * this number</b>, even though they raise the true largest possible hit.
     * Worked example: the Keris partisan family's 1/51 "puncturing" chance
     * triples the landed damage (see {@link KerisTripleRoll}), so the true
     * largest possible hit on a given attack is {@code 3 * maxHit()} — but
     * {@link KerisTripleRoll#finish} returns the ordinary pre-triple
     * {@code visibleMaxHit} here, not {@code 3x} it, because reporting the
     * tripled figure for a 1-in-51 event would make this number disagree
     * with every other calculator and with the number players actually
     * quote for the weapon. The proc is NOT silently dropped, though — it is
     * fully reflected in {@link #dps()}, {@link #avgHit()}, {@link
     * #ttkSeconds()}, and {@link #overkillPerKill()}, all of which fold in
     * its extra expected damage. Only this accessor reports the
     * conventional/nominal figure instead of the true theoretical maximum.
     */
    public int maxHit() {
        return maxHit;
    }

    /** Probability (0..1) that any single attack lands. */
    public double accuracy() {
        return accuracy;
    }

    /** Expected damage per second. */
    public double dps() {
        return dps;
    }

    /** Expected damage per attack (accounts for accuracy and misses) — GearScape's "Avg Hit". */
    public double avgHit() {
        return avgHit;
    }

    /** Expected time-to-kill the target in seconds (monster hp / dps); 0 when dps is 0. */
    public double ttkSeconds() {
        return ttkSeconds;
    }

    /**
     * Expected damage wasted on the killing blow (rolled beyond the target's
     * remaining HP), in hitpoints per kill — see
     * {@code DamageDistribution.expectedOverkill} for the model.
     */
    public double overkillPerKill() {
        return overkillPerKill;
    }

    /** True if one or more unmodelled (Tier B/C+) effects were skipped, so this number is a lower/approximate bound. */
    public boolean baseEstimate() {
        return baseEstimate;
    }

    @Override
    public String toString() {
        return "DpsResult{maxHit=" + maxHit + ", accuracy=" + accuracy + ", dps=" + dps
                + ", avgHit=" + avgHit + ", ttkSeconds=" + ttkSeconds
                + ", overkillPerKill=" + overkillPerKill + ", baseEstimate=" + baseEstimate + '}';
    }
}

