package com.ospulse.combat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.reflect.TypeToken;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Resolves an equippable item id &lt;-&gt; its display name and
 * {@code EquipmentInventorySlot} ordinal, from the bundled
 * {@code equipment_index.min.json} (see that resource's README for
 * provenance). This is the name/slot half of the item-search index the
 * Phase 2 what-if swap picker and the Phase 3 optimiser's candidate pool
 * both need; {@link EquipmentStatsRepository} supplies the numeric bonuses
 * for the same id space (every id here is guaranteed to also resolve there —
 * see the README).
 *
 * <p>Pure and thread-safe to read from anywhere (including the EDT): static
 * bundled data, no {@code Client}/{@code ItemManager} dependency. Mirrors
 * {@link EquipmentStatsRepository}/{@link WeaponCategoryRepository}'s
 * bundled-resource singleton pattern.
 */
public final class EquipmentIndexRepository {
    private static final String RESOURCE_PATH = "/com/ospulse/combat/equipment_index.min.json";

    private static volatile EquipmentIndexRepository instance;

    private final List<Entry> entries;
    private final Map<Integer, Entry> byItemId;
    private final Map<String, Integer> idByLowercaseName;
    private final Map<String, List<Integer>> idsByLowercaseName;

    private EquipmentIndexRepository(List<Entry> entries) {
        this.entries = Collections.unmodifiableList(entries);
        Map<Integer, Entry> byId = new HashMap<>();
        Map<String, Integer> byName = new HashMap<>();
        Map<String, List<Integer>> allByName = new HashMap<>();
        for (Entry e : entries) {
            byId.put(e.itemId(), e);
            String key = e.name().toLowerCase(Locale.ROOT);
            // First entry wins on a name collision (several ids can share a
            // display name, e.g. multiple imbue-source id families for the
            // same item) — deterministic file-order preference.
            byName.putIfAbsent(key, e.itemId());
            // idsForName (below) keeps every id sharing the name, in file
            // order, for callers that must check ALL of them (e.g. an
            // ownership check against a name with several reward-source ids —
            // idForName's single-id pick would silently miss a match).
            allByName.computeIfAbsent(key, k -> new ArrayList<>()).add(e.itemId());
        }
        this.byItemId = Collections.unmodifiableMap(byId);
        this.idByLowercaseName = Collections.unmodifiableMap(byName);
        Map<String, List<Integer>> frozen = new HashMap<>();
        for (Map.Entry<String, List<Integer>> e : allByName.entrySet()) {
            frozen.put(e.getKey(), Collections.unmodifiableList(e.getValue()));
        }
        this.idsByLowercaseName = Collections.unmodifiableMap(frozen);
    }

    /** Shared, lazily-initialised singleton loaded from the bundled resource. */
    public static EquipmentIndexRepository getInstance() {
        EquipmentIndexRepository result = instance;
        if (result == null) {
            synchronized (EquipmentIndexRepository.class) {
                result = instance;
                if (result == null) {
                    instance = result = loadFromResource(RESOURCE_PATH);
                }
            }
        }
        return result;
    }

    /** Loads a repository from an arbitrary classpath resource (mainly for tests). */
    static EquipmentIndexRepository loadFromResource(String resourcePath) {
        Gson gson = BundledGson.get();
        try (Reader reader = new InputStreamReader(requireResource(resourcePath), StandardCharsets.UTF_8)) {
            Type mapType = new TypeToken<Map<String, JsonArray>>() {
            }.getType();
            Map<String, JsonArray> raw = gson.fromJson(reader, mapType);
            List<Entry> parsed = new ArrayList<>();
            if (raw != null) {
                for (Map.Entry<String, JsonArray> e : raw.entrySet()) {
                    JsonArray row = e.getValue();
                    if (row == null || row.size() < 2) {
                        continue; // malformed row — treated as "no data"
                    }
                    int itemId;
                    try {
                        itemId = Integer.parseInt(e.getKey().trim());
                    } catch (NumberFormatException ignored) {
                        continue;
                    }
                    JsonElement nameEl = row.get(0);
                    JsonElement slotEl = row.get(1);
                    if (nameEl == null || nameEl.isJsonNull() || slotEl == null || slotEl.isJsonNull()) {
                        continue;
                    }
                    boolean isTwoHanded = row.size() > 2 && !row.get(2).isJsonNull() && row.get(2).getAsBoolean();
                    parsed.add(new Entry(itemId, nameEl.getAsString(), slotEl.getAsInt(), isTwoHanded));
                }
            }
            return new EquipmentIndexRepository(parsed);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to load equipment index data from " + resourcePath, e);
        }
    }

    private static InputStream requireResource(String resourcePath) {
        InputStream in = EquipmentIndexRepository.class.getResourceAsStream(resourcePath);
        if (in == null) {
            throw new IllegalStateException("Bundled resource not found on classpath: " + resourcePath);
        }
        return in;
    }

    public int size() {
        return entries.size();
    }

    /** The name+slot entry for an item id, or {@code null} if unknown/unindexed. */
    public Entry entryFor(int itemId) {
        return byItemId.get(itemId);
    }

    /**
     * Case-insensitive EXACT name -&gt; item id lookup (as opposed to
     * {@link #searchSlot}'s substring search), or {@code null} if no indexed
     * item has that display name. Used to resolve a variant's plain-name
     * counterpart (e.g. stripping the " (f)"/" (i)" suffix — see
     * {@code GearSection.ownedPriceMap}) without hard-coding per-item ids.
     */
    public Integer idForName(String name) {
        if (name == null) {
            return null;
        }
        return idByLowercaseName.get(name.toLowerCase(Locale.ROOT));
    }

    /**
     * Every item id sharing {@code name} (case-insensitive), in file order —
     * the multi-id counterpart to {@link #idForName}. Several display names
     * genuinely have more than one backing id (e.g. an imbued ring or a
     * slayer helmet has one id per reward source), so a caller that needs to
     * check "do I own ANY item called X" (as opposed to "resolve the name to
     * a single canonical id") must check all of them, not just
     * {@link #idForName}'s single file-order pick. Never {@code null}; empty
     * if no indexed item has that name.
     */
    public List<Integer> idsForName(String name) {
        if (name == null) {
            return Collections.emptyList();
        }
        List<Integer> ids = idsByLowercaseName.get(name.toLowerCase(Locale.ROOT));
        return ids == null ? Collections.emptyList() : ids;
    }

    /** All indexed (computable) item ids — the optimiser's candidate universe. */
    public java.util.Set<Integer> allItemIds() {
        return Collections.unmodifiableSet(byItemId.keySet());
    }

    /**
     * Every indexed item that fits the given {@code EquipmentInventorySlot}
     * ordinal, in file order. Never {@code null}; empty if the slot ordinal
     * indexes nothing (e.g. one of the internal-only ordinals).
     */
    public List<Entry> forSlot(int slotOrdinal) {
        List<Entry> out = new ArrayList<>();
        for (Entry e : entries) {
            if (e.slotOrdinal() == slotOrdinal) {
                out.add(e);
            }
        }
        return out;
    }

    /**
     * Case-insensitive substring search over a slot's items by display name,
     * empty query returns every item in the slot (matching
     * {@code MonsterRepository.search}'s convention).
     */
    public List<Entry> searchSlot(int slotOrdinal, String query) {
        String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
        List<Entry> out = new ArrayList<>();
        for (Entry e : entries) {
            if (e.slotOrdinal() == slotOrdinal
                    && (needle.isEmpty() || e.name().toLowerCase(Locale.ROOT).contains(needle))) {
                out.add(e);
            }
        }
        return out;
    }

    /** One equippable item's display name, equipment-slot ordinal and two-handedness. Immutable. */
    public static final class Entry {
        private final int itemId;
        private final String name;
        private final int slotOrdinal;
        private final boolean twoHanded;

        Entry(int itemId, String name, int slotOrdinal, boolean twoHanded) {
            this.itemId = itemId;
            this.name = name;
            this.slotOrdinal = slotOrdinal;
            this.twoHanded = twoHanded;
        }

        public int itemId() {
            return itemId;
        }

        public String name() {
            return name;
        }

        /** {@code net.runelite.api.EquipmentInventorySlot} ordinal this item is worn in. */
        public int slotOrdinal() {
            return slotOrdinal;
        }

        /**
         * True for a two-handed weapon (weapon-slot entries only — always
         * {@code false} for every other slot). Lets the EDT-only what-if
         * picker enforce shield exclusivity without an {@code ItemManager}
         * call (see the resource README).
         */
        public boolean isTwoHanded() {
            return twoHanded;
        }
    }
}

package com.ospulse.combat;

/**
 * Demonbane weapons and their vs-demon multipliers, per each weapon's OSRS
 * Wiki page: the melee Silverlight → Emberlight sword line and the ranged
 * Scorching bow. The bonus applies ONLY when the target carries the
 * {@link MonsterAttribute#DEMON} attribute and only for the weapon's own
 * combat style family (see {@link #appliesTo(CombatStyle)}).
 *
 * <p><b>Stacking (per the wiki DPS calculator, weirdgloop
 * {@code PlayerVsNPCCalc.ts} — our GearScape-parity oracle):</b> demonbane is
 * the weapon's OWN passive and does NOT live in the single salve/slayer
 * target-bonus slot. It is applied as a separate multiplicative floor step
 * AFTER that slot on both the attack roll and max hit — so it stacks with the
 * on-task slayer helm and with salve. One documented exception: for the
 * RANGED max hit only, the Scorching bow's +30% damage folds ADDITIVELY into
 * an on-task IMBUED slayer helm/black mask's 23/20 step (a single floor of
 * (23+6)/20 = 29/20 — the wiki's "total damage boost of 45%"); see
 * {@link DpsCalculator}.
 *
 * <p>The accuracy multiplier scales the attack roll; the damage multiplier
 * scales max hit. Silverlight/Darklight boost damage only (+60%); Arclight
 * and Emberlight boost both (+70%); the Scorching bow boosts both (+30%);
 * Burning claws boost both (+5%). Cerberus and almost all demons take the
 * full multiplier — the documented exception is Duke Sucellus (30%
 * demonbane resistance), modelled via {@link Monster#demonbaneResistPercent()}
 * and applied in {@code DpsCalculator}'s demonbane step (see that class for
 * the exact formula).
 *
 * <p><b>Scope:</b> the sword line, the Scorching bow and Burning claws (melee,
 * +5% accuracy AND damage, item id 29577 — cache-verified, see
 * {@code GearVariants}) are wired; the magic demonbane path (Purging staff,
 * which doubles demonbane-SPELL bonuses rather than granting a flat passive)
 * is deferred.
 *
 * @see <a href="https://oldschool.runescape.wiki/w/Demonbane_weapons">Demonbane weapons</a>
 * @see <a href="https://oldschool.runescape.wiki/w/Emberlight">Emberlight</a> (+70% accuracy and damage)
 * @see <a href="https://oldschool.runescape.wiki/w/Scorching_bow">Scorching bow</a> (+30% accuracy and damage, damage additive with slayer helm (i))
 */
public enum DemonbaneWeapon {
    NONE(Fraction.ONE, Fraction.ONE, null),
    /** Silverlight (melee): +60% damage only. */
    SILVERLIGHT(Fraction.ONE, new Fraction(8, 5), CombatStyle.STAB),
    /** Darklight (melee): +60% damage only. */
    DARKLIGHT(Fraction.ONE, new Fraction(8, 5), CombatStyle.STAB),
    /** Arclight (melee): +70% accuracy AND damage. */
    ARCLIGHT(new Fraction(17, 10), new Fraction(17, 10), CombatStyle.STAB),
    /** Emberlight (melee): +70% accuracy AND damage. */
    EMBERLIGHT(new Fraction(17, 10), new Fraction(17, 10), CombatStyle.STAB),
    /** Scorching bow (ranged): +30% accuracy AND damage. */
    SCORCHING_BOW(new Fraction(13, 10), new Fraction(13, 10), CombatStyle.RANGED),
    /** Burning claws (melee, slash): +5% accuracy AND damage. */
    BURNING_CLAWS(new Fraction(21, 20), new Fraction(21, 20), CombatStyle.SLASH);

    private final Fraction accuracyMult;
    private final Fraction damageMult;
    /** Style family marker: any melee style for the sword line, RANGED for the bow. */
    private final CombatStyle styleFamily;

    DemonbaneWeapon(Fraction accuracyMult, Fraction damageMult, CombatStyle styleFamily) {
        this.accuracyMult = accuracyMult;
        this.damageMult = damageMult;
        this.styleFamily = styleFamily;
    }

    /** True when this weapon's demonbane passive applies to an attack of the given style. */
    public boolean appliesTo(CombatStyle style) {
        if (this == NONE || style == null) {
            return false;
        }
        // The sword line is melee: its passive covers all three melee styles.
        if (styleFamily != null && styleFamily.isMelee()) {
            return style.isMelee();
        }
        return style == styleFamily;
    }

    /** Multiplier on the attack roll vs demons (1/1 for the damage-only Silver/Darklight). */
    public Fraction accuracyMult() {
        return accuracyMult;
    }

    /** Multiplier on max hit vs demons. */
    public Fraction damageMult() {
        return damageMult;
    }
}

package com.ospulse.combat;

import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * A monster's combat-relevant stats: the data RuneLite does not expose
 * (defensive bonuses, magic level, attributes), sourced from a bundled/
 * refreshed data snapshot via {@link MonsterRepository}.
 */
public final class Monster {
    private final String name;
    private final List<Integer> npcIds;
    private final int hitpoints;
    private final int defenceLevel;
    private final int dstab;
    private final int dslash;
    private final int dcrush;
    private final int dmagic;
    private final int drange;
    private final int magicLevel;
    private final int size;
    private final Set<MonsterAttribute> attributes;
    private final Integer attackSpeedTicks;
    private final int demonbaneResistPercent;
    private final String weaknessElement;
    private final int weaknessSeverity;
    private final boolean wildernessTarget;
    private final String lookupName;

    private Monster(Builder b) {
        this.name = b.name;
        this.npcIds = Collections.unmodifiableList(b.npcIds);
        this.hitpoints = b.hitpoints;
        this.defenceLevel = b.defenceLevel;
        this.dstab = b.dstab;
        this.dslash = b.dslash;
        this.dcrush = b.dcrush;
        this.dmagic = b.dmagic;
        this.drange = b.drange;
        this.magicLevel = b.magicLevel;
        // Upstream uses 0 (and, defensively, any non-positive value) to mean
        // "size unknown" - never a genuine monster footprint, since an NPC
        // cannot be 0x0. Normalise to the smallest real size, 1x1, here at
        // the model boundary so every consumer (Colossal blade's
        // +2*min(size,5) bonus, ScytheCascade's hit count, etc.) sees a
        // realistic size without each call site having to special-case it.
        this.size = b.size > 0 ? b.size : 1;
        this.attributes = Collections.unmodifiableSet(EnumSet.copyOf(
                b.attributes.isEmpty() ? EnumSet.noneOf(MonsterAttribute.class) : b.attributes));
        this.attackSpeedTicks = b.attackSpeedTicks;
        this.demonbaneResistPercent = b.demonbaneResistPercent;
        this.weaknessElement = b.weaknessElement;
        this.weaknessSeverity = b.weaknessSeverity;
        this.wildernessTarget = b.wildernessTarget;
        this.lookupName = b.lookupName != null ? b.lookupName : b.name;
    }

    public String name() {
        return name;
    }

    public List<Integer> npcIds() {
        return npcIds;
    }

    public int hitpoints() {
        return hitpoints;
    }

    public int defenceLevel() {
        return defenceLevel;
    }

    public int dstab() {
        return dstab;
    }

    public int dslash() {
        return dslash;
    }

    public int dcrush() {
        return dcrush;
    }

    public int dmagic() {
        return dmagic;
    }

    public int drange() {
        return drange;
    }

    /** Defensive bonus relevant to the given attacking style (dstab/dslash/dcrush/drange, or dmagic for MAGIC). */
    public int defenceBonus(CombatStyle style) {
        switch (style) {
            case STAB:
                return dstab;
            case SLASH:
                return dslash;
            case CRUSH:
                return dcrush;
            case RANGED:
                return drange;
            case MAGIC:
                return dmagic;
            default:
                throw new IllegalArgumentException("Unknown style: " + style);
        }
    }

    public int magicLevel() {
        return magicLevel;
    }

    public int size() {
        return size;
    }

    public Set<MonsterAttribute> attributes() {
        return attributes;
    }

    public boolean isUndead() {
        return attributes.contains(MonsterAttribute.UNDEAD);
    }

    public boolean isDemon() {
        return attributes.contains(MonsterAttribute.DEMON);
    }

    /** True for draconic creatures (dragons, hydras, wyverns, Great Olm) — gates Dragon Hunter and similar dragonbane effects. */
    public boolean isDragon() {
        return attributes.contains(MonsterAttribute.DRAGON);
    }

    /** Attack speed in ticks, if known (not always present in the source data). */
    public Integer attackSpeedTicks() {
        return attackSpeedTicks;
    }

    /**
     * Percent by which this monster resists the demonbane weapon BONUS
     * (0-100; default 0 = no resistance). E.g. Duke Sucellus is 30: a
     * demonbane weapon's excess-over-1 multiplier is scaled down by
     * {@code (1 - resistPercent / 100)} — see {@code DpsCalculator}'s
     * demonbane apply step for the exact formula. Populated from the bundled
     * monster data when present; otherwise 0 (mechanism is data-driven, so it
     * activates automatically once a monster's data carries a non-zero value).
     */
    public int demonbaneResistPercent() {
        return demonbaneResistPercent;
    }

    /**
     * This monster's elemental weakness element ({@code "WIND"}/{@code "WATER"}/
     * {@code "EARTH"}/{@code "FIRE"}, matching {@link Spell.Element} names), or
     * {@code null} when this monster has no elemental weakness. Populated from
     * the bundled monster data's {@code weakness.element} (upstream's
     * {@code "air"} is mapped to {@code "WIND"} at minify time — see the
     * monsters.min.json.README.md field-mapping table).
     */
    public String weaknessElement() {
        return weaknessElement;
    }

    /**
     * The elemental-weakness damage bonus, as a percent added to the caster's
     * magic-damage percent when the cast spell's {@link Spell.Element} matches
     * {@link #weaknessElement()} (0 when {@link #weaknessElement()} is
     * {@code null}) — see {@code DpsCalculator.computeMagic}.
     */
    public int weaknessSeverity() {
        return weaknessSeverity;
    }

    /**
     * True when this target should receive the revenant-weapon Wilderness
     * bonus (see {@code RevenantWeapon}/{@code DpsCalculator}) — either
     * because it is a genuinely Wilderness-exclusive monster ({@link
     * WildernessMonsterRepository}'s curated set), or because it is a
     * SYNTHETIC "(Wilderness)" twin of a both-locations monster (see {@link
     * #lookupName()} and {@link WildernessVariantMonsterRepository}) that
     * the player explicitly selected in preference to the ordinary,
     * non-Wilderness entry of the same species. An ordinary both-locations
     * monster's own (non-synthetic) entry always returns {@code false} here
     * — selecting it means the player is NOT claiming to be fighting it in
     * the Wilderness.
     */
    public boolean isWildernessTarget() {
        return wildernessTarget;
    }

    /**
     * The name every OTHER lookup (per-target damage caps/penalties via
     * {@code MonsterCombatRequirementRepository}, required-gear reminders
     * via {@code MonsterGearOverrideRepository}, consumables reminders via
     * {@code MonsterConsumablesRepository}) should resolve against — equal
     * to {@link #name()} for an ordinary monster, but for a SYNTHETIC
     * "(Wilderness)" variant this returns the REAL underlying monster's
     * name instead (e.g. "Black dragon (Level 227)" for the "Black dragon
     * (Wilderness)" synthetic entry).
     *
     * <p>This is the reverse-map a synthetic target needs so it behaves
     * identically to its base monster in every respect except the
     * revenant-weapon bonus: a Wilderness Black dragon must still gate on
     * the same weapon requirements, get the same required-gear warnings,
     * and get the same dragonfire consumables reminder as the ordinary
     * Black dragon (Level 227) — only {@link #isWildernessTarget()} and the
     * DISPLAY name ({@link #name()}) differ. Callers resolving identity-based
     * data must use this method, never {@link #name()}, for that reason.
     */
    public String lookupName() {
        return lookupName;
    }

    /**
     * Builds a new {@link Monster} that copies every field of {@code
     * source} — used ONLY to synthesize a Wilderness-selectable "twin" of a
     * both-locations monster (see {@link WildernessVariantMonsterRepository}):
     * the caller then overrides {@link Builder#name}, {@link
     * Builder#wildernessTarget}, and {@link Builder#lookupName} on the
     * returned builder before calling {@link Builder#build()}.
     */
    public static Builder builderFrom(Monster source) {
        Builder b = new Builder();
        b.name = source.name;
        b.npcIds = source.npcIds;
        b.hitpoints = source.hitpoints;
        b.defenceLevel = source.defenceLevel;
        b.dstab = source.dstab;
        b.dslash = source.dslash;
        b.dcrush = source.dcrush;
        b.dmagic = source.dmagic;
        b.drange = source.drange;
        b.magicLevel = source.magicLevel;
        b.size = source.size;
        b.attributes = EnumSet.copyOf(source.attributes.isEmpty()
                ? EnumSet.noneOf(MonsterAttribute.class) : source.attributes);
        b.attackSpeedTicks = source.attackSpeedTicks;
        b.demonbaneResistPercent = source.demonbaneResistPercent;
        b.weaknessElement = source.weaknessElement;
        b.weaknessSeverity = source.weaknessSeverity;
        b.wildernessTarget = source.wildernessTarget;
        b.lookupName = source.lookupName;
        return b;
    }

    public static Builder builder() {
        return new Builder();
    }

    public static final class Builder {
        private String name;
        private List<Integer> npcIds = Collections.emptyList();
        private int hitpoints;
        private int defenceLevel;
        private int dstab;
        private int dslash;
        private int dcrush;
        private int dmagic;
        private int drange;
        private int magicLevel;
        private int size = 1;
        private Set<MonsterAttribute> attributes = EnumSet.noneOf(MonsterAttribute.class);
