package com.ospulse.combat.optimizer;

import net.runelite.api.gameval.ItemID;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Charge-variant families: groups every charge level of one chargeable item
 * (e.g. Amulet of glory (1) … (6), the uncharged amulet, and the infinite
 * Amulet of eternal glory) so the optimiser can treat the whole family as a
 * SINGLE item for ownership and recommendation — the equivalent of RuneLite's
 * Equipment Inventory Setups "fuzzy matching" toggle, enabled automatically.
 *
 * <h2>Why this can't come from the bundled index</h2>
 * The plugin's {@code equipment_index} deliberately flattens every glory charge
 * to the same display name ("Amulet of glory") with the same slot, and
 * {@code equipment_stats} gives every charge byte-identical combat bonuses — so
 * neither the family membership NOR the charge ORDER is recoverable from bundled
 * data alone (a low charge is indistinguishable from a full one there).
 *
 * <h2>Clean-room source of the ordering</h2>
 * Membership and order are taken from RuneLite's public
 * {@link net.runelite.api.gameval.ItemID} constants — an API the plugin already
 * depends on. Those constant NAMES are a mechanical transcription of the game's
 * own item names, so they carry the charge count the display names dropped:
 * {@code AMULET_OF_GLORY} (uncharged) &lt; {@code AMULET_OF_GLORY_1} &lt; … &lt;
 * {@code AMULET_OF_GLORY_6} &lt; {@code AMULET_OF_GLORY_INF} (infinite). Each
 * family below lists its members highest-charge FIRST, so the first owned member
 * walking the array is always the most-charged one.
 *
 * <p>The "higher suffix = more charges" convention is corroborated by two
 * independent signals so it is not an assumption: (1) the original glory ids
 * ascend with charge (1704 uncharged → 1712 the (4)); (2) the trimmed family's
 * ids <em>descend</em> with charge (10362 uncharged → 10354 the (4)), which
 * proves the item-id order is NOT the rank and the name suffix is — the two
 * families would disagree if we ranked by id.
 *
 * <h2>Scope: DPS-safe families only</h2>
 * Only families whose members share IDENTICAL combat bonuses are included, so
 * collapsing a family can never change a DPS result — the pick is purely about
 * which owned charge to surface. Both glory families satisfy this (verified
 * against bundled {@code equipment_stats}). Weapon charge families
 * (trident/sanguinesti/shadow/blowpipe) and stat-changing "variants" (serpentine
 * helm charged vs uncharged, ring of suffering imbue/recoil) are deliberately
 * EXCLUDED: their charged and uncharged forms have different combat stats, so
 * "treat as one item" would misstate achievable DPS. This class is a registry —
 * adding a family is one line once its members are known to be stat-identical.
 */
public final class ChargeFamilies
{
	/**
	 * Amulet of glory — every charge shares byte-identical combat bonuses; the
	 * charge count only governs teleports, so the highest-charge owned member is
	 * always the one to equip. Highest-charge first (infinite → 6 → … → uncharged).
	 */
	private static final int[] GLORY = {
		ItemID.AMULET_OF_GLORY_INF, // Amulet of eternal glory (infinite charges)
		ItemID.AMULET_OF_GLORY_6,
		ItemID.AMULET_OF_GLORY_5,
		ItemID.AMULET_OF_GLORY_4,
		ItemID.AMULET_OF_GLORY_3,
		ItemID.AMULET_OF_GLORY_2,
		ItemID.AMULET_OF_GLORY_1,
		ItemID.AMULET_OF_GLORY, // uncharged
	};

	/** Amulet of glory (t) — trimmed cosmetic twin of {@link #GLORY}; same stat-identity, its own family (distinct ids, no infinite variant). */
	private static final int[] GLORY_TRIMMED = {
		ItemID.TRAIL_AMULET_OF_GLORY_6,
		ItemID.TRAIL_AMULET_OF_GLORY_5,
		ItemID.TRAIL_AMULET_OF_GLORY_4,
		ItemID.TRAIL_AMULET_OF_GLORY_3,
		ItemID.TRAIL_AMULET_OF_GLORY_2,
		ItemID.TRAIL_AMULET_OF_GLORY_1,
		ItemID.TRAIL_AMULET_OF_GLORY, // uncharged (t)
	};

	private static final int[][] FAMILIES = { GLORY, GLORY_TRIMMED };

	/** member item id -> its family array (highest-charge first). */
	private static final Map<Integer, int[]> BY_MEMBER;

	static
	{
		Map<Integer, int[]> byMember = new HashMap<>();
		for (int[] family : FAMILIES)
		{
			for (int memberId : family)
			{
				byMember.put(memberId, family);
			}
		}
		BY_MEMBER = Collections.unmodifiableMap(byMember);
	}

	private ChargeFamilies()
	{
	}

	/** Test-only view of the raw family tables (each highest-charge first). Package-private. */
	static int[][] familiesForTest()
	{
		return FAMILIES;
	}

	/** Whether {@code itemId} is a charge-variant of a known family. */
	public static boolean isMember(int itemId)
	{
		return BY_MEMBER.containsKey(itemId);
	}

	/**
	 * The charge family {@code itemId} belongs to, highest-charge first, or
	 * {@code null} if {@code itemId} isn't a known charge-variant. The returned
	 * array is shared/immutable — treat it as read-only.
	 */
	public static int[] familyOf(int itemId)
	{
		return BY_MEMBER.get(itemId);
	}

	/**
	 * The highest-charge member of {@code itemId}'s family that the player OWNS
	 * and hasn't excluded, or {@code null} when {@code itemId} isn't a family
	 * member or no owned, non-excluded member exists. Because members are stored
	 * highest-charge first, this is the first array entry present in
	 * {@code owned} and absent from {@code excluded}.
	 *
	 * @param itemId   any member of the family to resolve within
	 * @param owned    item ids the player owns (never {@code null})
	 * @param excluded item ids the player excluded from suggestions, or {@code null}
	 */
	public static Integer bestOwnedMember(int itemId, Set<Integer> owned, Set<Integer> excluded)
	{
		int[] family = BY_MEMBER.get(itemId);
		if (family == null || owned == null)
		{
			return null;
		}
		for (int memberId : family)
		{
			if (owned.contains(memberId) && (excluded == null || !excluded.contains(memberId)))
			{
				return memberId;
			}
		}
		return null;
	}
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.CombatStyle;
import com.ospulse.combat.EquipmentStatsRepository;
import com.ospulse.combat.WeaponCategoryRepository;
import com.ospulse.combat.WeaponStyle;

/**
 * Pure item-id scoring heuristics shared by {@link GearOptimizer}'s pruning
 * and tie-breaking passes: cheap proxies computed straight from
 * {@link EquipmentStatsRepository}/{@link WeaponCategoryRepository} bundled
 * data, with no dependency on a search {@code Request} or any in-progress
 * loadout. Method bodies are unchanged from their previous home in
 * {@code GearOptimizer}.
 */
public final class CandidateScore {
    private CandidateScore() {
    }

    /**
     * A DPS-tie tie-break score: the sum of an item's every offensive, defensive
     * and prayer bonus. Used to fill DPS-neutral slots (B9-2) with the best
     * wearable owned piece on a DPS tie; an empty/unknown slot scores lowest so
     * any real item beats "wear nothing".
     */
    public static int tieBreakScore(int itemId) {
        if (itemId <= 0) {
            return Integer.MIN_VALUE;
        }
        EquipmentStatsRepository.Stats s = EquipmentStatsRepository.getInstance().statsFor(itemId);
        if (s == null) {
            return Integer.MIN_VALUE + 1;
        }
        return s.astab() + s.aslash() + s.acrush() + s.amagic() + s.arange()
                + s.dstab() + s.dslash() + s.dcrush() + s.dmagic() + s.drange()
                + s.str() + s.rstr() + (int) s.mdmg() + s.prayer();
    }

    /** The prayer bonus of one item (0 if unknown), for the ammo-slot-ignored-by-weapon ranking exception. */
    public static int prayerBonusOf(int itemId) {
        EquipmentStatsRepository.Stats s = EquipmentStatsRepository.getInstance().statsFor(itemId);
        return s == null ? 0 : s.prayer();
    }

    /** True when the weapon id's real combat options include a style of {@code type} ({@code null} type = no constraint). */
    public static boolean weaponSupportsStyle(int weaponId, CombatStyle type) {
        if (type == null) {
            return true;
        }
        for (WeaponStyle style : WeaponCategoryRepository.getInstance().stylesForItem(weaponId)) {
            if (style.type() == type) {
                return true;
            }
        }
        return false;
    }

    /**
     * The cheap pruning proxy for one item. Unconstrained ({@code style ==
     * null}): the historical sum of every offensive bonus. Style-constrained:
     * only the bonuses that actually feed that style's DPS — otherwise e.g. a
     * MAGIC-constrained search would prune Ancestral (small raw totals) in
     * favour of melee armour whose big slash/str numbers are irrelevant to the
     * constraint. Weights: magic damage is a percentage (1% is worth far more
     * than 1 accuracy point) and ranged strength scales the max hit directly
     * (keeps ammo/blessing candidates ranked above accuracy-only picks).
     */
    public static int proxyOffensiveScore(int itemId, CombatStyle style) {
        EquipmentStatsRepository.Stats s = EquipmentStatsRepository.getInstance().statsFor(itemId);
        if (s == null) {
            return Integer.MIN_VALUE;
        }
        if (style == null) {
            return s.astab() + s.aslash() + s.acrush() + s.arange() + s.amagic() + s.str() + s.rstr() + (int) s.mdmg();
        }
        switch (style) {
            case STAB:
                return s.astab() + s.str();
            case SLASH:
                return s.aslash() + s.str();
            case CRUSH:
                return s.acrush() + s.str();
            case RANGED:
                return s.arange() + 2 * s.rstr();
            case MAGIC:
                return s.amagic() + (int) (10 * s.mdmg());
            default:
                return s.astab() + s.aslash() + s.acrush() + s.arange() + s.amagic() + s.str() + s.rstr() + (int) s.mdmg();
        }
    }
}

package com.ospulse.combat.optimizer;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A hypothetical per-slot item-id override on top of a live loadout — Phase 2's
 * "what-if" state (see the design spec section 2). Purely a
 * {@code slotOrdinal -> itemId} map; it is never mutated into the real
 * {@code GearSnapshot}, only merged with the live gear at compute time by
 * {@link WhatIfLoadout#apply}.
 *
 * <p>Immutable — every mutator returns a new instance, which keeps the
 * {@code GearSection} UI state simple to reason about (undo/redo would be
 * trivial if ever wanted) and makes this trivially unit-testable without any
 * Swing/RuneLite dependency.
 */
public final class LoadoutOverride {
    /**
     * Sentinel override value meaning "this slot is explicitly EMPTIED
     * (unequipped)" — distinct from having no override at all. Needed because
     * the override map can only <em>replace</em> a slot, so 2H/shield
     * exclusivity could not otherwise unequip a LIVE weapon/shield that has no
     * override entry (see {@link #withWeaponSlot}/{@link #withShieldSlot}). Real
     * item ids are always {@code > 0}, so {@code 0} is unambiguous.
     */
    public static final int EMPTIED = 0;

    private static final LoadoutOverride EMPTY = new LoadoutOverride(Collections.emptyMap());

    private final Map<Integer, Integer> bySlot;

    private LoadoutOverride(Map<Integer, Integer> bySlot) {
        this.bySlot = bySlot;
    }

    /** No overrides — the what-if loadout equals the live loadout. */
    public static LoadoutOverride empty() {
        return EMPTY;
    }

    /** True when no slot is overridden. */
    public boolean isEmpty() {
        return bySlot.isEmpty();
    }

    /**
     * The overridden item id for a slot, or {@code -1} if that slot is not
     * overridden. A return of {@code 0} ({@link #EMPTIED}) means the slot is
     * overridden to <em>empty</em> (explicitly unequipped) — callers already
     * treat {@code id <= 0} as an empty slot.
     */
    public int itemIdFor(int slotOrdinal) {
        Integer id = bySlot.get(slotOrdinal);
        return id == null ? -1 : id;
    }

    public boolean hasOverride(int slotOrdinal) {
        return bySlot.containsKey(slotOrdinal);
    }

    /**
     * Returns a new override with {@code slotOrdinal} set to {@code itemId}
     * (equip a hypothetical item in that slot). {@code itemId <= 0} clears the
     * slot back to "no override" — equivalent to {@link #withoutSlot}.
     */
    public LoadoutOverride withSlot(int slotOrdinal, int itemId) {
        if (itemId <= 0) {
            return withoutSlot(slotOrdinal);
        }
        Map<Integer, Integer> next = new LinkedHashMap<>(bySlot);
        next.put(slotOrdinal, itemId);
        return new LoadoutOverride(next);
    }

    /**
     * Returns a new override with {@code slotOrdinal} explicitly EMPTIED
     * (unequipped). Unlike {@link #withoutSlot} — which clears the override so
     * the LIVE item shows again — this forces the slot empty in the effective
     * loadout, which is what 2H/shield exclusivity needs to unequip a live
     * weapon/shield the override map could not otherwise reach.
     */
    public LoadoutOverride withEmptiedSlot(int slotOrdinal) {
        Map<Integer, Integer> next = new LinkedHashMap<>(bySlot);
        next.put(slotOrdinal, EMPTIED);
        return new LoadoutOverride(next);
    }

    /** Returns a new override with {@code slotOrdinal}'s override cleared ("reset slot" — live gear shows again). */
    public LoadoutOverride withoutSlot(int slotOrdinal) {
        if (!bySlot.containsKey(slotOrdinal)) {
            return this;
        }
        Map<Integer, Integer> next = new LinkedHashMap<>(bySlot);
        next.remove(slotOrdinal);
        return next.isEmpty() ? EMPTY : new LoadoutOverride(next);
    }

    /**
     * Two-handed weapon / shield exclusivity: equipping a 2H weapon in the
     * WEAPON slot must clear any SHIELD override (and vice versa — equipping a
     * shield while a 2H weapon is overridden must clear the weapon override),
     * matching in-game behaviour. {@code weaponIsTwoHanded} is resolved by the
     * caller (see {@link WhatIfLoadout#isTwoHanded}) since this class has no
     * item-data dependency.
     *
     * <p>A 2H weapon EMPTIES the shield slot ({@link #withEmptiedSlot}) rather
     * than merely clearing its override — otherwise a LIVE shield (with no
     * override entry) would survive into the effective loadout alongside the 2H
     * weapon, an impossible in-game combination whose summed bonuses inflate DPS.
     */
    public LoadoutOverride withWeaponSlot(int weaponSlotOrdinal, int shieldSlotOrdinal, int itemId, boolean itemIsTwoHanded) {
        LoadoutOverride next = withSlot(weaponSlotOrdinal, itemId);
        return itemIsTwoHanded ? next.withEmptiedSlot(shieldSlotOrdinal) : next;
    }

    /**
     * Shield-slot exclusivity counterpart: equipping ANY shield while the
     * current effective weapon (live-or-overridden) is two-handed must clear
     * the weapon override back to live gear, since a 2H weapon cannot coexist
     * with a shield. {@code currentWeaponIsTwoHanded} is resolved by the
     * caller from the CURRENT effective weapon (live gear, unless already
     * overridden).
     *
     * <p>Equipping a shield over a two-handed weapon EMPTIES the weapon slot
     * ({@link #withEmptiedSlot}) rather than clearing its override — otherwise a
     * LIVE 2H weapon (no override entry) would survive alongside the shield, the
     * exact bug where the optimiser recommended e.g. a buckler on top of a live
     * blowpipe and summed both sets of bonuses.
     */
    public LoadoutOverride withShieldSlot(int weaponSlotOrdinal, int shieldSlotOrdinal, int itemId, boolean currentWeaponIsTwoHanded) {
        LoadoutOverride next = withSlot(shieldSlotOrdinal, itemId);
        return currentWeaponIsTwoHanded ? next.withEmptiedSlot(weaponSlotOrdinal) : next;
    }

    /** All overridden slot ordinals (unspecified order — this is a value type, not a UI model). */
    public int[] overriddenSlots() {
        int[] out = new int[bySlot.size()];
        int i = 0;
        for (Integer slot : bySlot.keySet()) {
            out[i++] = slot;
        }
        Arrays.sort(out);
        return out;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof LoadoutOverride)) {
            return false;
        }
        return bySlot.equals(((LoadoutOverride) o).bySlot);
    }

    @Override
    public int hashCode() {
        return bySlot.hashCode();
    }

    @Override
    public String toString() {
        return "LoadoutOverride" + bySlot;
    }
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.EquipmentIndexRepository;
import com.ospulse.combat.EquipmentStatsRepository;
import com.ospulse.session.GearMapper;

/**
 * An EDT-safe {@link GearMapper.SlotStatsLookup} backed entirely by bundled
 * data ({@link EquipmentStatsRepository} for numeric bonuses,
 * {@link EquipmentIndexRepository} for the two-handed flag) — no
 * {@code ItemManager}/{@code Client} call, so (unlike
 * {@code SessionTracker.lookupSlotStats}, which needs the client thread for
 * RuneLite's {@code getItemStats}) this can resolve an ARBITRARY item id,
 * owned or not, from the Swing EDT.
 *
 * <p>This is what lets Phase 2's what-if swap picker and Phase 3's optimiser
 * search recompute {@code EquipmentStats} for a hypothetical loadout entirely
 * on the EDT, reusing {@link GearMapper#buildEquipmentStats} unchanged.
 *
 * <p>Trade-off vs the live lookup: an item present in RuneLite's item stats
 * but absent from the bundled cache data resolves to {@code null} here (no
 * wiki-derived fallback, since that requires {@code ItemManager}) — in
 * practice {@code equipment_stats.min.json} covers the full cache-derived
 * item set (3501 items at last regen), so this only matters for a brand-new
 * item release before the bundled data refreshes.
 */
public final class BundledSlotStatsLookup implements GearMapper.SlotStatsLookup {
    public static final BundledSlotStatsLookup INSTANCE = new BundledSlotStatsLookup();

    private BundledSlotStatsLookup() {
    }

    @Override
    public GearMapper.SlotStats statsFor(int itemId) {
        EquipmentStatsRepository.Stats cache = EquipmentStatsRepository.getInstance().statsFor(itemId);
        if (cache == null) {
            return null;
        }
        EquipmentIndexRepository.Entry indexEntry = EquipmentIndexRepository.getInstance().entryFor(itemId);
        boolean isTwoHanded = indexEntry != null && indexEntry.isTwoHanded();
        return new GearMapper.SlotStats(
                cache.astab(), cache.aslash(), cache.acrush(), cache.amagic(), cache.arange(),
                cache.dstab(), cache.dslash(), cache.dcrush(), cache.dmagic(), cache.drange(),
                cache.str(), cache.rstr(), cache.mdmg(), cache.prayer(), cache.aspeed(), isTwoHanded);
    }
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.EquipmentIndexRepository;
import com.ospulse.combat.EquipmentStats;
import com.ospulse.session.GearMapper;

/**
 * Merges a live loadout's worn item ids with a {@link LoadoutOverride} and
 * recomputes {@link EquipmentStats} for the resulting hypothetical loadout —
 * the Phase 2 "what-if per-slot swap" engine (design spec section 2). Pure
 * and EDT-safe: every lookup is bundled data (see
 * {@link BundledSlotStatsLookup}), so this never touches the real gear and
 * never requires the client thread.
 */
public final class WhatIfLoadout {
    /** {@code EquipmentInventorySlot.WEAPON} ordinal. */
    public static final int WEAPON_SLOT = 3;
    /** {@code EquipmentInventorySlot.SHIELD} ordinal. */
    public static final int SHIELD_SLOT = 5;
    /** {@code EquipmentInventorySlot.AMMO} ordinal. */
    public static final int AMMO_SLOT = 13;

    private WhatIfLoadout() {
    }

    /**
     * The effective per-slot item ids: {@code liveItemIds} with every
     * overridden slot replaced by the override's item id. Never mutates
     * {@code liveItemIds}.
     */
    public static int[] effectiveItemIds(int[] liveItemIds, LoadoutOverride override) {
        int[] effective = liveItemIds.clone();
        for (int slot : override.overriddenSlots()) {
            if (slot >= 0 && slot < effective.length) {
                effective[slot] = override.itemIdFor(slot);
            }
        }
        return effective;
    }

    /**
     * Recomputes {@link EquipmentStats} for {@code liveItemIds} with
     * {@code override} applied, using only bundled data (no
     * {@code ItemManager}/client-thread requirement) — safe to call from the
     * Swing EDT.
     */
    public static EquipmentStats buildEquipmentStats(int[] liveItemIds, LoadoutOverride override) {
        int[] effective = effectiveItemIds(liveItemIds, override);
        return GearMapper.buildEquipmentStats(effective, WEAPON_SLOT, BundledSlotStatsLookup.INSTANCE);
    }

    /**
     * True if {@code itemId} is a two-handed weapon per the bundled equipment
     * index; {@code false} for an unknown/non-weapon id (bare fists, an
     * unindexed item). Used to enforce weapon/shield exclusivity when the
     * user overrides the weapon or shield slot in the UI.
     */
    public static boolean isTwoHanded(int itemId) {
        EquipmentIndexRepository.Entry entry = EquipmentIndexRepository.getInstance().entryFor(itemId);
        return entry != null && entry.isTwoHanded();
    }

    /**
     * Applies a weapon-slot swap to {@code override}, enforcing 2H/shield
     * exclusivity: equipping a two-handed weapon clears any shield override.
     */
    public static LoadoutOverride equipWeapon(LoadoutOverride override, int weaponItemId) {
        return override.withWeaponSlot(WEAPON_SLOT, SHIELD_SLOT, weaponItemId, isTwoHanded(weaponItemId));
    }

    /**
     * Applies a shield-slot swap to {@code override}, enforcing 2H/shield
     * exclusivity: equipping a shield while the CURRENT effective weapon
     * (override if set, else the live weapon id) is two-handed clears the
     * weapon override back to live gear (matching in-game unequip behaviour).
     */
    public static LoadoutOverride equipShield(LoadoutOverride override, int[] liveItemIds, int shieldItemId) {
        int currentWeaponId = override.hasOverride(WEAPON_SLOT)
                ? override.itemIdFor(WEAPON_SLOT)
                : (WEAPON_SLOT < liveItemIds.length ? liveItemIds[WEAPON_SLOT] : -1);
        return override.withShieldSlot(WEAPON_SLOT, SHIELD_SLOT, shieldItemId, isTwoHanded(currentWeaponId));
    }
}

package com.ospulse.combat.optimizer;

import com.ospulse.combat.AmmoCompatibility;
import com.ospulse.combat.CombatStyle;
import com.ospulse.combat.DpsCalculator;
import com.ospulse.combat.DpsResult;
import com.ospulse.combat.EquipmentIndexRepository;
import com.ospulse.combat.EquipmentRequirementsRepository;
import com.ospulse.combat.EquipmentStats;
import com.ospulse.combat.Monster;
import com.ospulse.combat.MonsterCombatRequirement;
import com.ospulse.combat.PlayerCombat;
import com.ospulse.combat.Spell;
import com.ospulse.combat.WeaponCategoryRepository;
import com.ospulse.combat.WeaponStyle;
import com.ospulse.session.GearMapper;

import net.runelite.api.gameval.ItemID;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Phase 3 gear optimiser (design spec section 3): given a starting loadout, a
 * target, and a candidate pool (owned items + anything affordable within a
 * gp budget), searches for the best-DPS loadout and ranks the upgrades over
 * the owned-only baseline by DPS-per-gp.
 *
 * <p>Pure and EDT-safe: every candidate lookup is bundled data
 * ({@link EquipmentIndexRepository} for the slot/name/2h index,
 * {@link BundledSlotStatsLookup} for numeric bonuses via
 * {@link GearMapper#buildEquipmentStats}), so this never needs the client
 * thread and can be driven straight from a Swing action handler (though
 * callers should still run a large search off the EDT — see the class-level
 * "Threading" note below — since the search itself can take tens of
 * milliseconds per slot at the default candidate width).
 *
 * <h2>Search strategy</h2>
 * <p>Per the design spec: prune each slot's candidates to the top-N by a
 * cheap per-style proxy bonus (kept small enough that {@code owned} and
 * {@code included} items are never pruned away, since those are mandatory
 * "you already have it / you demanded it" candidates regardless of how they
 * rank), then greedy-seed (pick each slot's best candidate independently,
 * ignoring interactions) followed by local search — repeatedly try every
 * single-slot swap and keep the first improving move, until a full pass
 * finds no improving swap (bounded by {@link #MAX_LOCAL_SEARCH_PASSES} to
 * guarantee termination). This is a heuristic, NOT an exhaustive search: set
 * effects (Void) are evaluated correctly because {@code EquipmentStats} is
 * rebuilt from the FULL loadout on every candidate evaluation (no per-slot
 * additive shortcut), but the local search can in principle miss a
 * multi-slot-simultaneous improvement that no single-slot swap reveals
 * (e.g. two pieces that only help DPS when equipped together and neither
 * alone). This is the same trade-off the design spec calls out ("greedy seed
 * then local search") to keep the search responsive in a side panel.
 *
 * <h2>Weapon slot special-casing</h2>
 * <p>A weapon candidate changes the AVAILABLE attack styles/spells, unlike
 * every other slot which only changes bonuses under a fixed style. So for
 * the weapon slot specifically, each candidate weapon is evaluated at its
 * OWN best style/spell (mirroring {@code GearSection}'s ranked style
 * picker), not the incumbent weapon's style — an upgrade search that only
 * compared different weapons under one fixed style would systematically
 * undervalue a weapon whose best style differs from the current one (e.g.
 * comparing a stab weapon only via a Slash style). Non-weapon slots use
 * whatever style/spell the WEAPON side of the current candidate loadout
 * resolves to.
 */
public final class GearOptimizer {
    /** Equipment slot ordinals actually searched — mirrors GearSection.SLOT_GRID's non-decorative entries. */
    public static final int[] SEARCHABLE_SLOTS = {0, 1, 2, 3, 4, 5, 7, 9, 10, 12, 13};

    /** Default per-slot candidate width after pruning (owned/included items are exempt — see class javadoc). */
    public static final int DEFAULT_CANDIDATES_PER_SLOT = 12;

    /** Ammo equipment slot ordinal — mirrors net.runelite.api.EquipmentInventorySlot.AMMO (see GearMapper). */
    private static final int AMMO_SLOT = 13;

    private static final int MAX_LOCAL_SEARCH_PASSES = 6;

    private GearOptimizer() {
    }

    /**
     * One resolved candidate: an item id with its GE price (0 for
     * owned/untradeable — owned items are always "affordable" regardless of
     * price since no purchase is needed).
     */
    public static final class Candidate {
        private final int itemId;
        private final long price;
        private final boolean owned;

        public Candidate(int itemId, long price, boolean owned) {
            this.itemId = itemId;
            this.price = price;
            this.owned = owned;
        }

        public int itemId() {
            return itemId;
        }

        /** GE price (0 if owned/untradeable); irrelevant to affordability when {@link #owned()}. */
        public long price() {
            return price;
        }

        public boolean owned() {
            return owned;
        }
    }

    /**
     * Resolves an item id's GE price. The design spec says "reuse whatever
     * price source the existing code already uses" — that's
     * {@code ItemManager.getItemPrice}/{@code RuneLiteItemValuation.unitValue},
     * both client-thread-only. This seam lets the caller supply a
     * pre-resolved price map (or any other source) so the optimiser itself
     * stays free of any {@code ItemManager}/client-thread dependency and can
     * run entirely off bundled data plus this one caller-supplied function.
     */
    @FunctionalInterface
    public interface PriceSource {
        /**
         * GE price for {@code itemId}. {@code 0} (or negative) is treated as
         * FREE/affordable regardless of budget — the convention owned/untradeable
         * items use (see {@link Candidate}'s javadoc and
         * {@code buildCandidatesForSlot}'s {@code price > request.budget} check,
         * which a {@code 0} price always passes). To mark a non-owned item as
         * unaffordable (e.g. unknown/unpriced), return a value greater than any
         * realistic budget, such as {@code Long.MAX_VALUE} — returning {@code 0}
         * for that case would incorrectly make the item look free.
         */
        long priceFor(int itemId);

        /** A price source that treats every item as free — useful for tests and an owned-only search. */
        static PriceSource zero() {
            return itemId -> 0L;
        }
    }

    /**
     * Search inputs (design spec section 3 "Inputs"). Immutable; build with
     * {@link Builder}.
     */
    public static final class Request {
        private final int[] liveItemIds;
        private final Monster target;
        private final long budget;
        private final Set<Integer> owned;
        private final Set<Integer> exclude;
        private final Set<Integer> include;
        private final int candidatesPerSlot;
        private final PlayerCombat.Builder playerTemplate;
        private final PriceSource priceSource;
        private final PriceSource riskValueSource;
        private final int expensiveItemCount;
        private final long expensiveItemThreshold;
        private final CombatStyle style;
        private final Spell.SpellBook spellBook;
        private final MonsterCombatRequirement combatRequirement;
        private final java.util.Map<String, Integer> playerBaseLevels;
        private final java.util.Map<Integer, Long> ownedItemPrices;

        private Request(Builder b) {
            this.liveItemIds = b.liveItemIds.clone();
            this.target = b.target;
            this.budget = b.budget;
            this.owned = Collections.unmodifiableSet(new HashSet<>(b.owned));
            this.exclude = Collections.unmodifiableSet(new HashSet<>(b.exclude));
            this.include = Collections.unmodifiableSet(new HashSet<>(b.include));
            this.candidatesPerSlot = b.candidatesPerSlot;
            this.playerTemplate = b.playerTemplate;
            this.priceSource = b.priceSource;
            // Default to the budget priceSource when the caller never wires a
            // dedicated risk source, so every existing caller/test (single
            // price concept) behaves unchanged — see Builder#riskValueSource.
            this.riskValueSource = b.riskValueSource != null ? b.riskValueSource : b.priceSource;
            this.expensiveItemCount = b.expensiveItemCount;
            this.expensiveItemThreshold = b.expensiveItemThreshold;
            this.style = b.style;
            this.spellBook = b.spellBook;
            this.combatRequirement = b.combatRequirement;
            this.playerBaseLevels = java.util.Collections.unmodifiableMap(new java.util.HashMap<>(b.playerBaseLevels));
            this.ownedItemPrices = java.util.Collections.unmodifiableMap(new java.util.HashMap<>(b.ownedItemPrices));
        }

        public static Builder builder(int[] liveItemIds, Monster target, PlayerCombat.Builder playerTemplate) {
            return new Builder(liveItemIds, target, playerTemplate);
        }

        public static final class Builder {
            private final int[] liveItemIds;
            private final Monster target;
            private final PlayerCombat.Builder playerTemplate;
            private long budget = 0L;
            private final Set<Integer> owned = new HashSet<>();
            private final Set<Integer> exclude = new HashSet<>();
            private final Set<Integer> include = new HashSet<>();
            private int candidatesPerSlot = DEFAULT_CANDIDATES_PER_SLOT;
            private PriceSource priceSource = PriceSource.zero();
            private PriceSource riskValueSource = null;
            private int expensiveItemCount = 0;
            private long expensiveItemThreshold = 0L;
            private CombatStyle style;
            private Spell.SpellBook spellBook;
            private MonsterCombatRequirement combatRequirement;
            private java.util.Map<String, Integer> playerBaseLevels = java.util.Collections.emptyMap();
            private java.util.Map<Integer, Long> ownedItemPrices = java.util.Collections.emptyMap();

            private Builder(int[] liveItemIds, Monster target, PlayerCombat.Builder playerTemplate) {
                this.liveItemIds = liveItemIds;
                this.target = target;
                this.playerTemplate = playerTemplate;
                // The player's own worn gear is always "owned" — free to use in the search.
                for (int id : liveItemIds) {
                    if (id > 0) {
                        owned.add(id);
                    }
                }
            }

            /** GP budget for GE purchases beyond owned gear (design spec: 0 = owned-only search). */
            public Builder budget(long budget) {
                this.budget = Math.max(0, budget);
                return this;
            }

            /** Adds owned item ids (e.g. from the player's bank) — always affordable regardless of price. */
            public Builder owned(Set<Integer> ownedItemIds) {
                this.owned.addAll(ownedItemIds);
                return this;
            }

            /** "Don't use this" — never appears in the result, even if owned. */
            public Builder exclude(Set<Integer> excludeItemIds) {
                this.exclude.addAll(excludeItemIds);
                return this;
            }

            /** "Must use this" — forced into the result (best loadout built around it). */
            public Builder include(Set<Integer> includeItemIds) {
                this.include.addAll(includeItemIds);
                return this;
            }

            public Builder candidatesPerSlot(int n) {
                this.candidatesPerSlot = Math.max(1, n);
                return this;
            }

            /** Supplies GE prices for affordability filtering + spend/DPS-per-gp reporting (default: everything free). */
            public Builder priceSource(PriceSource priceSource) {
                this.priceSource = priceSource != null ? priceSource : PriceSource.zero();
                return this;
            }

            /**
             * Supplies each item's real gp "risk value" for the expensive-item
             * cap ({@link #expensiveItemCount}/{@link #expensiveItemThreshold})
             * ONLY — completely separate from {@link #priceSource}, which drives
             * budget/affordability. This decoupling is the fix for the
             * under-counting bug where an OWNED item (free via {@link #owned})
             * or an untradeable item (unpurchasable via {@link #priceSource})
             * could dodge the risk cap despite being worth real gp: a tradeable
             * item's risk value is its GE price; an untradeable item's risk
             * value is the value of the tradeable components it represents
             * (see {@code com.ospulse.combat.RiskValuation}), regardless of
             * ownership or purchasability. {@code null} (the default) falls
             * back to {@link #priceSource} unchanged, preserving prior
             * behaviour for every existing caller/test that never wires a
             * dedicated risk source.
             */
            public Builder riskValueSource(PriceSource riskValueSource) {
                this.riskValueSource = riskValueSource;
                return this;
            }

            /**
             * How many "expensive" items (see {@link #expensiveItemThreshold}) the
             * caller wants allowed in the result, e.g. for wilderness/PvP risk
             * budgeting. Enforced by the search (see {@link Request#expensiveItemCount()})
             * only when the cap can bind — a positive threshold and an allowance
             * below the number of searchable slots.
             */
            public Builder expensiveItemCount(int count) {
                this.expensiveItemCount = Math.max(0, count);
                return this;
            }

            /**
             * The gp value at/above which an item counts as "expensive" for
             * {@link #expensiveItemCount}. A threshold of 0 (the default) means
             * "no item is expensive" and disables the cap (see
             * {@link Request#expensiveItemThreshold()}).
             */
            public Builder expensiveItemThreshold(long threshold) {
                this.expensiveItemThreshold = Math.max(0, threshold);
                return this;
            }

            /**
             * Constrains the magic DPS evaluation to a single spellbook — the
             * Standard/Ancient tab the user picked in the magic view — so the
             * gear search's magic DPS follows the chosen book instead of
             * silently scoring whichever book's best spell is globally higher.
             * {@code null} leaves it unconstrained (best of Standard/Ancient).
             */
            public Builder spellBook(Spell.SpellBook spellBook) {
                this.spellBook = spellBook;
                return this;
            }

            /**
             * Constrains the search to loadouts that deal the given damage type
             * (item #6e's 5-way Ranged/Magic/Crush/Slash/Stab selector):
             * <ul>
             *   <li>weapon-slot candidates are filtered to weapons whose real
             *       combat options (see {@link WeaponCategoryRepository}) include
             *       a style of this {@link CombatStyle};</li>
             *   <li>every candidate loadout is evaluated ONLY at styles of this
             *       type (a loadout whose weapon cannot attack with it evaluates
             *       to {@code null}/unusable rather than silently falling back to
             *       a different type);</li>
             *   <li>the per-slot pruning proxy ranks by this style's relevant
             *       bonuses (e.g. magic attack + magic damage for MAGIC) instead
             *       of the style-agnostic all-bonus sum, so e.g. magic armour is
             *       never pruned away by melee armour's bigger raw stat totals.</li>
             * </ul>
             * {@code null} (the default) keeps the historical unconstrained
             * behaviour: every weapon evaluated at its own best style.
             */
            public Builder style(CombatStyle style) {
                this.style = style;
                return this;
            }

            /**
             * Constrains the weapon/ammo slot candidates to those permitted by the
             * given monster's combat gate (e.g. Kurask's leaf-bladed-weapon-or-magic
             * restriction) at the requested {@link #style(CombatStyle)}. {@code null}
             * (the default) leaves the search unconstrained by any monster gate.
             */
            public Builder combatRequirement(MonsterCombatRequirement combatRequirement) {
                this.combatRequirement = combatRequirement;
                return this;
            }

            /**
             * The player's BASE (real, un-boosted) skill levels as lowercase
             * {@code skill name → level} (e.g. {@code {"attack": 70, ...}}), used
             * to drop candidate items the player cannot equip at their current
             * levels (see {@link EquipmentRequirementsRepository}). {@code null}
             * or empty (the default) disables the level gate entirely — every
             * item is assumed wearable, preserving the historical behaviour.
             */
            public Builder playerBaseLevels(java.util.Map<String, Integer> playerBaseLevels) {
                this.playerBaseLevels = playerBaseLevels != null ? playerBaseLevels : java.util.Collections.emptyMap();
                return this;
            }

            /**
             * Known GE/bank values for OWNED item ids, keyed by item id — used
             * exclusively by the expensive-item risk cap ({@link #expensiveItemCount}/
             * {@link #expensiveItemThreshold}) to price owned/equipped gear,
             * taking priority over {@link #priceSource} for any id present here.
             * Owned ids are commonly excluded from an async price-source lookup
             * (no need to check affordability on something already owned), so
             * that lookup either doesn't know an owned id at all or — worse,
             * once wrapped as "unresolved = unaffordable" — reports it as
             * {@link Long#MAX_VALUE}; without this map taking priority the risk
             * count would then price every such owned item as maximally
             * expensive regardless of its real value. An owned id absent from
             * this map still falls back to {@link #priceSource}. {@code null}/
             * empty (the default) leaves every owned item priced by {@link
             * #priceSource} unchanged, preserving historical behaviour.
             */
            public Builder ownedItemPrices(java.util.Map<Integer, Long> ownedItemPrices) {
                this.ownedItemPrices = ownedItemPrices != null ? ownedItemPrices : java.util.Collections.emptyMap();
                return this;
            }

            public Request build() {
                return new Request(this);
            }
        }

        /** The damage-type constraint for the search, or {@code null} for the unconstrained best-of-any-style search. */
        public CombatStyle style() {
            return style;
        }

        /** The monster combat gate constraining weapon/ammo candidates, or {@code null} if unconstrained. */
        public MonsterCombatRequirement combatRequirement() {
            return combatRequirement;
        }

        /** The player's base skill levels for the equip-requirement gate (empty = gate disabled). */
        public java.util.Map<String, Integer> playerBaseLevels() {
            return playerBaseLevels;
        }

        /**
         * The number of "expensive" items (see {@link #expensiveItemThreshold()})
         * the caller wants allowed in the result (e.g. for wilderness/PvP risk
         * budgeting). Enforced by {@link GearOptimizer#optimize}: the returned
         * loadout holds no more than this many items priced ABOVE the threshold
         * whenever that's achievable from the candidate pool — the local search
         * de-risks even a live loadout that starts over the cap. Counts owned
         * items too (an owned high-value item is still riskable). Inert unless
         * the threshold is positive and this allowance is below the searchable
         * slot count (an allowance that large can never bind).
         */
        public int expensiveItemCount() {
            return expensiveItemCount;
        }

        /**
         * The gp value STRICTLY ABOVE which an item is considered "expensive"
         * for {@link #expensiveItemCount()} — a price exactly equal to this
         * threshold is "spend up to X", i.e. within the ceiling. A threshold
         * of 0 (the default) means "no item is expensive" and disables the
         * cap in {@link GearOptimizer#optimize}.
         */
        public long expensiveItemThreshold() {
            return expensiveItemThreshold;
        }

        /**
         * Known GE/bank values for owned item ids — see {@link Builder#ownedItemPrices}.
         * No longer consulted by the expensive-item risk cap (see {@link #riskValueSource()}),
         * which now owns that job exclusively; this map/getter is left in place
         * for any other budget-side caller and for backward compatibility.
         */
        public java.util.Map<Integer, Long> ownedItemPrices() {
            return ownedItemPrices;
        }

        /**
         * The per-item risk-value source for the expensive-item cap — see
         * {@link Builder#riskValueSource}. Never {@code null}: defaults to
         * {@link #priceSource()} when the caller doesn't set one.
         */
        public PriceSource riskValueSource() {
            return riskValueSource;
        }
    }

    /** One slot's chosen item in the result loadout, with its role for the DPS-per-gp readout. */
    public static final class SlotChoice {
        private final int slotOrdinal;
        private final int itemId;
        private final boolean owned;
        private final long price;

        SlotChoice(int slotOrdinal, int itemId, boolean owned, long price) {
            this.slotOrdinal = slotOrdinal;
            this.itemId = itemId;
            this.owned = owned;
            this.price = price;
        }

        public int slotOrdinal() {
            return slotOrdinal;
        }

        public int itemId() {
            return itemId;
        }

        public boolean owned() {
            return owned;
        }

        /** GE price if this is a purchase (0 if owned or the slot is empty). */
        public long price() {
            return price;
        }
    }

    /** The optimiser's result: the best loadout found, its DPS, total spend, and the upgrade-vs-owned-only comparison. */
    public static final class Result {
        private final List<SlotChoice> loadout;
        private final DpsResult dps;
        private final WeaponStyle style;
        private final Spell spell;
        private final long totalSpend;
        private final double ownedOnlyDps;

        Result(List<SlotChoice> loadout, DpsResult dps, WeaponStyle style, Spell spell, long totalSpend, double ownedOnlyDps) {
            this.loadout = Collections.unmodifiableList(loadout);
            this.dps = dps;
            this.style = style;
            this.spell = spell;
            this.totalSpend = totalSpend;
            this.ownedOnlyDps = ownedOnlyDps;
        }

        public List<SlotChoice> loadout() {
            return loadout;
        }

        public DpsResult dps() {
            return dps;
        }

        /** The (possibly {@code null} for a spell-driven magic result) style the DPS above was computed with. */
        public WeaponStyle style() {
            return style;
        }

        /** The spell driving the DPS above, or {@code null} for a non-magic result. */
        public Spell spell() {
            return spell;
        }

        /** Total GE spend of every non-owned slot choice. */
        public long totalSpend() {
            return totalSpend;
        }

        /** DPS of the best owned-items-only loadout (budget=0 equivalent) — the baseline for the upgrade comparison. */
        public double ownedOnlyDps() {
            return ownedOnlyDps;
        }

        /** DPS gained over the owned-only baseline. */
        public double deltaDps() {
            return dps.dps() - ownedOnlyDps;
        }

        /** DPS gained per gp spent, or {@code 0} if nothing was spent (avoids a divide-by-zero / Infinity surprise). */
        public double dpsPerGp() {
            return totalSpend <= 0 ? 0.0 : deltaDps() / totalSpend;
        }
    }

    /**
     * Runs the search. Intended to be called off the EDT for anything beyond
     * a trivial candidate pool (see class javadoc) — it is pure computation
     * with no I/O, so any executor/background thread works; the caller
     * publishes the {@link Result} back to the EDT.
     */
    public static Result optimize(Request request) {
        EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();

        // Build each slot's pruned candidate list once. The AMMO slot is
        // built FIRST because the weapon slot's DPS-ranked pruning pairs each
        // candidate weapon with its best affordable compatible ammo (a bow is
        // meaningless without arrows — see buildWeaponCandidates).
        List<Candidate> ammoCandidates = buildCandidatesForSlot(index, AMMO_SLOT, request, Collections.emptyList());
        List<List<Candidate>> candidatesBySlot = new ArrayList<>();
        int[] slotForIndex = new int[SEARCHABLE_SLOTS.length];
        int n = 0;
        for (int slot : SEARCHABLE_SLOTS) {
            slotForIndex[n++] = slot;
            candidatesBySlot.add(slot == AMMO_SLOT
                    ? ammoCandidates
                    : buildCandidatesForSlot(index, slot, request, ammoCandidates));
        }

        // Greedy seeding below is restricted to OWNED candidates (spend 0),
        // so the ammo paired into a weapon trial there must be owned too.
        List<Candidate> ownedAmmoCandidates = ownedOnly(ammoCandidates);

        // Seed: the live/owned loadout as the starting point for local search
        // (guarantees the search never returns worse than the player's own gear
        // when combined with the greedy weapon pass below).
        int[] current = request.liveItemIds.clone();
        // Charge-variant fuzzy grouping (item #7): a worn low charge is rewritten
        // to the player's highest owned charge of the same family up front, so the
        // recommendation surfaces the best owned charge instead of the identical
        // worn one (which a DPS tie-break would otherwise never swap away).
        current = normalizeChargeFamilies(current, request);
        applyForcedIncludes(current, request, index);

        // Greedy seed: independently pick each slot's best OWNED candidate
        // (weapon slot evaluated at its own best style — see class javadoc),
        // holding every other slot at its CURRENT (live) value. Seeding from
        // owned-only candidates (price 0) guarantees the seed's total spend
        // is always 0 <= budget, so the loadout the budget-guarded local
        // search below starts from is always feasible; a slot with no owned
        // candidate is left at its current/live value, same as before. This
        // purposefully ignores slot interactions; local search below fixes
        // that (within the budget).
        for (int i = 0; i < slotForIndex.length; i++) {
            int slot = slotForIndex[i];
            if (request.include.contains(current[slot])) {
                continue; // forced include already applied (incl. the weapon slot) — never second-guessed here
            }
            List<Candidate> ownedForSlot = new ArrayList<>();
            for (Candidate c : candidatesBySlot.get(i)) {
                if (c.owned()) {
                    ownedForSlot.add(c);
                }
            }
            if (!ownedForSlot.isEmpty()) {
                current = bestSingleSlotChoice(current, slot, ownedForSlot, request, ownedAmmoCandidates);
            }
        }

        // De-risk BEFORE the DPS local search, choosing by DPS loss: the
        // first-improving walk below takes the first overflow-lowering swap
        // it meets in SEARCHABLE_SLOTS order, which would let slot order —
        // not DPS — pick which over-cap item is sacrificed (see deriskToCap).
        // Once within the cap the local search can never re-raise the
        // overflow, so the allocation made here sticks.
        current = deriskToCap(current, candidatesBySlot, slotForIndex, ammoCandidates, request);

        // Local search: repeat full passes over every slot, applying the first
        // improving single-slot swap found, until a pass makes no change. A
        // swap is only accepted if it BOTH improves the objective AND keeps
        // the loadout's total (non-owned) spend within budget — this is what
        // bounds cumulative spend across slots (the per-item price check in
        // buildCandidatesForSlot only rules out items that could never be
        // affordable alone; it does not bound the sum across multiple slots).
        Evaluation currentEval = evaluate(current, request);
        for (int pass = 0; pass < MAX_LOCAL_SEARCH_PASSES; pass++) {
            boolean improved = false;
            for (int i = 0; i < slotForIndex.length; i++) {
                int slot = slotForIndex[i];
                if (request.include.contains(current[slot])) {
                    continue; // forced — never swapped away by local search
                }
                // Expensive-item risk of the loadout as it stands entering this
                // slot (recomputed per slot since an earlier slot's swap this
                // pass may have changed it) — a swap is judged first on whether
                // it moves this toward/away from the cap, then on DPS.
                int currentOverflow = expensiveOverflowOf(current, request);
                for (Candidate c : candidatesBySlot.get(i)) {
                    if (c.itemId() == current[slot]) {
                        continue;
                    }
                    int[] trial = applySlotChoice(current, slot, c.itemId());
                    if (slot == WhatIfLoadout.WEAPON_SLOT) {
                        // A weapon swap carries its ammo requirement with it: a
                        // bow tried while (say) a blessing or nothing is worn
                        // would otherwise score without any arrow ranged
                        // strength and lose to the incumbent — the classic
                        // two-slot interaction single-slot local search misses.
                        trial = withBestCompatibleAmmo(trial, ammoCandidates, request);
                    }
                    if (!withinBudget(trial, request)) {
                        continue; // would push cumulative spend over budget — reject regardless of DPS
                    }
                    Evaluation trialEval = evaluate(trial, request);
                    if (trialEval == null) {
                        continue;
                    }
                    int trialOverflow = expensiveOverflowOf(trial, request);
                    boolean better;
                    if (trialOverflow != currentOverflow) {
                        // Feasibility dominates DPS: never add risk (reject a
                        // higher overflow), accept a lower one. WHICH over-cap
                        // slot to sacrifice is deriskToCap's decision (by DPS
                        // loss, before this loop) — this branch only guards
                        // against re-risking and backstops overflow the
                        // pre-search pass could not clear (e.g. a later swap
                        // freeing budget). Equal overflow falls through to the
                        // DPS/tie-break decision below; an inactive cap keeps
                        // every overflow 0, so this is a no-op there.
                        better = trialOverflow < currentOverflow;
                    } else if (slot == AMMO_SLOT) {
                        // Ammo compares (DPS, then prayer on a DPS tie): worn
                        // ammo a weapon doesn't fire is DPS-invisible (see
                        // AmmoCompatibility/GearMapper), so among DPS-tied
                        // candidates the freed slot goes to the best blessing.
                        double currentDps = currentEval == null ? Double.NEGATIVE_INFINITY : currentEval.dps.dps();
                        double diff = trialEval.dps.dps() - currentDps;
                        better = diff > 1e-9
                                || (Math.abs(diff) <= 1e-9 && CandidateScore.prayerBonusOf(c.itemId()) > CandidateScore.prayerBonusOf(current[slot]));
                    } else if (currentEval == null) {
                        better = true;
                    } else {
                        // Same DPS tie-break as the greedy seed (B9-2): fill a
                        // DPS-neutral slot with the best-stat wearable item rather
                        // than leaving whatever the seed held (possibly empty).
                        double diff = trialEval.dps.dps() - currentEval.dps.dps();
                        better = diff > 1e-9
                                || (Math.abs(diff) <= 1e-9
                                    && CandidateScore.tieBreakScore(c.itemId()) > CandidateScore.tieBreakScore(current[slot]));
                    }
                    if (better) {
                        current = trial;
                        currentEval = trialEval;
                        improved = true;
                        break;
                    }
                }
            }
            if (!improved) {
                break;
            }
        }

        // Owned-only baseline: same search restricted to owned items (budget
        // effectively 0), for the DPS-per-gp comparison.
        double ownedOnlyDps = ownedOnlyBestDps(request, index);

        List<SlotChoice> loadoutOut = new ArrayList<>();
        long totalSpend = 0L;
        for (int slot : SEARCHABLE_SLOTS) {
            int itemId = current[slot];
            if (itemId <= 0) {
                continue;
            }
            boolean owned = request.owned.contains(itemId);
            long price = owned ? 0L : priceOf(itemId, request);
            if (!owned) {
                totalSpend += price;
            }
            loadoutOut.add(new SlotChoice(slot, itemId, owned, price));
        }

        DpsResult finalDps = currentEval != null ? currentEval.dps : zeroDps();
        WeaponStyle finalStyle = currentEval != null ? currentEval.style : null;
        Spell finalSpell = currentEval != null ? currentEval.spell : null;
        return new Result(loadoutOut, finalDps, finalStyle, finalSpell, totalSpend, ownedOnlyDps);
    }

    // ------------------------------------------------------------- internals

    private static long priceOf(int itemId, Request request) {
        long price = request.priceSource.priceFor(itemId);
        return Math.max(0L, price);
    }

    /**
     * Total GE spend of every non-owned, non-empty slot in {@code itemIds} —
     * the same accounting {@link #optimize} uses to build the final
     * {@link Result#totalSpend()}, exposed here so the local search can
     * reject any swap that would push cumulative spend over budget (see
     * {@link #withinBudget}). Owned items are always 0 regardless of price.
     */
    private static long totalSpendOf(int[] itemIds, Request request) {
        long total = 0L;
        for (int slot : SEARCHABLE_SLOTS) {
            int itemId = slot < itemIds.length ? itemIds[slot] : -1;
            if (itemId <= 0 || request.owned.contains(itemId)) {
                continue;
            }
            total += priceOf(itemId, request);
            if (total < 0) {
                // Overflow guard: an absurd combination of prices summed past
                // Long.MAX_VALUE would wrap negative — clamp to MAX_VALUE so
                // the budget comparison below still correctly reads "over".
                return Long.MAX_VALUE;
            }
        }
        return total;
    }

    /**
     * True when {@code itemIds}' cumulative non-owned spend fits within
     * {@code request.budget}. Compares via subtraction-free addition (see
     * {@link #totalSpendOf}'s overflow guard) rather than assuming both sides
     * fit safely in a {@code long} sum, so an unbounded/very large budget
     * (e.g. {@code Long.MAX_VALUE}, however unlikely given
     * {@link Request.Builder#budget} clamps to non-negative) never
     * overflows into a false rejection.
     */
    private static boolean withinBudget(int[] itemIds, Request request) {
        return totalSpendOf(itemIds, request) <= request.budget;
    }

    /**
     * True when the expensive-item cap is an ACTIVE constraint: a positive
     * threshold (0 means "no item is expensive" — the disabled default) and an
     * allowance below the number of searchable slots (an allowance >= slots can
     * never bind, so the whole search runs unchanged). When inactive, every
     * {@link #expensiveOverflowOf} is 0 and the local search behaves exactly as
     * the pre-cap DPS-only search.
     */
    private static boolean expensiveCapActive(Request request) {
        return expensiveCapActive(request.expensiveItemThreshold(), request.expensiveItemCount());
    }

    /**
     * Whether the expensive-item cap can bind at all: a threshold of 0 means
     * "no cap", and an allowance covering every SEARCHABLE slot can never be
     * exceeded. Public and parameterised so callers deciding anything on the
     * cap's behalf share this ONE definition — the count must be compared
     * against {@link #SEARCHABLE_SLOTS}{@code .length} (11), NOT the 14
     * equipment slots. Getting that wrong reports the cap active when the
     * optimiser has it disabled, which is exactly the disagreement this
     * overload exists to prevent.
     */
    public static boolean expensiveCapActive(long threshold, int allowance) {
        return threshold > 0 && allowance < SEARCHABLE_SLOTS.length;
    }

    /**
     * Untradeable items that are FREE to reclaim if lost (diary/quest re-obtainables),
     * so they carry no death risk and must never count against the expensive-item
     * ceiling ({@link #expensiveItemCountOf}). Extend as more are identified.
     *
     * <p>Ids verified against the decompiled {@code net.runelite.api.gameval.ItemID}
     * constants shipped in the {@code net.runelite:runelite-api} jar resolved on this
     * project's classpath (checked both {@code 1.12.31.1} and {@code 1.12.32} from the
     * local Gradle cache — identical in both). The RuneLite-generated constant names
     * don't match the in-game item names exactly: the Ardougne diary cloak is named
     * {@code ARDY_CAPE_*} (not {@code ARDY_CLOAK_*}), and Rada's blessing is named
     * {@code ZEAH_BLESSING_*} (Rada's blessing is the Kourend/Zeah region's diary
     * reward; {@code EASY/MEDIUM/HARD/ELITE} map to blessing tiers 1-4).
     *
     * <p><b>Rada's blessing is currently inert here:</b> it occupies the OSRS
     * "pocket" equipment slot, which post-dates and isn't modelled by
     * {@link net.runelite.api.EquipmentInventorySlot} (14 slots, no pocket entry) or
     * this optimizer's {@code itemIds[]} arrays ({@code GearSnapshot.EQUIPMENT_SLOT_COUNT
     * == 14}, {@link #SEARCHABLE_SLOTS} spans only those 14 indices). A pocket-slot item
     * can never appear in {@code itemIds[]}, so these 4 entries can never match in
     * {@link #expensiveItemCountOf}'s loop today — kept for correctness/documentation
     * and to future-proof this set if pocket-slot support is ever added to the
     * optimizer's equipment model. Ardougne cloak tiers (cape slot, index 1, which IS
     * searchable) are fully active.
     */
    private static final Set<Integer> FREE_REOBTAINABLE = Set.of(
            ItemID.ARDY_CAPE_EASY, ItemID.ARDY_CAPE_MEDIUM, ItemID.ARDY_CAPE_HARD, ItemID.ARDY_CAPE_ELITE,
            ItemID.ZEAH_BLESSING_EASY, ItemID.ZEAH_BLESSING_MEDIUM, ItemID.ZEAH_BLESSING_HARD, ItemID.ZEAH_BLESSING_ELITE
    );

    /**
     * Public read-only view of {@link #FREE_REOBTAINABLE}, for callers outside this
     * class that need the same "free to reclaim, no death risk" exemption — currently
     * {@code com.ospulse.combat.RiskValuation#classify}, wired via {@code
     * GearSection}'s {@code OptimizerPriceResolver} so a free-reobtainable untradeable
     * (e.g. Ardougne cloak, Rada's blessing) never falls through to the Trouver
     * parchment fallback even though it has no {@code ItemMapping}/assembled/curated
     * value either.
     */
    public static boolean isFreeReobtainable(int itemId) {
        return FREE_REOBTAINABLE.contains(itemId);
    }

    /**
     * Count of non-empty slots in {@code itemIds} holding an "expensive" item —
     * GE value STRICTLY ABOVE {@link Request#expensiveItemThreshold()} (an
     * item priced exactly at the threshold is "spend up to X", i.e. within
     * the ceiling, not exceeding it). Unlike
     * {@link #totalSpendOf} this counts OWNED items too: an owned high-value
     * item is still riskable gear in the wilderness/PvP, which is exactly what
     * the expensive-item cap protects against, so ownership (= free to equip)
     * must not exempt it from the risk count. The one exception is
     * {@link #FREE_REOBTAINABLE}: those ids are skipped (and never priced)
     * before this rule applies, since they carry no death risk at all.
     *
     * <p>Every item — owned or not, tradeable or not — is priced via {@link
     * Request#riskValueSource()} ONLY, completely separate from the budget
     * path ({@link Request#priceSource()}/{@link Request#ownedItemPrices()}).
     * This decoupling fixes two under-counting bugs the risk cap used to be
     * vulnerable to: (1) an owned item could be marked "owned at price 0" by
     * the caller (e.g. a variant's plain form) and dodge the cap entirely
     * even though it's genuinely worth real gp; (2) an untradeable item has
     * no budget price at all ({@link Request#priceSource()} treats it as
     * unpurchasable), which used to leave it unpriced/free for risk purposes
     * too. {@code riskValueSource} is built from real gp worth regardless of
     * ownership or purchasability (see {@code com.ospulse.combat.RiskValuation}),
     * so neither escape hatch works anymore; it defaults to {@link
     * Request#priceSource()} when the caller never sets a dedicated one,
     * preserving prior behaviour for callers that only supply one price
     * concept.
     */
    private static int expensiveItemCountOf(int[] itemIds, Request request) {
        long threshold = request.expensiveItemThreshold();
        int count = 0;
        for (int slot : SEARCHABLE_SLOTS) {
            int itemId = slot < itemIds.length ? itemIds[slot] : -1;
            if (capRiskValueOf(itemId, request) > threshold) {
                count++;
            }
        }
        return count;
    }

    /**
     * The gp value the expensive-item cap counts {@code itemId} at: {@code 0}
     * for an empty slot and for {@link #FREE_REOBTAINABLE} ids (no death risk,
     * so never priced), otherwise the item's non-negative
     * {@link Request#riskValueSource()} value. The ONE pricing rule shared by
     * {@link #expensiveItemCountOf}, the charge-family helpers
     * ({@link #bestOwnedFamilyMember}/{@link #familyDeriskPurchase}) and the
     * cap diagnostic in {@link #optimize}, so they can never disagree about
     * what a given item risks.
     */
    private static long capRiskValueOf(int itemId, Request request) {
        if (itemId <= 0 || FREE_REOBTAINABLE.contains(itemId)) {
            return 0L;
        }
        return Math.max(0L, request.riskValueSource().priceFor(itemId));
    }

    /**
     * By how much {@code itemIds} exceeds the expensive-item allowance (0 when
     * within the cap, or the cap is inactive). The local search treats this as
     * a feasibility "violation" that dominates DPS — it drives the overflow
     * toward 0 first, then optimises DPS among equally-feasible loadouts. This
     * is what lets a starting loadout that already over-risks (the player's own
     * worn gear can, since the seed is never rejected up front) be DE-RISKED
     * rather than leaving the search stuck: a hard "reject any over-cap
     * loadout" gate would reject every single-slot step of a multi-item de-risk
     * too, since intermediate loadouts are still over the cap.
     */
    private static int expensiveOverflowOf(int[] itemIds, Request request) {
        if (!expensiveCapActive(request)) {
            return 0;
        }
        return Math.max(0, expensiveItemCountOf(itemIds, request) - request.expensiveItemCount());
    }

    /**
     * Drives an over-cap loadout back within the expensive-item allowance by
     * the CHEAPEST DPS concessions that still REACH the allowance: each round
     * gathers every valid overflow-lowering swap ({@link #overflowLoweringMoves})
     * and applies the best-DPS one — except that a swap which leaves the
     * loadout over the cap is only accepted while the cap stays reachable
     * from its result ({@link #capClearableFrom}); otherwise the next-best
     * DPS pick is tried, down to the clearing swaps (which trivially
     * qualify), and only when NO move keeps the cap reachable does the plain
     * DPS-best pick go ahead as a best-effort shed. Repeats until the
     * loadout is within the cap or no overflow-lowering swap exists (the
     * leftover overflow then stays for the local search's guard/backstop);
     * every applied swap strictly lowers the overflow, so this terminates.
     *
     * <p>Choosing by least DPS loss is what spends the allowance on the
     * items that buy the most DPS: with one premium slot allowed, a premium
     * amulet with real offensive stats worn alongside a premium ring with
     * none, the DPS-dead ring is the free demotion and the amulet keeps its
     * premium item. Leaving this to the local search's first-improving walk
     * instead let {@link #SEARCHABLE_SLOTS} order pick the sacrifice — the
     * amulet (slot 2, walked before ring slot 12) lost its item for the same
     * risk count and strictly less DPS.
     *
     * <p>The reachability guard exists because the budget couples the
     * rounds: over the cap by two, a cheap-DPS demotion that eats the
     * remaining budget outranks a 2H purchase whose eviction of an expensive
     * shield would clear the cap in one within-budget swap — and once the
     * budget is spent that eviction is unaffordable forever, stranding the
     * result over the cap although a compliant loadout was reachable.
     * Feasibility dominates DPS, so the stranding pick must yield. Ranking
     * by overflow shed instead would over-correct the other way — a
     * huge-DPS-loss double eviction must not beat two cheap single demotions
     * that clear the cap between them — which is why the guard rejects only
     * moves that make the cap UNREACHABLE, never moves that merely clear it
     * more slowly. When the budget never binds the guard never rejects and
     * the pure least-DPS-loss ordering runs unchanged. Returns {@code
     * current} unchanged when already within the cap (or the cap is inactive
     * — every overflow is 0 then).
     */
    private static int[] deriskToCap(int[] current, List<List<Candidate>> candidatesBySlot, int[] slotForIndex,
                                     List<Candidate> ammoCandidates, Request request) {
        int overflow = expensiveOverflowOf(current, request);
        while (overflow > 0) {
            List<DeriskMove> moves =
                    overflowLoweringMoves(current, overflow, candidatesBySlot, slotForIndex, ammoCandidates, request);
            if (moves.isEmpty()) {
                break;
            }
            moves.sort(DeriskMove.BY_DPS);
            DeriskMove chosen = moves.get(0); // best-effort shed when nothing keeps the cap reachable
            for (DeriskMove move : moves) {
                if (move.overflow == 0 || capClearableFrom(move.trial, move.overflow, candidatesBySlot,
                        slotForIndex, ammoCandidates, request)) {
                    chosen = move;
                    break;
                }
            }
            current = chosen.trial;
            overflow = chosen.overflow;
        }
        return current;
    }

    /** One candidate de-risk swap: the loadout it produces and how that loadout scores. */
    private static final class DeriskMove {
        /**
         * Best DPS first; an exact DPS tie falls to the incoming item's
         * {@link #tieBreakScore} (B9-2's idiom) — DPS-identical swaps (the
         * usual tie: items whose differing stats are all DPS-invisible)
         * evaluate to bit-equal DPS, so no epsilon is needed and the
         * comparator stays a valid total order for sorting.
         */
        static final Comparator<DeriskMove> BY_DPS = (a, b) -> a.dps != b.dps
                ? Double.compare(b.dps, a.dps)
                : Integer.compare(CandidateScore.tieBreakScore(b.swapInId), CandidateScore.tieBreakScore(a.swapInId));

        final int[] trial;
        final int overflow;
        final long spend;
        final double dps;
        final int swapInId;

        DeriskMove(int[] trial, int overflow, long spend, double dps, int swapInId) {
            this.trial = trial;
            this.overflow = overflow;
            this.spend = spend;
            this.dps = dps;
            this.swapInId = swapInId;
        }
    }

    /**
     * Every single-slot swap of {@code current} that LOWERS the expensive-item
     * overflow while staying within budget and evaluable — the one move set
     * both {@link #deriskToCap}'s DPS-ranked pass and {@link #capClearableFrom}'s
     * reachability probe draw from (they must agree, or the probe could prove
     * a path the real pass cannot take). The overflow comparison uses the
     * full trial ({@link #expensiveOverflowOf}), so a 2H weapon evicting an
     * expensive shield counts as the double removal it is. Force-included
     * items are never swapped away, mirroring the local search.
     */
    private static List<DeriskMove> overflowLoweringMoves(int[] current, int overflow,
                                                          List<List<Candidate>> candidatesBySlot, int[] slotForIndex,
                                                          List<Candidate> ammoCandidates, Request request) {
        List<DeriskMove> moves = new ArrayList<>();
        for (int i = 0; i < slotForIndex.length; i++) {
            int slot = slotForIndex[i];
            if (request.include.contains(current[slot])) {
                continue;
            }
            for (Candidate c : candidatesBySlot.get(i)) {
                if (c.itemId() == current[slot]) {
                    continue;
                }
                int[] trial = applySlotChoice(current, slot, c.itemId());
                if (slot == WhatIfLoadout.WEAPON_SLOT) {
                    trial = withBestCompatibleAmmo(trial, ammoCandidates, request);
                }
                int trialOverflow = expensiveOverflowOf(trial, request);
                if (trialOverflow >= overflow) {
                    continue;
                }
                long spend = totalSpendOf(trial, request);
                if (spend > request.budget) {
                    continue;
                }
                Evaluation trialEval = evaluate(trial, request);
                if (trialEval == null) {
                    continue;
                }
                moves.add(new DeriskMove(trial, trialOverflow, spend, trialEval.dps.dps(), c.itemId()));
            }
        }
        return moves;
    }

    /**
     * Whether the expensive-item cap is still REACHABLE from {@code state}
     * within the budget: simulates the rest of the de-risk DPS-blind,
     * applying the LOWEST-SPEND overflow-lowering move each round (spend
     * tie: most overflow shed) until the overflow hits 0 (reachable) or no
     * move remains (stranded). Spending as little as possible each round
     * keeps the most budget open for the rest of the chain, so this finds a
     * clearing path whenever budget headroom is the only question; a path
     * needing one specific combination of unequal purchases can in principle
     * still be missed, in which case {@link #deriskToCap} merely settles for
     * a different (typically clearing) move — a {@code true} here is always
     * genuine, since the simulated chain is one the real pass could take.
     * Terminates like the caller: every simulated move strictly lowers the
     * overflow.
     */
    private static boolean capClearableFrom(int[] state, int overflow, List<List<Candidate>> candidatesBySlot,
                                            int[] slotForIndex, List<Candidate> ammoCandidates, Request request) {
        while (overflow > 0) {
            DeriskMove cheapest = null;
            for (DeriskMove move
                    : overflowLoweringMoves(state, overflow, candidatesBySlot, slotForIndex, ammoCandidates, request)) {
                if (cheapest == null || move.spend < cheapest.spend
                        || (move.spend == cheapest.spend && move.overflow < cheapest.overflow)) {
                    cheapest = move;
                }
            }
            if (cheapest == null) {
                return false;
            }
            state = cheapest.trial;
            overflow = cheapest.overflow;
        }
        return true;
    }

    private static int[] applySlotChoice(int[] itemIds, int slot, int itemId) {
        LoadoutOverride single = LoadoutOverride.empty().withSlot(slot, itemId);
        // Reuse WhatIfLoadout's 2H/shield exclusivity so a weapon/shield swap
        // during the search obeys the same rule the what-if UI enforces.
        if (slot == WhatIfLoadout.WEAPON_SLOT) {
            single = WhatIfLoadout.equipWeapon(LoadoutOverride.empty(), itemId);
        } else if (slot == WhatIfLoadout.SHIELD_SLOT) {
            single = WhatIfLoadout.equipShield(LoadoutOverride.empty(), itemIds, itemId);
        }
        int[] next = WhatIfLoadout.effectiveItemIds(itemIds, single);
        return next;
    }

    /**
     * The best single choice for one slot, holding every other slot fixed.
     * Weapon-slot trials get their best compatible ammo from
     * {@code ammoCandidates} paired in (see {@link #withBestCompatibleAmmo});
     * ammo-slot candidates compare by (DPS, then prayer bonus on a DPS tie) —
     * worn ammo a weapon doesn't fire is DPS-invisible (blowpipes ignore the
     * slot entirely, incompatible consumables are skipped by
     * {@code GearMapper}/{@link com.ospulse.combat.AmmoCompatibility}), so a
     * pure-DPS ranking would keep whichever candidate happened to be worn
     * instead of freeing the slot for the best blessing.
     */
    private static int[] bestSingleSlotChoice(int[] itemIds, int slot, List<Candidate> candidates, Request request,
                                              List<Candidate> ammoCandidates) {
        int[] best = itemIds;
        Evaluation bestEval = evaluate(itemIds, request);
        int bestPrayer = slot == AMMO_SLOT ? CandidateScore.prayerBonusOf(slotItemId(itemIds, slot)) : 0;
        for (Candidate c : candidates) {
            int[] trial = applySlotChoice(itemIds, slot, c.itemId());
            if (slot == WhatIfLoadout.WEAPON_SLOT) {
                trial = withBestCompatibleAmmo(trial, ammoCandidates, request);
            }
            Evaluation trialEval = evaluate(trial, request);
            if (trialEval == null) {
                continue;
            }
            boolean better;
            int trialPrayer = slot == AMMO_SLOT ? CandidateScore.prayerBonusOf(c.itemId()) : 0;
            if (bestEval == null) {
                better = true;
            } else if (slot == AMMO_SLOT) {
                double diff = trialEval.dps.dps() - bestEval.dps.dps();
                better = diff > 1e-9 || (Math.abs(diff) <= 1e-9 && trialPrayer > bestPrayer);
            } else {
                // DPS tie-break (B9-2): a DPS-neutral slot (legs, ring, most
                // armour under a fixed style) never RAISES DPS, so a pure ">"
                // test would leave it at its seed value — empty when starting
                // from naked gear ("recommend no legs"). On a DPS tie prefer the
                // higher-stat wearable item so the slot gets filled with the best
                // owned piece instead of being left empty.
                double diff = trialEval.dps.dps() - bestEval.dps.dps();
                better = diff > 1e-9
                        || (Math.abs(diff) <= 1e-9
                            && CandidateScore.tieBreakScore(c.itemId()) > CandidateScore.tieBreakScore(slotItemId(best, slot)));
            }
            if (better) {
                best = trial;
                bestEval = trialEval;
                bestPrayer = trialPrayer;
            }
        }
        return best;
    }

    /**
     * Pairs a weapon trial with the best affordable ammo it can actually
     * fire: when the trial's weapon consumes an ammo class the worn ammo
     * doesn't match, the highest-ranked in-class candidate that keeps the
     * loadout within budget is swapped into the ammo slot ({@code
     * ammoCandidates} arrives per-class best-first from
     * {@link #buildCandidatesForSlot}). Without this, a consuming weapon is
     * systematically undervalued at every seeding/swap step — a Scorching
     * bow tried over a blowpipe loadout would score without any arrow
     * ranged strength and always lose. No-op for weapons that use no worn
     * ammo, for already-compatible ammo, and when no in-class candidate fits
     * the budget.
     */
    private static int[] withBestCompatibleAmmo(int[] itemIds, List<Candidate> ammoCandidates, Request request) {
        AmmoCompatibility.AmmoClass needed =
                AmmoCompatibility.consumedClass(slotItemId(itemIds, WhatIfLoadout.WEAPON_SLOT));
        if (needed == null || AmmoCompatibility.classify(slotItemId(itemIds, AMMO_SLOT)) == needed) {
            return itemIds;
        }
        for (Candidate c : ammoCandidates) {
            if (AmmoCompatibility.classify(c.itemId()) != needed) {
                continue;
            }
            int[] trial = applySlotChoice(itemIds, AMMO_SLOT, c.itemId());
            if (withinBudget(trial, request)) {
                return trial;
            }
        }
        return itemIds;
    }

    /** The owned subset of {@code candidates}, order preserved (per-class best-first for ammo lists). */
    private static List<Candidate> ownedOnly(List<Candidate> candidates) {
        List<Candidate> owned = new ArrayList<>();
        for (Candidate c : candidates) {
            if (c.owned()) {
                owned.add(c);
            }
        }
        return owned;
    }

    private static int slotItemId(int[] itemIds, int slot) {
        return slot >= 0 && slot < itemIds.length ? itemIds[slot] : -1;
    }

    private static void applyForcedIncludes(int[] itemIds, Request request, EquipmentIndexRepository index) {
        for (int includedId : request.include) {
            EquipmentIndexRepository.Entry entry = index.entryFor(includedId);
            if (entry == null) {
                continue;
            }
            int[] forced = applySlotChoice(itemIds, entry.slotOrdinal(), includedId);
            System.arraycopy(forced, 0, itemIds, 0, itemIds.length);
        }
    }

    /**
     * Test seam: the item ids the optimiser would consider for {@code slot}
     * under {@code request} (post-collapse). Lets a test assert directly that a
     * charge family collapses to a single candidate without reaching into the
     * private candidate pipeline.
     */
    static List<Integer> candidateIdsForSlotForTest(int slot, Request request) {
        List<Candidate> candidates =
                buildCandidatesForSlot(EquipmentIndexRepository.getInstance(), slot, request, Collections.emptyList());
        List<Integer> ids = new ArrayList<>();
        for (Candidate c : candidates) {
            ids.add(c.itemId());
        }
        return ids;
    }

    /**
     * Collapses every {@link ChargeFamilies charge family} present in {@code
     * candidates} to a single representative candidate (item #7): the family is
     * treated as one item so the optimiser never lists eight identical Amulet of
     * glory charges as separate options, and — when any charge is owned — the
     * representative is the best owned member (see {@link #bestOwnedFamilyMember}:
     * the highest owned charge, de-risked under an active expensive-item cap, so
     * a player wearing the (1) but holding the (4) is recommended the (4)).
     *
     * <p>One deliberate exception to "single candidate": when the expensive-item
     * cap is active and the representative's risk value sits ABOVE the cap's
     * ceiling, the family also keeps ONE below-ceiling purchase member (see
     * {@link #familyDeriskPurchase}) — otherwise a player owning only the ~50m
     * Amulet of eternal glory could never be told to buy a ~15k identical-DPS
     * glory to get back under the cap, even though the search makes exactly that
     * de-risk swap for non-family items. With the cap inactive, or any owned
     * member within the ceiling (the representative then de-risks to it), the
     * family still collapses to exactly one candidate.
     *
     * <p>A family the player force-included is left untouched (all its members
     * pass through) so the explicit include always survives. Returns {@code
     * candidates} unchanged when no family member is present, so non-charge
     * items are unaffected.
     */
    private static List<Candidate> collapseChargeFamilies(List<Candidate> candidates, Request request) {
        boolean anyFamily = false;
        for (Candidate c : candidates) {
            if (ChargeFamilies.isMember(c.itemId())) {
                anyFamily = true;
                break;
            }
        }
        if (!anyFamily) {
            return candidates;
        }

        // Families with a force-included member are never collapsed — the user's
        // explicit choice of a specific charge must reach the search intact.
        Set<int[]> includedFamilies = Collections.newSetFromMap(new java.util.IdentityHashMap<>());
        for (Candidate c : candidates) {
            int[] family = ChargeFamilies.familyOf(c.itemId());
            if (family != null && request.include.contains(c.itemId())) {
                includedFamilies.add(family);
            }
        }

        List<Candidate> out = new ArrayList<>();
        Set<int[]> emitted = Collections.newSetFromMap(new java.util.IdentityHashMap<>());
        for (Candidate c : candidates) {
            int[] family = ChargeFamilies.familyOf(c.itemId());
            if (family == null || includedFamilies.contains(family)) {
                out.add(c);
                continue;
            }
            if (!emitted.add(family)) {
                continue; // this family already has its candidate(s)
            }
            Candidate representative = chargeFamilyRepresentative(family, candidates, request);
            if (representative == null) {
                representative = c;
            }
            out.add(representative);
            Candidate deRisk = familyDeriskPurchase(family, representative, candidates, request);
            if (deRisk != null) {
                out.add(deRisk);
            }
        }
        return out;
    }

    /**
     * The one EXTRA candidate that keeps the expensive-item risk cap able to
     * de-risk WITHIN a charge family: when the cap is active
     * ({@link #expensiveCapActive}) and {@code representative}'s risk value
     * ({@link #capRiskValueOf}) is strictly above the ceiling, this returns the
     * cheapest not-owned family member that survived this slot's gates
     * (affordability/exclusion/level — i.e. is present in {@code candidates})
     * AND whose own risk value is at/below the ceiling, tie-broken toward the
     * highest charge (family order). Every member is DPS-identical, so the
     * local search only ever picks it when it lowers the expensive-item
     * overflow — a loadout already within the cap keeps the free owned
     * representative on the DPS/stat tie-break and never buys needlessly.
     *
     * <p>{@code null} — leaving the family collapsed to the single
     * representative exactly as before — when the cap is inactive, the
     * representative is already within the ceiling, or no affordable
     * below-ceiling member exists. Only not-owned members are considered
     * because {@link #bestOwnedFamilyMember} already de-risks within the owned
     * members under an active cap: an over-ceiling owned representative proves
     * no owned member sits within the ceiling, so any within-ceiling member is
     * necessarily a purchase.
     */
    private static Candidate familyDeriskPurchase(int[] family, Candidate representative,
                                                  List<Candidate> candidates, Request request) {
        if (!expensiveCapActive(request)) {
            return null;
        }
        long threshold = request.expensiveItemThreshold();
        if (capRiskValueOf(representative.itemId(), request) <= threshold) {
            return null; // representative already within the ceiling — nothing to de-risk
        }
        Candidate best = null;
        for (int memberId : family) { // highest charge first — a price tie resolves to the higher charge
            if (memberId == representative.itemId() || capRiskValueOf(memberId, request) > threshold) {
                continue;
            }
            for (Candidate c : candidates) {
                if (c.itemId() == memberId && !c.owned()) {
                    if (best == null || c.price() < best.price()) {
                        best = c;
                    }
                    break;
                }
            }
        }
        return best;
    }

    /**
     * The owned, non-excluded member of {@code itemId}'s charge family to
     * surface — the HIGHEST charge (family array is highest-first). Every
     * member is DPS/stat-identical, and per-charge GE prices genuinely differ
     * (a glory (1) is cheaper than a (4)), so risk values must never influence
     * the pick while the expensive-item cap is inactive — ordering by risk
     * would demote an owned (4) to the (1).
     *
     * <p>The one exception: when the cap is active ({@link #expensiveCapActive})
     * and the highest owned charge's risk value ({@link #capRiskValueOf}) is
     * strictly above the ceiling, the pick de-risks WITHIN the owned members —
     * the highest owned charge at/below the ceiling — so owning a normal ~15k
     * Amulet of glory AND a ~50m Amulet of eternal glory (identical combat
     * stats) never needlessly burns the cap on the eternal. When no owned
     * member is within the ceiling the highest charge is still returned;
     * {@link #familyDeriskPurchase} then supplies the below-ceiling purchase
     * alternative. {@code null} when {@code itemId} isn't a family member or
     * no owned, non-excluded member exists.
     */
    private static Integer bestOwnedFamilyMember(int itemId, Request request) {
        int[] family = ChargeFamilies.familyOf(itemId);
        if (family == null) {
            return null;
        }
        Integer best = null;
        for (int memberId : family) { // highest charge first
            if (request.owned.contains(memberId) && !request.exclude.contains(memberId)) {
                best = memberId;
                break;
            }
        }
        if (best == null || !expensiveCapActive(request)) {
            return best;
        }
        long threshold = request.expensiveItemThreshold();
        if (capRiskValueOf(best, request) <= threshold) {
            return best;
        }
        // Over the ceiling — de-risk within owned first: the highest owned
        // charge at/below the ceiling, if any, before the search resorts to
        // the purchase candidate familyDeriskPurchase keeps in the pool.
        for (int memberId : family) { // highest charge first
            if (request.owned.contains(memberId) && !request.exclude.contains(memberId)
                    && capRiskValueOf(memberId, request) <= threshold) {
                return memberId;
            }
        }
        return best;
    }

    /**
     * The candidate that stands in for {@code family}: the best owned,
     * non-excluded member (always free/owned — see {@link #bestOwnedFamilyMember})
     * when the player owns any, otherwise the cheapest not-owned charge that
     * survived this slot's gates — every charge has identical combat stats, so
     * the cheapest is the best buy, tie-broken toward the highest charge.
     * {@code null} only if the family has no usable member here (the caller then
     * keeps the original candidate). Usually the family's ONLY candidate; see
     * {@link #familyDeriskPurchase} for the one risk-cap exception.
     */
    private static Candidate chargeFamilyRepresentative(int[] family, List<Candidate> candidates, Request request) {
        Integer ownedBest = bestOwnedFamilyMember(family[0], request);
        if (ownedBest != null) {
            return new Candidate(ownedBest, 0L, true);
        }
        Candidate best = null;
        for (int memberId : family) { // highest charge first
            for (Candidate c : candidates) {
                if (c.itemId() == memberId && !c.owned()) {
                    if (best == null || c.price() < best.price()) {
                        best = c;
                    }
                    break;
                }
            }
        }
        return best;
    }

    /**
     * Rewrites any charge-family member in {@code itemIds} (the live/seed
     * loadout) to the best owned member of its family (item #7; highest charge,
     * cap-aware — see {@link #bestOwnedFamilyMember}), so a player already
     * WEARING a low charge is seeded — and therefore recommended — with their
     * best owned charge rather than the DPS-identical worn one that the
     * tie-break would otherwise leave untouched. Returns {@code itemIds}
     * unchanged (same reference) when nothing needs rewriting.
     *
     * <p>Deliberately OWNED-only: when the player's sole owned member is an
     * expensive one (only the ~50m eternal glory), the seed keeps it — a seed
     * must never fabricate a purchase — and the search moves off it when the
     * risk cap demands, via the below-ceiling purchase candidate that
     * {@link #familyDeriskPurchase} keeps in the slot's pool.
     */
    private static int[] normalizeChargeFamilies(int[] itemIds, Request request) {
        int[] out = itemIds;
        for (int i = 0; i < itemIds.length; i++) {
            Integer best = bestOwnedFamilyMember(itemIds[i], request);
            if (best != null && best != itemIds[i]) {
                if (out == itemIds) {
                    out = itemIds.clone();
                }
                out[i] = best;
            }
        }
        return out;
    }

    /** True if any force-included item occupies the shield slot (so a 2H weapon would evict it). */
    private static boolean forcesShieldSlot(Request request, EquipmentIndexRepository index) {
        for (int includedId : request.include) {
            EquipmentIndexRepository.Entry entry = index.entryFor(includedId);
            if (entry != null && entry.slotOrdinal() == WhatIfLoadout.SHIELD_SLOT) {
                return true;
            }
        }
        return false;
    }

    private static List<Candidate> buildCandidatesForSlot(EquipmentIndexRepository index, int slot, Request request,
                                                          List<Candidate> ammoCandidates) {
        List<EquipmentIndexRepository.Entry> all = index.forSlot(slot);
        List<Candidate> affordable = new ArrayList<>();
        boolean weaponSlotWithForcedShield =
                slot == WhatIfLoadout.WEAPON_SLOT && forcesShieldSlot(request, index);
        for (EquipmentIndexRepository.Entry e : all) {
            if (request.exclude.contains(e.itemId())) {
                continue;
            }
            if (slot == WhatIfLoadout.WEAPON_SLOT && !CandidateScore.weaponSupportsStyle(e.itemId(), request.style)) {
                // Style-constrained search (item #6e): a weapon that cannot
                // attack with the requested damage type is never a candidate —
                // it would only ever evaluate to null under the constraint.
                continue;
            }
            MonsterCombatRequirement combatReq = request.combatRequirement;
            if (combatReq != null) {
                if (slot == WhatIfLoadout.WEAPON_SLOT
                        && !combatReq.permitsWeapon(e.itemId(), request.style,
                                AmmoCompatibility.consumedClass(e.itemId()) != null)) {
                    // Monster combat gate (e.g. Kurask): a weapon the monster
                    // cannot be damaged by is never a candidate. A self-supplying
                    // ranged weapon (blowpipe) can't satisfy a broad-ammo gate via
                    // the worn ammo slot, so it is gated out here too.
                    continue;
                }
                if (slot == AMMO_SLOT && !combatReq.permitsAmmo(e.itemId(), request.style)) {
                    continue;
                }
            }
            if (!request.playerBaseLevels.isEmpty()
                    && !EquipmentRequirementsRepository.getInstance().canEquip(e.itemId(), request.playerBaseLevels)) {
                // B9-5: never recommend gear the player can't equip at their
                // current (base) levels — a level-40-Attack player must not be
                // told to wear a Dragon scimitar (60 Attack). Applied to every
                // candidate (owned or not) since ownership doesn't grant the
                // level to wield it. Disabled when no levels are supplied.
                continue;
            }
            boolean owned = request.owned.contains(e.itemId());
            boolean included = request.include.contains(e.itemId());
            long price = owned ? 0L : priceOf(e.itemId(), request);
            if (!owned && !included && price > request.budget) {
                continue;
            }
            affordable.add(new Candidate(e.itemId(), price, owned));
        }

        // Charge-variant fuzzy grouping (item #7): collapse each charge family
        // (e.g. every Amulet of glory charge) to ONE candidate so the family is
        // treated as a single item — owned iff any charge is owned, represented
        // by the best owned member — plus, under an active expensive-item cap
        // with an over-ceiling representative, ONE below-ceiling purchase member
        // so the cap can de-risk within the family (see familyDeriskPurchase).
        // A no-op for slots/loadouts with no family members, so every non-charge
        // item keeps its existing behaviour.
        affordable = collapseChargeFamilies(affordable, request);

        if (weaponSlotWithForcedShield) {
            // A forced shield-slot item (mirror shield vs Basilisk) can't coexist
            // with a two-handed weapon. Prefer a one-handed weapon + the shield by
            // dropping 2H candidates — but ONLY when a usable one-handed weapon of
            // this style actually exists. Otherwise keep the 2H options so the
            // search doesn't collapse to zero swaps when the player only owns 2H
            // weapons of that style (Tumeken's shadow, bow of faerdhinen, ...);
            // the advisory shield then yields (equipWeapon empties the shield
            // slot for a 2H weapon). See B8-5.
            boolean hasOneHanded = false;
            for (Candidate c : affordable) {
                if (!WhatIfLoadout.isTwoHanded(c.itemId())) {
                    hasOneHanded = true;
                    break;
                }
            }
            if (hasOneHanded) {
                affordable.removeIf(c -> WhatIfLoadout.isTwoHanded(c.itemId()));
            }
        }

        if (slot == AMMO_SLOT) {
            return pruneAmmoCandidates(affordable, request);
        }
        if (slot == WhatIfLoadout.WEAPON_SLOT && request.target != null) {
            return pruneWeaponCandidatesByDps(affordable, request, ammoCandidates);
        }

        // Non-weapon slots (and the degenerate no-target case): prune to
        // top-N by a cheap proxy bonus (see proxyOffensiveScore) — the
        // requested style's relevant bonuses when the search is style-
        // constrained, else the style-agnostic sum of every offensive bonus.
        // These slots contribute additively under a fixed style, so the
        // proxy ranking is faithful enough; owned/included items are exempt
        // from pruning as always.
        affordable.sort(Comparator.comparingInt((Candidate c) -> -CandidateScore.proxyOffensiveScore(c.itemId(), request.style)));
        List<Candidate> pruned = new ArrayList<>();
        Set<Integer> keptIds = new HashSet<>();
        for (Candidate c : affordable) {
            boolean mandatory = mandatoryCandidate(c, request);
            if (mandatory || pruned.size() < request.candidatesPerSlot) {
                pruned.add(c);
                keptIds.add(c.itemId());
            }
        }
        retainSubCeilingCandidates(affordable, pruned, keptIds, request);
        return pruned;
    }

    /**
     * True when {@code c} must survive every per-slot pruning stage: the
     * player owns it or force-included it (the historical "you already have
     * it / you demanded it" exemptions — see the class javadoc), or it is a
     * charge-family member that survived {@link #collapseChargeFamilies}.
     * Post-collapse a family contributes at most two DELIBERATE candidates —
     * its representative plus, under an active expensive-item cap, one
     * below-ceiling purchase member — and each is load-bearing: pruning
     * either away would break the family's "treated as one item"
     * recommendation or the cap's ability to de-risk within the family. (A
     * force-included family passes through the collapse whole, so its
     * members are similarly all kept — a handful of identical-stat items at
     * most.) Family candidates are never numerous, so the exemption cannot
     * meaningfully widen the search.
     */
    private static boolean mandatoryCandidate(Candidate c, Request request) {
        return c.owned() || request.include.contains(c.itemId()) || ChargeFamilies.isMember(c.itemId());
    }

    /**
     * When the expensive-item cap ({@link #expensiveCapActive}) is active,
     * the top-N-by-stat/DPS pruning above can starve a slot of every
     * AT/BELOW-ceiling item: the highest scorers are exactly the "expensive"
     * ones a capped, non-premium slot must avoid, so a genuinely good cheap
     * item can be pruned away entirely — leaving the local search a choice
     * only between an over-ceiling item and whatever junk happened to
     * survive, unable to actually de-risk into anything good. This appends
     * up to {@code request.candidatesPerSlot} MORE items (not already in
     * {@code keptIds}) priced AT/BELOW the threshold, walking {@code
     * sortedBest} in the order the caller already ranked it (proxy stat for
     * non-weapon slots, real evaluated DPS for the weapon slot), so the
     * search always has a genuine sub-ceiling option to fall back to.
     *
     * <p>A no-op when the cap is inactive, so an inactive cap's candidate
     * list — and therefore its result — is unchanged from before this fix.
     */
    private static void retainSubCeilingCandidates(List<Candidate> sortedBest, List<Candidate> pruned,
                                                    Set<Integer> keptIds, Request request) {
        if (!expensiveCapActive(request)) {
            return;
        }
        long threshold = request.expensiveItemThreshold();
        int kept = 0;
        for (Candidate c : sortedBest) {
            if (kept >= request.candidatesPerSlot) {
                break;
            }
            if (keptIds.contains(c.itemId())) {
                continue;
            }
            if (c.price() <= threshold) {
                pruned.add(c);
                keptIds.add(c.itemId());
                kept++;
            }
        }
    }

    /**
     * Weapon-slot pruning by REAL evaluated DPS: each affordable weapon is
     * scored by {@link #evaluate} at its own best style/spell against the
     * actual target, applied over the live loadout with its best affordable
     * compatible ammo paired in ({@link #withBestCompatibleAmmo}) — then the
     * top {@code candidatesPerSlot} survive (owned/included are exempt, as
     * everywhere).
     *
     * <p>This replaces the old target-blind linear proxy ({@code arange +
     * 2*rstr} for ranged), which systematically mis-ranked everything whose
     * value isn't a raw bonus sum: attack SPEED (a 3-tick blowpipe's whole
     * advantage — measured: it ranked ~50th of the ranged pool and was
     * always pruned), target passives (demonbane/dragonbane/Twisted bow),
     * ammo the weapon brings vs. ammo it wears, and powered-staff scaling.
     * A per-candidate evaluation is a few microseconds of pure arithmetic;
     * even the unconstrained ~1500-weapon pool costs low tens of
     * milliseconds once per search, within the class javadoc's stated
     * budget. Weapons that evaluate to {@code null} (cannot attack under the
     * style/spellbook constraint) are dropped unless owned/included.
     */
    private static List<Candidate> pruneWeaponCandidatesByDps(List<Candidate> affordable, Request request,
                                                              List<Candidate> ammoCandidates) {
        final class Scored {
            final Candidate candidate;
            final double dps;

            Scored(Candidate candidate, double dps) {
                this.candidate = candidate;
                this.dps = dps;
            }
        }
        List<Scored> scored = new ArrayList<>(affordable.size());
        for (Candidate c : affordable) {
            int[] trial = applySlotChoice(request.liveItemIds, WhatIfLoadout.WEAPON_SLOT, c.itemId());
            trial = withBestCompatibleAmmo(trial, ammoCandidates, request);
            Evaluation eval = evaluate(trial, request);
            scored.add(new Scored(c, eval == null ? Double.NEGATIVE_INFINITY : eval.dps.dps()));
        }
        scored.sort((a, b) -> Double.compare(b.dps, a.dps));
        List<Candidate> pruned = new ArrayList<>();
        Set<Integer> keptIds = new HashSet<>();
        List<Candidate> viableByDps = new ArrayList<>(scored.size());
        for (Scored s : scored) {
            boolean mandatory = mandatoryCandidate(s.candidate, request);
            if (mandatory || (pruned.size() < request.candidatesPerSlot && s.dps != Double.NEGATIVE_INFINITY)) {
                pruned.add(s.candidate);
                keptIds.add(s.candidate.itemId());
            }
            if (s.dps != Double.NEGATIVE_INFINITY) {
                // Already DPS-sorted; weapons that can't attack under the
                // style/spellbook constraint are excluded so the expensive-
                // item retention below never resurrects an unusable weapon.
                viableByDps.add(s.candidate);
            }
        }
        retainSubCeilingCandidates(viableByDps, pruned, keptIds, request);
        return pruned;
    }

    /**
     * Ammo-slot pruning, per {@link com.ospulse.combat.AmmoCompatibility}
     * class: the searched weapon changes during the search (bow vs crossbow
     * vs blowpipe), so instead of one flat top-N (which the highest-rstr
     * class — javelins — would monopolise), the list keeps the top
     * {@code candidatesPerSlot} of EVERY consumable class ranked by the
     * ranged proxy, plus the top blessings ranked by prayer bonus, so
     * whatever weapon the search lands on finds its own class's best ammo
     * (and non-consuming weapons find a blessing). Owned/included are exempt
     * from pruning as always. Within each class the order is best-first,
     * which {@link #withBestCompatibleAmmo} relies on.
     */
    private static List<Candidate> pruneAmmoCandidates(List<Candidate> affordable, Request request) {
        java.util.Map<AmmoCompatibility.AmmoClass, List<Candidate>> byClass = new java.util.LinkedHashMap<>();
        for (AmmoCompatibility.AmmoClass ammoClass : AmmoCompatibility.AmmoClass.values()) {
            byClass.put(ammoClass, new ArrayList<>());
        }
        List<Candidate> unclassified = new ArrayList<>();
        for (Candidate c : affordable) {
            AmmoCompatibility.AmmoClass ammoClass = AmmoCompatibility.classify(c.itemId());
            (ammoClass == null ? unclassified : byClass.get(ammoClass)).add(c);
        }

        List<Candidate> pruned = new ArrayList<>();
        for (java.util.Map.Entry<AmmoCompatibility.AmmoClass, List<Candidate>> entry : byClass.entrySet()) {
            List<Candidate> group = entry.getValue();
            if (entry.getKey().isConsumable()) {
                // Ranged strength drives consumable ammo's DPS contribution.
                group.sort(Comparator.comparingInt((Candidate c) ->
                        -CandidateScore.proxyOffensiveScore(c.itemId(), CombatStyle.RANGED)));
            } else {
                // Blessings are DPS-invisible — prayer bonus is their value.
                group.sort(Comparator.comparingInt((Candidate c) -> -CandidateScore.prayerBonusOf(c.itemId())));
            }
            addPrunedGroup(pruned, group, request);
        }
        // Unknown/unclassifiable ammo (not expected with current data): keep
        // the old proxy ranking so nothing silently disappears.
        unclassified.sort(Comparator.comparingInt((Candidate c) ->
                -CandidateScore.proxyOffensiveScore(c.itemId(), CombatStyle.RANGED)));
        addPrunedGroup(pruned, unclassified, request);
        return pruned;
    }

    /** Appends {@code group}'s top {@code candidatesPerSlot} entries to {@code out} (owned/included always kept). */
    private static void addPrunedGroup(List<Candidate> out, List<Candidate> group, Request request) {
        int kept = 0;
        for (Candidate c : group) {
            boolean mandatory = mandatoryCandidate(c, request);
            if (mandatory || kept < request.candidatesPerSlot) {
                out.add(c);
                kept++;
            }
        }
    }

    // Item-id scoring heuristics (tieBreakScore, prayerBonusOf,
    // weaponSupportsStyle, proxyOffensiveScore) now live in CandidateScore —
    // pure proxies with no dependency on Request or an in-progress loadout.

    /** One fully-evaluated candidate loadout: its best style/spell and resulting DPS. */
    private static final class Evaluation {
        final DpsResult dps;
        final WeaponStyle style;
        final Spell spell;

        Evaluation(DpsResult dps, WeaponStyle style, Spell spell) {
            this.dps = dps;
            this.style = style;
            this.spell = spell;
        }
    }

    /**
     * Evaluates one full loadout: resolves its weapon's real styles/spells
     * (see {@link WeaponCategoryRepository}) and returns the BEST-DPS
     * style/spell for it — mirroring {@code GearSection}'s ranked picker so
     * the optimiser never undervalues a weapon whose best style differs from
     * another candidate's. Returns {@code null} if nothing is computable
     * (e.g. no target).
     */
    private static Evaluation evaluate(int[] itemIds, Request request) {
        if (request.target == null) {
            return null;
        }
        EquipmentStats stats = GearMapper.buildEquipmentStats(itemIds, WhatIfLoadout.WEAPON_SLOT, BundledSlotStatsLookup.INSTANCE);
        int weaponId = itemIds.length > WhatIfLoadout.WEAPON_SLOT ? itemIds[WhatIfLoadout.WEAPON_SLOT] : -1;
        List<WeaponStyle> styles = WeaponCategoryRepository.getInstance().stylesForItem(weaponId);

        DpsResult best = null;
        WeaponStyle bestStyle = null;
        Spell bestSpell = null;

        boolean poweredStaff = stats.poweredStaff().applies();
        int ammoId = itemIds.length > AMMO_SLOT ? itemIds[AMMO_SLOT] : -1;
        boolean weaponUsesWornAmmo = AmmoCompatibility.consumedClass(weaponId) != null;
        for (WeaponStyle style : styles) {
            if (request.style != null && style.type() != request.style) {
                // Style-constrained search (item #6e): only styles of the
                // requested damage type may drive the DPS. A weapon with no
                // such style yields best == null -> this loadout is unusable
                // under the constraint (never silently scored at another type).
                continue;
            }
            if (request.combatRequirement != null
                    && (!request.combatRequirement.permitsWeapon(weaponId, style.type(), weaponUsesWornAmmo)
                        || !request.combatRequirement.permitsAmmo(ammoId, style.type()))) {
                // Monster combat gate (B9-1): a (weapon, style, worn-ammo) combo
                // the monster cannot be damaged by scores no DPS. The candidate
                // pruning already drops gated weapons/ammo, but the SEED loadout
                // carries the player's live worn ammo, which pruning never sees —
                // so without this check a bow + non-broad worn arrows would score
                // a bogus positive ranged DPS vs Kurask and wrongly offer Ranged.
                // Mirrors GearSection's readout gate (permits()) so the two agree.
                continue;
            }
            PlayerCombat player = request.playerTemplate.stance(style.stance()).build();
            if (style.type() == CombatStyle.MAGIC) {
                if (poweredStaff) {
                    DpsResult r = DpsCalculator.compute(stats, player, CombatStyle.MAGIC, request.target, (Spell) null,
                            weaponId, request.combatRequirement);
                    if (best == null || r.dps() > best.dps()) {
                        best = r;
                        bestStyle = style;
                        bestSpell = null;
                    }
                } else {
                    for (Spell spell : Spell.values()) {
                        if (spell.book() != Spell.SpellBook.STANDARD && spell.book() != Spell.SpellBook.ANCIENT) {
                            continue;
                        }
                        if (request.spellBook != null && spell.book() != request.spellBook) {
                            // Constrained to the magic view's selected spellbook
                            // tab: the gear DPS follows the book the user chose,
                            // not whichever book's best spell is globally higher.
                            continue;
                        }
                        if (!spell.isCastableWith(weaponId)) {
                            // Mirrors GearSection's ranked spell picker: e.g. Iban
                            // Blast must never inflate a non-Iban's-staff weapon.
                            continue;
                        }
                        DpsResult r = DpsCalculator.compute(stats, player, CombatStyle.MAGIC, request.target, spell,
                                weaponId, request.combatRequirement);
                        if (best == null || r.dps() > best.dps()) {
                            best = r;
                            bestStyle = style;
                            bestSpell = spell;
                        }
                    }
                }
            } else {
                DpsResult r = DpsCalculator.compute(stats, player, style.type(), request.target, 0, weaponId,
                        request.combatRequirement);
                if (best == null || r.dps() > best.dps()) {
                    best = r;
                    bestStyle = style;
                    bestSpell = null;
                }
            }
        }
        return best == null ? null : new Evaluation(best, bestStyle, bestSpell);
    }

    private static double ownedOnlyBestDps(Request request, EquipmentIndexRepository index) {
        int[] current = request.liveItemIds.clone();
        // Owned ammo, best-first by the ranged proxy, for weapon-trial ammo
        // pairing (see withBestCompatibleAmmo) — an owned bow's baseline DPS
        // must include the player's own best arrows.
        List<Candidate> ownedAmmo = new ArrayList<>();
        for (EquipmentIndexRepository.Entry e : index.forSlot(AMMO_SLOT)) {
            if (request.owned.contains(e.itemId()) && !request.exclude.contains(e.itemId())) {
                ownedAmmo.add(new Candidate(e.itemId(), 0L, true));
            }
        }
        ownedAmmo.sort(Comparator.comparingInt((Candidate c) ->
                -CandidateScore.proxyOffensiveScore(c.itemId(), CombatStyle.RANGED)));
        for (int slot : SEARCHABLE_SLOTS) {
            List<Candidate> ownedCandidates = new ArrayList<>();
            for (EquipmentIndexRepository.Entry e : index.forSlot(slot)) {
                if (request.owned.contains(e.itemId()) && !request.exclude.contains(e.itemId())) {
                    ownedCandidates.add(new Candidate(e.itemId(), 0L, true));
                }
            }
            current = bestSingleSlotChoice(current, slot, ownedCandidates, request, ownedAmmo);
        }
        // One local-search pass for interactions among owned items too (cheap — owned pools are small).
        for (int pass = 0; pass < MAX_LOCAL_SEARCH_PASSES; pass++) {
            boolean improved = false;
            for (int slot : SEARCHABLE_SLOTS) {
                List<Candidate> ownedCandidates = new ArrayList<>();
                for (EquipmentIndexRepository.Entry e : index.forSlot(slot)) {
                    if (request.owned.contains(e.itemId()) && !request.exclude.contains(e.itemId())) {
                        ownedCandidates.add(new Candidate(e.itemId(), 0L, true));
                    }
                }
                Evaluation before = evaluate(current, request);
                int[] afterArr = bestSingleSlotChoice(current, slot, ownedCandidates, request, ownedAmmo);
                Evaluation after = evaluate(afterArr, request);
                if (after != null && (before == null || after.dps.dps() > before.dps.dps() + 1e-9)) {
                    current = afterArr;
                    improved = true;
                }
            }
            if (!improved) {
                break;
            }
        }
        Evaluation eval = evaluate(current, request);
        return eval == null ? 0.0 : eval.dps.dps();
    }

    private static DpsResult zeroDps() {
        return new DpsResult(0, 0, 0, 0, 0, 0, false);
    }
}

package com.ospulse.combat;

import com.google.gson.Gson;

/**
 * Holder for the RuneLite client's injected {@link Gson}, seeded once at
 * plugin start-up so the static combat repositories can parse their bundled
 * JSON through the client's shared instance instead of constructing their own
 * (the Plugin Hub packager forbids fresh Gson instances in shipped code).
 *
 * <p>Tests that exercise the repositories outside the client seed this
 * themselves before the first repository load.
 */
public final class BundledGson {
    private static volatile Gson gson;

    private BundledGson() {
    }

    /** Seeds the shared instance; the plugin does this before any repository loads. */
    public static void set(Gson g) {
        gson = g;
    }

    /** The shared instance, or throws if nothing has seeded it yet. */
    public static Gson get() {
        Gson g = gson;
        if (g == null) {
            throw new IllegalStateException(
                "BundledGson not initialised - seed it (OSPulsePlugin.startUp or test setup) "
                    + "before the combat repositories load");
        }
        return g;
    }
}

package com.ospulse.combat;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Picks the single best curated {@link SpecWeapon} to recommend for the
 * current target, per the design spec §8 "Selection rule" (director decision
 * — implemented exactly as specified below, not redesigned):
 * <pre>
 * 1. Filter to owned ({@link SpecWeapon#isOwned}), NOT excluded ({@link
 *    SpecWeapon#isExcluded} — the panel's user-facing "Exclude from
 *    suggestions" action, same as any ordinary optimiser candidate), NOT
 *    permanently restricted ({@link SpecWeapon#itemId()} present in the
 *    caller's mode-lock restriction set — per-ID only, deliberately not
 *    alias-symmetric like {@code isExcluded}), equippable at the player's
 *    current levels ({@link SpecWeapon#canEquip} — owning an item never
 *    implies meeting its equip requirements), and legal ({@link
 *    MonsterCombatRequirement#permitsWeapon}/{@link
 *    MonsterCombatRequirement#permitsAmmo} — a ranged spec that fires WORN
 *    ammo must also have the player's actual worn ammo satisfy an
 *    ammo-gated target; {@code permitsWeapon} alone deliberately accepts a
 *    worn-ammo-capable weapon type without checking which ammo is actually
 *    loaded) — so a monster with a melee gate (e.g. Zulrah) never gets a
 *    melee spec suggested, and an ammo-gated target (e.g. Kurask) never
 *    gets a ranged spec suggested unless the player's actual arrows/bolts
 *    qualify, falling out of the existing combat-requirement work for free.
 * 2. If the target's Defence is high enough to matter
 *    ({@link #HIGH_DEFENCE_THRESHOLD}) and a {@link SpecRole#DEFENCE_DRAIN}
 *    spec is owned+legal, recommend the best-scoring one of those.
 * 3. Otherwise recommend the best-scoring owned+legal {@link SpecRole#DAMAGE}
 *    spec, scored by expected damage per use divided by spec-bar cost
 *    ("damage per spec-bar %").
 * 4. {@link SpecRole#UTILITY} specs are never recommended.
 * 5. Final fallback (round-2 director decision, added after the original
 *    rule shipped): if neither step 2 nor step 3 produced a recommendation
 *    — the player owns no applicable {@code DAMAGE} or {@code
 *    DEFENCE_DRAIN} spec for this target — but does own a {@link
 *    SpecRole#HEAL} spec, recommend it. Sustain is genuinely incommensurable
 *    with damage and unknowable at planning time, so it deliberately never
 *    OUTRANKS steps 2-3; it only fills the gap where they would otherwise
 *    recommend nothing at all, which is strictly worse when the player is
 *    holding a Saradomin godsword. Its readout names the effect ("heals 50%
 *    of damage dealt"), never a DPS number, so it carries no false claim.
 * </pre>
 *
 * <p><b>Interpreting "no applicable DEFENCE_DRAIN" for step 5.</b> A
 * DEFENCE_DRAIN spec that IS owned+legal but whose target doesn't clear
 * {@link #HIGH_DEFENCE_THRESHOLD} (so step 2 never fires) is treated the
 * same as "none owned" for step 5's purposes — the rule falls through to
 * whatever step 3/5 produces rather than recommending a drain the target is
 * too weak to warrant. This one under-specified cell was not covered by
 * either of the director's two required HEAL-fallback scenarios (own ONLY
 * HEAL; own HEAL AND DAMAGE), so it is resolved by the simplest reading
 * that adds no branch beyond what was asked, stated here rather than left
 * implicit.
 */
public final class SpecWeaponSelector {
    private SpecWeaponSelector() {
    }

    /**
     * "High enough [Defence] to matter" (design spec §8) — derived from the
     * bundled monster defence-level distribution in {@code
     * monsters.min.json.gz}, not invented. That file holds 2830 rows across
     * every monster/phase; deduplicating to one entry per distinct base name
     * (keeping each monster's highest-defence phase) gives 1497 distinct
     * monsters with defence levels ranging 0-480 (mean 69.3, median 52).
     * This constant is the 90th percentile of THAT distribution: 150. In
     * other words, a defence-drain spec is only recommended over a pure
     * damage spec against a target in the toughest 10% of monsters by
     * Defence — exactly the point of the role split (a drain that never
     * meaningfully reduces the target's effective defence isn't worth
     * spending the spec bar on). Computed 2026-07-26 via a one-off script
     * over the bundled data; re-derive the same way if the bundled monster
     * set is ever refreshed and this should be revisited.
     */
    static final int HIGH_DEFENCE_THRESHOLD = 150;

    /**
     * Supplies the (hitChance, maxHit) pair for wielding one curated {@link
     * SpecWeapon} at its own {@link SpecWeapon#style()} against the current
     * target, with every other worn slot held fixed and only the weapon slot
     * swapped to the candidate — "if I switched to this weapon and attacked
     * normally, what would that attack roll look like" — the same
     * swap-one-slot machinery {@code GearOptimizer} already uses for
     * ordinary candidate scoring. {@code null} when not computable (e.g. no
     * target selected, or the weapon's style can't be resolved).
     */
    public interface DpsProbe {
        DpsResult probe(SpecWeapon weapon);
    }

    /**
     * Convenience overload for a caller with no exclusions, no equip-level
     * data, and no worn ammo to validate (e.g. a test exercising only the
     * role/threshold/ownership/legality logic) — equivalent to calling the
     * full overload with an empty exclusion set, an empty level map (which
     * {@link EquipmentRequirementsRepository#canEquip} treats as "don't
     * over-filter"), and no worn ammo id.
     */
    public static Optional<SpecWeaponRecommendation> select(Monster target, MonsterCombatRequirement requirement,
                                                              Set<Integer> ownedItemIds, DpsProbe probe) {
        return select(target, requirement, ownedItemIds, java.util.Collections.emptySet(),
                java.util.Collections.emptyMap(), -1, probe);
    }

    /**
     * Back-compat overload with no standing (mode-locked) restriction set —
     * equivalent to calling the full overload with an empty {@code
     * restrictedItemIds}. See the full overload for the exact rule.
     *
     * @param excludedItemIds   the panel's "Exclude from suggestions" set —
     *                          a USER action, alias-symmetric via {@link
     *                          SpecWeapon#isExcluded} (excluding any cosmetic
     *                          recolour excludes the whole weapon family).
     */
    public static Optional<SpecWeaponRecommendation> select(Monster target, MonsterCombatRequirement requirement,
                                                              Set<Integer> ownedItemIds, Set<Integer> excludedItemIds,
                                                              Map<String, Integer> playerBaseLevels, int wornAmmoItemId,
                                                              DpsProbe probe) {
        return select(target, requirement, ownedItemIds, excludedItemIds, java.util.Collections.emptySet(),
                playerBaseLevels, wornAmmoItemId, probe);
    }

    /**
     * See the class javadoc for the exact rule; {@link Optional#empty()} when
     * nothing owned+legal qualifies.
     *
     * @param excludedItemIds    the panel's "Exclude from suggestions" set —
     *                           a USER action, alias-symmetric via {@link
     *                           SpecWeapon#isExcluded}: excluding any one
     *                           cosmetic-recolour/alias id excludes the whole
     *                           weapon family, same as an ordinary optimiser
     *                           candidate.
     * @param restrictedItemIds  standing, permanent per-ID restrictions (e.g.
     *                           {@code ItemEligibility.restrictedItemIds()} —
     *                           Deadman/BH/LMS/beta-locked ids). NOT merged
     *                           with {@code excludedItemIds}: a restriction
     *                           is checked per-ID against whichever id(s) the
     *                           player actually owns ({@link
     *                           SpecWeapon#hasOwnedUnrestrictedId}, round-3
     *                           fix), not family-wide like {@code
     *                           excludedItemIds} and not against the
     *                           canonical id alone. Round-2 fix: merging it
     *                           into the alias-symmetric exclusion set
     *                           previously suppressed an entire family, e.g.
     *                           Voidwaker (deadman) 29607 being restricted
     *                           wrongly excluded the ordinary, perfectly
     *                           legal Voidwaker 27690. Round-3 fix: checking
     *                           only the canonical id then swung too far the
     *                           other way — a player who owned ONLY the
     *                           restricted alias 29607 (never 27690) was
     *                           still recommended 27690, because 27690 itself
     *                           was unrestricted even though the player never
     *                           owned it.
     * @param playerBaseLevels   the player's base skill levels (lowercase
     *                           skill-name keys, e.g. {@code "attack"}), fed
     *                           straight to {@link SpecWeapon#canEquip} — the
     *                           SAME map {@code GearOptimizer.Request}'s
     *                           {@code playerBaseLevels} carries.
     * @param wornAmmoItemId     the player's currently effective worn ammo
     *                           item id (or {@code <= 0} for none) — used for
     *                           ANY candidate that fires worn ammo (see
     *                           {@link AmmoCompatibility#consumedClass}),
     *                           regardless of target, to enforce that the
     *                           worn ammo's class actually matches what the
     *                           weapon fires; ALSO fed to {@link
     *                           MonsterCombatRequirement#permitsAmmo} when
     *                           the target additionally gates ammo (e.g.
     *                           Kurask's broad-ammo-only gate — {@code
     *                           permitsWeapon} alone can't tell "Zaryte
     *                           crossbow, but the ammo gate needs broad
     *                           bolts and I'm not wearing any").
     */
    public static Optional<SpecWeaponRecommendation> select(Monster target, MonsterCombatRequirement requirement,
                                                              Set<Integer> ownedItemIds, Set<Integer> excludedItemIds,
                                                              Set<Integer> restrictedItemIds,
                                                              Map<String, Integer> playerBaseLevels, int wornAmmoItemId,
                                                              DpsProbe probe) {
        if (target == null || ownedItemIds == null || probe == null) {
            return Optional.empty();
        }
        Set<Integer> exclusions = excludedItemIds == null ? java.util.Collections.emptySet() : excludedItemIds;
        Set<Integer> restrictions = restrictedItemIds == null ? java.util.Collections.emptySet() : restrictedItemIds;
        List<SpecWeapon> eligible = new ArrayList<>();
        for (SpecWeapon weapon : SpecWeapon.CATALOG) {
            if (weapon.role() == SpecRole.UTILITY) {
                continue; // rule 4 — never recommended, so not even worth probing.
            }
            if (!weapon.isOwned(ownedItemIds)) {
                continue;
            }
            if (weapon.isExcluded(exclusions)) {
                continue; // "Exclude from suggestions" — same rule an ordinary candidate obeys.
            }
            if (!weapon.hasOwnedUnrestrictedId(ownedItemIds, restrictions)) {
                // Per-ID, applied to whichever id(s) are actually owned —
                // see the @param javadoc above and {@link
                // SpecWeapon#hasOwnedUnrestrictedId} (round-3 fix). A
                // restricted ALIAS (e.g. the deadman recolour) must not
                // suppress this row when the player owns a DIFFERENT,
                // unrestricted id in the same family (e.g. the canonical
                // id) — but must reject it when the only id the player
                // actually owns IS the restricted one.
                continue;
            }
            if (!weapon.canEquip(playerBaseLevels)) {
                continue; // owning it is not the same as meeting its equip requirements.
            }
            AmmoCompatibility.AmmoClass consumedClass = AmmoCompatibility.consumedClass(weapon.itemId());
            boolean weaponUsesWornAmmo = consumedClass != null;
            if (weapon.style() == CombatStyle.RANGED && weaponUsesWornAmmo
                    && AmmoCompatibility.classify(wornAmmoItemId) != consumedClass) {
                // Weapon/ammo compatibility is a property of the WEAPON and
                // must be enforced regardless of whether the monster gates
                // ammo at all — most targets are unrestricted, so this can't
                // live inside the `requirement != null` branch below. E.g. a
                // Magic shortbow (fires ARROW) with broad bolts (BOLT) worn
                // must be rejected even at a target with no combat
                // requirement, and even at one whose allowedAmmoIds happen to
                // include broad bolts for a DIFFERENT weapon (Kurask permits
                // both broad arrows and broad bolts).
                continue;
            }
            if (requirement != null) {
                if (!requirement.permitsWeapon(weapon.itemId(), weapon.style(), weaponUsesWornAmmo)) {
                    continue;
                }
                if (weapon.style() == CombatStyle.RANGED && weaponUsesWornAmmo
                        && !requirement.permitsAmmo(wornAmmoItemId, weapon.style())) {
                    // permitsWeapon() alone accepts any worn-ammo-capable
                    // ranged weapon on an ammo-gated target (e.g. Kurask) —
                    // it can't know WHICH ammo is actually loaded. A weapon
                    // that fires its own ammo (blowpipe) never reaches this
                    // branch: weaponUsesWornAmmo is false for it.
                    continue;
                }
            }
            eligible.add(weapon);
        }
        if (eligible.isEmpty()) {
            return Optional.empty();
        }

        if (target.defenceLevel() >= HIGH_DEFENCE_THRESHOLD) {
            SpecWeaponRecommendation drain = bestByRole(eligible, SpecRole.DEFENCE_DRAIN, probe);
            if (drain != null) {
                return Optional.of(drain);
            }
        }
        SpecWeaponRecommendation damage = bestByRole(eligible, SpecRole.DAMAGE, probe);
        if (damage != null) {
            return Optional.of(damage);
        }
        // Step 5 fallback — see class javadoc. Never reached when step 2 or 3
        // above already returned.
        return Optional.ofNullable(bestByRole(eligible, SpecRole.HEAL, probe));
    }

    /**
     * <b>Known limitation — not target-damage-cap aware.</b> {@link
     * DpsResult#maxHit()} is the target's VISIBLE max hit ({@code
     * DpsCalculator.finish} sets it from {@code TargetDamage.visibleMaxHit()},
     * i.e. {@code min(uncapped, cap)}), so at a damage-capped target — The
     * Hueycoatl's tail ({@code CLAMP}), Verzik Vitur phase 1 ({@code REROLL}) —
     * the {@code expectedDamagePerUse} call below applies the special's boosts
     * and multi-hit cascade to a number the cap has already been folded into,
     * as if it were the weapon's uncapped base roll. The boosted hitsplat can
     * then exceed the target's ceiling, and multi-hit specials lose the real
     * uncapped distribution before each hitsplat is capped or re-rolled.
     *
     * <p>This distorts the SCORE and so can reorder the recommendation at those
     * targets; it never reaches the player as a displayed max hit. Fixing it
     * means carrying the uncapped max, the cap and the {@code CapMode} from
     * {@link DpsCalculator} through {@link DpsResult} into every {@code
     * SpecWeapon.DamageModel} and applying the cap per hitsplat in all six
     * model families, including {@link SpecCascadeMath}'s reverse-engineered
     * claw/dagger branch enumerations. Deliberately deferred to its own change
     * rather than done partially — making some model families cap-aware and not
     * others would skew the cross-weapon comparison this method exists to make.
     * Pinned by {@code SpecWeaponDamageCapLimitationTest} (PR #25 round 4).
     */
    private static SpecWeaponRecommendation bestByRole(List<SpecWeapon> eligible, SpecRole role, DpsProbe probe) {
        SpecWeapon bestWeapon = null;
        double bestScore = Double.NEGATIVE_INFINITY;
        for (SpecWeapon weapon : eligible) {
            if (weapon.role() != role) {
                continue;
            }
            DpsResult result = probe.probe(weapon);
            if (result == null) {
                continue;
            }
            double damagePerUse = weapon.expectedDamagePerUse(result.accuracy(), result.maxHit());
            double score = damagePerUse / weapon.specCostPercent();
            if (score > bestScore) {
                bestScore = score;
                bestWeapon = weapon;
            }
        }
        return bestWeapon == null ? null : new SpecWeaponRecommendation(bestWeapon, bestScore);
    }
}

package com.ospulse.combat;

import com.ospulse.OSPulseConfig;
import net.runelite.client.config.ConfigManager;

/**
 * The dart type assumed loaded inside a blowpipe (Toxic/Blazing/Drygore/
 * Camphor/Ironwood/Rosewood blowpipe — every 2H ranged "blowpipe" weapon
 * variant). A blowpipe loads darts <i>internally</i>: the loaded dart is not
 * held in the equipment ammo slot, and the blowpipe ignores whatever item is
 * worn there. Each dart only contributes ranged strength (its ranged-attack
 * bonus is 0) — see {@link #rangedStrength()}. Values verified against the
 * bundled equipment_stats data and the OSRS Wiki (dart ranged-strength table)
 * 2026-07-04. Picked via the gear panel's blowpipe right-click "Set darts"
 * submenu, persisted under the {@value #CONFIG_KEY} config key.
 */
public enum BlowpipeDart
{
	BRONZE("Bronze", 1),
	IRON("Iron", 2),
	STEEL("Steel", 3),
	BLACK("Black", 6),
	MITHRIL("Mithril", 9),
	ADAMANT("Adamant", 17),
	RUNE("Rune", 26),
	AMETHYST("Amethyst", 28),
	DRAGON("Dragon", 35);

	/** Config key the picked dart persists under (raw {@link ConfigManager} storage — no {@code @ConfigItem}). */
	public static final String CONFIG_KEY = "blowpipeDart";

	private final String displayName;
	private final int rangedStrength;

	BlowpipeDart(String displayName, int rangedStrength)
	{
		this.displayName = displayName;
		this.rangedStrength = rangedStrength;
	}

	/** The dart's ranged-strength bonus (its ranged-attack bonus is always 0). */
	public int rangedStrength()
	{
		return rangedStrength;
	}

	/**
	 * The dart the user picked via the gear panel's "Set darts" submenu,
	 * read from raw {@link ConfigManager} storage (the {@value #CONFIG_KEY}
	 * key — there is no {@code @ConfigItem}, dart selection lives in the panel
	 * UI, not the settings screen). Falls back to {@link #DRAGON} when there is
	 * no config manager (headless tests), no stored value, or a stale/unknown
	 * enum name (e.g. an older plugin version).
	 */
	public static BlowpipeDart fromConfig(ConfigManager configManager)
	{
		if (configManager == null)
		{
			return DRAGON;
		}
		String raw = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY);
		if (raw == null || raw.isEmpty())
		{
			return DRAGON;
		}
		try
		{
			return BlowpipeDart.valueOf(raw);
		}
		catch (IllegalArgumentException e)
		{
			return DRAGON;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.ospulse.combat;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Curated map of an assembled (untradeable) piece of equipment to the tradeable
 * component whose Grand Exchange price stands in for "buying" it.
 *
 * <p>Some best-in-slot items can't be bought off the GE directly because the
 * final item is untradeable, but they are assembled from a tradeable part the
 * player buys and combines with something they already own. The flagship case:
 * an <b>Avernic defender</b> (untradeable) is made by using an <b>Avernic
 * defender hilt</b> (tradeable, ~31.8M) on a dragon defender the player already
 * has. Left as a plain untradeable, the gear optimiser can never recommend it
 * as an upgrade even when the player can clearly afford the hilt.
 *
 * <p>The optimiser therefore prices the assembled item at its component's GE
 * price while keeping the assembled item's own id (and hence its own name in
 * the readout), so it can recommend "Avernic defender" at the hilt's cost.
 * Jonathan's call: don't over-explain in the UI — just show the assembled
 * item's name at the component price; players understand it means "buy the
 * hilt". Only tradeable components with a real price are used; anything else
 * falls back to the normal untradeable = unbuyable rule.
 *
 * <p>Item ids verified against the RuneLite {@code net.runelite.api.ItemID}
 * constants ({@code AVERNIC_DEFENDER = 22322}, {@code AVERNIC_DEFENDER_HILT =
 * 22477}), not the wiki. Extend by adding one line per assembled/component
 * pair.
 */
public final class AssembledItemComponents
{
	/** assembled (untradeable) item id -> tradeable component item id whose price to use. */
	private static final Map<Integer, Integer> PRICE_SOURCE;

	static
	{
		Map<Integer, Integer> m = new HashMap<>();
		m.put(22322, 22477); // Avernic defender <- Avernic defender hilt
		PRICE_SOURCE = Collections.unmodifiableMap(m);
	}

	private AssembledItemComponents()
	{
	}

	/**
	 * @param assembledId an equipment item id
	 * @return the tradeable component item id whose GE price stands in for
	 *         buying {@code assembledId}, or {@code null} if this item is not a
	 *         curated assembled-from-component case
	 */
	public static Integer priceSourceComponent(int assembledId)
	{
		return PRICE_SOURCE.get(assembledId);
	}
}

package com.ospulse.combat;

/**
 * The Twinflame staff's (item id 30634 — see {@code GearVariants}) second-hit
 * passive, extracted into its own small, pure, dependency-light class (per
 * the existing precedent of {@code DemonbaneWeapon}/{@code
 * DragonHunterWeapon}/{@code Tome}/{@code VoidSet}) rather than folded into
 * {@code CombatMath}, so this narrow mechanic can be unit-tested in
 * isolation and extracted further without touching that already-large,
 * concurrently-edited file.
 *
 * <p>Per the OSRS Wiki: "the staff fires two spells at once ... when casting
 * elemental spells (excluding Strike and Surge spells)" (gated by {@link
 * Spell#twinflameEligible()}, which lives on {@link Spell} since it is
 * genuinely spell metadata) and "the second hit will land one tick after the
 * first, dealing 40% of the damage dealt by the first, rounded down." The
 * second spell does not consume runes/charges or grant XP — irrelevant here,
 * since this calculator only models damage/DPS.
 *
 * <p><b>The second hit is NOT an independent roll or accuracy check.</b> Per
 * the OSRS Wiki's own DPS calculator (weirdgloop/osrs-dps-calc,
 * {@code PlayerVsNPCCalc.ts}), the second hitsplat is derived from the FIRST
 * hit's actual rolled damage {@code d} as {@code floor(0.4 * d)} — a missed
 * first hit yields a zero second hit, and a landed first hit always produces
 * this second hit alongside it (both hitsplats share the same landed-hit
 * probability, {@code hitChance}).
 *
 * <p><b>Why the floor cannot be pulled out of the expectation:</b> {@code
 * floor} is not a linear operator, so {@code E[floor(0.4*D)] != 0.4*E[D]} in
 * general — e.g. rolls of 1, 2, 3 and 4 all floor {@code 0.4*d} to 0, 0, 1,
 * and 1 respectively, not a smooth 0.4x scaling. The only correct way to get
 * the exact expectation is to sum {@code floor(0.4*d) * P(d)} over the same
 * discrete per-attack damage distribution {@code DamageDistribution
 * .averageDamage} uses: a landed hit rolls uniform {@code 0..maxHit}
 * with a rolled 0 bumped to 1 (so {@code P(1) = 2/(maxHit+1)}, {@code P(d) =
 * 1/(maxHit+1)} for {@code d} in {@code 2..maxHit}). A short direct
 * enumeration over that range is exact and fast (magic max hits are small),
 * so that is what every method below does — no closed form is derived.
 */
final class TwinflameSecondHit {
    private TwinflameSecondHit() {
    }

    /**
     * Exact expected second-hit damage per attack (misses included), for an
     * uncapped target: {@code hitChance * sum_{d=1..maxHit} P(d) * floor(0.4*d)}.
     * {@code floor(0.4*d)} is computed as the exact integer division
     * {@code (2*d)/5} (Java truncates toward zero, identical to floor for
     * non-negative {@code d}) to avoid any floating-point rounding on the
     * 0.4 literal.
     */
    static double secondHitAverage(double hitChance, int maxHit) {
        if (maxHit <= 0) {
            return 0.0;
        }
        double denom = maxHit + 1.0;
        double sum = 0.0;
        for (int d = 1; d <= maxHit; d++) {
            double p = (d == 1 ? 2.0 : 1.0) / denom;
            sum += p * ((2 * d) / 5);
        }
        return hitChance * sum;
    }

    /**
     * Exact expected second-hit damage per attack when the target caps each
     * hitsplat (e.g. The Hueycoatl's tail — see {@code TargetDamageRule}).
     *
     * <p>The wiki's "40% of the damage DEALT by the first hit" is the
     * first hit's DISPLAYED (i.e. already-capped) value, so this enumerates
     * the same raw roll {@code d} over {@code 0..uncappedMaxHit} as {@link
     * #secondHitAverage}, clamps each {@code d} to the cap to get the
     * visible first-hit damage, then floors 40% of THAT. The second hit's own
     * value is never itself reduced further by the cap: it is at most {@code
     * floor(0.4*cap)}, strictly below {@code cap} for any {@code cap > 0},
     * so it can never exceed the per-hitsplat ceiling on its own.
     */
    static double cappedSecondHitAverage(double hitChance, int uncappedMaxHit, int cap) {
        if (cap >= uncappedMaxHit) {
            return secondHitAverage(hitChance, uncappedMaxHit);
        }
        if (cap <= 0 || uncappedMaxHit <= 0) {
            return 0.0;
        }
        double denom = uncappedMaxHit + 1.0;
        double sum = 0.0;
        for (int d = 1; d <= uncappedMaxHit; d++) {
            double p = (d == 1 ? 2.0 : 1.0) / denom;
            int visibleFirst = Math.min(d, cap);
            sum += p * ((2 * visibleFirst) / 5);
        }
        return hitChance * sum;
    }

    /**
     * Exact expected second-hit damage per attack when a monster RE-ROLLS
     * each hitsplat above a cap back into {@code 0..cap} (e.g. Verzik Vitur
     * phase 1), as opposed to {@link #cappedSecondHitAverage}'s clamp.
     *
     * <p>The 40%-of-first-hit rule reads off the DISPLAYED first hit, i.e.
     * the value AFTER any re-roll — so this sums {@code floor(0.4*v) * P(v)}
     * over {@link DamageDistribution#rerolledHitsplatDistribution}'s {@code 0..cap}
     * array (the same one {@link DamageDistribution#rerolledExpectedOverkill} uses),
     * NOT over the raw {@code 0..uncappedMaxHit} roll the uncapped {@link
     * #secondHitAverage} enumerates. Using the raw roll here would be the
     * exact "REROLL is just a clamp with extra steps" mistake this whole
     * feature keeps having to guard against elsewhere.
     *
     * <p>{@code cap >= uncappedMaxHit}: nothing is ever re-rolled, so this
     * delegates to {@link #secondHitAverage} against the true max hit.
     * {@code cap <= 0}: every outcome (including the bumped 1) re-rolls into
     * the single value {@code {0}}, so the second hit is always {@code 0} —
     * matching {@link DamageDistribution#rerolledAverageDamage}'s own
     * {@code cap <= 0} guard.
     */
    static double rerolledSecondHitAverage(double hitChance, int uncappedMaxHit, int cap) {
        if (cap >= uncappedMaxHit) {
            return secondHitAverage(hitChance, uncappedMaxHit);
        }
        if (cap <= 0) {
            return 0.0;
        }
        double[] p = DamageDistribution.rerolledHitsplatDistribution(uncappedMaxHit, cap);
        double sum = 0.0;
        for (int v = 0; v <= cap; v++) {
            sum += p[v] * ((2 * v) / 5);
        }
        return hitChance * sum;
    }

    /**
     * Expected overkill (damage wasted on the killing blow) for a Twinflame
     * attack, uncapped target.
     *
     * <p><b>Modelling choice (stated explicitly, not left implicit):</b> the
     * second hit lands only one tick after the first, and this calculator
     * only ever models a single continuous attacking source with nothing
     * else able to act on the target in that one-tick gap — so, for the
     * purpose of tracking the target's remaining hitpoints between attack
     * cycles, the first and second hitsplat are treated as landing TOGETHER:
     * each attack cycle removes {@code d + floor(0.4*d)} hitpoints (for a
     * landed roll {@code d}), or 0 on a miss. This is the same discrete
     * dynamic-programme recurrence {@code DamageDistribution.expectedOverkill} uses,
     * generalised so a single successful attack can remove more than {@code
     * maxHit} hitpoints (up to {@code maxHit + floor(0.4*maxHit)}).
     *
     * <p><b>Known simplification (documented, not silent):</b> if the first
     * hitsplat alone is already lethal, the real game likely does not apply
     * the second hitsplat's damage against an already-dead target (or its
     * damage number becomes moot), whereas this combined model still counts
     * the full {@code d + floor(0.4*d)} toward that kill's overkill. This
     * only affects the literal last attack of a kill — a single hit's worth
     * of a much longer kill sequence — so its effect on the reported
     * overkill/TTK is negligible; an exact treatment of that boundary case is
     * out of scope here, matching how {@code DpsCalculator.finishFang}
     * documents its own uncapped-overkill approximation.
     */
    static double combinedExpectedOverkill(int maxHit, int targetHitpoints) {
        if (maxHit <= 0 || targetHitpoints <= 0) {
            return 0.0;
        }
        double[] over = new double[targetHitpoints + 1];
        for (int h = 1; h <= targetHitpoints; h++) {
            double sum = 0.0;
            for (int d = 1; d <= maxHit; d++) {
                double p = (d == 1 ? 2.0 : 1.0) / (maxHit + 1.0);
                int combined = d + ((2 * d) / 5);
                sum += p * (combined >= h ? (combined - h) : over[h - combined]);
            }
            over[h] = sum;
        }
        return over[targetHitpoints];
    }

    /**
     * Expected overkill for a Twinflame attack against a target that caps
     * each hitsplat — same combined-hitsplat model as {@link
     * #combinedExpectedOverkill}, but the first hit (and therefore the
     * second, derived from it) is clamped to {@code cap} before combining,
     * matching {@link #cappedSecondHitAverage}.
     */
    static double cappedCombinedExpectedOverkill(int uncappedMaxHit, int cap, int targetHitpoints) {
        if (cap >= uncappedMaxHit) {
            return combinedExpectedOverkill(uncappedMaxHit, targetHitpoints);
        }
        if (cap <= 0 || targetHitpoints <= 0 || uncappedMaxHit <= 0) {
            return 0.0;
        }
        double denom = uncappedMaxHit + 1.0;
        double[] over = new double[targetHitpoints + 1];
        for (int h = 1; h <= targetHitpoints; h++) {
            double sum = 0.0;
            for (int d = 1; d <= uncappedMaxHit; d++) {
                double p = (d == 1 ? 2.0 : 1.0) / denom;
                int visibleFirst = Math.min(d, cap);
                int combined = visibleFirst + ((2 * visibleFirst) / 5);
                sum += p * (combined >= h ? (combined - h) : over[h - combined]);
            }
            over[h] = sum;
        }
        return over[targetHitpoints];
    }

    /**
     * Expected overkill for a Twinflame attack against a target that
     * RE-ROLLS each hitsplat above a cap back into {@code 0..cap} — same
     * combined-hitsplat model as {@link #combinedExpectedOverkill}/{@link
     * #cappedCombinedExpectedOverkill}, but over {@link
     * DamageDistribution#rerolledHitsplatDistribution}'s zero-aware {@code 0..cap}
     * array (the one {@link #rerolledSecondHitAverage} and {@link
     * DamageDistribution#rerolledExpectedOverkill} also consume), rather than a raw
     * enumeration of the {@code 0..uncappedMaxHit} roll.
     *
     * <p><b>The zero-mass trap:</b> under REROLL, {@code P(0)} is genuinely
     * positive (a re-rolled zero), and {@code combined(0) = 0}, so the naive
     * {@code over[h] = sum_v P(v) * (...)} recurrence used by {@link
     * #combinedExpectedOverkill}/{@link #cappedCombinedExpectedOverkill}
     * would put {@code over[h]} on its own right-hand side via the
     * {@code v = 0} term ({@code over[h - 0]}). This delegates to {@link
     * DamageDistribution#overkillFromExplicitDistribution(double[], int[], int)}
     * instead, which conditions on a state-changing (non-zero-value)
     * outcome exactly as {@link DamageDistribution#rerolledExpectedOverkill} does —
     * the two must not, and here cannot, disagree on that convention, since
     * both ultimately call the same method.
     *
     * <p>{@code cap >= uncappedMaxHit}: nothing is ever re-rolled, so this
     * delegates to {@link #combinedExpectedOverkill} against the true max
     * hit. {@code cap <= 0}: every outcome re-rolls into the single value
     * {@code {0}}, so the combined hitsplat is always {@code 0} and there is
     * never any overkill to speak of.
     */
    static double rerolledCombinedExpectedOverkill(int uncappedMaxHit, int cap, int targetHitpoints) {
        if (cap >= uncappedMaxHit) {
            return combinedExpectedOverkill(uncappedMaxHit, targetHitpoints);
        }
        if (cap <= 0 || targetHitpoints <= 0 || uncappedMaxHit <= 0) {
            return 0.0;
        }
        double[] p = DamageDistribution.rerolledHitsplatDistribution(uncappedMaxHit, cap);
        int[] combined = new int[cap + 1];
        for (int v = 0; v <= cap; v++) {
            combined[v] = v + ((2 * v) / 5);
        }
        return DamageDistribution.overkillFromExplicitDistribution(p, combined, targetHitpoints);
    }
}

package com.ospulse.combat;

/**
 * "Best available potion" boost formulas for {@link PlayerCombat#assumeBestPotion()}.
 * All boosts are {@code base + floor(baseLevel * pct)} — the flat integer is
 * added AFTER flooring the percentage term, per the OSRS Wiki's
 * "Temporary skill boost" pages (Static/current level * pct, floored, then
 * a flat addend).
 *
 * @see <a href="https://oldschool.runescape.wiki/w/Temporary_skill_boost/Strength">Temporary skill boost/Strength</a> (Super strength: 5 + floor(level*0.15))
 * @see <a href="https://oldschool.runescape.wiki/w/Temporary_skill_boost/Attack">Temporary skill boost/Attack</a> (Super attack: 5 + floor(level*0.15))
 * @see <a href="https://oldschool.runescape.wiki/w/Temporary_skill_boost/Ranged">Temporary skill boost/Ranged</a> (Ranging potion: 4 + floor(level*0.1))
 * @see <a href="https://oldschool.runescape.wiki/w/Imbued_heart">Imbued heart</a> (Magic: floor(level*0.1) + 1)
 */
final class PotionBoosts {
    private PotionBoosts() {
    }

    /** Super attack / super strength / super combat potion: best sustained melee accuracy+damage boost. */
    static int bestMeleeBoostedLevel(int baseLevel) {
        return baseLevel + 5 + (int) Math.floor(baseLevel * 0.15);
    }

    /** Ranging potion (also Bastion potion): best sustained ranged boost. */
    static int bestRangedBoostedLevel(int baseLevel) {
        return baseLevel + 4 + (int) Math.floor(baseLevel * 0.1);
    }

    /** Imbued heart: best readily-repeatable magic accuracy boost (saturated heart's +3 is a Tier-B refinement). */
    static int bestMagicBoostedLevel(int baseLevel) {
        return imbuedHeartBoostedLevel(baseLevel);
    }

    /** Imbued heart (Invigorate): {@code 1 + floor(level * 0.1)}. */
    static int imbuedHeartBoostedLevel(int baseLevel) {
        return baseLevel + (int) Math.floor(baseLevel * 0.1) + 1;
    }

    /** Saturated heart (upgraded Imbued heart): {@code 4 + floor(level * 0.1)} — the highest magic-level boost. */
    static int saturatedHeartBoostedLevel(int baseLevel) {
        return baseLevel + (int) Math.floor(baseLevel * 0.1) + 4;
    }

    /**
     * Ancient brew: {@code 2 + floor(level * 0.05)} — a smaller Magic boost than
     * either heart, traded for draining Attack/Strength/Defence (not modelled
     * here; this method only covers the Magic-level side of the potion).
     */
    static int ancientBrewBoostedLevel(int baseLevel) {
        return baseLevel + (int) Math.floor(baseLevel * 0.05) + 2;
    }
}

package com.ospulse.combat;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Resolves an equipment item id → its offensive/defensive bonuses from the
 * bundled, clean-room {@code equipment_stats.min.json} (read straight from the
 * OSRS cache — see the accompanying README for provenance/regeneration). This is
 * the licence-free replacement for RuneLite's wiki-derived
 * {@code ItemManager.getItemStats()} numeric data: the DPS engine sources every
 * numeric bonus from here so a future non-RuneLite (web) build can share the exact
 * same data without the CC-BY-NC-SA wiki dataset.
 *
 * <p>Pure and thread-safe to read from anywhere (including the EDT): static game
 * data with no {@code Client}/{@code ItemManager} dependency, which also lets a
 * not-yet-owned item (future optimiser) be looked up the same way. Mirrors
 * {@link WeaponCategoryRepository}/{@code MonsterRepository}'s bundled-resource
 * pattern.
 *
 * <p><b>Two-handedness is deliberately NOT here</b> — no cache param reliably
 * encodes it (best calibration was random), so the plugin still reads {@code
 * isTwoHanded} from RuneLite at runtime; the row's trailing slot hint is dropped.
 */
public final class EquipmentStatsRepository {
    private static final String RESOURCE_PATH = "/com/ospulse/combat/equipment_stats.min.json";

    // Column order of each row in the min.json, mirroring the extractor's FIELDS:
    // 0 astab 1 aslash 2 acrush 3 amagic 4 arange 5 dstab 6 dslash 7 dcrush
    // 8 dmagic 9 drange 10 str 11 rstr 12 mdmg 13 prayer 14 speed 15 slotId(hint).
    private static final int I_MDMG = 12;
    private static final int I_SPEED = 14;
    private static final int MIN_ROW_LEN = 15; // 15 stats; a trailing slot hint (index 15) is optional/ignored.

    // The file stores magic damage in tenths of a percent (Kodai wand = 150),
    // but the DPS engine expects whole percent (CombatMath applies 1 + mdmg/100),
    // so scale it down on load. Ranged strength / all other bonuses are 1:1.
    private static final double MDMG_TENTHS_TO_PERCENT = 10.0;

    private static volatile EquipmentStatsRepository instance;

    private final Map<Integer, Stats> byItemId;

    private EquipmentStatsRepository(Map<Integer, Stats> byItemId) {
        this.byItemId = Collections.unmodifiableMap(byItemId);
    }

    /** Shared, lazily-initialised singleton loaded from the bundled resource. */
    public static EquipmentStatsRepository getInstance() {
        EquipmentStatsRepository result = instance;
        if (result == null) {
            synchronized (EquipmentStatsRepository.class) {
                result = instance;
                if (result == null) {
                    instance = result = loadFromResource(RESOURCE_PATH);
                }
            }
        }
        return result;
    }

    /** Loads a repository from an arbitrary classpath resource (mainly for tests). */
    static EquipmentStatsRepository loadFromResource(String resourcePath) {
        Gson gson = BundledGson.get();
        try (Reader reader = new InputStreamReader(requireResource(resourcePath), StandardCharsets.UTF_8)) {
            Type mapType = new TypeToken<Map<String, int[]>>() {
            }.getType();
            Map<String, int[]> raw = gson.fromJson(reader, mapType);
            HashMap<Integer, Stats> parsed = new HashMap<>();
            if (raw != null) {
                for (Map.Entry<String, int[]> e : raw.entrySet()) {
                    int[] row = e.getValue();
                    if (row == null || row.length < MIN_ROW_LEN) {
                        continue; // malformed row — treated as "no data" (caller falls back)
                    }
                    int itemId;
                    try {
                        itemId = Integer.parseInt(e.getKey().trim());
                    } catch (NumberFormatException ignored) {
                        continue; // non-numeric key in the data — skip defensively
                    }
                    parsed.put(itemId, Stats.fromRow(row));
                }
            }
            return new EquipmentStatsRepository(parsed);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to load equipment stats data from " + resourcePath, e);
        }
    }

    private static InputStream requireResource(String resourcePath) {
        InputStream in = EquipmentStatsRepository.class.getResourceAsStream(resourcePath);
        if (in == null) {
            throw new IllegalStateException("Bundled resource not found on classpath: " + resourcePath);
        }
        return in;
    }

    public int size() {
        return byItemId.size();
    }

    /**
     * The cache-derived bonuses for an item id, or {@code null} if the id is
     * empty ({@code <= 0}) or absent from the data. Callers fall back to their
     * previous source (e.g. RuneLite {@code getItemStats}) on {@code null}.
     */
    public Stats statsFor(int itemId) {
        if (itemId <= 0) {
            return null;
        }
        return byItemId.get(itemId);
    }

    /**
     * One item's offensive/defensive bonuses in the DPS engine's units (magic
     * damage as whole percent). Immutable. Mirrors {@code ItemEquipmentStats}'s
     * numeric fields, minus {@code isTwoHanded} (not cache-derivable — see class
     * javadoc).
     */
    public static final class Stats {
        private final int astab;
        private final int aslash;
        private final int acrush;
        private final int amagic;
        private final int arange;
        private final int dstab;
        private final int dslash;
        private final int dcrush;
        private final int dmagic;
        private final int drange;
        private final int str;
        private final int rstr;
        private final double mdmg;
        private final int prayer;
        private final int aspeed;

        private Stats(int astab, int aslash, int acrush, int amagic, int arange,
                      int dstab, int dslash, int dcrush, int dmagic, int drange,
                      int str, int rstr, double mdmg, int prayer, int aspeed) {
            this.astab = astab;
            this.aslash = aslash;
            this.acrush = acrush;
            this.amagic = amagic;
            this.arange = arange;
            this.dstab = dstab;
            this.dslash = dslash;
            this.dcrush = dcrush;
            this.dmagic = dmagic;
            this.drange = drange;
            this.str = str;
            this.rstr = rstr;
            this.mdmg = mdmg;
            this.prayer = prayer;
            this.aspeed = aspeed;
        }

        static Stats fromRow(int[] r) {
            return new Stats(r[0], r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9],
                    r[10], r[11], r[I_MDMG] / MDMG_TENTHS_TO_PERCENT, r[13], r[I_SPEED]);
        }

        public int astab() {
            return astab;
        }

        public int aslash() {
            return aslash;
        }

        public int acrush() {
            return acrush;
        }

        public int amagic() {
            return amagic;
        }

        public int arange() {
            return arange;
        }

        public int dstab() {
            return dstab;
        }

        public int dslash() {
            return dslash;
        }

        public int dcrush() {
            return dcrush;
        }

        public int dmagic() {
            return dmagic;
        }

        public int drange() {
            return drange;
        }

        public int str() {
            return str;
        }

        public int rstr() {
            return rstr;
        }

        /** Magic damage as a whole percent (e.g. 15.0 for +15%), already scaled from the file's tenths. */
        public double mdmg() {
            return mdmg;
        }

        public int prayer() {
            return prayer;
        }

        /** Weapon attack speed in ticks; {@code 0} means "derive from weapon category" (powered staves etc.). */
        public int aspeed() {
            return aspeed;
        }
    }
}

package com.ospulse.combat;

import com.google.gson.reflect.TypeToken;

import java.lang.reflect.Type;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;

/**
 * Maps a {@link WeaponCategory} + {@link WeaponStyle} to the NATIVE in-game
 * Combat Options sprite id that OSRS itself draws on that weapon-type's
 * attack-style buttons — {@code net.runelite.api.gameval.SpriteID.Combaticons}
 * / {@code Combaticons2} / {@code Combaticons3} (verified 2026-07-03 against
 * {@code runelite-api-1.12.31.1.jar}: e.g. {@code AXE_CHOP}, {@code SWORD_SLASH},
 * {@code BOW_RAPID}, {@code CLAWS_LUNGE}).
 *
 * <p><b>Why not RuneLite's own {@code attackstyles} plugin:</b> that core
 * plugin (see {@code net.runelite.client.plugins.attackstyles.AttackStylesPlugin})
 * only shows/hides the game's own combat-options widgets and reads style
 * NAMES from {@code EnumID.WEAPON_STYLES} — it never draws icons itself and
 * ships no sprite-id table; the actual icons are painted by the game client's
 * own interface script directly from each weapon's struct data, which is not
 * exposed to plugins as a lookup. This class is therefore a hand-verified,
 * pure-data port of the pertinent sprite ids (mirroring how {@link WeaponStyles}
 * itself already ports weirdgloop's {@code getCombatStylesForCategory}),
 * keyed by the same {@code (WeaponCategory, style name)} this plugin's
 * {@link WeaponStyles} already produces — so the mapping is exact for every
 * category with a genuinely distinct native icon, and falls back to the
 * closest same-damage-type sprite where OSRS itself reuses one weapon type's
 * icon set for another (see the fallback notes below).
 *
 * <p>The category/style/spriteId table itself is bundled data — see {@code
 * /com/ospulse/combat/attack_style_icons.json} — loaded once through {@link
 * CombatDataLoader}, the same shared bundled-resource loading path {@link
 * WeaponStyles} uses. A handful of entries in that table are deliberate
 * same-icon reuses rather than genuinely distinct native sprites, because OSRS
 * itself has no dedicated icon for the style:
 * <ul>
 *   <li>{@code TWO_HANDED_SWORD} "Smash" reuses the mace Pound icon (no
 *       dedicated 2h-sword "Smash" sprite; nearest crush icon).</li>
 *   <li>{@code WHIP} "Deflect" reuses "Lash" (OSRS has no dedicated "Deflect"
 *       combat icon; the whip's own Lash is closest).</li>
 *   <li>{@code BULWARK} "Pummel" reuses the mace Pummel icon (no dedicated
 *       bulwark sprite; nearest crush icon).</li>
 *   <li>{@code FLAIL} "Chop" reuses the sword Chop icon (no dedicated flail
 *       sprite; nearest slash icon).</li>
 *   <li>{@code GUN} "Kick" reuses the unarmed Kick icon (no dedicated gun
 *       sprite).</li>
 *   <li>{@code THROWN} reuses the {@code BOW} icons wholesale (no dedicated
 *       thrown-weapon sprite set; nearest ranged icons).</li>
 * </ul>
 */
public final class AttackStyleIcons {

    private static final String RESOURCE_PATH = "/com/ospulse/combat/attack_style_icons.json";
    private static final Type BY_CATEGORY_JSON_TYPE = new TypeToken<Map<String, Map<String, Integer>>>() {
    }.getType();

    private AttackStyleIcons() {
    }

    private static final Map<WeaponCategory, Map<String, Integer>> BY_CATEGORY = buildByCategory();

    private static Map<WeaponCategory, Map<String, Integer>> buildByCategory() {
        Map<String, Map<String, Integer>> raw = CombatDataLoader.load(
            AttackStyleIcons.class, RESOURCE_PATH, BY_CATEGORY_JSON_TYPE);
        Map<WeaponCategory, Map<String, Integer>> parsed = new EnumMap<>(WeaponCategory.class);
        for (Map.Entry<String, Map<String, Integer>> categoryEntry : raw.entrySet()) {
            WeaponCategory category;
            try {
                category = WeaponCategory.valueOf(categoryEntry.getKey());
            } catch (IllegalArgumentException e) {
                continue; // unknown category key in the bundled data — treated as "no data"
            }
            parsed.put(category, Collections.unmodifiableMap(new HashMap<>(categoryEntry.getValue())));
        }
        return Collections.unmodifiableMap(parsed);
    }

    /**
     * The native Combat Options sprite id for {@code category}'s {@code styleName}
     * (as produced by {@link WeaponStyles#forCategory}), or a same-damage-type
     * generic fallback (see {@link #genericSpriteFor}) if this exact
     * category/name pair has no bundled entry (e.g. an unmapped category).
     * Never returns 0/invalid — always resolves to SOME reasonable sprite id.
     */
    public static int spriteIdFor(WeaponCategory category, WeaponStyle style) {
        if (category != null && style != null) {
            Map<String, Integer> byName = BY_CATEGORY.get(category);
            if (byName != null) {
                Integer id = byName.get(style.name());
                if (id != null) {
                    return id;
                }
            }
        }
        return style == null ? 249 /* UNARMED_BLOCK */ : genericSpriteFor(style);
    }

    /** A same-damage-type/stance generic icon for a style with no bundled per-category entry. */
    private static int genericSpriteFor(WeaponStyle style) {
        switch (style.type()) {
            case STAB:
                return 240; // SWORD_STAB
            case SLASH:
                return 238; // SWORD_SLASH
            case CRUSH:
                return 246; // MACE_POUND
            case RANGED:
                return 268; // BOW_ACCURATE
            case MAGIC:
                return 263; // MAGIC_ACCURATE
            default:
                return 249; // UNARMED_BLOCK
        }
    }
}

package com.ospulse.combat;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Resolves an equipment item id → its skill EQUIP requirements (e.g. Dragon
 * scimitar → {attack: 60}) from the bundled, clean-room
 * {@code equipment_requirements.min.json} (read straight from the OSRS cache's
 * item config params 434-437 — see the accompanying README for provenance /
 * regeneration). This is the licence-free source the gear optimiser uses to
 * avoid recommending gear a player cannot equip at their current levels.
 *
 * <p>Pure and thread-safe to read from anywhere (including the EDT): static game
 * data with no {@code Client}/{@code ItemManager} dependency, so a not-yet-owned
 * item can be checked the same way. Mirrors {@link EquipmentStatsRepository}'s
 * bundled-resource singleton pattern.
 *
 * <p>Skill keys are lowercase names ({@code attack}, {@code defence},
 * {@code strength}, {@code hitpoints}, {@code ranged}, {@code prayer},
 * {@code magic}, {@code agility}, {@code slayer}, …) — the same lowercase form
 * the extractor writes.
 */
public final class EquipmentRequirementsRepository {
    private static final String RESOURCE_PATH = "/com/ospulse/combat/equipment_requirements.min.json";

    private static volatile EquipmentRequirementsRepository instance;

    /** item id → (skill name → required level). Inner maps are unmodifiable. */
    private final Map<Integer, Map<String, Integer>> byItemId;

    private EquipmentRequirementsRepository(Map<Integer, Map<String, Integer>> byItemId) {
        this.byItemId = Collections.unmodifiableMap(byItemId);
    }

    /** Shared, lazily-initialised singleton loaded from the bundled resource. */
    public static EquipmentRequirementsRepository getInstance() {
        EquipmentRequirementsRepository result = instance;
        if (result == null) {
            synchronized (EquipmentRequirementsRepository.class) {
                result = instance;
                if (result == null) {
                    instance = result = loadFromResource(RESOURCE_PATH);
                }
            }
        }
        return result;
    }

    /** Loads a repository from an arbitrary classpath resource (mainly for tests). */
    static EquipmentRequirementsRepository loadFromResource(String resourcePath) {
        Gson gson = BundledGson.get();
        try (Reader reader = new InputStreamReader(requireResource(resourcePath), StandardCharsets.UTF_8)) {
            Type mapType = new TypeToken<Map<String, Map<String, Number>>>() {
            }.getType();
            Map<String, Map<String, Number>> raw = gson.fromJson(reader, mapType);
            HashMap<Integer, Map<String, Integer>> parsed = new HashMap<>();
            if (raw != null) {
                for (Map.Entry<String, Map<String, Number>> e : raw.entrySet()) {
                    Map<String, Number> reqs = e.getValue();
                    if (reqs == null || reqs.isEmpty()) {
                        continue;
                    }
                    int itemId;
                    try {
                        itemId = Integer.parseInt(e.getKey().trim());
                    } catch (NumberFormatException ignored) {
                        continue; // non-numeric key — skip defensively
                    }
                    Map<String, Integer> levels = new LinkedHashMap<>();
                    for (Map.Entry<String, Number> r : reqs.entrySet()) {
                        if (r.getKey() != null && r.getValue() != null) {
                            levels.put(r.getKey().toLowerCase(Locale.ROOT), r.getValue().intValue());
                        }
                    }
                    if (!levels.isEmpty()) {
                        parsed.put(itemId, Collections.unmodifiableMap(levels));
                    }
                }
            }
            return new EquipmentRequirementsRepository(parsed);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to load equipment requirements data from " + resourcePath, e);
        }
    }

    private static InputStream requireResource(String resourcePath) {
        InputStream in = EquipmentRequirementsRepository.class.getResourceAsStream(resourcePath);
        if (in == null) {
            throw new IllegalStateException("Bundled resource not found on classpath: " + resourcePath);
        }
        return in;
    }

    public int size() {
        return byItemId.size();
    }

    /**
     * The skill equip requirements for an item id as an unmodifiable
     * (skill name → level) map, or {@code null} if the id is empty
     * ({@code <= 0}) or has no requirements in the data (i.e. equippable at
     * level 1 / no skill gate).
     */
    public Map<String, Integer> requirementsFor(int itemId) {
        if (itemId <= 0) {
            return null;
        }
        return byItemId.get(itemId);
    }

    /**
     * True if a player with the given base skill levels ({@code skill name →
     * level}, lowercase keys) can equip {@code itemId}. Fail-open: an item with
     * no requirement data is always allowed, and a requirement whose skill is
     * ABSENT from {@code baseLevels} is assumed met (so an incomplete level map
     * never hides otherwise-wearable gear — callers should populate at least the
     * combat skills). Only a KNOWN level below the requirement blocks the item.
     */
    public boolean canEquip(int itemId, Map<String, Integer> baseLevels) {
        Map<String, Integer> reqs = requirementsFor(itemId);
        if (reqs == null || reqs.isEmpty()) {
            return true;
        }
        if (baseLevels == null || baseLevels.isEmpty()) {
            return true; // no level info supplied → don't over-filter
        }
        for (Map.Entry<String, Integer> req : reqs.entrySet()) {
            Integer have = baseLevels.get(req.getKey());
            if (have != null && have < req.getValue()) {
                return false;
            }
        }
        return true;
    }
}

package com.ospulse.combat;

import com.google.gson.Gson;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Loads the bundled, hand-curated "don't forget" consumables/gear reminder
 * table ({@code /com/ospulse/combat/monster_consumables.json}) and serves
 * in-memory lookups by monster name.
 *
 * <p>A reminder is advisory only — e.g. "Zulrah poisons you — bring
 * antivenom" — and is never fed into {@link
 * com.ospulse.combat.optimizer.GearOptimizer}: it is a pure keyed map lookup
 * at render time, entirely outside the optimiser search, so it cannot slow it
 * down. {@code GearSection} (via {@code
 * com.ospulse.ui.sections.gear.ConsumablesReminderPanel}) renders the note;
 * this repository just exposes the curated data.
 *
 * <p>Matches by monster NAME, exact-then-base-name — mirroring {@link
 * MonsterCombatRequirementRepository#forMonster}, NOT {@link
 * MonsterGearOverrideRepository}'s exact-only matching — so {@code "Zulrah"}
 * resolves {@code "Zulrah (Serpentine)"}/{@code "(Magma)"}/{@code
 * "(Tanzanite)"} for free while a phase-scoped entry can still key on an
 * exact dataset name. Mirrors {@link MonsterCombatRequirementRepository}'s
 * bundled-resource singleton pattern.
 */
public final class MonsterConsumablesRepository {
    private static final String RESOURCE_PATH = "/com/ospulse/combat/monster_consumables.json";

    private static volatile MonsterConsumablesRepository instance;

    private final Map<String, MonsterConsumablesReminder> byLowercaseMonsterName;

    private MonsterConsumablesRepository(Map<String, MonsterConsumablesReminder> byLowercaseMonsterName) {
        this.byLowercaseMonsterName = Collections.unmodifiableMap(byLowercaseMonsterName);
    }

    /** Shared, lazily-initialised singleton loaded from the bundled resource. */
    public static MonsterConsumablesRepository getInstance() {
        MonsterConsumablesRepository result = instance;
        if (result == null) {
            synchronized (MonsterConsumablesRepository.class) {
                result = instance;
                if (result == null) {
                    instance = result = loadFromResource(RESOURCE_PATH);
                }
            }
        }
        return result;
    }

    /** Loads a repository from an arbitrary classpath resource (mainly for tests). */
    static MonsterConsumablesRepository loadFromResource(String resourcePath) {
        Gson gson = BundledGson.get();
        try (Reader reader = new InputStreamReader(requireResource(resourcePath), StandardCharsets.UTF_8)) {
            RootDto root = gson.fromJson(reader, RootDto.class);
            Map<String, MonsterConsumablesReminder> byName = new HashMap<>();
            if (root != null && root.reminders != null) {
                for (ReminderDto dto : root.reminders) {
                    if (dto.monsters == null || dto.note == null) {
                        continue; // malformed entry — treated as "no data"
                    }
                    Set<Integer> equipmentItemIds = dto.equipmentItemIds == null
                        ? Collections.emptySet()
                        : new LinkedHashSet<>(dto.equipmentItemIds);
                    Set<Integer> consumableItemIds = dto.consumableItemIds == null
                        ? Collections.emptySet()
                        : new LinkedHashSet<>(dto.consumableItemIds);
                    MonsterConsumablesReminder reminder =
                        new MonsterConsumablesReminder(dto.note, equipmentItemIds, consumableItemIds);
                    for (String monsterName : dto.monsters) {
                        if (monsterName == null || monsterName.isEmpty()) {
                            continue;
                        }
                        byName.put(monsterName.toLowerCase(Locale.ROOT), reminder);
                    }
                }
            }
            return new MonsterConsumablesRepository(byName);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to load monster consumables reminder data from " + resourcePath, e);
        }
    }

    private static InputStream requireResource(String resourcePath) {
        InputStream in = MonsterConsumablesRepository.class.getResourceAsStream(resourcePath);
        if (in == null) {
            throw new IllegalStateException("Bundled resource not found on classpath: " + resourcePath);
        }
        return in;
    }

    public int size() {
        return byLowercaseMonsterName.size();
    }

    /**
     * The curated consumables reminder for the given monster name, or empty
     * if this monster has none. Tries the full lowercased name first, then
     * falls back to {@link MonsterNameKey#baseName} — the picker hands us
     * dataset names like {@code "Zulrah (Serpentine)"}.
     */
    public Optional<MonsterConsumablesReminder> forMonster(String monsterName) {
        if (monsterName == null) {
            return Optional.empty();
        }
        MonsterConsumablesReminder exact = byLowercaseMonsterName.get(monsterName.toLowerCase(Locale.ROOT));
        if (exact != null) {
            return Optional.of(exact);
        }
        return Optional.ofNullable(byLowercaseMonsterName.get(MonsterNameKey.baseName(monsterName)));
    }

    /**
     * Every curated key, lowercased, exactly as stored in the lookup map.
     * Exposed so the data-integrity test can assert each one still resolves
     * against the bundled monster data.
     */
    Set<String> curatedKeys() {
        return Collections.unmodifiableSet(byLowercaseMonsterName.keySet());
    }

    /** Every curated entry, for dataset-wide integrity checks (e.g. every equipment id resolves). */
    Collection<MonsterConsumablesReminder> allReminders() {
        return Collections.unmodifiableCollection(byLowercaseMonsterName.values());
    }

    /** Exposes the name normalisation {@link #forMonster} falls back to. */
    static String baseNameOf(String monsterName) {
        return MonsterNameKey.baseName(monsterName);
    }

    /** Internal Gson deserialisation shape mirroring {@code monster_consumables.json}'s top-level object. */
    private static final class RootDto {
        List<ReminderDto> reminders;
    }

    /** Internal Gson deserialisation shape mirroring one entry of the {@code reminders} array. */
    private static final class ReminderDto {
        List<String> monsters;
        String note;
        List<Integer> equipmentItemIds;
        List<Integer> consumableItemIds;
    }
}

package com.ospulse.combat;

import java.util.Locale;

/**
 * Weapon &lt;-&gt; worn-ammo compatibility, resolved purely from the bundled
 * data ({@link EquipmentIndexRepository} display names +
 * {@link WeaponCategoryRepository} categories) — no {@code Client}/
 * {@code ItemManager} read and no client thread, so the same lookup serves
 * the live DPS readout, the what-if picker, and the optimiser's candidate
 * pool identically (mirrors {@link WeaponCategoryRepository}'s rationale).
 *
 * <p>Two questions are answered here:
 * <ul>
 *   <li>{@link #consumedClass(int)} — which {@link AmmoClass} a weapon FIRES
 *       from the worn ammo slot ({@code null} when it doesn't use worn ammo
 *       at all: melee/magic weapons, self-supplying bows like the crystal
 *       bow family, blowpipes, standalone thrown weapons, chinchompas);</li>
 *   <li>{@link #wornAmmoContributes(int, int)} — whether one worn ammo-slot
 *       item's bonuses should count toward a loadout led by a given weapon.
 *       Per the wiki's DPS rules, CONSUMABLE ammo (arrows/bolts/javelins/…)
 *       only contributes its ranged strength when the weapon actually fires
 *       that class — dragon javelins worn behind a shortbow add nothing —
 *       while NON-consumable ammo-slot wearables (Rada's/god blessings) are
 *       passive and always count.</li>
 * </ul>
 *
 * <p>Deliberate approximations (documented, not bugs):
 * <ul>
 *   <li><b>Class-level only, no tier rules.</b> A bow is matched to ARROW,
 *       not to the specific arrow tiers it can fire (e.g. a Magic shortbow
 *       cannot really fire Dragon arrows). Tier tables are a much bigger
 *       data set for marginal optimiser gain — the realistic best-in-class
 *       ammo is usually usable by the best-in-class weapon. The two tier
 *       mismatches glaring enough to WIN searches wrongly get their own
 *       classes instead: Karil's crossbow / Bolt racks
 *       ({@link AmmoClass#RACK}) and the Hunters' crossbows / kebbit +
 *       antler bolts ({@link AmmoClass#HUNTER_BOLT}).</li>
 *   <li><b>Eclipse atlatl</b> fires Atlatl darts, which have no row in the
 *       bundled index — its class resolves to {@link AmmoClass#DART} with no
 *       indexed members, so the optimiser leaves its ammo slot alone.</li>
 *   <li><b>Unknown ammo-slot items</b> (not in the bundled index) fall back
 *       to "contributes" — the pre-compatibility behaviour.</li>
 * </ul>
 */
public final class AmmoCompatibility {
    /**
     * The bundled index's ammo-slot items partition cleanly by display name
     * (verified against equipment_index.min.json 2026-07-07: 73 arrows + 81
     * bolts + 1 bolt rack + 4 hunter bolts + 32 javelins + 5 tars + 11
     * blessings, zero unmatched).
     */
    public enum AmmoClass {
        /** Arrows, incl. the "brutal" comp-bow arrows. Consumable. */
        ARROW(true),
        /** Regular crossbow bolts. Consumable. */
        BOLT(true),
        /**
         * Barrows Bolt racks — split from BOLT because Karil's crossbow fires
         * ONLY racks and no other crossbow fires racks; class-level matching
         * would otherwise recommend (and credit) Karil's + dragon-tier bolts,
         * an impossible pairing strong enough to win real searches. Consumable.
         */
        RACK(true),
        /**
         * Hunter ammo ((long) kebbit bolts + sunlight/moonlight antler
         * bolts) — split from BOLT for the same reason: the Hunters'/Hunters'
         * sunlight crossbows fire only these, and no regular crossbow fires
         * them. Consumable.
         */
        HUNTER_BOLT(true),
        /** Javelins (ballista ammo). Consumable. */
        JAVELIN(true),
        /** Atlatl darts — real class, but no indexed members (see class javadoc). Consumable. */
        DART(true),
        /** Salamander fuel (Guam/Harralander/… tar). Consumable. */
        TAR(true),
        /** Rada's/god/Ancient blessings — passive prayer wearables, fired by nothing. */
        BLESSING(false);

        private final boolean consumable;

        AmmoClass(boolean consumable) {
            this.consumable = consumable;
        }

        /** True when the class is fired/used up by a weapon (everything except {@link #BLESSING}). */
        public boolean isConsumable() {
            return consumable;
        }
    }

    /**
     * BOW-category weapons that supply their own ammo (worn ammo slot stays
     * free for a blessing): the crystal bow family (incl. the Gauntlet's
     * corrupted tiers, harmless to list even though those are excluded from
     * the optimiser pool upstream), Bow of faerdhinen, and the wilderness
     * revenant bows. Name fragments, lower-case, matched by substring so
     * charge/cosmetic variants ("(c)", "(i)", clan colours) are all covered.
     */
    private static final String[] SELF_SUPPLYING_BOW_NAME_FRAGMENTS = {
        "crystal bow", "corrupted bow", "bow of faerdhinen", "craw's bow", "webweaver bow",
    };

    private AmmoCompatibility() {
    }

    /**
     * Classifies one AMMO-SLOT item by its indexed display name, or
     * {@code null} for an empty id, a non-ammo-slot item, or a name matching
     * no known class (treated as "unknown — always contributes").
     */
    public static AmmoClass classify(int itemId) {
        EquipmentIndexRepository.Entry entry = EquipmentIndexRepository.getInstance().entryFor(itemId);
        if (entry == null || entry.slotOrdinal() != 13) {
            return null;
        }
        String name = entry.name().toLowerCase(Locale.ROOT);
        if (name.contains("blessing")) {
            return AmmoClass.BLESSING;
        }
        if (name.contains("javelin")) {
            return AmmoClass.JAVELIN;
        }
        if (name.contains("bolt rack")) {
            return AmmoClass.RACK;
        }
        if (name.contains("kebbit") || name.contains("antler")) {
            return AmmoClass.HUNTER_BOLT;
        }
        if (name.contains("bolt")) {
            return AmmoClass.BOLT;
        }
        if (name.contains("arrow") || name.contains("brutal")) {
            return AmmoClass.ARROW;
        }
        if (name.endsWith("tar")) {
            return AmmoClass.TAR;
        }
        return null;
    }

    /**
     * The {@link AmmoClass} a WEAPON-slot item fires from the worn ammo slot,
     * or {@code null} when it doesn't use worn ammo at all. Resolution order:
     * <ol>
     *   <li>per-item name exceptions first: ballistae are categorised
     *       "crossbow" in the bundled data but fire JAVELINs; the Eclipse
     *       atlatl is categorised "bow" but fires (unindexed) atlatl DARTs;
     *       blowpipes are already category "thrown" (which resolves to
     *       {@code null} below) but are name-checked explicitly for safety
     *       since they load darts internally — same name rule as
     *       {@code GearVariants.isBlowpipe};</li>
     *   <li>then by {@link WeaponCategory}: BOW → ARROW (minus the
     *       self-supplying bows above), CROSSBOW → BOLT, SALAMANDER → TAR;</li>
     *   <li>everything else (melee, magic, thrown, chinchompas, unknown) →
     *       {@code null}.</li>
     * </ol>
     */
    public static AmmoClass consumedClass(int weaponItemId) {
        if (weaponItemId <= 0) {
            return null;
        }
        EquipmentIndexRepository.Entry entry = EquipmentIndexRepository.getInstance().entryFor(weaponItemId);
        String name = entry == null ? "" : entry.name().toLowerCase(Locale.ROOT);
        if (name.contains("blowpipe")) {
            return null;
        }
        if (name.contains("ballista")) {
            return AmmoClass.JAVELIN;
        }
        if (name.contains("atlatl")) {
            return AmmoClass.DART;
        }
        WeaponCategory category = WeaponCategoryRepository.getInstance().categoryFor(weaponItemId);
        if (category == WeaponCategory.BOW) {
            for (String fragment : SELF_SUPPLYING_BOW_NAME_FRAGMENTS) {
                if (name.contains(fragment)) {
                    return null;
                }
            }
            return AmmoClass.ARROW;
        }
        if (category == WeaponCategory.CROSSBOW) {
            if (name.contains("karil")) {
                return AmmoClass.RACK;
            }
            if (name.contains("hunters'")) {
                return AmmoClass.HUNTER_BOLT;
            }
            return AmmoClass.BOLT;
        }
        if (category == WeaponCategory.SALAMANDER) {
            return AmmoClass.TAR;
        }
        return null;
    }

    /** True when the weapon fires SOME worn-ammo class ({@link #consumedClass} non-null). */
    public static boolean usesWornAmmo(int weaponItemId) {
        return consumedClass(weaponItemId) != null;
    }

    /**
     * True when the worn ammo-slot item's bonuses count toward a loadout led
     * by {@code weaponItemId} (see class javadoc): non-consumable/unknown
     * ammo always counts; consumable ammo counts only when the weapon fires
     * exactly that class. Note the one caller-side exception: blowpipes skip
     * the worn ammo slot ENTIRELY (blessings included) in
     * {@code GearMapper.buildEquipmentStats}, which handles them before this
     * rule — the internally-loaded dart is modelled there instead.
     */
    public static boolean wornAmmoContributes(int weaponItemId, int ammoItemId) {
        AmmoClass ammoClass = classify(ammoItemId);
        if (ammoClass == null || !ammoClass.isConsumable()) {
            return true;
        }
        return consumedClass(weaponItemId) == ammoClass;
    }
}

package com.ospulse.combat;

/**
 * Craw's bow / Viggora's chainmace / Thammaron's sceptre — the three
 * revenant-cave weapons that, while charged with revenant ether, grant a
 * flat accuracy AND damage boost vs any NPC the player selects as being in
 * the Wilderness ({@link Monster#isWildernessTarget()}). Coverage is
 * comprehensive by construction, not by curated guesswork: a monster that
 * is EXCLUSIVELY Wilderness (see {@link WildernessMonsterRepository}) is a
 * single always-boosted entry, while a monster that exists BOTH in and out
 * of the Wilderness (e.g. Black dragon, found at both the Lava Maze Dungeon
 * and several non-Wilderness dungeons) gets an explicitly separate,
 * player-selectable "(Wilderness)" target (see {@link
 * WildernessVariantMonsterRepository}) rather than the engine silently
 * guessing which instance is meant — the player says which one they mean,
 * so nothing is assumed or overstated. Mirrors the {@code
 * DemonbaneWeapon}/{@code DragonHunterWeapon} enum shape: a plain
 * multiplicative floor step {@link DpsCalculator} applies to both the
 * attack roll and max hit.
 *
 * <p><b>All three are currently +50% accuracy / +50% damage — verified
 * individually against the OSRS Wiki 2026-07-27, NOT assumed symmetric just
 * because the design spec's summary table said so:</b>
 * <ul>
 * <li>Craw's bow: "an additional 50% ranged accuracy and damage boost is
 * applied when attacking any NPC in the Wilderness" (OSRS Wiki, Craw's
 * bow).</li>
 * <li>Viggora's chainmace: "an additional 50% melee accuracy and damage
 * boost is applied when attacking any NPC in the Wilderness" (OSRS Wiki,
 * Viggora's chainmace).</li>
 * <li>Thammaron's sceptre: "an additional 50% magic accuracy and damage
 * boost is applied when attacking any NPC in the Wilderness" (OSRS Wiki,
 * Thammaron's sceptre).</li>
 * </ul>
 * <b>Thammaron's sceptre specifically was flagged in review as asymmetric
 * (2/1 accuracy, 5/4 damage) — that is the PRE-2023 value, not the current
 * one.</b> The sceptre's own wiki changelog records: 14 September 2022,
 * accuracy 100%→50% and damage 25%→50%, reverted the next day as
 * unintentional; then reapplied for real on 25 January 2023 ("Wilderness
 * Boss Rework") with the identical wording. No changelog entry since has
 * touched these percentages, so the live value today is the symmetric
 * 50%/50% already implemented here — the review finding was based on stale
 * data. Each enum constant still takes independent accuracy/damage {@link
 * Fraction}s (not one shared value) specifically so a future weapon whose
 * real numbers DO differ can be added without a structural change, and so
 * {@code RevenantWeaponEffectTest} can pin each weapon's own pair
 * independently.
 *
 * <p><b>Ether is assumed charged, not modelled.</b> This calculator has no
 * concept of ether charge count (nothing else in the codebase tracks
 * per-item charge state either), so every loadout wearing one of these
 * weapons is treated as fully charged — the state a player is realistically
 * in when equipping it to check DPS. An uncharged/uncharged-and-reverted
 * weapon would not carry this bonus in-game; that state is out of scope
 * here, per the design spec's explicit instruction to assume charged rather
 * than model ether consumption.
 *
 * <p>Each weapon's own combat style: Craw's bow is RANGED-only; Thammaron's
 * sceptre (and its "(a)" ether-enhanced reskin) is MAGIC-only; Viggora's
 * chainmace applies to any melee style (its bonus is not documented as
 * style-restricted the way, say, Osmumten's fang's passive is), mirroring
 * how {@code DemonbaneWeapon}'s melee sword line covers all three melee
 * styles via the same STAB-as-"melee family" sentinel.
 *
 * @see <a href="https://oldschool.runescape.wiki/w/Craw%27s_bow">Craw's bow</a>
 * @see <a href="https://oldschool.runescape.wiki/w/Viggora%27s_chainmace">Viggora's chainmace</a>
 * @see <a href="https://oldschool.runescape.wiki/w/Thammaron%27s_sceptre">Thammaron's sceptre</a> (see the "Changes" section for the 2022/2023 percentage history)
 */
public enum RevenantWeapon {
    NONE(Fraction.ONE, Fraction.ONE, null),
    /** Craw's bow (ranged): +50% accuracy and +50% damage vs any curated Wilderness NPC. */
    CRAWS_BOW(new Fraction(3, 2), new Fraction(3, 2), CombatStyle.RANGED),
    /** Viggora's chainmace (melee, any style): +50% accuracy and +50% damage vs any curated Wilderness NPC. */
    VIGGORAS_CHAINMACE(new Fraction(3, 2), new Fraction(3, 2), CombatStyle.STAB),
    /**
     * Thammaron's sceptre (magic): +50% accuracy and +50% damage vs any
     * curated Wilderness NPC — CURRENT value since the 25 January 2023
     * "Wilderness Boss Rework" (previously an asymmetric 100%/25% before
     * that update; see the class javadoc).
     */
    THAMMARONS_SCEPTRE(new Fraction(3, 2), new Fraction(3, 2), CombatStyle.MAGIC);

    private final Fraction accuracyMult;
    private final Fraction damageMult;
    /** Style family marker: STAB is the melee-family sentinel (see class javadoc), RANGED/MAGIC are exact. */
    private final CombatStyle styleFamily;

    RevenantWeapon(Fraction accuracyMult, Fraction damageMult, CombatStyle styleFamily) {
        this.accuracyMult = accuracyMult;
        this.damageMult = damageMult;
        this.styleFamily = styleFamily;
    }

    /** True when this weapon's Wilderness passive applies to an attack of the given style. */
    public boolean appliesTo(CombatStyle style) {
        if (this == NONE || style == null) {
            return false;
        }
        if (styleFamily.isMelee()) {
            return style.isMelee();
        }
        return style == styleFamily;
    }

    /** Multiplier on the attack roll vs a Wilderness target. */
    public Fraction accuracyMult() {
        return accuracyMult;
    }

    /** Multiplier on max hit vs a Wilderness target. */
    public Fraction damageMult() {
        return damageMult;
    }
}

package com.ospulse.combat;

import java.util.Objects;

/**
 * One selectable attack style from a weapon's combat-options tab: its in-game
 * display name (e.g. "Lunge", "Rapid"), the damage {@link CombatStyle} it uses
 * (which attack-bonus and monster-defence columns apply) and the {@link Stance}
 * it sets (which drives the +3/+1/0 style bonus and, for Rapid, the -1 tick).
 *
 * <p>These are the real per-weapon-type styles, so ranking them by DPS answers
 * "which attack style should I use against this monster" exactly as the in-game
 * combat tab presents the choice. Built by {@link WeaponStyles#forCategory}.
 */
public final class WeaponStyle {
    private final String name;
    private final CombatStyle type;
    private final Stance stance;

    public WeaponStyle(String name, CombatStyle type, Stance stance) {
        this.name = name;
        this.type = type;
        this.stance = stance;
    }

    public String name() {
        return name;
    }

    public CombatStyle type() {
        return type;
    }

    public Stance stance() {
        return stance;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof WeaponStyle)) {
            return false;
        }
        WeaponStyle that = (WeaponStyle) o;
        // Deliberately identity-by-(type,stance): two styles that read the same
        // gear/defence columns and set the same stance compute identical DPS, so
        // the ranked picker treats them as one (dedups e.g. a bludgeon's three
        // aggressive-crush styles). Name is display-only and excluded.
        return type == that.type && stance == that.stance;
    }

    @Override
    public int hashCode() {
        return Objects.hash(type, stance);
    }

    @Override
    public String toString() {
        return "WeaponStyle{" + name + ", " + type + ", " + stance + '}';
    }
}

package com.ospulse.combat;

/**
 * Dragon Hunter ("dragonbane") weapons and their vs-dragon multipliers, per
 * each weapon's OSRS Wiki page (verified 2026-07-03): Dragon hunter lance
 * "20% increased accuracy and damage when fighting draconic creatures";
 * Dragon hunter crossbow "30% increase in ranged accuracy and 25% increase in
 * damage". Applies only when the target carries
 * {@link MonsterAttribute#DRAGON} (the bundled data already tags hydras,
 * wyverns and Great Olm; Elvarg/revenant-dragon exceptions are not in the
 * monster set).
 *
 * <p><b>Stacking (per the wiki DPS calculator, weirdgloop
 * {@code PlayerVsNPCCalc.ts}):</b> dragonbane is the weapon's own passive and
 * is applied as a SEPARATE multiplicative floor step on top of the
 * salve/slayer slot — with one exception: the ranged MAX HIT folds the DHCB's
 * +25% damage additively into an on-task IMBUED slayer helm's 23/20 step
 * ((23+5)/20, one floor — the wiki's "additive with the Slayer helm (i)");
 * DHCB accuracy always stays its own separate ×13/10 step. See
 * {@code DpsCalculator.computeRanged}.
 *
 * <p>Dragon hunter wand (magic): grants +75% magic accuracy and +40% magic
 * damage vs draconic creatures, per the OSRS Wiki (verified 2026-07-03).
 */
public enum DragonHunterWeapon {
    NONE(Fraction.ONE, Fraction.ONE, null),
    /** Dragon hunter lance (melee): +20% accuracy and +20% damage vs dragons. */
    LANCE(new Fraction(6, 5), new Fraction(6, 5), CombatStyle.STAB),
    /** Dragon hunter crossbow (ranged): +30% accuracy and +25% damage vs dragons. */
    CROSSBOW(new Fraction(13, 10), new Fraction(5, 4), CombatStyle.RANGED),
    /** Dragon hunter wand (magic): +75% accuracy and +40% damage vs dragons. */
    WAND(new Fraction(7, 4), new Fraction(7, 5), CombatStyle.MAGIC);

    private final Fraction accuracyMult;
    private final Fraction damageMult;
    private final CombatStyle styleFamily;

    DragonHunterWeapon(Fraction accuracyMult, Fraction damageMult, CombatStyle styleFamily) {
        this.accuracyMult = accuracyMult;
        this.damageMult = damageMult;
        this.styleFamily = styleFamily;
    }

    /** True when this weapon's dragonbane passive applies to an attack of the given style. */
    public boolean appliesTo(CombatStyle style) {
        if (this == NONE || style == null) {
            return false;
        }
        // The lance is a melee weapon: its passive covers all three melee styles.
        if (this == LANCE) {
            return style.isMelee();
        }
        return style == styleFamily;
    }

    /** Multiplier on the attack roll vs dragons. */
    public Fraction accuracyMult() {
        return accuracyMult;
    }

    /** Multiplier on max hit vs dragons. */
    public Fraction damageMult() {
        return damageMult;
    }
}

package com.ospulse.combat;

import com.google.gson.Gson;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Loads the bundled, hand-curated monster-mechanic gear override table
 * ({@code /com/ospulse/combat/monster_gear_overrides.json}, see the
 * accompanying README for provenance/shape) and serves in-memory lookups by
 * monster name.
 *
 * <p>These are cases where a specific item matters for a MECHANICS reason
 * (special-attack mitigation, safespotting, immunity, etc.) rather than raw
 * DPS — flagship example: Insulated boots vs Rune dragons (halves the
 * lightning special-attack damage) — so the DPS optimiser would never
 * surface them on its own. This repository just exposes the curated data;
 * {@code GearSection} renders the advisory note and (where wired up) pins the
 * item into the optimiser search.
 *
 * <p>Matches by monster NAME (case-insensitive), not npc id: a monster has
 * many combat-instance-variant ids sharing the same name, and the curated
 * data is authored against display names (see the resource README). Mirrors
 * {@link MonsterRepository}/{@link EquipmentStatsRepository}'s
 * bundled-resource singleton pattern.
 */
public final class MonsterGearOverrideRepository {
    private static final String RESOURCE_PATH = "/com/ospulse/combat/monster_gear_overrides.json";

    private static volatile MonsterGearOverrideRepository instance;

    private final Map<String, List<MonsterGearOverride>> byLowercaseMonsterName;

    private MonsterGearOverrideRepository(Map<String, List<MonsterGearOverride>> byLowercaseMonsterName) {
        this.byLowercaseMonsterName = Collections.unmodifiableMap(byLowercaseMonsterName);
    }

    /** Shared, lazily-initialised singleton loaded from the bundled resource. */
    public static MonsterGearOverrideRepository getInstance() {
        MonsterGearOverrideRepository result = instance;
        if (result == null) {
            synchronized (MonsterGearOverrideRepository.class) {
                result = instance;
                if (result == null) {
                    instance = result = loadFromResource(RESOURCE_PATH);
                }
            }
        }
        return result;
    }

    /** Loads a repository from an arbitrary classpath resource (mainly for tests). */
    static MonsterGearOverrideRepository loadFromResource(String resourcePath) {
        Gson gson = BundledGson.get();
        try (Reader reader = new InputStreamReader(requireResource(resourcePath), StandardCharsets.UTF_8)) {
            RootDto root = gson.fromJson(reader, RootDto.class);
            Map<String, List<MonsterGearOverride>> byName = new HashMap<>();
            if (root != null && root.overrides != null) {
                for (OverrideDto dto : root.overrides) {
                    if (dto.monsters == null || dto.slot == null || dto.itemName == null) {
                        continue; // malformed entry — treated as "no data"
                    }
                    MonsterGearOverride.Slot slot;
                    try {
                        slot = MonsterGearOverride.Slot.valueOf(dto.slot.trim().toUpperCase(Locale.ROOT));
                    } catch (IllegalArgumentException ignored) {
                        continue; // unknown slot name in the data — skip defensively
                    }
                    java.util.Set<Integer> alternativeItemIds = dto.alternativeItemIds == null
                            ? java.util.Collections.emptySet()
                            : new java.util.LinkedHashSet<>(dto.alternativeItemIds);
                    for (String monsterName : dto.monsters) {
                        if (monsterName == null || monsterName.isEmpty()) {
                            continue;
                        }
                        MonsterGearOverride override = new MonsterGearOverride(
                                monsterName, slot, dto.itemId, dto.itemName, dto.reason, alternativeItemIds);
                        byName.computeIfAbsent(monsterName.toLowerCase(Locale.ROOT), k -> new ArrayList<>())
                                .add(override);
                    }
                }
            }
            Map<String, List<MonsterGearOverride>> immutableByName = new HashMap<>();
            for (Map.Entry<String, List<MonsterGearOverride>> e : byName.entrySet()) {
                immutableByName.put(e.getKey(), Collections.unmodifiableList(e.getValue()));
            }
            return new MonsterGearOverrideRepository(immutableByName);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to load monster gear override data from " + resourcePath, e);
        }
    }

    private static InputStream requireResource(String resourcePath) {
        InputStream in = MonsterGearOverrideRepository.class.getResourceAsStream(resourcePath);
        if (in == null) {
            throw new IllegalStateException("Bundled resource not found on classpath: " + resourcePath);
        }
        return in;
    }

    public int size() {
        int total = 0;
        for (List<MonsterGearOverride> overrides : byLowercaseMonsterName.values()) {
            total += overrides.size();
        }
        return total;
    }

    /**
     * The curated gear override(s) for the given monster name (case-insensitive
     * exact match, mirroring {@link MonsterRepository#byName}), or an empty
     * list if this monster has none.
     */
    public List<MonsterGearOverride> forMonster(String monsterName) {
        if (monsterName == null) {
            return Collections.emptyList();
        }
        List<MonsterGearOverride> found = byLowercaseMonsterName.get(monsterName.toLowerCase(Locale.ROOT));
        if (found == null) {
            // The picker hands us dataset names like "Rune dragon (Elvarg)" — fall back to the base name.
            found = byLowercaseMonsterName.get(MonsterNameKey.baseName(monsterName));
        }
        return found == null ? Collections.emptyList() : found;
    }

    /** Internal Gson deserialisation shape mirroring {@code monster_gear_overrides.json}'s top-level object. */
    private static final class RootDto {
        List<OverrideDto> overrides;
    }

    /** Internal Gson deserialisation shape mirroring one entry of the {@code overrides} array. */
    private static final class OverrideDto {
        List<String> monsters;
        String slot;
        int itemId;
        String itemName;
        String reason;
        /**
         * Optional: other item ids that satisfy this requirement equally well
         * as {@code itemId} (review finding 3 — e.g. every Slayer helmet
         * variant substitutes for a plain face-protection item). Absent/empty
         * for every requirement with no known substitute.
         */
        List<Integer> alternativeItemIds;
    }
}

package com.ospulse.combat;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * One curated monster-mechanic gear requirement: a specific item that matters
 * for a MECHANICS reason (special-attack mitigation, safespotting, immunity,
 * etc.) rather than raw DPS — the kind of thing the DPS optimiser would never
 * surface on its own. See {@link MonsterGearOverrideRepository} for how this
 * is loaded and looked up, and that class's bundled resource README for the
 * data shape/provenance.
 */
public final class MonsterGearOverride {
    /**
     * The {@code net.runelite.api.EquipmentInventorySlot} this override
     * applies to, named (not the raw ordinal) for readability in the bundled
     * JSON. Ordinals mirror {@link EquipmentIndexRepository}'s README.
     */
    public enum Slot {
        HEAD(0),
        CAPE(1),
        AMULET(2),
        WEAPON(3),
        BODY(4),
        SHIELD(5),
        LEGS(7),
        GLOVES(9),
        BOOTS(10),
        RING(12),
        AMMO(13);

        private final int slotOrdinal;

        Slot(int slotOrdinal) {
            this.slotOrdinal = slotOrdinal;
        }

        /** The {@code EquipmentInventorySlot} ordinal this named slot maps to. */
        public int slotOrdinal() {
            return slotOrdinal;
        }
    }

    private final String monsterName;
    private final Slot slot;
    private final int itemId;
    private final String itemName;
    private final String reason;
    private final Set<Integer> alternativeItemIds;

    MonsterGearOverride(String monsterName, Slot slot, int itemId, String itemName, String reason) {
        this(monsterName, slot, itemId, itemName, reason, Collections.emptySet());
    }

    /**
     * @param alternativeItemIds Other item ids that ALSO satisfy this
     * requirement just as well as {@code itemId} (e.g. a Slayer helmet
     * substitutes for a Dust devil's Facemask requirement — see review
     * finding 3). {@code itemId} itself never needs to be repeated here.
     */
    MonsterGearOverride(String monsterName, Slot slot, int itemId, String itemName, String reason,
                         Set<Integer> alternativeItemIds) {
        this.monsterName = monsterName;
        this.slot = slot;
        this.itemId = itemId;
        this.itemName = itemName;
        this.reason = reason;
        this.alternativeItemIds = alternativeItemIds == null || alternativeItemIds.isEmpty()
            ? Collections.emptySet()
            : Collections.unmodifiableSet(new LinkedHashSet<>(alternativeItemIds));
    }

    /** The exact monster display name this entry was declared under (one name per expanded entry). */
    public String monsterName() {
        return monsterName;
    }

    public Slot slot() {
        return slot;
    }

    /** The primary/canonical item id — shown in the advisory note and what the optimiser force-includes. */
    public int itemId() {
        return itemId;
    }

    public String itemName() {
        return itemName;
    }

    /** One short sentence explaining why this item matters (shown verbatim in the advisory note). */
    public String reason() {
        return reason;
    }

    /**
     * Other item ids that satisfy this requirement equally well as
     * {@link #itemId()} (e.g. every Slayer helmet variant substitutes for a
     * plain face-protection item like a Facemask) — see {@link #satisfiedBy}.
     * Empty when this requirement has no known substitutes.
     */
    public Set<Integer> alternativeItemIds() {
        return alternativeItemIds;
    }

    /** True when {@code shownId} is either the primary {@link #itemId()} or one of {@link #alternativeItemIds()}. */
    public boolean satisfiedBy(int shownId) {
        return shownId == itemId || alternativeItemIds.contains(shownId);
    }
}

package com.ospulse.combat;

import com.google.gson.Gson;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Loads the bundled, hand-curated "both-locations" monster list ({@code
 * /com/ospulse/combat/wilderness_variant_monsters.json}, see the
 * accompanying README for provenance/generation) — monsters that CAN be
 * fought in the Wilderness but are NOT Wilderness-exclusive (see {@link
 * WildernessMonsterRepository} for that set). Each entry pairs the real
 * bundled monster name ({@code baseMonster}, e.g. "Black dragon (Level
 * 227)") with the synthetic, selectable display name ({@code displayName},
 * e.g. "Black dragon (Wilderness)") {@link MonsterRepository} synthesizes a
 * twin {@link Monster} for at load time.
 *
 * <p>This is the director-mandated fix for a real gap: excluding a
 * both-locations monster entirely (the previous stage's approach)
 * silently withheld the revenant-weapon bonus from a real, selectable
 * Wilderness fight (e.g. Black dragon at the Lava Maze Dungeon). Making
 * the Wilderness instance a SEPARATE, explicitly-selected target instead
 * of guessing removes the ambiguity entirely: the player says which one
 * they mean, so nothing is silently assumed or overstated.
 */
public final class WildernessVariantMonsterRepository {
    private static final String RESOURCE_PATH = "/com/ospulse/combat/wilderness_variant_monsters.json";

    private static volatile WildernessVariantMonsterRepository instance;

    private final List<Variant> variants;

    /** One base-monster -> synthetic-Wilderness-twin pairing. */
    public static final class Variant {
        private final String baseMonster;
        private final String displayName;

        Variant(String baseMonster, String displayName) {
            this.baseMonster = baseMonster;
            this.displayName = displayName;
        }

        /** The real bundled monster name this variant is a Wilderness twin of. */
        public String baseMonster() {
            return baseMonster;
        }

        /** The synthetic, selectable display name for the Wilderness twin. */
        public String displayName() {
            return displayName;
        }
    }

    private WildernessVariantMonsterRepository(List<Variant> variants) {
        this.variants = Collections.unmodifiableList(variants);
    }

    /** Shared, lazily-initialised singleton loaded from the bundled resource. */
    public static WildernessVariantMonsterRepository getInstance() {
        WildernessVariantMonsterRepository result = instance;
        if (result == null) {
            synchronized (WildernessVariantMonsterRepository.class) {
                result = instance;
                if (result == null) {
                    instance = result = loadFromResource(RESOURCE_PATH);
                }
            }
        }
        return result;
    }

    /** Loads a repository from an arbitrary classpath resource (mainly for tests). */
    static WildernessVariantMonsterRepository loadFromResource(String resourcePath) {
        Gson gson = BundledGson.get();
        try (Reader reader = new InputStreamReader(requireResource(resourcePath), StandardCharsets.UTF_8)) {
            RootDto root = gson.fromJson(reader, RootDto.class);
            List<Variant> parsed = new ArrayList<>();
            if (root != null && root.variants != null) {
                for (VariantDto dto : root.variants) {
                    if (dto.baseMonster == null || dto.baseMonster.isEmpty()
                            || dto.displayName == null || dto.displayName.isEmpty()) {
                        continue; // malformed entry - treated as "no data"
                    }
                    parsed.add(new Variant(dto.baseMonster, dto.displayName));
                }
            }
            return new WildernessVariantMonsterRepository(parsed);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to load wilderness variant monster data from " + resourcePath, e);
        }
    }

    private static InputStream requireResource(String resourcePath) {
        InputStream in = WildernessVariantMonsterRepository.class.getResourceAsStream(resourcePath);
        if (in == null) {
            throw new IllegalStateException("Bundled resource not found on classpath: " + resourcePath);
        }
        return in;
    }

    public int size() {
        return variants.size();
    }

    /** Every curated base-monster -> synthetic-display-name pairing. */
    public List<Variant> all() {
        return variants;
    }

    /** Internal Gson deserialisation shape mirroring {@code wilderness_variant_monsters.json}'s top-level object. */
    private static final class RootDto {
        List<VariantDto> variants;
    }

    /** Internal Gson deserialisation shape for one entry of the {@code variants} array. */
    private static final class VariantDto {
        String baseMonster;
        String displayName;
    }
}

