package com.ospulse.combat;

import com.google.gson.Gson;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Loads the bundled, hand-curated monster combat-requirement table
 * ({@code /com/ospulse/combat/monster_combat_requirements.json}) and serves
 * in-memory lookups by monster name.
 *
 * <p>These are cases where a monster can only be damaged by a specific
 * subset of weapons/ammo/combat styles (a {@link MonsterCombatRequirement.Type#WEAPON_GATE}),
 * or must be finished off with a specific item at low HP (a
 * {@link MonsterCombatRequirement.Type#FINISHER}) — flagship examples: Kurask
 * (leaf-bladed weapons, broad ammunition, or magic only) and Gargoyles
 * (rock/granite hammer finisher).
 *
 * <p>Matches by monster NAME (case-insensitive), not npc id, mirroring
 * {@link MonsterGearOverrideRepository}'s bundled-resource singleton pattern.
 */
public final class MonsterCombatRequirementRepository {
    private static final String RESOURCE_PATH = "/com/ospulse/combat/monster_combat_requirements.json";

    private static volatile MonsterCombatRequirementRepository instance;

    private final Map<String, MonsterCombatRequirement> byLowercaseMonsterName;

    private MonsterCombatRequirementRepository(Map<String, MonsterCombatRequirement> byLowercaseMonsterName) {
        this.byLowercaseMonsterName = Collections.unmodifiableMap(byLowercaseMonsterName);
    }

    /** Shared, lazily-initialised singleton loaded from the bundled resource. */
    public static MonsterCombatRequirementRepository getInstance() {
        MonsterCombatRequirementRepository result = instance;
        if (result == null) {
            synchronized (MonsterCombatRequirementRepository.class) {
                result = instance;
                if (result == null) {
                    instance = result = loadFromResource(RESOURCE_PATH);
                }
            }
        }
        return result;
    }

    /** Loads a repository from an arbitrary classpath resource (mainly for tests). */
    static MonsterCombatRequirementRepository loadFromResource(String resourcePath) {
        Gson gson = BundledGson.get();
        try (Reader reader = new InputStreamReader(requireResource(resourcePath), StandardCharsets.UTF_8)) {
            RootDto root = gson.fromJson(reader, RootDto.class);
            Map<String, MonsterCombatRequirement> byName = new HashMap<>();
            if (root != null && root.requirements != null) {
                for (ReqDto dto : root.requirements) {
                    if (dto.monsters == null || dto.type == null) {
                        continue; // malformed entry — treated as "no data"
                    }
                    MonsterCombatRequirement.Type type;
                    try {
                        type = MonsterCombatRequirement.Type.valueOf(dto.type.trim().toUpperCase(Locale.ROOT));
                    } catch (IllegalArgumentException ignored) {
                        continue; // unknown type in the data — skip defensively
                    }
                    Set<CombatStyle> allowedStyles = EnumSet.noneOf(CombatStyle.class);
                    if (dto.allowedStyles != null) {
                        for (String styleName : dto.allowedStyles) {
                            if (styleName == null) {
                                continue;
                            }
                            try {
                                allowedStyles.add(CombatStyle.valueOf(styleName.trim().toUpperCase(Locale.ROOT)));
                            } catch (IllegalArgumentException ignored) {
                                // unknown style name in the data — skip defensively
                            }
                        }
                    }
                    MonsterCombatRequirement requirement;
                    if (type == MonsterCombatRequirement.Type.FINISHER) {
                        requirement = MonsterCombatRequirement.finisher(
                                dto.finisherItemIds == null ? Collections.emptySet() : new HashSet<>(dto.finisherItemIds),
                                dto.note);
                    } else if (type == MonsterCombatRequirement.Type.DAMAGE_PENALTY) {
                        requirement = MonsterCombatRequirement.damagePenalty(
                                dto.allowedItemIds == null ? Collections.emptySet() : new HashSet<>(dto.allowedItemIds),
                                dto.damageMultiplier == null ? 1.0 : dto.damageMultiplier,
                                parseStyles(dto.penalisedStyles), parseStyles(dto.exemptStyles), dto.note);
                    } else if (type == MonsterCombatRequirement.Type.DAMAGE_CAP) {
                        requirement = MonsterCombatRequirement.damageCap(
                                dto.maxHitCap == null ? -1 : dto.maxHitCap,
                                dto.maxHitCapWhenCrushHighest == null ? -1 : dto.maxHitCapWhenCrushHighest,
                                dto.allowedItemIds == null ? Collections.emptySet() : new HashSet<>(dto.allowedItemIds),
                                parseCapByStyle(dto.maxHitCapByStyle),
                                parseCapMode(dto.capMode),
                                dto.note);
                    } else {
                        requirement = MonsterCombatRequirement.weaponGate(
                                dto.allowedItemIds == null ? Collections.emptySet() : new HashSet<>(dto.allowedItemIds),
                                dto.allowedAmmoIds == null ? Collections.emptySet() : new HashSet<>(dto.allowedAmmoIds),
                                allowedStyles, dto.note);
                    }
                    for (String monsterName : dto.monsters) {
                        if (monsterName == null || monsterName.isEmpty()) {
                            continue;
                        }
                        byName.put(monsterName.toLowerCase(Locale.ROOT), requirement);
                    }
                }
            }
            return new MonsterCombatRequirementRepository(byName);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to load monster combat requirement data from " + resourcePath, e);
        }
    }

    /** Parses a style-name list from the curated data, skipping anything unrecognised. */
    private static Set<CombatStyle> parseStyles(List<String> styleNames) {
        Set<CombatStyle> styles = EnumSet.noneOf(CombatStyle.class);
        if (styleNames == null) {
            return styles;
        }
        for (String styleName : styleNames) {
            if (styleName == null) {
                continue;
            }
            try {
                styles.add(CombatStyle.valueOf(styleName.trim().toUpperCase(Locale.ROOT)));
            } catch (IllegalArgumentException ignored) {
                // unknown style name in the data — skip defensively
            }
        }
        return styles;
    }

    /**
     * Parses the optional per-style cap map (JSON keys are style names, e.g.
     * {@code "RANGED"}), skipping anything unrecognised or null-valued. Gson
     * leaves the field {@code null} when it is absent from the source JSON —
     * every existing {@code DAMAGE_CAP} entry lacks this key, so this must
     * (and does) return an empty map for them, leaving {@link
     * TargetDamageRule#maxHitCapFor} to fall back to the flat/crush-highest
     * value exactly as before.
     */
    private static Map<CombatStyle, Integer> parseCapByStyle(Map<String, Integer> raw) {
        Map<CombatStyle, Integer> result = new EnumMap<>(CombatStyle.class);
        if (raw == null) {
            return result;
        }
        for (Map.Entry<String, Integer> entry : raw.entrySet()) {
            if (entry.getKey() == null || entry.getValue() == null) {
                continue;
            }
            try {
                result.put(CombatStyle.valueOf(entry.getKey().trim().toUpperCase(Locale.ROOT)), entry.getValue());
            } catch (IllegalArgumentException ignored) {
                // unknown style name in the data — skip defensively
            }
        }
        return result;
    }

    /**
     * Parses the optional cap-mode field, defaulting to {@link
     * MonsterCombatRequirement.CapMode#CLAMP} when absent (Gson leaves it
     * {@code null}) or unrecognised — every entry written before {@code
     * CapMode} existed has no {@code capMode} key and must keep clamp
     * semantics.
     */
    private static MonsterCombatRequirement.CapMode parseCapMode(String raw) {
        if (raw == null) {
            return MonsterCombatRequirement.CapMode.CLAMP;
        }
        try {
            return MonsterCombatRequirement.CapMode.valueOf(raw.trim().toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException ignored) {
            return MonsterCombatRequirement.CapMode.CLAMP;
        }
    }

    private static InputStream requireResource(String resourcePath) {
        InputStream in = MonsterCombatRequirementRepository.class.getResourceAsStream(resourcePath);
        if (in == null) {
            throw new IllegalStateException("Bundled resource not found on classpath: " + resourcePath);
        }
        return in;
    }

    public int size() {
        return byLowercaseMonsterName.size();
    }

    /**
     * The curated combat requirement for the given monster name
     * (case-insensitive exact match, mirroring
     * {@link MonsterGearOverrideRepository#forMonster}), or empty if this
     * monster has none.
     */
    public Optional<MonsterCombatRequirement> forMonster(String monsterName) {
        if (monsterName == null) {
            return Optional.empty();
        }
        MonsterCombatRequirement exact = byLowercaseMonsterName.get(monsterName.toLowerCase(Locale.ROOT));
        if (exact != null) {
            return Optional.of(exact);
        }
        // The picker hands us dataset names like "Kurask (Normal)" — fall back to the base name.
        return Optional.ofNullable(byLowercaseMonsterName.get(MonsterNameKey.baseName(monsterName)));
    }

    /**
     * Every curated key, lowercased, exactly as stored in the lookup map. Exposed so
     * the data-integrity test can assert each one still resolves against the bundled
     * monster data — a typo here silently disables a gate rather than failing loudly.
     */
    Set<String> curatedKeys() {
        return Collections.unmodifiableSet(byLowercaseMonsterName.keySet());
    }

    /** Every curated entry, for dataset-wide integrity checks. */
    Collection<MonsterCombatRequirement> allRequirements() {
        return Collections.unmodifiableCollection(byLowercaseMonsterName.values());
    }

    /** Exposes the name normalisation {@link #forMonster} falls back to. */
    static String baseNameOf(String monsterName) {
        return MonsterNameKey.baseName(monsterName);
    }

    /** Internal Gson deserialisation shape mirroring {@code monster_combat_requirements.json}'s top-level object. */
    private static final class RootDto {
        List<ReqDto> requirements;
    }

    /** Internal Gson deserialisation shape mirroring one entry of the {@code requirements} array. */
    private static final class ReqDto {
        List<String> monsters;
        String type;
        List<Integer> allowedItemIds;
        List<Integer> allowedAmmoIds;
        List<String> allowedStyles;
        List<Integer> finisherItemIds;
        String note;
        Double damageMultiplier;
        List<String> penalisedStyles;
        List<String> exemptStyles;
        Integer maxHitCap;
        Integer maxHitCapWhenCrushHighest;
        Map<String, Integer> maxHitCapByStyle;
        String capMode;
    }
}

package com.ospulse.combat;

/**
 * The Keris partisan family's 1/51 "puncturing" triple-damage roll (see
 * {@link KerisPartisan} for the family's OTHER, plain-multiplier passive):
 * per the OSRS Wiki, a landed hit has a 1/51 chance to deal triple the
 * rolled damage. Extracted into its own small, pure, dependency-light class
 * (the {@code TonalzticsDualHit}/{@code ScytheCascade} precedent) since this
 * is a genuinely different DISTRIBUTION from a plain roll — the roll is
 * tripled AFTER whatever value it would otherwise have displayed, so it
 * cannot be expressed as a multiplier on max hit — and therefore bypasses
 * the generic {@code finish()} the same way {@code finishFang} does.
 *
 * <p><b>The average is always exactly {@code baseAverage * 53/51}</b> —
 * {@code E[displayed'] = (50/51)*E[displayed] + (1/51)*E[3*displayed] =
 * E[displayed] * (50 + 3)/51}, a pure linear scaling that holds regardless
 * of what "displayed" distribution feeds it (uncapped, CLAMP, or REROLL —
 * see {@link #averageDamage}). This mirrors why {@code
 * TonalzticsDualHit}'s combined average is "just" a doubling: the SHAPE of
 * the underlying distribution is irrelevant to a linear rescaling of its
 * mean, only to its variance/overkill.
 *
 * <p><b>Overkill needs the full mixture distribution</b> (unlike the
 * average, {@code floor}/clamp/re-roll boundaries interact with which raw
 * value gets tripled, so this builds the explicit {@code 0..3*range}
 * mixture — 50/51 of the ordinary displayed-damage mass kept as-is, 1/51
 * of it moved to triple its own value — then hands it to {@link
 * DamageDistribution#overkillFromExplicitDistribution(double[], int[], int)}.
 *
 * <p><b>Disclosed modelling choice for a capped target</b> (no currently
 * curated Kalphite/Scarabite monster has a damage cap, so this path is
 * untested against real data): the cap is modelled as applying to the
 * PRE-triple roll — i.e. the weapon's own passive triples whatever value
 * the roll would otherwise display, INCLUDING past the cap — rather than
 * the monster's cap re-applying a second time after tripling. If a future
 * curated monster is both Kalphite-tagged and damage-capped, this
 * assumption should be revisited against the real in-game behaviour.
 */
final class KerisTripleRoll {
    private KerisTripleRoll() {
    }

    /** The 1/51 chance of a triple, expressed as a {@link Fraction}-shaped constant pair used throughout this class. */
    private static final double TRIPLE_CHANCE = 1.0 / 51.0;
    private static final double PLAIN_CHANCE = 50.0 / 51.0;

    /** Exact average-damage scaling factor: {@code 50/51 + 3/51 = 53/51}. */
    static double averageDamage(double baseAverage) {
        return baseAverage * (PLAIN_CHANCE + 3.0 * TRIPLE_CHANCE);
    }

    /** Uncapped expected overkill, including the 1/51 triple-damage mixture. */
    static double expectedOverkill(double hitChance, int maxHit, int targetHitpoints) {
        if (maxHit <= 0 || targetHitpoints <= 0) {
            return 0.0;
        }
        double[] displayed = uncappedPerHitDistribution(hitChance, maxHit);
        return overkillFromMixture(displayed, targetHitpoints);
    }

    /** Expected overkill against a target that CLAMPS each hitsplat, including the triple-damage mixture. */
    static double cappedExpectedOverkill(double hitChance, int uncappedMaxHit, int cap, int targetHitpoints) {
        if (targetHitpoints <= 0) {
            return 0.0;
        }
        double[] displayed = cappedPerHitDistribution(hitChance, uncappedMaxHit, cap);
        return overkillFromMixture(displayed, targetHitpoints);
    }

    /** Expected overkill against a target that RE-ROLLS each hitsplat above a cap, including the triple-damage mixture. */
    static double rerolledExpectedOverkill(double hitChance, int uncappedMaxHit, int cap, int targetHitpoints) {
        if (targetHitpoints <= 0) {
            return 0.0;
        }
        double[] displayed = rerolledPerHitDistribution(hitChance, uncappedMaxHit, cap);
        return overkillFromMixture(displayed, targetHitpoints);
    }

    /** One hit's outcome distribution (index 0 = miss, summing to 1): miss, or the ordinary bumped-uniform {@code 0..maxHit} roll. */
    private static double[] uncappedPerHitDistribution(double hitChance, int maxHit) {
        if (maxHit <= 0) {
            double[] p = new double[2];
            p[0] = 1.0 - hitChance;
            p[1] = hitChance;
            return p;
        }
        double[] p = new double[maxHit + 1];
        p[0] = 1.0 - hitChance;
        double denom = maxHit + 1.0;
        p[1] = hitChance * 2.0 / denom;
        for (int d = 2; d <= maxHit; d++) {
            p[d] = hitChance / denom;
        }
        return p;
    }

    private static double[] cappedPerHitDistribution(double hitChance, int maxHit, int cap) {
        if (maxHit <= 0 || cap >= maxHit) {
            return uncappedPerHitDistribution(hitChance, maxHit);
        }
        if (cap <= 0) {
            double[] p = new double[1];
            p[0] = 1.0;
            return p;
        }
        double[] capped = DamageDistribution.cappedHitsplatDistribution(maxHit, cap);
        double[] p = new double[cap + 1];
        p[0] = 1.0 - hitChance;
        for (int d = 1; d <= cap; d++) {
            p[d] = hitChance * capped[d];
        }
        return p;
    }

    private static double[] rerolledPerHitDistribution(double hitChance, int maxHit, int cap) {
        if (maxHit <= 0 || cap >= maxHit) {
            return uncappedPerHitDistribution(hitChance, maxHit);
        }
        if (cap <= 0) {
            double[] p = new double[1];
            p[0] = 1.0;
            return p;
        }
        double[] rerolled = DamageDistribution.rerolledHitsplatDistribution(maxHit, cap);
        double[] p = new double[cap + 1];
        p[0] = (1.0 - hitChance) + hitChance * rerolled[0];
        for (int d = 1; d <= cap; d++) {
            p[d] = hitChance * rerolled[d];
        }
        return p;
    }

    /**
     * Mixes a "displayed damage" distribution with its own 1/51-triggered
     * tripled self: {@code q[v] += 50/51 * displayed[v]} (kept as-is) and
     * {@code q[3*v] += 1/51 * displayed[v]} (tripled), for every {@code v}
     * (including {@code v = 0}, whose triple is still 0 — a miss is
     * unaffected by the puncture roll either way).
     */
    private static double[] tripleMixture(double[] displayed) {
        int maxDisplayed = displayed.length - 1;
        double[] q = new double[3 * maxDisplayed + 1];
        for (int v = 0; v <= maxDisplayed; v++) {
            if (displayed[v] == 0.0) {
                continue;
            }
            q[v] += PLAIN_CHANCE * displayed[v];
            q[3 * v] += TRIPLE_CHANCE * displayed[v];
        }
        return q;
    }

    private static double overkillFromMixture(double[] displayed, int targetHitpoints) {
        double[] mixture = tripleMixture(displayed);
        int[] identity = new int[mixture.length];
        for (int v = 0; v < mixture.length; v++) {
            identity[v] = v;
        }
        return DamageDistribution.overkillFromExplicitDistribution(mixture, identity, targetHitpoints);
    }

    /**
     * Assembles the full {@link DpsResult} for a Keris-partisan-vs-Kalphite
     * attack, mirroring {@link TonalzticsDualHit#finish}/{@link
     * ScytheCascade#finish}'s shape. {@code uncappedMaxHit}/{@code
     * attackRoll} must already include the family's own +33% (and, for "of
     * breaching", +33% accuracy) multiplicative step — this class only
     * models the triple-damage mixture on top of whatever roll it is given.
     */
    static DpsResult finish(int uncappedMaxHit, int cap, MonsterCombatRequirement.CapMode mode,
                             int attackRoll, int defenceRoll, int weaponSpeedTicks, int targetHitpoints) {
        double hitChance = CombatMath.hitChance(attackRoll, defenceRoll);
        boolean capped = cap >= 0 && cap < uncappedMaxHit;
        int visibleMaxHit = capped ? Math.min(uncappedMaxHit, cap) : uncappedMaxHit;
        double baseAverage;
        double overkill;
        if (!capped) {
            baseAverage = DamageDistribution.averageDamage(hitChance, uncappedMaxHit);
            overkill = expectedOverkill(hitChance, uncappedMaxHit, targetHitpoints);
        } else if (mode == MonsterCombatRequirement.CapMode.REROLL) {
            baseAverage = DamageDistribution.rerolledAverageDamage(hitChance, uncappedMaxHit, cap);
            overkill = rerolledExpectedOverkill(hitChance, uncappedMaxHit, cap, targetHitpoints);
        } else {
            baseAverage = DamageDistribution.cappedAverageDamage(hitChance, uncappedMaxHit, cap);
            overkill = cappedExpectedOverkill(hitChance, uncappedMaxHit, cap, targetHitpoints);
        }
        double avgDamage = averageDamage(baseAverage);
        double dps = CombatMath.dps(avgDamage, weaponSpeedTicks);
        double ttkSeconds = dps > 0 ? (targetHitpoints + overkill) / dps : 0.0;
        // Deliberately returning visibleMaxHit (NOT 3x it) even though the 1/51
        // puncture roll can triple the landed damage: DpsResult#maxHit()'s
        // contract is the standard/displayed max hit, matching the wiki and
        // other calculators, not the true theoretical maximum with a rare proc
        // included - see that javadoc for the full rationale. The proc is
        // still fully reflected in dps/avgDamage/ttkSeconds/overkill above.
        return new DpsResult(visibleMaxHit, hitChance, dps, avgDamage, ttkSeconds, overkill, false);
    }
}

package com.ospulse.combat;

import java.util.Collections;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Combat spells and their base max hits — hand-transcribed raw FACTS from the
 * OSRS Wiki spell pages ("OSRS Wiki spell facts, hand-transcribed"; NOT copied
 * from any third-party dataset, so this table carries no NC licence).
 *
 * <p><b>Within-tier level scaling (deliberate simplification):</b> since the
 * 2023 elemental-spell rework, a lower element's max hit scales up with Magic
 * level until it matches the strongest spell of its tier (e.g. Wind Bolt
 * reaches Fire Bolt's 12 well before level 59). The values here are each
 * tier's cap — exact whenever the player's Magic level is at or above the
 * tier's strongest-spell requirement, which is the realistic use of a DPS
 * picker; the sub-cap low-level ramp is not modelled.
 *
 * <p>God spells assume no Charge (Charge's +10 is a separate TODO). Magic
 * Dart, salamanders and Tumeken/Trident built-ins are NOT spells — powered
 * staves are handled by {@link PoweredStaff}.
 *
 * <p><b>{@code spriteId}:</b> the legacy (deprecated but still bundled)
 * {@code net.runelite.api.SpriteID.SPELL_*} constant for this spell's
 * spellbook icon, hand-copied here as a raw int so this pure combat-engine
 * class carries no RuneLite import. Every offensive spell in this enum has an
 * exact {@code SPELL_<NAME>} match in that class (verified against the
 * pinned client jar) — none needed a rune-icon fallback.
 */
public enum Spell {
    // ---- Standard spellbook (elemental tiers at their tier-cap max hits) ----
    WIND_STRIKE("Wind Strike", SpellBook.STANDARD, 8, 15, Element.WIND, Tier.STRIKE),
    WATER_STRIKE("Water Strike", SpellBook.STANDARD, 8, 17, Element.WATER, Tier.STRIKE),
    EARTH_STRIKE("Earth Strike", SpellBook.STANDARD, 8, 19, Element.EARTH, Tier.STRIKE),
    FIRE_STRIKE("Fire Strike", SpellBook.STANDARD, 8, 21, Element.FIRE, Tier.STRIKE),
    WIND_BOLT("Wind Bolt", SpellBook.STANDARD, 12, 23, Element.WIND, Tier.BOLT),
    WATER_BOLT("Water Bolt", SpellBook.STANDARD, 12, 26, Element.WATER, Tier.BOLT),
    EARTH_BOLT("Earth Bolt", SpellBook.STANDARD, 12, 29, Element.EARTH, Tier.BOLT),
    FIRE_BOLT("Fire Bolt", SpellBook.STANDARD, 12, 32, Element.FIRE, Tier.BOLT),
    WIND_BLAST("Wind Blast", SpellBook.STANDARD, 16, 35, Element.WIND, Tier.BLAST),
    WATER_BLAST("Water Blast", SpellBook.STANDARD, 16, 38, Element.WATER, Tier.BLAST),
    EARTH_BLAST("Earth Blast", SpellBook.STANDARD, 16, 40, Element.EARTH, Tier.BLAST),
    FIRE_BLAST("Fire Blast", SpellBook.STANDARD, 16, 44, Element.FIRE, Tier.BLAST),
    WIND_WAVE("Wind Wave", SpellBook.STANDARD, 20, 46, Element.WIND, Tier.WAVE),
    WATER_WAVE("Water Wave", SpellBook.STANDARD, 20, 48, Element.WATER, Tier.WAVE),
    EARTH_WAVE("Earth Wave", SpellBook.STANDARD, 20, 51, Element.EARTH, Tier.WAVE),
    FIRE_WAVE("Fire Wave", SpellBook.STANDARD, 20, 52, Element.FIRE, Tier.WAVE),
    WIND_SURGE("Wind Surge", SpellBook.STANDARD, 24, 362, Element.WIND, Tier.SURGE),
    WATER_SURGE("Water Surge", SpellBook.STANDARD, 24, 363, Element.WATER, Tier.SURGE),
    EARTH_SURGE("Earth Surge", SpellBook.STANDARD, 24, 364, Element.EARTH, Tier.SURGE),
    FIRE_SURGE("Fire Surge", SpellBook.STANDARD, 24, 365, Element.FIRE, Tier.SURGE),
    CRUMBLE_UNDEAD("Crumble Undead", SpellBook.STANDARD, 15, 34),
    /**
     * Castable ONLY with Iban's staff equipped (regular 1409, the other
     * charged id 1410, or the upgraded Iban's staff (u) 12658) — see
     * {@link #isCastableWith(int)}.
     */
    IBAN_BLAST("Iban Blast", SpellBook.STANDARD, 25, 53, 1409, 1410, 12658),
    SARADOMIN_STRIKE("Saradomin Strike", SpellBook.STANDARD, 20, 61),
    CLAWS_OF_GUTHIX("Claws of Guthix", SpellBook.STANDARD, 20, 60),
    FLAMES_OF_ZAMORAK("Flames of Zamorak", SpellBook.STANDARD, 20, 59),

    // ---- Ancient Magicks ----
    SMOKE_RUSH("Smoke Rush", SpellBook.ANCIENT, 13, 329),
    SHADOW_RUSH("Shadow Rush", SpellBook.ANCIENT, 14, 337),
    BLOOD_RUSH("Blood Rush", SpellBook.ANCIENT, 15, 333),
    ICE_RUSH("Ice Rush", SpellBook.ANCIENT, 16, 325),
    SMOKE_BURST("Smoke Burst", SpellBook.ANCIENT, 17, 330),
    SHADOW_BURST("Shadow Burst", SpellBook.ANCIENT, 18, 338),
    BLOOD_BURST("Blood Burst", SpellBook.ANCIENT, 21, 334),
    ICE_BURST("Ice Burst", SpellBook.ANCIENT, 22, 326),
    SMOKE_BLITZ("Smoke Blitz", SpellBook.ANCIENT, 23, 331),
    SHADOW_BLITZ("Shadow Blitz", SpellBook.ANCIENT, 24, 339),
    BLOOD_BLITZ("Blood Blitz", SpellBook.ANCIENT, 25, 335),
    ICE_BLITZ("Ice Blitz", SpellBook.ANCIENT, 26, 327),
    SMOKE_BARRAGE("Smoke Barrage", SpellBook.ANCIENT, 27, 332),
    SHADOW_BARRAGE("Shadow Barrage", SpellBook.ANCIENT, 28, 340),
    BLOOD_BARRAGE("Blood Barrage", SpellBook.ANCIENT, 29, 336),
    ICE_BARRAGE("Ice Barrage", SpellBook.ANCIENT, 30, 328);

    /** All autocast spell casts take 5 game ticks (3.0s), regardless of the staff's own melee speed. */
    public static final int CAST_SPEED_TICKS = 5;

    /**
     * The classic elemental-spell element, used to match a monster's
     * elemental weakness (see {@link Monster#weaknessElement()} /
     * {@code DpsCalculator.computeMagic}). Only the standard Strike/Bolt/
     * Blast/Wave/Surge tiers carry one; Iban Blast, Magic Dart, the god
     * spells and every Ancient Magicks spell (ice/blood/smoke/shadow) have
     * none, so they never get a weakness bonus. The upstream weirdgloop
     * data calls the wind element "air" — {@code WIND} is this enum's name
     * for the same element.
     */
    public enum Element {
        WIND,
        WATER,
        EARTH,
        FIRE
    }

    /**
     * The standard-spellbook elemental tier a spell belongs to, used ONLY to
     * gate the Twinflame staff's second-hit passive (see
     * {@link #twinflameEligible()}) — it has no other combat effect here.
     * Only the 20 elemental Strike/Bolt/Blast/Wave/Surge spells carry a tier;
     * every other spell (Iban Blast, Crumble Undead, the three god spells and
     * all 12 Ancient Magicks) has {@code tier() == null}, matching their
     * {@code element() == null}.
     */
    public enum Tier {
        STRIKE,
        BOLT,
        BLAST,
        WAVE,
        SURGE
    }

    public enum SpellBook {
        STANDARD("Standard"),
        ANCIENT("Ancient");

        private final String displayName;

        SpellBook(String displayName) {
            this.displayName = displayName;
        }

        public String displayName() {
            return displayName;
        }
    }

    private final String displayName;
    private final SpellBook book;
    private final int baseMaxHit;
    private final int spriteId;
    /** Weapon item ids this spell may be cast with; empty = castable with any (magic) weapon. */
    private final Set<Integer> requiredWeaponItemIds;
    /** This spell's elemental-weakness-matching element, or {@code null} if it has none. */
    private final Element element;
    /** This spell's elemental {@link Tier}, or {@code null} if it has none (see {@link Tier}'s javadoc). */
    private final Tier tier;

    Spell(String displayName, SpellBook book, int baseMaxHit, int spriteId) {
        this(displayName, book, baseMaxHit, spriteId, null, null, new int[0]);
    }

    /** Standard elemental tiers (Strike/Bolt/Blast/Wave/Surge): carries an {@link Element} and a {@link Tier}, no weapon requirement. */
    Spell(String displayName, SpellBook book, int baseMaxHit, int spriteId, Element element, Tier tier) {
        this(displayName, book, baseMaxHit, spriteId, element, tier, new int[0]);
    }

    /**
     * @param requiredWeaponItemIds if non-empty, {@link #isCastableWith(int)} only
     *                               returns {@code true} for one of these weapon
     *                               item ids (e.g. Iban Blast + Iban's staff).
     */
    Spell(String displayName, SpellBook book, int baseMaxHit, int spriteId, int... requiredWeaponItemIds) {
        this(displayName, book, baseMaxHit, spriteId, null, null, requiredWeaponItemIds);
    }

    private Spell(String displayName, SpellBook book, int baseMaxHit, int spriteId, Element element, Tier tier,
                  int... requiredWeaponItemIds) {
        this.displayName = displayName;
        this.book = book;
        this.baseMaxHit = baseMaxHit;
        this.spriteId = spriteId;
        this.element = element;
        this.tier = tier;
        this.requiredWeaponItemIds = requiredWeaponItemIds.length == 0
                ? Collections.emptySet()
                : java.util.Arrays.stream(requiredWeaponItemIds).boxed().collect(Collectors.toSet());
    }

    public String displayName() {
        return displayName;
    }

    public SpellBook book() {
        return book;
    }

    /** The spell's base max hit BEFORE any magic-damage bonuses (see class javadoc for the tier-cap simplification). */
    public int baseMaxHit() {
        return baseMaxHit;
    }

    /** The {@code net.runelite.api.SpriteID.SPELL_*} constant for this spell's icon (see class javadoc). */
    public int spriteId() {
        return spriteId;
    }

    /**
     * This spell's element for elemental-weakness matching, or {@code null}
     * when it has none (Iban Blast, Magic Dart, god spells, all Ancient
     * Magicks — see {@link Element}).
     */
    public Element element() {
        return element;
    }

    /**
     * This spell's elemental {@link Tier} (Strike/Bolt/Blast/Wave/Surge), or
     * {@code null} when it has none — see {@link Tier}'s javadoc for exactly
     * which spells carry one.
     */
    public Tier tier() {
        return tier;
    }

    /**
     * True when the Twinflame staff (item id 30634 — see {@code
     * GearVariants}) fires a second hit for this spell. Per the OSRS Wiki:
     * "the staff fires two spells at once ... when casting elemental spells
     * (excluding Strike and Surge spells)" — i.e. Bolt/Blast/Wave across all
     * four elements (12 spells total).
     *
     * <p><b>Deliberately gated on {@link #element()} + {@link #tier()}, NOT
     * on the spell's display name.</b> The reference JS implementation
     * (weirdgloop/osrs-dps-calc) gates on {@code name.includes('Bolt'|'Blast'|
     * 'Wave')}, which also incorrectly matches "Iban Blast" — a non-elemental
     * spell ({@code element() == null}) that this codebase must NOT treat as
     * eligible. Iban Blast, Crumble Undead, the three god spells and all 12
     * Ancient Magicks all have {@code element() == null} (and {@code tier()
     * == null}) and therefore never qualify, regardless of what their name
     * contains.
     */
    public boolean twinflameEligible() {
        return element != null && (tier == Tier.BOLT || tier == Tier.BLAST || tier == Tier.WAVE);
    }

    /**
     * True when this spell may actually be cast with the given equipped
     * weapon item id. Spells with no weapon requirement (the vast majority)
     * are always castable; Iban Blast is the one exception in this enum —
     * castable ONLY with Iban's staff (1409/1410/12658).
     */
    public boolean isCastableWith(int weaponItemId) {
        return requiredWeaponItemIds.isEmpty() || requiredWeaponItemIds.contains(weaponItemId);
    }

    @Override
    public String toString() {
        return displayName;
    }
}

package com.ospulse.combat;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * A monster's combat requirement: a weapon/ammo/style damage gate, a finisher
 * item, or a damage-magnitude effect (penalty/cap) a hard style-gate cannot
 * express. Pure, no RuneLite deps.
 */
public final class MonsterCombatRequirement
{
    public enum Type { WEAPON_GATE, FINISHER, DAMAGE_PENALTY, DAMAGE_CAP }

    /**
     * How a {@link Type#DAMAGE_CAP} ceiling is actually applied to the damage
     * roll — these are mechanically different distributions, not two names
     * for the same thing:
     * <ul>
     * <li>{@link #CLAMP} — the roll stays uniform {@code 0..uncappedMaxHit}
     * and every result above the cap lands ON the cap, piling probability
     * mass there (e.g. The Hueycoatl's tail). See
     * {@link DamageDistribution#cappedAverageDamage}/
     * {@link DamageDistribution#cappedExpectedOverkill}.</li>
     * <li>{@link #REROLL} — a hit above the cap is re-rolled uniformly into
     * {@code 0..cap} (e.g. Verzik Vitur phase 1). Use
     * {@link DamageDistribution#rerolledAverageDamage}/
     * {@link DamageDistribution#rerolledExpectedOverkill}.
     *
     * <p><b>Do NOT implement this as {@code maxHit = min(maxHit, cap)} fed
     * through the ordinary uncapped path.</b> That is tempting because the
     * re-rolled distribution is nearly uniform over {@code 0..cap}, but the
     * ordinary formulas carry OSRS's "a rolled 0 becomes 1" correction, and a
     * re-rolled 0 is a GENUINE result that must keep its probability mass. The
     * bump belongs to the damage roll, so it applies before the monster
     * re-rolls and survives only on values that were never re-rolled, giving
     * {@code E = cap/2 + 1/(uncappedMax + 1)} for {@code cap >= 1} — not the
     * {@code cap/2 + 1/(cap + 1)} the ordinary path would produce. At Verzik's
     * ranged/magic cap of 3 that shortcut overstates by about 15% and hands
     * the overkill DP a zero-free distribution, so TTK is wrong too. This
     * exact mistake shipped once and was caught in review.</li>
     * </ul>
     * Default {@link #CLAMP} — every entry shipped before this enum existed
     * used clamp semantics, so this default keeps them byte-identical.
     */
    public enum CapMode { CLAMP, REROLL }

    private final Type type;
    private final Set<Integer> allowedItemIds;
    private final Set<Integer> allowedAmmoIds;
    private final Set<CombatStyle> allowedStyles;
    private final Set<Integer> finisherItemIds;
    private final String note;
    private final double damageMultiplier;
    private final Set<CombatStyle> penalisedStyles;
    private final Set<CombatStyle> exemptStyles;
    private final int maxHitCap;
    private final int maxHitCapWhenCrushHighest;
    private final Map<CombatStyle, Integer> maxHitCapByStyle;
    private final CapMode capMode;

    private MonsterCombatRequirement(Type type, Set<Integer> allowedItemIds, Set<Integer> allowedAmmoIds,
                                     Set<CombatStyle> allowedStyles, Set<Integer> finisherItemIds, String note,
                                     double damageMultiplier, Set<CombatStyle> penalisedStyles,
                                     Set<CombatStyle> exemptStyles,
                                     int maxHitCap, int maxHitCapWhenCrushHighest,
                                     Map<CombatStyle, Integer> maxHitCapByStyle, CapMode capMode)
    {
        this.type = type;
        this.allowedItemIds = allowedItemIds == null ? Collections.emptySet() : new HashSet<>(allowedItemIds);
        this.allowedAmmoIds = allowedAmmoIds == null ? Collections.emptySet() : new HashSet<>(allowedAmmoIds);
        this.allowedStyles = (allowedStyles == null || allowedStyles.isEmpty())
            ? EnumSet.noneOf(CombatStyle.class) : EnumSet.copyOf(allowedStyles);
        this.finisherItemIds = finisherItemIds == null ? Collections.emptySet() : new HashSet<>(finisherItemIds);
        this.note = note == null ? "" : note;
        this.damageMultiplier = damageMultiplier;
        this.penalisedStyles = (penalisedStyles == null || penalisedStyles.isEmpty())
            ? EnumSet.noneOf(CombatStyle.class) : EnumSet.copyOf(penalisedStyles);
        this.exemptStyles = (exemptStyles == null || exemptStyles.isEmpty())
            ? EnumSet.noneOf(CombatStyle.class) : EnumSet.copyOf(exemptStyles);
        this.maxHitCap = maxHitCap;
        this.maxHitCapWhenCrushHighest = maxHitCapWhenCrushHighest;
        this.maxHitCapByStyle = (maxHitCapByStyle == null || maxHitCapByStyle.isEmpty())
            ? Collections.emptyMap() : new EnumMap<>(maxHitCapByStyle);
        this.capMode = capMode == null ? CapMode.CLAMP : capMode;
    }

    public static MonsterCombatRequirement weaponGate(Set<Integer> allowedItemIds, Set<Integer> allowedAmmoIds,
                                                      Set<CombatStyle> allowedStyles, String note)
    {
        return new MonsterCombatRequirement(Type.WEAPON_GATE, allowedItemIds, allowedAmmoIds,
            allowedStyles, Collections.emptySet(), note, 1.0, Collections.emptySet(), Collections.emptySet(), -1, -1,
            Collections.emptyMap(), CapMode.CLAMP);
    }

    public static MonsterCombatRequirement finisher(Set<Integer> finisherItemIds, String note)
    {
        return new MonsterCombatRequirement(Type.FINISHER, Collections.emptySet(), Collections.emptySet(),
            EnumSet.noneOf(CombatStyle.class), finisherItemIds, note, 1.0, Collections.emptySet(), Collections.emptySet(), -1, -1,
            Collections.emptyMap(), CapMode.CLAMP);
    }

    /**
     * A monster that deals-with (rather than blocks) an off-style weapon: any
     * weapon NOT in {@code allowedItemIds} has its max hit multiplied by
     * {@code damageMultiplier} for a style in {@code penalisedStyles} (empty
     * means every style). This never gates — see {@link TargetDamageRule}.
     */
    public static MonsterCombatRequirement damagePenalty(Set<Integer> allowedItemIds, double damageMultiplier,
                                                          Set<CombatStyle> penalisedStyles,
                                                          Set<CombatStyle> exemptStyles, String note)
    {
        return new MonsterCombatRequirement(Type.DAMAGE_PENALTY, allowedItemIds, Collections.emptySet(),
            EnumSet.noneOf(CombatStyle.class), Collections.emptySet(), note, damageMultiplier, penalisedStyles,
            exemptStyles, -1, -1, Collections.emptyMap(), CapMode.CLAMP);
    }

    /**
     * A flat max-hit ceiling regardless of gear, with an alternative (usually
     * higher) ceiling when the loadout's crush attack bonus is its highest —
     * see {@link TargetDamageRule#maxHitCapFor}. Uses clamp semantics ({@link
     * CapMode#CLAMP}) and no per-style overrides or cap-exempt weapons — the
     * original shape, kept unchanged so every entry written before per-style
     * caps existed is byte-identical. This never gates.
     */
    public static MonsterCombatRequirement damageCap(int maxHitCap, int maxHitCapWhenCrushHighest, String note)
    {
        return damageCap(maxHitCap, maxHitCapWhenCrushHighest, Collections.emptySet(),
            Collections.emptyMap(), CapMode.CLAMP, note);
    }

    /**
     * Full {@link Type#DAMAGE_CAP} form: a per-style cap map (e.g. Verzik
     * Vitur phase 1's melee-10/ranged-3/magic-3 split — one flat value cannot
     * express that), a set of weapons wholly exempt from the cap (e.g.
     * Dawnbringer at Verzik), and a {@link CapMode}. Resolution order — see
     * {@link TargetDamageRule#maxHitCapFor}: an exempt weapon first, then a
     * per-style hit, then the flat/crush-highest fallback above. This never
     * gates.
     */
    public static MonsterCombatRequirement damageCap(int maxHitCap, int maxHitCapWhenCrushHighest,
                                                      Set<Integer> capExemptItemIds,
                                                      Map<CombatStyle, Integer> maxHitCapByStyle,
                                                      CapMode capMode, String note)
    {
        return new MonsterCombatRequirement(Type.DAMAGE_CAP, capExemptItemIds, Collections.emptySet(),
            EnumSet.noneOf(CombatStyle.class), Collections.emptySet(), note, 1.0, Collections.emptySet(),
            Collections.emptySet(), maxHitCap, maxHitCapWhenCrushHighest, maxHitCapByStyle, capMode);
    }

    public Type type() { return type; }
    public String note() { return note; }
    public Set<Integer> finisherItemIds() { return Collections.unmodifiableSet(finisherItemIds); }
    public Set<Integer> allowedItemIds() { return Collections.unmodifiableSet(allowedItemIds); }
    public Set<Integer> allowedAmmoIds() { return Collections.unmodifiableSet(allowedAmmoIds); }
    public Set<CombatStyle> allowedStyles() { return Collections.unmodifiableSet(allowedStyles); }

    /** Multiplier applied to max hit when the weapon is NOT in {@link #allowedItemIds()}. Default {@code 1.0}. */
    public double damageMultiplier() { return damageMultiplier; }

    /** Styles the {@link #damageMultiplier()} applies to; empty means "all styles". Default empty. */
    public Set<CombatStyle> penalisedStyles() { return Collections.unmodifiableSet(penalisedStyles); }
    /** Styles on which {@code allowedItemIds} actually grants the exemption; empty = any penalised style. */
    public Set<CombatStyle> exemptStyles() { return Collections.unmodifiableSet(exemptStyles); }

    /** Flat max-hit ceiling; {@code -1} means "no cap". Default {@code -1}. */
    public int maxHitCap() { return maxHitCap; }

    /** Alternative cap used when crush is the loadout's highest attack bonus; {@code -1} means "no such rule". Default {@code -1}. */
    public int maxHitCapWhenCrushHighest() { return maxHitCapWhenCrushHighest; }

    /**
     * Per-{@link CombatStyle} cap override (e.g. Verzik Vitur phase 1: melee
     * 10, ranged/magic 3) — takes priority over {@link #maxHitCap()}/
     * {@link #maxHitCapWhenCrushHighest()} for a style present in this map.
     * Empty means no per-style split; every entry falls back to the flat/
     * crush-highest value. Default empty.
     */
    public Map<CombatStyle, Integer> maxHitCapByStyle() { return Collections.unmodifiableMap(maxHitCapByStyle); }

    /**
     * How the cap is applied to the damage roll — see {@link CapMode}.
     * Default {@link CapMode#CLAMP}, matching every entry shipped before this
     * enum existed.
     */
    public CapMode capMode() { return capMode; }

    /** Full-attack truth: can this weapon+style+ammo deal damage to the monster? */
    public boolean permits(int weaponId, CombatStyle style, int ammoId)
    {
        if (type != Type.WEAPON_GATE) { return true; }
        if (allowedStyles.contains(style)) { return true; }
        if (allowedItemIds.contains(weaponId)) { return true; }
        if (style == CombatStyle.RANGED && !allowedAmmoIds.isEmpty() && allowedAmmoIds.contains(ammoId)) { return true; }
        return false;
    }

    /**
     * Optimiser weapon-slot gate (chosen style fixed; ammo slot enforced
     * separately). Back-compat overload — assumes the weapon fires worn ammo.
     */
    public boolean permitsWeapon(int weaponId, CombatStyle style)
    {
        return permitsWeapon(weaponId, style, true);
    }

    /**
     * Optimiser weapon-slot gate. {@code weaponUsesWornAmmo} must be {@code false}
     * for a self-supplying ranged weapon (blowpipe, chinchompa, crystal bow,
     * atlatl): such a weapon fires its own ammunition, so it can never satisfy a
     * broad-ammo gate via the worn ammo slot and is only permitted when listed
     * explicitly in {@code allowedItemIds}. Without this a blowpipe slipped
     * through Kurask's gate paired with (unfired) broad bolts.
     */
    public boolean permitsWeapon(int weaponId, CombatStyle style, boolean weaponUsesWornAmmo)
    {
        if (type != Type.WEAPON_GATE) { return true; }
        if (allowedStyles.contains(style)) { return true; }
        if (allowedItemIds.contains(weaponId)) { return true; }
        return style == CombatStyle.RANGED && !allowedAmmoIds.isEmpty() && weaponUsesWornAmmo;
    }

    /** Optimiser ammo-slot gate (only restricts ranged). */
    public boolean permitsAmmo(int ammoId, CombatStyle style)
    {
        if (type != Type.WEAPON_GATE) { return true; }
        if (style != CombatStyle.RANGED) { return true; }
        if (allowedAmmoIds.isEmpty()) { return true; }
        return allowedAmmoIds.contains(ammoId);
    }
}

package com.ospulse.combat;

import net.runelite.client.game.ItemMapping;

import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;

/**
 * Pure per-item "risk value" — the real gp worth of an item id, used ONLY by
 * the gear optimiser's expensive-item wilderness/PvP risk cap (see {@code
 * GearOptimizer.Request.Builder#riskValueSource}). Deliberately decoupled
 * from the BUDGET/affordability price: owning an item keeps it free to equip
 * (the budget path, via {@code GearOptimizer.Request.owned}), but it is still
 * real gp at risk if lost, so the risk value here is always the item's true
 * worth regardless of ownership.
 *
 * <ul>
 *   <li>A tradeable item's risk value is simply its own GE price.</li>
 *   <li>An untradeable item's risk value is the summed GE price of the
 *       tradeable component(s) it represents, resolved via {@link
 *       ItemMapping} — RuneLite's own bundled price-checking data, covering
 *       Barrows pieces (degraded/undamaged tiers, echo variants), imbued
 *       rings, and other GE-restricted-but-valuable items automatically, at
 *       any scale, with no per-item hand-listing required.</li>
 *   <li>An "assembled" best-in-slot item (e.g. an Avernic defender, made
 *       from a tradeable hilt on a defender the player already owns) is
 *       valued at its curated {@link AssembledItemComponents} tradeable
 *       component's GE price when {@link ItemMapping} doesn't cover it.</li>
 *   <li>A small curated fallback ({@link #CREATED_ITEM_COMPONENTS}) covers
 *       created/untradeable items {@link ItemMapping} does not (yet) map.
 *       Add entries only once the exact tradeable component ids are verified
 *       against a concrete source (RuneLite's generated {@code ItemID}
 *       constants, or the OSRS wiki) — see the field's javadoc.</li>
 *   <li>{@link #classify} additionally supports a last-resort Trouver
 *       parchment fallback for rare untradeables with no tradeable
 *       equivalent anywhere above (Fire cape, Fighter torso, imbued capes,
 *       etc.) — the parchment is the real gp cost to protect one on death,
 *       so it stands in as the item's risk value rather than letting it
 *       silently escape the cap at 0. Free-to-reclaim items (Ardougne
 *       cloak, Rada's blessing) are exempted from this fallback entirely.
 *       The back-compat {@link #riskValue} entry point does not use this
 *       fallback (unmapped/no curated entry still risks at 0 there).</li>
 *   <li>Within that parchment fallback, a small curated {@link
 *       #UNTRADEABLE_RECLAIM_COST} table caps the value at the item's real
 *       gp reclaim/purchase cost (via {@code Math.min}) for the handful of
 *       CHEAP untradeables the parchment price would otherwise wildly
 *       over-value — e.g. Barrows gloves, a ~130k item, would otherwise risk
 *       at the ~575k parchment price it happens to also fall back to.</li>
 * </ul>
 *
 * <p><b>No client-thread dependency:</b> {@link ItemMapping#map(int)} is a
 * static enum lookup over data bundled in the {@code net.runelite:client}
 * jar itself (verified via {@code javap} against {@code client-1.12.32.jar}
 * on this project's classpath) — it does NOT touch {@code ItemManager} or
 * any other client-thread-only API, so this class runs anywhere, including
 * plain unit tests, given a caller-supplied {@code isTradeable}/{@code
 * gePrice} pair (see {@link RiskValuationTest}).
 */
public final class RiskValuation
{
	private RiskValuation()
	{
	}

	/**
	 * Curated fallback for created/untradeable items {@link ItemMapping} does
	 * not cover: item id -&gt; tradeable component item ids whose summed GE
	 * price stands in for the created item's risk value.
	 *
	 * <p><b>Scorching bow (29591) does NOT need an entry here.</b> Verified
	 * via {@code javap}-inspection of the decompiled {@code
	 * net.runelite.client.game.ItemMapping} enum shipped in {@code
	 * net.runelite:client:1.12.32} (this project's pinned classpath
	 * dependency — see {@code build.gradle}): {@code ItemMapping.map(29591)}
	 * already resolves to a single entry with {@code tradeableItem =
	 * TORMENTED_SYNAPSE (29580)}, {@code quantity = 1} — RuneLite's own
	 * price-checking convention for the three Doom-of-Mokhaiotl weapons
	 * (Scorching bow 29591, Emberlight 29589, Purging staff 29594, all keyed
	 * off the same synapse mapping). The {@link ItemMapping} branch in {@link
	 * #riskValue} therefore handles it automatically. This map intentionally
	 * starts EMPTY; add an entry only for a created item confirmed absent
	 * from {@link ItemMapping} (re-run the same {@code javap}/reflection
	 * check before adding one — do not guess a component id from memory).
	 */
	private static final Map<Integer, int[]> CREATED_ITEM_COMPONENTS;

	static
	{
		Map<Integer, int[]> m = new HashMap<>();
		CREATED_ITEM_COMPONENTS = Collections.unmodifiableMap(m);
	}

	/**
	 * Curated reclaim/purchase costs (flat, non-fluctuating game constants —
	 * NOT GE prices) for a handful of clearly-CHEAP untradeables that would
	 * otherwise fall to the Trouver parchment fallback in {@link #classify}
	 * and risk at a wildly inflated value (the parchment itself is a
	 * mid-value GE item, currently priced far above many of these items'
	 * real worth). Used only via {@code Math.min(parchmentPrice,
	 * reclaimCost)} — never on its own — so an entry here can only ever
	 * LOWER an item's risk value versus the plain parchment fallback, never
	 * raise it.
	 *
	 * <p>Add an entry only for an item whose id is confirmed against this
	 * project's own {@code equipment_index.min.json} (id -&gt; name -&gt;
	 * tradeable flag) AND whose reclaim cost is a single unambiguous flat gp
	 * figure with no diary/minigame-point/quest-state dependency — anything
	 * uncertain is deliberately left at the plain parchment price instead
	 * (see the field's per-entry comment for the verification done).
	 */
	private static final Map<Integer, Long> UNTRADEABLE_RECLAIM_COST;

	static
	{
		Map<Integer, Long> m = new HashMap<>();
		// 7462 = Barrows gloves. Verified against this project's own
		// src/main/resources/com/ospulse/combat/equipment_index.min.json
		// ("7462": ["Barrows gloves", 9, false] — slot 9 = hands,
		// tradeable = false), cross-checked against the OSRS Wiki
		// (oldschool.runescape.wiki/w/Barrows_gloves, fetched 2026-07-14).
		// Bought from the Culinaromancer's Chest (Lumbridge Castle cellar,
		// after completing Recipe for Disaster) for a flat 130,000gp.
		// Deliberately the FULL price, not the Elite Lumbridge & Draynor
		// Diary-discounted 104,000gp — that discount is player-state
		// dependent, so 130,000 is the one figure correct for every player.
		m.put(7462, 130_000L);
		UNTRADEABLE_RECLAIM_COST = Collections.unmodifiableMap(m);
	}

	/**
	 * Which rule produced a {@link Risk}'s value — surfaced so callers (the
	 * optimizer price resolver, and eventually the UI/exclude wave) can tell a
	 * genuinely-priced item apart from one that only "counts" because of the
	 * {@link #classify parchment fallback}.
	 */
	public enum Source
	{
		/** The item is itself tradeable; valued at its own GE price. */
		TRADEABLE,
		/** Untradeable; valued via a real {@link ItemMapping} entry. */
		MAPPING,
		/** Untradeable; valued via {@link AssembledItemComponents#priceSourceComponent(int)}. */
		ASSEMBLED,
		/** Untradeable; valued via the curated {@link #CREATED_ITEM_COMPONENTS} fallback. */
		CURATED,
		/**
		 * Untradeable with no real value found anywhere above; stood in for by
		 * the Trouver parchment price (the cost to protect it on death) so it
		 * still counts as "expensive" for the risk cap.
		 */
		PARCHMENT,
		/**
		 * Untradeable but re-obtainable at a known flat reclaim/purchase cost
		 * (curated {@link #UNTRADEABLE_RECLAIM_COST}). Valued at that cost, capped
		 * at the parchment price. DELIBERATELY distinct from {@link #PARCHMENT} so a
		 * cheap reclaimable item (e.g. Barrows gloves) is NOT flagged as a rare
		 * parchment-only unprotectable — needsProtection, the "must be protected
		 * (Trouver parchment)" UI, and the hide-unprotectable exclusion all key off
		 * {@link #PARCHMENT}, not this.
		 */
		RECLAIM,
		/** No value could be determined (and it isn't free-reobtainable either) — 0. */
		NONE
	}

	/** A risk value paired with which rule ({@link Source}) produced it. */
	public static final class Risk
	{
		public final long value;
		public final Source source;

		public Risk(long value, Source source)
		{
			this.value = value;
			this.source = source;
		}

		@Override
		public boolean equals(Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Risk))
			{
				return false;
			}
			Risk other = (Risk) o;
			return value == other.value && source == other.source;
		}

		@Override
		public int hashCode()
		{
			return java.util.Objects.hash(value, source);
		}

		@Override
		public String toString()
		{
			return "Risk{value=" + value + ", source=" + source + '}';
		}
	}

	/**
	 * The real gp "risk value" of {@code itemId} for the expensive-item cap,
	 * plus which rule produced it — see {@link Source}. NEVER used for
	 * budget/affordability — see class javadoc.
	 *
	 * <p>Order of resolution for an UNTRADEABLE item: (1) a real {@link
	 * ItemMapping} entry ({@link Source#MAPPING}); (2) {@link
	 * AssembledItemComponents#priceSourceComponent(int)}, for best-in-slot
	 * items assembled from a tradeable part ({@link Source#ASSEMBLED} — fixes
	 * the Avernic defender reading 0); (3) the curated {@link
	 * #CREATED_ITEM_COMPONENTS} fallback ({@link Source#CURATED}); (4) the
	 * Trouver parchment price, standing in for "cost to protect this on
	 * death" ({@link Source#PARCHMENT}) — but only when {@code
	 * isFreeReobtainable} is false (a free-to-reclaim item, e.g. Ardougne
	 * cloak or Rada's blessing, carries no death risk at all and must never
	 * be priced) and {@code parchmentPrice > 0}. That parchment value is
	 * itself capped at {@code Math.min(parchmentPrice, reclaimCost)} for the
	 * curated {@link #UNTRADEABLE_RECLAIM_COST} entries (e.g. Barrows
	 * gloves, ~130k, never risks at the ~575k parchment price), still
	 * reported as {@link Source#RECLAIM} (not {@link Source#PARCHMENT}) so cheap reclaimables are not flagged as parchment-only unprotectables. A TRADEABLE item is always
	 * just its own GE price ({@link Source#TRADEABLE}), regardless of
	 * free-reobtainable status.
	 *
	 * @param itemId              the equipment item id to value
	 * @param isTradeable         whether {@code itemId} itself can be bought/sold on the GE
	 * @param gePrice             GE unit price for a (tradeable) item id; 0 if none
	 * @param parchmentPrice      the Trouver parchment's own GE price (0 if unknown/untradeable
	 *                            right now), used only as the last-resort fallback
	 * @param isFreeReobtainable  whether {@code itemId} is free to reclaim if lost (no death
	 *                            risk); checked first, before any other rule
	 */
	public static Risk classify(int itemId, IntPredicate isTradeable, IntToLongFunction gePrice,
		long parchmentPrice, IntPredicate isFreeReobtainable)
	{
		if (isFreeReobtainable.test(itemId))
		{
			return new Risk(0L, Source.NONE);
		}

		if (isTradeable.test(itemId))
		{
			return new Risk(Math.max(0L, gePrice.applyAsLong(itemId)), Source.TRADEABLE);
		}

		Collection<ItemMapping> mappings = ItemMapping.map(itemId);
		if (mappings != null && !mappings.isEmpty())
		{
			long sum = 0L;
			for (ItemMapping mapping : mappings)
			{
				long componentPrice = Math.max(0L, gePrice.applyAsLong(mapping.getTradeableItem()));
				sum += componentPrice * mapping.getQuantity();
			}
			if (sum > 0L)
			{
				return new Risk(sum, Source.MAPPING);
			}
		}

		Integer assembledComponent = AssembledItemComponents.priceSourceComponent(itemId);
		if (assembledComponent != null)
		{
			long componentPrice = Math.max(0L, gePrice.applyAsLong(assembledComponent));
			if (componentPrice > 0L)
			{
				return new Risk(componentPrice, Source.ASSEMBLED);
			}
		}

		int[] components = CREATED_ITEM_COMPONENTS.get(itemId);
		if (components != null)
		{
			long sum = 0L;
			for (int componentId : components)
			{
				sum += Math.max(0L, gePrice.applyAsLong(componentId));
			}
			return new Risk(sum, Source.CURATED);
		}

		long parchment = Math.max(0L, parchmentPrice);
		if (parchment > 0L)
		{
			Long reclaimCost = UNTRADEABLE_RECLAIM_COST.get(itemId);
			if (reclaimCost != null)
			{
				// Re-obtainable at a known flat cost: value at min(cost, parchment)
				// and mark RECLAIM (not PARCHMENT) so it is NOT added to
				// needsProtection / flagged "must be protected (Trouver parchment)".
				return new Risk(Math.min(parchment, reclaimCost), Source.RECLAIM);
			}
			return new Risk(parchment, Source.PARCHMENT);
		}

		return new Risk(0L, Source.NONE);
	}

	/**
	 * Backward-compatible entry point: delegates to {@link #classify} with no
	 * parchment fallback ({@code parchmentPrice = 0}) and no free-reobtainable
	 * exemption (always {@code false}), so existing callers/tests keep their
	 * prior behaviour unchanged — untradeable items with no {@link
	 * ItemMapping}/{@link AssembledItemComponents}/{@link
	 * #CREATED_ITEM_COMPONENTS} value still resolve to 0.
	 *
	 * @param itemId      the equipment item id to value
	 * @param isTradeable whether {@code itemId} itself can be bought/sold on
	 *                    the GE
	 * @param gePrice     GE unit price for a (tradeable) item id; 0 if none
	 */
	public static long riskValue(int itemId, IntPredicate isTradeable, IntToLongFunction gePrice)
	{
		return classify(itemId, isTradeable, gePrice, 0L, id -> false).value;
	}
}

package com.ospulse.combat;

/**
 * Entry point: computes max hit / accuracy / DPS for one gear+player+style
 * setup against one {@link Monster}, per the OSRS Wiki DPS calculator
 * formulas (see per-method Javadoc in {@link CombatMath}/{@link DamageDistribution} for citations).
 * <p>
 * Tier-A effects modelled (each isolated below, with an "applies when"
 * predicate, per the design doc): offensive prayers, best-potion boosts,
 * Slayer helm(i)/black mask(i) on-task bonus, Salve amulet variants vs
 * Undead, Void/Elite Void. Tier-B effects: demonbane weapons (melee sword
 * line + Burning claws + ranged Scorching bow; accuracy/damage split, applied
 * as the weapon's own step stacking with the salve/slayer slot, with the
 * ranged max hit folding additively into an on-task imbued helm — see
 * computeRanged; a per-monster demonbane RESISTANCE, e.g. Duke Sucellus's
 * 30%, scales the bonus's excess-over-1 down — see
 * resistedDemonbaneFraction), Dragon
 * Hunter lance/crossbow/wand vs dragons and the Twisted bow's vs-target-magic
 * scaling (separate multiplicative steps — they stack with the target
 * slot, with the same ranged-max-hit additive fold for the DHCB),
 * powered-staff built-in spells and real {@link Spell} max hits for
 * autocast, and elemental weakness (a monster's {@code weaknessElement}/
 * {@code weaknessSeverity} adds straight into the magic-damage percent when
 * the cast {@link Spell}'s {@link Spell.Element} matches - see
 * computeMagic), and Osmumten's fang's two STAB-only passives (double
 * accuracy roll + compressed 15%-85%-of-max-hit damage roll — its own
 * hitChance/avgDamage formulas replace the generic ones entirely rather than
 * being a multiplicative step on maxHit/attackRoll — see computeMelee /
 * finishFang / {@link DamageDistribution#fangHitChance} /
 * {@link DamageDistribution#fangAverageDamage}). Six further
 * multi-hit/conditional-bonus mechanics (design spec §9, each behind its own
 * "applies when" predicate): the Scythe of Vitur family's target-size-scaled
 * 1-3x cascade (own bespoke hitChance/average pair, see {@link
 * ScytheCascade}/finishScythe-equivalent bypass in computeMelee), Colossal
 * blade's flat {@code +2*min(size,5)} max hit, the Keris partisan family's
 * vs-Kalphite/Scarabite +33% damage(+accuracy for "of breaching")/1-in-51
 * triple-damage roll (see {@link KerisPartisan}/{@link KerisTripleRoll}),
 * the charged Tonalztics of Ralos's two full independent damage rolls (see
 * {@link TonalzticsDualHit}), the revenant weapons' (Craw's bow/Viggora's
 * chainmace/Thammaron's sceptre) +50% accuracy/damage vs a Wilderness target
 * — gated on {@link Monster#isWildernessTarget()}, true for both genuinely
 * Wilderness-exclusive monsters ({@link WildernessMonsterRepository}) and a
 * player-selected synthetic "(Wilderness)" twin of a both-locations monster
 * ({@link WildernessVariantMonsterRepository}; see {@link
 * Monster#lookupName()} for how every OTHER lookup resolves such a twin back
 * to its real underlying monster) — and the
 * Crystal armour set + Crystal bow/Bow of Faerdhinen's +15% damage/+30%
 * accuracy (see {@code EquipmentStats#crystalSetBonusActive}). Remaining
 * unmodelled effects (special attacks, Avarice, Tumeken's 3x gear
 * multiplier, ...) are simply not applied — extend this class (and {@link
 * CombatMath}/{@link DamageDistribution}) to add them, gated behind their
 * own "applies when" predicate.
 *
 * <p>Per-target damage-magnitude effects (a curated {@link
 * MonsterCombatRequirement}, resolved once per compute call from {@code
 * target.lookupName()} — {@link Monster#lookupName()}, NOT {@link
 * Monster#name()}, so a synthetic Wilderness-variant target resolves the
 * SAME requirement its real underlying monster would — via {@link
 * MonsterCombatRequirementRepository} by the
 * overloads below that don't take one explicitly, or supplied directly by a
 * caller — such as {@code GearOptimizer} — that already resolved its own,
 * which then takes priority instead of a second, independent lookup here; see
 * {@link #applyTargetDamageRules} for how "not supplied" and "supplied null"
 * are told apart): a {@link
 * MonsterCombatRequirement.Type#DAMAGE_PENALTY} multiplies max hit for an
 * off-style weapon (e.g. Corporeal Beast's half-damage stab), and a {@link
 * MonsterCombatRequirement.Type#DAMAGE_CAP} ceilings max hit, optionally per
 * {@link CombatStyle} (e.g. Verzik Vitur phase 1: melee 10, ranged/magic 3)
 * and optionally exempting a specific weapon entirely (e.g. Dawnbringer) —
 * both applied as the final step immediately before {@code finish}/{@code
 * finishFang}; see {@link TargetDamageRule}. A cap's {@link
 * MonsterCombatRequirement.CapMode} decides HOW it applies: {@code CLAMP}
 * piles the roll's excess probability mass onto the cap itself (The
 * Hueycoatl's tail), {@code REROLL} re-rolls a too-high hit uniformly into
 * {@code 0..cap} (Verzik). Even for the GENERIC 0..maxHit roll this is NOT
 * simply {@link DamageDistribution#averageDamage}/{@link
 * DamageDistribution#expectedOverkill} fed the cap as maxHit — that shape equivalence
 * (a re-roll into {@code 0..cap} of a uniform {@code 0..M} roll is exactly a
 * uniform {@code 0..cap} roll) is real, but those two methods ALSO bake in
 * the ordinary "rolled 0 becomes 1" bump, which belongs to the ORIGINAL roll
 * and does not apply a second time to the re-roll's own genuine zero —
 * {@link DamageDistribution#rerolledAverageDamage}/{@code
 * rerolledExpectedOverkill} get this right; see {@link #finish}. Osmumten's
 * fang needs its own re-rolled formulas for a different reason (its
 * compressed roll isn't 0..M to begin with) — see {@link #finishFang} and
 * {@link DamageDistribution#rerolledFangAverageDamage}.
 */
public final class DpsCalculator {
    private DpsCalculator() {
    }

    /**
     * Legacy/simple entry point: magic uses {@code baseSpellMaxHit} verbatim
     * with the weapon's own attack speed (no powered-staff or spell logic).
     * Prefer {@link #compute(EquipmentStats, PlayerCombat, CombatStyle, Monster, Spell)}
     * for magic with a real spell, which also auto-detects powered staves.
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, int baseSpellMaxHit) {
        return compute(gear, player, style, target, baseSpellMaxHit, UNKNOWN_WEAPON_ID);
    }

    /**
     * As above, plus the worn weapon's item id — needed to resolve a
     * per-target {@link MonsterCombatRequirement.Type#DAMAGE_PENALTY} (see
     * {@link TargetDamageRule#damageMultiplierFor}). Callers that do not know
     * the weapon id may use the no-arg overload; an unknown id never matches
     * a curated exemption list, so any penalty for the target still applies
     * (the conservative default).
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, int baseSpellMaxHit, int weaponId) {
        return compute(gear, player, style, target, baseSpellMaxHit, weaponId, resolveRequirement(target));
    }

    /**
     * As {@link #compute(EquipmentStats, PlayerCombat, CombatStyle, Monster, int)},
     * but the caller supplies the target's already-resolved {@link
     * MonsterCombatRequirement} instead of it being looked up here — see
     * {@link #applyTargetDamageRules} for why a caller-supplied {@code null}
     * is never re-resolved.
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, int baseSpellMaxHit, MonsterCombatRequirement requirement) {
        return compute(gear, player, style, target, baseSpellMaxHit, UNKNOWN_WEAPON_ID, requirement);
    }

    /**
     * As {@link #compute(EquipmentStats, PlayerCombat, CombatStyle, Monster, int, int)},
     * but the caller supplies the target's already-resolved {@link
     * MonsterCombatRequirement} instead of it being looked up here — see
     * {@link #applyTargetDamageRules} for why a caller-supplied {@code null}
     * is never re-resolved.
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, int baseSpellMaxHit, int weaponId,
                                     MonsterCombatRequirement requirement) {
        if (style == CombatStyle.MAGIC) {
            return computeMagic(gear, player, target, baseSpellMaxHit, gear.weaponSpeedTicks(), false, null, weaponId,
                    requirement, false);
        }
        return computeNonMagic(gear, player, style, target, weaponId, requirement);
    }

    /**
     * Spell-aware entry point. For {@link CombatStyle#MAGIC}: a worn powered
     * staff (detected on {@code gear}) takes precedence — its built-in spell's
     * max hit is derived from the (boosted) Magic level at the weapon's own
     * speed; otherwise the given {@link Spell}'s base max hit is cast at a
     * weapon-aware speed (see {@link MagicCastSpeed}: the Twinflame staff and
     * Harmonised nightmare staff override the default {@link
     * Spell#CAST_SPEED_TICKS}). A {@code null} spell with no powered staff
     * yields a zero-damage result rather than a guess.
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, Spell spell) {
        return compute(gear, player, style, target, spell, UNKNOWN_WEAPON_ID);
    }

    /**
     * As above, plus the worn weapon's item id — see {@link #compute(EquipmentStats,
     * PlayerCombat, CombatStyle, Monster, int, int)} for why it is needed.
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, Spell spell, int weaponId) {
        return compute(gear, player, style, target, spell, weaponId, resolveRequirement(target));
    }

    /**
     * As {@link #compute(EquipmentStats, PlayerCombat, CombatStyle, Monster, Spell)},
     * but the caller supplies the target's already-resolved {@link
     * MonsterCombatRequirement} instead of it being looked up here — see
     * {@link #applyTargetDamageRules} for why a caller-supplied {@code null}
     * is never re-resolved.
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, Spell spell, MonsterCombatRequirement requirement) {
        return compute(gear, player, style, target, spell, UNKNOWN_WEAPON_ID, requirement);
    }

    /**
     * As {@link #compute(EquipmentStats, PlayerCombat, CombatStyle, Monster, Spell, int)},
     * but the caller supplies the target's already-resolved {@link
     * MonsterCombatRequirement} instead of it being looked up here — see
     * {@link #applyTargetDamageRules} for why a caller-supplied {@code null}
     * is never re-resolved.
     */
    public static DpsResult compute(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                     Monster target, Spell spell, int weaponId, MonsterCombatRequirement requirement) {
        if (style != CombatStyle.MAGIC) {
            return computeNonMagic(gear, player, style, target, weaponId, requirement);
        }
        if (gear.poweredStaff().applies()) {
            // Base max hit derives from the boosted level inside computeMagic.
            // Powered staves cast their own built-in "spell" (Magic Dart etc.),
            // which is not a real Spell and carries no element - no weakness bonus.
            // Twinflame/Harmonised are not powered staves, so this branch never
            // needs the weapon-aware cast speed or the second-hit passive.
            return computeMagic(gear, player, target, POWERED_STAFF_SENTINEL, gear.weaponSpeedTicks(),
                    gear.poweredStaff().approximate(), null, weaponId, requirement, false);
        }
        int baseMaxHit = spell == null ? 0 : spell.baseMaxHit();
        Spell.Element element = spell == null ? null : spell.element();
        int castSpeedTicks = MagicCastSpeed.ticksFor(gear.twinflameStaff(), gear.harmonisedNightmareStaff(), spell);
        boolean twinflameSecondHit = gear.twinflameStaff() && spell != null && spell.twinflameEligible();
        return computeMagic(gear, player, target, baseMaxHit, castSpeedTicks, false, element, weaponId,
                requirement, twinflameSecondHit);
    }

    /** Sentinel meaning "the worn weapon's item id is not known to this caller". */
    private static final int UNKNOWN_WEAPON_ID = -1;

    /**
     * The repository-default resolution used by every overload that does not
     * take an explicit {@link MonsterCombatRequirement} — exactly what {@link
     * #applyTargetDamageRules} looked up internally before this class started
     * threading the requirement through as a parameter. Kept as its own
     * method so every "resolve it yourself" overload performs the identical
     * lookup, byte-identical to the old behaviour.
     */
    private static MonsterCombatRequirement resolveRequirement(Monster target) {
        return MonsterCombatRequirementRepository.getInstance().forMonster(target.lookupName()).orElse(null);
    }

    private static DpsResult computeNonMagic(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                             Monster target, int weaponId, MonsterCombatRequirement requirement) {
        if (style == CombatStyle.RANGED) {
            return computeRanged(gear, player, target, weaponId, requirement);
        }
        return computeMelee(gear, player, style, target, weaponId, requirement);
    }

    // ---- Melee (STAB/SLASH/CRUSH) -----------------------------------------------------

    private static DpsResult computeMelee(EquipmentStats gear, PlayerCombat player, CombatStyle style,
                                          Monster target, int weaponId, MonsterCombatRequirement requirement) {
        int boostedStr = player.assumeBestPotion()
                ? PotionBoosts.bestMeleeBoostedLevel(player.baseStrength())
                : player.boostedStrength();
        int boostedAtt = player.assumeBestPotion()
                ? PotionBoosts.bestMeleeBoostedLevel(player.baseAttack())
                : player.boostedAttack();

        OffensivePrayer meleePrayer = assumed(player, OffensivePrayer.PIETY);
        double prayerStrMult = player.assumeBestPrayer() ? meleePrayer.meleeStrengthMult()
                : maxOf(player, OffensivePrayer::meleeStrengthMult);
        double prayerAttMult = player.assumeBestPrayer() ? meleePrayer.meleeAttackMult()
                : maxOf(player, OffensivePrayer::meleeAttackMult);

        int styleBonusStr = player.stance() == Stance.AGGRESSIVE ? 3 : player.stance() == Stance.CONTROLLED ? 1 : 0;
        int styleBonusAtt = player.stance() == Stance.ACCURATE ? 3 : player.stance() == Stance.CONTROLLED ? 1 : 0;

        double voidMult = gear.voidSet().meleeMultiplier();

        int effStr = CombatMath.effectiveMeleeOrRangedLevel(boostedStr, prayerStrMult, styleBonusStr, 8, voidMult);
        int effAtt = CombatMath.effectiveMeleeOrRangedLevel(boostedAtt, prayerAttMult, styleBonusAtt, 8, voidMult);

        TargetBonus targetGearBonus = salveOrSlayerTargetBonus(style, gear, target, player);

        int maxHit = CombatMath.meleeOrRangedMaxHit(effStr, gear.str(), targetGearBonus.damage);
        int attackRoll = CombatMath.meleeOrRangedAttackRoll(effAtt, gear.attackBonus(style), targetGearBonus.accuracy);

        // Melee demonbane (Emberlight/Arclight +70% acc+dmg; Silver/Darklight
        // +60% dmg-only): the weapon's OWN vs-demon passive — a SEPARATE
        // multiplicative floor step AFTER the salve/slayer slot, so it STACKS with
        // the on-task slayer helm: floor(floor(base*7/6)*17/10).
        // ⚠️ DO NOT change this to highest-wins. IN-GAME VERIFIED 2026-07-07:
        // Emberlight + slayer helm + Piety + super combat on Cerberus = 62 max hit
        // (matches weirdgloop, which stacks). GearScape shows 52 and is WRONG/
        // unreliable for demon numbers — do not chase GearScape parity here. Some
        // demons (Duke Sucellus) partially resist — see resistedDemonbaneFraction.
        DemonbaneWeapon demonbane = gear.demonbaneWeapon();
        if (target.isDemon() && demonbane.appliesTo(style)) {
            int resist = target.demonbaneResistPercent();
            maxHit = (int) resistedDemonbaneFraction(demonbane.damageMult(), resist).applyFloor(maxHit);
            attackRoll = (int) resistedDemonbaneFraction(demonbane.accuracyMult(), resist).applyFloor(attackRoll);
        }

        // Dragon Hunter lance: the weapon's own vs-dragon passive — a SEPARATE
        // multiplicative floor step, stacking with the salve/slayer slot.
        DragonHunterWeapon dh = gear.dragonHunterWeapon();
        if (target.isDragon() && dh.appliesTo(style)) {
            maxHit = (int) dh.damageMult().applyFloor(maxHit);
            attackRoll = (int) dh.accuracyMult().applyFloor(attackRoll);
        }

        // Colossal blade: a flat +2*min(targetSize, 5) max-hit bonus (up to
        // +10), stacking with everything above INCLUDING the slayer/salve
        // slot and demonbane/dragonbane — this is the weapon's own passive,
        // a separate additive term (not a multiplicative floor step), added
        // last so a per-target damage cap (below) applies to the TOTAL,
        // matching how the game's own displayed max hit already includes it.
        if (gear.colossalBlade()) {
            maxHit += 2 * Math.min(target.size(), 5);
        }

        // Keris partisan family: a per-variant damage bonus vs
        // Kalphites/Scarabites (+33% for most variants, but only +15% for
        // "of amascut" — see KerisPartisan's javadoc), plus (for "of
        // breaching" only) +33% accuracy — the weapon's own separate
        // multiplicative step(s), stacking with everything above. The
        // family's OTHER passive (a 1/51 chance to triple the landed
        // damage) is a genuinely different distribution and is applied below
        // via KerisTripleRoll, bypassing the generic finish() path.
        KerisPartisan keris = gear.kerisPartisan();
        boolean kerisApplies = keris != KerisPartisan.NONE && target.attributes().contains(MonsterAttribute.KALPHITE);
        if (kerisApplies) {
            maxHit = (int) keris.damageMultiplier().applyFloor(maxHit);
            if (keris.hasAccuracyBonus()) {
                attackRoll = (int) keris.damageMultiplier().applyFloor(attackRoll);
            }
        }

        // Viggora's chainmace (revenant weapon): +50% accuracy AND damage vs
        // any Wilderness NPC, while charged with ether (assumed — see
        // RevenantWeapon) — the weapon's own separate multiplicative step.
        RevenantWeapon revenant = gear.revenantWeapon();
        if (revenant.appliesTo(style) && target.isWildernessTarget()) {
            maxHit = (int) revenant.damageMult().applyFloor(maxHit);
            attackRoll = (int) revenant.accuracyMult().applyFloor(attackRoll);
        }

        int defenceRoll = CombatMath.npcDefenceRoll(target.defenceLevel(), target.defenceBonus(style));

        // Osmumten's fang (and re-skins/cosmetics): two passives, STAB style
        // only (the double-accuracy-roll passive was restricted to Stab by the
        // 17 Jan 2024 update — see DamageDistribution.fangHitChance/fangAverageDamage
        // for the exact formulas + citation). Neither passive changes maxHit or
        // attackRoll themselves — they change how hitChance/avgDamage are
        // derived from them, so this bypasses the generic finish() path.
        boolean fangApplies = gear.osmumtensFang() && style == CombatStyle.STAB;
        // Scythe of Vitur family: hits 1-3x by target size, each hit's max
        // decaying to 50% of the previous (rounded down) — a genuinely
        // different distribution from a single roll, so this too bypasses
        // the generic finish() path entirely; see ScytheCascade.
        boolean scytheApplies = gear.scytheOfVitur();
        TargetDamage damage = applyTargetDamageRules(maxHit, requirement, gear, style, weaponId);
        maxHit = damage.visibleMaxHit();
        if (fangApplies) {
            return finishFang(damage, attackRoll, defenceRoll, gear.weaponSpeedTicks(), target.hitpoints());
        }
        if (scytheApplies) {
            return ScytheCascade.finish(damage.uncapped, damage.cap, damage.mode, target.size(), attackRoll,
                    defenceRoll, gear.weaponSpeedTicks(), target.hitpoints());
        }
        if (kerisApplies) {
            return KerisTripleRoll.finish(damage.uncapped, damage.cap, damage.mode, attackRoll, defenceRoll,
                    gear.weaponSpeedTicks(), target.hitpoints());
        }

        return finish(damage, attackRoll, defenceRoll, gear.weaponSpeedTicks(), target.hitpoints(), false);
    }

    // ---- Ranged -----------------------------------------------------------------------

    private static DpsResult computeRanged(EquipmentStats gear, PlayerCombat player, Monster target, int weaponId,
                                           MonsterCombatRequirement requirement) {
        int boostedRanged = player.assumeBestPotion()
                ? PotionBoosts.bestRangedBoostedLevel(player.baseRanged())
                : player.boostedRanged();

        OffensivePrayer rangedPrayer = assumed(player, OffensivePrayer.RIGOUR);
        double prayerAttMult = player.assumeBestPrayer() ? rangedPrayer.rangedAttackMult()
                : maxOf(player, OffensivePrayer::rangedAttackMult);
        double prayerStrMult = player.assumeBestPrayer() ? rangedPrayer.rangedStrengthMult()
                : maxOf(player, OffensivePrayer::rangedStrengthMult);

        // Ranged has only one meaningful style bonus (Accurate, +3), applied identically
        // to both the effective-attack and effective-strength calculations.
        int styleBonus = player.stance() == Stance.ACCURATE ? 3 : 0;

        // Elite ranged void boosts max hit (+12.5%) more than accuracy (+10%),
        // so the strength and attack sides take DIFFERENT void multipliers.
        int effStr = CombatMath.effectiveMeleeOrRangedLevel(boostedRanged, prayerStrMult, styleBonus, 8,
                gear.voidSet().rangedStrengthMultiplier());
        int effAtt = CombatMath.effectiveMeleeOrRangedLevel(boostedRanged, prayerAttMult, styleBonus, 8,
                gear.voidSet().rangedAccuracyMultiplier());

        TargetBonus targetGearBonus = salveOrSlayerTargetBonus(CombatStyle.RANGED, gear, target, player);

        DemonbaneWeapon demonbane = gear.demonbaneWeapon();
        boolean demonbaneApplies = target.isDemon() && demonbane.appliesTo(CombatStyle.RANGED);
        DragonHunterWeapon dh = gear.dragonHunterWeapon();
        boolean dragonbaneApplies = target.isDragon() && dh.appliesTo(CombatStyle.RANGED);

        // MAX HIT ONLY (per the wiki DPS calc's "these are additive with slayer
        // only"): when the on-task IMBUED slayer helm/black mask wins the target
        // slot, the ranged demonbane (Scorching bow +30% -> +6/20) and dragonbane
        // (DHCB +25% -> +5/20) damage bonuses fold ADDITIVELY into its 23/20 step
        // — ONE floor of (23+5+6)/20 — instead of applying as separate steps.
        // E.g. Cerberus on-task with a Scorching bow: floor(40 * 29/20) = 58
        // (the wiki's "total damage boost of 45%"), not floor(46 * 13/10) = 59.
        Fraction damageSlot = targetGearBonus.damage;
        boolean foldIntoSlayer = targetGearBonus.imbuedSlayer && (demonbaneApplies || dragonbaneApplies);
        if (foldIntoSlayer) {
            long numerator = 23
                    + (dragonbaneApplies ? additiveTwentieths(dh.damageMult()) : 0)
                    + (demonbaneApplies ? additiveTwentieths(demonbane.damageMult()) : 0);
            damageSlot = new Fraction(numerator, 20);
        }

        int maxHit = CombatMath.meleeOrRangedMaxHit(effStr, gear.rstr(), damageSlot);
        int attackRoll = CombatMath.meleeOrRangedAttackRoll(effAtt, gear.arange(), targetGearBonus.accuracy);

        // Dragon Hunter crossbow — the accuracy side is ALWAYS its own separate
        // multiplicative step; the damage side only when not folded above.
        if (dragonbaneApplies) {
            if (!foldIntoSlayer) {
                maxHit = (int) dh.damageMult().applyFloor(maxHit);
            }
            attackRoll = (int) dh.accuracyMult().applyFloor(attackRoll);
        }

        // Scorching bow (ranged demonbane) — same shape as dragonbane above.
        // Per-monster demonbane resistance (Duke Sucellus) is applied to the
        // separate-step accuracy roll and to the damage step when it is NOT
        // folded into the slayer-helm slot above; a resisted value folded
        // additively into that slot is not documented by the wiki calc, so we
        // do not attempt to fold a resisted bonus (out of scope — no known
        // demon combines on-task-imbued-helm ranged demonbane with resistance).
        if (demonbaneApplies) {
            int resist = target.demonbaneResistPercent();
            if (!foldIntoSlayer) {
                maxHit = (int) resistedDemonbaneFraction(demonbane.damageMult(), resist).applyFloor(maxHit);
            }
            attackRoll = (int) resistedDemonbaneFraction(demonbane.accuracyMult(), resist).applyFloor(attackRoll);
        }

        // Twisted bow: the weapon's own scaling with the TARGET's magic level —
        // also its own multiplicative step (stacks with everything above).
        if (gear.twistedBow()) {
            int accPct = CombatMath.twistedBowAccuracyPercent(target.magicLevel());
            int dmgPct = CombatMath.twistedBowDamagePercent(target.magicLevel());
            attackRoll = (int) new Fraction(accPct, 100).applyFloor(attackRoll);
            maxHit = (int) new Fraction(dmgPct, 100).applyFloor(maxHit);
        }

        // Craw's bow (revenant weapon): +50% accuracy AND damage vs any
        // Wilderness NPC, while charged with ether (assumed — see
        // RevenantWeapon) — the weapon's own separate multiplicative step,
        // stacking with everything above (including a folded slayer helm).
        RevenantWeapon revenant = gear.revenantWeapon();
        if (revenant.appliesTo(CombatStyle.RANGED) && target.isWildernessTarget()) {
            maxHit = (int) revenant.damageMult().applyFloor(maxHit);
            attackRoll = (int) revenant.accuracyMult().applyFloor(attackRoll);
        }

        // Crystal armour set (full ACTIVE helm+body+legs) + an ACTIVE Crystal
        // bow/Bow of Faerdhinen: a conditional weapon+armour combo, not baked
        // into per-piece stats — +15% damage/+30% accuracy, its own separate
        // multiplicative step (see EquipmentStats#crystalSetBonusActive /
        // GearVariants for the active/inactive-piece distinction).
        if (gear.crystalSetBonusActive()) {
            maxHit = (int) new Fraction(23, 20).applyFloor(maxHit); // +15%
            attackRoll = (int) new Fraction(13, 10).applyFloor(attackRoll); // +30%
        }

        int defenceRoll = CombatMath.npcDefenceRoll(target.defenceLevel(), target.drange());

        // Rapid attack style reduces the weapon's attack speed by 1 tick.
        int weaponSpeedTicks = gear.weaponSpeedTicks() - (player.stance() == Stance.RAPID ? 1 : 0);
        weaponSpeedTicks = Math.max(1, weaponSpeedTicks);

        // Charged Tonalztics of Ralos: two full, independent damage rolls per
        // attack (neither halved) — bypasses the generic finish() entirely,
        // same shape as finishFang/finishTwinflame; see TonalzticsDualHit.
        //
        // ORDERING IS LOAD-BEARING, not a style choice: the weapon's OWN
        // range shaping (its 75% per-hit reduction, {@code
        // TonalzticsDualHit.perHitMaxHit}) must run on the RAW, pre-penalty
        // {@code maxHit} FIRST; the target's damage penalty/cap (Corporeal
        // Beast's 0.5 multiplier etc., via applyTargetDamageRules) must run
        // LAST, on that already-reduced per-hit value. {@code
        // floor(floor(x*a)*b)} and {@code floor(floor(x*b)*a)} do not
        // commute in general, and reversing the order (applying the target
        // penalty to the raw max hit, THEN reducing 75%) was a P2 defect —
        // confirmed against the reference weirdgloop/osrs-dps-calc
        // implementation, which builds the weapon's own hit distribution
        // (including its multi-hit/range transform) first and only then
        // layers the Corp penalty as a further transform over that
        // already-formed distribution. E.g. a calculated max of 35 against
        // Corp (0.5x): weapon-first-then-target gives
        // floor(floor(35*3/4)*0.5) = floor(26*0.5) = 13 (correct); the
        // reversed order gives floor(floor(35*0.5)*3/4) = floor(17*3/4) = 12
        // (wrong — one damage point short on every hit). See {@link
        // TonalzticsDualHit#finishFromPerHit}'s javadoc for the full
        // rationale. Running the cap through applyTargetDamageRules on the
        // per-hit value (rather than the raw max hit) is correct and
        // intended — target damage caps are per-hitsplat, not per-weapon.
        if (gear.tonalzticsOfRalosCharged()) {
            int perHit = TonalzticsDualHit.perHitMaxHit(maxHit);
            TargetDamage reduced = applyTargetDamageRules(perHit, requirement, gear, CombatStyle.RANGED, weaponId);
            return TonalzticsDualHit.finishFromPerHit(reduced.uncapped, reduced.cap, reduced.mode, attackRoll,
                    defenceRoll, weaponSpeedTicks, target.hitpoints());
        }
        // UNCHARGED Tonalztics of Ralos: a SINGLE hit over the same reduced
        // 75% range as the charged form's per-hit roll, per the OSRS Wiki:
        // "Uncharged, the weapon hits a target once for 0-75% of the
        // player's maximum ranged hit." Reuses TonalzticsDualHit's own
        // perHitMaxHit helper (the single source of truth for the 75%
        // figure) rather than a second constant. Same ordering fix as the
        // charged branch immediately above (see its comment for the worked
        // example and citation): the weapon's own 75% reduction runs on the
        // RAW max hit first, and only then does applyTargetDamageRules
        // resolve the target's penalty/cap against that reduced value — the
        // target's cap/mode are otherwise left untouched, only the roll's
        // own range shrinks before the cap is (or isn't) applied by the
        // generic finish().
        if (gear.tonalzticsOfRalosUncharged()) {
            int perHit = TonalzticsDualHit.perHitMaxHit(maxHit);
            TargetDamage reduced = applyTargetDamageRules(perHit, requirement, gear, CombatStyle.RANGED, weaponId);
            return finish(reduced, attackRoll, defenceRoll, weaponSpeedTicks, target.hitpoints(), false);
        }
        TargetDamage damage = applyTargetDamageRules(maxHit, requirement, gear, CombatStyle.RANGED, weaponId);
        return finish(damage, attackRoll, defenceRoll, weaponSpeedTicks, target.hitpoints(), false);
    }

    // ---- Magic --------------------------------------------------------------------------

    /** Marker for "derive the base max hit from the worn powered staff at the boosted Magic level". */
    private static final int POWERED_STAFF_SENTINEL = -1;

    /**
     * The Magic-level boost {@link PlayerCombat#assumeBestPotion()} applies for
     * the given {@link PlayerCombat#magicPotionVariant()} — see
     * {@link CombatIcons.BoostPotion} / {@link PotionBoosts}. Only the three
     * magic-boosting variants are meaningful here; a non-magic variant (or
     * {@code null}) falls back to the Imbued heart formula.
     */
    private static int magicPotionBoostedLevel(CombatIcons.BoostPotion variant, int baseLevel) {
        if (variant == CombatIcons.BoostPotion.SATURATED_HEART) {
            return PotionBoosts.saturatedHeartBoostedLevel(baseLevel);
        }
        if (variant == CombatIcons.BoostPotion.ANCIENT_BREW) {
            return PotionBoosts.ancientBrewBoostedLevel(baseLevel);
        }
        return PotionBoosts.imbuedHeartBoostedLevel(baseLevel);
    }

    private static DpsResult computeMagic(EquipmentStats gear, PlayerCombat player, Monster target,
                                          int baseSpellMaxHit, int castSpeedTicks, boolean approximate,
                                          Spell.Element spellElement, int weaponId,
                                          MonsterCombatRequirement requirement, boolean twinflameSecondHit) {
        int boostedMagic = player.assumeBestPotion()
                ? magicPotionBoostedLevel(player.magicPotionVariant(), player.baseMagic())
                : player.boostedMagic();

        if (baseSpellMaxHit == POWERED_STAFF_SENTINEL) {
            // Powered staff: built-in spell max hit scales with the boosted level.
            baseSpellMaxHit = gear.poweredStaff().maxHitAt(boostedMagic);
        }

        OffensivePrayer magicPrayer = assumed(player, OffensivePrayer.AUGURY);
        double prayerAccMult = player.assumeBestPrayer() ? magicPrayer.magicAccuracyMult()
                : maxOf(player, OffensivePrayer::magicAccuracyMult);
        double prayerDamagePercent = player.assumeBestPrayer() ? magicPrayer.magicDamagePercent()
                : maxOf(player, OffensivePrayer::magicDamagePercent);

        int styleBonus = player.stance() == Stance.ACCURATE ? 3 : player.stance() == Stance.LONGRANGE ? 1 : 0;
        double voidMult = gear.voidSet().magicMultiplier();

        int effMagic = CombatMath.effectiveMagicLevel(boostedMagic, prayerAccMult, styleBonus, voidMult);

        boolean salveVsUndead = target.isUndead() && gear.salveType() != SalveType.NONE;
        boolean slayerOnTaskImbued = player.onSlayerTask() && gear.slayerHeadgear().isImbued();
        boolean magicAccuracyBonusApplies = (salveVsUndead && gear.salveType().isImbued()) || slayerOnTaskImbued;
        Fraction accuracyTargetBonus = magicAccuracyBonusApplies ? new Fraction(23, 20) : Fraction.ONE;

        int accuracyRoll = CombatMath.magicAccuracyRoll(effMagic, gear.amagic(), accuracyTargetBonus);
        int defenceRoll = CombatMath.npcDefenceRoll(target.magicLevel(), target.dmagic());

        // Elemental weakness (e.g. frost dragons vs Fire spells): a per-monster
        // percent, added straight into the magic-damage percent when the cast
        // spell's element matches the monster's weakness element - matching
        // weirdgloop/osrs-dps-calc semantics. Spells with no element (Iban
        // Blast, Magic Dart/powered staves, god spells, all Ancient Magicks -
        // spellElement is null for those) never get this bonus, and a monster
        // with no weakness (weaknessElement() null) never grants it.
        // It is NOT folded into the magic-damage percent below; it is a separate
        // additive term applied last (see the elemental-weakness step at the end).
        boolean weaknessApplies = spellElement != null
                && target.weaknessElement() != null
                && target.weaknessElement().equals(spellElement.name());

        double totalDamagePercent = gear.mdmg()
                + gear.voidSet().eliteMagicDamageBonusPercent()
                + (target.isUndead() ? gear.salveType().magicDamagePercent() : 0.0)
                + prayerDamagePercent;
        int primaryDamage = CombatMath.magicPrimaryDamage(baseSpellMaxHit, totalDamagePercent);

        // Slayer on-task +15% never stacks with an active Salve bonus (per wiki).
        boolean slayerPreHitRollApplies = slayerOnTaskImbued && !salveVsUndead;
        int maxHit = CombatMath.magicPreHitRoll(primaryDamage, slayerPreHitRollApplies);

        // Dragon hunter wand — the weapon's own vs-dragon passive, a separate
        // multiplicative floor step stacking with the salve/slayer slot (see computeRanged).
        DragonHunterWeapon dh = gear.dragonHunterWeapon();
        if (target.isDragon() && dh.appliesTo(CombatStyle.MAGIC)) {
            maxHit = (int) dh.damageMult().applyFloor(maxHit);
            accuracyRoll = (int) dh.accuracyMult().applyFloor(accuracyRoll);
        }

        // Elemental weakness — the FINAL damage modifier: a separate additive term,
        // floor(baseSpellMaxHit * severity%), computed from the base spell max hit
        // and floored independently, then added on. This is weirdgloop/osrs-dps-calc's
        // exact stage (maxHit += trunc(baseMax * severity/100)) and the OSRS Wiki
        // "Maximum magic hit" (two floors, not one — folding it into the damage
        // percent above over-/under-shoots by 1 in ~12% of gear/level combos).
        if (weaknessApplies) {
            maxHit += CombatMath.elementalWeaknessBonus(baseSpellMaxHit, target.weaknessSeverity());
        }

        // Charged elemental tome (fire/water/earth): +10% damage vs NPCs to the
        // matching-element standard-spellbook spell. weirdgloop's MAX_HIT_TOME
        // step (floor(maxHit * 11/10)) is the FINAL magic-damage modifier —
        // applied AFTER the elemental-weakness bonus above, as its own floored
        // multiplicative step. spellElement is null for powered staves / Ancient
        // / non-elemental casts, so those never receive it.
        if (spellElement != null && gear.tome().boosts(spellElement)) {
            maxHit = (int) new Fraction(11, 10).applyFloor(maxHit);
        }

        // Thammaron's sceptre (revenant weapon): +50% accuracy AND damage vs
        // any Wilderness NPC, while charged with ether (assumed — see
        // RevenantWeapon) — the weapon's own separate multiplicative step.
        RevenantWeapon revenant = gear.revenantWeapon();
        if (revenant.appliesTo(CombatStyle.MAGIC) && target.isWildernessTarget()) {
            maxHit = (int) revenant.damageMult().applyFloor(maxHit);
            accuracyRoll = (int) revenant.accuracyMult().applyFloor(accuracyRoll);
        }

        TargetDamage damage = applyTargetDamageRules(maxHit, requirement, gear, CombatStyle.MAGIC, weaponId);
        maxHit = damage.visibleMaxHit();
        if (twinflameSecondHit) {
            return finishTwinflame(damage, accuracyRoll, defenceRoll, castSpeedTicks, target.hitpoints());
        }
        return finish(damage, accuracyRoll, defenceRoll, castSpeedTicks, target.hitpoints(), approximate);
    }

    /**
     * The final max-hit step, shared by all three styles: applies the given,
     * already-resolved {@link MonsterCombatRequirement}'s damage penalty then
     * its damage cap, in that order — see {@link TargetDamageRule}. A
     * {@code null} req (the overwhelming majority of monsters) is unaffected:
     * both {@link TargetDamageRule} methods return their neutral values for a
     * {@code null} requirement.
     *
     * <p><b>{@code req} is never re-resolved here</b> — resolution happens
     * exactly once, before this method is ever called, so a plain {@code
     * null} unambiguously means "this target has no requirement" and nothing
     * else. There is no third "not yet resolved" state to confuse it with:
     * the public {@code compute(...)} overloads that do NOT accept a {@link
     * MonsterCombatRequirement} parameter (the original API) look it up
     * themselves via {@link #resolveRequirement} — exactly the {@code
     * MonsterCombatRequirementRepository.getInstance().forMonster(target.lookupName())}
     * call this method used to make internally — and pass that (possibly
     * {@code null}) result down through {@code computeNonMagic}/{@code
     * computeMelee}/{@code computeRanged}/{@code computeMagic} to here
     * unchanged; the newer overloads that DO accept the parameter pass the
     * caller's value straight through, likewise unchanged. Overload dispatch
     * (arity/type, decided at the call site, not at runtime) is therefore the
     * whole "sentinel": which family of overload was invoked is what tells
     * "resolve it yourself" apart from "here is the resolved answer, even if
     * that answer is null" — no in-band marker value is needed, and none of
     * {@code MonsterCombatRequirement}'s real states is stolen for the
     * purpose.
     *
     * <p>Deliberately does NOT collapse a {@code REROLL} cap into a lower
     * {@code uncapped} value here, tempting as that shortcut looks for the
     * generic melee/ranged/magic path (see {@link #finish}, where it IS
     * exact). {@link #finishFang} needs the true, uncapped max hit AND the
     * cap AND the mode kept separate — Osmumten's fang compresses its roll
     * from the TRUE max, not from a value that has already had the cap
     * folded into it, exactly the defect the fang's {@code CLAMP} path was
     * fixed for in review; collapsing here would silently reintroduce the
     * same defect for {@code REROLL} instead. {@link TargetDamage} therefore
     * carries the mode, and each of {@link #finish}/{@link #finishFang}
     * decides for itself what to do with it.
     */
    /**
     * <b>Known limitation — the damage PENALTY is applied to the endpoint, not
     * to the distribution.</b> {@code afterPenalty} below scales the max hit and
     * every downstream {@code finish*} then models a uniform roll over {@code
     * 0..afterPenalty}. The game instead scales each ROLLED hit, and scaling a
     * uniform roll does not yield a uniform roll: for a {@code 0..26} roll under
     * Corporeal Beast's {@code 0.5x}, the real outcome is {@code P(k)=2/27} for
     * {@code k} in {@code 0..12} and {@code P(13)=1/27} (mean {@code 169/27 ~
     * 6.2593}), where this models a uniform {@code 0..13} (mean {@code 6.5}) —
     * about 3.85% high.
     *
     * <p>The displayed max hit is unaffected and correct; what is overstated is
     * average damage, and hence DPS, overkill and TTK, against every {@code
     * DAMAGE_PENALTY} target.
     *
     * <p><b>Deliberately not fixed piecemeal.</b> This is the single shared site
     * every style routes through, so the approximation applies to ALL weapons
     * equally. Correcting it for one weapon would compute that weapon on a
     * different model from everything it is ranked against, which is worse than
     * a uniform approximation — the same reasoning that split the spec-weapon
     * damage-cap gap out whole. A real fix transforms the distribution here, for
     * everything, and must also settle penalty-versus-cap ordering (the
     * reference applies the Corp penalty BEFORE other limiters). Pinned by
     * {@code TargetDamagePenaltyDistributionLimitationTest} (PR #24 round 12).
     */
    private static TargetDamage applyTargetDamageRules(int maxHit, MonsterCombatRequirement req, EquipmentStats gear,
                                                       CombatStyle style, int weaponId) {
        int afterPenalty = (int) Math.floor(maxHit * TargetDamageRule.damageMultiplierFor(req, weaponId, style));
        int cap = TargetDamageRule.maxHitCapFor(req, gear, style, weaponId);
        MonsterCombatRequirement.CapMode mode = TargetDamageRule.capModeFor(req);
        return new TargetDamage(afterPenalty, cap, mode);
    }

    /**
     * A max hit split into the roll's real (uncapped) range, the per-hitsplat
     * cap, and the {@link MonsterCombatRequirement.CapMode} it applies with —
     * three separate things are needed because none of them is
     * interchangeable with another, in BOTH modes. Under {@code CLAMP} the
     * roll stays {@code 0..uncapped} and everything above {@code cap} lands
     * ON the cap — collapsing {@code uncapped} and {@code cap} into one
     * number loses the probability mass that piles up there (see {@link
     * DamageDistribution#cappedAverageDamage}). Under {@code REROLL} the
     * distribution's SHAPE reduces to a plain {@code 0..cap} roll, but its
     * mean still depends on {@code uncapped}: the ordinary "rolled 0 becomes
     * 1" bump belongs to the ORIGINAL {@code 0..uncapped} roll (see {@link
     * DamageDistribution#rerolledAverageDamage}'s {@code 1/(uncapped+1)}
     * term) — collapsing to just {@code cap} and feeding it through the
     * ordinary {@link DamageDistribution#averageDamage} would apply that
     * bump a second time, to the re-roll's own genuine zero, and overstate
     * the mean. {@link #finishFang} needs the same three kept apart for a
     * different reason on top: it must compress its own {@code lo..hi} roll
     * from the TRUE max, not from a value the cap has already been folded
     * into. Both numbers and the mode therefore travel together all the way
     * to whichever {@code finish*} method consumes them.
     */
    private static final class TargetDamage {
        /** Max hit after any damage penalty, before any cap — the roll's real range. */
        final int uncapped;
        /** Per-hitsplat ceiling, or {@code -1} for none. */
        final int cap;
        /** How the cap applies; meaningless when {@link #cap} is {@code -1}. */
        final MonsterCombatRequirement.CapMode mode;

        TargetDamage(int uncapped, int cap, MonsterCombatRequirement.CapMode mode) {
            this.uncapped = uncapped;
            this.cap = cap;
            this.mode = mode;
        }

        /** What the player actually sees as their max hit. */
        int visibleMaxHit() {
            return cap >= 0 ? Math.min(uncapped, cap) : uncapped;
        }

        boolean isCapped() {
            return cap >= 0 && cap < uncapped;
        }
    }

    // ---- Shared helpers -----------------------------------------------------------------

    /**
     * The single non-stacking salve/slayer target-bonus slot, split into its
     * accuracy and damage components. {@code imbuedSlayer} records that the
     * WINNER is the on-task imbued slayer helm/black mask — the only case the
     * ranged max hit folds demonbane/dragonbane additively into (see
     * computeRanged).
     */
    private static final class TargetBonus {
        static final TargetBonus NONE = new TargetBonus(Fraction.ONE, Fraction.ONE, false);

        final Fraction accuracy;
        final Fraction damage;
        final boolean imbuedSlayer;

        TargetBonus(Fraction accuracy, Fraction damage, boolean imbuedSlayer) {
            this.accuracy = accuracy;
            this.damage = damage;
            this.imbuedSlayer = imbuedSlayer;
        }
    }

    /**
     * Target-specific gear-bonus slot shared by max hit and attack roll for
     * melee/ranged. ONE non-stacking slot holding Salve (vs undead) and the
     * on-task Slayer helm/black mask — the strongest effect wins (matching the
     * wiki DPS calc's if/else chain, where Salve takes precedence over the
     * helm; Salve's fractions also dominate numerically, so highest-wins and
     * the documented "salve wins over slayer" coincide).
     *
     * <p>Demonbane, Dragon Hunter weapons and the Twisted bow do NOT live in
     * this slot — each is the weapon's own passive, applied as a separate
     * multiplicative floor step in computeMelee/computeRanged (stacking with
     * this slot), with one exception: the ranged MAX HIT folds demonbane/
     * dragonbane damage additively into an on-task imbued helm's 23/20 (see
     * computeRanged; wiki calc: "these are additive with slayer only").
     */
    private static TargetBonus salveOrSlayerTargetBonus(CombatStyle style, EquipmentStats gear, Monster target, PlayerCombat player) {
        TargetBonus best = TargetBonus.NONE;

        if (target.isUndead()) {
            Fraction salve = style.isMelee() ? gear.salveType().meleeBonus() : gear.salveType().rangedBonus();
            best = stronger(best, new TargetBonus(salve, salve, false));
        }
        if (player.onSlayerTask() && gear.slayerHeadgear().wornAtAll()) {
            boolean imbued = gear.slayerHeadgear().isImbued();
            Fraction slayer = style.isMelee()
                    ? new Fraction(7, 6)
                    : (imbued ? new Fraction(23, 20) : Fraction.ONE); // ranged: imbued only
            best = stronger(best, new TargetBonus(slayer, slayer, imbued && !slayer.isOne()));
        }
        return best;
    }

    /**
     * A bonus fraction's additive contribution to the imbued slayer helm's
     * numerator, in twentieths: e.g. the Scorching bow's 13/10 (+30%) is +6,
     * the DHCB's 5/4 (+25%) is +5 — exactly the wiki calc's
     * {@code numerator += 5/6} constants on top of the helm's 23/20. Exact for
     * every wired bonus (both divide evenly); revisit if a bonus whose percent
     * is not a multiple of 5 ever needs folding.
     */
    private static long additiveTwentieths(Fraction bonus) {
        return (bonus.numerator - bonus.denominator) * 20 / bonus.denominator;
    }

    /**
     * Scales a demonbane bonus fraction down for a monster's demonbane
     * resistance: the bonus's excess-over-1 (its "BONUS portion", e.g.
     * Emberlight's 17/10 is 1 + 7/10) is reduced by {@code resistPercent}%,
     * so the final multiplier is {@code 1 + excess * (1 - resistPercent/100)}.
     * Duke Sucellus (30% resistance): Emberlight's documented +70% becomes
     * +49% (0.7 * 0.7 = 0.49), i.e. 149/100 instead of 17/10 — per the OSRS
     * Wiki ("an emberlight would only have 49% increased damage and accuracy
     * against him rather than 70%"). {@code resistPercent} of 0 (the default
     * for almost every demon) returns the bonus unchanged.
     */
    private static Fraction resistedDemonbaneFraction(Fraction bonus, int resistPercent) {
        if (resistPercent <= 0 || bonus.isOne()) {
            return bonus;
        }
        // excess = bonus - 1, as a fraction with the same denominator as bonus.
        long excessNumerator = bonus.numerator - bonus.denominator;
        // scaledExcess = excess * (100 - resistPercent) / 100
        long numerator = bonus.denominator * 100L + excessNumerator * (100L - resistPercent);
        long denominator = bonus.denominator * 100L;
        return new Fraction(numerator, denominator);
    }

    /** The stronger of two slot candidates: higher damage multiplier wins, accuracy breaks ties. */
    private static TargetBonus stronger(TargetBonus a, TargetBonus b) {
        double da = a.damage.asDouble();
        double db = b.damage.asDouble();
        if (db > da) {
            return b;
        }
        if (db == da && b.accuracy.asDouble() > a.accuracy.asDouble()) {
            return b;
        }
        return a;
    }

    private static double maxOf(PlayerCombat player, java.util.function.ToDoubleFunction<OffensivePrayer> extractor) {
        double best = 1.0;
        for (OffensivePrayer prayer : player.activePrayers()) {
            best = Math.max(best, extractor.applyAsDouble(prayer));
        }
        return best;
    }

    /**
     * The prayer the {@code assumeBestPrayer} branch applies: the player's
     * explicit pick, else {@code fallback} (the style's top-tier prayer, which
     * is what this branch hardcoded before the pick existed).
     */
    private static OffensivePrayer assumed(PlayerCombat player, OffensivePrayer fallback) {
        return player.assumedPrayer() != null ? player.assumedPrayer() : fallback;
    }

    private static DpsResult finish(int maxHit, int attackRoll, int defenceRoll, int weaponSpeedTicks,
                                    int targetHitpoints, boolean baseEstimate) {
        return finish(new TargetDamage(maxHit, -1, MonsterCombatRequirement.CapMode.CLAMP), attackRoll, defenceRoll,
            weaponSpeedTicks, targetHitpoints, baseEstimate);
    }

    /**
     * Applies a {@link TargetDamage}'s cap (if any) to the GENERIC
     * uniform-{@code 0..maxHit} roll used by every style except Osmumten's
     * fang (see {@link #finishFang} for that one). Uncapped: the ordinary
     * formulas. {@code CLAMP}: the roll stays {@code 0..uncapped} with excess
     * mass piled on the cap ({@code cappedAverageDamage}/
     * {@code cappedExpectedOverkill}). {@code REROLL}: a re-roll into
     * {@code 0..cap} of a uniform {@code 0..M} roll is EXACTLY a uniform
     * {@code 0..cap} roll — BUT that equivalence is about the shape of the
     * distribution only, not the "rolled 0 becomes 1" bump: the bump belongs
     * to the ORIGINAL {@code 0..M} roll (it happens first), and the re-roll
     * into {@code 0..cap} is a separate, later step with its own genuine
     * zero. Feeding the cap into {@link DamageDistribution#averageDamage}/
     * {@link DamageDistribution#expectedOverkill} (as if it were a plain {@code
     * 0..cap} weapon roll) therefore overstates the mean by the bump's
     * {@code 1/(cap+1)} term where the correct term is {@code 1/(M+1)} — at
     * Verzik's ranged/magic cap of 3 that reports 1.75 instead of the true
     * ~1.524, a 14.8% overstatement (the same over-general-equivalence
     * mistake the fang's re-rolled formulas were built to avoid, caught in
     * the same review). {@link DamageDistribution#rerolledAverageDamage}/
     * {@code rerolledExpectedOverkill} are the exact, zero-aware versions.
     * Overkill always uses the SAME distribution as avgDamage in every
     * branch, since TTK is derived from both together.
     */
    private static DpsResult finish(TargetDamage damage, int attackRoll, int defenceRoll, int weaponSpeedTicks,
                                    int targetHitpoints, boolean baseEstimate) {
        int maxHit = damage.visibleMaxHit();
        double hitChance = CombatMath.hitChance(attackRoll, defenceRoll);
        double avgDamage;
        double overkill;
        if (!damage.isCapped()) {
            avgDamage = DamageDistribution.averageDamage(hitChance, maxHit);
            overkill = DamageDistribution.expectedOverkill(maxHit, targetHitpoints);
        } else if (damage.mode == MonsterCombatRequirement.CapMode.REROLL) {
            avgDamage = DamageDistribution.rerolledAverageDamage(hitChance, damage.uncapped, damage.cap);
            overkill = DamageDistribution.rerolledExpectedOverkill(damage.uncapped, damage.cap, targetHitpoints);
        } else {
            avgDamage = DamageDistribution.cappedAverageDamage(hitChance, damage.uncapped, damage.cap);
            overkill = DamageDistribution.cappedExpectedOverkill(damage.uncapped, damage.cap, targetHitpoints);
        }
        double dps = CombatMath.dps(avgDamage, weaponSpeedTicks);
        // TTK must account for overkill: the killing blow rolls past 0 HP, wasting
        // `overkill` HP of damage, so effective damage per kill is HP + overkill.
        // By Wald's identity E[TTK] = (HP + E[overkill]) / DPS exactly — the naive
        // HP/DPS understates it (e.g. Cerberus 57.3s vs GearScape's overkill-aware 59s).
        double ttkSeconds = dps > 0 ? (targetHitpoints + overkill) / dps : 0.0;
        return new DpsResult(maxHit, hitChance, dps, avgDamage, ttkSeconds, overkill, baseEstimate);
    }

    /**
     * Osmumten's fang variant of {@link #finish}: uses the fang's own
     * double-accuracy-roll hit chance and compressed-damage-roll average
     * damage (see {@link DamageDistribution#fangHitChance} /
     * {@link DamageDistribution#fangAverageDamage} for the formulas +
     * citation). {@code maxHit} in the returned {@link DpsResult} is left as
     * the TRUE (unshrunk) max hit, matching how the wiki/GearScape display it
     * — only the roll range feeding avgDamage is compressed.
     *
     * <p>Uncapped: overkill/TTK reuse the generic uniform-0..maxHit overkill
     * model on the true max hit (not the shrunk range) as an approximation —
     * modelling overkill exactly for the fang's UNCAPPED compressed
     * distribution is out of scope here (Tier B, not requested); this only
     * matters for the very last hit of a kill and the effect is small.
     *
     * <p><b>A capped target caps the fang's compressed roll, not the max hit it
     * is compressed from.</b> The cap therefore cannot be folded into {@code
     * maxHit} before this method is reached — it has to travel alongside the
     * true max (and the {@link MonsterCombatRequirement.CapMode}), which is
     * why this takes the whole {@link TargetDamage} rather than an
     * already-collapsed int. {@code CLAMP}: {@link
     * DamageDistribution#cappedFangAverageDamage} / {@code
     * cappedFangExpectedOverkill} — both against the fang's own
     * compressed-and-clamped distribution, so the average and the overkill
     * cannot disagree (an earlier version of this ran overkill on the
     * GENERIC capped distribution instead, which silently reported a
     * different TTK than the average implied — fixed in review).
     * {@code REROLL}: unlike the generic path, this is NOT algebraically a
     * lower max hit — the fang would re-derive a different, much narrower
     * compression from a lowered max — so it needs its own EXACT formula,
     * {@link DamageDistribution#rerolledFangAverageDamage} / {@code
     * rerolledFangExpectedOverkill}, built from the same {@code lo..hi}
     * distribution for both, for exactly the same reason.
     */
    private static DpsResult finishFang(TargetDamage damage, int attackRoll, int defenceRoll, int weaponSpeedTicks,
                                        int targetHitpoints) {
        double hitChance = DamageDistribution.fangHitChance(attackRoll, defenceRoll);
        double avgDamage;
        double overkill;
        if (!damage.isCapped()) {
            avgDamage = DamageDistribution.fangAverageDamage(hitChance, damage.uncapped);
            overkill = DamageDistribution.expectedOverkill(damage.uncapped, targetHitpoints);
        } else if (damage.mode == MonsterCombatRequirement.CapMode.REROLL) {
            avgDamage = DamageDistribution.rerolledFangAverageDamage(hitChance, damage.uncapped, damage.cap);
            overkill = DamageDistribution.rerolledFangExpectedOverkill(damage.uncapped, damage.cap, targetHitpoints);
        } else {
            avgDamage = DamageDistribution.cappedFangAverageDamage(hitChance, damage.uncapped, damage.cap);
            overkill = DamageDistribution.cappedFangExpectedOverkill(damage.uncapped, damage.cap, targetHitpoints);
        }
        double dps = CombatMath.dps(avgDamage, weaponSpeedTicks);
        double ttkSeconds = dps > 0 ? (targetHitpoints + overkill) / dps : 0.0;
        return new DpsResult(damage.visibleMaxHit(), hitChance, dps, avgDamage, ttkSeconds, overkill, false);
    }

    /**
     * Twinflame staff variant of {@link #finish}: adds the exact expected
     * second-hit damage (see {@link TwinflameSecondHit} for the derivation
     * and why {@code E[floor(0.4*D)] != 0.4*E[D]}) to the average damage used
     * for DPS, and uses {@link TwinflameSecondHit}'s combined-hitsplat model
     * for overkill/TTK — see that class's javadoc for the explicit modelling
     * choice and its one documented, negligible simplification (the killing
     * blow's second hitsplat is still counted in full even when the first
     * alone would already be lethal).
     *
     * <p>Both the average AND the overkill are migrated together here
     * deliberately: reflecting the second hit in only one of the two would
     * leave the reported DPS and TTK disagreeing with each other for every
     * Twinflame-eligible cast.
     *
     * <p>Mirrors {@link #finish}'s three-way switch on {@link
     * TargetDamage#mode} rather than the two-way {@code isCapped()} check
     * this used to branch on: a {@code REROLL}-capped target (e.g. Verzik
     * Vitur phase 1's ranged/magic cap of 3) was previously silently routed
     * through the {@code cappedXxx} (i.e. {@code CLAMP}) helpers for all
     * three terms, piling excess probability onto the cap instead of
     * re-rolling it into {@code 0..cap} — the exact same over-general
     * "REROLL is just a clamp" mistake {@link #finish}/{@link #finishFang}
     * were already fixed for. {@link TwinflameSecondHit#rerolledSecondHitAverage}/
     * {@code rerolledCombinedExpectedOverkill} are the exact, zero-aware
     * REROLL replacements, built from the same distribution {@link
     * DamageDistribution#rerolledAverageDamage}/{@code
     * rerolledExpectedOverkill} use so all three terms cannot disagree.
     */
    private static DpsResult finishTwinflame(TargetDamage damage, int attackRoll, int defenceRoll, int castSpeedTicks,
                                              int targetHitpoints) {
        int maxHit = damage.visibleMaxHit();
        double hitChance = CombatMath.hitChance(attackRoll, defenceRoll);
        double firstHitAvg;
        double secondHitAvg;
        double overkill;
        if (!damage.isCapped()) {
            firstHitAvg = DamageDistribution.averageDamage(hitChance, maxHit);
            secondHitAvg = TwinflameSecondHit.secondHitAverage(hitChance, maxHit);
            overkill = TwinflameSecondHit.combinedExpectedOverkill(maxHit, targetHitpoints);
        } else if (damage.mode == MonsterCombatRequirement.CapMode.REROLL) {
            firstHitAvg = DamageDistribution.rerolledAverageDamage(hitChance, damage.uncapped, damage.cap);
            secondHitAvg = TwinflameSecondHit.rerolledSecondHitAverage(hitChance, damage.uncapped, damage.cap);
            overkill = TwinflameSecondHit.rerolledCombinedExpectedOverkill(damage.uncapped, damage.cap, targetHitpoints);
        } else {
            firstHitAvg = DamageDistribution.cappedAverageDamage(hitChance, damage.uncapped, damage.cap);
            secondHitAvg = TwinflameSecondHit.cappedSecondHitAverage(hitChance, damage.uncapped, damage.cap);
            overkill = TwinflameSecondHit.cappedCombinedExpectedOverkill(damage.uncapped, damage.cap, targetHitpoints);
        }
        double avgDamage = firstHitAvg + secondHitAvg;
        double dps = CombatMath.dps(avgDamage, castSpeedTicks);
        double ttkSeconds = dps > 0 ? (targetHitpoints + overkill) / dps : 0.0;
        return new DpsResult(maxHit, hitChance, dps, avgDamage, ttkSeconds, overkill, false);
    }
}

package com.ospulse.combat;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * One curated "don't forget" consumables/gear reminder for a monster — e.g.
 * "Zulrah poisons you — bring antivenom." Text is the payload; the optional
 * {@link #equipmentItemIds()} only ever names items that are genuinely
 * equipment and therefore verifiable against {@link EquipmentIndexRepository}
 * (a ring, a shield). Inventory consumables (potions) are named in
 * {@link #note()} prose, and — when the id has been verified against the
 * runelite-api jar's {@code ItemID} constants, not the equipment index — also
 * carried as an id in {@link #consumableItemIds()}, a separately-validated
 * field because {@code equipment_index.min.json} indexes equipment alone. See
 * {@link MonsterConsumablesRepository} for how this is loaded/looked up and
 * that class's bundled resource README for provenance.
 */
public final class MonsterConsumablesReminder {
    private final String note;
    private final Set<Integer> equipmentItemIds;
    private final Set<Integer> consumableItemIds;

    MonsterConsumablesReminder(String note, Set<Integer> equipmentItemIds, Set<Integer> consumableItemIds) {
        this.note = note == null ? "" : note;
        this.equipmentItemIds = equipmentItemIds == null || equipmentItemIds.isEmpty()
            ? Collections.emptySet()
            : Collections.unmodifiableSet(new LinkedHashSet<>(equipmentItemIds));
        this.consumableItemIds = consumableItemIds == null || consumableItemIds.isEmpty()
            ? Collections.emptySet()
            : Collections.unmodifiableSet(new LinkedHashSet<>(consumableItemIds));
    }

    /** The advisory text shown verbatim in the panel — the whole payload for a consumables-only reminder. */
    public String note() {
        return note;
    }

    /**
     * Optional equipment item ids relevant to this reminder (e.g. a
     * dragonfire shield, an anti-dragon shield) — never a potion/consumable
     * id, since those cannot be verified against the equipment index. Empty
     * for a reminder with no equipment component.
     */
    public Set<Integer> equipmentItemIds() {
        return equipmentItemIds;
    }

    /**
     * Optional inventory consumable item ids relevant to this reminder (a
     * potion dose, e.g. antivenom+ or antipoison) — verified against the
     * runelite-api jar's {@code net.runelite.api.gameval.ItemID} constants,
     * NOT the equipment index (potions aren't equipment). Empty for a
     * reminder with no verified consumable ids.
     */
    public Set<Integer> consumableItemIds() {
        return consumableItemIds;
    }
}

