/**
 * OSPulse — accurate OSRS session profit + net-worth tracker.
 *
 * <p>Owns the RuneLite lifecycle and wiring: it feeds live game events into the
 * {@link SessionTracker} (which drives the pure session/GE/XP engines) and
 * renders the result in {@link OSPulsePanel}.
 */
@Slf4j
@PluginDescriptor(
	// BuildInfo.PLUGIN_NAME is the committed default "OSPulse" (Plugin Hub
	// build); a local -Pdev sideloaded testing build overrides it with
	// "OSPulse (dev)" (see build.gradle) so the two are distinguishable in
	// the client's plugin list.
	name = BuildInfo.PLUGIN_NAME,
	description = "Accurate session profit (banking-aware), loot feed, net worth, XP and GE "
		+ "flip P&L, valued with RuneLite's GE prices.",
	tags = {"profit", "loot", "wealth", "gp", "session", "tracker", "ge", "flipping", "xp"}
)
// The "Show in bank" feature drives RuneLite's Bank Tags to filter the open
// bank to the optimiser's recommended items. BankTagsService/TagManager are
// bound inside the banktags plugin's own injector, so without declaring the
// dependency they inject as null and the feature silently no-ops.
@PluginDependency(BankTagsPlugin.class)
// The loot feed consumes Loot Tracker's LootReceived events to NAME a drop's
// source; declaring the dependency makes RuneLite start that plugin first so
// early kills are not missed. A nicety, not a requirement: the feed derives the
// loot itself from the inventory diff (see SessionTracker#attributeDiffLoot), so
// with Loot Tracker off the drops still appear, just unnamed.
@PluginDependency(LootTrackerPlugin.class)
public class OSPulsePlugin extends Plugin
{
	@Inject
	private OSPulseConfig config;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private net.runelite.client.game.SpriteManager spriteManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private net.runelite.client.callback.ClientThread clientThread;

	@com.google.inject.Inject(optional = true)
	private net.runelite.client.plugins.banktags.BankTagsService bankTagsService;

	@com.google.inject.Inject(optional = true)
	private net.runelite.client.plugins.banktags.TagManager tagManager;

	/** Mirrors {@link OSPulseConfig#ironmanOwnedOnly()}'s {@code keyName} — see {@link #checkIronmanAutoDetect()} and {@link IronmanOwnedOnlyStore#KEY}. */
	private static final String IRONMAN_OWNED_ONLY_KEY = IronmanOwnedOnlyStore.KEY;
	/** Per-RS-profile "have I already evaluated auto-detect for this profile" bookkeeping key — see {@link #checkIronmanAutoDetect()}. */
	private static final String IRONMAN_AUTO_DETECT_SEEN_KEY = "ironmanOwnedOnlyAutoDetectSeen";

	private SessionTracker tracker;
	private OSPulsePanel panel;
	private PriceTrendService priceTrendService;
	private NavigationButton navButton;
	private com.ospulse.integration.BankRecommendationHighlighter bankHighlighter;
	/** Owns every {@code ironmanOwnedOnly} read/write — the per-account merged-read scheme's reads/writes/mirror (issue #11 leak fix). */
	private IronmanOwnedOnlyStore ownedOnlyStore;

	/** Last observed bank-interface-open state, to fire transitions once. */
	private boolean lastBankOpen;

	/**
	 * Set on every {@code LOGGED_IN} transition; {@link #onGameTick} is where
	 * {@link #checkIronmanAutoDetect()} actually runs (see that method's
	 * javadoc for why account state can't be read on the LOGGED_IN event
	 * itself) — but only CLEARS this flag once {@link #checkIronmanAutoDetect()}
	 * reports it actually ran (P2 fix): if the first post-login tick still
	 * sees {@code Client.getAccountHash() == -1}, this stays armed and
	 * {@link #checkIronmanAutoDetect()} is retried on every subsequent tick
	 * until account state is ready, rather than being silently dropped for
	 * the whole session.
	 */
	private boolean pendingIronmanAutoDetect;

	@Override
	protected void startUp()
	{
		// Seed the shared Gson holder FIRST: the static combat repositories
		// parse their bundled JSON through the client's injected Gson (the
		// Plugin Hub forbids fresh instances), and anything below may trigger
		// their lazy load.
		BundledGson.set(gson);

		tracker = new SessionTracker(client, itemManager, config, configManager, gson);

		ownedOnlyStore = new IronmanOwnedOnlyStore(configManager);

		priceTrendService = new PriceTrendService(okHttpClient, config, gson);

		bankHighlighter = new com.ospulse.integration.BankRecommendationHighlighter(
			bankTagsService, tagManager, configManager, clientThread);
		if (bankTagsService == null || tagManager == null)
		{
			// With @PluginDependency(BankTagsPlugin) these should always resolve;
			// log loudly if not so the inert "Show in bank" is diagnosable.
			log.warn("OSPulse: Bank Tags unavailable (bankTagsService={}, tagManager={}) — 'Show in bank' will be inert",
				bankTagsService != null, tagManager != null);
		}

		RuneLiteItemValuation valuation = new RuneLiteItemValuation(itemManager);
		// Precomputes BOTH prices and tradeability on the client thread
		// (ItemManager.getItemComposition/isTradeable assert it) into plain
		// collections, so the background optimiser search never touches the
		// ItemManager itself. Tradeability matters because getItemPrice
		// "prices" some untradeables via ItemMapping's tradeable proxies
		// (e.g. trouver-locked items cost the Trouver parchment's ~1m) — an
		// unowned untradeable must be unpurchasable, whatever it "costs".
		GearSection.OptimizerPriceResolver optimizerPriceResolver = (ids, cb) -> clientThread.invoke(() ->
		{
			java.util.Map<Integer, Long> m = new java.util.HashMap<>();
			java.util.Set<Integer> untradeable = new java.util.HashSet<>();
			for (int id : ids)
			{
				if (!valuation.isTradeable(id))
				{
					// Curated exception: a few best-in-slot items are untradeable
					// but assembled from a tradeable component (e.g. an Avernic
					// defender is made from a tradeable Avernic defender hilt on a
					// dragon defender). Price such an item at its component's GE
					// cost so the optimiser can still recommend it; the readout
					// keeps the assembled item's own name.
					Integer component = com.ospulse.combat.AssembledItemComponents.priceSourceComponent(id);
					if (component != null && valuation.isTradeable(component))
					{
						long cv = valuation.unitValue(component);
						if (cv > 0)
						{
							m.put(id, cv);
							continue;
						}
					}
					untradeable.add(id);
					continue;
				}
				long v = valuation.unitValue(id);
				if (v > 0)
				{
					m.put(id, v);
				}
			}
			// Per-item real gp "risk value" for the expensive-item wilderness/
			// PvP cap ONLY (see GearOptimizer.Request.Builder#riskValueSource) —
			// deliberately independent of the budget map `m` above: a
			// tradeable item's risk value is its own GE price; an untradeable
			// item's risk value is the summed GE price of the tradeable
			// component(s) it represents (Barrows pieces, imbued rings, Doom-
			// of-Mokhaiotl weapons, etc.), an AssembledItemComponents component
			// price (e.g. Avernic defender), or — as a last resort, for rare
			// untradeables with no tradeable equivalent anywhere else, and never
			// for a free-reobtainable id — the Trouver parchment price (see
			// RiskValuation#classify), resolved for EVERY id here (owned ids
			// included, since the caller no longer excludes them — see
			// GearSection#withResolvedPrices), so an owned or untradeable
			// expensive item can no longer dodge the cap.
			//
			// 24187 = ItemID.TROUVER_PARCHMENT, fetched once per resolve rather
			// than per item (verified via javap against the pinned
			// net.runelite:client/runelite-api 1.12.32 jars on this project's
			// classpath).
			long parchmentPrice = Math.max(0L, valuation.unitValue(24187));
			java.util.Map<Integer, Long> riskValues = new java.util.HashMap<>();
			java.util.Set<Integer> needsProtection = new java.util.HashSet<>();
			for (int id : ids)
			{
				com.ospulse.combat.RiskValuation.Risk risk = com.ospulse.combat.RiskValuation.classify(
					id, valuation::isTradeable, valuation::unitValue, parchmentPrice,
					com.ospulse.combat.optimizer.GearOptimizer::isFreeReobtainable);
				if (risk.value > 0)
				{
					riskValues.put(id, risk.value);
				}
				if (risk.source == com.ospulse.combat.RiskValuation.Source.PARCHMENT)
				{
					needsProtection.add(id);
				}
			}
			GearSection.PriceLookup lookup = new GearSection.PriceLookup(m, untradeable, riskValues, needsProtection);
			javax.swing.SwingUtilities.invokeLater(() -> cb.accept(lookup));
		});

		panel = new OSPulsePanel(config, itemManager, configManager, priceTrendService, skillIconManager,
			spriteManager, this, client, overlayManager, optimizerPriceResolver);
		// resetSession() reads live item containers (buildWealth ->
		// client.getItemContainer), which asserts the client thread; the Reset
		// button fires on the Swing EDT, so marshal the engine reset onto the
		// client thread here. The panel's own resetSections() still runs first
		// on the EDT (clearing UI baselines before the re-anchored snapshot is
		// published back), preserving the phantom-profit-on-reset ordering.
		panel.setResetCallback(() -> clientThread.invoke(tracker::resetSession));
		panel.setBankHighlighter(bankHighlighter);
		tracker.addListener(panel);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("OSPulse")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// If the plugin is toggled on mid-session, start tracking immediately.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			tracker.onLogin();
		}
		armPendingIronmanAutoDetectIfLoggedIn();

		log.debug("OSPulse plugin started");
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (panel != null)
		{
			// Drop any category overlays the user added to the canvas so a
			// plugin toggle doesn't leak stale XP-Tracker-style overlays.
			panel.removeAllCategoryOverlays();
			// Flush HoldingsSection's Unrealized P/L snapshot so "since last
			// login" has the freshest possible baseline next time.
			panel.persistState();
		}
		if (tracker != null)
		{
			// Persist the last-known bank before tearing down so a plugin toggle
			// or client close doesn't lose it.
			tracker.flush();
			tracker.removeListener(panel);
		}
		tracker = null;
		panel = null;
		if (priceTrendService != null)
		{
			// Cancel in-flight price-trend fetches so a late callback can't run
			// Swing work against the now-detached panel.
			priceTrendService.shutdown();
		}
		priceTrendService = null;
		if (bankHighlighter != null)
		{
			bankHighlighter.clear();
		}
		bankHighlighter = null;
		lastBankOpen = false;

		log.debug("OSPulse plugin stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				tracker.onLogin();
				armPendingIronmanAutoDetectIfLoggedIn();
				break;
			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				tracker.onLogout();
				lastBankOpen = false;
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (pendingIronmanAutoDetect)
		{
			// P2 fix: only consumed once checkIronmanAutoDetect() actually ran —
			// see that method's readiness guard/javadoc. Clearing the flag
			// unconditionally here (the earlier bug) would silently drop the
			// only pending attempt for the whole session whenever the FIRST
			// post-login tick still reported account state as not-yet-ready:
			// no other event re-arms pendingIronmanAutoDetect until the next
			// LOGGED_IN transition, so auto-detect would just never run.
			pendingIronmanAutoDetect = !checkIronmanAutoDetect();
		}

		// Detect bank open/close transitions before advancing the tracker so the
		// engine treats inventory<->bank moves as transfers while the bank is
		// open, and re-baselines on close.
		// Bankmain.UNIVERSE is the bank interface's root container (packed id
		// 786433 = group 12 child 1, the classic "bank container" component).
		// A bank DEPOSIT BOX (BankDepositbox.UNIVERSE, group 192) is banking too:
		// items go straight to the bank with no wealth loss, so it must count as
		// "bank open" — otherwise a deposit there books the tracked drop as a loss
		// while the offsetting bank rise is mis-classified. The server keeps the
		// InventoryID.BANK container synced through a deposit box, so the rise is
		// observed and settles the deposit exactly like an open-bank transfer.
		final Widget bankWidget = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		final Widget depositBoxWidget = client.getWidget(InterfaceID.BankDepositbox.UNIVERSE);
		final boolean bankOpen = (bankWidget != null && !bankWidget.isHidden())
			|| (depositBoxWidget != null && !depositBoxWidget.isHidden());
		if (bankOpen != lastBankOpen)
		{
			lastBankOpen = bankOpen;
			tracker.onBankOpenChanged(bankOpen);
			if (bankOpen)
			{
				bankHighlighter.reapplyIfArmed();
			}
		}

		tracker.onTick();
	}

	/**
	 * Arms {@link #pendingIronmanAutoDetect} if the client is already logged
	 * in — shared by {@link #startUp()} (plugin enabled while already
	 * logged in, which fires no {@code LOGGED_IN} {@link GameStateChanged})
	 * and {@link #onGameStateChanged}'s own LOGGED_IN case, so the two paths
	 * cannot drift (issue #11 P2 fix).
	 */
	void armPendingIronmanAutoDetectIfLoggedIn()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			pendingIronmanAutoDetect = true;
		}
	}

	/** Test seam: {@link #pendingIronmanAutoDetect}'s current value. */
	boolean pendingIronmanAutoDetectForTest()
	{
		return pendingIronmanAutoDetect;
	}

	/**
	 * One-time, per-RS-profile auto-enable of {@link OSPulseConfig#ironmanOwnedOnly()}
	 * for ironman accounts (issue #11). Deliberately run from the first
	 * {@link GameTick} after login rather than {@link #onGameStateChanged}
	 * itself: reading account state (e.g. {@link Client#getAccountType()}) on
	 * the LOGGED_IN transition has been observed elsewhere in this codebase
	 * (see the bank-cache/GE-ledger restore in {@code SessionTracker}) to run
	 * before the client has finished populating post-login state, so this
	 * mirrors {@code SessionTracker#onTick}'s own bootstrap-on-next-tick
	 * pattern by deferring exactly one tick.
	 *
	 * <p>{@code ironmanOwnedOnly} is per-account now (issue #11 leak fix): the
	 * write below goes through {@link #ownedOnlyStore}'s {@code
	 * writeAutoDetected}, which sets ONLY the current account's RS-profile-
	 * scoped value, never the client-wide {@code @ConfigItem} — an ironman
	 * alt auto-enabling can therefore never leak onto a main sharing the same
	 * client. The bookkeeping "have I already evaluated this profile" marker
	 * (separate from the value itself) is likewise RS-profile-scoped (via
	 * {@code getRSProfileConfiguration}/{@code setRSProfileConfiguration},
	 * mirroring {@code SessionTracker}'s bank-cache/GE-ledger persistence) —
	 * this guarantees an ironman alt and a main sharing one client each get
	 * their own independent one-time evaluation, rather than one profile's
	 * "already decided" state silently blocking the other's. See {@link
	 * IronmanAutoDetect} for the pure decision logic and {@link
	 * IronmanOwnedOnlyStore}/{@code com.ospulse.ui.sections.gear.IronmanOwnedOnlyResolver}
	 * for the full per-account merged-read scheme.
	 *
	 * @return {@code false} when the readiness guard below refused to run at
	 *         all (account state not yet available) — {@link #onGameTick}'s
	 *         P2 fix uses this to decide whether {@link
	 *         #pendingIronmanAutoDetect} may be cleared or must stay armed
	 *         for a retry on the next tick; {@code true} otherwise (the check
	 *         ran to completion, whatever it decided).
	 */
	private boolean checkIronmanAutoDetect()
	{
		if (configManager == null || client.getAccountHash() == -1L)
		{
			return false;
		}

		String seenMarker = configManager.getRSProfileConfiguration(
			OSPulseConfig.GROUP, IRONMAN_AUTO_DETECT_SEEN_KEY);
		if (IronmanAutoDetect.needsEvaluation(seenMarker))
		{
			configManager.setRSProfileConfiguration(OSPulseConfig.GROUP, IRONMAN_AUTO_DETECT_SEEN_KEY, true);

			String rawOwnedOnly = ownedOnlyStore.rawProfileValue();
			AccountType accountType = client.getAccountType();
			boolean isIronman = accountType != null && (accountType.isIronman() || accountType.isGroupIronman());
			if (IronmanAutoDetect.shouldAutoEnable(rawOwnedOnly, isIronman))
			{
				ownedOnlyStore.writeAutoDetected(true);
			}
		}

		// Mirror (issue #11 leak fix): every login re-syncs the client-wide
		// checkbox to this account's resolved effective value, so the settings
		// panel never shows a stale value left over from whichever account was
		// last logged in. Also re-run from onRuneScapeProfileChanged (an RS
		// profile switch without a full re-login, e.g. bank PIN or world hop
		// edge cases RuneLite itself treats as a profile change).
		ownedOnlyStore.mirrorToClientWide();
		return true;
	}

	/** Test seam: runs {@link #checkIronmanAutoDetect()} directly (private, no {@code pendingIronmanAutoDetect} plumbing needed in a test). */
	void checkIronmanAutoDetectForTest()
	{
		checkIronmanAutoDetect();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		tracker.onItemContainerChanged(event.getContainerId(), event.getItemContainer());
	}

	/**
	 * Forwards chat messages so {@link SessionTracker}'s fish-barrel tracker can
	 * infer barreled-fish contents from catch/full/empty messages — an open
	 * fish barrel auto-stores caught fish without ever passing them through the
	 * inventory, so this is the only signal available for those catches.
	 */
	@Subscribe
	public void onChatMessage(net.runelite.api.events.ChatMessage event)
	{
		tracker.onChatMessage(event.getType(), event.getMessage());
	}

	/**
	 * Forwards the fish barrel's "Check" interface load (group 193) so the
	 * tracker can resynchronise its exact per-species contents from the
	 * widget text. See {@code FishBarrelTracker#onWidgetLoaded}.
	 */
	@Subscribe
	public void onWidgetLoaded(net.runelite.api.events.WidgetLoaded event)
	{
		tracker.onWidgetLoaded(event.getGroupId());
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		tracker.onGrandExchangeOfferChanged(event.getSlot(), event.getOffer());
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		tracker.onStatChanged(event.getSkill(), event.getXp());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		tracker.onLootReceived(event.getName(), event.getAmount(), event.getItems());
	}

	/**
	 * Forwards deliberate "Drop"/"Destroy" inventory item ops to the tracker as
	 * per-tick {@link com.ospulse.session.MovementSignals}. Shift-click drop
	 * fires the same "Drop" option, so it's covered without extra handling.
	 *
	 * <p><b>Destroy timing caveat:</b> "Destroy" fires on the menu click itself,
	 * BEFORE the confirmation dialog is shown — so a later-confirmed (or
	 * cancelled) destroy may not align with the item's actual vanish tick, since
	 * this is recorded as a per-tick signal at click time. Drop has no such
	 * confirmation step and is unaffected. This is a known limitation to verify
	 * in-client, not a blocker for this wiring.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}
		int itemId = event.getItemId();
		if (itemId <= 0)
		{
			return;
		}
		if ("Drop".equalsIgnoreCase(option))
		{
			tracker.recordDrop(itemId);
		}
		else if ("Destroy".equalsIgnoreCase(option))
		{
			tracker.recordDestroy(itemId);
		}
		// Fish barrel "Fill"/"Empty"/"Empty to bank"/"Check" ops — forwarded
		// unconditionally; the tracker itself filters to barrel item ids.
		tracker.onBarrelMenuAction(itemId, option);
	}

	/**
	 * Forwards the local player's death to the tracker as a per-tick
	 * {@link com.ospulse.session.MovementSignals#diedThisTick()} signal.
	 *
	 * <p><b>Timing caveat:</b> {@code ActorDeath} fires on the death animation,
	 * but the {@code died} signal is only drained on the next {@link
	 * SessionTracker#onTick} refresh (per-tick drain, same mechanism as
	 * Drop/Destroy). For the engine's death-parking to gate correctly, this
	 * event's tick must coincide with the tick the inventory actually clears.
	 * If in practice the inventory clears a tick or more after {@code
	 * ActorDeath}, the signal may miss its window — a known integration risk
	 * to verify in-client, not a blocker for this wiring. The per-tick drain
	 * design itself is unchanged to compensate for this.
	 */
	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			tracker.recordDeath();
		}
	}

	/**
	 * Tracks the local player's animation so the engine can open a skilling
	 * episode from it. Animation is not a nicety here: herblore's unf-making
	 * step grants no XP at all, so an XP-only trigger would never see the step
	 * the expensive herb is spent on. See {@code ProductionActivity} for the id
	 * table — every id resolved from RuneLite's own {@code AnimationID}
	 * constants and guarded by {@code ProductionAnimationProvenanceTest} — and
	 * for why a missing id degrades safely.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			tracker.onAnimationChanged(event.getActor().getAnimation());
		}
	}

	/**
	 * An RS profile switch without a full re-login (RuneLite fires this
	 * whenever its own profile resolution decides the "current" RS profile
	 * changed) — re-mirrors the newly-current account's resolved value into
	 * the client-wide checkbox (issue #11 leak fix), same as {@link
	 * #checkIronmanAutoDetect()} does on every login.
	 */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		if (ownedOnlyStore == null)
		{
			return;
		}
		ownedOnlyStore.mirrorToClientWide();
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::refreshIronmanOwnedOnlyMode);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!OSPulseConfig.GROUP.equals(event.getGroup()) || panel == null)
		{
			return;
		}

		// Panel-section show/hide toggles apply live (no plugin restart): the panel
		// keeps every section constructed and just re-lays-out the visible set.
		final String key = event.getKey();
		if (key != null && key.startsWith("show") && key.endsWith("Section"))
		{
			SwingUtilities.invokeLater(panel::applySectionVisibility);
		}

		// Ironman owned-only mode (issue #11 P2 fix, then the issue #11 leak
		// fix's per-account scheme): every change on this key — the auto-
		// detect's own per-profile write, this plugin's own client-wide
		// mirror echoing back, or a genuine user toggle of the settings-panel
		// checkbox — must recompute the affected GearSection visibility live,
		// same as the show*Section keys above.
		if (IRONMAN_OWNED_ONLY_KEY.equals(key))
		{
			// A non-null profile means this is a profile-SCOPED write (verified
			// against the ConfigManager bytecode: setRSProfileConfiguration's
			// posted ConfigChanged always carries the resolved RS profile key;
			// every plain setConfiguration — whether ours or the settings
			// panel's — always carries a null profile) — i.e. auto-detect's own
			// write, never a user toggle of the client-wide checkbox. Refresh
			// only; never treat it as a toggle to persist.
			if (event.getProfile() == null)
			{
				// Client-wide write: either this plugin's own mirrorToClientWide
				// echoing back (swallowed by the echo latch — see
				// IronmanOwnedOnlyStore's javadoc) or a genuine user toggle,
				// which must persist to the current account's per-profile value
				// AND the global default.
				if (!ownedOnlyStore.consumeMirrorEcho(event.getNewValue()))
				{
					ownedOnlyStore.writeUserToggle(Boolean.parseBoolean(event.getNewValue()));
				}
			}
			SwingUtilities.invokeLater(panel::refreshIronmanOwnedOnlyMode);
		}
	}

	@Provides
	OSPulseConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OSPulseConfig.class);
	}
}

package com.ospulse.model;

import lombok.Getter;

import java.util.Objects;

/**
 * Immutable value type representing a quantity of a single item at a given
 * per-unit value. Pure domain type: no RuneLite imports, unit-testable
 * without a game client.
 */
@Getter
public final class ItemStack
{
	private final int id;
	private final String name;
	private final long quantity;
	private final long unitValue;
	/**
	 * Per-unit High Alchemy price, resolved on the client thread at
	 * construction time; {@code -1} if not resolved (composition unavailable).
	 */
	private final long haPrice;

	public ItemStack(int id, String name, long quantity, long unitValue)
	{
		this(id, name, quantity, unitValue, -1L);
	}

	/**
	 * @param haPrice per-unit High Alchemy price, or {@code -1} if not resolved
	 *                (e.g. no {@code ItemComposition} was available). Must be
	 *                resolved on the RuneLite client thread — never the Swing
	 *                EDT, since {@code ItemManager.getItemComposition} asserts
	 *                that thread.
	 */
	public ItemStack(int id, String name, long quantity, long unitValue, long haPrice)
	{
		this.id = id;
		this.name = name;
		this.quantity = quantity;
		this.unitValue = unitValue;
		this.haPrice = haPrice;
	}

	/**
	 * Total value of this stack: quantity * unitValue.
	 */
	public long value()
	{
		return quantity * unitValue;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof ItemStack))
		{
			return false;
		}
		ItemStack itemStack = (ItemStack) o;
		return id == itemStack.id
			&& quantity == itemStack.quantity
			&& unitValue == itemStack.unitValue
			&& Objects.equals(name, itemStack.name);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id, name, quantity, unitValue);
	}

	@Override
	public String toString()
	{
		return "ItemStack{"
			+ "id=" + id
			+ ", name='" + name + '\''
			+ ", quantity=" + quantity
			+ ", unitValue=" + unitValue
			+ '}';
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.MonsterConsumablesReminder;
import com.ospulse.combat.MonsterConsumablesRepository;

import net.runelite.client.ui.ColorScheme;

import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * The "don't forget" consumables/gear reminder row(s) below the
 * potion/prayer/slayer toggles in the Gear section — a single curated
 * advisory line naming what a target demands (venom, dragonfire, etc.) that
 * the DPS optimiser cannot infer, sourced from {@link
 * MonsterConsumablesRepository}. Renders through the same {@link
 * AdvisoryNoteRenderer#wrappingNote} every other Gear-section advisory note
 * uses, so it wraps and reads identically to the mechanic-override and
 * combat-requirement notes it sits beside.
 *
 * <p>Deliberately free of any {@code GearSection} state: {@link #refresh}
 * takes only a monster name (or {@code null}), so this class is
 * independently constructible and testable without a {@code GearSection}
 * instance. It is a pure keyed-lookup render step, never touching {@code
 * GearOptimizer} — picking a target with no curated entry costs one map
 * lookup and renders nothing, not an empty placeholder row.
 *
 * <p><b>The caller must pass {@code Monster.lookupName()}, not {@code
 * Monster.name()}.</b> A synthetic Wilderness-variant target (see {@code
 * WildernessVariantMonsterRepository}) has a decorated DISPLAY name (e.g.
 * "Black dragon (Wilderness)") that this repository's curated data was
 * never authored against — the reminder must resolve against the real
 * underlying monster's identity so a Wilderness Black dragon still gets the
 * same dragonfire-shield note the ordinary Black dragon does.
 */
public final class ConsumablesReminderPanel extends JPanel
{
	public ConsumablesReminderPanel()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setVisible(false);
	}

	/**
	 * Rebuilds this panel for the given target's LOOKUP name (see the class
	 * javadoc — {@code Monster.lookupName()}, not {@code Monster.name()}).
	 * {@code null} (no target selected) and a name with no curated reminder
	 * both leave the panel empty and invisible — no empty row, no placeholder.
	 *
	 * <p>Named {@code refresh}, not {@code update}, to avoid an overload
	 * clash/shadow with {@code JComponent.update(Graphics)}.
	 */
	public void refresh(String monsterName)
	{
		removeAll();
		boolean show = false;
		if (monsterName != null)
		{
			Optional<MonsterConsumablesReminder> reminder =
				MonsterConsumablesRepository.getInstance().forMonster(monsterName);
			if (reminder.isPresent() && !reminder.get().note().isEmpty())
			{
				add(AdvisoryNoteRenderer.wrappingNote(reminder.get().note(), ColorScheme.BRAND_ORANGE));
				show = true;
			}
		}
		setVisible(show);
		revalidate();
		repaint();
	}

	/** Test seam: the rendered text of every current advisory line, in order. */
	public List<String> noteTextsForTest()
	{
		List<String> texts = new ArrayList<>();
		for (Component c : getComponents())
		{
			if (c instanceof JTextArea)
			{
				texts.add(((JTextArea) c).getText());
			}
		}
		return texts;
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.optimizer.GearOptimizer;

/**
 * Pure decision logic for the ironman "owned gear only" optimiser mode
 * (issue #11). An ironman can't buy anything, so the upgrade-oriented UI
 * (budget/risk row, "Best DPS found", "vs owned-only", "Total spend", "DPS
 * per gp spent", suggested swaps) is noise — this is a real optimiser
 * restriction (budget forced to 0), not merely a visual mask, so every
 * remaining recommendation is actually reachable.
 *
 * <p>Deliberately free of any {@link com.ospulse.ui.sections.GearSection}
 * state: callers pass in whatever budget/visibility inputs they hold rather
 * than this class reaching into private mutable fields, so it stays trivially
 * unit-testable and easy to split out later.
 */
public final class OwnedOnlyMode
{
	private OwnedOnlyMode()
	{
	}

	/**
	 * The optimiser request's actual budget: forced to 0 in owned-only mode.
	 * {@code storedBudget} (whatever the user has typed/persisted) is only
	 * ever read here, never written, so toggling the mode back off restores
	 * it unchanged.
	 */
	public static long effectiveBudget(boolean ownedOnly, long storedBudget)
	{
		return ownedOnly ? 0L : storedBudget;
	}

	/**
	 * Whether the budget/risk row (gold-pile badge, budget field, K/M toggle,
	 * risk column) should be visible. Unlike {@link #upgradeStatRowsVisible},
	 * this row has no other reason to hide, so owned-only mode is the only
	 * input.
	 */
	public static boolean upgradeUiVisible(boolean ownedOnly)
	{
		return !ownedOnly;
	}

	/**
	 * Whether the four upgrade-oriented result rows ("Best DPS found", "vs
	 * owned-only", "Total spend", "DPS per gp spent") and the suggested-swaps
	 * list should be visible. Composes owned-only mode with whether the
	 * current result is otherwise usable ({@code hasUsableResult} — false in
	 * the pre-existing "no usable weapon" state, which must keep hiding these
	 * regardless of mode). The "Optimised for" row is deliberately NOT
	 * included here — it describes the current pick, not an upgrade, and
	 * stays visible whenever {@code hasUsableResult} alone would show it; see
	 * {@code GearSection#setOptimizerStyleRowVisible}.
	 */
	public static boolean upgradeStatRowsVisible(boolean ownedOnly, boolean hasUsableResult)
	{
		return hasUsableResult && !ownedOnly;
	}

	/** {@link #upgradeStatRowsVisible(boolean, boolean)}, deriving "has a usable result" from a nullable optimiser result — {@code null} or a {@code null} style means not usable. */
	public static boolean upgradeStatRowsVisible(boolean ownedOnly, GearOptimizer.Result result)
	{
		return upgradeStatRowsVisible(ownedOnly, result != null && result.style() != null);
	}
}

package com.ospulse.ui.sections.gear;

/**
 * Pure decision logic for the per-account (per-RS-profile) scheme behind
 * {@link com.ospulse.OSPulseConfig#ironmanOwnedOnly()} — the fix for the
 * "ironman alt leaks the mode onto a main sharing one client" bug the
 * original {@code ironmanOwnedOnly} {@code @ConfigItem} had ({@link
 * IronmanAutoDetect} covers the one-time auto-enable decision this scheme
 * feeds).
 *
 * <p>{@code @ConfigItem} storage is inherently client-wide, so three raw
 * values live under the {@code ospulse} config group:
 * <ul>
 *   <li>a per-RS-profile {@code ironmanOwnedOnly} value (via {@code
 *       ConfigManager#getRSProfileConfiguration}/{@code
 *       setRSProfileConfiguration}) — the authoritative per-account value,
 *       {@code null} meaning "this account has never been decided";</li>
 *   <li>the client-wide {@code ironmanOwnedOnly} {@code @ConfigItem} itself —
 *       now only an edit surface / per-account display mirror, never read as
 *       the source of truth for behaviour;</li>
 *   <li>a client-wide, hidden {@code ironmanOwnedOnlyDefault} key (no {@code
 *       @ConfigItem}) — the user's global preference, consulted only for
 *       accounts with no per-profile value yet.</li>
 * </ul>
 *
 * <p>This class holds only the merged-read and toggle/echo decisions given
 * raw string inputs, never touching {@code ConfigManager} or any other
 * RuneLite type directly, so it is trivially unit-testable. {@link
 * IronmanOwnedOnlyStore} owns the actual reads/writes (including the
 * mutable echo-latch state) and calls into this class for the decisions.
 */
public final class IronmanOwnedOnlyResolver
{
	private IronmanOwnedOnlyResolver()
	{
	}

	/**
	 * The merged three-way read: the per-profile value wins if set, else the
	 * global default if set, else {@code false} (a never-decided account with
	 * no global preference either).
	 *
	 * @param rawProfileValue the current account's raw per-profile value
	 *                        ({@code null} = never decided for this account)
	 * @param rawGlobalDefault the raw {@code ironmanOwnedOnlyDefault} value
	 *                         ({@code null} = the user has no global
	 *                         preference recorded yet)
	 */
	public static boolean resolve(String rawProfileValue, String rawGlobalDefault)
	{
		if (rawProfileValue != null)
		{
			return Boolean.parseBoolean(rawProfileValue);
		}
		if (rawGlobalDefault != null)
		{
			return Boolean.parseBoolean(rawGlobalDefault);
		}
		return false;
	}

	/**
	 * Whether the client-wide mirror actually needs (re-)writing: only when
	 * the resolved effective value differs from what the client-wide box
	 * currently shows. Callers must skip the write entirely (never arm an
	 * echo latch) when this is {@code false} — see {@link
	 * IronmanOwnedOnlyStore}'s echo-latch javadoc for why an unnecessary arm
	 * is dangerous (it would never be consumed, and could swallow a later
	 * genuine user toggle).
	 */
	public static boolean needsMirrorWrite(String rawClientWideValue, boolean effective)
	{
		return Boolean.parseBoolean(rawClientWideValue) != effective;
	}

	/**
	 * Whether a {@code ConfigChanged} event on the client-wide key's raw new
	 * value matches the value a just-armed mirror write was expected to
	 * produce — i.e. this event is that write echoing back through the event
	 * bus, not an independent change. Compared as parsed booleans (not raw
	 * strings) so serialisation-format differences can't cause a false
	 * negative.
	 *
	 * <p>{@code armedExpectedValue == null} means the latch isn't armed (no
	 * mirror write is in flight), so nothing can ever match it.
	 */
	public static boolean isMirrorEcho(String armedExpectedValue, String eventNewValue)
	{
		return armedExpectedValue != null
			&& Boolean.parseBoolean(armedExpectedValue) == Boolean.parseBoolean(eventNewValue);
	}
}

package com.ospulse.ui.sections.gear;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.ActionListener;
import javax.swing.ButtonModel;
import javax.swing.JButton;
import net.runelite.client.ui.FontManager;

/**
 * A flat, filled, rounded-rectangle button for the Gear DPS panel — e.g. the
 * green "Find Best" / red "Revert" controls flanking the helmet slot. Paints
 * its own solid background (with hover/pressed/disabled shading) so it reads as
 * a pill regardless of the platform look-and-feel, which would otherwise draw a
 * grey system button. First extracted piece of the {@code ui.sections.gear}
 * package (the GearSection redesign is being modularised section by section).
 */
public final class RoundedButton extends JButton
{
	private static final int ARC = 12;

	private final Color base;
	private final Color hover;
	private final Color pressed;

	public RoundedButton(String text, Color base, Color fg)
	{
		super(text);
		this.base = base;
		this.hover = shade(base, 0.12f);
		this.pressed = shade(base, -0.12f);
		setForeground(fg);
		setFont(FontManager.getRunescapeSmallFont());
		setFocusPainted(false);
		setBorderPainted(false);
		setContentAreaFilled(false);
		setOpaque(false);
		setRolloverEnabled(true);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setMargin(new Insets(3, 8, 3, 8));
	}

	/** Convenience factory: styled button wired to {@code onClick} with a tooltip. */
	public static RoundedButton action(String text, Color base, Color fg, String tooltip, ActionListener onClick)
	{
		RoundedButton button = new RoundedButton(text, base, fg);
		button.setToolTipText(tooltip);
		button.addActionListener(onClick);
		return button;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		ButtonModel model = getModel();
		Color bg;
		if (!isEnabled())
		{
			bg = shade(base, -0.28f);
		}
		else if (model.isPressed())
		{
			bg = pressed;
		}
		else if (model.isRollover())
		{
			bg = hover;
		}
		else
		{
			bg = base;
		}
		g2.setColor(bg);
		g2.fillRoundRect(0, 0, getWidth(), getHeight(), ARC, ARC);
		g2.dispose();
		// Draws the label/icon on top; content-area-filled is off so nothing
		// paints over our rounded background.
		super.paintComponent(g);
	}

	/** Lighten ({@code f>0}) or darken ({@code f<0}) a colour by a fraction of full scale. */
	private static Color shade(Color c, float f)
	{
		return new Color(
			clamp(Math.round(c.getRed() + 255 * f)),
			clamp(Math.round(c.getGreen() + 255 * f)),
			clamp(Math.round(c.getBlue() + 255 * f)));
	}

	private static int clamp(int v)
	{
		return Math.max(0, Math.min(255, v));
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.EquipmentIndexRepository;
import com.ospulse.model.ItemStack;
import com.ospulse.session.GearSnapshot;
import com.ospulse.wealth.WealthSnapshot;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * For each plain item id the player owns only by CREDIT, the id of the held
 * variant that credit came from — the inverse of {@code
 * GearSection.addVariantPlainForm}'s synthetic ownership entry.
 *
 * <p>The credit is deliberately one-way in the ownership map: owning "Imbued
 * saradomin cape (deadman)" marks the plain cape owned at price 0, and the
 * optimiser needs nothing more than that to treat it as free. But two things
 * downstream need to know <b>which physical item</b> the credit stands for:
 *
 * <ul>
 *   <li>the display, which must name the item the player actually holds (see
 *   {@link HeldItemIds} and {@code GearSection#resolvedItemId});</li>
 *   <li>the expensive-item risk cap, which must price what the player is
 *   actually told to <b>risk</b>. A tradeable cosmetic — Deadman AGS, Dark
 *   bow, Bowfa — can be worth a different amount from its ordinary
 *   counterpart, and the cap looking up the credited plain id counts the
 *   wrong item's gp. With a threshold between the two values, a
 *   wilderness/PvP search silently violates the user's own expensive-item
 *   limit.</li>
 * </ul>
 *
 * <p>A plain id the player <b>physically holds</b> is never listed here: it
 * prices itself, and no substitution happens for it anyway.
 *
 * <p><b>Exclusions are honoured for the same reason the display honours
 * them.</b> {@code preferOwnedVariant} never returns a variant the player
 * excluded from suggestions, so an excluded variant's credit leaves the plain
 * id on screen and in the preview — and the cap must then price the plain
 * item, the one that will actually be equipped. A credit map that ignored
 * exclusions would charge for an item the player has told the panel not to
 * use, which can reject a valid setup or wave through an over-threshold one
 * depending on which side of the threshold the two values fall.
 */
public final class VariantCreditSources
{
	private VariantCreditSources()
	{
	}

	/**
	 * Credited plain id -&gt; the held variant id backing it. Mirrors {@code
	 * GearSection.ownedPriceMap()}'s two sources and its {@code
	 * getAllHoldings()}-then-{@code getTopHoldings()} fallback, so the credit
	 * map can never disagree with the ownership map about what was credited.
	 *
	 * <p>When two held variants credit the same plain id the first wins,
	 * matching the ownership map's own {@code putIfAbsent} semantics.
	 */
	public static Map<Integer, Integer> from(WealthSnapshot wealth, GearSnapshot gear,
		EquipmentIndexRepository index, Set<Integer> excludedItemIds)
	{
		Set<Integer> held = HeldItemIds.from(wealth, gear, index);
		Map<Integer, Integer> credits = new HashMap<>();
		if (wealth != null)
		{
			Collection<ItemStack> stacks = !wealth.getAllHoldings().isEmpty()
				? wealth.getAllHoldings().values()
				: wealth.getTopHoldings();
			for (ItemStack stack : stacks == null ? Collections.<ItemStack>emptyList() : stacks)
			{
				if (stack != null)
				{
					record(credits, held, index, excludedItemIds, stack.getId());
				}
			}
		}
		if (gear != null)
		{
			for (int id : gear.equippedItemIds())
			{
				record(credits, held, index, excludedItemIds, id);
			}
		}
		return credits;
	}

	private static void record(Map<Integer, Integer> credits, Set<Integer> held,
		EquipmentIndexRepository index, Set<Integer> excludedItemIds, int heldItemId)
	{
		if (heldItemId <= 0 || index.entryFor(heldItemId) == null
			|| (excludedItemIds != null && excludedItemIds.contains(heldItemId)))
		{
			return;
		}
		Integer plainId = OwnedVariantResolver.plainFormId(index, heldItemId);
		if (plainId != null && !held.contains(plainId))
		{
			credits.putIfAbsent(plainId, heldItemId);
		}
	}
}

package com.ospulse.ui.sections.gear;

import net.runelite.client.ui.FontManager;

import javax.swing.JTextArea;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;

/**
 * Builds the one word-wrapping advisory "label" every DPS-blind curated note
 * in the Gear section shares — the mechanic-override note, the
 * combat-requirement note, and the consumables reminder note all render
 * through this single method so they read (and wrap) identically. Extracted
 * out of {@code GearSection} verbatim (no behaviour change) so a brand-new
 * advisory panel can reuse the exact same rendering instead of a parallel
 * implementation.
 */
public final class AdvisoryNoteRenderer
{
	private AdvisoryNoteRenderer()
	{
	}

	/**
	 * A read-only, non-opaque, word-wrapping "label" that — unlike a plain
	 * {@code JLabel} (no wrap) or an HTML-{@code JLabel} approach
	 * (hard-coded {@code width:200px}, clipped in a narrower panel) — wraps to
	 * whatever width the enclosing {@code BoxLayout} panel actually gives it.
	 * Standard Swing trick: {@link JTextArea#getPreferredSize()} normally
	 * measures the UNWRAPPED width, so it is overridden here to re-measure
	 * against the parent's current width once one is known, and
	 * {@code getMaximumSize()} caps height at that (dynamic) preferred height
	 * while leaving width free to stretch to the container.
	 */
	public static JTextArea wrappingNote(String text, Color foreground)
	{
		JTextArea area = new JTextArea(text)
		{
			@Override
			public Dimension getPreferredSize()
			{
				Container parent = getParent();
				int width = parent != null ? parent.getWidth() : 0;
				if (width > 0)
				{
					setSize(width, Short.MAX_VALUE);
				}
				return super.getPreferredSize();
			}

			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		area.setEditable(false);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setFont(FontManager.getRunescapeSmallFont());
		area.setForeground(foreground);
		area.setBorder(null);
		area.setAlignmentX(Component.LEFT_ALIGNMENT);
		return area;
	}
}

package com.ospulse.ui.sections.gear;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * A decorative gold-coin pile with the resolved budget value (e.g. "50M")
 * painted over its top-left corner in a magnitude colour, per Jonathan's
 * mockup. The value is anchored to the top-left and shrinks to stay within the
 * pile's width (never spills past the gold), with a black drop-shadow for
 * legibility like in-game stack text.
 */
public final class CoinPileBadge extends JComponent
{
	private final BufferedImage pile;
	private final int w;
	private final int h;
	private final Font baseFont;

	private String value = "0";
	private Color valueColor = Color.WHITE;

	public CoinPileBadge(BufferedImage pile, int width, int height)
	{
		this.pile = pile;
		this.w = width;
		this.h = height;
		this.baseFont = FontManager.getRunescapeBoldFont();
		Dimension d = new Dimension(width, height);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
	}

	/** Sets the displayed value text and its (magnitude) colour, then repaints. */
	public void setValue(String value, Color color)
	{
		this.value = value == null ? "" : value;
		this.valueColor = color;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		// Pile fills the component (bottom-aligned so the value sits over its top).
		if (pile != null)
		{
			g2.drawImage(pile, 0, 0, w, h, null);
		}

		// Value at top-left, shrunk until it fits the pile's width.
		float size = 15f;
		Font font = baseFont.deriveFont(Font.BOLD, size);
		g2.setFont(font);
		FontMetrics fm = g2.getFontMetrics();
		while (fm.stringWidth(value) > w - 2 && size > 8f)
		{
			size -= 1f;
			font = baseFont.deriveFont(Font.BOLD, size);
			g2.setFont(font);
			fm = g2.getFontMetrics();
		}
		int x = 1;
		int y = fm.getAscent();
		// Full black outline (8 offsets) so the value stays legible over the
		// gold pile, then the coloured value on top.
		g2.setColor(Color.BLACK);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					g2.drawString(value, x + dx, y + dy);
				}
			}
		}
		g2.setColor(valueColor);
		g2.drawString(value, x, y);
		g2.dispose();
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.ui.CentFormat;
import java.util.Locale;

/**
 * Formats DPS numbers for the Gear DPS panel. The sibling of {@link GpFormat}:
 * where that one handles gp amounts, this one handles the "x.xx" damage-per-second
 * values, and both defer to {@link CentFormat} so every "cent" number in the panel
 * shares one treatment.
 */
public final class DpsFormat
{
	private DpsFormat()
	{
	}

	/** A DPS value at the panel's fixed two-decimal precision. */
	public static String format(double dps)
	{
		return String.format(Locale.ROOT, "%.2f", dps);
	}

	/**
	 * Renders a DPS value as an HTML fragment that resists the "1.98 read as
	 * 198" misread — a real report, since a woodcutting felling axe legitimately
	 * does ~2 DPS. Price-tag style: the whole-number part is unbolded in the
	 * given colour, and the decimal point plus the fractional digits are
	 * dimmed and half-size, so the magnitude reads at a glance and the
	 * decimals visibly recede. Delegates to {@link CentFormat} so every
	 * "cent" number in the panel (gp values, DPS, accuracy, avg hit, TTK,
	 * overkill — "cent" meaning the fractional/decimal part, by analogy
	 * with money cents) shares the exact same treatment.
	 */
	public static String fragment(double dps)
	{
		return CentFormat.fragment(format(dps));
	}

	/**
	 * {@link #fragment(double)}, but with an explicit integer/decimal
	 * colour pairing — used by the "vs worn"/optimizer delta rows so a
	 * green (upgrade) or red (downgrade) comparison dims its decimals in the
	 * matching hue instead of the default grey.
	 */
	public static String fragment(double dps, String intColor, String decimalColor)
	{
		return CentFormat.fragment(format(dps), intColor, decimalColor);
	}

	/**
	 * {@link #fragment(double)}, but with the integer in {@code intColor}
	 * and the decimal dimmed to match it (see {@link CentFormat#fragment(String, String)}) —
	 * used by a highlighted/best row whose label foreground isn't the
	 * default white, so the number's own colour has to agree with the row
	 * instead of hard-coding white (an explicit HTML {@code <font color>}
	 * always wins over the label's {@code setForeground}).
	 */
	public static String fragment(double dps, String intColor)
	{
		return CentFormat.fragment(format(dps), intColor);
	}

	/**
	 * {@link #fragment(double)} coloured to match a "vs worn"/optimizer
	 * delta's sign — green (with a dull-green decimal) for an upgrade, red
	 * (dull-red decimal) for a downgrade, or the plain white/grey default
	 * when the delta is effectively zero. {@code delta} is shared across
	 * both the "before" and "after" values in a single comparison row so
	 * they always render in the same colour.
	 */
	public static String deltaFragment(double dps, double delta)
	{
		if (delta > 1e-9)
		{
			return fragment(dps, CentFormat.GREEN, CentFormat.GREEN_DIM);
		}
		if (delta < -1e-9)
		{
			return fragment(dps, CentFormat.RED, CentFormat.RED_DIM);
		}
		return fragment(dps);
	}

	/** {@link #fragment(double)} as a standalone HTML label string. */
	public static String html(double dps)
	{
		return "<html>" + fragment(dps) + "</html>";
	}

	/** {@link #fragment(double, String)} as a standalone HTML label string. */
	public static String html(double dps, String intColor)
	{
		return "<html>" + fragment(dps, intColor) + "</html>";
	}
}

package com.ospulse.ui.sections.gear;

import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Pure decision logic for the P2-A fix (Codex finding on PR #19, {@code
 * GearSection.java:4789}, "Revalidate every recommended item against current
 * ownership").
 *
 * <p>{@link OwnedOnlyMandatoryOverrideGate} already guarantees a target's
 * mandatory {@code MonsterGearOverride} is satisfiable by something owned
 * RIGHT NOW (it reads a live {@code ownedIds} set, not a stale one) before
 * {@code GearSection#onOptimizerResult} installs a result. But that gate only
 * covers the one forced item a mandatory override injects — every OTHER slot
 * in the loadout is whatever {@code GearOptimizer} picked from the {@code
 * ownedPrices} snapshot {@code GearSection#withResolvedPrices} captured when
 * the search LAUNCHED. Owned-only mode's entire guarantee is that every
 * recommended item is one the player owns; if the player drops, sells, or
 * banks-then-loses an item in the gap between that snapshot and the result
 * landing (price resolution / the background {@code SwingWorker} can take a
 * while), an ordinary — non-mandatory — loadout choice can be installed,
 * previewed, and bank-highlighted for an item the player no longer owns,
 * silently breaking the guarantee. Worse, a result that WAS valid at install
 * time can go stale later still: {@code GearSection#apply(SessionSnapshot)}
 * refreshes the player's live holdings on every wealth snapshot without
 * re-validating whatever result is currently installed.
 *
 * <p>This class answers one question for both of those moments — "does
 * {@code ownedIds} (a LIVE read, taken at whatever instant the caller calls
 * this) still contain every id this loadout actually resolves to" — so
 * {@code GearSection} can reuse the exact same check for both: once right
 * before installing a freshly-landed {@code GearOptimizer.Result} (P2-A half
 * 1), and again as a targeted check whenever the player's holdings change
 * while a result is already installed (P2-A half 2), rather than either
 * skipping the second check or blanket-invalidating on every wealth update
 * (which would flicker the panel and discard still-valid results on every
 * unrelated snapshot).
 *
 * <p>Deliberately keyed on the caller-supplied RESOLVED slot-&gt;item-id map
 * (e.g. {@code GearSection#loadoutSlotMap}'s output) rather than the
 * raw {@code GearOptimizer.SlotChoice} list: {@code
 * GearSection#resolvedItemId} is the single choke point that turns a
 * choice into the exact id the panel actually shows/applies/bank-highlights
 * (an owned fortified/imbued variant resolves to the owned variant's id, not
 * the optimiser's plain base id) — validating anything else risks agreeing
 * with a stale/wrong id the user was never actually shown.
 */
public final class OwnedOnlyResultOwnershipGate
{
	private OwnedOnlyResultOwnershipGate()
	{
	}

	/**
	 * The first (slot ordinal, resolved item id) entry in {@code
	 * resolvedLoadout} that {@code ownedIds} does not contain, or empty when
	 * owned-only mode is off or every resolved id in the loadout is still
	 * owned. Iteration order follows {@code resolvedLoadout}'s own order
	 * (callers pass a {@code LinkedHashMap} keyed by slot ordinal), so the
	 * result is deterministic for a given loadout.
	 *
	 * @param ownedOnly whether the ironman "owned gear only" mode is active
	 * @param resolvedLoadout equipment-slot-ordinal -&gt; RESOLVED item-id map
	 *                         for the loadout being validated (see the class
	 *                         javadoc on why this must already be resolved)
	 * @param ownedIds every item id the player currently owns (worn + banked
	 *                  + variant-normalised — see {@code
	 *                  GearSection#ownedPriceMap()}), read live by the caller
	 *                  at the instant of the check
	 */
	public static Optional<Map.Entry<Integer, Integer>> firstUnownedEntry(boolean ownedOnly,
		Map<Integer, Integer> resolvedLoadout, Set<Integer> ownedIds)
	{
		if (!ownedOnly)
		{
			return Optional.empty();
		}
		for (Map.Entry<Integer, Integer> entry : resolvedLoadout.entrySet())
		{
			if (!ownedIds.contains(entry.getValue()))
			{
				return Optional.of(entry);
			}
		}
		return Optional.empty();
	}
}

package com.ospulse.ui.sections.gear;

import java.util.List;

/**
 * Decides how the ranked attack-style rows are arranged: a compact 2-column
 * grid (with the last row spanning the full width when there is an odd one
 * out), or a plain 1-column list when the names simply do not fit.
 *
 * <p><b>Why this is not a fixed choice.</b> The styles list lives in
 * RuneLite's fixed 225px panel — about 211px usable, so ~103px per cell in a
 * 2-column grid. A row must hold an 18px icon, the style name, and the DPS,
 * which leaves roughly 46px of text. Measured against the real font
 * (2026-07-15), 4 of the 33 style names blow that budget outright —
 * {@code Longrange} (52px) and the three chinchompa fuses, {@code Short fuse}
 * (54), {@code Medium fuse} (62), {@code Long fuse} (49). The rest fit.
 *
 * <p>So neither layout is right for every weapon: forcing 2 columns truncates
 * those names, and forcing 1 column doubles the height of the block for the
 * ~29 names that were fine. This picks per weapon, from the rows' own measured
 * widths, so it can never drift when a name or a font changes.
 *
 * <p><b>The odd-row span</b> (Jonathan's suggestion, 2026-07-15) is what saves
 * the common case: a bow ranks Accurate/Rapid/Longrange, and Longrange is
 * almost always the worst of the three, so it lands last and takes the full
 * bottom row where 52px is no problem. Only the PAIRED rows are width-checked
 * — the spanning row gets the whole width and always fits. If a long name ever
 * did rank into a paired slot, the check catches it and falls back to 1 column
 * on its own.
 *
 * <p>Chinchompas are the case the span cannot rescue: all three fuse names are
 * too wide, and only one of them can span. They fall back to 1 column.
 */
public final class StyleGrid
{
	private StyleGrid()
	{
	}

	/**
	 * Whether {@code rowWidths} (in ranked order, each row's own preferred
	 * pixel width) fit a 2-column grid of {@code availableWidth}.
	 *
	 * <p>A single row is reported as NOT fitting: one lonely half-width cell
	 * beside a gap looks like a bug, and full width is both simpler and always
	 * correct for it.
	 */
	public static boolean fitsTwoColumns(List<Integer> rowWidths, int availableWidth, int hgap)
	{
		if (rowWidths.size() < 2)
		{
			return false;
		}
		int cellWidth = (availableWidth - hgap) / 2;
		// The odd row out spans the full width, so it is exempt from the check.
		int paired = rowWidths.size() - (rowWidths.size() % 2);
		for (int i = 0; i < paired; i++)
		{
			if (rowWidths.get(i) > cellWidth)
			{
				return false;
			}
		}
		return true;
	}

	/** Visual row count for {@code rowCount} rows in the chosen layout — drives the viewport height. */
	public static int visualRows(int rowCount, boolean twoColumns)
	{
		return twoColumns ? rowCount / 2 + (rowCount % 2) : rowCount;
	}

	/** Index of the row that spans the full width, or -1 when none does. */
	public static int spanningRowIndex(int rowCount, boolean twoColumns)
	{
		return twoColumns && rowCount % 2 == 1 ? rowCount - 1 : -1;
	}
}

package com.ospulse.ui.sections.gear;

import java.awt.Color;
import java.util.Locale;

/**
 * Formats and colours gp (coin) amounts for the Gear DPS panel. Colour by
 * magnitude per Jonathan's spec: under 100K is yellow, 100K up to just under
 * 10M is white, 10M and above is green (the GearScape {@code #08F67F} green).
 */
public final class GpFormat
{
	public static final Color YELLOW = new Color(240, 220, 90);
	public static final Color WHITE = Color.WHITE;
	public static final Color GREEN = new Color(8, 246, 127);

	private GpFormat()
	{
	}

	/** Colour for a gp amount: {@code <100K} yellow, {@code 100K–<10M} white, {@code >=10M} green. */
	public static Color color(long gp)
	{
		long a = Math.abs(gp);
		if (a >= 10_000_000)
		{
			return GREEN;
		}
		if (a >= 100_000)
		{
			return WHITE;
		}
		return YELLOW;
	}

	/**
	 * Short stacked amount capped at four visible digits: {@code 10B},
	 * {@code 9999M}, {@code 10M}, {@code 1.5M}, {@code 350K}, {@code 999}. Values
	 * that would need a fifth digit as millions (>= 10B) roll over to billions,
	 * so the widest string is "9999M".
	 */
	public static String format(long gp)
	{
		long a = Math.abs(gp);
		if (a >= 10_000_000_000L)
		{
			return (gp / 1_000_000_000L) + "B";
		}
		if (a >= 10_000_000)
		{
			return (gp / 1_000_000) + "M";
		}
		if (a >= 1_000_000)
		{
			return String.format(Locale.ROOT, "%.1fM", gp / 1_000_000.0);
		}
		if (a >= 1_000)
		{
			return String.format(Locale.ROOT, "%.0fK", gp / 1000.0);
		}
		return String.valueOf(gp);
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.model.ItemStack;
import com.ospulse.session.GearSnapshot;
import com.ospulse.wealth.WealthSnapshot;
import com.ospulse.combat.EquipmentIndexRepository;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * The indexed item ids the player PHYSICALLY holds — banked/valued holdings
 * plus worn gear — with NO synthetic variant credit mixed in.
 *
 * <p>This exists because {@code GearSection.ownedPriceMap()} deliberately
 * blends two different facts into one map: ids the player really has, and
 * ids they are merely CREDITED with because they hold a variant of them
 * ({@code addVariantPlainForm} puts the suffix-stripped plain form in at
 * price 0). That blend is exactly right for the optimiser, which only needs
 * to know "can this be equipped for free". It is wrong for the DISPLAY
 * layer, which has to answer a different question: <i>which item does the
 * player actually go and take out of the bank?</i> A credited plain id is
 * not in the bank, so nothing can highlight it and the swap row must not
 * name it as the thing to equip.
 *
 * <p>Deliberately a separate, pure class rather than another private method
 * on {@code GearSection}: that file is already ~6.6k lines, and this is
 * unit-testable without a Swing component.
 */
public final class HeldItemIds
{
	private HeldItemIds()
	{
	}

	/**
	 * Every indexed id present in {@code wealth}'s holdings or worn in
	 * {@code gear}. Mirrors {@code GearSection.ownedPriceMap()}'s two
	 * sources and its {@code getAllHoldings()}-then-{@code getTopHoldings()}
	 * fallback exactly, so "held" can never disagree with "owned" about
	 * where an id came from — it only drops the variant-credit additions.
	 * Ids absent from {@link EquipmentIndexRepository} are skipped for the
	 * same reason the price map skips them: they are not equipment the
	 * optimiser can reason about.
	 */
	public static Set<Integer> from(WealthSnapshot wealth, GearSnapshot gear, EquipmentIndexRepository index)
	{
		Set<Integer> held = new HashSet<>();
		if (wealth != null)
		{
			Collection<ItemStack> stacks = !wealth.getAllHoldings().isEmpty()
				? wealth.getAllHoldings().values()
				: wealth.getTopHoldings();
			for (ItemStack stack : stacks == null ? Collections.<ItemStack>emptyList() : stacks)
			{
				if (stack != null && index.entryFor(stack.getId()) != null)
				{
					held.add(stack.getId());
				}
			}
		}
		if (gear != null)
		{
			for (int id : gear.equippedItemIds())
			{
				if (id > 0 && index.entryFor(id) != null)
				{
					held.add(id);
				}
			}
		}
		return held;
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.EquipmentIndexRepository;
import com.ospulse.combat.Monster;
import com.ospulse.combat.MonsterGearOverride;
import com.ospulse.combat.MonsterGearOverrideRepository;
import com.ospulse.combat.optimizer.GearOptimizer;

import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Which items the gear optimiser may never suggest, which it MUST include,
 * and price-source rules for untradeable-but-buyable items (issue #11 batch
 * extraction — pure logic keyed only off the shared {@link
 * EquipmentIndexRepository}/{@link MonsterGearOverrideRepository} singletons,
 * no {@code GearSection} state).
 */
public final class ItemEligibility
{
	private ItemEligibility()
	{
	}

	/**
	 * Untradeable weapons that are nonetheless "buyable" because they are
	 * crafted directly from ONE tradeable GE ingredient — priced at that
	 * ingredient, overriding the blanket untradeable-=-unpurchasable rule in
	 * {@link #resolveOptimizerPriceSource}. Currently just the Scorching bow
	 * (crafted from a Tormented synapse, id 29580, + a ~1k Magic longbow (u)
	 * at 74 Fletching — the synapse IS the price; both ids verified against
	 * the OSRS Wiki 2026-07-07). The other two synapse weapons are
	 * deliberately NOT mapped: Emberlight's base item (Arclight) is itself
	 * untradeable, and the Purging staff is a magic weapon with no optimiser
	 * demand yet — add entries here only when the full craft cost is
	 * genuinely ~one tradeable ingredient.
	 */
	public static final Map<Integer, Integer> UNTRADEABLE_CRAFT_INGREDIENT =
		Map.of(29591 /* Scorching bow */, 29580 /* Tormented synapse */);

	/**
	 * Wraps a raw (unowned-item) GE price lookup with two rules (bug D):
	 * <ul>
	 *   <li><b>untradeable = unpurchasable:</b> an UNOWNED item flagged
	 *       untradeable by the client-thread-precomputed {@code
	 *       PriceLookup#untradeableIds()} can never be bought, whatever price
	 *       the raw lookup reports — RuneLite's {@code
	 *       ItemManager.getItemPrice} routes some untradeables through {@code
	 *       ItemMapping} to a tradeable proxy (e.g. every trouver-locked
	 *       item, including Dragon defender (l) 24143 and Fire cape (l)
	 *       24223, "costs" the Trouver parchment's ~1m GE price), which made
	 *       the optimiser recommend buying items that cannot be bought.
	 *       Tradeability comes from the precomputed set (the source of
	 *       truth), NOT from a hand-maintained per-item override. Owned
	 *       untradeables never reach this path — they are priced 0 via
	 *       {@code .owned()} directly;</li>
	 *   <li>a resolved price &lt;= 0 means untradeable/unpriced, not free —
	 *       an UNOWNED item you cannot buy is unaffordable ({@link
	 *       Long#MAX_VALUE}), not a bargain;</li>
	 *   <li><b>craftable-from-one-ingredient exception:</b> the few
	 *       untradeables in {@link #UNTRADEABLE_CRAFT_INGREDIENT} price at
	 *       their tradeable ingredient's GE cost INSTEAD of the two rules
	 *       above (checked first) — e.g. the untradeable Scorching bow
	 *       "costs" a Tormented synapse, so the optimiser can recommend it to
	 *       a non-owner and the spend readout shows the real acquisition
	 *       cost rather than the bogus ~1m ItemMapping value or a blanket
	 *       "unbuyable".</li>
	 * </ul>
	 */
	public static GearOptimizer.PriceSource resolveOptimizerPriceSource(GearOptimizer.PriceSource rawPriceSource,
		Set<Integer> untradeableIds)
	{
		return itemId ->
		{
			Integer ingredientId = UNTRADEABLE_CRAFT_INGREDIENT.get(itemId);
			if (ingredientId != null)
			{
				long ingredientPrice = rawPriceSource.priceFor(ingredientId);
				return ingredientPrice > 0 ? ingredientPrice : Long.MAX_VALUE;
			}
			if (untradeableIds.contains(itemId))
			{
				return Long.MAX_VALUE;
			}
			long resolved = rawPriceSource.priceFor(itemId);
			return resolved > 0 ? resolved : Long.MAX_VALUE;
		};
	}

	/**
	 * Matches a parenthesised game-mode marker in an item's display name —
	 * Deadman Mode, Bounty Hunter, Last Man Standing/LMS, or a league beta
	 * cosmetic. These items are not usable by a normal-mode player and must
	 * never be suggested by the optimiser (bug C).
	 */
	private static final Pattern MODE_LOCKED_NAME_PATTERN = Pattern.compile(
		"(?i)\\((deadman mode|deadman|bh|lms|last man standing|beta)\\)");

	/** True when an item's indexed display name carries a mode-locked marker — see {@link #MODE_LOCKED_NAME_PATTERN}. */
	public static boolean isModeLockedItem(String name)
	{
		return name != null && MODE_LOCKED_NAME_PATTERN.matcher(name).find();
	}

	/**
	 * Name suffixes of The Gauntlet's instance-only weapon/armour tiers —
	 * "Crystal/Corrupted X (basic|attuned|perfected)" (ids 23840-23903 +
	 * 30340). These are REAL main-game items but exist only INSIDE the
	 * Gauntlet (made from crystal shards in the instance, unusable/lost the
	 * moment the player leaves), so they can never be equipped against a
	 * normal overworld target and must never be optimiser candidates. Their
	 * names carry no "(deadman)/(lms)"-style mode marker, so {@link
	 * #MODE_LOCKED_NAME_PATTERN} cannot catch them — the suffix IS the
	 * marker. The suffix-less main-game crystal armour ("Crystal helm/body/
	 * legs", distinct ids 23971-23981) is untouched by this rule.
	 */
	private static final String[] GAUNTLET_ONLY_NAME_SUFFIXES = { " (basic)", " (attuned)", " (perfected)" };

	/** True when an item's indexed display name is a Gauntlet-instance-only tier — see {@link #GAUNTLET_ONLY_NAME_SUFFIXES}. */
	public static boolean isGauntletOnlyItem(String name)
	{
		if (name == null)
		{
			return false;
		}
		for (String suffix : GAUNTLET_ONLY_NAME_SUFFIXES)
		{
			if (name.length() >= suffix.length()
				&& name.regionMatches(true, name.length() - suffix.length(), suffix, 0, suffix.length()))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Every indexed item id the player can never actually use against a
	 * normal target — added to the optimiser's exclude set every search,
	 * regardless of price or ownership:
	 * <ul>
	 *   <li>mode-locked names (bug C): Deadman/BH/LMS/beta-only items, which
	 *       the user (not being in those modes) cannot use;</li>
	 *   <li>Gauntlet-instance-only tiers — see
	 *       {@link #GAUNTLET_ONLY_NAME_SUFFIXES}.</li>
	 * </ul>
	 */
	public static Set<Integer> restrictedItemIds()
	{
		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		Set<Integer> ids = new HashSet<>();
		for (Integer id : index.allItemIds())
		{
			EquipmentIndexRepository.Entry entry = index.entryFor(id);
			if (entry != null && (isModeLockedItem(entry.name()) || isGauntletOnlyItem(entry.name())))
			{
				ids.add(id);
			}
		}
		return ids;
	}

	/**
	 * Item ids the optimiser search MUST use for {@code target} (via {@code
	 * GearOptimizer.Request.Builder#include}) — the curated {@link
	 * MonsterGearOverrideRepository} entries for that monster, so a
	 * mechanic-critical item (e.g. Insulated boots vs Rune dragons) can never
	 * be dropped by DPS ranking. A user's explicit slot exclusion still wins
	 * (an item present in {@code exclusions} is left out of the forced set
	 * rather than fighting the exclude list).
	 *
	 * <p>Outside owned-only mode this always forces the primary {@link
	 * MonsterGearOverride#itemId()} — an unaffordable force-include there is
	 * a legitimate purchase suggestion, and the player may simply buy it. In
	 * owned-only mode it forces whichever id {@link
	 * OwnedOnlyMandatoryOverrideGate#ownedOnlySatisfyingItemId} says actually
	 * satisfies the requirement — the owned alternative (e.g. a Slayer
	 * helmet the player owns for a Dust devil's Facemask requirement) when
	 * the primary isn't owned, so {@code GearOptimizer.applyForcedIncludes}
	 * can never force-equip an unowned item that {@link
	 * OwnedOnlyMandatoryOverrideGate#blockingOverride} agreed the target was
	 * satisfied for. When neither the primary nor any alternative is owned,
	 * this still returns the primary — but that case is exactly what {@link
	 * OwnedOnlyMandatoryOverrideGate#blockingOverride} refuses the target
	 * for before a result reaches the player, so the unowned id is never
	 * actually shown/equipped.
	 *
	 * @param ownedOnly whether the ironman "owned gear only" mode is active
	 * @param ownedIds every item id the player currently owns — only
	 *                  consulted when {@code ownedOnly} is true
	 */
	public static Set<Integer> mandatoryOverrideItemIds(Monster target, Set<Integer> exclusions,
		boolean ownedOnly, Set<Integer> ownedIds)
	{
		if (target == null)
		{
			return Collections.emptySet();
		}
		Set<Integer> ids = new LinkedHashSet<>();
		for (MonsterGearOverride override : MonsterGearOverrideRepository.getInstance().forMonster(target.lookupName()))
		{
			int id = ownedOnly
				? OwnedOnlyMandatoryOverrideGate.ownedOnlySatisfyingItemId(override, ownedIds)
				: override.itemId();
			if (!exclusions.contains(id))
			{
				ids.add(id);
			}
		}
		return ids;
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.OSPulseConfig;
import net.runelite.client.config.ConfigManager;

/**
 * Owns every {@link ConfigManager} read/write for the ironman "owned gear
 * only" flag's per-account scheme — see {@link IronmanOwnedOnlyResolver} for
 * the pure merged-read/echo decisions this class calls into.
 *
 * <p>Three raw keys under {@link OSPulseConfig#GROUP}:
 * <ul>
 *   <li>{@link #KEY} scoped per-RS-profile (the authoritative per-account
 *       value) via {@code getRSProfileConfiguration}/{@code
 *       setRSProfileConfiguration};</li>
 *   <li>{@link #KEY} client-wide (the {@code @ConfigItem} checkbox) — an
 *       edit surface / display mirror only, via plain {@code
 *       getConfiguration}/{@code setConfiguration};</li>
 *   <li>{@link #DEFAULT_KEY} client-wide, hidden (no {@code @ConfigItem}) —
 *       the user's global preference for accounts with no per-profile value
 *       yet.</li>
 * </ul>
 *
 * <p><b>Echo latch:</b> {@link #mirrorToClientWide} writes the resolved
 * effective value into the client-wide checkbox so the settings panel shows
 * the truth for whichever account is logged in. That write fires its own
 * {@code ConfigChanged} (indistinguishable by {@code getProfile()} from a
 * real user toggle — both are client-wide writes with a {@code null}
 * profile, verified against the {@code ConfigManager} bytecode; only a
 * profile-SCOPED write carries a non-null profile). {@link
 * #mirrorToClientWide} arms the value it's about to write immediately before
 * writing it, and {@link #consumeMirrorEcho} lets the caller swallow the
 * first matching client-wide event as that write's own echo rather than a
 * user toggle. The latch is only armed when {@link
 * IronmanOwnedOnlyResolver#needsMirrorWrite} is true (see {@link
 * #mirrorToClientWide}) — arming it for a write that would be a no-op would
 * never see a matching event, leaving the latch stuck armed to wrongly
 * swallow a later genuine toggle. If the latch is ever consumed by
 * coincidence rather than the real echo (e.g. some other write races in with
 * the exact same value), the swallowed value already equals what's stored,
 * so there is no visible harm — the checkbox already reads correctly either
 * way.
 */
public final class IronmanOwnedOnlyStore
{
	/** Mirrors {@link OSPulseConfig#ironmanOwnedOnly()}'s {@code keyName} — used both per-profile and client-wide (see class javadoc). */
	public static final String KEY = "ironmanOwnedOnly";
	/** Client-wide, hidden (no {@code @ConfigItem}) global-preference key — see class javadoc. */
	public static final String DEFAULT_KEY = "ironmanOwnedOnlyDefault";

	private final ConfigManager configManager;

	/** Echo latch: the raw value a {@link #mirrorToClientWide} write is expecting to see echo back, or {@code null} when unarmed. */
	private String armedMirrorValue;

	public IronmanOwnedOnlyStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/** The current account's raw per-profile value, or {@code null} if not logged in or never decided for this profile. */
	public String rawProfileValue()
	{
		String profileKey = configManager.getRSProfileKey();
		return profileKey != null ? configManager.getRSProfileConfiguration(OSPulseConfig.GROUP, KEY) : null;
	}

	/** The merged effective read for whichever account is currently logged in (or the global default alone, logged out) — see {@link IronmanOwnedOnlyResolver#resolve}. */
	public boolean resolveEffective()
	{
		String rawDefault = configManager.getConfiguration(OSPulseConfig.GROUP, DEFAULT_KEY);
		return IronmanOwnedOnlyResolver.resolve(rawProfileValue(), rawDefault);
	}

	/**
	 * Auto-detect's one-time write (issue #11): the per-profile key ONLY,
	 * never the client-wide value — this is what keeps an ironman alt's
	 * auto-enable from leaking onto a main sharing the same client. Caller
	 * ({@code OSPulsePlugin#checkIronmanAutoDetect}) already gates this on
	 * {@link IronmanAutoDetect#needsEvaluation}/{@link
	 * IronmanAutoDetect#shouldAutoEnable}.
	 */
	public void writeAutoDetected(boolean value)
	{
		configManager.setRSProfileConfiguration(OSPulseConfig.GROUP, KEY, value);
	}

	/**
	 * A genuine user toggle of the client-wide checkbox (a real, non-echo
	 * {@code ConfigChanged} on {@link #KEY} — the caller is responsible for
	 * having already ruled out a profile-scoped write and a mirror echo, see
	 * class javadoc): writes the current account's per-profile value AND the
	 * global default, so the next never-decided account still inherits the
	 * user's latest explicit choice. When not logged in (no RS profile key),
	 * only the global default is written.
	 */
	public void writeUserToggle(boolean value)
	{
		String profileKey = configManager.getRSProfileKey();
		if (profileKey != null)
		{
			configManager.setRSProfileConfiguration(OSPulseConfig.GROUP, KEY, value);
		}
		configManager.setConfiguration(OSPulseConfig.GROUP, DEFAULT_KEY, value);
	}

	/**
	 * Re-mirrors the resolved effective value into the client-wide checkbox
	 * (called on login and RS profile change — {@code OSPulsePlugin}) so the
	 * settings panel reflects the truth for the account now logged in. Only
	 * writes when the stored client-wide value actually differs (see {@link
	 * IronmanOwnedOnlyResolver#needsMirrorWrite}), arming the echo latch
	 * immediately beforehand — the write's own {@code ConfigChanged} fires
	 * synchronously within {@code setConfiguration}, so by the time this
	 * method returns the latch has already been consumed by the nested
	 * {@code onConfigChanged} call.
	 */
	public void mirrorToClientWide()
	{
		boolean effective = resolveEffective();
		String rawClientWide = configManager.getConfiguration(OSPulseConfig.GROUP, KEY);
		if (!IronmanOwnedOnlyResolver.needsMirrorWrite(rawClientWide, effective))
		{
			return;
		}
		armedMirrorValue = String.valueOf(effective);
		configManager.setConfiguration(OSPulseConfig.GROUP, KEY, effective);
	}

	/**
	 * Consumes a client-wide (profile-{@code null}) {@code ConfigChanged}
	 * event on {@link #KEY} if it matches the armed {@link
	 * #mirrorToClientWide} echo: disarms the latch and returns {@code true}
	 * (caller must NOT treat this as a user toggle). Returns {@code false}
	 * (latch left as-is) for anything else, meaning the caller should treat
	 * it as a genuine user toggle.
	 */
	public boolean consumeMirrorEcho(String eventNewValue)
	{
		if (IronmanOwnedOnlyResolver.isMirrorEcho(armedMirrorValue, eventNewValue))
		{
			armedMirrorValue = null;
			return true;
		}
		return false;
	}

	/** Test seam: whether the echo latch is currently armed. */
	boolean isEchoLatchArmedForTest()
	{
		return armedMirrorValue != null;
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.Monster;
import com.ospulse.combat.MonsterGearOverride;
import com.ospulse.combat.MonsterGearOverrideRepository;

import java.util.Optional;
import java.util.Set;

/**
 * Pure decision logic for the P1-A fix (Codex finding on PR #19, {@code
 * GearSection.java:4602}, "Restrict mandatory includes in owned-only mode").
 *
 * <p>{@code GearOptimizer} force-includes a curated {@link
 * MonsterGearOverride}'s item id past the budget filter and force-equips it
 * into the recommended loadout regardless of ownership or price — a real,
 * deliberate behaviour (these are mechanical/safety requirements like Rune
 * dragons' Insulated boots, not DPS suggestions: silently dropping one would
 * produce a result that LOOKS owned-only-safe and isn't). In every mode
 * except owned-only, that is fine: an unaffordable force-include is a real
 * purchase suggestion. In owned-only mode specifically it is not — the
 * mode's entire guarantee is that every recommendation is something the
 * player already owns, and a forced item the player owns neither the
 * primary form of nor any {@link MonsterGearOverride#alternativeItemIds()}
 * substitute for breaks that guarantee outright.
 *
 * <p>The earlier attempt at this finding only disclosed the gap (an
 * advisory line added by {@code GearSection#updateGearOverrideNote()}
 * appending "you don't own this"). Codex escalated that to P1 as
 * insufficient: a warning elsewhere in the panel does not stop the loadout,
 * the auto-applied preview, or the bank highlight from still recommending
 * the unowned item. This class instead answers "should owned-only mode
 * refuse to recommend anything at all for this target" — {@code
 * GearSection#onOptimizerResult} uses it to short-circuit into an explicit
 * blocked state (mirroring the existing "no usable weapon" cannot-recommend
 * path) rather than filtering the override out and returning a loadout that
 * silently skips a mechanical requirement.
 *
 * <p>Deliberately free of any {@code GearSection} state, matching {@link
 * OwnedOnlyMode} / {@link IronmanOwnedOnlyResolver}'s shape: callers pass in
 * whatever target/ownership inputs they hold rather than this class reaching
 * into private mutable fields.
 *
 * <p>{@link #ownedOnlySatisfyingItemId} is the single source of truth for
 * "which owned id (if any) satisfies this override" — both {@link
 * #blockingOverride} (should owned-only mode refuse this target outright)
 * and {@code ItemEligibility#mandatoryOverrideItemIds} (which id owned-only
 * mode's force-include should actually inject) are derived from it, so the
 * two questions cannot disagree the way they did before this fix: the gate
 * accepted an owned alternative (e.g. a Slayer helmet for a Dust devil's
 * Facemask requirement) as satisfying the requirement and let the result
 * through, while the force-include path kept injecting the unowned primary
 * — equipping an item owned-only mode had just promised was never going to
 * happen.
 */
public final class OwnedOnlyMandatoryOverrideGate
{
	private OwnedOnlyMandatoryOverrideGate()
	{
	}

	/**
	 * The first mandatory {@link MonsterGearOverride} for {@code target} that
	 * owned-only mode cannot satisfy — the player owns neither {@link
	 * MonsterGearOverride#itemId()} nor any of {@link
	 * MonsterGearOverride#alternativeItemIds()} — or empty when owned-only
	 * mode is off, no target is selected, or every mandatory override (if
	 * any) is satisfied by something owned. Same substitution rule {@code
	 * GearSection#updateGearOverrideNote()} already uses for its "you don't
	 * own this" disclosure.
	 *
	 * @param ownedOnly whether the ironman "owned gear only" mode is active
	 * @param target the currently selected monster, or {@code null} if none
	 * @param ownedIds every item id the player currently owns (worn + banked
	 *                  + variant-normalised — see {@code GearSection#ownedPriceMap()})
	 */
	public static Optional<MonsterGearOverride> blockingOverride(boolean ownedOnly, Monster target, Set<Integer> ownedIds)
	{
		if (!ownedOnly || target == null)
		{
			return Optional.empty();
		}
		for (MonsterGearOverride override : MonsterGearOverrideRepository.getInstance().forMonster(target.lookupName()))
		{
			if (!ownedIds.contains(ownedOnlySatisfyingItemId(override, ownedIds)))
			{
				return Optional.of(override);
			}
		}
		return Optional.empty();
	}

	/**
	 * The item id that satisfies {@code override} under owned-only mode given
	 * {@code ownedIds}: the owned alternative when the primary {@link
	 * MonsterGearOverride#itemId()} isn't owned but one of {@link
	 * MonsterGearOverride#alternativeItemIds()} is, otherwise the primary
	 * itself (whether owned or not — an unowned return here is exactly what
	 * makes {@link #blockingOverride} refuse the target, and is also what
	 * {@code ItemEligibility#mandatoryOverrideItemIds} force-includes outside
	 * owned-only mode, where an unaffordable force-include is a legitimate
	 * purchase suggestion rather than a broken guarantee).
	 */
	static int ownedOnlySatisfyingItemId(MonsterGearOverride override, Set<Integer> ownedIds)
	{
		if (!ownedIds.contains(override.itemId()))
		{
			for (Integer alternativeId : override.alternativeItemIds())
			{
				if (ownedIds.contains(alternativeId))
				{
					return alternativeId;
				}
			}
		}
		return override.itemId();
	}
}

package com.ospulse.ui.sections.gear;

/**
 * Pure decision logic for auto-enabling the ironman "owned gear only"
 * optimiser mode (issue #11) the first time an ironman-type account is seen
 * on a given RS profile.
 *
 * <p>A {@code @ConfigItem} default is a compile-time constant, so it can't
 * itself depend on the runtime account type — a first-login write is the
 * only way to default the setting ON for an ironman. This class holds only
 * the decision, never touching any RuneLite API directly (no {@code Client}
 * / {@code ConfigManager}), so it is trivially unit-testable without
 * mocking either. The caller ({@code OSPulsePlugin}) owns the actual reads/
 * writes (via {@link IronmanOwnedOnlyStore}) and the RS-profile-scoped
 * bookkeeping key that gates how often {@link #shouldAutoEnable} is even
 * consulted.
 */
public final class IronmanAutoDetect
{
	private IronmanAutoDetect()
	{
	}

	/**
	 * Whether this RS profile still needs its one-time auto-detect
	 * evaluation. {@code rawAutoDetectMarker} is the raw, per-RS-profile
	 * bookkeeping value (the caller's own {@code getRSProfileConfiguration}
	 * read) — {@code null} the first time this profile is ever seen after
	 * login, non-null forever after regardless of outcome. This is NOT the
	 * {@code ironmanOwnedOnly} value itself; it only tracks whether the
	 * one-time check has already run for this profile, so an ironman alt and
	 * a main sharing one client each get their own independent evaluation
	 * instead of one profile's "already decided" state blocking the other's.
	 */
	public static boolean needsEvaluation(String rawAutoDetectMarker)
	{
		return rawAutoDetectMarker == null;
	}

	/**
	 * Whether the {@code ironmanOwnedOnly} flag should be auto-enabled for
	 * this account. Only ever meaningful when {@link #needsEvaluation} was
	 * true for this profile, and only ever true when the flag has never been
	 * explicitly set for THIS account ({@code rawOwnedOnlyValue == null} — an
	 * explicit {@code "false"} means the user deliberately turned it off and
	 * must never be silently re-enabled) and the logged-in account is some
	 * ironman variant.
	 *
	 * <p>{@code rawOwnedOnlyValue} is this account's raw PER-PROFILE value
	 * (see {@link IronmanOwnedOnlyStore#rawProfileValue()}) — per the
	 * per-account scheme, auto-detect only ever reads/writes the per-profile
	 * key, never the client-wide {@code @ConfigItem}, so an ironman alt's
	 * auto-enable can never leak onto a main sharing the same client.
	 */
	public static boolean shouldAutoEnable(String rawOwnedOnlyValue, boolean accountIsIronman)
	{
		return rawOwnedOnlyValue == null && accountIsIronman;
	}
}

package com.ospulse.ui.sections.gear;

/**
 * Pure glyph/visibility logic for a single clickable "▸"/"▾"
 * collapsible heading (issue #11's "Excluded from suggestions" list) —
 * mirrors {@code LootSection}'s per-row collapse-triangle idiom, but for one
 * section-wide toggle rather than a triangle per row.
 *
 * <p>Composes with a panel's pre-existing empty-list self-hide: an empty list
 * has nothing to collapse (the whole panel hides, same as before this
 * feature existed), while a collapsed non-empty list keeps its heading up
 * (so the user can expand it again) but hides the body below it. Kept free of
 * any Swing/{@code GearSection} state so it is trivially unit-testable.
 */
public final class CollapsibleHeading
{
	private CollapsibleHeading()
	{
	}

	private static final String EXPANDED_GLYPH = "▾"; // ▾
	private static final String COLLAPSED_GLYPH = "▸"; // ▸

	/** The heading text to display, e.g. {@code "▾ Excluded from suggestions"}. */
	public static String headingText(String label, boolean collapsed)
	{
		return (collapsed ? COLLAPSED_GLYPH : EXPANDED_GLYPH) + " " + label;
	}

	/**
	 * Whether the collapsible body (below the heading) should render. An
	 * empty list always hides the body (nothing to show); a non-empty list
	 * shows it unless collapsed.
	 */
	public static boolean bodyVisible(boolean hasItems, boolean collapsed)
	{
		return hasItems && !collapsed;
	}
}

package com.ospulse.ui.sections.gear;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.LongUnaryOperator;

/**
 * When a variant's ownership credit should be WITHDRAWN so the ordinary
 * counterpart can be bought instead.
 *
 * <p>One item id cannot carry two different (ownership, risk) pairs. The
 * credit marks the plain id owned and free, and {@code VariantCreditSources}
 * makes it inherit the held variant's risk — correct, because that variant is
 * what the player would actually wear and lose. But it collapses a real
 * choice: with the held variant above the expensive-item threshold and the
 * ordinary counterpart below it <b>and affordable</b>, the optimiser can no
 * longer represent "buy a separate ordinary copy". The single candidate is
 * owned-but-over-cap, so the cap can only drop the slot or take worse gear,
 * even though the budget would cover the safe alternative.
 *
 * <p>Rather than teach the optimiser to hold two candidates per slot — its
 * per-slot candidates are bare item ids — the credit is withdrawn in exactly
 * the case where it does more harm than good. The plain id then behaves as an
 * ordinary purchase: priced at its own gp, risked at its own value, and shown
 * as the not-owned suggestion it is. When the condition does not hold nothing
 * changes, so the credit keeps working for every player it helps.
 *
 * <p>All five conditions must hold, and each rules out a case where
 * withdrawing would make things worse:
 * <ul>
 *   <li><b>the cap is active</b> — with no cap there is nothing to de-risk
 *   for, and withdrawing would only make free gear cost money. Decided by
 *   {@code GearOptimizer.expensiveCapActive}, never re-derived here: the
 *   allowance must be compared against the 11 SEARCHABLE slots, not the 14
 *   equipment slots, or this reports the cap active while the optimiser has
 *   it disabled;</li>
 *   <li><b>the allowance is zero</b> — the cap permits {@code
 *   expensiveItemCount} items above the threshold, so with any allowance at
 *   all the held variant may legitimately fit, and withdrawing would spend
 *   the player's budget on a copy they did not need. Worse, withdrawing
 *   several credits at once can make a compliant mixed keep-some/buy-some
 *   loadout unrepresentable. Only at zero can NO over-threshold item be worn,
 *   which is the one case where the credit is certainly useless;</li>
 *   <li><b>the held variant is over the threshold</b> — otherwise the credit
 *   is already safe and free, which is strictly better than buying;</li>
 *   <li><b>the counterpart is at or under the threshold</b> — buying an
 *   equally risky copy solves nothing and just spends the budget;</li>
 *   <li><b>the counterpart is affordable</b> — a purchase the budget cannot
 *   cover is not an alternative at all, and withdrawing would leave the slot
 *   empty for no gain.</li>
 * </ul>
 */
public final class RiskCreditPolicy
{
	private RiskCreditPolicy()
	{
	}

	/**
	 * The credited plain ids whose credit should be withdrawn so they can be
	 * purchased instead — see the class javadoc for why each condition is
	 * required.
	 *
	 * @param creditSources credited plain id -&gt; held variant id, from
	 *                      {@link VariantCreditSources}
	 * @param riskValueOf   an id's gp risk value (the variant's own value for
	 *                      a variant id; the counterpart's own value for the
	 *                      plain id — NOT the credit-remapped lookup, which
	 *                      would report the variant's value for both and make
	 *                      the comparison vacuous)
	 * @param priceOf       an id's purchase price
	 * @param capActive     whether the expensive-item cap can bind at all —
	 *                      pass {@code GearOptimizer.expensiveCapActive}'s
	 *                      verdict rather than re-deriving it
	 * @param allowance     how many over-threshold items the cap permits
	 * @param threshold     the cap's gp threshold
	 * @param budget        the search's gp budget
	 */
	public static Set<Integer> withdrawnForSaferPurchase(Map<Integer, Integer> creditSources,
		LongUnaryOperator riskValueOf, LongUnaryOperator priceOf, boolean capActive, int allowance,
		long threshold, long budget)
	{
		Set<Integer> withdrawn = new HashSet<>();
		if (!capActive || allowance > 0 || creditSources.isEmpty())
		{
			return withdrawn;
		}
		for (Map.Entry<Integer, Integer> credit : creditSources.entrySet())
		{
			int plainId = credit.getKey();
			int variantId = credit.getValue();
			if (riskValueOf.applyAsLong(variantId) > threshold
				&& riskValueOf.applyAsLong(plainId) <= threshold
				&& priceOf.applyAsLong(plainId) <= budget)
			{
				withdrawn.add(plainId);
			}
		}
		return withdrawn;
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.CombatStyle;

/**
 * The display label for a {@link CombatStyle} damage type (issue #11 batch
 * extraction — a pure lookup table, no {@code GearSection} state).
 */
public final class CombatStyleLabel
{
	private CombatStyleLabel()
	{
	}

	public static String of(CombatStyle type)
	{
		switch (type)
		{
			case STAB:
				return "Stab";
			case SLASH:
				return "Slash";
			case CRUSH:
				return "Crush";
			case RANGED:
				return "Ranged";
			case MAGIC:
				return "Magic";
			default:
				return type.name();
		}
	}
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.SpecWeaponRecommendation;

import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

import javax.swing.JLabel;
import javax.swing.SwingConstants;
import java.awt.Cursor;
import java.awt.Dimension;

/**
 * The "best spec weapon" cell in the Gear section's equipment grid (design
 * spec §8 — placed at the unused flat filler slot directly below WEAPON and
 * above GLOVES; see {@code GearSection}'s {@code SLOT_GRID}).
 *
 * <p>Deliberately its OWN small class with its OWN {@link JLabel} and its OWN
 * diff-guard ({@link #renderedItemId}), entirely separate from {@code
 * GearSection}'s {@code slotLabels[]}/{@code renderedSlotIds[]} arrays: this
 * is a pseudo-slot with no {@code EquipmentInventorySlot} ordinal, and those
 * two arrays are sized and indexed by the 14 REAL ordinals
 * ({@code GearSnapshot.EQUIPMENT_SLOT_COUNT}) — squatting on an unused
 * ordinal there would silently break whichever real slot happened to claim
 * it next. Parallel plumbing, not shared plumbing.
 */
public final class SpecWeaponCell extends JLabel {
    /** Diff-guard, mirroring {@code GearSection.renderedSlotIds}' role for the real slots: avoids re-fetching the same sprite every refresh. */
    private int renderedItemId = Integer.MIN_VALUE;

    public SpecWeaponCell(int slotWidth, int slotHeight) {
        setOpaque(true);
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setHorizontalAlignment(SwingConstants.CENTER);
        setVerticalAlignment(SwingConstants.CENTER);
        setPreferredSize(new Dimension(slotWidth, slotHeight));
        setCursor(Cursor.getDefaultCursor());
        setToolTipText(noTargetTooltip());
    }

    /**
     * Rebuilds this cell for {@code recommendation} ({@code null} = either no
     * target selected, or a target IS selected but nothing owned+legal
     * qualifies — see {@code SpecWeaponSelector}). {@code targetSelected}
     * disambiguates those two {@code null} cases (PR #25 finding) so the
     * tooltip never tells a player who already picked a target, and simply
     * owns no eligible spec weapon for it, to go pick a target — a false
     * remedy. {@code itemManager} may be {@code null} in headless tests, in
     * which case the icon is skipped but the tooltip still updates (mirrors
     * {@code GearSection.updateGearGrid}'s own null-safety).
     */
    public void refresh(SpecWeaponRecommendation recommendation, boolean targetSelected, ItemManager itemManager) {
        int id = recommendation == null ? -1 : recommendation.itemId();
        if (recommendation != null) {
            setToolTipText(recommendation.readoutText());
        } else {
            setToolTipText(targetSelected ? noEligibleWeaponTooltip() : noTargetTooltip());
        }
        if (id == renderedItemId) {
            return;
        }
        renderedItemId = id;
        if (id > 0 && itemManager != null) {
            // EDT-safe: getImage is async (AsyncBufferedImage), the ONLY
            // ItemManager call permitted off the client thread — same as
            // every other slot cell in GearSection.
            itemManager.getImage(id).addTo(this);
        } else {
            setIcon(null);
        }
    }

    private static String noTargetTooltip() {
        return "Best spec weapon — pick a target to see a recommendation";
    }

    /** PR #25 finding: distinct from {@link #noTargetTooltip()} — a target IS selected, but nothing the player owns qualifies. */
    private static String noEligibleWeaponTooltip() {
        return "Best spec weapon — no owned, equippable, legal spec weapon qualifies for this target";
    }

    /** Test seam: the item id this cell last rendered (or {@code -1}/{@code Integer.MIN_VALUE} before any refresh). */
    public int renderedItemIdForTest() {
        return renderedItemId;
    }
}

package com.ospulse.ui.sections.gear;

import com.ospulse.combat.EquipmentIndexRepository;
import com.ospulse.combat.EquipmentRequirementsRepository;
import com.ospulse.combat.EquipmentStatsRepository;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Fortified/imbued cosmetic-or-charged variant suffixes (e.g. Masori
 * armour's " (f)" fortify, a ring's " (i)" imbue) and the two-way mapping
 * between a variant's name and its plain base form that {@link
 * com.ospulse.ui.sections.GearSection}'s ownership/recommendation logic
 * needs:
 * <ul>
 *   <li><b>ownership</b> — owning the VARIANT also counts as owning the
 *   plain base form, so the optimiser doesn't suggest "upgrading" to an item
 *   the player already effectively has (see {@link #plainFormId}, used by
 *   {@code GearSection#addVariantPlainForm});</li>
 *   <li><b>display</b> — when a recommendation resolves to the plain base
 *   form because that's the id the ownership check above marked owned, the
 *   UI should still show the actual OWNED variant's name/icon, not the
 *   plain one — {@link #preferOwnedVariant} is the reverse lookup for
 *   that.</li>
 * </ul>
 *
 * <p><b>Name collisions carry two DIFFERENT relationships, not one</b> (P1
 * fix, issue #11 Stage 3 follow-up): several display names are shared by
 * more than one backing id ({@link EquipmentIndexRepository#idsForName}),
 * and this class must not treat every such group the same way.
 * <ul>
 *   <li><i>Reward-source/charge duplicates</i> (an imbued ring's three
 *   quest-source copies, Black mask's 0-10 charge levels, the two Imbued god
 *   cape ids per god): every member shares IDENTICAL combat stats AND
 *   IDENTICAL equip requirements — picking any one of them is always safe,
 *   so the historical "first in file order" behaviour is kept for these.</li>
 *   <li><i>Genuinely different items sharing a name</i> — Deadman-mode
 *   crystal helm/body/legs each have an ACTIVE id (real combat stats) and an
 *   INACTIVE id (all-zero stats, cosmetically deactivated) that share the
 *   SAME plain "Crystal body"/"Crystal helm"/"Crystal legs" name. Picking
 *   the first file-order id here is wrong: owning the zero-stat inactive
 *   deadman piece must never credit the fully-statted active plain id (the
 *   optimiser would then compute and recommend DPS the player cannot
 *   actually achieve), and the reverse display lookup must never show the
 *   zero-stat inactive icon for a result actually calculated off the active
 *   id's real stats.</li>
 *   <li><i>Combat-stat-identical but requirement-different</i> — a subtler
 *   variant of the above: Deadman-mode Imbued god capes and the Dark bow's
 *   several reward duplicates are combat-stat-IDENTICAL across every field
 *   {@link EquipmentStatsRepository} models, yet differ on recorded equip
 *   requirement (e.g. two "Imbued saradomin cape" ids, one requiring magic
 *   75 and one with no recorded requirement — {@code
 *   equipment_requirements.min.json}). Stats alone made these look like safe
 *   "any pick is fine" duplicates; picking file order here would silently
 *   drop the level gate and recommend/credit gear the player cannot actually
 *   equip. Requirements are therefore checked as a second, independent
 *   dimension alongside stats — see {@link #isHomogeneous}.</li>
 * </ul>
 * Both {@link #plainFormId} and {@link #preferOwnedVariant} now detect which
 * case applies via {@link #resolveByStatMatch} / {@link #isHomogeneous}: a
 * name-sharing group is resolved by position ONLY when every member is
 * BOTH stat-identical and requirement-identical (safe by construction);
 * otherwise the specific member whose stats AND requirements match the item
 * on the OTHER side of the mapping is required, and {@code null}/the
 * original id (no credit, no substitution) is returned when no exact match
 * exists — over-crediting ownership the player cannot actually reach, or
 * bypassing a level gate, is the real harm, and a missing credit is visibly
 * absent while a wrong one looks modelled.
 */
public final class OwnedVariantResolver
{
	/**
	 * Space-prefixed variant suffixes, as they appear at the end of an
	 * {@link EquipmentIndexRepository.Entry#name()}. " (deadman)" covers
	 * Deadman Mode reward duplicates (e.g. "Imbued saradomin cape
	 * (deadman)") — most are stat-identical to a real, non-mode-locked
	 * counterpart item, but Deadman crystal armour's active/inactive split
	 * is NOT (see the class javadoc) — {@code
	 * GearSection.restrictedItemIds()} always excludes the "(deadman)" id
	 * itself from optimiser candidates (by design, regardless of
	 * ownership), so without this suffix, owning one never credits the
	 * player with owning its real, recommendable counterpart, and the
	 * optimiser falls back to a worse candidate.
	 */
	public static final String[] SUFFIXES = { " (f)", " (i)", " (deadman)" };

	/**
	 * Curated alias for a suffix-stripped plain name that has NO indexed entry
	 * at all under its own name, but still has a stat-matching counterpart
	 * under a genuinely DIFFERENT display name (every other suffix case —
	 * see {@link #SUFFIXES} — already lands on the right name once stripped,
	 * so this table is the exception, not the rule).
	 *
	 * <p><b>"Toxic staff (deadman)"</b> (ids 33035/33036, {@code
	 * net.runelite.api.gameval.ItemID.TOXIC_SOTD_DEADMAN}/{@code
	 * _CHARGED_DEADMAN}) strips to "Toxic staff", which isn't indexed under
	 * any id in the bundled {@code equipment_index.min.json} — the real item
	 * is named "Toxic staff of the dead" (12902 uncharged/12904 charged,
	 * {@code ItemID.TOXIC_SOTD}/{@code _CHARGED}), whose two ids are NOT
	 * stat-identical (uncharged amagic +17 vs. charged amagic +25 in {@code
	 * equipment_stats.min.json}) but exactly stat-match 33035/33036
	 * respectively — the same heterogeneous-name-collision shape as Deadman
	 * crystal armour, just with the collision landing on a different name
	 * than a plain suffix-strip finds. A survey of every {@link #SUFFIXES}
	 * suffix across the entire bundled index (see {@code
	 * OwnedVariantResolverTest}) found this is the ONLY suffix-stripped name
	 * with zero indexed entries, so a single curated alias is used here
	 * rather than a general renaming rule.
	 */
	private static final Map<String, String> UNINDEXED_PLAIN_NAME_ALIASES =
		Collections.singletonMap("toxic staff", "Toxic staff of the dead");

	private OwnedVariantResolver()
	{
	}

	/**
	 * The plain (suffix-stripped) form's item id for {@code variantItemId}, or
	 * {@code null} if the item isn't indexed, its name doesn't end in a known
	 * variant suffix, neither the plain form nor its {@link
	 * #UNINDEXED_PLAIN_NAME_ALIASES} counterpart is indexed, or the resolved
	 * name maps to more than one id that differs in stats and/or equip
	 * requirements and none of them matches {@code variantItemId}'s own stats
	 * AND requirements (see class javadoc) — crediting nothing is safer than
	 * guessing which one the player can actually reach.
	 */
	public static Integer plainFormId(EquipmentIndexRepository index, int variantItemId)
	{
		EquipmentIndexRepository.Entry entry = index.entryFor(variantItemId);
		if (entry == null)
		{
			return null;
		}
		String name = entry.name();
		for (String suffix : SUFFIXES)
		{
			if (name.regionMatches(true, name.length() - suffix.length(), suffix, 0, suffix.length()))
			{
				String plainName = name.substring(0, name.length() - suffix.length());
				List<Integer> candidates = index.idsForName(plainName);
				if (candidates.isEmpty())
				{
					String alias = UNINDEXED_PLAIN_NAME_ALIASES.get(plainName.toLowerCase(Locale.ROOT));
					if (alias != null)
					{
						candidates = index.idsForName(alias);
					}
				}
				return resolveByStatMatch(index, candidates, variantItemId);
			}
		}
		return null;
	}

	/**
	 * The item id that should actually be DISPLAYED (and, by the caller's own
	 * choice, applied) for a recommendation that resolved to {@code itemId}:
	 * if {@code itemId} is a plain base form and {@code ownedIds} genuinely
	 * contains one of its variants' ids, returns an owned, non-excluded
	 * variant id instead — so a recommendation that's really "you already own
	 * Masori mask (f)" shows that name/icon, not the plain "Masori mask" the
	 * optimiser matched candidates against. Falls back to {@code itemId}
	 * unchanged when no such owned variant applies (including when
	 * {@code itemId} is already a variant, owns nothing extra, or the only
	 * owned variant is in {@code excludedItemIds}).
	 *
	 * <p><b>Excluded variants are never returned</b> (a caller-supplied
	 * {@code excludedItemIds}): if the player right-clicked "Exclude from
	 * suggestions" on their own owned variant, the optimiser correctly falls
	 * back to the plain form as its recommendation, and remapping the display
	 * back to the excluded item would silently defeat that exclusion — the
	 * excluded item would reappear under a different id's row. Showing the
	 * plain name in that case is the honest answer: it really is what the
	 * optimiser is proposing.
	 *
	 * <p><b>Name collisions:</b> {@link EquipmentIndexRepository#idForName}
	 * keeps only one id per display name, but several variant names
	 * genuinely have more than one backing id (e.g. an imbued ring or a
	 * slayer helmet has one id per reward source/quest). This method checks
	 * {@link EquipmentIndexRepository#idsForName} — every id sharing the
	 * variant's name — not just the first, so owning a different reward-
	 * source copy of the same-named variant still resolves correctly.
	 *
	 * <p><b>Stat- or requirement-different name collisions</b> (Deadman
	 * crystal armour's active/inactive split, or Deadman god capes'/Dark
	 * bow's requirement-only differences — see class javadoc): when the
	 * variant NAME's ids are not all both stat- and requirement-identical,
	 * only an owned id whose stats AND requirements match {@code itemId}'s
	 * own is substituted — never a wrong-state or wrong-level-gate duplicate
	 * (e.g. an owned zero-stat inactive deadman piece must never be
	 * displayed for a result actually calculated off the fully-statted
	 * active plain id).
	 */
	public static int preferOwnedVariant(EquipmentIndexRepository index, int itemId, Map<Integer, Long> ownedIds,
		Set<Integer> excludedItemIds)
	{
		if (ownedIds == null || ownedIds.isEmpty())
		{
			return itemId;
		}
		EquipmentIndexRepository.Entry entry = index.entryFor(itemId);
		if (entry == null)
		{
			return itemId;
		}
		EquipmentStatsRepository.Stats itemStats = EquipmentStatsRepository.getInstance().statsFor(itemId);
		for (String baseName : variantBaseNamesFor(entry.name()))
		{
			for (String suffix : SUFFIXES)
			{
				List<Integer> variantIds = index.idsForName(baseName + suffix);
				if (variantIds.isEmpty())
				{
					continue;
				}
				boolean homogeneous = isHomogeneous(variantIds);
				for (Integer variantId : variantIds)
				{
					if (!ownedIds.containsKey(variantId)
						|| (excludedItemIds != null && excludedItemIds.contains(variantId)))
					{
						continue;
					}
					if (homogeneous
						|| (sameStats(itemStats, EquipmentStatsRepository.getInstance().statsFor(variantId))
							&& sameRequirements(itemId, variantId)))
					{
						return variantId;
					}
				}
			}
		}
		return itemId;
	}

	/**
	 * Every name a variant of {@code indexedName} could be filed under: the
	 * item's own name first, then any {@link #UNINDEXED_PLAIN_NAME_ALIASES}
	 * key that maps ONTO it.
	 *
	 * <p><b>The alias table has to work in both directions</b>, or the
	 * credit it enables has no matching display. {@link #plainFormId} reads
	 * it forwards: "Toxic staff (deadman)" strips to the unindexed "Toxic
	 * staff", which the table redirects to the real "Toxic staff of the
	 * dead", crediting 12902/12904. {@link #preferOwnedVariant} then has to
	 * come back the other way — and appending a suffix to the item's OWN
	 * name looks for "Toxic staff of the dead (deadman)", which does not
	 * exist. Without the reverse hop the credited plain id is displayed and
	 * highlighted even though the player holds only 33035/33036, which is
	 * the same class of defect as crediting an id and then naming a
	 * different one (see {@code GearSection#resolvedItemId}): the
	 * ownership map says "you have this" and every surface points at
	 * something that is not in the bank.
	 *
	 * <p>Only the NAME lookup is widened. The stat/requirement match still
	 * decides which id is substituted, which is what keeps the charged and
	 * uncharged staffs apart — 33035 ↔ 12902 (amagic +17) and 33036 ↔ 12904
	 * (amagic +25) — since that name group is heterogeneous and therefore
	 * requires an exact match rather than file order.
	 */
	private static List<String> variantBaseNamesFor(String indexedName)
	{
		List<String> names = new java.util.ArrayList<>(2);
		names.add(indexedName);
		for (Map.Entry<String, String> alias : UNINDEXED_PLAIN_NAME_ALIASES.entrySet())
		{
			if (alias.getValue().equalsIgnoreCase(indexedName))
			{
				// The key is already lowercase and idsForName is
				// case-insensitive, so no display-case reconstruction is needed.
				names.add(alias.getKey());
			}
		}
		return names;
	}

	/**
	 * Resolves a name-sharing group of ids to a single id "compatible with"
	 * {@code referenceItemId}: if every id in {@code candidates} has
	 * IDENTICAL combat stats AND IDENTICAL equip requirements (the common
	 * case — reward-source/charge duplicates, or a (f)/(i) suffix's single
	 * plain form), any one of them is safe and the first (file order,
	 * matching historical behaviour) is returned. Otherwise the group holds
	 * items that genuinely differ — either in combat stats (Deadman crystal
	 * armour's active/inactive split) or in equip requirements alone
	 * (Deadman god capes, Dark bow's reward duplicates) — and only an id
	 * whose stats AND requirements exactly match {@code referenceItemId}'s
	 * own is trustworthy; {@code null} if none does — see class javadoc for
	 * why that's the safe answer, not a guess.
	 */
	private static Integer resolveByStatMatch(EquipmentIndexRepository index, List<Integer> candidates,
		int referenceItemId)
	{
		if (candidates.isEmpty())
		{
			return null;
		}
		if (isHomogeneous(candidates))
		{
			return candidates.get(0);
		}
		EquipmentStatsRepository.Stats referenceStats = EquipmentStatsRepository.getInstance().statsFor(referenceItemId);
		for (Integer candidateId : candidates)
		{
			if (sameStats(referenceStats, EquipmentStatsRepository.getInstance().statsFor(candidateId))
				&& sameRequirements(referenceItemId, candidateId))
			{
				return candidateId;
			}
		}
		return null;
	}

	/**
	 * True when every id in {@code ids} (non-empty) shares identical combat
	 * stats AND identical equip skill/level requirements. Both must agree:
	 * {@link EquipmentStatsRepository}'s 14 combat-bonus fields don't capture
	 * everything a same-named duplicate can differ on — a stat-identical pair
	 * can still gate on a different skill level (e.g. two "Imbued saradomin
	 * cape" ids are combat-stat-identical, but one requires magic 75 and the
	 * other has no recorded requirement at all). Treating that pair as
	 * "homogeneous" and picking file order would silently drop the level
	 * gate, so requirements are checked as a second, independent dimension —
	 * a single-element list is always homogeneous (nothing to disagree with).
	 */
	private static boolean isHomogeneous(List<Integer> ids)
	{
		int first = ids.get(0);
		EquipmentStatsRepository.Stats firstStats = EquipmentStatsRepository.getInstance().statsFor(first);
		for (int i = 1; i < ids.size(); i++)
		{
			int other = ids.get(i);
			if (!sameStats(firstStats, EquipmentStatsRepository.getInstance().statsFor(other))
				|| !sameRequirements(first, other))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Every field {@link EquipmentStatsRepository.Stats} models equal (both
	 * {@code null} counts as equal; one {@code null} does not) — the 14
	 * bonus fields AND {@link EquipmentStatsRepository.Stats#aspeed()}.
	 *
	 * <p><b>Attack speed is part of equivalence, not a bonus footnote.</b>
	 * {@code BundledSlotStatsLookup} feeds {@code aspeed} straight into the
	 * optimiser's {@code SlotStats}, so it is a direct DPS input: two ids
	 * with byte-identical bonuses and identical requirements but different
	 * weapon speeds are NOT interchangeable, and treating them as
	 * "homogeneous" (or as an exact match in {@link #resolveByStatMatch})
	 * would let ownership of a slower variant credit a faster counterpart
	 * and produce a DPS figure the player cannot actually achieve — the
	 * exact class of over-credit this whole resolver exists to prevent.
	 *
	 * <p>On the currently bundled data this changes no outcome: across all
	 * 84 name groups reachable by a {@link #SUFFIXES} strip, no group's
	 * homogeneity verdict flips when speed is included, and no
	 * variant/plain pair matches on the 14 bonus fields and requirements
	 * while differing in speed (checked including the {@link
	 * #UNINDEXED_PLAIN_NAME_ALIASES} pair — Toxic staff 33035/33036 vs
	 * 12902/12904 — and every god cape/Dark bow deadman pair). It is a
	 * guard against a future data refresh introducing such a pair
	 * silently, which the previous comparison could not have caught.
	 *
	 * <p>The stat rows carry a 16th entry the repository deliberately does
	 * not model (attack range: -1 for melee, 3-13 for ranged/magic). It is
	 * not a DPS input in this engine and is not compared here.
	 */
	private static boolean sameStats(EquipmentStatsRepository.Stats a, EquipmentStatsRepository.Stats b)
	{
		if (a == null || b == null)
		{
			return a == b;
		}
		return a.astab() == b.astab() && a.aslash() == b.aslash() && a.acrush() == b.acrush()
			&& a.amagic() == b.amagic() && a.arange() == b.arange()
			&& a.dstab() == b.dstab() && a.dslash() == b.dslash() && a.dcrush() == b.dcrush()
			&& a.dmagic() == b.dmagic() && a.drange() == b.drange()
			&& a.str() == b.str() && a.rstr() == b.rstr()
			&& a.mdmg() == b.mdmg() && a.prayer() == b.prayer()
			&& a.aspeed() == b.aspeed();
	}

	/**
	 * Test seam for {@link #sameStats} on two real bundled item ids — the
	 * comparison is data-driven and its attack-speed term changes no outcome
	 * on the currently shipped variant groups, so the only way to assert it
	 * at all is against a pair that genuinely exercises it.
	 */
	static boolean sameStatsForTest(int itemIdA, int itemIdB)
	{
		EquipmentStatsRepository repo = EquipmentStatsRepository.getInstance();
		return sameStats(repo.statsFor(itemIdA), repo.statsFor(itemIdB));
	}

	/**
	 * True when {@code itemIdA} and {@code itemIdB} carry the EXACT same equip
	 * skill/level requirements (an absent requirement map counts as "no
	 * requirements", equal to another absent one, but NOT equal to any
	 * non-empty requirement map — {@code equipment_requirements.min.json}
	 * only records an item when it carries at least one requirement, so
	 * absent means "no requirement recorded in the cache", never "definitely
	 * ungated"; this comparison is written to be correct either way, since it
	 * only ever asks "do these two match", not "is this one gated"). Used
	 * alongside {@link #sameStats} so a duplicate that differs ONLY in its
	 * level gate (not in combat stats) is never treated as an interchangeable
	 * "any pick is safe" duplicate — see {@link #isHomogeneous}.
	 */
	private static boolean sameRequirements(int itemIdA, int itemIdB)
	{
		Map<String, Integer> a = EquipmentRequirementsRepository.getInstance().requirementsFor(itemIdA);
		Map<String, Integer> b = EquipmentRequirementsRepository.getInstance().requirementsFor(itemIdB);
		Map<String, Integer> normalizedA = a == null ? Collections.emptyMap() : a;
		Map<String, Integer> normalizedB = b == null ? Collections.emptyMap() : b;
		return normalizedA.equals(normalizedB);
	}
}

package com.ospulse.ui.sections.gear;

import javax.swing.JToggleButton;
import java.util.Locale;

/**
 * Parses the optimiser's budget/expensive-threshold number fields (issue #11
 * batch extraction — pure text/number logic, no {@code GearSection} state).
 */
public final class BudgetAmount
{
	private BudgetAmount()
	{
	}

	/**
	 * Parses a budget string with an optional trailing k/m/b unit (design
	 * spec: "numeric + K/M unit toggle" — a suffix is a lighter-weight
	 * equivalent for a text field than a separate toggle button and reads
	 * naturally, matching how players already type prices in-game, e.g. GE
	 * search). Blank/unparseable input is treated as 0 (owned-only search)
	 * rather than rejected, since a budget field is not a validated form
	 * control here.
	 */
	public static long parse(String text)
	{
		if (text == null)
		{
			return 0L;
		}
		String trimmed = text.trim().toLowerCase(Locale.ROOT).replace(",", "");
		if (trimmed.isEmpty())
		{
			return 0L;
		}
		double multiplier = 1.0;
		if (trimmed.endsWith("b"))
		{
			multiplier = 1_000_000_000.0;
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		}
		else if (trimmed.endsWith("m"))
		{
			multiplier = 1_000_000.0;
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		}
		else if (trimmed.endsWith("k"))
		{
			multiplier = 1_000.0;
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		}
		try
		{
			double value = Double.parseDouble(trimmed.trim());
			return value <= 0 ? 0L : Math.round(value * multiplier);
		}
		catch (NumberFormatException e)
		{
			return 0L;
		}
	}

	/**
	 * Combines a plain numeric field's text with a K/M segmented toggle's
	 * current selection into the same "10m"/"500k" shape {@link #parse} has
	 * always accepted, then parses it — so the budget/expensive-threshold
	 * number fields feed {@code GearOptimizer.Request} exactly as the old
	 * single free-text budget field did. Neither toggle selected is treated
	 * as a plain number (no unit multiplier).
	 */
	public static long parseUnitAmount(String numberText, JToggleButton kToggle, JToggleButton mToggle)
	{
		String suffix = mToggle.isSelected() ? "m" : kToggle.isSelected() ? "k" : "";
		return parse((numberText == null ? "" : numberText.trim()) + suffix);
	}
}

package com.ospulse.ui.sections;

/**
 * Pure, side-effect-free formatters used by {@link HoldingsSection}'s
 * collapsed-header summary. Kept separate (and Swing-free) so the compact
 * value formatting can be unit-tested directly.
 *
 * <p>Distinct from {@link com.ospulse.ui.GpFormat}: that formatter is used
 * throughout the panel for row-level gp values ({@code 1.5m}, {@code 2b}).
 * This one produces the shorter, uppercase-suffix form used specifically in
 * the "Top holdings" summary badge ({@code 2.1B}, {@code 950M}) so the
 * label + trend badge together reliably fit the fixed panel width.
 */
final class HoldingsFormat
{
	private static final String[] SUFFIXES = {"", "K", "M", "B", "T"};

	private HoldingsFormat()
	{
	}

	/**
	 * Compact gp formatting with uppercase suffixes and no thousands
	 * separators, e.g. {@code 950_000_000 -> "950M"},
	 * {@code 2_100_000_000 -> "2.1B"}, {@code 999 -> "999"}. Negative values
	 * keep their sign.
	 */
	static String compact(long value)
	{
		if (value == 0)
		{
			return "0";
		}

		String sign = value < 0 ? "-" : "";
		long abs = Math.abs(value);

		if (abs < 1000)
		{
			return sign + abs;
		}

		int magnitude = 0;
		double scaled = abs;
		while (scaled >= 1000 && magnitude < SUFFIXES.length - 1)
		{
			scaled /= 1000.0;
			magnitude++;
		}

		double rounded = Math.round(scaled * 10) / 10.0;
		if (rounded >= 1000 && magnitude < SUFFIXES.length - 1)
		{
			rounded = Math.round((rounded / 1000.0) * 10) / 10.0;
			magnitude++;
		}

		String numberPart = rounded == Math.floor(rounded)
			? String.valueOf((long) rounded)
			: String.valueOf(rounded);

		return sign + numberPart + SUFFIXES[magnitude];
	}
}

package com.ospulse.ui.sections;

import com.ospulse.session.SessionSnapshot;
import com.ospulse.ui.CollapsibleSection;
import com.ospulse.ui.GpFormat;
import com.ospulse.ui.PanelWidgets;
import com.ospulse.ui.ThinProgressBar;
import com.ospulse.ui.category.CategoryOverlay;
import com.ospulse.ui.category.CategorySectionSupport;
import com.ospulse.xp.VirtualLevelTable;
import com.ospulse.xp.XpSkillView;

import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.SkillColor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * XP gained this session, in this plugin's own compact card style rather than
 * a copy of RuneLite's built-in XP Tracker widget: an "Overall" summary row,
 * then per trained skill a small icon-row/progress-bar/detail-row stack built
 * from the same {@link PanelWidgets} + {@link ThinProgressBar} pieces the
 * Grand Exchange section uses, so the whole panel reads as one design.
 *
 * <p>Levels past 99 keep climbing as RuneLite's virtual levels (see {@link
 * VirtualLevelTable}), up to the 126 cap, instead of flatlining the progress
 * bar and "next level" target at 99.
 *
 * <p>Falls back to the plain gained-per-skill list when the snapshot carries
 * no {@link XpSkillView}s (e.g. one produced via the older constructors).
 *
 * <p>Each skill card carries an XP-Tracker-style right-click menu (see
 * {@code com.ospulse.ui.category.CategoryContextMenu}, ported from RuneLite's
 * own XP Tracker plugin's {@code XpInfoBox}), including its "Open Wise Old
 * Man" link (using the skill name as the WOM gained-metric) and "Add to
 * canvas" (a positionable game overlay via {@code
 * com.ospulse.ui.category.CategoryOverlay}, ported from {@code
 * XpInfoBoxOverlay}). "Pause" freezes a skill's card at its last-seen {@link
 * XpSkillView} rather than stopping the underlying XP tracking; "Reset"/
 * "Reset others"/"Reset all" hide the skill's card from this section's list
 * (a UI-level filter) since XP totals here are read from the single tracker
 * rather than each skill owning independent, clearable state.
 */
public final class XpSection extends CollapsibleSection
{
	public static final String KEY = "xp";

	private static final int ICON_SIZE = 28;
	/**
	 * Icon render size used only inside {@link #skillCard}'s icon-row — smaller
	 * than {@link #ICON_SIZE} so the 2x2 stat grid beside it has enough
	 * horizontal room that value labels (e.g. XP/hr) don't get cropped at the
	 * panel's fixed width.
	 */
	private static final int CARD_ICON_SIZE = 18;

	private final JPanel breakdownPanel;
	private final SkillIconManager skillIconManager;
	private final CategorySectionSupport categorySupport;

	/**
	 * Last-seen view per skill category id, so a paused card keeps showing its
	 * frozen figures. ConcurrentHashMap because the canvas overlay's line
	 * supplier reads this on the CLIENT (render) thread while section rebuilds
	 * mutate it on the EDT — a plain HashMap can corrupt / CME under that
	 * concurrent get/put.
	 */
	private final Map<String, XpSkillView> lastSeenBySkill = new ConcurrentHashMap<>();
	/** Skills hidden via "Reset"/"Reset others"/"Reset all". */
	private final java.util.Set<String> hiddenSkills = new java.util.HashSet<>();
	/** Reset-epoch last observed per category id, so a "Reset" click is detected exactly once. */
	private final Map<String, Integer> lastSeenEpoch = new HashMap<>();

	private long xpTotal;
	private long elapsedMs;

	public XpSection(CollapseStore store, SkillIconManager skillIconManager,
		Plugin plugin, Client client, OverlayManager overlayManager)
	{
		super(KEY, "XP gained", store);
		this.skillIconManager = skillIconManager;
		this.categorySupport = new CategorySectionSupport(plugin, client, overlayManager);
		breakdownPanel = new JPanel();
		breakdownPanel.setLayout(new BoxLayout(breakdownPanel, BoxLayout.Y_AXIS));
		breakdownPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		breakdownPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		body().add(breakdownPanel);
	}

	private static String categoryId(String skillName)
	{
		return "xp:" + skillName;
	}

	@Override
	public void apply(SessionSnapshot snapshot)
	{
		xpTotal = snapshot.getXpTotal();
		elapsedMs = snapshot.getElapsedMs();

		breakdownPanel.removeAll();
		List<XpSkillView> skills = snapshot.getXpSkills();
		if (skills != null && !skills.isEmpty())
		{
			renderSkillViews(skills, snapshot.getXpPerHour());
		}
		else
		{
			renderGainedFallback(snapshot.getXpGained());
		}

		breakdownPanel.revalidate();
		breakdownPanel.repaint();
		refreshSummary();
	}

	/** "Overall" summary row + one compact card per skill (paused skills frozen, reset skills hidden). */
	private void renderSkillViews(List<XpSkillView> skills, long overallXpPerHour)
	{
		breakdownPanel.add(PanelWidgets.listRow("Overall XP",
			GpFormat.format(xpTotal) + " · " + GpFormat.format(overallXpPerHour) + " xp/hr"));
		breakdownPanel.add(PanelWidgets.spacer());

		List<XpSkillView> display = new ArrayList<>();
		for (XpSkillView view : skills)
		{
			String catId = categoryId(view.getSkillName());
			detectReset(catId);
			categorySupport.setLinesSupplier(catId, () -> canvasLines(catId));
			categorySupport.setProgressSupplier(catId, () -> canvasProgress(catId));
			// RuneLite-XpInfoBox-style canvas overlay: icon + colour are constant
			// per skill (captured here), figures are read live in buildXpModel.
			Skill overlaySkill = parseSkill(view.getSkillName());
			BufferedImage overlayIcon = overlayIcon(overlaySkill);
			Color overlayColor = overlaySkill != null
				? SkillColor.find(overlaySkill).getColor() : ColorScheme.BRAND_ORANGE;
			categorySupport.setXpModelSupplier(catId, () -> buildXpModel(catId, overlayIcon, overlayColor));

			if (categorySupport.controller().isPaused(catId))
			{
				display.add(lastSeenBySkill.getOrDefault(catId, view));
			}
			else
			{
				lastSeenBySkill.put(catId, view);
				if (!hiddenSkills.contains(catId))
				{
					display.add(view);
				}
			}
		}
		// A paused-but-also-reset skill was already excluded via hiddenSkills
		// before pausing froze it; filter here too so a reset always hides
		// the card regardless of pause order.
		display.removeIf(v -> hiddenSkills.contains(categoryId(v.getSkillName())));

		boolean first = true;
		for (XpSkillView skill : display)
		{
			if (!first)
			{
				breakdownPanel.add(rigidSpacer(4));
				breakdownPanel.add(skillSeparator());
				breakdownPanel.add(rigidSpacer(4));
			}
			first = false;
			breakdownPanel.add(skillCard(skill));
		}
	}

	/** A thin 1px full-width divider so adjacent skill cards don't visually merge. */
	private static JPanel skillSeparator()
	{
		JPanel line = new JPanel();
		line.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		line.setPreferredSize(new Dimension(0, 1));
		line.setMinimumSize(new Dimension(0, 1));
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
		return line;
	}

	/** Marks {@code catId} hidden the moment its reset epoch advances (a "Reset"/"Reset others"/"Reset all" click). */
	private void detectReset(String catId)
	{
		int epoch = categorySupport.controller().resetEpoch(catId);
		Integer lastEpoch = lastSeenEpoch.get(catId);
		if (lastEpoch == null)
		{
			lastSeenEpoch.put(catId, epoch);
			return;
		}
		if (epoch != lastEpoch)
		{
			hiddenSkills.add(catId);
			lastSeenEpoch.put(catId, epoch);
		}
	}

	private List<CategoryOverlay.Line> canvasLines(String catId)
	{
		XpSkillView view = lastSeenBySkill.get(catId);
		if (view == null)
		{
			return List.of();
		}
		return List.of(
			new CategoryOverlay.Line("Lvl", String.valueOf(view.getCurrentLevel())),
			new CategoryOverlay.Line("XP gained", GpFormat.format(view.getGained())),
			new CategoryOverlay.Line("XP/hr", GpFormat.format(view.getXpPerHour())));
	}

	/** Progress to next level for {@code catId}'s canvas overlay bar, from the same last-seen view {@link #canvasLines} reads. */
	private Double canvasProgress(String catId)
	{
		XpSkillView view = lastSeenBySkill.get(catId);
		return view == null ? null : view.getProgressToNextLevel();
	}

	/**
	 * The RuneLite-XpInfoBox-style model for {@code catId}'s canvas overlay:
	 * skill icon + colour (passed in, constant per skill) plus XP-gained / XP-hr
	 * lines and the current-level / % / next-level bar labels, read live from
	 * the same last-seen {@link XpSkillView} the panel card uses. Returns {@code
	 * null} before the skill has been seen, so the overlay falls back to the
	 * generic look for that one frame.
	 */
	private CategoryOverlay.XpModel buildXpModel(String catId, BufferedImage icon, Color color)
	{
		XpSkillView view = lastSeenBySkill.get(catId);
		if (view == null)
		{
			return null;
		}
		boolean maxed = view.getCurrentLevel() >= VirtualLevelTable.MAX_LEVEL;
		String percent = Math.round(view.getProgressToNextLevel() * 100.0) + "%";
		return new CategoryOverlay.XpModel(
			icon, color,
			"XP gained", GpFormat.format(view.getGained()),
			"XP/hr", GpFormat.format(view.getXpPerHour()),
			String.valueOf(view.getCurrentLevel()),
			maxed ? "" : percent,
			maxed ? "Max" : String.valueOf(view.getCurrentLevel() + 1),
			view.getProgressToNextLevel());
	}

	/** The raw (small) skill sprite for the canvas overlay icon, or {@code null} — the overlay then draws no icon. */
	private BufferedImage overlayIcon(Skill skill)
	{
		if (skillIconManager == null || skill == null)
		{
			return null;
		}
		try
		{
			return skillIconManager.getSkillImage(skill, true);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * One skill's own compact card, mirroring RuneLite's native XP Tracker
	 * {@code XpInfoBox} layout: the skill icon pinned left with the labelled
	 * 2x2 stat grid (XP Gained / XP/hr / XP left / Actions) to its right, a
	 * skill-coloured {@link ThinProgressBar} below, then an annotation row
	 * below the bar with current level · % complete · next level. There's no
	 * skill-name text — the icon alone identifies the skill, exactly as
	 * XpInfoBox does — and the current level appears exactly once, on the
	 * bar annotation, rather than duplicated in a header. The four stats are
	 * labelled inline (rather than bare numbers) so each figure is
	 * self-describing.
	 *
	 * <p>The same right-click popup is attached to every component in the
	 * card (not just the icon row) via {@link #attachPopupRecursively}, so
	 * right-clicking anywhere on the card opens the Pause/Reset/Add-to-canvas
	 * menu.
	 */
	private JPanel skillCard(XpSkillView view)
	{
		Skill skill = parseSkill(view.getSkillName());
		Color accent = skill != null ? SkillColor.find(skill).getColor() : ColorScheme.BRAND_ORANGE;
		boolean maxed = view.getCurrentLevel() >= VirtualLevelTable.MAX_LEVEL;

		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		String catId = categoryId(view.getSkillName());
		JPopupMenu popupMenu = categorySupport.buildMenu(catId, view.getSkillName());

		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		top.setAlignmentX(Component.LEFT_ALIGNMENT);

		Image iconImage = skillIcon(skill);
		JLabel iconLabel = new JLabel();
		if (iconImage != null)
		{
			// Re-scaled down from the already-{@value #ICON_SIZE}px icon just
			// for this card's icon-row, so the stat grid to its right gets
			// enough width that the XP/hr and XP-left values don't crop —
			// ICON_SIZE itself stays untouched since other rows rely on it.
			Image cardIcon = iconImage.getScaledInstance(CARD_ICON_SIZE, CARD_ICON_SIZE, Image.SCALE_SMOOTH);
			iconLabel.setIcon(new javax.swing.ImageIcon(cardIcon));
		}
		iconLabel.setVerticalAlignment(SwingConstants.CENTER);
		iconLabel.setPreferredSize(new Dimension(CARD_ICON_SIZE, CARD_ICON_SIZE));
		top.add(iconLabel, BorderLayout.WEST);
		top.add(statGrid(view, maxed), BorderLayout.CENTER);
		top.setMaximumSize(new Dimension(Integer.MAX_VALUE, top.getPreferredSize().height));
		card.add(top);

		card.add(rigidSpacer(3));

		ThinProgressBar bar = new ThinProgressBar();
		bar.setForeground(accent);
		bar.setProgress(view.getProgressToNextLevel());
		bar.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(bar);
		card.add(rigidSpacer(1));
		card.add(barAnnotation(view, maxed));

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		attachPopupRecursively(card, popupMenu);
		return card;
	}

	/**
	 * Attaches {@code popupMenu} to {@code component} and every descendant,
	 * since Swing's {@code setComponentPopupMenu} only fires for the exact
	 * component under the mouse and doesn't inherit to children — so without
	 * walking the tree, right-clicking a JLabel nested inside the card would
	 * show no menu at all.
	 */
	private static void attachPopupRecursively(Component component, JPopupMenu popupMenu)
	{
		if (component instanceof javax.swing.JComponent)
		{
			((javax.swing.JComponent) component).setComponentPopupMenu(popupMenu);
		}
		if (component instanceof java.awt.Container)
		{
			for (Component child : ((java.awt.Container) component).getComponents())
			{
				attachPopupRecursively(child, popupMenu);
			}
		}
	}

	/** Labelled 2x2 grid: XP Gained / XP/hr on the first row, XP left / Actions on the second. */
	private static JPanel statGrid(XpSkillView view, boolean maxed)
	{
		JPanel grid = new JPanel(new GridLayout(2, 2, 8, 1));
		grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);

		String xpLeft = maxed ? "0" : GpFormat.format(view.getXpLeft());
		String actions = maxed ? "Maxed"
			: view.getActionsLeft() < 0 ? "?" : String.format(Locale.ROOT, "%,d", view.getActionsLeft());

		grid.add(statCell("XP Gained", GpFormat.format(view.getGained())));
		grid.add(statCell("XP/hr", GpFormat.format(view.getXpPerHour())));
		grid.add(statCell("XP left", xpLeft));
		grid.add(statCell("Actions", actions));

		grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, grid.getPreferredSize().height));
		return grid;
	}

	/** A "Label value" cell: grey label pinned left, white value pinned right. */
	private static JPanel statCell(String label, String value)
	{
		JPanel cell = new JPanel(new BorderLayout(4, 0));
		cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel labelLabel = new JLabel(label);
		labelLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		labelLabel.setFont(FontManager.getRunescapeSmallFont());

		JLabel valueLabel = new JLabel(value);
		valueLabel.setForeground(Color.WHITE);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		cell.add(labelLabel, BorderLayout.WEST);
		cell.add(valueLabel, BorderLayout.CENTER);
		return cell;
	}

	/** Under-bar annotation row: current level (left) · % complete (centre) · next level or "Max" (right). */
	private static JPanel barAnnotation(XpSkillView view, boolean maxed)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel current = miniLabel(String.valueOf(view.getCurrentLevel()), SwingConstants.LEFT);
		JLabel percent = miniLabel(Math.round(view.getProgressToNextLevel() * 100.0) + "%", SwingConstants.CENTER);
		JLabel next = miniLabel(maxed ? "Max" : String.valueOf(view.getCurrentLevel() + 1), SwingConstants.RIGHT);

		row.add(current, BorderLayout.WEST);
		row.add(percent, BorderLayout.CENTER);
		row.add(next, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private static JLabel miniLabel(String text, int alignment)
	{
		JLabel label = new JLabel(text, alignment);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		return label;
	}

	private static Component rigidSpacer(int height)
	{
		return Box.createRigidArea(new Dimension(0, height));
	}

	/** The pre-parity rendering: gained per skill, ordered by gain descending. */
	private void renderGainedFallback(Map<String, Long> xpGained)
	{
		boolean any = false;
		if (xpGained != null)
		{
			List<Map.Entry<String, Long>> entries = new ArrayList<>(xpGained.entrySet());
			entries.removeIf(e -> e.getValue() == null || e.getValue() <= 0);
			entries.sort((a, b) -> Long.compare(b.getValue(), a.getValue()));
			for (Map.Entry<String, Long> entry : entries)
			{
				breakdownPanel.add(PanelWidgets.listRow(prettySkillName(entry.getKey()),
					GpFormat.format(entry.getValue())));
				any = true;
			}
		}

		if (!any)
		{
			breakdownPanel.add(PanelWidgets.emptyRowLabel("No XP gained yet."));
		}
	}

	/** The RuneLite Skill enum for a skill name (e.g. "WOODCUTTING"), or null. */
	private static Skill parseSkill(String name)
	{
		if (name == null || name.isEmpty())
		{
			return null;
		}
		try
		{
			return Skill.valueOf(name.toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/**
	 * A small ({@value #ICON_SIZE}px) skill icon for a skill, or {@code null}
	 * if unavailable — the row then renders without an icon rather than
	 * failing. Deliberately smaller than RuneLite's 35x35 XpInfoBox icon to
	 * keep this section's rows compact.
	 */
	private Image skillIcon(Skill skill)
	{
		if (skillIconManager == null || skill == null)
		{
			return null;
		}
		try
		{
			Image full = skillIconManager.getSkillImage(skill, false);
			return full == null ? null : full.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** "WOODCUTTING" -&gt; "Woodcutting" (skill enum names are single words). */
	private static String prettySkillName(String name)
	{
		if (name == null || name.isEmpty())
		{
			return "";
		}
		String lower = name.toLowerCase(Locale.ROOT);
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}

	private long xpPerHour()
	{
		if (elapsedMs <= 0)
		{
			return 0;
		}
		return xpTotal * 3_600_000L / elapsedMs;
	}

	@Override
	public void removeAllCategoryOverlays()
	{
		categorySupport.removeAllOverlays();
	}

	/**
	 * Full panel reset (feature 11): forgets every hidden skill, frozen
	 * paused-figure snapshot and reset epoch, zeroes the totals and clears the
	 * per-skill breakdown. The next snapshot rebuilds the breakdown from
	 * scratch, so a skill hidden via "Reset" reappears and paused cards
	 * un-freeze.
	 */
	@Override
	public void resetState()
	{
		lastSeenBySkill.clear();
		hiddenSkills.clear();
		lastSeenEpoch.clear();
		xpTotal = 0;
		elapsedMs = 0;
		categorySupport.clearAll();
		breakdownPanel.removeAll();
		breakdownPanel.revalidate();
		breakdownPanel.repaint();
		refreshSummary();
	}

	@Override
	protected String summaryText()
	{
		return GpFormat.format(xpTotal) + " · " + GpFormat.format(xpPerHour()) + " xp/hr";
	}

	// ------------------------------------------------- test seams (package)

	boolean isSkillHiddenForTest(String skillName)
	{
		return hiddenSkills.contains(categoryId(skillName));
	}

	/** Simulates "Reset"-ing a skill (hides it until next XP drop) and pausing it. */
	void hideSkillForTest(String skillName)
	{
		hiddenSkills.add(categoryId(skillName));
		categorySupport.controller().setPaused(categoryId(skillName), true);
	}

	int breakdownRowCountForTest()
	{
		return breakdownPanel.getComponentCount();
	}
}

package com.ospulse.ui.sections;

import com.ospulse.model.ItemStack;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Plain-Java (no Swing) tracker for the loot feed's "Hide item" / "Hide
 * loot" right-click actions, kept separate from {@link LootSection} so the
 * filtering logic is unit-testable without a Swing/RuneLite environment.
 *
 * <p>Two independent sets are maintained deliberately:
 * <ul>
 *   <li>Item hides ({@link #hideItem}) and manual source hides ({@link
 *   #hideSource}) are both "hidden until explicitly un-hidden" — distinct
 *   from {@code LootSection}'s existing {@code hiddenSources} set, which is
 *   "hidden until a new pickup" (the Reset/Reset-others/Reset-all
 *   semantics).
 * </ul>
 *
 * <p>Not thread-safe; use on the Swing EDT only, same as the section that
 * owns an instance of this.
 */
public final class LootHiddenState
{
	private final Map<Integer, String> hiddenItemIds = new LinkedHashMap<>();
	private final Map<String, String> manuallyHiddenSources = new LinkedHashMap<>();

	/** Hides {@code item}'s id from the feed; retains its last-seen name for the "View hidden items" list. */
	public void hideItem(ItemStack item)
	{
		hiddenItemIds.put(item.getId(), item.getName());
	}

	public boolean isItemHidden(int itemId)
	{
		return hiddenItemIds.containsKey(itemId);
	}

	public void unhideItem(int itemId)
	{
		hiddenItemIds.remove(itemId);
	}

	/** Hides an entire source (by category id) until explicitly unhidden via "View hidden items". */
	public void hideSource(String catId, String displayName)
	{
		manuallyHiddenSources.put(catId, displayName);
	}

	public boolean isSourceHidden(String catId)
	{
		return manuallyHiddenSources.containsKey(catId);
	}

	public void unhideSource(String catId)
	{
		manuallyHiddenSources.remove(catId);
	}

	/** Snapshot of hidden item id -> last-seen name, in insertion order. */
	public Map<Integer, String> hiddenItems()
	{
		return new LinkedHashMap<>(hiddenItemIds);
	}

	/** Snapshot of hidden source catId -> display name, in insertion order. */
	public Map<String, String> hiddenSources()
	{
		return new LinkedHashMap<>(manuallyHiddenSources);
	}

	public boolean isEmpty()
	{
		return hiddenItemIds.isEmpty() && manuallyHiddenSources.isEmpty();
	}

	/** Clears both sets, e.g. as part of a section/panel-wide "full reset". */
	public void clear()
	{
		hiddenItemIds.clear();
		manuallyHiddenSources.clear();
	}

	/** Whether {@code item} should be filtered out of the loot feed grid. */
	public boolean isItemFiltered(ItemStack item)
	{
		return isItemHidden(item.getId());
	}
}

package com.ospulse.ui.sections;

import com.ospulse.OSPulseConfig;
import com.ospulse.integration.PriceTrendService;
import com.ospulse.model.ItemStack;
import com.ospulse.session.HoldingPnl;
import com.ospulse.session.SessionSnapshot;
import com.ospulse.ui.CollapsibleSection;
import com.ospulse.ui.GpFormat;
import com.ospulse.ui.PanelWidgets;
import com.ospulse.wealth.WealthSnapshot;

import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.OptionalDouble;

/**
 * Top holdings: the most valuable items in the player's wealth. Collapsed
 * summary shows the total value of the top holdings, plus - when price
 * trends are enabled - a value-weighted aggregate trend badge.
 *
 * <p>Rows are shown {@code config.holdingsPageSize()} at a time ("Show N
 * more" / "Show less"), and optionally carry a per-item price trend badge
 * (▲/▼ X.X%) sourced from {@link PriceTrendService}. Trend data is entirely
 * opt-in and off by default: with it disabled this section behaves exactly
 * as the plain holdings list did before, just paginated.
 *
 * <p>Each row also carries a per-item unrealized-drift badge (live value vs
 * session cost basis, see {@link HoldingPnl}) with the cost basis in the row
 * tooltip — a per-holding "how has this drifted since I picked it up"
 * readout. There is deliberately no session-wide "Unrealized P/L" stat row
 * here (or anywhere else in the panel): under the locked session model,
 * price drift on held/worn/inventory gear is zeroed and never independently
 * moves net worth, and the session's own unrealised figure — GE positions,
 * open/collectable Grand Exchange offers marked to market — lives in the
 * Session section instead.
 */
public final class HoldingsSection extends CollapsibleSection
{
	public static final String KEY = "holdings";

	private static final int DEFAULT_PAGE_SIZE = 5;

	private final ItemManager itemManager;
	private final OSPulseConfig config;
	private final PriceTrendService priceTrendService;
	private final ConfigManager configManager;
	private final Client client;

	private final JPanel holdingsListPanel;
	private final JPanel pagerRow;
	private final JButton moreButton;
	private final JButton lessButton;

	private List<ItemStack> lastHoldings = List.of();
	private Map<Integer, HoldingPnl> lastPnls = Map.of();
	private long total;
	private int visibleCount;
	/** Colored (green/red) HTML {@code <font>} span for the value-weighted aggregate trend badge, or null. */
	private String aggregateTrendBadgeHtml;

	public HoldingsSection(CollapseStore store, ItemManager itemManager, OSPulseConfig config,
		PriceTrendService priceTrendService)
	{
		this(store, itemManager, config, priceTrendService, null, null);
	}

	public HoldingsSection(CollapseStore store, ItemManager itemManager, OSPulseConfig config,
		PriceTrendService priceTrendService, ConfigManager configManager, Client client)
	{
		super(KEY, "Top holdings", store);
		this.itemManager = itemManager;
		this.config = config;
		this.priceTrendService = priceTrendService;
		this.configManager = configManager;
		this.client = client;
		this.visibleCount = pageSize();

		holdingsListPanel = new JPanel();
		holdingsListPanel.setLayout(new BoxLayout(holdingsListPanel, BoxLayout.Y_AXIS));
		holdingsListPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		holdingsListPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		body().add(holdingsListPanel);

		moreButton = new JButton();
		moreButton.setFont(FontManager.getRunescapeSmallFont());
		moreButton.addActionListener(e ->
		{
			visibleCount += pageSize();
			render();
		});

		lessButton = new JButton("Show less");
		lessButton.setFont(FontManager.getRunescapeSmallFont());
		lessButton.addActionListener(e ->
		{
			visibleCount = pageSize();
			render();
		});

		pagerRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 2));
		pagerRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		pagerRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		pagerRow.add(moreButton);
		pagerRow.add(lessButton);
		pagerRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, pagerRow.getPreferredSize().height));
		body().add(pagerRow);

		if (priceTrendService != null)
		{
			priceTrendService.setOnUpdate(() -> SwingUtilities.invokeLater(this::render));
		}
	}

	@Override
	public void apply(SessionSnapshot snapshot)
	{
		WealthSnapshot wealth = snapshot.getWealth();
		lastHoldings = wealth == null ? List.of() : wealth.getTopHoldings();
		Map<Integer, HoldingPnl> pnls = new HashMap<>();
		for (HoldingPnl pnl : snapshot.getHoldingPnls())
		{
			pnls.put(pnl.getItemId(), pnl);
		}
		lastPnls = pnls;
		// Never shrink below a full page across a snapshot update, but do
		// preserve however far the user has paged.
		if (visibleCount < pageSize())
		{
			visibleCount = pageSize();
		}
		render();
	}

	/**
	 * No-op, retained so {@link com.ospulse.ui.OSPulsePanel#persistState()} can
	 * keep calling it unconditionally on plugin shutdown: this section no
	 * longer persists any cross-login state (the "since last login" Unrealized
	 * P/L baseline it used to write was removed along with the session-wide
	 * Unrealized P/L stat row — see the class javadoc).
	 */
	public void shutdown()
	{
	}

	/**
	 * Full panel reset (feature 11): collapses the "Show more" pagination back
	 * to a single page and clears the cached holdings so the list reads empty
	 * until the next snapshot repopulates it. Holdings themselves are live
	 * wealth (re-supplied every {@code apply}), so this only forgets transient
	 * view state.
	 */
	@Override
	public void resetState()
	{
		lastHoldings = List.of();
		lastPnls = Map.of();
		total = 0;
		visibleCount = pageSize();
		aggregateTrendBadgeHtml = null;
		render();
	}

	/**
	 * Collapsed-header summary: "Top holdings" value formatted compactly
	 * (e.g. {@code 2.1B} / {@code 950M}), plus - when a value-weighted trend
	 * is available - a separate colored (green up / red down) percentage
	 * badge with its arrow. Rendered as HTML in a plain (non-wrapping,
	 * non-HTML by default) {@code JLabel}: without the {@code <html>} wrapper
	 * long concatenated plain text just gets silently clipped by the header's
	 * fixed-width {@code BorderLayout.EAST} slot, which is what caused the
	 * value and trend badge to run together and overflow off the panel edge.
	 */
	@Override
	protected String summaryText()
	{
		String base = HoldingsFormat.compact(total);
		if (aggregateTrendBadgeHtml == null)
		{
			return "<html>" + base + "</html>";
		}
		return "<html>" + base + "&nbsp;&nbsp;" + aggregateTrendBadgeHtml + "</html>";
	}

	private void render()
	{
		holdingsListPanel.removeAll();

		boolean trendsOn = config != null && config.priceTrendEnabled();
		total = 0L;
		double weightedTrendSum = 0.0;
		double weightedValueSum = 0.0;

		if (lastHoldings.isEmpty())
		{
			holdingsListPanel.add(PanelWidgets.emptyRowLabel("No holdings tracked yet."));
		}
		else
		{
			int shown = Math.min(visibleCount, lastHoldings.size());
			List<Integer> shownIds = new ArrayList<>();

			for (int i = 0; i < lastHoldings.size(); i++)
			{
				ItemStack stack = lastHoldings.get(i);
				total += stack.value();

				OptionalDouble trend = (trendsOn && priceTrendService != null)
					? priceTrendService.getTrendPercent(stack.getId())
					: OptionalDouble.empty();
				if (trend.isPresent())
				{
					weightedTrendSum += stack.value() * trend.getAsDouble();
					weightedValueSum += stack.value();
				}

				if (i < shown)
				{
					shownIds.add(stack.getId());

					HoldingPnl pnl = lastPnls.get(stack.getId());
					String label = stack.getName() + " x" + String.format("%,d", stack.getQuantity());
					String value = GpFormat.format(stack.value());
					String unrlBadge = pnl != null && pnl.unrealized() != 0
						? unrealizedBadgeHtml(pnl.unrealized())
						: null;
					String right = trendsOn || unrlBadge != null
						? "<html>" + value
							+ (unrlBadge == null ? "" : "&nbsp;&nbsp;" + unrlBadge)
							+ (trendsOn ? "&nbsp;&nbsp;" + trendBadgeHtml(trend) : "")
							+ "</html>"
						: value;

					JPanel row = PanelWidgets.iconRow(itemManager, stack.getId(), label, right,
						ColorScheme.LIGHT_GRAY_COLOR);
					if (pnl != null)
					{
						row.setToolTipText("Cost basis: " + GpFormat.format(pnl.getCostBasis())
							+ "  |  Unrealized: " + signedGp(pnl.unrealized()));
					}
					holdingsListPanel.add(row);
				}
			}

			if (trendsOn && priceTrendService != null)
			{
				priceTrendService.prefetch(shownIds);
			}
		}

		aggregateTrendBadgeHtml = weightedValueSum > 0
			? trendBadgeHtml(OptionalDouble.of(weightedTrendSum / weightedValueSum))
			: null;

		boolean canShowMore = lastHoldings.size() > visibleCount;
		boolean canShowLess = visibleCount > pageSize();
		moreButton.setText("Show " + pageSize() + " more");
		moreButton.setVisible(canShowMore);
		lessButton.setVisible(canShowLess);
		pagerRow.setVisible(canShowMore || canShowLess);

		holdingsListPanel.revalidate();
		holdingsListPanel.repaint();
		body().revalidate();
		body().repaint();
		refreshSummary();
	}

	private int pageSize()
	{
		return config == null ? DEFAULT_PAGE_SIZE : Math.max(1, config.holdingsPageSize());
	}

	private static String signedGp(long value)
	{
		return (value > 0 ? "+" : "") + GpFormat.format(value);
	}

	/**
	 * Colored per-holding unrealized-drift badge (e.g. "+120k" / "-45k"):
	 * how far this holding's live value has moved from its session cost
	 * basis. Same visual idiom as the trend badge.
	 */
	private static String unrealizedBadgeHtml(long unrealized)
	{
		Color color = unrealized >= 0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR;
		return "<font color='" + toHex(color) + "'>" + signedGp(unrealized) + "</font>";
	}

	private static String trendText(double pct)
	{
		String arrow = pct >= 0 ? "▲" : "▼"; // ▲ / ▼
		return arrow + " " + String.format("%.1f", Math.abs(pct)) + "%";
	}

	private static String trendBadgeHtml(OptionalDouble trend)
	{
		if (!trend.isPresent())
		{
			return "<font color='" + toHex(ColorScheme.LIGHT_GRAY_COLOR) + "'>—</font>"; // —
		}

		double pct = trend.getAsDouble();
		Color color = pct >= 0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR;
		return "<font color='" + toHex(color) + "'>" + trendText(pct) + "</font>";
	}

	private static String toHex(Color c)
	{
		return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}
}

package com.ospulse.ui.sections;

import com.ospulse.session.SessionSnapshot;
import com.ospulse.ui.CollapsibleSection;
import com.ospulse.ui.GpFormat;
import com.ospulse.ui.PanelWidgets;
import com.ospulse.wealth.WealthSnapshot;

import javax.swing.JLabel;

/**
 * Net-worth breakdown: net worth, tracked wealth and its components, plus bank
 * (shown as "unknown" until the bank has been opened). Collapsed summary shows
 * net worth.
 */
public final class WealthSection extends CollapsibleSection
{
	public static final String KEY = "wealth";

	private final JLabel netWorthValue;
	private final JLabel trackedValue;
	private final JLabel inventoryValue;
	private final JLabel equipmentValue;
	private final JLabel geInFlightValue;
	private final JLabel pouchValue;
	private final JLabel bankValue;

	private String summary = "-";

	public WealthSection(CollapseStore store)
	{
		super(KEY, "Net worth breakdown", store);
		netWorthValue = PanelWidgets.statRow(body(), "Net worth");
		trackedValue = PanelWidgets.statRow(body(), "Tracked");
		inventoryValue = PanelWidgets.statRow(body(), "Inventory");
		equipmentValue = PanelWidgets.statRow(body(), "Equipment");
		geInFlightValue = PanelWidgets.statRow(body(), "GE in-flight");
		pouchValue = PanelWidgets.statRow(body(), "Pouch");
		bankValue = PanelWidgets.statRow(body(), "Bank");
	}

	@Override
	public void apply(SessionSnapshot snapshot)
	{
		WealthSnapshot wealth = snapshot.getWealth();
		if (wealth == null)
		{
			netWorthValue.setText("—");
			trackedValue.setText("—");
			inventoryValue.setText("—");
			equipmentValue.setText("—");
			geInFlightValue.setText("—");
			pouchValue.setText("—");
			bankValue.setText("—");
			PanelWidgets.resetLabelColor(netWorthValue);
			summary = "—";
			refreshSummary();
			return;
		}

		PanelWidgets.setSignedGpLabel(netWorthValue, wealth.netWorth());
		PanelWidgets.gpLabel(trackedValue, wealth.tracked());
		PanelWidgets.gpLabel(inventoryValue, wealth.getInventoryValue());
		PanelWidgets.gpLabel(equipmentValue, wealth.getEquipmentValue());
		PanelWidgets.gpLabel(geInFlightValue, wealth.getGeInFlightValue());
		PanelWidgets.gpLabel(pouchValue, wealth.getPouchValue());

		if (wealth.isBankKnown())
		{
			PanelWidgets.gpLabel(bankValue, wealth.getBankValue());
		}
		else
		{
			bankValue.setText("— (unknown)");
			PanelWidgets.resetLabelColor(bankValue);
		}

		summary = GpFormat.format(wealth.netWorth());
		refreshSummary();
	}

	@Override
	protected String summaryText()
	{
		return summary;
	}
}

package com.ospulse.ui.sections;

import com.ospulse.session.SessionSnapshot;
import com.ospulse.ui.CollapsibleSection;
import com.ospulse.ui.GpFormat;
import com.ospulse.ui.PanelWidgets;
import com.ospulse.ui.category.CategoryOverlay;
import com.ospulse.ui.category.CategorySectionSupport;

import net.runelite.api.Client;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.Component;
import java.util.List;

/**
 * Session P&amp;L breakdown: Loot, Supplies used, Profit, Profit/hr, GE flip,
 * GE positions and Bank, ending in "Net worth change" — the LOCKED session
 * model. "Net worth change" is a pure SUM of four components: {@code Profit
 * (= Loot - Supplies) + GE flip (realised) + GE positions (unrealised
 * mark-to-market on open/collectable GE offers) + Bank (bankValue -
 * bankLineAnchor)}. Profit and GE flip are always included; GE positions and
 * Bank each carry their own include/exclude checkbox (default ON) so a
 * player who only cares about realised activity can zero them out of the
 * total without losing the raw readout. Held/worn/inventory gear price drift
 * deliberately shows up nowhere in this panel — it is zeroed until the item
 * transacts (sold via GE, banked, or consumed/looted) — so there is
 * intentionally no standalone "Unrealized"/"P/L" row anywhere here.
 *
 * <p>A "Show breakdown" checkbox splits the individual component rows from
 * the final "Net worth change" total: unchecked, only elapsed and the total
 * are shown, mirroring a simple win/loss readout; checked (default), every
 * component row is visible above the total.
 *
 * <p>"Loot" is the gp value of items actually picked up — realised gains
 * with GE flip removed (flips have their own line) and excluding consumption
 * spend entirely (see {@link com.ospulse.session.SessionEngine#update});
 * Supplies used is shown below it as a separate spent/negative-styled
 * readout; "Profit" = Loot − Supplies used, and Profit/hr is the hourly
 * extrapolation of that net figure. Internal ids keep the older
 * profit/net-profit naming so persisted reset/pause state survives. Collapsed
 * summary shows elapsed + Loot.
 *
 * <p>Each stat row carries an XP-Tracker-style right-click menu (see {@code
 * com.ospulse.ui.category.CategoryContextMenu}, ported from RuneLite's XP
 * Tracker plugin). Since these stats are read straight off the single {@link
 * com.ospulse.session.SessionEngine} accumulator rather than each having
 * their own independent counter, "Reset" here rebases the displayed figure
 * to zero from that point (subtracting a captured baseline) rather than
 * clearing any engine-level state; "Pause" freezes the row's displayed value
 * rather than stopping the engine from tracking it. The include/exclude
 * toggles are a separate, display-only concern (whether a component counts
 * towards "Net worth change") and are independent of reset/pause.
 */
public final class SessionSection extends CollapsibleSection
{
	public static final String KEY = "session";

	private static final String CAT_ELAPSED = "session:elapsed";
	private static final String CAT_PROFIT = "session:profit";
	private static final String CAT_SUPPLIES = "session:supplies";
	private static final String CAT_NET_PROFIT = "session:netProfit";
	private static final String CAT_PROFIT_PER_HOUR = "session:profitPerHour";
	private static final String CAT_NET_WORTH_DELTA = "session:netWorthDelta";
	private static final String CAT_GE_PNL = "session:gePnl";
	private static final String CAT_GE_POSITIONS = "session:gePositions";
	private static final String CAT_BANK = "session:bank";

	private final JLabel elapsedValue;
	private final JLabel profitValue;
	private final JLabel suppliesUsedValue;
	private final JLabel netProfitValue;
	private final JLabel profitPerHourValue;
	private final JLabel netWorthDeltaValue;
	private final JLabel geRealizedPnlValue;
	private final JCheckBox gePositionsToggle;
	private final JLabel gePositionsValue;
	private final JCheckBox bankToggle;
	private final JLabel bankValue;
	private final JCheckBox splitToggle;
	private final JPanel breakdownPanel;

	private final CategorySectionSupport categorySupport;

	/** Baselines captured at "Reset" time (raw engine value when reset was clicked), keyed by category id. */
	private long profitBaseline;
	private long suppliesBaseline;
	private long netProfitBaseline;
	private long profitPerHourBaseline;
	private long gePnlBaseline;
	/**
	 * Net-worth-change baselines, captured PER COMPONENT when the "Net worth
	 * change" row is reset — one raw component value each, ALWAYS all four
	 * regardless of which components are toggled on/off at that instant. A
	 * single aggregate baseline (the raw total at reset time) cannot survive
	 * a later toggle flip: subtracting a toggle-filtered total from a
	 * baseline that was captured with a different set of components included
	 * jumps by exactly the flipped component's value the moment the toggle
	 * changes (the bug this fixes). Per-component baselines make {@code raw -
	 * baseline} well-defined for each component independently of its own
	 * toggle state, at reset time or later.
	 */
	private long nwProfitBaseline;
	private long nwGeFlipBaseline;
	private long nwGePositionsBaseline;
	private long nwBankBaseline;

	private long elapsedMs;
	private long displayedProfit;
	/** The raw (untoggled) component values from the last snapshot, so the toggles can recompute on click without waiting for the next apply(). */
	private long lastRawNetProfit;
	private long lastRawGePnl;
	private long lastRawGePositions;
	private long lastRawBankDelta;

	public SessionSection(CollapseStore store, Plugin plugin, Client client, OverlayManager overlayManager)
	{
		super(KEY, "Session", store);
		categorySupport = new CategorySectionSupport(plugin, client, overlayManager);

		elapsedValue = PanelWidgets.statRow(body(), "Elapsed",
			categorySupport.buildMenu(CAT_ELAPSED, null));

		// Rows 1-6 (+ Profit/hr) of the LOCKED layout live in their own panel so
		// the "Show breakdown" toggle can hide them as one block while leaving
		// Elapsed and the Net worth change total (row 8) always visible.
		breakdownPanel = new JPanel();
		breakdownPanel.setLayout(new BoxLayout(breakdownPanel, BoxLayout.Y_AXIS));
		breakdownPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		breakdownPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		body().add(breakdownPanel);

		// 1. Loot — gross realised gains (loot + trade P&L), before the cost of
		// supplies burned to earn them. (Internal ids stay CAT_PROFIT/profitValue
		// so persisted reset/pause state survives.)
		profitValue = PanelWidgets.statRow(breakdownPanel, "Loot",
			categorySupport.buildMenu(CAT_PROFIT, null));
		// 2. Supplies used.
		suppliesUsedValue = PanelWidgets.statRow(breakdownPanel, "Supplies used",
			categorySupport.buildMenu(CAT_SUPPLIES, null));
		// 3. Profit = Loot - Supplies used. (Internal id stays CAT_NET_PROFIT/netProfitValue.)
		netProfitValue = PanelWidgets.statRow(breakdownPanel, "Profit",
			categorySupport.buildMenu(CAT_NET_PROFIT, null));
		profitPerHourValue = PanelWidgets.statRow(breakdownPanel, "Profit/hr",
			categorySupport.buildMenu(CAT_PROFIT_PER_HOUR, null));
		// 4. GE flip (realised) — always included in the total, no toggle.
		geRealizedPnlValue = PanelWidgets.statRow(breakdownPanel, "GE flip",
			categorySupport.buildMenu(CAT_GE_PNL, null));
		// EVERY tick box in this section shares ONE name-column width so they
		// all line up on one x, while their names stay flush-left with the
		// plain stat rows above (Profit/GE flip). "Show breakdown" is included
		// even though it is added further down, outside breakdownPanel — it is
		// the widest of the three, so it is what sets the column. Measured from
		// the real font, so renaming any label re-sizes the column
		// automatically rather than silently misaligning it.
		int toggleNameColumn = PanelWidgets.toggleNameColumnWidth("GE positions", "Bank", "Show breakdown");
		// 5. GE positions (unrealised mark-to-market on open/collectable GE
		// offers) — include/exclude toggle, default ON.
		PanelWidgets.ToggleRow geRow = PanelWidgets.toggleStatRow(breakdownPanel, "GE positions", toggleNameColumn);
		gePositionsToggle = geRow.checkbox;
		gePositionsValue = geRow.value;
		gePositionsToggle.addActionListener(e -> refreshNetWorthChange());
		// 6. Bank (bankValue - bankLineAnchor) — include/exclude toggle, default ON.
		PanelWidgets.ToggleRow bankRow = PanelWidgets.toggleStatRow(breakdownPanel, "Bank", toggleNameColumn);
		bankToggle = bankRow.checkbox;
		bankValue = bankRow.value;
		bankToggle.addActionListener(e -> refreshNetWorthChange());

		// 7. Split toggle: show/hide the component breakdown above, independent
		// of the final total below. Added to body(), NOT breakdownPanel — it
		// must stay visible when the breakdown it controls is hidden. Uses the
		// same name column as the rows above so all three boxes share one x.
		splitToggle = PanelWidgets.toggleOnlyRow(body(), "Show breakdown", toggleNameColumn);
		splitToggle.addActionListener(e ->
		{
			breakdownPanel.setVisible(splitToggle.isSelected());
			body().revalidate();
			body().repaint();
		});

		// 8. Net worth change — LAST, the sum of the always-included components
		// (Profit, GE flip) plus whichever of GE positions/Bank are toggled on.
		netWorthDeltaValue = PanelWidgets.statRow(body(), "Net worth change",
			categorySupport.buildMenu(CAT_NET_WORTH_DELTA, null));

		categorySupport.setLinesSupplier(CAT_PROFIT, () -> List.of(
			new CategoryOverlay.Line("Loot", GpFormat.format(displayedProfit))));
	}

	@Override
	public void apply(SessionSnapshot snapshot)
	{
		elapsedMs = snapshot.getElapsedMs();
		long rawProfit = snapshot.getLootValue();
		long rawSuppliesUsed = snapshot.getSuppliesUsed();
		long rawNetProfit = snapshot.getNetProfit();
		long rawProfitPerHour = snapshot.getProfitPerHour();
		long rawGePnl = snapshot.getGeRealizedPnl();
		long rawGePositions = snapshot.getGePositions();
		long rawBankDelta = snapshot.getBankDelta();
		lastRawNetProfit = rawNetProfit;
		lastRawGePnl = rawGePnl;
		lastRawGePositions = rawGePositions;
		lastRawBankDelta = rawBankDelta;

		if (!categorySupport.controller().isPaused(CAT_ELAPSED))
		{
			elapsedValue.setText(PanelWidgets.formatElapsed(elapsedMs));
		}
		if (!categorySupport.controller().isPaused(CAT_PROFIT))
		{
			displayedProfit = rawProfit - profitBaseline;
			PanelWidgets.setSignedGpLabel(profitValue, displayedProfit);
		}
		if (!categorySupport.controller().isPaused(CAT_SUPPLIES))
		{
			// Supplies used is always a spend, never a gain — render it as a
			// negative-style figure (like a cost) regardless of sign so it
			// reads consistently as "gp burned", not as profit/loss.
			PanelWidgets.setSignedGpLabel(suppliesUsedValue, -(rawSuppliesUsed - suppliesBaseline));
		}
		if (!categorySupport.controller().isPaused(CAT_NET_PROFIT))
		{
			PanelWidgets.setSignedGpLabel(netProfitValue, rawNetProfit - netProfitBaseline);
		}
		if (!categorySupport.controller().isPaused(CAT_PROFIT_PER_HOUR))
		{
			PanelWidgets.setSignedGpLabel(profitPerHourValue, rawProfitPerHour - profitPerHourBaseline);
		}
		if (!categorySupport.controller().isPaused(CAT_GE_PNL))
		{
			PanelWidgets.setSignedGpLabel(geRealizedPnlValue, rawGePnl - gePnlBaseline);
		}
		if (!categorySupport.controller().isPaused(CAT_GE_POSITIONS))
		{
			PanelWidgets.setSignedGpLabel(gePositionsValue, rawGePositions);
		}
		if (!categorySupport.controller().isPaused(CAT_BANK))
		{
			PanelWidgets.setSignedGpLabel(bankValue, rawBankDelta);
		}

		rebaseIfJustReset(CAT_PROFIT, rawProfit, v -> profitBaseline = v);
		rebaseIfJustReset(CAT_SUPPLIES, rawSuppliesUsed, v -> suppliesBaseline = v);
		rebaseIfJustReset(CAT_NET_PROFIT, rawNetProfit, v -> netProfitBaseline = v);
		rebaseIfJustReset(CAT_PROFIT_PER_HOUR, rawProfitPerHour, v -> profitPerHourBaseline = v);
		rebaseIfJustReset(CAT_GE_PNL, rawGePnl, v -> gePnlBaseline = v);
		rebaseNetWorthChangeIfJustReset(rawNetProfit, rawGePnl, rawGePositions, rawBankDelta);

		refreshNetWorthChange();
		refreshSummary();
	}

	/**
	 * Captures ALL FOUR net-worth-change component baselines together,
	 * exactly once per "Net worth change" reset epoch — see the {@link
	 * #nwProfitBaseline} field javadoc for why per-component (not one
	 * aggregate) baselines are required.
	 */
	private void rebaseNetWorthChangeIfJustReset(long rawNetProfit, long rawGePnl,
		long rawGePositions, long rawBankDelta)
	{
		int epoch = categorySupport.controller().resetEpoch(CAT_NET_WORTH_DELTA);
		Integer lastEpoch = lastSeenEpoch.get(CAT_NET_WORTH_DELTA);
		if (lastEpoch == null)
		{
			lastSeenEpoch.put(CAT_NET_WORTH_DELTA, epoch);
			return;
		}
		if (epoch != lastEpoch)
		{
			nwProfitBaseline = rawNetProfit;
			nwGeFlipBaseline = rawGePnl;
			nwGePositionsBaseline = rawGePositions;
			nwBankBaseline = rawBankDelta;
			lastSeenEpoch.put(CAT_NET_WORTH_DELTA, epoch);
		}
	}

	/**
	 * Recomputes and renders the "Net worth change" total: Profit and GE flip
	 * (always included) plus whichever of GE positions/Bank is currently
	 * toggled on, each rebased against its OWN baseline captured at the last
	 * "Net worth change" reset (see {@link #computeNetWorthChangeTotal}).
	 * Called on every {@link #apply} and immediately on a toggle click, so
	 * unchecking a box updates the total without waiting for the next
	 * snapshot.
	 */
	private void refreshNetWorthChange()
	{
		if (categorySupport.controller().isPaused(CAT_NET_WORTH_DELTA))
		{
			return;
		}
		PanelWidgets.setSignedGpLabel(netWorthDeltaValue, computeNetWorthChangeTotal());
	}

	/**
	 * The "Net worth change" total from the last snapshot: each component
	 * rebased against its own reset-time baseline (zero if never reset), with
	 * GE positions/Bank included only while their toggle is checked. Per-
	 * component rebasing (rather than subtracting one aggregate baseline from
	 * a toggle-filtered total) keeps the figure stable across a toggle flip
	 * that happens after a reset — and equally across a reset that happens
	 * while a component is already toggled off.
	 */
	private long computeNetWorthChangeTotal()
	{
		long total = (lastRawNetProfit - nwProfitBaseline) + (lastRawGePnl - nwGeFlipBaseline);
		if (gePositionsToggle.isSelected())
		{
			total += lastRawGePositions - nwGePositionsBaseline;
		}
		if (bankToggle.isSelected())
		{
			total += lastRawBankDelta - nwBankBaseline;
		}
		return total;
	}

	/** Reset-epoch tracking per category, so a baseline is captured exactly once per "Reset" click. */
	private final java.util.Map<String, Integer> lastSeenEpoch = new java.util.HashMap<>();

	private void rebaseIfJustReset(String categoryId, long rawValue, java.util.function.LongConsumer setBaseline)
	{
		int epoch = categorySupport.controller().resetEpoch(categoryId);
		Integer lastEpoch = lastSeenEpoch.get(categoryId);
		if (lastEpoch == null)
		{
			lastSeenEpoch.put(categoryId, epoch);
			return;
		}
		if (epoch != lastEpoch)
		{
			setBaseline.accept(rawValue);
			lastSeenEpoch.put(categoryId, epoch);
		}
	}

	@Override
	public void removeAllCategoryOverlays()
	{
		categorySupport.removeAllOverlays();
	}

	/**
	 * Full panel reset (feature 11): drop the per-category "Reset" baselines
	 * back to zero and forget every paused/reset category, so the next snapshot
	 * shows the freshly re-anchored engine figures rather than a phantom.
	 *
	 * <p>This is the fix for the "phantom profit on reset" bug: each displayed
	 * stat is {@code raw - baseline}, where a per-row "Reset" click captured
	 * {@code baseline = raw} at that instant. When the panel-wide Reset
	 * re-anchors the engine so {@code raw} returns to ~0, a stale non-zero
	 * baseline would render {@code 0 - baseline} — a large phantom of the
	 * opposite sign. Zeroing the baselines (and clearing {@link #lastSeenEpoch}
	 * so the next {@code apply} re-syncs the epoch without re-capturing a
	 * baseline) makes the fresh figure {@code raw - 0 = raw}.
	 */
	@Override
	public void resetState()
	{
		profitBaseline = 0;
		suppliesBaseline = 0;
		netProfitBaseline = 0;
		profitPerHourBaseline = 0;
		gePnlBaseline = 0;
		nwProfitBaseline = 0;
		nwGeFlipBaseline = 0;
		nwGePositionsBaseline = 0;
		nwBankBaseline = 0;
		elapsedMs = 0;
		displayedProfit = 0;
		lastRawNetProfit = 0;
		lastRawGePnl = 0;
		lastRawGePositions = 0;
		lastRawBankDelta = 0;
		lastSeenEpoch.clear();
		categorySupport.clearAll();
		refreshSummary();
	}

	// ------------------------------------------------- test seams (package)

	long displayedProfitForTest()
	{
		return displayedProfit;
	}

	boolean isPausedForTest(String categoryId)
	{
		return categorySupport.controller().isPaused(categoryId);
	}

	/** Simulates the per-row "Reset" right-click action (bumps the category's reset epoch). */
	void resetCategoryForTest(String categoryId)
	{
		categorySupport.controller().reset(categoryId, System.currentTimeMillis());
	}

	void pauseCategoryForTest(String categoryId, boolean paused)
	{
		categorySupport.controller().setPaused(categoryId, paused);
	}

	/** The currently-displayed "Net worth change" total (post-toggle, post-reset-baseline). */
	long netWorthChangeForTest()
	{
		return computeNetWorthChangeTotal();
	}

	void setGePositionsToggleForTest(boolean included)
	{
		gePositionsToggle.setSelected(included);
		refreshNetWorthChange();
	}

	void setBankToggleForTest(boolean included)
	{
		bankToggle.setSelected(included);
		refreshNetWorthChange();
	}

	void setSplitToggleForTest(boolean expanded)
	{
		splitToggle.setSelected(expanded);
		breakdownPanel.setVisible(expanded);
	}

	boolean isBreakdownVisibleForTest()
	{
		return breakdownPanel.isVisible();
	}

	@Override
	protected String summaryText()
	{
		return PanelWidgets.formatElapsed(elapsedMs) + "  " + GpFormat.format(displayedProfit);
	}
}

