	/**
	 * Wires the bank-tags collaborator the "Show in bank" toggle drives.
	 * Defaults to {@code null} (toggle is a no-op) until the plugin assembles
	 * this — mirrors {@link com.ospulse.ui.OSPulsePanel#setResetCallback}.
	 */
	public void setBankHighlighter(com.ospulse.integration.BankRecommendationHighlighter bankHighlighter)
	{
		this.bankHighlighter = bankHighlighter;
	}

	/**
	 * Un-toggles "Show in bank" and drops any active bank-tag filter. Called
	 * from every place the optimiser result is invalidated or superseded
	 * (reset/clear, a new search starting, the result being applied to the
	 * what-if readout, target change) so the highlight never outlives the
	 * result it was generated from.
	 */
	/**
	 * The optimiser result's loadout as an equipment-slot-ordinal -> item-id
	 * map (for the bank layout). Each id is resolved via {@link
	 * #resolvedItemId} (Codex review finding #1, PR #5) so the bank
	 * highlight points at the exact item the suggested-swaps row/applied
	 * preview shows — an owned fortified/imbued item whose plain base id got
	 * the ownership-map treatment highlights the OWNED variant in the bank,
	 * not the plain form the player doesn't have.
	 */
	private java.util.Map<Integer, Integer> loadoutSlotMap(GearOptimizer.Result result)
	{
		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		java.util.Map<Integer, Long> ownedIds = ownedPriceMap();
		java.util.Set<Integer> heldIds = HeldItemIds.from(lastWealth, lastGear, index);
		java.util.Map<Integer, Integer> map = new java.util.LinkedHashMap<>();
		for (GearOptimizer.SlotChoice choice : result.loadout())
		{
			if (choice.itemId() > 0)
			{
				map.put(choice.slotOrdinal(), resolvedItemId(index, choice, ownedIds, heldIds));
			}
		}
		return map;
	}

	/**
	 * The "don't forget" consumables items (e.g. an antifire potion) for
	 * {@link #selectedMonster}, if any, so {@link #bankHighlighter} can lay
	 * them out beneath the recommended equipment grid alongside the note
	 * already shown in the side panel (B9-x). Combines {@link
	 * MonsterConsumablesReminder#equipmentItemIds()} (verified against the
	 * equipment index) and {@link MonsterConsumablesReminder#consumableItemIds()}
	 * (verified against the runelite-api jar's {@code ItemID} constants
	 * instead — potions aren't equipment), equipment ids first, de-duplicated,
	 * order preserved. Uses {@code lookupName()}, not {@code name()}, so
	 * synthetic Wilderness twins resolve to the real monster's curated data.
	 * Empty when there's no target or no reminder — or when the reminder is
	 * prose-only and carries no item ids at all.
	 */
	private java.util.List<Integer> bankConsumableIds()
	{
		if (selectedMonster == null)
		{
			return java.util.Collections.emptyList();
		}
		java.util.Optional<MonsterConsumablesReminder> reminder =
			MonsterConsumablesRepository.getInstance().forMonster(selectedMonster.lookupName());
		if (!reminder.isPresent())
		{
			return java.util.Collections.emptyList();
		}
		java.util.LinkedHashSet<Integer> ids = new java.util.LinkedHashSet<>(reminder.get().equipmentItemIds());
		ids.addAll(reminder.get().consumableItemIds());
		return new java.util.ArrayList<>(ids);
	}

	/** Test seam for {@link #bankConsumableIds()} — the combined equipment+consumable bank tag ids. */
	java.util.List<Integer> bankConsumableItemIdsForTest()
	{
		return bankConsumableIds();
	}

	private void resetBankHighlightToggle()
	{
		if (bankHighlighter != null)
		{
			bankHighlighter.clear();
		}
	}

	// ----------------------------------------------------------- gear grid

	/**
	 * A centered, equipment-tab-shaped grid of the player's worn item icons —
	 * populated live in {@link #apply} from {@link GearSnapshot#equippedItemIds()}
	 * via the EDT-safe async {@code ItemManager.getImage(int)}.
	 */
	private JPanel buildGearGrid()
	{
		// Row 0 is built separately from the rest of the silhouette: a green
		// "Find Best" and red "Revert" button flank the helmet (item #7b
		// redesign). The side columns carry equal weight so the helmet stays
		// centred — and, because the whole top row and the grid below are both
		// centre-aligned in the stack, the helmet lines up exactly over the
		// body column. The buttons live outside the equipment GridLayout, so
		// they can be wider than a slot without stretching the silhouette.
		JPanel topRow = new JPanel(new GridBagLayout());
		topRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		topRow.setAlignmentX(Component.CENTER_ALIGNMENT);
		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridy = 0;

		findBestGridButton = RoundedButton.action("Find Best", FIND_BEST_GREEN, Color.WHITE,
			"Find best setup", e -> runAndRankStyles());
		findBestGridButton.setPreferredSize(new Dimension(74, 24));
		gbc.gridx = 0;
		gbc.weightx = 1;
		gbc.anchor = GridBagConstraints.WEST;
		topRow.add(findBestGridButton, gbc);

		gbc.gridx = 1;
		gbc.weightx = 0;
		gbc.anchor = GridBagConstraints.CENTER;
		gbc.insets = new Insets(0, 6, 0, 6);
		topRow.add(buildSlotCell(0), gbc);
		gbc.insets = new Insets(0, 0, 0, 0);

		revertGridButton = RoundedButton.action("Reset", REVERT_RED, Color.WHITE,
			"Reset to your current worn gear", e -> resetAllOverrides());
		revertGridButton.setPreferredSize(new Dimension(74, 24));
		gbc.gridx = 2;
		gbc.weightx = 1;
		gbc.anchor = GridBagConstraints.EAST;
		topRow.add(revertGridButton, gbc);

		// Rows 1-4 of the equipment silhouette (SLOT_GRID index 3 onward — the
		// helmet at index 1 is already placed in the top row above).
		JPanel grid = new JPanel(new GridLayout(4, 3, 2, 2));
		grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		grid.setAlignmentX(Component.CENTER_ALIGNMENT);
		for (int i = 3; i < SLOT_GRID.length; i++)
		{
			int slotOrdinal = SLOT_GRID[i];
			if (slotOrdinal < 0)
			{
				if (i == SPEC_WEAPON_GRID_INDEX)
				{
					// Design spec §8: "it'd fit nicely between the weapon and
					// glove slots" — exactly this otherwise-unused filler cell.
					grid.add(specWeaponCell);
					continue;
				}
				JLabel filler = new JLabel();
				filler.setOpaque(false);
				grid.add(filler);
				continue;
			}
			grid.add(buildSlotCell(slotOrdinal));
		}

		JPanel stack = new JPanel();
		stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
		stack.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Pin both rows to their natural size so the vertical BoxLayout does not
		// stretch the equipment grid out to the (wider) button row's width — that
		// stretch is what squished/spread the slot icons across the panel.
		topRow.setMaximumSize(topRow.getPreferredSize());
		grid.setMaximumSize(grid.getPreferredSize());
		stack.add(topRow);
		stack.add(Box.createRigidArea(new Dimension(0, 2)));
		stack.add(grid);

		// Center the stack within the (BoxLayout, left-aligned) section body.
		JPanel wrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrapper.add(stack);
		wrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, wrapper.getPreferredSize().height));
		return wrapper;
	}

	/**
	 * Builds one live equipment-slot cell for {@link #buildGearGrid}. Registers
	 * the cell in {@link #slotLabels} and wires the left-click item-swap search
	 * plus the right-click "Exclude from suggestions" popup. Shared by the
	 * helmet (top row) and every other worn slot.
	 */
	private CrossableSlotLabel buildSlotCell(int slotOrdinal)
	{
		CrossableSlotLabel cell = new CrossableSlotLabel();
		cell.setOpaque(true);
		cell.setBackground(ColorScheme.DARK_GRAY_COLOR);
		cell.setHorizontalAlignment(SwingConstants.CENTER);
		cell.setVerticalAlignment(SwingConstants.CENTER);
		cell.setPreferredSize(new Dimension(SLOT_W, SLOT_H));
		cell.setToolTipText(SLOT_NAMES[slotOrdinal] + " slot (live) — click to try a different item");
		cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		slotLabels[slotOrdinal] = cell;
		renderedSlotIds[slotOrdinal] = Integer.MIN_VALUE;
		int clickedSlot = slotOrdinal;
		cell.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				// Right-click (popup trigger) on a cell showing a real item
				// offers "Exclude from suggestions" — Jonathan wanted this while
				// previewing an optimiser setup. Left-click still opens the
				// item-swap search. (Popup trigger fires on press on Linux and
				// release on Windows, so it is checked in both handlers.)
				if (maybeShowSlotExcludePopup(e, clickedSlot))
				{
					return;
				}
				if (SwingUtilities.isLeftMouseButton(e))
				{
					toggleItemSearch(clickedSlot);
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				maybeShowSlotExcludePopup(e, clickedSlot);
			}
		});
		return cell;
	}

	/**
	 * An equipment-slot cell that can paint a bold red diagonal strike-through
	 * over its icon (see {@link #setCrossedOut}) — used by {@link #updateGearGrid}
	 * to mark an individual slot "unusable" when {@link #isSlotInvalidForTarget}
	 * flags it (e.g. the weapon that can't damage the target), the same
	 * paintComponent-override approach as {@link
	 * HintableToggleButton}'s right-click-hint marker.
	 */
	private static final class CrossableSlotLabel extends JLabel
	{
		private boolean crossedOut;

		void setCrossedOut(boolean value)
		{
			if (value != crossedOut)
			{
				crossedOut = value;
				repaint();
			}
		}

		@Override
		protected void paintComponent(java.awt.Graphics g)
		{
			super.paintComponent(g);
			if (!crossedOut)
			{
				return;
			}
			java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
					java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(ColorScheme.PROGRESS_ERROR_COLOR);
				g2.setStroke(new java.awt.BasicStroke(2.5f));
				g2.drawLine(2, 2, getWidth() - 2, getHeight() - 2);
			}
			finally
			{
				g2.dispose();
			}
		}
	}

	/** Thin bright-orange border marking a Phase 2 what-if override the player must BUY (not owned) — the "you still need this" colour (item #3). */
	static final Border OVERRIDE_BORDER = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE, 2);

	/**
	 * Thin dull-grey border marking a Phase 2 what-if override the player
	 * already OWNS (worn elsewhere, or sitting in the bank/inventory) —
	 * deliberately muted next to {@link #OVERRIDE_BORDER} so "you already have
	 * this" reads as distinct from "you need to buy this" at a glance (item #3).
	 */
	static final Border OWNED_OVERRIDE_BORDER = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 2);

	/**
	 * Thin red border marking the WEAPON or SHIELD slot's currently SHOWN item
	 * (override id if overridden, else the live worn id) as invalid for the
	 * selected target — see {@link #isSlotInvalidForTarget} (A6). Combined with
	 * {@link #OVERRIDE_BORDER}/{@link #OWNED_OVERRIDE_BORDER} via
	 * {@link BorderFactory#createCompoundBorder} when the slot is ALSO
	 * overridden, so both signals show at once.
	 */
	static final Border INVALID_BORDER = BorderFactory.createLineBorder(ColorScheme.PROGRESS_ERROR_COLOR, 2);

	/**
	 * Diff-updates the worn-gear icon grid; only touched slots reload their
	 * sprite. Shows the what-if override's item in any overridden slot instead
	 * of the real worn item, bordered so an owned recommendation
	 * ({@link #OWNED_OVERRIDE_BORDER}, dull grey) is told apart from a must-buy
	 * one ({@link #OVERRIDE_BORDER}, bright orange) — see {@link #override}.
	 */
	private void updateGearGrid(GearSnapshot gear)
	{
		int[] ids = gear == null ? null : gear.equippedItemIds();
		// Owned-item lookup for the preview tooltips below — only needed while
		// at least one slot is overridden (i.e. a what-if/optimiser preview).
		java.util.Map<Integer, Long> ownedIds = override.isEmpty() ? null : ownedPriceMap();
		EquipmentIndexRepository index = override.isEmpty() ? null : EquipmentIndexRepository.getInstance();
		for (int slot = 0; slot < slotLabels.length; slot++)
		{
			JLabel cell = slotLabels[slot];
			if (cell == null)
			{
				continue;
			}
			boolean overridden = override.hasOverride(slot);
			int liveId = ids == null || slot >= ids.length ? -1 : ids[slot];
			int id = overridden ? override.itemIdFor(slot) : liveId;
			// Item #3: an owned-but-not-worn recommendation gets the duller grey
			// border, a must-buy one keeps the bright orange — same ownership
			// check the preview tooltip below already relies on (an emptied slot,
			// id <= 0, counts as owned = grey).
			boolean ownedItem = id <= 0 || (ownedIds != null && ownedIds.containsKey(id));
			Border recommendedBorder = ownedItem ? OWNED_OVERRIDE_BORDER : OVERRIDE_BORDER;
			// Only the genuinely-unusable slot is flagged — the weapon that can't
			// damage the target (Kurask: needs leaf-bladed/broad/magic), or a
			// required-gear slot holding the wrong item. The rest of the worn set
			// is perfectly usable, so it renders normally (no red border / cross).
			boolean invalid = isSlotInvalidForTarget(slot, id);
			cell.setBorder(invalid
				? (overridden ? BorderFactory.createCompoundBorder(INVALID_BORDER, recommendedBorder) : INVALID_BORDER)
				: (overridden ? recommendedBorder : null));
			if (cell instanceof CrossableSlotLabel)
			{
				((CrossableSlotLabel) cell).setCrossedOut(invalid);
			}
			// Item #6f (second site): the cell tooltip must describe what the
			// cell is actually SHOWING. While previewing it names the previewed
			// item + the real slot + whether the item is even owned, instead of
			// the misleading static "<slot> slot (live)" text over preview
			// content. Refreshed before the icon diff-guard below since the
			// override/owned state can change without the item id changing.
			if (overridden)
			{
				cell.setToolTipText(itemDisplayName(index, id) + " — " + SLOT_NAMES[slot] + " slot (preview"
					+ (ownedItem ? "" : ", not owned") + ") — click to try a different item");
			}
			else if (slot == WhatIfLoadout.AMMO_SLOT && id > 0)
			{
				// The ammo slot's icon alone often can't be told apart at a glance
				// (many arrows/bolts/blessing charges share a near-identical
				// sprite), so — unlike the other slots' generic "<Slot> slot
				// (live)" wording — this one names the actual worn item. index
				// is only built above when an override exists, so fetch it here
				// too (a cheap lazily-cached singleton — see
				// EquipmentIndexRepository#getInstance).
				EquipmentIndexRepository liveIndex = index != null ? index : EquipmentIndexRepository.getInstance();
				cell.setToolTipText(itemDisplayName(liveIndex, id) + " — Ammo slot (live) — click to try a different item");
			}
			else
			{
				cell.setToolTipText(SLOT_NAMES[slot] + " slot (live) — click to try a different item");
			}
			if (id == renderedSlotIds[slot])
			{
				continue;
			}
			renderedSlotIds[slot] = id;
			if (id > 0 && itemManager != null)
			{
				// EDT-safe: getImage is async (AsyncBufferedImage), the ONLY
				// ItemManager call permitted off the client thread.
				itemManager.getImage(id).addTo(cell);
			}
			else
			{
				cell.setIcon(null);
			}
		}
	}

	/**
	 * A6: true when the item currently shown in {@code slot} ({@code
	 * shownId} — the override id if the slot is overridden, else the live
	 * worn id) is invalid for {@link #selectedMonster}. Only WEAPON and
	 * SHIELD are ever flagged; every other slot always returns {@code false}
	 * (unchanged border logic), and there's no selected monster there's
	 * nothing to be invalid against.
	 * <ul>
	 * <li>WEAPON: there is a combat requirement for the target and the shown
	 * weapon/ammo/selected-style combo can't damage it — the same gate A5
	 * uses to grey out unusable attack styles.</li>
	 * <li>SHIELD: the target has a REQUIRED_GEAR override targeting the
	 * shield slot and the shown shield isn't the required item (e.g.
	 * Basilisk with an Avernic defender instead of the mirror shield).</li>
	 * </ul>
	 */
	private boolean isSlotInvalidForTarget(int slot, int shownId)
	{
		if (selectedMonster == null)
		{
			return false;
		}
		// Weapon gate (e.g. Kurask): the equipped weapon can't damage the target.
		if (slot == WEAPON_SLOT)
		{
			MonsterCombatRequirement combatReq =
				MonsterCombatRequirementRepository.getInstance().forMonster(selectedMonster.lookupName()).orElse(null);
			// selectedStyle is null when EVERY style was gated out — i.e. the
			// weapon has no attack style that can damage this target (the
			// Kurask-with-a-whip case), which is itself invalid.
			if (combatReq != null
				&& (selectedStyle == null
					|| !combatReq.permits(shownId, selectedStyle.type(), effectiveAmmoId())))
			{
				return true;
			}
		}
		// Required-gear override for THIS slot not worn (mirror shield vs
		// Basilisk, insulated boots vs Rune dragons, ...): flag red on ANY slot.
		// Finding 3 fix: a slot can have more than one acceptable item (e.g. a
		// Slayer helmet substitutes for a Dust devil's Facemask requirement —
		// see MonsterGearOverride#satisfiedBy) via either a separate override
		// entry for the same slot or one entry's alternativeItemIds, so this
		// must only flag invalid when the slot has an override AND shownId
		// satisfies NONE of them — not as soon as any single entry mismatches.
		boolean sawOverrideForSlot = false;
		for (MonsterGearOverride override : MonsterGearOverrideRepository.getInstance().forMonster(selectedMonster.lookupName()))
		{
			if (override.slot().slotOrdinal() != slot)
			{
				continue;
			}
			if (override.satisfiedBy(shownId))
			{
				return false;
			}
			sawOverrideForSlot = true;
		}
		return sawOverrideForSlot;
	}

	// ------------------------------------------------- attack-style picker

	/** Uniform height the bundled damage-type icons are scaled to for the selector row. */
	private static final int STYLE_ICON_HEIGHT = 18;

	/** Lazily-loaded, scaled damage-type icons for the optimiser style selector, keyed by style. */
	private static final java.util.Map<CombatStyle, ImageIcon> STYLE_ICONS = new java.util.EnumMap<>(CombatStyle.class);

	/**
	 * The bundled damage-type icon (Stab/Slash/Crush/Magic/Ranged sprite) for the
	 * optimiser style selector, scaled to a uniform {@link #STYLE_ICON_HEIGHT} so
	 * the segmented buttons align. Cached per style; returns {@code null} if the
	 * resource is missing so callers fall back to the text {@link CombatStyleLabel}.
	 */
	private static ImageIcon styleIcon(CombatStyle type)
	{
		if (STYLE_ICONS.containsKey(type))
		{
			return STYLE_ICONS.get(type);
		}
		String file = styleIconFile(type);
		ImageIcon icon = null;
		if (file != null)
		{
			BufferedImage img = ImageUtil.loadImageResource(GearSection.class, "/com/ospulse/ui/style/" + file);
			if (img != null)
			{
				int w = Math.max(1, img.getWidth() * STYLE_ICON_HEIGHT / img.getHeight());
				icon = new ImageIcon(img.getScaledInstance(w, STYLE_ICON_HEIGHT, Image.SCALE_SMOOTH));
			}
		}
		STYLE_ICONS.put(type, icon);
		return icon;
	}

	private static String styleIconFile(CombatStyle type)
	{
		switch (type)
		{
			case STAB:
				return "stab.png";
			case SLASH:
				return "slash.png";
			case CRUSH:
				return "crush.png";
			case RANGED:
				return "ranged.png";
			case MAGIC:
				return "magic.png";
			default:
				return null;
		}
	}


	/**
	 * Recomputes the equipped weapon's ranking (DPS-desc against the current
	 * target and boosts), rebuilds the clickable rows, re-selects the best (or
	 * keeps the user's pick if it survives), and refreshes the readout. Routes
	 * a magic weapon to the magic-first spellbook view and everything else to
	 * the classic ranked attack-style view. The single entry point whenever
	 * gear, target, boosts or the spellbook tab change.
	 */
	private void rankAndRender()
	{
		styleRows.clear();
		spellRows.clear();
		stylesPanel.removeAll();

		// effectiveWeaponId() honours a what-if weapon-slot swap (Phase 2) so a
		// hypothetical weapon re-ranks its own real styles/spells exactly like
		// equipping it for real would.
		int weaponId = effectiveWeaponId();
		if (weaponId != lastRankedWeaponId)
		{
			// A different weapon: its styles/spells differ, so any prior manual
			// pick no longer applies — fall back to auto-selecting the best.
			lastRankedWeaponId = weaponId;
			userPickedStyle = false;
			userPickedSpell = false;
			// The optimiser's 5-way selector follows the same rule (item #6e/#6g):
			// a manual damage-type pick — and any auto-picked best (item #1) —
			// is dropped on a weapon change so the selector re-detects from
			// whatever is now actually wielded.
			styleUserPicked = false;
			styleAutoPicked = false;
		}
		if (selectedMonster != lastRankedTarget)
		{
			// A new target re-ranks the spells, so a manual spell lock only holds
			// until the weapon or target changes (unlike the style lock, which
			// deliberately survives a target change).
			lastRankedTarget = selectedMonster;
			userPickedSpell = false;
		}

		// The risk cap is Wilderness-scoped, so its controls follow the target.
		refreshRiskCapEnabled();

		List<WeaponStyle> styles = new ArrayList<>(weaponRepo.stylesForItem(weaponId));
		currentWeaponCategory = weaponRepo.categoryFor(weaponId);
		EquipmentStats effectiveStats = effectiveEquipmentStats();
		PoweredStaff poweredStaff = effectiveStats != null ? effectiveStats.poweredStaff() : PoweredStaff.NONE;
		boolean canRank = lastGear != null && selectedMonster != null && effectiveStats != null;

		magicView = isMagicWeapon(weaponId, styles, poweredStaff);
		if (magicView)
		{
			// Magic weapon: magic-first view — melee/ranged rows are dropped and
			// the legacy spell combo is replaced by the ranked spell rows.
			spellPicker.setVisible(false);
			renderMagicView(weaponId, styles, poweredStaff, canRank);
		}
		else
		{
			renderStyleView(styles, poweredStaff, canRank);
		}

		stylesPanel.revalidate();
		stylesPanel.repaint();
		stylesScroll.revalidate();
		stylesScroll.repaint();
		body().revalidate();
		body().repaint();

		// Keep the optimiser's 5-way selector tracking the (possibly what-if)
		// equipped weapon's current style unless the user picked one (item #6g).
		syncStyleSelector();

		updateOutputs();
		updateSpecWeaponCell();
	}

	/**
	 * Recomputes {@link #specWeaponCell} for the currently selected target
	 * (design spec §8). Reuses the SAME weapon-slot-swap machinery {@code
	 * GearOptimizer} already relies on for ordinary candidate scoring ({@link
	 * WhatIfLoadout#effectiveItemIds} + {@link GearMapper#buildEquipmentStats})
	 * so every curated spec candidate is scored through the real {@code
	 * DpsCalculator}/{@code CombatMath} pipeline against the real target, with
	 * every other worn slot and every boost toggle held exactly as they are
	 * for the main readout — never a separate, drifting mini-calculator.
	 *
	 * <p>Every constraint the ordinary optimiser already enforces is threaded
	 * through here via the SAME seam rather than a second copy (PR #25
	 * findings): {@link #excludedItemIds} (the user's alias-symmetric
	 * "Exclude from suggestions" set) and {@link
	 * ItemEligibility#restrictedItemIds} (permanent, per-id mode-lock
	 * restrictions) are kept as TWO separate sets rather than merged into one
	 * — a round-2 fix: merging a restricted alias id (e.g. Voidwaker
	 * (deadman) 29607) into the same set the alias-symmetric {@code
	 * SpecWeapon.isExcluded} consumes wrongly suppressed the whole family
	 * (the ordinary, perfectly legal Voidwaker 27690 too), since {@link
	 * ItemEligibility#restrictedItemIds} is a per-id restriction, not a
	 * family-wide one. {@link #currentBaseLevels} (the exact
	 * map fed to {@code Request.playerBaseLevels}, which {@link
	 * SpecWeaponSelector#select} passes to {@link
	 * com.ospulse.combat.SpecWeapon#canEquip} — owning a Voidwaker at 60
	 * Attack does not mean it can be equipped), {@link #effectiveAmmoId} (fed
	 * to {@code MonsterCombatRequirement.permitsAmmo} for an ammo-gated
	 * target, since {@code permitsWeapon} alone deliberately accepts a
	 * worn-ammo-capable weapon type without checking which ammo is actually
	 * loaded), and the {@link WhatIfLoadout#isTwoHanded} 2H/shield collapse
	 * below (a two-handed candidate — e.g. Dragon claws — must clear the
	 * shield slot exactly as {@link LoadoutOverride#withWeaponSlot} does for
	 * an ordinary weapon-slot swap, or the scored stat total includes a
	 * shield the player could never actually have equipped alongside it).
	 */
	private void updateSpecWeaponCell()
	{
		if (lastGear == null || selectedMonster == null)
		{
			specWeaponCell.refresh(null, false, itemManager);
			return;
		}
		java.util.Set<Integer> ownedIds = ownedPriceMap().keySet();
		// Kept as TWO separate sets — see the method javadoc's round-2 fix note.
		java.util.Set<Integer> specExclusions = new java.util.LinkedHashSet<>(excludedItemIds);
		java.util.Set<Integer> specRestrictions = ItemEligibility.restrictedItemIds();
		java.util.Map<String, Integer> baseLevels = currentBaseLevels();
		int wornAmmoId = effectiveAmmoId();
		MonsterCombatRequirement requirement =
			MonsterCombatRequirementRepository.getInstance().forMonster(selectedMonster.lookupName()).orElse(null);
		int[] baseItemIds = WhatIfLoadout.effectiveItemIds(lastGear.equippedItemIds(), override);
		int blowpipeDartRangedStrength = currentBlowpipeDart().rangedStrength();
		SpecWeaponSelector.DpsProbe probe = weapon ->
		{
			WeaponStyle style = weapon.resolvedStyle(weaponRepo);
			if (style == null)
			{
				return null;
			}
			EquipmentStats swappedStats = swappedEquipmentStats(baseItemIds, weapon, blowpipeDartRangedStrength);
			return computeAgainst(swappedStats, style, weapon.itemId());
		};
		SpecWeaponRecommendation recommendation =
			SpecWeaponSelector.select(selectedMonster, requirement, ownedIds, specExclusions, specRestrictions,
					baseLevels, wornAmmoId, probe)
				.orElse(null);
		// A target IS selected here (guarded above) — a null recommendation past
		// this point means nothing owned+legal qualifies, not "no target"
		// (PR #25 finding), so SpecWeaponCell must be told a target IS selected.
		specWeaponCell.refresh(recommendation, true, itemManager);
	}

	/**
	 * {@link EquipmentStats} for {@code liveItemIds} with {@code weapon}
	 * swapped into the weapon slot — the same swap-one-slot machinery
	 * {@code GearOptimizer} uses for ordinary candidate scoring, plus the
	 * SAME 2H/shield collapse {@link LoadoutOverride#withWeaponSlot} applies
	 * for an ordinary weapon-slot swap (PR #25 finding 3): a two-handed
	 * candidate (e.g. Dragon claws) clears the shield slot rather than
	 * scoring alongside it, since the two can never actually coexist and
	 * summing both would credit an impossible stat total.
	 *
	 * <p>{@code blowpipeDartRangedStrength} is threaded through to {@link
	 * GearMapper}'s 4-arg overload (round-3 fix) so a Toxic blowpipe
	 * candidate is scored with the player's actually-configured dart ({@link
	 * #currentBlowpipeDart}), not the 3-arg overload's hard-coded Dragon-dart
	 * default — a probe scored against a dart the player never loaded is
	 * stronger than their real loadout and can wrongly outrank another owned
	 * spec.
	 */
	private static EquipmentStats swappedEquipmentStats(int[] liveItemIds, SpecWeapon weapon, int blowpipeDartRangedStrength)
	{
		int[] swapped = liveItemIds.clone();
		swapped[WhatIfLoadout.WEAPON_SLOT] = weapon.itemId();
		if (WhatIfLoadout.isTwoHanded(weapon.itemId()))
		{
			swapped[WhatIfLoadout.SHIELD_SLOT] = LoadoutOverride.EMPTIED;
		}
		return GearMapper.buildEquipmentStats(swapped, WhatIfLoadout.WEAPON_SLOT, BundledSlotStatsLookup.INSTANCE,
			blowpipeDartRangedStrength);
	}

	/**
	 * Test seam (PR #25 finding 3): the {@link EquipmentStats} {@link
	 * #updateSpecWeaponCell} would score {@code weapon} against, given the
	 * CURRENT live/what-if loadout — lets a test assert directly on the
	 * resulting bonuses (e.g. that an equipped shield's strength bonus is
	 * excluded for a two-handed candidate) without depending on a specific
	 * ranking outcome through the full DPS pipeline. Mirrors {@link
	 * #updateSpecWeaponCell}'s own use of {@link #currentBlowpipeDart} so a
	 * blowpipe candidate is scored the exact same way here as it would be
	 * live.
	 */
	EquipmentStats swappedEquipmentStatsForTest(SpecWeapon weapon)
	{
		int[] baseItemIds = WhatIfLoadout.effectiveItemIds(lastGear.equippedItemIds(), override);
		return swappedEquipmentStats(baseItemIds, weapon, currentBlowpipeDart().rangedStrength());
	}

	/**
	 * The player's base skill levels (lowercase skill-name keys), shared by
	 * {@link #buildRequest} (feeds {@code
	 * GearOptimizer.Request.playerBaseLevels}) and {@link
	 * #updateSpecWeaponCell} (feeds {@code SpecWeaponSelector.select}) so
	 * both consumers of the equip-requirement gate read the exact same map
	 * instead of two independently-maintained copies. {@code null} caller
	 * guard: both call sites already require {@link #lastGear} to be
	 * non-null before reaching here.
	 */
	private java.util.Map<String, Integer> currentBaseLevels()
	{
		java.util.Map<String, Integer> baseLevels = new java.util.HashMap<>();
		baseLevels.put("attack", lastGear.baseAttack());
		baseLevels.put("strength", lastGear.baseStrength());
		baseLevels.put("defence", lastGear.baseDefence());
		baseLevels.put("ranged", lastGear.baseRanged());
		baseLevels.put("magic", lastGear.baseMagic());
		baseLevels.put("prayer", lastGear.basePrayer());
		baseLevels.put("hitpoints", lastGear.baseHitpoints());
		baseLevels.put("slayer", lastGear.baseSlayer());
		baseLevels.put("agility", lastGear.baseAgility());
		return baseLevels;
	}

	/** Test seam: {@link #specWeaponCell}'s last-rendered item id for the current target (-1/{@code Integer.MIN_VALUE} if none). */
	int specWeaponCellItemIdForTest()
	{
		return specWeaponCell.renderedItemIdForTest();
	}

	/** Test seam (PR #25 finding): {@link #specWeaponCell}'s current tooltip, to distinguish "no target" from "no eligible weapon". */
	String specWeaponCellTooltipForTest()
	{
		return specWeaponCell.getToolTipText();
	}

	/**
	 * True when the equipped weapon should get the magic-first view: any worn
	 * powered staff, or a weapon whose combat options include a magic style —
	 * except the salamander, whose "Blaze" is its own built-in attack (it
	 * cannot autocast spellbook spells), so it keeps the classic ranked view.
	 */
	private boolean isMagicWeapon(int weaponId, List<WeaponStyle> styles, PoweredStaff poweredStaff)
	{
		if (poweredStaff.applies())
		{
			return true;
		}
		if (weaponRepo.categoryFor(weaponId) == WeaponCategory.SALAMANDER)
		{
			return false;
		}
		for (WeaponStyle style : styles)
		{
			if (style.type() == CombatStyle.MAGIC)
			{
				return true;
			}
		}
		return false;
	}

	/** The classic ranked attack-style rows (melee/ranged weapons — and the salamander, see isMagicWeapon). */
	private void renderStyleView(List<WeaponStyle> styles, PoweredStaff poweredStaff, boolean canRank)
	{
		stylesHeading.setText("Attack styles (best DPS first)");
		bookTabsPanel.setVisible(false);
		primaryRow.setVisible(false);
		secondaryRow.setVisible(false);

		// The legacy spell combo only remains relevant for a non-magic-view
		// weapon that still carries a magic style (the salamander's Blaze).
		boolean hasMagicStyle = false;
		for (WeaponStyle style : styles)
		{
			hasMagicStyle |= style.type() == CombatStyle.MAGIC;
		}
		spellPicker.setVisible(hasMagicStyle && !poweredStaff.applies());

		// Attack styles prefer a compact 2-column grid (e.g. Lunge | Stab /
		// Block | Slash) over a tall single-column list — but only when the
		// names actually fit it; placeStyleRows/StyleGrid decide per weapon and
		// report back how many visual rows resulted.
		renderRankedStyleRows(styles, canRank, true);
		setStylesViewportRows(Math.min(Math.max(lastStyleVisualRows, 1), STYLES_VISIBLE_ROWS));
	}

	/**
	 * Sizes the attack-styles viewport to {@code rows} grid rows so the
	 * 2-column melee/ranged view is a compact block rather than a tall, mostly
	 * empty scroll box (the fixed 5-row height is only needed for the magic
	 * spell list).
	 */
	private void setStylesViewportRows(int rows)
	{
		int h = rows * (STYLE_ROW_HEIGHT + 2) + 4;
		stylesScroll.setPreferredSize(new Dimension(0, h));
		stylesScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
	}

	/**
	 * The magic-first view for a magic weapon: spellbook tabs + ranked spell
	 * rows (autocast weapons), or the weapon's built-in-spell combat options
	 * (powered staves, which cannot autocast), plus the primary/secondary cast
	 * readout in both variants.
	 */
	private void renderMagicView(int weaponId, List<WeaponStyle> styles, PoweredStaff poweredStaff, boolean canRank)
	{
		// The magic view keeps the vertical spell/option list (Standard book
		// alone is ~25 rows) at the fixed 5-row viewport height. stylesPanel is
		// permanently a BoxLayout — the melee/ranged grid is a sub-panel inside
		// it, cleared by rankAndRender, so there is no layout to undo here.
		setStylesViewportRows(STYLES_VISIBLE_ROWS);

		// The stance carrier for spell computes: the weapon's own magic combat
		// option ("Spell"/STANDARD on a staff, "Accurate" on a powered staff).
		magicCastStyle = null;
		for (WeaponStyle style : styles)
		{
			if (style.type() == CombatStyle.MAGIC)
			{
				magicCastStyle = style;
				break;
			}
		}
		if (magicCastStyle == null)
		{
			// e.g. a powered staff missing from the category data — cast anyway.
			magicCastStyle = new WeaponStyle("Spell", CombatStyle.MAGIC, Stance.STANDARD);
		}

		primaryRow.setVisible(true);
		secondaryRow.setVisible(true);

		if (poweredStaff.applies())
		{
			// Built-in spell: the spellbook is irrelevant (powered staves cannot
			// autocast), so rank the weapon's own magic combat options instead of
			// a spell list — the engine derives the max hit from the Magic level.
			stylesHeading.setText("Magic — built-in spell (best DPS first)");
			bookTabsPanel.setVisible(false);
			selectedSpell = null;

			List<WeaponStyle> magicStyles = new ArrayList<>();
			for (WeaponStyle style : styles)
			{
				if (style.type() == CombatStyle.MAGIC)
				{
					magicStyles.add(style);
				}
			}
			if (magicStyles.isEmpty())
			{
				magicStyles.add(magicCastStyle);
			}
			List<Ranked> ranked = renderRankedStyleRows(magicStyles, canRank, false);
			setPrimarySecondary(
				readout(ranked.isEmpty() ? null : ranked.get(0).style.name(),
					ranked.isEmpty() ? null : ranked.get(0).result),
				readout(ranked.size() > 1 ? ranked.get(1).style.name() : null,
					ranked.size() > 1 ? ranked.get(1).result : null));
			return;
		}

		// Autocast weapon: spellbook tabs + that book's offensive spells, ranked.
		stylesHeading.setText("Spells (best DPS first)");
		bookTabsPanel.setVisible(true);
		syncBookTabs();
		selectedStyle = magicCastStyle;

		List<Spell> candidates = spellsFor(selectedBook, weaponId);
		if (candidates.isEmpty())
		{
			// Lunar/Arceuus: render the tab, but there is nothing to rank.
			selectedSpell = null;
			JLabel none = PanelWidgets.emptyRowLabel("No offensive spells on this spellbook");
			none.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			none.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.ITALIC));
			stylesPanel.add(none);
			setPrimarySecondary("-", "-");
			return;
		}

		List<RankedSpell> ranked = new ArrayList<>(candidates.size());
		for (Spell spell : candidates)
		{
			ranked.add(new RankedSpell(spell, canRank ? computeSpell(spell) : null));
		}
		if (canRank)
		{
			// Stable sort: equal-DPS spells keep their spellbook order.
			ranked.sort(Comparator.comparingDouble((RankedSpell r) -> r.result.dps()).reversed());
		}

		// Follow the best-DPS spell (top of the ranking) by default; only honour
		// a prior selection when the user explicitly clicked a spell row and the
		// weapon, target and spellbook that produced it are unchanged.
		Spell keep = null;
		if (userPickedSpell)
		{
			for (RankedSpell r : ranked)
			{
				if (r.spell == selectedSpell)
				{
					keep = r.spell;
					break;
				}
			}
		}
		selectedSpell = keep != null ? keep : ranked.get(0).spell;

		for (int i = 0; i < ranked.size(); i++)
		{
			RankedSpell r = ranked.get(i);
			boolean best = canRank && i == 0;
			SpellRow row = new SpellRow(r.spell, r.result, best);
			spellRows.add(row);
			stylesPanel.add(row);
			stylesPanel.add(Box.createRigidArea(new Dimension(0, 2)));
		}
		highlightSelectedSpellRow();

		// Primary = the auto-selected best; secondary = the next-best DPS.
		// TODO: current-cast spell when the snapshot exposes it — the secondary
		// should then prefer the spell actually being autocast in game.
		setPrimarySecondary(
			readout(ranked.get(0).spell.displayName(), ranked.get(0).result),
			ranked.size() > 1 ? readout(ranked.get(1).spell.displayName(), ranked.get(1).result) : "-");
	}

	/**
	 * Computes, ranks (DPS-desc) and renders one clickable row per style,
	 * re-selecting the best or keeping a surviving user pick. Shared by the
	 * classic style view and the powered-staff magic view.
	 */
	/**
	 * @param gridMode true for the melee/ranged view, which may pair rows into
	 *                 a 2-column grid; false for the magic view's plain
	 *                 vertical spell list. Passed in rather than sniffed from
	 *                 the layout: {@code stylesPanel} is always a BoxLayout
	 *                 now, and the grid (when it fits) is a sub-panel inside
	 *                 it — see {@link #placeStyleRows}.
	 */
	private List<Ranked> renderRankedStyleRows(List<WeaponStyle> styles, boolean canRank, boolean gridMode)
	{
		// Styles the selected target's combat requirement forbids are excluded
		// from ranking/DPS entirely (never ranked, never auto-selected) and
		// instead rendered as greyed, non-interactive rows below the ranked
		// ones. Ordinary monsters (no requirement) are unaffected.
		MonsterCombatRequirement combatReq = selectedMonster == null ? null
			: MonsterCombatRequirementRepository.getInstance().forMonster(selectedMonster.lookupName()).orElse(null);
		int gateWeaponId = effectiveWeaponId();
		int gateAmmoId = effectiveAmmoId();

		// Compute each style's DPS (null when we cannot yet), then rank desc.
		List<Ranked> ranked = new ArrayList<>(styles.size());
		List<WeaponStyle> gated = new ArrayList<>();
		for (WeaponStyle style : styles)
		{
			if (combatReq != null && !combatReq.permits(gateWeaponId, style.type(), gateAmmoId))
			{
				gated.add(style);
				continue;
			}
			DpsResult result = canRank ? computeFor(style) : null;
			ranked.add(new Ranked(style, result));
		}
		if (canRank)
		{
			ranked.sort(Comparator.comparingDouble((Ranked r) -> r.result.dps()).reversed());
		}

		// Follow the best-DPS style (top of the ranking) by default; only honour a
		// prior selection when the user explicitly clicked a row and it survives.
		WeaponStyle keep = null;
		if (userPickedStyle)
		{
			for (Ranked r : ranked)
			{
				if (r.style.equals(selectedStyle))
				{
					keep = r.style;
					break;
				}
			}
		}
		selectedStyle = keep != null ? keep : (ranked.isEmpty() ? null : ranked.get(0).style);

		List<JComponent> built = new ArrayList<>(ranked.size() + gated.size());
		for (int i = 0; i < ranked.size(); i++)
		{
			Ranked r = ranked.get(i);
			boolean best = canRank && i == 0;
			StyleRow row = new StyleRow(r.style, r.result, best);
			styleRows.add(row);
			built.add(row);
		}

		for (WeaponStyle style : gated)
		{
			// A5: keep the same icon + name look as a ranked row (a plain grey
			// JLabel lost the per-style icon and didn't match), just greyed
			// out with a "0" DPS and not selectable — see the StyleRow(style,
			// gated) constructor below.
			built.add(new StyleRow(style, true));
		}
		if (ranked.isEmpty() && !gated.isEmpty())
		{
			JLabel warningLabel = PanelWidgets.emptyRowLabel("No usable style — see the requirement note above.");
			warningLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			built.add(warningLabel);
		}

		lastStyleVisualRows = placeStyleRows(built, gridMode);
		highlightSelectedRow();
		return ranked;
	}

	/**
	 * Adds the built style rows to {@code stylesPanel} and returns how many
	 * VISUAL rows they occupy (which drives the viewport height).
	 *
	 * <p>{@code gridMode} false is the magic view: a plain vertical list.
	 * Otherwise the melee/ranged view asks {@link StyleGrid} whether the rows
	 * actually fit two columns at the current width; if they do, the paired
	 * rows go into a {@link GridLayout} sub-panel (GridLayout, not GridBag, so
	 * the two columns are exactly equal) and any odd row out is added straight
	 * to {@code stylesPanel} beneath it, where it spans the full width.
	 */
	private int placeStyleRows(List<JComponent> rows, boolean gridMode)
	{
		if (!gridMode)
		{
			for (JComponent row : rows)
			{
				stylesPanel.add(row);
				stylesPanel.add(Box.createRigidArea(new Dimension(0, 2)));
			}
			return rows.size();
		}

		// Prefer the REAL viewport width; it is 0 only before the first
		// layout, and rankAndRender re-runs on every gear/target change, so
		// the fallback is a first-paint estimate that self-corrects.
		int available = stylesScroll.getViewport().getWidth();
		if (available <= 0)
		{
			available = STYLES_VIEWPORT_WIDTH_ESTIMATE;
		}

		List<Integer> widths = new ArrayList<>(rows.size());
		for (JComponent row : rows)
		{
			widths.add(row.getPreferredSize().width);
		}
		boolean twoColumns = StyleGrid.fitsTwoColumns(widths, available, STYLE_GRID_HGAP);
		int spanning = StyleGrid.spanningRowIndex(rows.size(), twoColumns);

		if (!twoColumns)
		{
			for (JComponent row : rows)
			{
				stylesPanel.add(row);
				stylesPanel.add(Box.createRigidArea(new Dimension(0, 2)));
			}
			return rows.size();
		}

		int paired = spanning < 0 ? rows.size() : rows.size() - 1;
		if (paired > 0)
		{
			JPanel grid = new JPanel(new GridLayout(0, 2, STYLE_GRID_HGAP, 2));
			grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			grid.setAlignmentX(Component.LEFT_ALIGNMENT);
			for (int i = 0; i < paired; i++)
			{
				grid.add(rows.get(i));
			}
			grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, grid.getPreferredSize().height));
			stylesPanel.add(grid);
		}
		if (spanning >= 0)
		{
			if (paired > 0)
			{
				stylesPanel.add(Box.createRigidArea(new Dimension(0, 2)));
			}
			stylesPanel.add(rows.get(spanning));
		}
		return StyleGrid.visualRows(rows.size(), true);
	}

	/**
	 * The offensive spells of a spellbook tab (empty for Lunar/Arceuus — OSRS
	 * has no offensive nukes there), filtered to only those actually castable
	 * with the given weapon (see {@link Spell#isCastableWith(int)}) — e.g.
	 * Iban Blast never appears/ranks unless Iban's staff is equipped.
	 */
	private static List<Spell> spellsFor(BookTab tab, int weaponId)
	{
		if (tab.book() == null)
		{
			return Collections.emptyList();
		}
		List<Spell> spells = new ArrayList<>();
		for (Spell spell : Spell.values())
		{
			if (spell.book() == tab.book() && spell.isCastableWith(weaponId))
			{
				spells.add(spell);
			}
		}
		return spells;
	}

	/** "Name  ·  1.23" (or just the name pre-target, or "-" when absent) for the primary/secondary readout. */
	private static String readout(String name, DpsResult result)
	{
		if (name == null)
		{
			return "-";
		}
		return result == null ? name
			: "<html>" + escapeHtml(name) + " &middot; " + DpsFormat.fragment(result.dps()) + "</html>";
	}

	private void setPrimarySecondary(String primary, String secondary)
	{
		primaryValue.setText(primary);
		secondaryValue.setText(secondary);
	}

	// ------------------------------------------------- magic view widgets

	/** One tab of the spellbook segmented control; selection is driven by {@link #syncBookTabs}. */
	private JToggleButton bookTabButton(BookTab tab)
	{
		JToggleButton button = new JToggleButton(tab.label());
		button.setToolTipText(tab.label() + " spellbook");
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setMargin(new Insets(2, 1, 2, 1));

		Border selectedBorder = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE);
		Border unselectedBorder = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR);
		// Restyle on ANY selection change (user click or the programmatic
		// setSelected from syncBookTabs) — an ItemListener catches both.
		Runnable restyle = () ->
		{
			button.setBorder(button.isSelected() ? selectedBorder : unselectedBorder);
			button.setBackground(button.isSelected()
				? ColorScheme.MEDIUM_GRAY_COLOR
				: ColorScheme.DARKER_GRAY_COLOR);
			button.setForeground(button.isSelected()
				? ColorScheme.BRAND_ORANGE
				: ColorScheme.LIGHT_GRAY_COLOR);
		};
		restyle.run();
		button.addItemListener(e -> restyle.run());
		// Book-switch logic only on a USER click (an ActionListener does not fire
		// on programmatic setSelected, so syncBookTabs cannot recurse into here).
		button.addActionListener(e ->
		{
			if (selectedBook != tab)
			{
				selectedBook = tab;
				// A new book is a new ranking — follow its best spell again.
				userPickedSpell = false;
				rankAndRender();
				// If gear suggestions are already on screen, re-run so their DPS
				// follows the newly-selected spellbook too — not just the spell
				// readout that rankAndRender refreshes.
				if (lastOptimizerResult != null)
				{
					runOptimizer();
				}
			}
			else
			{
				// Clicking the active tab must not toggle it off.
				syncBookTabs();
			}
		});
		return button;
	}

	/** Re-asserts each tab button's selected state from {@link #selectedBook}. */
	private void syncBookTabs()
	{
		for (BookTab tab : BookTab.values())
		{
			JToggleButton button = bookTabButtons[tab.ordinal()];
			if (button != null && button.isSelected() != (tab == selectedBook))
			{
				button.setSelected(tab == selectedBook);
			}
		}
	}

