	/**
	 * The potion variant the potion toggle should show/apply for {@code style}:
	 * the user's right-click swap pick for that style if one was ever made
	 * (restored from config at startup — see {@link #loadVariants}),
	 * else {@link CombatIcons#bestPotion}'s default for that style.
	 */
	private CombatIcons.BoostPotion effectivePotionFor(CombatStyle style)
	{
		String key = styleKeyFor(style);
		if (key == null)
		{
			return null;
		}
		CombatIcons.BoostPotion picked = potionVariantByStyle.get(key);
		return picked != null ? picked : CombatIcons.bestPotion(style);
	}

	/**
	 * The offensive prayer the prayer toggle should show and {@link
	 * DpsCalculator} should apply for {@code style}: the user's right-click
	 * pick while the "best prayer" simulation ({@link #bestPrayerToggle}) is
	 * on, else the ladder-topped prayer for the player's real Prayer level
	 * (see {@link CombatIcons#bestOffensivePrayer}). With the toggle off the
	 * pick is ignored — the player's actually-active prayers win, exactly as
	 * {@link DpsCalculator} treats it.
	 */
	private OffensivePrayer effectivePrayerFor(CombatStyle style)
	{
		String key = styleKeyFor(style);
		OffensivePrayer picked = key == null ? null : prayerVariantByStyle.get(key);
		if (picked != null && bestPrayerToggle.isSelected())
		{
			return picked;
		}
		return CombatIcons.bestOffensivePrayer(
			style, lastGear != null ? lastGear.basePrayer() : 0, bestPrayerToggle.isSelected());
	}

	/**
	 * The prayer to feed {@link GearMapper#toPlayerCombat}/{@link
	 * PlayerCombat.Builder#assumedPrayer} for {@code style}: the swap-menu pick
	 * while {@link #bestPrayerToggle} is selected, else {@code null} so the
	 * calculator's own hardcoded top-tier fallback applies — mirrors {@link
	 * #buildRequest}'s identical rule for the optimizer request.
	 */
	private OffensivePrayer assumedPrayerFor(CombatStyle style)
	{
		return bestPrayerToggle.isSelected() ? prayerVariantByStyle.get(styleKeyFor(style)) : null;
	}

	/**
	 * The MAGIC-only variant actually fed to {@link DpsCalculator} — see
	 * {@link PlayerCombat#magicPotionVariant()}. Melee/Ranged variants never
	 * reach the calculator since their boost math is identical regardless of
	 * which variant is picked (see {@link CombatIcons.BoostPotion} javadoc).
	 */
	private CombatIcons.BoostPotion magicPotionVariantForCalc()
	{
		return potionVariantByStyle.get(styleKeyFor(CombatStyle.MAGIC));
	}

	/** Stable config-key fragment per style ("melee"/"ranged"/"magic"), or {@code null} for a style with no swappable variant. */
	private static String styleKeyFor(CombatStyle style)
	{
		if (style == null)
		{
			return null;
		}
		if (style.isMelee())
		{
			return "melee";
		}
		if (style == CombatStyle.RANGED)
		{
			return "ranged";
		}
		if (style == CombatStyle.MAGIC)
		{
			return "magic";
		}
		return null;
	}

	/**
	 * Restores each style's persisted right-click swap-menu pick from config
	 * — shared by the potion ({@code potionVariant.<style>}, see {@link
	 * #potionVariantByStyle}) and prayer ({@code prayerVariant.<style>}, see
	 * {@link #prayerVariantByStyle}) menus, so a choice like "Saturated heart
	 * on Magic" or a simulated Mystic Might survives a client restart. A
	 * stale/unknown enum name (e.g. from an older plugin version) is ignored,
	 * falling back to the style's default. No-ops without a {@link
	 * ConfigManager} (headless tests / the no-config-manager constructor).
	 */
	private <E extends Enum<E>> void loadVariants(String keyPrefix, Class<E> type, Map<String, E> into)
	{
		if (configManager == null)
		{
			return;
		}
		for (String styleKey : new String[] {"melee", "ranged", "magic"})
		{
			String raw = configManager.getConfiguration(OSPulseConfig.GROUP, keyPrefix + "." + styleKey);
			if (raw == null || raw.isEmpty())
			{
				continue;
			}
			try
			{
				into.put(styleKey, Enum.valueOf(type, raw));
			}
			catch (IllegalArgumentException e)
			{
				// Stale/unknown enum name (e.g. an older plugin version) — ignore, fall back to the style default.
			}
		}
	}

	/** Persists one style's right-click swap-menu pick ({@code keyPrefix} is {@code "potionVariant"} or {@code "prayerVariant"}) so it survives a client restart. */
	private void saveVariant(String keyPrefix, String styleKey, Enum<?> value)
	{
		if (configManager == null)
		{
			return;
		}
		configManager.setConfiguration(OSPulseConfig.GROUP, keyPrefix + "." + styleKey, value.name());
	}

	/**
	 * Reads the currently-selected blowpipe dart straight from config (mirrors
	 * {@link #loadVariants}'s load pattern), falling back to
	 * {@link BlowpipeDart#DRAGON} — {@link OSPulseConfig#blowpipeDart}'s own
	 * default — when unset/stale/no {@link ConfigManager} (headless tests).
	 * Used only to mark the current pick in the right-click "Set darts"
	 * submenu (see {@link #buildExcludePopup}); the LIVE readout itself
	 * reads the config value fresh via {@code SessionTracker}/{@code
	 * GearMapper} on the next gear snapshot, same as any other live gear change.
	 */
	private BlowpipeDart currentBlowpipeDart()
	{
		return BlowpipeDart.fromConfig(configManager);
	}

	/**
	 * Persists the picked blowpipe dart to config so it survives a client
	 * restart (mirrors {@link #saveVariant}), then re-ranks the
	 * readout immediately (mirrors the potion-swap/exclude-item pattern —
	 * see {@link #populatePotionVariantPopup}). No-ops without a {@link
	 * ConfigManager} (headless tests / the no-config-manager constructor).
	 */
	private void pickBlowpipeDart(BlowpipeDart dart)
	{
		if (configManager != null)
		{
			configManager.setConfiguration(OSPulseConfig.GROUP, BlowpipeDart.CONFIG_KEY, dart.name());
		}
		rankAndRender();
	}

	/**
	 * Refreshes the prayer/potion boost TOGGLE BUTTONS themselves so each one's
	 * icon always shows the SAME prayer/potion {@link DpsCalculator} is actually
	 * applying for {@code style}: the user's right-click prayer pick while the
	 * "best prayer" simulation is on, else the ladder-topped prayer for the
	 * player's real Prayer level (see {@link #effectivePrayerFor}), and the
	 * style's boosting potion (the user's right-click swap pick for Magic —
	 * see {@link #effectivePotionFor}). Falls back to the generic default icon
	 * with no target/gear selected yet (style is {@code null}) so the buttons
	 * are never blank.
	 */
	private void updateBoostIndicators(CombatStyle style)
	{
		if (style == null)
		{
			return;
		}

		OffensivePrayer prayer = effectivePrayerFor(style);
		if (prayer != null)
		{
			boolean prayerSwappable = CombatIcons.prayerVariantsFor(style).length > 0;
			bestPrayerToggle.setIcon(prayerIcon(prayer));
			bestPrayerToggle.setToolTipText("Offensive prayer applied: " + displayName(prayer)
				+ (prayerSwappable ? " (right-click to swap)" : ""));
			// bestPrayerToggle is a plain JToggleButton, not a HintableToggleButton
			// like bestPotionToggle below, so there is no corner-hint icon to set
			// here — the tooltip suffix above is its only "more options" signal.
		}

		CombatIcons.BoostPotion potion = effectivePotionFor(style);
		if (potion != null)
		{
			boolean swappable = CombatIcons.variantsFor(style).length > 0;
			bestPotionToggle.setIcon(potionIcon(potion));
			bestPotionToggle.setToolTipText("Boosting potion applied: " + displayName(potion)
				+ (swappable ? " (right-click to swap)" : ""));
			bestPotionToggle.setRightClickHint(swappable);
		}
	}

	/** "Piety" from {@code PIETY}, etc — title-cased enum name for tooltips. */
	private static String displayName(Enum<?> value)
	{
		String[] words = value.name().split("_");
		StringBuilder sb = new StringBuilder();
		for (String word : words)
		{
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(word.charAt(0)).append(word.substring(1).toLowerCase(Locale.ROOT));
		}
		return sb.toString();
	}

	/** Applies the selected-row border/background to whichever row matches {@link #selectedStyle}. */
	private void highlightSelectedRow()
	{
		for (StyleRow row : styleRows)
		{
			row.setSelected(row.style.equals(selectedStyle));
		}
	}

	/** User clicked a style row: lock the readout to it (ranking order is unchanged). */
	private void selectStyle(WeaponStyle style)
	{
		selectedStyle = style;
		userPickedStyle = true;
		highlightSelectedRow();
		updateOutputs();
	}

	/**
	 * DPS for one style against the current target + gear (overrides applied,
	 * see {@link #effectiveEquipmentStats}) + toggles, or {@code null} if not
	 * computable.
	 */
	private DpsResult computeFor(WeaponStyle style)
	{
		return computeAgainst(effectiveEquipmentStats(), style, effectiveWeaponId());
	}

	/**
	 * DPS for one style against the current target + toggles, using the given
	 * {@link EquipmentStats} rather than always the live/overridden one — lets
	 * {@link #updateWhatIfDelta} compute the SAME style against real worn gear
	 * for the baseline comparison. {@code weaponId} must correspond to {@code
	 * gearStats} (e.g. the real worn weapon id when {@code gearStats} is the
	 * real worn stats, even under a what-if override). {@code null} if not
	 * computable.
	 */
	private DpsResult computeAgainst(EquipmentStats gearStats, WeaponStyle style, int weaponId)
	{
		if (lastGear == null || selectedMonster == null || gearStats == null || style == null)
		{
			return null;
		}
		PlayerCombat player = GearMapper.toPlayerCombat(lastGear, style.stance(),
			bestPotionToggle.isSelected(), bestPrayerToggle.isSelected(), onSlayerTaskToggle.isSelected(),
			magicPotionVariantForCalc(), assumedPrayerFor(style.type()));
		if (style.type() == CombatStyle.MAGIC)
		{
			// Spell-aware path: a worn powered staff wins automatically; otherwise
			// the magic view's selected spell (or, outside the magic view, the
			// legacy picker's spell) is autocast at 5 ticks.
			Spell spell = magicView ? selectedSpell : currentSpell();
			if (spell == null && !gearStats.poweredStaff().applies())
			{
				// Magic view on a spell-less book (Lunar/Arceuus): nothing to cast.
				return null;
			}
			return DpsCalculator.compute(gearStats, player, CombatStyle.MAGIC, selectedMonster, spell, weaponId);
		}
		return DpsCalculator.compute(gearStats, player, style.type(), selectedMonster, 0, weaponId);
	}

	/** The spell currently picked in the selector (never {@code null} — the model always has a selection). */
	private Spell currentSpell()
	{
		Spell picked = (Spell) spellPicker.getSelectedItem();
		return picked != null ? picked : Spell.FIRE_SURGE;
	}

	// ------------------------------------------------------- target picker

	private void onSearchChanged()
	{
		// Ignore the programmatic setText that writes a picked target's name back
		// into the field (that must not re-open the just-collapsed result list).
		if (suppressSearchEvents)
		{
			return;
		}
		// Typing re-opens the (collapsed-after-pick) result list.
		setListOpen(true);
		populateMonsterList(monsterSearchField.getText());
	}

	/** Shows/hides the scrollable result list and reflows the panel around it. */
	private void setListOpen(boolean open)
	{
		if (listScroll.isVisible() == open)
		{
			return;
		}
		listScroll.setVisible(open);
		listScroll.revalidate();
		body().revalidate();
		body().repaint();
	}

	/**
	 * Refilters the full (uncapped) monster list and swaps the backing list of
	 * the {@link JList} model in one shot — no per-item model mutation, so
	 * typing stays responsive even when the filter matches thousands of names.
	 */
	private void populateMonsterList(String query)
	{
		filteredMonsters = MonsterRepository.getInstance().search(query == null ? "" : query.trim());
		suppressListEvents = true;
		monsterListModel.setMonsters(filteredMonsters);

		int keepIndex = -1;
		if (selectedMonster != null)
		{
			for (int i = 0; i < filteredMonsters.size(); i++)
			{
				if (filteredMonsters.get(i).name().equalsIgnoreCase(selectedMonster.name()))
				{
					keepIndex = i;
					break;
				}
			}
		}
		// Deliberately NO silent default target: computing against an
		// arbitrary first entry (previously "A corpse", 90 HP) produced
		// convincing-but-wrong numbers when the user hadn't picked yet. Until
		// the user selects a monster the outputs stay "-" with an explicit
		// "pick a target" hint instead.
		if (keepIndex >= 0)
		{
			monsterList.setSelectedIndex(keepIndex);
			monsterList.ensureIndexIsVisible(keepIndex);
		}
		else
		{
			// Selection filtered out — keep the last target (label still shows it).
			monsterList.clearSelection();
		}
		suppressListEvents = false;
		updateTargetLabel();
		rankAndRender();
	}

	private void updateTargetLabel()
	{
		targetLabel.setText(selectedMonster == null
			? "Target: pick a monster above"
			: "Target: " + selectedMonster.name());
		targetLabel.setForeground(selectedMonster == null
			? ColorScheme.LIGHT_GRAY_COLOR
			: java.awt.Color.WHITE);
		updateGearOverrideNote();
		updateCombatRequirementNote();
		consumablesReminderPanel.refresh(selectedMonster == null ? null : selectedMonster.lookupName());
	}

	/**
	 * Rebuilds {@link #gearOverrideNotePanel} from {@link MonsterGearOverrideRepository}
	 * for the currently selected target — one small orange advisory line per
	 * override (e.g. "vs Rune dragon: equip Insulated boots (Boots) — Halves
	 * the lightning special-attack damage."), hidden entirely when the target
	 * has none or no target is selected. Called whenever {@link #selectedMonster}
	 * changes (every {@link #updateTargetLabel} call site).
	 *
	 * <p><b>Ownership disclosure:</b> {@code GearOptimizer} force-includes a
	 * mandatory override's item id past the budget filter entirely ({@code
	 * GearOptimizer.java}'s per-slot affordability check exempts {@code
	 * request.include}) and then force-equips it into the recommended
	 * loadout regardless of ownership or price ({@code applyForcedIncludes})
	 * — a real, deliberate behaviour (these are mechanical/safety
	 * requirements, not DPS suggestions: dropping one because it's unowned
	 * would produce a result that LOOKS safe and isn't), never changed here.
	 * What changes is disclosure only: when the requirement isn't satisfied
	 * by anything the player owns (not the primary item, nor any of {@link
	 * MonsterGearOverride#alternativeItemIds()} — same substitution rule
	 * {@link #isSlotInvalidForTarget} already uses), the note says so, so the
	 * "equip X" instruction doesn't read as something already in hand. This
	 * is NOT gated to owned-only mode: an unowned mandatory include bypasses
	 * the budget filter in every mode, not just budget-0, so the gap is
	 * worth disclosing regardless of mode.
	 */
	private void updateGearOverrideNote()
	{
		gearOverrideNotePanel.removeAll();
		List<MonsterGearOverride> overrides = selectedMonster == null
			? Collections.emptyList()
			: MonsterGearOverrideRepository.getInstance().forMonster(selectedMonster.lookupName());
		java.util.Set<Integer> ownedIds = overrides.isEmpty() ? Collections.emptySet() : ownedPriceMap().keySet();
		for (MonsterGearOverride override : overrides)
		{
			boolean owned = ownedIds.contains(override.itemId())
				|| override.alternativeItemIds().stream().anyMatch(ownedIds::contains);
			String raw = "⚠ vs " + selectedMonster.name() + ": equip "
				+ override.itemName() + " (" + slotDisplayName(override.slot()) + ")"
				+ (owned ? "" : " — you don't own this") + " — " + override.reason();
			// A plain JLabel does not wrap, and a hard-coded HTML div width
			// clips as soon as the side panel is narrower than that pixel
			// value (Jonathan saw "...equip in selected boot..." cut off).
			// AdvisoryNoteRenderer.wrappingNote() wraps to whatever width the panel actually has.
			gearOverrideNotePanel.add(AdvisoryNoteRenderer.wrappingNote(raw, ColorScheme.BRAND_ORANGE));
		}
		gearOverrideNotePanel.setVisible(!overrides.isEmpty());
		gearOverrideNotePanel.revalidate();
		gearOverrideNotePanel.repaint();
	}

	/** Test seam: the rendered text of every current {@link #gearOverrideNotePanel} advisory line, in order. */
	java.util.List<String> gearOverrideNoteTextsForTest()
	{
		java.util.List<String> texts = new ArrayList<>();
		for (Component c : gearOverrideNotePanel.getComponents())
		{
			if (c instanceof javax.swing.JTextArea)
			{
				texts.add(((javax.swing.JTextArea) c).getText());
			}
		}
		return texts;
	}

	/** Test seam: the rendered text of every current {@link #consumablesReminderPanel} advisory line, in order. */
	java.util.List<String> consumablesReminderNoteTextsForTest()
	{
		return consumablesReminderPanel.noteTextsForTest();
	}

	/** Test seam: whether {@link #consumablesReminderPanel} is currently showing anything. */
	boolean consumablesReminderVisibleForTest()
	{
		return consumablesReminderPanel.isVisible();
	}

	/**
	 * Rebuilds {@link #combatReqNotePanel} from {@link MonsterCombatRequirementRepository}
	 * for the currently selected target — a single orange advisory line
	 * showing the curated combat-requirement note (e.g. "Kurask can only be
	 * damaged by leaf-bladed weapons, broad ammunition, or magic"), hidden
	 * entirely when the target has no requirement or its note is empty.
	 * Called whenever {@link #selectedMonster} changes (every
	 * {@link #updateTargetLabel} call site).
	 */
	private void updateCombatRequirementNote()
	{
		combatReqNotePanel.removeAll();
		boolean show = false;
		if (selectedMonster != null)
		{
			java.util.Optional<MonsterCombatRequirement> req =
				MonsterCombatRequirementRepository.getInstance().forMonster(selectedMonster.lookupName());
			if (req.isPresent() && !req.get().note().isEmpty())
			{
				combatReqNotePanel.add(AdvisoryNoteRenderer.wrappingNote("⚠ " + req.get().note(), ColorScheme.BRAND_ORANGE));
				show = true;
			}
		}
		combatReqNotePanel.setVisible(show);
		combatReqNotePanel.revalidate();
		combatReqNotePanel.repaint();
	}

	/** Human-readable slot name for the advisory note, e.g. {@code BOOTS} -&gt; {@code "Boots"}. */
	private static String slotDisplayName(MonsterGearOverride.Slot slot)
	{
		String raw = slot.name().toLowerCase(Locale.ROOT);
		return Character.toUpperCase(raw.charAt(0)) + raw.substring(1);
	}

	/** Minimal HTML escaping for text placed inside an {@code <html>} JLabel (ampersand first). */
	private static String escapeHtml(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	// ------------------------------------------------- Phase 2: what-if swaps

	/**
	 * Opens the item search scoped to {@code slotOrdinal} (closing it if that
	 * same slot's search was already open — a second click toggles it shut,
	 * matching the monster-list collapse UX).
	 */
	private void toggleItemSearch(int slotOrdinal)
	{
		if (searchOpenForSlot == slotOrdinal)
		{
			closeItemSearch();
			return;
		}
		searchOpenForSlot = slotOrdinal;
		itemSearchField.setText("");
		itemSearchRow.setVisible(true);
		itemSearchField.setToolTipText("Search " + SLOT_NAMES[slotOrdinal] + " items to try (what-if — your real gear is unaffected)");
		itemSearchField.requestFocusInWindow();
		populateItemList();
		body().revalidate();
		body().repaint();
	}

	/** Closes the item picker (search row + icon grid) — the X button, re-clicking the same slot, or picking an item all route here. */
	private void closeItemSearch()
	{
		searchOpenForSlot = -1;
		itemSearchRow.setVisible(false);
		itemGridScroll.setVisible(false);
		body().revalidate();
		body().repaint();
	}

	/** Refilters {@link #searchOpenForSlot}'s candidate items by the search box's text and rebuilds the icon grid. */
	private void populateItemList()
	{
		if (searchOpenForSlot < 0)
		{
			return;
		}
		filteredItems = EquipmentIndexRepository.getInstance().searchSlot(searchOpenForSlot, itemSearchField.getText());
		renderItemGrid();
		itemGridScroll.setVisible(!filteredItems.isEmpty());
		itemGridScroll.revalidate();
		body().revalidate();
		body().repaint();
	}

	/**
	 * Rebuilds the icon grid ({@link #itemGridPanel}, {@link #ITEM_GRID_COLUMNS}
	 * per row) from {@link #filteredItems} — one {@link ItemGridCell} per
	 * candidate: icon via the EDT-safe async {@code ItemManager.getImage(int)},
	 * tooltip = item name, click applies the override (same
	 * {@link #applyOverride} path the old text list used) and closes the
	 * picker.
	 */
	private void renderItemGrid()
	{
		itemGridPanel.removeAll();
		for (EquipmentIndexRepository.Entry entry : filteredItems)
		{
			itemGridPanel.add(new ItemGridCell(entry));
		}
		itemGridPanel.revalidate();
		itemGridPanel.repaint();
	}

	/**
	 * One clickable icon cell in the item-picker grid — icon only (no text
	 * label, to stay compact at {@link #ITEM_GRID_COLUMNS} per row in the
	 * narrow side panel), tooltip = the item's display name, click applies it
	 * as a what-if override for {@link #searchOpenForSlot} and closes the
	 * picker.
	 */
	private final class ItemGridCell extends JLabel
	{
		private ItemGridCell(EquipmentIndexRepository.Entry entry)
		{
			setOpaque(true);
			setBackground(ColorScheme.DARK_GRAY_COLOR);
			setHorizontalAlignment(SwingConstants.CENTER);
			setVerticalAlignment(SwingConstants.CENTER);
			setPreferredSize(new Dimension(ITEM_GRID_CELL_SIZE, ITEM_GRID_CELL_SIZE));
			setToolTipText(entry.name());
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
			if (itemManager != null)
			{
				// EDT-safe: getImage is async (AsyncBufferedImage), the same
				// pattern used by the worn-gear grid and boost toggles.
				itemManager.getImage(entry.itemId()).addTo(this);
			}
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					applyOverride(searchOpenForSlot, entry.itemId());
					closeItemSearch();
				}
			});
		}
	}

	/**
	 * Sets a what-if override for {@code slotOrdinal} to {@code itemId},
	 * enforcing 2H/shield exclusivity for the weapon and shield slots (see
	 * {@link WhatIfLoadout#equipWeapon}/{@link WhatIfLoadout#equipShield}) and
	 * recomputing the whole readout from the new override.
	 */
	private void applyOverride(int slotOrdinal, int itemId)
	{
		int[] liveIds = lastGear == null ? new int[GearSnapshot.EQUIPMENT_SLOT_COUNT] : lastGear.equippedItemIds();
		if (slotOrdinal == WhatIfLoadout.WEAPON_SLOT)
		{
			override = WhatIfLoadout.equipWeapon(override, itemId);
		}
		else if (slotOrdinal == WhatIfLoadout.SHIELD_SLOT)
		{
			override = WhatIfLoadout.equipShield(override, liveIds, itemId);
		}
		else
		{
			override = override.withSlot(slotOrdinal, itemId);
		}
		// A weapon swap changes the available attack styles/spells entirely —
		// re-rank exactly like a real weapon change (rankAndRender already
		// re-defaults the style/spell selection whenever the effective weapon
		// id it sees changes, since it reads lastGear.itemIdAt(WEAPON_SLOT) —
		// see effectiveWeaponId()).
		//
		// Finding 4 fix: rankAndRender() FIRST, updateGearGrid() SECOND —
		// isSlotInvalidForTarget (which updateGearGrid drives) reads
		// selectedStyle, and only rankAndRender re-selects it for the new
		// weapon. Calling updateGearGrid first would cross out a newly-valid
		// weapon using the PREVIOUS weapon's now-stale style until some
		// later, unrelated refresh happened to fix it.
		rankAndRender();
		updateGearGrid(lastGear);
	}

	/**
	 * Clears every what-if override AND any optimiser-applied preview/highlight
	 * — the single "undo everything, go back to what I'm actually wearing"
	 * action (design spec section 3's "Clear preview"/"Revert" reuses this same
	 * method). Previously this only cleared {@link #override}, leaving the
	 * optimiser result panel (and its stale "Apply to readout" button) visible
	 * — from the user's perspective nothing appeared to happen, since the
	 * lingering panel looked identical to a still-applied preview. Also drops
	 * any manual style/spell lock so the readout re-defaults to the best style
	 * for whatever weapon the player is ACTUALLY wearing, rather than
	 * potentially "keeping" a style selection that happens to satisfy
	 * {@link WeaponStyle#equals} (type+stance only) on the real weapon too.
	 */
	private void resetAllOverrides()
	{
		override = LoadoutOverride.empty();
		lastOptimizerResult = null;
		lastOptimizerNeedsProtection = java.util.Collections.emptySet();
		resultPanel.setVisible(false);
		clearPreviewButton.setVisible(false);
		statusLabel.setVisible(false);
		resetBankHighlightToggle();
		userPickedStyle = false;
		userPickedSpell = false;
		closeItemSearch();
		// Finding 4 fix: re-rank before regridding — see applyOverride()'s comment.
		rankAndRender();
		updateGearGrid(lastGear);
	}

	/**
	 * Full panel reset (feature 11): returns the gear panel to a fresh state —
	 * no target monster, no locked style/spell, no what-if overrides and no
	 * optimiser preview — while deliberately KEEPING the user's persisted
	 * preferences ({@link #potionVariantByStyle} and {@link #excludedItemIds}),
	 * which are config-backed choices, not session-tracking state.
	 *
	 * <p>The live gear/DPS readout itself is not cleared: equipment is live
	 * (re-supplied every {@link #apply}), so it re-defaults to the best style
	 * for the worn weapon rather than blanking out. Clearing
	 * {@link #lastRankedWeaponId} forces that re-default; {@link #resetAllOverrides}
	 * then drops the override, hides the optimiser result, closes the item
	 * search and re-renders.
	 */
	@Override
	public void resetState()
	{
		suppressListEvents = true;
		try
		{
			monsterSearchField.setText("");
			populateMonsterList("");
			monsterList.clearSelection();
		}
		finally
		{
			suppressListEvents = false;
		}
		selectedMonster = null;
		selectedStyle = null;
		lastRankedWeaponId = Integer.MIN_VALUE;
		lastRankedTarget = null;
		selectedSpell = null;
		selectedBook = BookTab.STANDARD;
		magicCastStyle = null;
		currentWeaponCategory = null;
		lastDps = 0.0;
		baselineDps = 0.0;
		lastWealth = null;
		optimizerStyle = null;
		styleUserPicked = false;
		styleAutoPicked = false;
		updateTargetLabel();
		// Reuse the shared what-if/optimiser teardown: it also clears
		// userPickedStyle/userPickedSpell, hides the optimiser panel, closes the
		// item search and re-renders the grid + readout from the live gear.
		resetAllOverrides();
	}

	/**
	 * The weapon item id the readout should actually use: the override's
	 * weapon if set, else the live worn weapon. {@link #rankAndRender} keys its
	 * "did the weapon change" re-ranking logic off this instead of the raw live
	 * id, so a what-if weapon swap re-ranks styles/spells exactly like a real
	 * weapon change would.
	 */
	private int effectiveWeaponId()
	{
		if (override.hasOverride(WhatIfLoadout.WEAPON_SLOT))
		{
			return override.itemIdFor(WhatIfLoadout.WEAPON_SLOT);
		}
		return lastGear == null ? -1 : lastGear.itemIdAt(WEAPON_SLOT);
	}

	/**
	 * The ammo item id the readout should actually use: the override's ammo
	 * if set, else the live worn ammo. Mirrors {@link #effectiveWeaponId()}.
	 */
	private int effectiveAmmoId()
	{
		if (override.hasOverride(WhatIfLoadout.AMMO_SLOT))
		{
			return override.itemIdFor(WhatIfLoadout.AMMO_SLOT);
		}
		return lastGear == null ? -1 : lastGear.itemIdAt(WhatIfLoadout.AMMO_SLOT);
	}

	/**
	 * The {@link EquipmentStats} the readout should compute against: the
	 * override-applied what-if loadout when any slot is overridden, otherwise
	 * the live snapshot's precomputed stats unchanged (zero behaviour change
	 * with no overrides active).
	 */
	private EquipmentStats effectiveEquipmentStats()
	{
		if (lastGear == null)
		{
			return null;
		}
		if (override.isEmpty())
		{
			return lastGear.equipmentStats();
		}
		return WhatIfLoadout.buildEquipmentStats(lastGear.equippedItemIds(), override);
	}

	/**
	 * Refreshes the what-if delta row: hidden with no overrides active: shown
	 * comparing the current (possibly-overridden) DPS against what the SAME
	 * style/spell selection would do on real worn gear. Guards a style/spell
	 * that only exists on the what-if weapon (e.g. switched from melee to a
	 * bow) by falling back to "-" rather than a misleading comparison.
	 */
	private void updateWhatIfDelta()
	{
		if (override.isEmpty() || lastGear == null || selectedMonster == null)
		{
			whatIfRow.setVisible(false);
			resetAllButton.setVisible(!override.isEmpty());
			return;
		}
		resetAllButton.setVisible(true);

		DpsResult baseline = computeAgainst(lastGear.equipmentStats(), selectedStyle, lastGear.itemIdAt(WEAPON_SLOT));
		if (baseline == null)
		{
			whatIfRow.setVisible(false);
			return;
		}
		baselineDps = baseline.dps();
		double delta = lastDps - baselineDps;
		// Item #6b: the literal triangle glyph (▲/▼) is gone — the number
		// itself is coloured green/red (DELTA_UP_COLOR/DELTA_DOWN_COLOR) and a
		// plain "->" arrow separates the two compared values, matching the
		// panel's existing green/red gain styling elsewhere.
		java.awt.Color color = delta > 1e-9 ? DELTA_UP_COLOR
			: delta < -1e-9 ? DELTA_DOWN_COLOR : java.awt.Color.WHITE;
		whatIfDeltaValue.setForeground(color);
		whatIfDeltaValue.setText("<html>" + DpsFormat.deltaFragment(baselineDps, delta) + " -> "
			+ DpsFormat.deltaFragment(lastDps, delta) + "</html>");
		whatIfRow.setVisible(true);
	}

	// ------------------------------------------------- Phase 3: optimiser

	/** The raw stored budget from {@link #budgetField} + K/M toggles, ignoring ironman owned-only mode — see {@link #resolvedBudget()}. */
	private long storedBudget()
	{
		return BudgetAmount.parseUnitAmount(budgetField.getText(), budgetKToggle, budgetMToggle);
	}

	/** {@link #storedBudget()}, forced to 0 in ironman owned-only mode (issue #11) — {@link #budgetField} itself is never written here. */
	private long resolvedBudget()
	{
		return OwnedOnlyMode.effectiveBudget(ironmanOwnedOnlyPref(), storedBudget());
	}

	/** Loads a panel icon from {@code /com/ospulse/ui/icon/} scaled to {@code size}px square. */
	private static ImageIcon loadPanelIcon(String file, int size)
	{
		BufferedImage img = ImageUtil.loadImageResource(GearSection.class, "/com/ospulse/ui/icon/" + file);
		return new ImageIcon(img.getScaledInstance(size, size, Image.SCALE_SMOOTH));
	}

	/** Updates the gold-pile badge's value text + magnitude colour (see {@link GpFormat}). */
	private void updateBudgetDisplay()
	{
		long budget = resolvedBudget();
		budgetBadge.setValue(GpFormat.format(budget), GpFormat.color(budget));
	}

	/** Pins a component to a fixed w x h (preferred = min = max) so BoxLayout/FlowLayout won't stretch it. */
	private static void fixSize(java.awt.Component c, int w, int h)
	{
		Dimension d = new Dimension(w, h);
		c.setPreferredSize(d);
		c.setMinimumSize(d);
		c.setMaximumSize(d);
	}

	/** Restricts a field to digits only, at most {@code maxDigits} (e.g. budget/threshold 4, count 2). */
	private static void limitDigits(javax.swing.JTextField field, int maxDigits)
	{
		((AbstractDocument) field.getDocument()).setDocumentFilter(new DocumentFilter()
		{
			@Override
			public void insertString(FilterBypass fb, int offset, String text, AttributeSet attr) throws BadLocationException
			{
				replace(fb, offset, 0, text, attr);
			}

			@Override
			public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attr) throws BadLocationException
			{
				String digits = text == null ? "" : text.replaceAll("\\D", "");
				int resultLength = fb.getDocument().getLength() - length + digits.length();
				if (resultLength <= maxDigits)
				{
					super.replace(fb, offset, length, digits, attr);
				}
			}
		});
	}

	/**
	 * Whether the expensive-item risk cap applies to the current search.
	 *
	 * <p>The cap exists to limit what the player is told to RISK, so it is
	 * scoped to targets that can actually get them PKed: the curated Wilderness
	 * monster set behind {@link Monster#isWildernessTarget()}. Monsters that
	 * exist both inside and outside the Wilderness are already disambiguated by
	 * the synthetic {@code "(Wilderness)"} twin the player selects explicitly,
	 * so no separate location question has to be asked (issue #11 — the cap
	 * previously constrained every search, including bosses nowhere near the
	 * Wilderness).
	 *
	 * <p>There is deliberately no location or PvP-world detection anywhere in
	 * the plugin; the override added alongside this is how a player opts the cap
	 * back in for PvP worlds or self-imposed risk.
	 */
	private boolean riskCapApplies()
	{
		return riskCapAnyTargetToggle.isSelected()
			|| (selectedMonster != null && selectedMonster.isWildernessTarget());
	}

	/** Greys the risk-cap controls out whenever {@link #riskCapApplies} is false, so the panel never offers a setting the search will ignore. */
	private void refreshRiskCapEnabled()
	{
		boolean applies = riskCapApplies();
		expensiveCountField.setEnabled(applies);
		expensiveThresholdField.setEnabled(applies);
		expensiveThresholdKToggle.setEnabled(applies);
		expensiveThresholdMToggle.setEnabled(applies);
		String reason = applies ? EXPENSIVE_COUNT_TOOLTIP : RISK_CAP_INACTIVE_TOOLTIP;
		expensiveCountField.setToolTipText(reason);
		expensiveThresholdField.setToolTipText(applies ? EXPENSIVE_THRESHOLD_TOOLTIP : RISK_CAP_INACTIVE_TOOLTIP);
	}

	/** The "expensive item" gp threshold from {@link #expensiveThresholdField} + its K/M toggle. */
	private long resolvedExpensiveThreshold()
	{
		return BudgetAmount.parseUnitAmount(expensiveThresholdField.getText(), expensiveThresholdKToggle, expensiveThresholdMToggle);
	}

	/** The "expensive items to allow" count from {@link #expensiveCountField} — blank/unparseable/negative treated as 0. */
	private int resolvedExpensiveCount()
	{
		try
		{
			return Math.max(0, Integer.parseInt(expensiveCountField.getText().trim()));
		}
		catch (NumberFormatException | NullPointerException e)
		{
			return 0;
		}
	}

	/**
	 * A compact two-button segmented K/M toggle (mirrors {@link #bookTabButton}'s
	 * selected/unselected styling) backing a numeric field's unit — exactly one
	 * of the two is ever selected via a shared {@link ButtonGroup}, and neither
	 * button can be clicked off (a segmented toggle always has a selection).
	 * {@code defaultMillions} picks the initially-selected button before
	 * {@link #loadOptimizerPrefs} may override it from persisted config.
	 */
	private JPanel unitToggle(JToggleButton kToggle, JToggleButton mToggle, boolean defaultMillions)
	{
		ButtonGroup group = new ButtonGroup();
		group.add(kToggle);
		group.add(mToggle);
		Border selectedBorder = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE);
		Border unselectedBorder = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR);
		for (JToggleButton button : new JToggleButton[] {kToggle, mToggle})
		{
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setFocusPainted(false);
			button.setMargin(new Insets(2, 6, 2, 6));
			Runnable restyle = () ->
			{
				button.setBorder(button.isSelected() ? selectedBorder : unselectedBorder);
				button.setBackground(button.isSelected()
					? ColorScheme.MEDIUM_GRAY_COLOR
					: ColorScheme.DARKER_GRAY_COLOR);
				button.setForeground(button.isSelected()
					? ColorScheme.BRAND_ORANGE
					: ColorScheme.LIGHT_GRAY_COLOR);
			};
			restyle.run();
			button.addItemListener(e -> restyle.run());
		}
		mToggle.setSelected(defaultMillions);
		kToggle.setSelected(!defaultMillions);

		JPanel panel = new JPanel(new GridLayout(1, 2, 1, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.add(kToggle);
		panel.add(mToggle);
		return panel;
	}

	// ------------------------------- optimiser settings persistence (budget/expensive)

	private static final String CONFIG_KEY_BUDGET_AMOUNT = "optimizerBudgetAmount";
	private static final String CONFIG_KEY_BUDGET_UNIT_MILLIONS = "optimizerBudgetUnitMillions";
	/**
	 * The expensive-item cap's count/threshold. These were once deliberately NOT
	 * persisted: a stale low cap silently constraining an unrelated search was a
	 * foot-gun, so they reset to their code defaults on every load. The
	 * Wilderness gate ({@link #riskCapApplies}) removed that foot-gun — the cap
	 * now only touches Wilderness targets or an explicit "Any target" opt-in, so
	 * nothing is silent any more and the values survive a restart like every
	 * other optimiser pref (issue #11).
	 */
	private static final String CONFIG_KEY_EXPENSIVE_COUNT = "optimizerExpensiveCount";
	private static final String CONFIG_KEY_EXPENSIVE_THRESHOLD_AMOUNT = "optimizerExpensiveThresholdAmount";
	/** K/M unit for {@link #CONFIG_KEY_EXPENSIVE_THRESHOLD_AMOUNT}, mirroring {@link #CONFIG_KEY_BUDGET_UNIT_MILLIONS}. */
	private static final String CONFIG_KEY_EXPENSIVE_THRESHOLD_UNIT_MILLIONS = "optimizerExpensiveThresholdUnitMillions";
	/** The "Any target" override — see {@link #riskCapAnyTargetToggle}. */
	private static final String CONFIG_KEY_RISK_CAP_ANY_TARGET = "optimizerRiskCapAnyTarget";

	/**
	 * Restores the budget amount/unit, the expensive-item cap's count/threshold/
	 * unit, and the "Any target" override from config (see {@link
	 * #saveOptimizerPrefs}) so they survive a client restart, mirroring {@link
	 * #loadVariants}'s pattern. No-op without a {@link ConfigManager}
	 * (headless tests / the no-config-manager constructors).
	 *
	 * <p>The expensive-item count/threshold now persist rather than always
	 * resetting to their code defaults ("11" / "100" K) — see {@link
	 * #CONFIG_KEY_EXPENSIVE_COUNT}'s javadoc for why that used to be a foot-gun
	 * and no longer is. An absent key leaves the field at its code default.
	 */
	private void loadOptimizerPrefs()
	{
		if (configManager == null)
		{
			return;
		}
		String budgetAmount = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_BUDGET_AMOUNT);
		if (budgetAmount != null && !budgetAmount.isEmpty())
		{
			budgetField.setText(budgetAmount);
		}
		String budgetUnit = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_BUDGET_UNIT_MILLIONS);
		if (budgetUnit != null)
		{
			budgetMToggle.setSelected(Boolean.parseBoolean(budgetUnit));
			budgetKToggle.setSelected(!Boolean.parseBoolean(budgetUnit));
		}
		String expensiveCount = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXPENSIVE_COUNT);
		if (expensiveCount != null && !expensiveCount.isEmpty())
		{
			expensiveCountField.setText(expensiveCount);
		}
		String expensiveThreshold = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXPENSIVE_THRESHOLD_AMOUNT);
		if (expensiveThreshold != null && !expensiveThreshold.isEmpty())
		{
			expensiveThresholdField.setText(expensiveThreshold);
		}
		String thresholdUnit = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXPENSIVE_THRESHOLD_UNIT_MILLIONS);
		if (thresholdUnit != null)
		{
			expensiveThresholdMToggle.setSelected(Boolean.parseBoolean(thresholdUnit));
			expensiveThresholdKToggle.setSelected(!Boolean.parseBoolean(thresholdUnit));
		}
		String anyTarget = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_RISK_CAP_ANY_TARGET);
		if (anyTarget != null)
		{
			riskCapAnyTargetToggle.setSelected(Boolean.parseBoolean(anyTarget));
		}
	}

	/**
	 * Persists the budget amount/unit, the expensive-item cap's count/threshold/
	 * unit, and the "Any target" override to config — see {@link
	 * #loadOptimizerPrefs}.
	 */
	private void saveOptimizerPrefs()
	{
		if (configManager == null)
		{
			return;
		}
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_BUDGET_AMOUNT, budgetField.getText());
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_BUDGET_UNIT_MILLIONS,
			String.valueOf(budgetMToggle.isSelected()));
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXPENSIVE_COUNT, expensiveCountField.getText());
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXPENSIVE_THRESHOLD_AMOUNT,
			expensiveThresholdField.getText());
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXPENSIVE_THRESHOLD_UNIT_MILLIONS,
			String.valueOf(expensiveThresholdMToggle.isSelected()));
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_RISK_CAP_ANY_TARGET,
			String.valueOf(riskCapAnyTargetToggle.isSelected()));
	}

	private static final String CONFIG_KEY_EXCLUDED_ITEM_IDS = "optimizerExcludedItemIds";

	/**
	 * Live read of {@link OSPulseConfig#hideUnprotectableItems()} — GearSection has
	 * no injected {@code OSPulseConfig} instance (only a raw {@link ConfigManager}),
	 * so, mirroring every other config read in this class (e.g. {@link
	 * #loadOptimizerPrefs}'s {@code budgetUnitMillions} boolean), it goes straight
	 * through {@code configManager.getConfiguration(...)} + {@link
	 * Boolean#parseBoolean}, which already defaults to {@code false} for a
	 * null/unset value — matching the {@code @ConfigItem}'s own default. No-op
	 * (returns {@code false}) without a {@link ConfigManager}.
	 */
	private boolean hideUnprotectableItemsPref()
	{
		if (configManager == null)
		{
			return false;
		}
		return Boolean.parseBoolean(
			configManager.getConfiguration(OSPulseConfig.GROUP, "hideUnprotectableItems"));
	}

	/**
	 * Live read of the per-account merged {@code ironmanOwnedOnly} value
	 * (issue #11 leak fix): the current RS profile's own value if it has one,
	 * else the client-wide {@code ironmanOwnedOnlyDefault} global preference,
	 * else {@code false} — see {@link com.ospulse.ui.sections.gear.IronmanOwnedOnlyResolver#resolve}.
	 * Deliberately never reads the client-wide {@code ironmanOwnedOnly}
	 * {@code @ConfigItem} itself here — that key is only an edit surface /
	 * display mirror now (kept in sync by {@code OSPulsePlugin}'s {@code
	 * IronmanOwnedOnlyStore}), never the source of truth for behaviour, which
	 * is the whole point of the per-account scheme (an ironman alt's
	 * auto-enable must never leak onto a main sharing this client). No-op
	 * (returns {@code false}) without a {@link ConfigManager}, mirroring
	 * {@link #hideUnprotectableItemsPref()}'s guard.
	 */
	private boolean ironmanOwnedOnlyPref()
	{
		if (configManager == null)
		{
			return false;
		}
		String profileKey = configManager.getRSProfileKey();
		String rawProfile = profileKey != null
			? configManager.getRSProfileConfiguration(OSPulseConfig.GROUP,
				com.ospulse.ui.sections.gear.IronmanOwnedOnlyStore.KEY)
			: null;
		String rawDefault = configManager.getConfiguration(OSPulseConfig.GROUP,
			com.ospulse.ui.sections.gear.IronmanOwnedOnlyStore.DEFAULT_KEY);
		return com.ospulse.ui.sections.gear.IronmanOwnedOnlyResolver.resolve(rawProfile, rawDefault);
	}

	/** Restores {@link #excludedItemIds} from a comma-separated config value. No-op without a {@link ConfigManager}. */
	private void loadExcludedItemsPref()
	{
		if (configManager == null)
		{
			return;
		}
		String raw = configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXCLUDED_ITEM_IDS);
		if (raw == null || raw.isEmpty())
		{
			return;
		}
		excludedItemIds.clear();
		for (String part : raw.split(","))
		{
			try
			{
				excludedItemIds.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException e)
			{
				// Stale/corrupt entry — skip it rather than fail the whole restore.
			}
		}
	}

	/** Persists {@link #excludedItemIds} as a comma-separated config value — see {@link #loadExcludedItemsPref}. */
	private void saveExcludedItemsPref()
	{
		if (configManager == null)
		{
			return;
		}
		StringBuilder sb = new StringBuilder();
		for (int id : excludedItemIds)
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(id);
		}
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXCLUDED_ITEM_IDS, sb.toString());
	}

	/** Raw config key for {@link #excludedItemsCollapsed} — a plain client-wide value, not RS-profile-scoped (issue #11). */
	private static final String CONFIG_KEY_EXCLUDED_ITEMS_COLLAPSED = "excludedItemsCollapsed";

	/** Restores {@link #excludedItemsCollapsed} so the collapse state survives a client restart. No-op (returns {@code false}) without a {@link ConfigManager}. */
	private boolean loadExcludedItemsCollapsedPref()
	{
		if (configManager == null)
		{
			return false;
		}
		return Boolean.parseBoolean(
			configManager.getConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXCLUDED_ITEMS_COLLAPSED));
	}

	/** Persists {@link #excludedItemsCollapsed} — see {@link #loadExcludedItemsCollapsedPref}. */
	private void saveExcludedItemsCollapsedPref()
	{
		if (configManager == null)
		{
			return;
		}
		configManager.setConfiguration(OSPulseConfig.GROUP, CONFIG_KEY_EXCLUDED_ITEMS_COLLAPSED,
			String.valueOf(excludedItemsCollapsed));
	}

	/** The "▾/▸ Excluded from suggestions" heading text for the current collapse state — see {@link CollapsibleHeading}. */
	private String excludedHeadingText()
	{
		return CollapsibleHeading.headingText("Excluded from suggestions", excludedItemsCollapsed);
	}

	/** Flips {@link #excludedItemsCollapsed}, persists it, and re-renders — the heading's click handler (issue #11). */
	private void toggleExcludedItemsCollapsed()
	{
		excludedItemsCollapsed = !excludedItemsCollapsed;
		saveExcludedItemsCollapsedPref();
		renderExcludedList();
	}

	/**
	 * A boost/task toggle (best potion, best prayer, on-task) changed: re-rank
	 * the worn-gear list AND — if an optimiser search is already on screen —
	 * re-run it, so the "Best setup for this target" numbers track the toggles
	 * instead of showing stale figures until the next "Find best setup" click.
	 * Mirrors the exclude-item / style-selector re-optimise pattern (see
	 * {@link #excludeFromSuggestions} / {@link #runOptimizer}). Only re-runs
	 * when a result exists, so idle toggling never kicks off a search.
	 */
	private void onBoostToggleChanged()
	{
		rankAndRender();
		if (lastOptimizerResult != null)
		{
			runOptimizer();
		}
	}

	/**
	 * Adds {@code itemId} to {@link #excludedItemIds}, persists it, and — if a
	 * search is already on screen — immediately re-runs the optimiser so the
	 * excluded item drops out and the next-best suggestion takes its place
	 * without the user having to click "Find best setup" again. Re-rendering the
	 * cached {@link #lastOptimizerResult} would just show the stale result (which
	 * still contains the excluded item), which is why we re-optimise here — the
	 * same pattern the style selector uses (see {@link #runOptimizer}).
	 *
	 * <p>PR #25 finding 4: {@link #updateSpecWeaponCell} also reads {@link
	 * #excludedItemIds}, so it must be refreshed here too — otherwise the
	 * "Exclude from suggestions" action would correctly stop the OPTIMISER
	 * from suggesting an item while leaving a stale spec-weapon cell still
	 * showing it, exactly the kind of silent non-application this action's
	 * own history (shipped stage 4 at the reporter's explicit request) warns
	 * against.
	 */
	private void excludeFromSuggestions(int itemId)
	{
		if (itemId <= 0 || !excludedItemIds.add(itemId))
		{
			return;
		}
		saveExcludedItemsPref();
		renderExcludedList();
		updateSpecWeaponCell();
		if (lastOptimizerResult != null)
		{
			runOptimizer();
		}
	}

	/**
	 * Removes {@code itemId} from {@link #excludedItemIds}, persists the change,
	 * refreshes the viewer, and — if a search is on screen — re-optimises so the
	 * item can immediately reappear as a suggestion. The counterpart to
	 * {@link #excludeFromSuggestions}; also refreshes {@link
	 * #specWeaponCell} for the same reason (see that method's javadoc).
	 */
	private void removeExcludedItem(int itemId)
	{
		if (!excludedItemIds.remove(itemId))
		{
			return;
		}
		saveExcludedItemsPref();
		renderExcludedList();
		updateSpecWeaponCell();
		if (lastOptimizerResult != null)
		{
			runOptimizer();
		}
	}

	/**
	 * Rebuilds the excluded-items viewer ({@link #excludedItemsList}) from
	 * {@link #excludedItemIds} — one icon-only cell per excluded item (a ✕ in
	 * the top-right corner stops excluding it), filtered by the
	 * {@link #excludedSearchField} text. The whole {@link #excludedItemsPanel}
	 * hides when nothing is excluded (regardless of the current filter) so it
	 * never adds empty clutter, but a filter that matches nothing still leaves
	 * the panel (and its search box) up so the user can clear the filter. Only
	 * the user's manual exclusions appear here; mode-based
	 * {@code restrictedItemIds()} (Deadman/LMS filters) are deliberately not shown.
	 * Also composes the collapse toggle (issue #11, {@link #excludedItemsCollapsed})
	 * with the empty-list self-hide: see {@link CollapsibleHeading#bodyVisible}.
	 */
	private void renderExcludedList()
	{
		if (excludedItemsList == null)
		{
			return; // called before construction finished — nothing to do yet
		}
		excludedItemsList.removeAll();
		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		String filter = excludedSearchField == null ? "" : excludedSearchField.getText().trim().toLowerCase(java.util.Locale.ROOT);
		for (int itemId : excludedItemIds)
		{
			String name = itemDisplayName(index, itemId);
			if (!filter.isEmpty() && !name.toLowerCase(java.util.Locale.ROOT).contains(filter))
			{
				continue;
			}
			excludedItemsList.add(buildExcludedCell(itemId, name));
		}
		boolean hasItems = !excludedItemIds.isEmpty();
		excludedItemsPanel.setVisible(hasItems);
		excludedHeading.setText(excludedHeadingText());
		// Composes collapse state with the empty-list self-hide above, not against it — see class javadoc.
		boolean showBody = CollapsibleHeading.bodyVisible(hasItems, excludedItemsCollapsed);
		excludedSearchField.setVisible(showBody);
		excludedScroll.setVisible(showBody);
		excludedItemsPanel.revalidate();
		excludedItemsPanel.repaint();
	}

	/**
	 * One icon-only cell for the excluded-items grid: the item sprite filling
	 * the cell with a small ✕ overlaid in the top-right corner (via
	 * {@link OverlayLayout}) that stops excluding the item. The name is carried
	 * only as a tooltip — see {@link #renderExcludedList}.
	 */
	private JPanel buildExcludedCell(int itemId, String name)
	{
		JLabel icon = swapItemIcon(itemId, name);
		icon.setAlignmentX(0.5f);
		icon.setAlignmentY(0.5f);

		// A transparent overlay the exact same size + alignment as the icon, so
		// OverlayLayout stacks the two dead-centre on each other; the ✕ is then
		// pinned to this overlay's own top-right via BorderLayout.NORTH. (Giving
		// the two cell children mismatched alignments instead would offset them,
		// since OverlayLayout aligns by each child's alignment *point*.)
		JButton remove = new JButton("✕"); // ✕ — stop excluding this item
		remove.setFont(FontManager.getRunescapeSmallFont());
		remove.setFocusPainted(false);
		remove.setBorder(null);
		remove.setMargin(new Insets(0, 0, 0, 0));
		remove.setContentAreaFilled(false);
		remove.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		remove.setToolTipText("Stop excluding " + name + " — allow it in suggestions again");
		remove.addActionListener(e -> removeExcludedItem(itemId));

		JPanel topRight = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		topRight.setOpaque(false);
		topRight.add(remove);

		JPanel overlay = new JPanel(new BorderLayout());
		overlay.setOpaque(false);
		overlay.setAlignmentX(0.5f);
		overlay.setAlignmentY(0.5f);
		overlay.setPreferredSize(new Dimension(ITEM_GRID_CELL_SIZE, ITEM_GRID_CELL_SIZE));
		overlay.setMaximumSize(new Dimension(ITEM_GRID_CELL_SIZE, ITEM_GRID_CELL_SIZE));
		overlay.setToolTipText(name + " — excluded from optimiser suggestions");
		overlay.add(topRight, BorderLayout.NORTH);

		JPanel cell = new JPanel();
		cell.setLayout(new OverlayLayout(cell));
		cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// The overlay is added first so it (and its ✕) paints on top of the icon.
		cell.add(overlay);
		cell.add(icon);
		return cell;
	}

	/**
	 * The owned-item pool + GE prices for the optimiser: every worn item
	 * (always owned, price irrelevant) plus the wealth snapshot's COMPLETE
	 * owned-item map ({@link WealthSnapshot#getAllHoldings()} — inventory +
	 * equipment + bank + pouches, see {@link #lastWealth}) filtered to items
	 * the {@link EquipmentIndexRepository} actually indexes (so the optimiser
	 * never tries to equip e.g. raw materials). Built fresh per search so it
	 * always reflects the latest snapshot.
	 *
	 * <p><b>Membership-based ownership:</b> ownership is "do you have the item
	 * at all", fully decoupled from GE value. The previous source —
	 * {@link WealthSnapshot#getTopHoldings()}, a top-50-BY-VALUE view — wrongly
	 * dropped owned low/zero-value items (e.g. an untradeable fire cape in the
	 * bank never makes a by-value cut), making them look purchasable-only.
	 * {@code getAllHoldings()} has no such truncation; {@code getTopHoldings()}
	 * remains only as a legacy fallback for snapshots built without the full
	 * map (older tests/callers).
	 *
	 * <p><b>Variant-aware ownership (bug B):</b> owning an upgraded variant —
	 * a name ending in " (f)" (fortified, e.g. "Masori body (f)") or " (i)"
	 * (imbued, e.g. "Berserker ring (i)") — also marks the PLAIN form (e.g.
	 * "Masori body"/"Berserker ring") as owned at price 0, resolved generically
	 * via {@link EquipmentIndexRepository#idForName}. Without this the
	 * optimiser has no idea an owned upgrade already supersedes the plain
	 * item, and will happily suggest buying the plain form as an "upgrade".
	 */
	private java.util.Map<Integer, Long> ownedPriceMap()
	{
		java.util.Map<Integer, Long> prices = new HashMap<>();
		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		// Real GE/bank values FIRST. This map feeds the expensive-item RISK cap
		// (GearOptimizer.Request.ownedItemPrices), which must price an owned item
		// at its ACTUAL value — a worn 5m whip is 5m of risk in the wilderness,
		// not free. (Ownership itself is membership-based and value-independent;
		// the value stored here is only the risk figure and the budget never
		// consults it — owned items are free via GearOptimizer's owned SET.)
		// Bug A (finding 1): the equipped loop below used to put(id, 0L) and the
		// wealth loop merged with Math::min, so min(0, realValue) kept 0 for any
		// worn item that was ALSO banked at a real value — every piece of worn
		// gear priced at 0 gp of risk, so the cap counted zero expensive items
		// and could never bind on owned gear. Take the MAX across duplicate
		// entries (worst-case risk) so a real value always wins over the 0 marker.
		if (lastWealth != null)
		{
			java.util.Collection<ItemStack> ownedStacks = !lastWealth.getAllHoldings().isEmpty()
				? lastWealth.getAllHoldings().values()
				: lastWealth.getTopHoldings();
			for (ItemStack stack : ownedStacks)
			{
				if (index.entryFor(stack.getId()) != null)
				{
					prices.merge(stack.getId(), Math.max(0L, stack.getUnitValue()), Math::max);
					addVariantPlainForm(prices, index, stack.getId(), excludedItemIds);
				}
			}
		}
		// Worn items the wealth snapshot didn't value (or a null snapshot) still
		// count as owned, at a 0-gp fallback — an unknown-value item can't be
		// judged expensive, so 0 (never flagged) is the safe default. putIfAbsent
		// so a real value resolved above is never overwritten back to 0.
		if (lastGear != null)
		{
			for (int id : lastGear.equippedItemIds())
			{
				if (id > 0 && index.entryFor(id) != null)
				{
					prices.putIfAbsent(id, 0L);
					addVariantPlainForm(prices, index, id, excludedItemIds);
				}
			}
		}
		return prices;
	}

	/**
	 * If {@code ownedItemId}'s indexed name ends in one of
	 * {@link OwnedVariantResolver#SUFFIXES}, marks the plain (suffix-stripped)
	 * form's item id owned at price 0 too — see {@link #ownedPriceMap}'s
	 * javadoc for why.
	 *
	 * <p><b>An EXCLUDED variant credits nothing.</b> The credit's whole
	 * justification is that the player effectively has the plain item because
	 * they hold the variant — but "exclude from suggestions" withdraws the
	 * variant from every path that could put it in a loadout, so the plain
	 * counterpart stops being backed by anything. Crediting it anyway lets the
	 * optimiser recommend, at zero spend, an item that is not in the bank, and
	 * points the bank highlighter at an id that cannot be there — the exclusion
	 * would have manufactured a free item out of nothing.
	 *
	 * <p>This is the same rule {@link OwnedVariantResolver#preferOwnedVariant}
	 * and {@link VariantCreditSources} already apply, at the layer that grants
	 * the credit rather than the layers that read it. It is the load-bearing
	 * one: dropping the credit here means the plain form is simply not owned,
	 * so a budgeted search prices it as the genuine purchase it would be.
	 */
	private static void addVariantPlainForm(java.util.Map<Integer, Long> prices, EquipmentIndexRepository index,
		int ownedItemId, java.util.Set<Integer> excludedItemIds)
	{
		if (excludedItemIds != null && excludedItemIds.contains(ownedItemId))
		{
			return;
		}
		Integer plainId = OwnedVariantResolver.plainFormId(index, ownedItemId);
		if (plainId != null)
		{
			prices.putIfAbsent(plainId, 0L);
		}
	}

	/**
	 * Builds the 5-way Ranged/Magic/Crush/Slash/Stab selector (item #6e) —
	 * a segmented control mirroring {@link #unitToggle}'s styling. Exactly one
	 * button is ever selected (shared {@link ButtonGroup}); a USER click on a
	 * different type re-runs any visible search for that type immediately
	 * (programmatic {@code setSelected} from {@link #syncStyleSelector}
	 * only fires the ItemListener restyle, never the ActionListener, so the
	 * follow-the-weapon auto-sync can never trigger a search by itself).
	 */
	private JPanel buildOptimizerStyleSelector()
	{
		ButtonGroup group = new ButtonGroup();
		Border selectedBorder = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE);
		Border unselectedBorder = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR);
		JPanel panel = new JPanel(new GridLayout(1, STYLE_ORDER.length, 1, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setToolTipText("Optimise the best setup for this damage type — follows your equipped weapon's "
			+ "current style until you pick one yourself");
		for (int i = 0; i < STYLE_ORDER.length; i++)
		{
			CombatStyle style = STYLE_ORDER[i];
			ImageIcon icon = styleIcon(style);
			// Show the damage-type icon; fall back to the text label if the
			// bundled sprite is missing so the control is never blank.
			JToggleButton button = icon != null ? new JToggleButton(icon) : new JToggleButton(CombatStyleLabel.of(style));
			button.setToolTipText("Find the best " + CombatStyleLabel.of(style)
				+ " setup (owned gear + anything affordable within the budget)");
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setFocusPainted(false);
			button.setMargin(new Insets(2, 0, 2, 0));
			Runnable restyle = () ->
			{
				button.setBorder(button.isSelected() ? selectedBorder : unselectedBorder);
				button.setBackground(button.isSelected()
					? ColorScheme.MEDIUM_GRAY_COLOR
					: ColorScheme.DARKER_GRAY_COLOR);
				button.setForeground(button.isSelected()
					? ColorScheme.BRAND_ORANGE
					: ColorScheme.LIGHT_GRAY_COLOR);
			};
			restyle.run();
			button.addItemListener(e -> restyle.run());
			button.addActionListener(e ->
			{
				if (optimizerStyle == style)
				{
					return; // re-clicking the active type: nothing to do (group keeps it selected)
				}
				optimizerStyle = style;
				styleUserPicked = true;
				if (lastOptimizerResult != null)
				{
					// A search is on screen — re-run it for the new type so the
					// selector always describes the result being shown.
					runOptimizer();
				}
			});
			group.add(button);
			styleButtons[i] = button;
			panel.add(button);
		}
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		styleSelectorPanel = panel;
		return panel;
	}

	/**
	 * The combat style the optimiser should target when the user has not
	 * explicitly picked one (item #6g): the live readout's currently selected
	 * style — which {@link #rankAndRender} always resolves from the EQUIPPED
	 * (or what-if) weapon's real combat options, so a wand detects MAGIC and a
	 * bow RANGED — falling back to the weapon's first style pre-target.
	 */
	private CombatStyle detectedCombatStyle()
	{
		if (selectedStyle != null)
		{
			return selectedStyle.type();
		}
		List<WeaponStyle> styles = weaponRepo.stylesForItem(effectiveWeaponId());
		return styles.isEmpty() ? null : styles.get(0).type();
	}

	/** The damage-type constraint for the next optimiser run: the user's pick, else the detected current style. */
	private CombatStyle optimizerConstraint()
	{
		return optimizerStyle != null ? optimizerStyle : detectedCombatStyle();
	}

	/**
	 * Re-asserts the 5-way selector from {@link #optimizerStyle}, first
	 * re-detecting it from the equipped weapon unless the user has picked one
	 * manually. Called on every {@link #rankAndRender} so the selector tracks
	 * weapon swaps live (the manual pick is dropped on a weapon change, same
	 * as the readout's own style lock).
	 */
	private void syncStyleSelector()
	{
		if (!styleUserPicked && !styleAutoPicked)
		{
			CombatStyle detected = detectedCombatStyle();
			if (detected != null)
			{
				optimizerStyle = detected;
			}
		}
		for (int i = 0; i < STYLE_ORDER.length; i++)
		{
			JToggleButton button = styleButtons[i];
			boolean selected = STYLE_ORDER[i] == optimizerStyle;
			if (button != null && button.isSelected() != selected)
			{
				button.setSelected(selected);
			}
		}
	}

	/** Callback invoked once a budget/owned-prices/price-source/risk-values/needs-protection set is ready — see {@link #withResolvedPrices}. */
	@FunctionalInterface
	private interface PriceReady
	{
		void run(long budget, java.util.Map<Integer, Long> ownedPrices, GearOptimizer.PriceSource priceSource,
			java.util.Map<Integer, Long> riskValues, java.util.Set<Integer> needsProtection);
	}

	/**
	 * Shared price-resolution scaffolding for both the single-style
	 * ({@link #runOptimizer}) and all-styles ({@link #runAndRankStyles})
	 * search paths: guards on a selected target, flips the button/status UI
	 * into "Searching...", persists prefs, resolves the budget/owned-prices,
	 * and — once a {@link GearOptimizer.PriceSource} is available, either
	 * immediately (no resolver wired) or asynchronously (client-thread GE
	 * lookup) — hands them to {@code consumer}.
	 *
	 * <p>The candidate id set sent to the resolver deliberately does NOT
	 * exclude owned ids (unlike the historical behaviour): the resolver also
	 * computes each id's real gp risk value (see {@link PriceLookup#riskValues()}),
	 * and an owned item's risk value must be resolved too — see {@code
	 * GearOptimizer.expensiveItemCountOf}'s javadoc for why an owned item is
	 * still riskable gear. This is safe for the BUDGET price too: {@link
	 * GearOptimizer} never consults {@code priceSource} for an owned id
	 * (owned items are always free via {@code Request.owned}), so pricing
	 * them here has no budget-side effect.
	 */
	private void withResolvedPrices(PriceReady consumer)
	{
		if (lastGear == null || selectedMonster == null)
		{
			statusLabel.setText("Pick a target above first");
			statusLabel.setVisible(true);
			resultPanel.setVisible(false);
			clearPreviewButton.setVisible(false);
			resetBankHighlightToggle();
			return;
		}

		findBestSetupButton.setEnabled(false);
		findBestGridButton.setEnabled(false);
		statusLabel.setText("Searching...");
		statusLabel.setVisible(true);
		resultPanel.setVisible(false);
		clearPreviewButton.setVisible(false);
		resetBankHighlightToggle();
		saveOptimizerPrefs();

		long budget = resolvedBudget();
		java.util.Map<Integer, Long> ownedPrices = ownedPriceMap();

		if (priceResolver == null)
		{
			// No client-thread price source available (headless test / not wired) —
			// legitimate owned-only fallback: an unpriced non-owned item resolves to
			// Long.MAX_VALUE (unaffordable at any budget); owned items are separately
			// marked affordable via .owned(...) regardless of price. No risk-value
			// data either — the cap falls back to the price source (see
			// GearOptimizer.Request.Builder#riskValueSource).
			consumer.run(budget, ownedPrices,
				ItemEligibility.resolveOptimizerPriceSource(id -> ownedPrices.getOrDefault(id, 0L), java.util.Collections.emptySet()),
				java.util.Collections.emptyMap(), java.util.Collections.emptySet());
			return;
		}

		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		java.util.Set<Integer> candidateIds = new java.util.HashSet<>(index.allItemIds());
		candidateIds.addAll(ownedPrices.keySet());
		// Craft-ingredient ids (e.g. the Scorching bow's Tormented synapse)
		// must be priced too: resolveOptimizerPriceSource's craft-ingredient
		// branch reads the ingredient's price from lookup.prices(), which is
		// only populated for ids in this set — an ingredient absent here
		// (not itself equipment, not owned) resolves to 0 there and the
		// exception falls through to unaffordable. Mirrors
		// runOptimizerSyncForTest/runOptimizerAndRankStylesSyncForTest,
		// which already did this for the test-seam paths.
		candidateIds.addAll(ItemEligibility.UNTRADEABLE_CRAFT_INGREDIENT.values());

		priceResolver.resolve(candidateIds, lookup ->
		{
			// .owned() already makes owned items free/affordable — no need to
			// special-case ownedPrices here. Anything the resolver didn't price
			// (unknown) or flagged untradeable falls back to Long.MAX_VALUE =
			// unaffordable — see resolveOptimizerPriceSource (bug D).
			consumer.run(budget, ownedPrices,
				ItemEligibility.resolveOptimizerPriceSource(id -> lookup.prices().getOrDefault(id, 0L), lookup.untradeableIds()),
				lookup.riskValues(), lookup.needsProtection());
		});
	}

	/**
	 * Runs {@link GearOptimizer} off the EDT for the currently selected style
	 * and publishes the result back via {@link #onOptimizerResult}.
	 *
	 * <p>P1-B fix: {@link #optimizerGeneration} is captured HERE, before
	 * price resolution (which may hop async) even begins — see {@link
	 * #installResultIfCurrent}.
	 */
	private void runOptimizer()
	{
		int generation = optimizerGeneration;
		withResolvedPrices((budget, ownedPrices, priceSource, riskValues, needsProtection) ->
		{
			lastOptimizerNeedsProtection = needsProtection;
			runOptimizerSearch(buildRequest(budget, ownedPrices, priceSource, riskValues, needsProtection,
				optimizerConstraint()), generation);
		});
	}

	/**
	 * The "Find best setup" button's action (item #6e): runs the optimiser for
	 * ALL FIVE damage types (not just the selected one), then displays either
	 * the style the user has explicitly locked in or — if nothing is locked (a
	 * fresh target, or the weapon-detected default) — whichever damage type
	 * actually comes out on top by DPS, and reorders the style selector buttons
	 * left-to-right by best-achievable DPS (see {@link #applyRankedStyleResults}).
	 * Unlike {@link #runOptimizer}, this is deliberately NOT used by the toggle/
	 * exclude-item/style-selector re-runs — those stay single-style so they
	 * stay responsive.
	 *
	 * <p>P1-B fix: {@link #optimizerGeneration} is captured HERE, before
	 * price resolution (which may hop async) even begins — see {@link
	 * #applyRankedStyleResultsIfCurrent}.
	 */
	private void runAndRankStyles()
	{
		int generation = optimizerGeneration;
		withResolvedPrices((budget, ownedPrices, priceSource, riskValues, needsProtection) ->
		{
			lastOptimizerNeedsProtection = needsProtection;
			CombatStyle selected = optimizerConstraint();
			java.util.Map<CombatStyle, GearOptimizer.Request> requests = new java.util.LinkedHashMap<>();
			for (CombatStyle style : STYLE_ORDER)
			{
				requests.put(style, buildRequest(budget, ownedPrices, priceSource, riskValues,
					needsProtection, style));
			}

			new javax.swing.SwingWorker<java.util.Map<CombatStyle, GearOptimizer.Result>, Void>()
			{
				@Override
				protected java.util.Map<CombatStyle, GearOptimizer.Result> doInBackground()
				{
					java.util.Map<CombatStyle, GearOptimizer.Result> results = new java.util.LinkedHashMap<>();
					for (java.util.Map.Entry<CombatStyle, GearOptimizer.Request> entry : requests.entrySet())
					{
						results.put(entry.getKey(), GearOptimizer.optimize(entry.getValue()));
					}
					return results;
				}

				@Override
				protected void done()
				{
					try
					{
						applyRankedStyleResultsIfCurrent(get(), selected, generation);
					}
					catch (java.util.concurrent.ExecutionException | InterruptedException e)
					{
						statusLabel.setText("Search failed");
						findBestSetupButton.setEnabled(true);
						findBestGridButton.setEnabled(true);
					}
				}
			}.execute();
		});
	}

	/**
	 * Shared by the real ({@code SwingWorker}) and sync-test paths of
	 * {@link #runAndRankStyles}: resolves which style to actually
	 * display, renders it, and reorders the 5-way selector by DPS.
	 *
	 * <p>If the user has a style explicitly locked in ({@code selected}, from
	 * {@link #optimizerConstraint()}), that pick is honoured. If nothing is
	 * locked — a freshly picked target, or a weapon-detected default the user
	 * never confirmed — the actual global-best damage type (by DPS across
	 * {@code results}) is selected instead and locked in exactly as a manual
	 * click on that style's button would, so a later re-render (e.g.
	 * {@link #syncStyleSelector}) can't silently re-detect it away
	 * from the equipped weapon's own style.
	 */
	private void applyRankedStyleResults(java.util.Map<CombatStyle, GearOptimizer.Result> results, CombatStyle selected)
	{
		CombatStyle display = selected;
		if (!styleUserPicked)
		{
			CombatStyle best = null;
			double bestScore = Double.NEGATIVE_INFINITY;
			for (CombatStyle style : STYLE_ORDER)
			{
				double score = bestDps(results.get(style));
				// best == null takes the first candidate unconditionally: if every
				// style is unusable (all-NEGATIVE_INFINITY), the strict `score >
				// bestScore` alone would never fire and `best` would stay null,
				// leaving `display` null when nothing was explicitly selected
				// either — see onOptimizerResult's NPE on result.style() below.
				if (best == null || score > bestScore)
				{
					bestScore = score;
					best = style;
				}
			}
			if (best != null)
			{
				display = best;
				optimizerStyle = best;
				// Auto-lock (not a manual pick): sticks against a weapon
				// re-detect, but is dropped on a target change so the next
				// monster re-evaluates its own best style (item #1).
				styleAutoPicked = true;
				// Programmatic setSelected fires only the ItemListener restyle,
				// never the ActionListener search (see buildOptimizerStyleSelector),
				// so locking the auto-picked best in cannot recurse.
				for (int i = 0; i < STYLE_ORDER.length; i++)
				{
					styleButtons[i].setSelected(STYLE_ORDER[i] == best);
				}
			}
		}

		GearOptimizer.Result displayResult = results.get(display);
		if (displayResult == null)
		{
			// Defensive fallback: `display` is null (no style was selected/locked
			// and results was empty above) or points to a style missing from the
			// map. Both should be unreachable given STYLE_ORDER is
			// always fully populated by runAndRankStyles, but falling
			// back to any available entry beats an NPE in onOptimizerResult.
			java.util.Iterator<GearOptimizer.Result> any = results.values().iterator();
			displayResult = any.hasNext() ? any.next() : null;
		}
		onOptimizerResult(displayResult);
		reorderSelectorsByDps(results);
	}

	/**
	 * P1-B fix: gates {@link #applyRankedStyleResults} — which reorders the
	 * style selector AND installs a result via {@link #onOptimizerResult} —
	 * behind the {@link #optimizerGeneration} this all-styles search was
	 * launched under (captured by {@link #runAndRankStyles} /
	 * {@link #runOptimizerAndRankStylesSyncForTest} before price resolution
	 * began). A mismatch means owned-only mode flipped OFF-&gt;ON while this
	 * search was still in flight (see {@link #refreshIronmanOwnedOnlyMode});
	 * {@code results} is dropped entirely rather than installed or used to
	 * reorder the selector. The "Find best setup" buttons are still
	 * re-enabled either way — a stale drop must not leave them stuck
	 * disabled.
	 */
	private void applyRankedStyleResultsIfCurrent(java.util.Map<CombatStyle, GearOptimizer.Result> results,
		CombatStyle selected, int generation)
	{
		if (generation != optimizerGeneration)
		{
			findBestSetupButton.setEnabled(true);
			findBestGridButton.setEnabled(true);
			return;
		}
		applyRankedStyleResults(results, selected);
	}

	/**
	 * Reorders the visual layout of {@link #styleSelectorPanel} so
	 * the five style buttons read left-to-right by best-achievable DPS
	 * (highest first), stable on ties (keeping {@link #STYLE_ORDER}'s
	 * order). A style with no usable weapon at all ({@code result.style() ==
	 * null}, or a missing result) sorts last. Only the VISUAL order changes —
	 * {@link #STYLE_ORDER} and {@link #styleButtons} stay
	 * untouched so selection logic ({@link #syncStyleSelector}) keeps
	 * working unmodified.
	 */
	private void reorderSelectorsByDps(java.util.Map<CombatStyle, GearOptimizer.Result> results)
	{
		if (styleSelectorPanel == null)
		{
			return;
		}

		Integer[] order = new Integer[STYLE_ORDER.length];
		for (int i = 0; i < order.length; i++)
		{
			order[i] = i;
		}
		java.util.Arrays.sort(order, (a, b) ->
		{
			double dpsA = bestDps(results.get(STYLE_ORDER[a]));
			double dpsB = bestDps(results.get(STYLE_ORDER[b]));
			// Arrays.sort on an Integer[] (object array) is a stable mergesort,
			// so equal-dps styles keep their original STYLE_ORDER
			// position without an explicit tiebreak.
			return Double.compare(dpsB, dpsA);
		});

		styleSelectorPanel.removeAll();
		for (int idx : order)
		{
			styleSelectorPanel.add(styleButtons[idx]);
		}
		styleSelectorPanel.revalidate();
		styleSelectorPanel.repaint();
	}

	/** The DPS to rank a style by in {@link #reorderSelectorsByDps} — unusable styles sort last. */
	private static double bestDps(GearOptimizer.Result result)
	{
		return (result == null || result.style() == null) ? Double.NEGATIVE_INFINITY : result.dps().dps();
	}

	/**
	 * Builds the {@link GearOptimizer.Request} shared by both the resolver and
	 * no-resolver price paths ({@link #withResolvedPrices}), for the given
	 * {@code styleConstraint} — the single-style caller passes
	 * {@link #optimizerConstraint()}; the all-styles ranker
	 * ({@link #runAndRankStyles}) passes each of
	 * {@link #STYLE_ORDER} in turn.
	 *
	 * @param riskValues per-item id real gp risk value (see {@link
	 *                   PriceLookup#riskValues()}), wired as {@link
	 *                   GearOptimizer.Request.Builder#riskValueSource} — empty
	 *                   (the no-resolver path) leaves the cap falling back to
	 *                   {@code priceSource} unchanged.
	 * @param needsProtection ids priced only via the Trouver-parchment fallback
	 *                        (see {@link PriceLookup#needsProtection()} / {@code
	 *                        com.ospulse.combat.RiskValuation.Source#PARCHMENT}) —
	 *                        rare untradeables with no real tradeable equivalent.
	 *                        Added to the optimizer's exclude set when the
	 *                        "Hide unprotectable items" config setting is on;
	 *                        otherwise left alone (still valued, still allowed).
	 */
	private GearOptimizer.Request buildRequest(long budget, java.util.Map<Integer, Long> ownedPrices,
		GearOptimizer.PriceSource priceSource, java.util.Map<Integer, Long> riskValues,
		java.util.Set<Integer> needsProtection, CombatStyle styleConstraint)
	{
		int[] liveIds = lastGear.equippedItemIds();
		Monster target = selectedMonster;
		PlayerCombat.Builder template = PlayerCombat.builder()
			.attack(lastGear.baseAttack(), lastGear.boostedAttack())
			.strength(lastGear.baseStrength(), lastGear.boostedStrength())
			.defence(lastGear.baseDefence(), lastGear.boostedDefence())
			.ranged(lastGear.baseRanged(), lastGear.boostedRanged())
			.magic(lastGear.baseMagic(), lastGear.boostedMagic())
			.prayer(lastGear.basePrayer(), lastGear.boostedPrayer())
			.hitpoints(lastGear.baseHitpoints(), lastGear.boostedHitpoints())
			.activePrayers(lastGear.activePrayers())
			.assumeBestPotion(bestPotionToggle.isSelected())
			.assumeBestPrayer(bestPrayerToggle.isSelected())
			// Keyed off styleConstraint (this request's own style), not
			// selectedStyle: runAndRankStyles calls buildRequest once per
			// STYLE_ORDER entry, so each style's search must apply that
			// style's own swap-menu pick, not whichever style the readout
			// currently has selected. Ignored entirely with the toggle off —
			// see assumedPrayerFor's javadoc for why that mirrors DpsCalculator.
			.assumedPrayer(assumedPrayerFor(styleConstraint))
			.onSlayerTask(onSlayerTaskToggle.isSelected())
			.magicPotionVariant(magicPotionVariantForCalc());

		java.util.Map<Integer, Integer> creditSources =
			new java.util.HashMap<>(VariantCreditSources.from(lastWealth, lastGear,
				EquipmentIndexRepository.getInstance(), excludedItemIds));
		// A credit collapses "use the held variant" and "buy an ordinary copy"
		// onto one item id, which the optimiser's per-slot candidates (bare
		// ints) cannot tell apart. Where that costs the cap its only safe
		// option, the credit is withdrawn so the counterpart behaves as the
		// ordinary purchase it would be — see RiskCreditPolicy for why each
		// condition is required. Risk values are read UNremapped here: the
		// request's own source reports the variant's value for both ids, which
		// would make the comparison vacuous. Gated by riskCapApplies() (issue
		// #11) so a closed Wilderness gate leaves the credit alone too, not
		// just the Request's own expensiveItemThreshold below — both must
		// agree on whether the cap is active, or a non-Wilderness search with
		// the override off can still withdraw a credit the (inactive) cap was
		// never going to enforce anyway.
		long gatedExpensiveThreshold = riskCapApplies() ? resolvedExpensiveThreshold() : 0L;
		int expensiveAllowance = resolvedExpensiveCount();
		java.util.Set<Integer> withdrawnCredits = RiskCreditPolicy.withdrawnForSaferPurchase(
			creditSources,
			id -> riskValues.getOrDefault((int) id, 0L),
			id -> priceSource.priceFor((int) id),
			GearOptimizer.expensiveCapActive(gatedExpensiveThreshold, expensiveAllowance),
			expensiveAllowance, gatedExpensiveThreshold, budget);
		java.util.Set<Integer> ownedIdsForSearch = ownedPrices.keySet();
		if (!withdrawnCredits.isEmpty())
		{
			creditSources.keySet().removeAll(withdrawnCredits);
			ownedIdsForSearch = new java.util.LinkedHashSet<>(ownedPrices.keySet());
			ownedIdsForSearch.removeAll(withdrawnCredits);
		}
		java.util.Set<Integer> exclusions = new java.util.LinkedHashSet<>(excludedItemIds);
		exclusions.addAll(ItemEligibility.restrictedItemIds());
		if (hideUnprotectableItemsPref())
		{
			// "Hide unprotectable items": rare untradeables with no real tradeable
			// equivalent (only priced via the Trouver-parchment fallback — see
			// com.ospulse.combat.RiskValuation.Source#PARCHMENT) are still valued
			// (they count against the expensive-item cap either way), but with
			// this setting on they're also excluded outright rather than ever
			// recommended, since the player can't actually protect them on death.
			exclusions.addAll(needsProtection);
		}

		// B9-5: the player's BASE levels drive the equip-requirement gate so the
		// optimiser never recommends gear they can't wield at their current
		// levels. Combat skills come straight from the live snapshot; Agility /
		// Slayer requirements (crystal gear, slayer helm) are now included too.
		java.util.Map<String, Integer> baseLevels = currentBaseLevels();

		return GearOptimizer.Request
			.builder(liveIds, target, template)
			.budget(budget)
			.owned(ownedIdsForSearch)
			// Retained for any other budget-side consumer/back-compat, but no
			// longer consulted by the expensive-item risk cap — riskValueSource
			// below owns that job exclusively now (see
			// GearOptimizer.expensiveItemCountOf's updated javadoc).
			.ownedItemPrices(ownedPrices)
			.exclude(exclusions)
			.include(ItemEligibility.mandatoryOverrideItemIds(target, exclusions, ironmanOwnedOnlyPref(), ownedPrices.keySet()))
			.priceSource(priceSource)
			// The expensive-item risk cap's OWN price source: a real gp "risk
			// value" per item — tradeable = GE price, untradeable = value of
			// its tradeable components (see com.ospulse.combat.RiskValuation) —
			// completely decoupled from priceSource/ownedItemPrices above,
			// which drive budget/affordability only. Only wired when the
			// client-thread resolver actually supplied risk data; an empty map
			// (no resolver, e.g. a headless owned-only search) leaves the cap
			// falling back to priceSource unchanged (see
			// GearOptimizer.Request.Builder#riskValueSource).
			// The cap must price what the player is actually told to RISK, and
			// for a credited plain id that is the held variant, not the
			// counterpart the ownership map invented (see
			// VariantCreditSources). A tradeable cosmetic can be worth a
			// different amount from its ordinary form, and with a threshold
			// between the two the cap would otherwise count the wrong item's
			// gp and let a wilderness search break the user's own limit. The
			// variant's own value wins; the credited id's value is the
			// fallback for a variant the resolver did not price, so an
			// unpriced variant can never silently drop the slot to 0.
			.riskValueSource(lastRiskValueSource = riskValues.isEmpty() ? null : id ->
			{
				Integer source = creditSources.get(id);
				Long variantRisk = source == null ? null : riskValues.get(source);
				return variantRisk != null ? variantRisk : riskValues.getOrDefault(id, 0L);
			})
			.expensiveItemCount(resolvedExpensiveCount())
			// Wilderness gate (issue #11): threshold 0 is GearOptimizer's existing
			// "cap disabled" sentinel (see expensiveCapActive), so a closed gate
			// needs no optimizer-side change and no stale field value can leak
			// into a search the cap should not touch. Same gated value the
			// credit-withdrawal check above already used, so both agree.
			.expensiveItemThreshold(gatedExpensiveThreshold)
			// Items #6e/#6g: anchor the search to the requested damage type,
			// which (for the single-style caller) defaults to the EQUIPPED
			// weapon's current style — never an implicit best-of-any-style
			// (i.e. usually melee) search.
			.style(styleConstraint)
			// Magic view only: pin the gear DPS to the selected spellbook tab so
			// swapping Standard/Ancient swaps the optimiser's magic spell too.
			.spellBook(magicView ? selectedBook.book() : null)
			// Monster combat gate (e.g. Kurask): restrict weapon/ammo candidates
			// to what can actually damage the selected target.
			.combatRequirement(target == null ? null
				: MonsterCombatRequirementRepository.getInstance().forMonster(target.lookupName()).orElse(null))
			.playerBaseLevels(baseLevels)
			.build();
	}

	/**
	 * Runs the given request off the EDT via {@code SwingWorker} and
	 * publishes the result back via {@link #onOptimizerResult} — unless
	 * {@code generation} (the {@link #optimizerGeneration} this search was
	 * launched under — see {@link #runOptimizer}) has since gone stale (P1-B
	 * fix), in which case {@link #installResultIfCurrent} drops it.
	 */
	private void runOptimizerSearch(GearOptimizer.Request request, int generation)
	{
		new javax.swing.SwingWorker<GearOptimizer.Result, Void>()
		{
			@Override
			protected GearOptimizer.Result doInBackground()
			{
				return GearOptimizer.optimize(request);
			}

			@Override
			protected void done()
			{
				try
				{
					installResultIfCurrent(get(), generation);
				}
				catch (java.util.concurrent.ExecutionException | InterruptedException e)
				{
					statusLabel.setText("Search failed");
					findBestSetupButton.setEnabled(true);
					findBestGridButton.setEnabled(true);
				}
			}
		}.execute();
	}

	/**
	 * P1-B fix: installs {@code result} via {@link #onOptimizerResult}
	 * unless the search that produced it was launched under a since-stale
	 * {@link #optimizerGeneration} — i.e. owned-only mode flipped OFF-&gt;ON
	 * (see {@link #refreshIronmanOwnedOnlyMode}) while price resolution or
	 * the background {@code SwingWorker} was still running. A stale result
	 * is dropped entirely: never installed into {@link #lastOptimizerResult},
	 * never auto-previewed, never used to arm the bank highlight. The "Find
	 * best setup" buttons are still re-enabled either way — a stale drop
	 * must not leave them stuck disabled.
	 */
	private void installResultIfCurrent(GearOptimizer.Result result, int generation)
	{
		if (generation != optimizerGeneration)
		{
			findBestSetupButton.setEnabled(true);
			findBestGridButton.setEnabled(true);
			return;
		}
		onOptimizerResult(result);
	}

	/** Renders a completed {@link GearOptimizer.Result} — called on the EDT by the {@code SwingWorker} above. */
	private void onOptimizerResult(GearOptimizer.Result result)
	{
		findBestSetupButton.setEnabled(true);
		findBestGridButton.setEnabled(true);

		// P1-A fix: a mandatory monster-gear override the player owns
		// neither the primary item nor any accepted substitute for is
		// force-included/force-equipped by GearOptimizer regardless of
		// budget (see ItemEligibility#mandatoryOverrideItemIds and
		// GearOptimizer's applyForcedIncludes) — that is correct in every
		// other mode, but owned-only mode's entire guarantee is that every
		// recommendation is something the player owns, so `result` here
		// must never be installed/auto-previewed/bank-highlighted in that
		// case. Checked ahead of `result` entirely (not derived from it):
		// the block is a property of the target + ownership, independent of
		// whatever loadout the optimiser happened to compute around the
		// forced item.
		java.util.Map<Integer, Long> ownedIds = ownedPriceMap();
		java.util.Optional<MonsterGearOverride> blockingOverride = OwnedOnlyMandatoryOverrideGate.blockingOverride(
			ironmanOwnedOnlyPref(), selectedMonster, ownedIds.keySet());
		if (blockingOverride.isPresent())
		{
			MonsterGearOverride blocking = blockingOverride.get();
			renderOwnedOnlyBlockedState("Cannot recommend a loadout vs " + selectedMonster.name() + ": "
				+ blocking.itemName() + " (" + slotDisplayName(blocking.slot())
				+ ") is required and you don't own it — " + blocking.reason());
			return;
		}
		// P2-B fix (Codex finding on PR #19, GearSection.java:5123, "Hide the
		// blocked message before rendering a later result"): every path below
		// this point renders a NON-blocked outcome (a normal loadout, an
		// unchanged-loadout "no upgrade", or the no-usable-weapon state) — hide
		// the "cannot recommend" label here, the single place every one of
		// those paths already passes through, so a later successful/no-usable-
		// weapon result can never leave the earlier blocked target's message
		// lingering underneath it.
		ownedOnlyBlockedLabel.setVisible(false);

		// P2-A fix (half 1, Codex finding on PR #19, GearSection.java:4789,
		// "Revalidate every recommended item against current ownership"): the
		// mandatory-override gate above only covers a MonsterGearOverride's
		// forced item — an ORDINARY loadout choice the optimiser picked from
		// the ownedPrices snapshot captured when the search launched (see
		// withResolvedPrices) can go stale by the time this callback lands,
		// e.g. the player sells it while price resolution/the background
		// SwingWorker was still running. Re-check every RESOLVED id (via
		// loadoutSlotMap -> resolvedItemId, the single choke
		// point everything downstream of `result` actually shows/applies)
		// against ownedIds — a LIVE read taken just above, not the stale
		// snapshot the optimiser searched against — before installing,
		// previewing, or bank-highlighting anything from `result`.
		java.util.Optional<java.util.Map.Entry<Integer, Integer>> unownedEntry = OwnedOnlyResultOwnershipGate
			.firstUnownedEntry(ironmanOwnedOnlyPref(), loadoutSlotMap(result), ownedIds.keySet());
		if (unownedEntry.isPresent())
		{
			int unownedSlot = unownedEntry.get().getKey();
			int unownedItemId = unownedEntry.get().getValue();
			String unownedSlotName = unownedSlot >= 0 && unownedSlot < SLOT_NAMES.length
				&& !SLOT_NAMES[unownedSlot].isEmpty() ? SLOT_NAMES[unownedSlot] : ("Slot " + unownedSlot);
			renderOwnedOnlyBlockedState("Cannot recommend a loadout vs " + selectedMonster.name() + ": "
				+ itemDisplayName(EquipmentIndexRepository.getInstance(), unownedItemId) + " (" + unownedSlotName
				+ ") is no longer owned.");
			return;
		}

		lastOptimizerResult = result;

		CombatStyle constraint = optimizerConstraint();
		resultStyle.setText(result.style() != null
			? CombatStyleLabel.of(result.style().type())
			: (constraint != null ? CombatStyleLabel.of(constraint) : "-"));

		boolean anyChange = hasAnySlotChange(result);
		boolean noUsableWeapon = result.style() == null;
		if (noUsableWeapon)
		{
			// Style-constrained search found NO loadout that can attack with the
			// requested type at all (e.g. Magic selected but no magic weapon is
			// owned or affordable) — say that, not a misleading "no upgrade".
			statusLabel.setText("No usable " + (constraint != null ? CombatStyleLabel.of(constraint) : "")
				+ " weapon owned or affordable within budget");
			statusLabel.setVisible(true);
		}
		else if (!anyChange)
		{
			// Fix 5: say so explicitly instead of leaving the user staring at a
			// "Best DPS found" panel that matches their current loadout with no
			// indication of whether that's a bug or just "you're already best".
			statusLabel.setText("No upgrade found within budget / owned + affordable pool");
			statusLabel.setVisible(true);
		}
		else
		{
			statusLabel.setVisible(false);
		}

		resultDps.setText(DpsFormat.html(result.dps().dps()));
		double delta = result.deltaDps();
		// Item #6b: no literal triangle glyph — "owned-only DPS -> best-found
		// DPS", the whole readout coloured green (upgrade) / red (downgrade),
		// matching the what-if row's styling (updateWhatIfDelta) and the
		// panel's existing green/red gain colours elsewhere.
		java.awt.Color deltaColor = delta > 1e-9 ? DELTA_UP_COLOR
			: delta < -1e-9 ? DELTA_DOWN_COLOR : java.awt.Color.WHITE;
		resultDelta.setForeground(deltaColor);
		resultDelta.setText("<html>" + DpsFormat.deltaFragment(result.ownedOnlyDps(), delta) + " -> "
			+ DpsFormat.deltaFragment(result.dps().dps(), delta) + "</html>");
		resultSpend.setText(formatGp(result.totalSpend()));
		resultDpsPerGp.setText(result.totalSpend() > 0
			? String.format(Locale.ROOT, "%.6f", result.dpsPerGp())
			: "-");
		// Item #5: in the no-usable-weapon state, the five stat rows above (and
		// the "Suggested swaps" heading + list) are all meaningless/stale — hide
		// them entirely and show one big, unmissable line instead. Symmetric:
		// a subsequent usable result restores the normal layout in the else
		// branch below. Split in two (issue #11) so ironman owned-only mode
		// can additionally hide the four upgrade rows without touching
		// "Optimised for" (which describes the pick, not an upgrade).
		setOptimizerStyleRowVisible(!noUsableWeapon);
		setUpgradeStatRowsVisible(OwnedOnlyMode.upgradeStatRowsVisible(ironmanOwnedOnlyPref(), !noUsableWeapon));
		if (noUsableWeapon)
		{
			// A8: a style with no usable weapon at all must never fall through
			// to the "already best" placeholder below (that phrasing implies
			// "you're optimal", not "this style can't damage the target") —
			// show a clear big "0 DPS" line instead.
			String typeLabel = constraint != null ? CombatStyleLabel.of(constraint) : "";
			noUsableWeaponLabel.setText("No usable " + typeLabel + " weapon earned or affordable — 0 DPS");
			noUsableWeaponLabel.setVisible(true);
			renderNoUsableWeaponSwapMessage(constraint);
		}
		else
		{
			noUsableWeaponLabel.setVisible(false);
			renderSwapList(result);
		}
		// Nothing to preview/clear/show-in-bank when the suggestion equals what's
		// already worn, or when there's no usable weapon to recommend at all.
		// (applyResultButton itself stays hidden — B8-4 auto-previews
		// below instead of waiting for a manual click.)
		clearPreviewButton.setVisible(anyChange && !noUsableWeapon);
		// B9-4: auto-arm the bank filter the moment a usable result exists — no
		// manual "Show in bank" toggle. This arms even when anyChange is false
		// (worn == best) so the full recommended equipment grid still shows in the
		// bank; switching styles re-runs the optimiser and lands back here, live-
		// updating the grid. When the bank is closed nothing renders; it appears
		// on the next bank open (BankRecommendationHighlighter.reapplyIfArmed).
		if (bankHighlighter != null)
		{
			if (noUsableWeapon)
			{
				bankHighlighter.clear();
			}
			else
			{
				bankHighlighter.showInBank(loadoutSlotMap(result), bankConsumableIds());
			}
		}
		resultPanel.setVisible(true);
		resultPanel.revalidate();
		body().revalidate();
		body().repaint();

		// Item #4: refresh the grid's crossed-out state for this result right
		// away — the noUsableWeapon case never reaches applyResultToOverride()
		// below (that's guarded on result.style() != null && anyChange), which is
		// otherwise the only place updateGearGrid gets called after a fresh
		// optimiser result, so without this the "every slot crossed out" render
		// would only appear on some later, unrelated grid refresh.
		updateGearGrid(lastGear);

		// B8-4: auto-preview — apply the swaps immediately instead of requiring
		// a manual "Preview these swaps" click, so both "Find best setup" and
		// clicking a style icon (which re-runs the optimiser for that single
		// style and lands back here) instantly show the what-if readout for
		// the currently-displayed result.
		if (result != null && result.style() != null && anyChange)
		{
			applyResultToOverride();
		}
	}

	/** A {@code PanelWidgets.statRow} value label's row container ({@code statRow} returns only the value, so the row is its parent). */
	private static java.awt.Container statRow(JLabel value)
	{
		java.awt.Container parent = value.getParent();
		return parent != null ? parent : value;
	}

	/** Shows/hides only the "Optimised for" row — split out of the old combined {@code setOptimizerStatRowsVisible} (issue #11) since owned-only mode must never hide it. */
	private void setOptimizerStyleRowVisible(boolean visible)
	{
		statRow(resultStyle).setVisible(visible);
	}

	/** Shows/hides the four upgrade-oriented stat rows + "Suggested swaps" heading/list — the other half of the old combined {@code setOptimizerStatRowsVisible} (issue #11). */
	private void setUpgradeStatRowsVisible(boolean visible)
	{
		for (JLabel value : new JLabel[] {
			resultDps, resultDelta, resultSpend, resultDpsPerGp})
		{
			statRow(value).setVisible(visible);
		}
		swapListHeading.setVisible(visible);
		swapList.setVisible(visible);
	}

	/**
	 * Re-applies ironman owned-only mode after a post-construction config
	 * change (issue #11 P2 fix) — setVisible only, no rebuild.
	 *
	 * <p>Codex/CodeRabbit finding on PR #19: a "Find best setup" result
	 * computed while owned-only mode was OFF (a real, possibly non-zero
	 * budget) used to simply have its upgrade-UI rows hidden here, but the
	 * result itself — and the what-if override / bank highlight it already
	 * auto-applied (see the class javadoc's "B8-4 auto-preview" / "B9-4
	 * auto-arm") — survived untouched, so the panel kept silently
	 * recommending gear the player might not own while owned-only mode was
	 * now visibly ON. This is exactly the scenario auto-detect creates:
	 * flipping the mode ON mid-session, after the player already searched.
	 *
	 * <p>Only clears on the OFF-&gt;ON transition specifically (see {@link
	 * #lastKnownIronmanOwnedOnlyPref}'s javadoc for why "currently on" alone
	 * is the wrong condition). {@link #resetAllOverrides()} — the existing
	 * "Revert to current gear" / "Clear preview" action — is reused rather
	 * than re-running the optimiser: {@code runOptimizer()} always goes
	 * through {@code runOptimizerSearch}'s real {@code SwingWorker} (even
	 * with no {@link #priceResolver} wired — see {@code
	 * runOptimizerSyncForTest}'s javadoc on why that test seam exists at
	 * all), so it can't complete synchronously with this method's caller
	 * ({@code OSPulsePlugin#onConfigChanged}, off the EDT via {@code
	 * invokeLater} either way); {@code resetAllOverrides()} is fully
	 * synchronous and already exactly clears "every what-if override AND any
	 * optimiser-applied preview/highlight" in one clean, already-tested step,
	 * leaving the readout showing the player's real worn gear — never a
	 * half-torn-down state.
	 *
	 * <p>P1-B fix (Codex finding on PR #19, {@code GearSection.java:4843}):
	 * the {@code lastOptimizerResult != null} guard above only clears a
	 * result that has already LANDED. A search launched under the previous
	 * (possibly nonzero) budget — price resolution still in flight, or the
	 * {@code SwingWorker} still running in the background — has {@link
	 * #lastOptimizerResult} still {@code null} at the exact moment this
	 * method runs, so nothing was invalidated; that search then reaches
	 * {@link #onOptimizerResult} moments later and installs its unowned
	 * result anyway, auto-applying the preview and arming the bank
	 * highlight. {@link #optimizerGeneration} closes that gap: it is bumped
	 * unconditionally on every OFF-&gt;ON transition (not gated on a result
	 * already existing), every search captures it at launch, and {@link
	 * #onOptimizerResult} is only ever reached for a captured value that
	 * still matches — see the call sites that capture {@code
	 * optimizerGeneration} (e.g. {@link #runOptimizer}).
	 */
	public void refreshIronmanOwnedOnlyMode()
	{
		boolean ownedOnly = ironmanOwnedOnlyPref();
		if (ownedOnly && !lastKnownIronmanOwnedOnlyPref)
		{
			optimizerGeneration++;
			if (lastOptimizerResult != null)
			{
				resetAllOverrides();
			}
		}
		lastKnownIronmanOwnedOnlyPref = ownedOnly;

		budgetColumn.setVisible(OwnedOnlyMode.upgradeUiVisible(ownedOnly));
		updateBudgetDisplay();
		setUpgradeStatRowsVisible(OwnedOnlyMode.upgradeStatRowsVisible(ownedOnly, lastOptimizerResult));
	}

	/**
	 * True if the optimiser's proposed loadout differs from the currently worn
	 * gear in at least one slot.
	 *
	 * <p><b>The comparison is against the RESOLVED id, not the raw choice.</b>
	 * When a mode-locked variant is already WORN rather than banked, the
	 * optimiser is forced to pick its credited plain counterpart (the variant
	 * itself is excluded from every search), and {@link
	 * #resolvedItemId} maps that straight back to the worn id. Comparing
	 * the raw choice would see live 29617 against choice 21791, call it a
	 * change, and report an upgrade that is really the item already on the
	 * player's back. Every live-vs-suggestion comparison — here, {@link
	 * #renderSwapList}'s skip and {@link
	 * #applyResultToOverride}'s — must therefore resolve first, or
	 * they disagree with what the panel actually shows.
	 */
	private boolean hasAnySlotChange(GearOptimizer.Result result)
	{
		int[] liveIds = lastGear == null ? new int[GearSnapshot.EQUIPMENT_SLOT_COUNT] : lastGear.equippedItemIds();
		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		java.util.Map<Integer, Long> ownedIds = ownedPriceMap();
		java.util.Set<Integer> heldIds = HeldItemIds.from(lastWealth, lastGear, index);
		for (GearOptimizer.SlotChoice choice : result.loadout())
		{
			int liveId = choice.slotOrdinal() < liveIds.length ? liveIds[choice.slotOrdinal()] : -1;
			if (liveId != resolvedItemId(index, choice, ownedIds, heldIds))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Renders "current item icon -&gt; suggested item icon" for every slot the
	 * optimiser actually wants to change (slots where the suggestion matches
	 * what's already worn are omitted — nothing to show there) — design ask:
	 * show the actual swaps, not just an aggregate "Best DPS found" number.
	 * Icons (not text names) so a swap reads at a glance, matching the
	 * worn-gear grid / item-picker's icon-first style; the slot + item names
	 * + spend move to the row's tooltip and a small caption underneath
	 * instead of inline text. Right-clicking the SUGGESTED icon offers
	 * "Exclude from suggestions" (item #6a).
	 */
	private void renderSwapList(GearOptimizer.Result result)
	{
		swapList.removeAll();
		int[] liveIds = lastGear == null ? new int[GearSnapshot.EQUIPMENT_SLOT_COUNT] : lastGear.equippedItemIds();
		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		// Item #9: an owned recommendation whose id is the optimiser's
		// variant-aware plain base form (see OwnedVariantResolver/
		// addVariantPlainForm) must still be SHOWN (and, via
		// resolvedItemId, actually APPLIED) as the actual owned
		// variant (e.g. "Masori mask (f)"), not the plain name — buildSwapRow
		// needs the owned-item pool to make that reverse lookup.
		java.util.Map<Integer, Long> ownedIds = ownedPriceMap();
		java.util.Set<Integer> heldIds = HeldItemIds.from(lastWealth, lastGear, index);
		boolean anyRow = false;
		for (GearOptimizer.SlotChoice choice : result.loadout())
		{
			// Resolve BEFORE comparing — see hasAnySlotChange: a worn mode-locked
			// variant resolves back to itself, and comparing the raw choice would
			// render a 29617 -> 29617 self-swap row.
			int resolvedId = resolvedItemId(index, choice, ownedIds, heldIds);
			int liveId = choice.slotOrdinal() < liveIds.length ? liveIds[choice.slotOrdinal()] : -1;
			if (liveId == resolvedId)
			{
				continue; // unchanged — nothing to report for this slot
			}
			anyRow = true;
			swapList.add(buildSwapRow(index, choice.slotOrdinal(), liveId, resolvedId, choice));
			swapList.add(Box.createRigidArea(new Dimension(0, 2)));
		}
		if (!anyRow)
		{
			JLabel none = PanelWidgets.emptyRowLabel("No slot changes — your current loadout is already best");
			none.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			swapList.add(none);
		}
	}

	/**
	 * Codex review finding #1 (P2, PR #5): the item id that must be used
	 * EVERYWHERE a {@link GearOptimizer.SlotChoice} reaches the user or
	 * drives further logic — the suggested-swap row's icon/name/exclude
	 * action, the applied what-if preview's gear-grid icon and DPS, and the
	 * bank highlight — so none of those can ever drift from each other. A
	 * not-owned choice (a genuine purchase) is never remapped: {@link
	 * #addVariantPlainForm} only ever marks the PLAIN id owned at price 0, so
	 * a not-owned suggestion is always exactly what the optimiser means to
	 * buy. An owned choice is resolved through {@link
	 * OwnedVariantResolver#preferOwnedVariant}, which also respects {@link
	 * #excludedItemIds} (Codex finding #2): if the player excluded their own
	 * owned variant, the plain id is shown/applied as-is rather than
	 * resurrecting the excluded item under a different row.
	 *
	 * <p><b>What "resolved" means when a mode-locked variant is the source of
	 * the credit</b> (issue #11 Stage 3; supersedes an earlier attempt that
	 * unioned {@link #restrictedItemIds()} into the never-substitute set).
	 * These two rules look like they conflict and do not:
	 * <ul>
	 *   <li>A mode-locked id ("(deadman)"/"(bh)"/"(lms)"/"(beta)") is never
	 *   an optimiser CANDIDATE — {@link #buildRequest} excludes
	 *   every one of them from every search regardless of ownership, and
	 *   {@code GearSectionGearPoolTest
	 *   #deadmanNamedItem_isNeverSuggestedByTheOptimizer} locks that in.
	 *   Nothing here weakens it: the optimiser still cannot pick, score, or
	 *   recommend one.</li>
	 *   <li>Once ownership of such a variant has CREDITED its plain
	 *   counterpart (the entire point of adding " (deadman)" to {@link
	 *   OwnedVariantResolver#SUFFIXES}), the display must name the item the
	 *   player actually holds. The credited plain id is not in their bank —
	 *   {@link #addVariantPlainForm} invented it at price 0 — so showing it
	 *   tells the player to equip something they do not own, and arms the
	 *   bank highlight on an id that cannot be there while missing the one
	 *   that is.</li>
	 * </ul>
	 * Blocking the substitution satisfied the first rule by breaking the
	 * second, which is the strictly worse trade: the recommendation stays
	 * correct either way (the ids are stat- and requirement-identical — that
	 * is what {@link OwnedVariantResolver} verifies before crediting at all),
	 * so the only thing at stake is whether the player is pointed at the
	 * right physical item. Credit and display must agree; if a mode-locked
	 * variant is not a usable stand-in it should never have been credited in
	 * the first place, and that decision lives in {@code SUFFIXES}, not here.
	 *
	 * <p>{@code heldItemIds} keeps the earlier fix's real kernel: a
	 * substitution only ever happens for a choice the player does NOT
	 * physically hold. If the optimiser picked an id that is genuinely in
	 * the bank or already worn, that id is returned untouched, so an owned
	 * plain form can never be swapped out for a mode-locked look-alike the
	 * player also happens to own. See {@link HeldItemIds} for why the
	 * ownership map alone cannot answer that.
	 */
	private int resolvedItemId(EquipmentIndexRepository index, GearOptimizer.SlotChoice choice,
		java.util.Map<Integer, Long> ownedIds, java.util.Set<Integer> heldItemIds)
	{
		if (!choice.owned() || heldItemIds.contains(choice.itemId()))
		{
			return choice.itemId();
		}
		return OwnedVariantResolver.preferOwnedVariant(index, choice.itemId(), ownedIds, excludedItemIds);
	}

	/**
	 * A8/item #5: clears {@link #swapList} for a style the optimiser
	 * found NO usable weapon for at all (owned or affordable), e.g. Magic
	 * selected against a monster with no owned/affordable magic weapon. The
	 * list (and its "Suggested swaps" heading) are hidden entirely in this
	 * state by {@link #setUpgradeStatRowsVisible} — {@link
	 * #noUsableWeaponLabel} is the single visible message now, so
	 * there is nothing left to render here beyond emptying the list.
	 */
	private void renderNoUsableWeaponSwapMessage(CombatStyle constraint)
	{
		swapList.removeAll();
	}

	/**
	 * P1-A fix: the explicit "cannot recommend" state {@link
	 * #onOptimizerResult} switches to when {@link
	 * OwnedOnlyMandatoryOverrideGate#blockingOverride} finds owned-only mode
	 * cannot satisfy a target's mandatory gear override, OR (P2-A half 1 fix)
	 * when {@link OwnedOnlyResultOwnershipGate} finds an ORDINARY resolved
	 * loadout id is no longer owned. Mirrors the pre-existing no-usable-weapon
	 * path exactly: the five upgrade stat rows and swap list hide, a single
	 * big error-coloured line (the caller-supplied {@code message}) takes
	 * their place, the bank highlight clears, and no what-if preview is
	 * applied — nothing from {@code result} is ever installed. Any PREVIOUS
	 * preview/override (e.g. from a different target searched just before
	 * this one) is dropped too, so a stale preview can never linger under a
	 * blocked message.
	 */
	private void renderOwnedOnlyBlockedState(String message)
	{
		lastOptimizerResult = null;
		override = LoadoutOverride.empty();
		statusLabel.setVisible(false);
		setOptimizerStyleRowVisible(false);
		setUpgradeStatRowsVisible(false);
		noUsableWeaponLabel.setVisible(false);
		swapList.removeAll();
		ownedOnlyBlockedLabel.setText(message);
		ownedOnlyBlockedLabel.setVisible(true);
		clearPreviewButton.setVisible(false);
		if (bankHighlighter != null)
		{
			bankHighlighter.clear();
		}
		resultPanel.setVisible(true);
		resultPanel.revalidate();
		body().revalidate();
		body().repaint();
		updateGearGrid(lastGear);
	}

	/**
	 * One "current icon -&gt; suggested icon (spend)" swap row — see
	 * {@link #renderSwapList}. {@code suggestedItemId} is already
	 * fully resolved by the caller (via {@link #resolvedItemId}) —
	 * this method renders it as-is rather than re-deriving it, so the icon,
	 * name, tooltip, and the right-click "Exclude from suggestions"/needs-
	 * protection actions all agree with each other and with whatever
	 * {@link #applyResultToOverride} actually applies for this slot
	 * (Codex review finding #1, PR #5): there is exactly one id in play.
	 */
	private JPanel buildSwapRow(EquipmentIndexRepository index, int slotOrdinal, int currentItemId,
		int suggestedItemId, GearOptimizer.SlotChoice choice)
	{
		String slotName = slotOrdinal >= 0 && slotOrdinal < SLOT_NAMES.length && !SLOT_NAMES[slotOrdinal].isEmpty()
			? SLOT_NAMES[slotOrdinal] : ("Slot " + slotOrdinal);
		String currentName = itemDisplayName(index, currentItemId);
		String suggestedName = itemDisplayName(index, suggestedItemId);
		String spend = choice.owned() ? "owned" : (formatGp(choice.price()) + " — not owned");

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel iconsPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
		iconsPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		iconsPanel.add(swapItemIcon(currentItemId, currentName));
		JLabel arrow = new JLabel("→"); // "->" glyph between the two item icons
		arrow.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		arrow.setFont(FontManager.getRunescapeSmallFont());
		arrow.setVerticalAlignment(SwingConstants.CENTER);
		iconsPanel.add(arrow);
		JLabel suggestedIcon = swapItemIcon(suggestedItemId, suggestedName + " (" + spend + ")");
		suggestedIcon.setComponentPopupMenu(buildExcludePopup(suggestedItemId, suggestedName, -1));
		if (lastOptimizerNeedsProtection.contains(suggestedItemId))
		{
			// Item #6/#6b follow-up: flag a recommended rare untradeable that
			// must be carried with a Trouver parchment (or lost outright on
			// death) — background tint (see NEEDS_PROTECTION_TINT's javadoc
			// for why not a border) + an exact, dedicated tooltip; the row's
			// own tooltip below already covers the name/slot/spend, so this
			// icon's tooltip is free to be single-purpose.
			suggestedIcon.setBackground(NEEDS_PROTECTION_TINT);
			suggestedIcon.setToolTipText(NEEDS_PROTECTION_TOOLTIP);
		}
		if (choice.owned())
		{
			iconsPanel.add(suggestedIcon);
		}
		else
		{
			// Item #6e rendering ask: a suggested item the player does NOT own
			// must be visually distinct from owned ones AND show its gp value
			// right by the item — gold border on the icon + a gold price label
			// directly beneath it (owned suggestions keep the plain icon).
			suggestedIcon.setBorder(BorderFactory.createLineBorder(NOT_OWNED_GOLD));
			JPanel notOwnedCell = new JPanel();
			notOwnedCell.setLayout(new BoxLayout(notOwnedCell, BoxLayout.Y_AXIS));
			notOwnedCell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			suggestedIcon.setAlignmentX(Component.CENTER_ALIGNMENT);
			notOwnedCell.add(suggestedIcon);
			JLabel price = new JLabel(formatGp(choice.price()));
			price.setName("notOwnedPrice"); // test hook + self-documenting component name
			price.setFont(FontManager.getRunescapeSmallFont());
			price.setForeground(NOT_OWNED_GOLD);
			price.setAlignmentX(Component.CENTER_ALIGNMENT);
			price.setToolTipText(suggestedName + " — not owned; GE price " + formatGp(choice.price()));
			notOwnedCell.add(price);
			iconsPanel.add(notOwnedCell);
		}
		row.add(iconsPanel, BorderLayout.WEST);

		JLabel caption = new JLabel(slotName + (choice.owned() ? " (owned)" : " (" + formatGp(choice.price()) + ")"));
		caption.setForeground(choice.owned() ? ColorScheme.MEDIUM_GRAY_COLOR : NOT_OWNED_GOLD);
		caption.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.ITALIC));
		caption.setHorizontalAlignment(SwingConstants.RIGHT);
		// Right inset keeps the "(52.6m)" / "(owned)" tail off the panel's right
		// edge — the side-panel scrollbar overlaps the last ~10px and was
		// clipping the caption's final characters; the small left inset gives it
		// breathing room from the WEST icons.
		caption.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 10));
		row.add(caption, BorderLayout.EAST);

		row.setToolTipText(slotName + ": " + currentName + " -> " + suggestedName + " (" + spend
			+ ") — right-click the suggested icon to exclude it from future suggestions");
		// Height is content-driven now: a not-owned suggestion adds a price
		// label under its icon, so the old fixed ITEM_GRID_CELL_SIZE cap would
		// clip it.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** One item-icon label for a swap row (see {@link #buildSwapRow}) — same async icon source as the worn-gear grid/item picker. */
	private JLabel swapItemIcon(int itemId, String tooltip)
	{
		JLabel icon = new JLabel();
		icon.setOpaque(true);
		icon.setBackground(ColorScheme.DARK_GRAY_COLOR);
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setVerticalAlignment(SwingConstants.CENTER);
		icon.setPreferredSize(new Dimension(ITEM_GRID_CELL_SIZE, ITEM_GRID_CELL_SIZE));
		icon.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		icon.setToolTipText(tooltip);
		if (itemManager != null && itemId > 0)
		{
			itemManager.getImage(itemId).addTo(icon);
		}
		return icon;
	}

	/**
	 * If {@code e} is a right-click/popup trigger over a slot cell currently
	 * SHOWING a real item (the previewed optimiser suggestion, a what-if swap,
	 * or live gear), pops the "Exclude from suggestions" menu for that item and
	 * returns {@code true}. The shown item id is read from {@link #renderedSlotIds}
	 * (what the cell last drew). Returns {@code false} for a non-popup click or
	 * an empty cell, so the caller falls through to the left-click swap search.
	 */
	private boolean maybeShowSlotExcludePopup(MouseEvent e, int slot)
	{
		if (!e.isPopupTrigger())
		{
			return false;
		}
		int shownId = slot >= 0 && slot < renderedSlotIds.length ? renderedSlotIds[slot] : -1;
		if (shownId <= 0)
		{
			return false;
		}
		String name = itemDisplayName(EquipmentIndexRepository.getInstance(), shownId);
		buildExcludePopup(shownId, name, slot).show(e.getComponent(), e.getX(), e.getY());
		return true;
	}

	/**
	 * Right-click menu for a suggested-swap icon (item #6a): an "Exclude from
	 * suggestions" action, plus — for the WEAPON slot showing a blowpipe (see
	 * {@link GearVariants#isBlowpipe}) — a nested "Set darts" submenu (see
	 * {@link #populateBlowpipeDartSubmenu}) letting the loaded dart be picked
	 * by right-click instead of the (now-hidden) settings-panel dropdown.
	 */
	private javax.swing.JPopupMenu buildExcludePopup(int itemId, String itemName, int slot)
	{
		javax.swing.JPopupMenu menu = new javax.swing.JPopupMenu();
		javax.swing.JMenuItem exclude = new javax.swing.JMenuItem("Exclude " + itemName + " from suggestions");
		exclude.addActionListener(e -> excludeFromSuggestions(itemId));
		menu.add(exclude);

		if (slot == WhatIfLoadout.WEAPON_SLOT && GearVariants.isBlowpipe(itemId))
		{
			javax.swing.JMenu dartsMenu = new javax.swing.JMenu("Set darts");
			populateBlowpipeDartSubmenu(dartsMenu);
			menu.add(dartsMenu);
		}
		return menu;
	}

	/**
	 * Fills {@code menu} with one item per {@link BlowpipeDart}, the currently
	 * selected one shown checked (see {@link #currentBlowpipeDart}). Picking a
	 * dart persists it and re-ranks (see {@link #pickBlowpipeDart}). Built as a
	 * nested {@link javax.swing.JMenu} added straight to the popup — NOT a
	 * second {@link javax.swing.JPopupMenu} shown manually via {@code
	 * menu.show(...)}, since clicking the parent item hides its popup first and
	 * {@code invoker.getLocationOnScreen()} then throws {@code
	 * IllegalComponentStateException} (the exact bug a manual second popup hit
	 * elsewhere in this project) — a nested JMenu cascades natively instead.
	 */
	private void populateBlowpipeDartSubmenu(javax.swing.JMenu menu)
	{
		BlowpipeDart current = currentBlowpipeDart();
		for (BlowpipeDart dart : BlowpipeDart.values())
		{
			javax.swing.JCheckBoxMenuItem item = new javax.swing.JCheckBoxMenuItem(dart.toString());
			item.setState(dart == current);
			item.addActionListener(e -> pickBlowpipeDart(dart));
			menu.add(item);
		}
	}

	/** Display name for an item id via the bundled equipment index, or a placeholder for an empty/unindexed slot. */
	private static String itemDisplayName(EquipmentIndexRepository index, int itemId)
	{
		if (itemId <= 0)
		{
			return "(empty)";
		}
		EquipmentIndexRepository.Entry entry = index.entryFor(itemId);
		return entry != null ? entry.name() : ("item " + itemId);
	}

	/** "1.2m" / "350k" / "0" — compact gp formatting for the spend readout. */
	private static String formatGp(long gp)
	{
		if (gp >= 1_000_000)
		{
			return String.format(Locale.ROOT, "%.1fm", gp / 1_000_000.0);
		}
		if (gp >= 1_000)
		{
			return String.format(Locale.ROOT, "%.0fk", gp / 1000.0);
		}
		return String.valueOf(gp);
	}

	/**
	 * Loads the last optimizer result into the what-if overrides (design
	 * spec's "apply to readout" handoff) — every slot the result touches
	 * becomes a {@link LoadoutOverride}, so the existing Phase 2 readout
	 * (styles/spells ranking, DPS/TTK/etc, delta-vs-worn-gear row) picks it up
	 * unchanged. Real gear is never touched.
	 */
	private void applyResultToOverride()
	{
		if (lastOptimizerResult == null)
		{
			return;
		}
		// Only override slots that actually differ from the currently worn gear
		// — the optimiser's loadout() lists every equipped slot, but "Preview
		// these swaps" must only highlight genuinely-changed slots (mirrors the
		// guard in renderSwapList / hasAnySlotChange).
		int[] liveIds = lastGear == null ? new int[GearSnapshot.EQUIPMENT_SLOT_COUNT] : lastGear.equippedItemIds();
		// Codex review finding #1 (PR #5): every slot goes through the SAME
		// resolvedItemId as the suggested-swaps row, so the preview
		// grid/DPS/bank-highlight this produces can never show a different
		// item than the row the user actually clicked "Apply" on.
		EquipmentIndexRepository index = EquipmentIndexRepository.getInstance();
		java.util.Map<Integer, Long> ownedIds = ownedPriceMap();
		java.util.Set<Integer> heldIds = HeldItemIds.from(lastWealth, lastGear, index);
		LoadoutOverride next = LoadoutOverride.empty();
		for (GearOptimizer.SlotChoice choice : lastOptimizerResult.loadout())
		{
			// Resolve BEFORE comparing — see hasAnySlotChange: a worn mode-locked
			// variant resolves back to itself, and comparing the raw choice would
			// preview a redundant override of the item already equipped.
			int resolvedId = resolvedItemId(index, choice, ownedIds, heldIds);
			int liveId = choice.slotOrdinal() < liveIds.length ? liveIds[choice.slotOrdinal()] : -1;
			if (liveId == resolvedId)
			{
				continue; // unchanged — nothing to preview for this slot
			}
			next = next.withSlot(choice.slotOrdinal(), resolvedId);
		}
		// B9-3: a two-handed weapon frees the shield slot. The optimiser empties
		// the shield internally, but empty slots aren't listed in loadout(), so
		// the loop above never overrides the shield — leaving the live shield
		// (e.g. an Avernic defender) lingering in the preview beside a 2H weapon
		// (e.g. a Scorching bow). Explicitly empty it when the recommended weapon
		// is two-handed.
		int previewWeaponId = loadoutSlotMap(lastOptimizerResult)
			.getOrDefault(WhatIfLoadout.WEAPON_SLOT, -1);
		if (previewWeaponId > 0 && WhatIfLoadout.isTwoHanded(previewWeaponId))
		{
			next = next.withEmptiedSlot(WhatIfLoadout.SHIELD_SLOT);
		}
		override = next;
		// B8-6: don't reset the bank filter on every preview — if it's already
		// armed (Show in bank ticked), refresh it to this preview's items so
		// switching styles (each re-runs the optimiser -> onOptimizerResult ->
		// this method) live-updates the highlighted bank items instead of
		// silently dropping the filter.
		if (bankHighlighter != null && bankHighlighter.isArmed() && lastOptimizerResult != null)
		{
			bankHighlighter.showInBank(loadoutSlotMap(lastOptimizerResult), bankConsumableIds());
		}

		// Item #6g: the preview must show the DPS the optimiser actually
		// computed — i.e. lock the readout to the RESULT's style/spell instead
		// of letting rankAndRender re-default to the new weapon's best-of-any-
		// style (which could flip a Ranged/Magic-constrained preview to melee).
		// Pre-setting lastRankedWeaponId suppresses the weapon-change auto-reset
		// of these locks (and of the 5-way selector's user pick) for this
		// deliberate, style-aware swap.
		lastRankedWeaponId = effectiveWeaponId();
		if (lastOptimizerResult.style() != null)
		{
			selectedStyle = lastOptimizerResult.style();
			userPickedStyle = true;
		}
		if (lastOptimizerResult.spell() != null)
		{
			selectedSpell = lastOptimizerResult.spell();
			userPickedSpell = true;
			selectedBook = lastOptimizerResult.spell().book() == Spell.SpellBook.ANCIENT
				? BookTab.ANCIENT : BookTab.STANDARD;
			lastRankedTarget = selectedMonster; // keep the spell lock through the re-rank
		}

		updateGearGrid(lastGear);
		rankAndRender();
	}

	// ------------------------------------------------------------- compute

	@Override
	public void apply(SessionSnapshot snapshot)
	{
		lastGear = snapshot.getGear();
		lastWealth = snapshot.getWealth();
		autoToggleSlayerFromGear();
		invalidateStaleOwnedOnlyResult();
		// Finding 4 fix: re-rank before regridding — see applyOverride()'s
		// comment. Matters here too: a live gear change (e.g. the player
		// swaps weapon in-game) must not leave a newly-valid weapon crossed
		// out against the STALE style from before this snapshot.
		rankAndRender();
		updateGearGrid(lastGear);
		refreshSummary();
	}

	/**
	 * P2-A fix (half 2, Codex finding on PR #19, {@code
	 * GearSection.java:4789}, "Revalidate every recommended item against
	 * current ownership"): {@code apply(SessionSnapshot)} above refreshes
	 * {@link #lastWealth} on every wealth snapshot without ever re-checking
	 * whatever owned-only result is currently installed — a result that WAS
	 * fully owned when {@link #onOptimizerResult} installed it (see that
	 * method's own P2-A half-1 check) can still go stale afterwards if the
	 * player then drops, sells, or otherwise loses one of its items, and
	 * nothing was clearing it: {@code lastWealth} just silently moved on
	 * underneath a preview/bank-highlight the mode's guarantee says must
	 * never point at an unowned item.
	 *
	 * <p>Deliberately a TARGETED check, not a blanket invalidate on every
	 * call: wealth snapshots arrive frequently (any gear/inventory/bank
	 * change), so unconditionally clearing {@link #lastOptimizerResult} here
	 * would flicker the panel and throw away still-valid results on every
	 * unrelated update. Only actually invalidate when a resolved loadout id
	 * of the CURRENTLY installed result is no longer owned — otherwise a
	 * no-op, same as every other {@code apply()} call.
	 *
	 * <p>Reuses {@link #resetAllOverrides()} — the same "revert to worn gear"
	 * path {@link #refreshIronmanOwnedOnlyMode()} already uses on its
	 * OFF-&gt;ON transition — rather than re-rendering a blocked message: this
	 * fires mid-session behind a routine wealth update, not a user-initiated
	 * search, so silently falling back to the player's real worn gear (what
	 * they're actually equipped with right now) is the least surprising
	 * outcome, exactly like the OFF-&gt;ON case.
	 */
	private void invalidateStaleOwnedOnlyResult()
	{
		if (lastOptimizerResult == null || !ironmanOwnedOnlyPref())
		{
			return;
		}
		if (OwnedOnlyResultOwnershipGate.firstUnownedEntry(true,
			loadoutSlotMap(lastOptimizerResult), ownedPriceMap().keySet()).isPresent())
		{
			resetAllOverrides();
		}
	}

	/**
	 * Auto-ticks "On Slayer task" when the player puts on a slayer helmet /
	 * black mask (any variant), and auto-unticks it when the headgear comes
	 * off. Edge-triggered: it only acts when the worn-state actually flips, so
	 * a manual untick while the helm is still worn is respected (the common
	 * "wearing the helm but off-task" case). Detection uses the client-thread-
	 * computed {@link GearSnapshot#equipmentStats()} — {@code slayerHeadgear()}
	 * is already resolved there, so no {@code Client}/{@code ItemManager} lookup
	 * happens on the EDT. The slayer bonus only applies while the headgear is
	 * worn anyway, so this keeps the toggle honest by default.
	 */
	private void autoToggleSlayerFromGear()
	{
		boolean worn = lastGear != null
			&& lastGear.equipmentStats() != null
			&& lastGear.equipmentStats().slayerHeadgear().wornAtAll();
		if (worn != lastSlayerHeadgearWorn)
		{
			lastSlayerHeadgearWorn = worn;
			onSlayerTaskToggle.setSelected(worn); // fires ItemListener -> rankAndRender + restyle
		}
	}

	/** Updates the max hit / accuracy / DPS readout for the currently selected style. */
	private void updateOutputs()
	{
		DpsResult result = computeFor(selectedStyle);
		if (result == null)
		{
			clearOutputs();
			return;
		}

		maxHitValue.setText(String.valueOf(result.maxHit()));
		accuracyValue.setText(CentFormat.html(String.format(Locale.ROOT, "%.1f%%", result.accuracy() * 100.0)));
		avgHitValue.setText(CentFormat.html(String.format(Locale.ROOT, "%.2f", result.avgHit())));
		lastDps = result.dps();
		dpsValue.setText(DpsFormat.html(lastDps));
		ttkValue.setText(CentFormat.html(formatTtk(result.ttkSeconds())));
		overkillValue.setText(CentFormat.html(String.format(Locale.ROOT, "%.1f", result.overkillPerKill())));
		baseEstimateNote.setVisible(result.baseEstimate());
		updateBoostIndicators(selectedStyle != null ? selectedStyle.type() : null);
		updateWhatIfDelta();

		refreshSummary();
	}

	private void clearOutputs()
	{
		maxHitValue.setText("-");
		accuracyValue.setText("-");
		avgHitValue.setText("-");
		dpsValue.setText("-");
		ttkValue.setText("-");
		overkillValue.setText("-");
		baseEstimateNote.setVisible(false);
		lastDps = 0.0;
		// DPS itself isn't computable without a target (that's why we're here),
		// but the boost indicators (prayer/potion) are purely a function of the
		// EQUIPPED weapon's own best style, which rankAndRender() already
		// resolved into selectedStyle regardless of target — so still refresh
		// them here instead of blanking them, letting the potion icon track a
		// weapon swap even with no monster picked yet.
		updateBoostIndicators(selectedStyle != null ? selectedStyle.type() : null);
		whatIfRow.setVisible(false);
		resetAllButton.setVisible(!override.isEmpty());
	}

	/** Formats a time-to-kill (seconds) as "12.3s" or "1:05" for a minute or more; "-" when non-positive. */
	private static String formatTtk(double ttkSeconds)
	{
		if (ttkSeconds <= 0 || Double.isInfinite(ttkSeconds) || Double.isNaN(ttkSeconds))
		{
			return "-";
		}
		if (ttkSeconds < 60)
		{
			return String.format(Locale.ROOT, "%.1fs", ttkSeconds);
		}
		int total = (int) Math.round(ttkSeconds);
		return String.format(Locale.ROOT, "%d:%02d", total / 60, total % 60);
	}

	@Override
	protected String summaryText()
	{
		if (selectedMonster == null)
		{
			return "no target";
		}
		return "DPS " + String.format(Locale.ROOT, "%.2f", lastDps);
	}

	// ------------------------------------------------------- icon controls

	/**
	 * An icon-toggle button that can paint a small "*" in its top-right corner
	 * as a "more options on right-click" hint (see {@link #setRightClickHint}) —
	 * used by the potion (and, if it ever gains options, prayer) boost toggle
	 * so the right-click swap menu is discoverable instead of hidden.
	 */
	private static final class HintableToggleButton extends JToggleButton
	{
		private boolean rightClickHint;

		void setRightClickHint(boolean hint)
		{
			if (hint != rightClickHint)
			{
				rightClickHint = hint;
				repaint();
			}
		}

		@Override
		protected void paintComponent(java.awt.Graphics g)
		{
			super.paintComponent(g);
			if (!rightClickHint)
			{
				return;
			}
			java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
					java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setColor(ColorScheme.BRAND_ORANGE);
				Font markerFont = FontManager.getRunescapeBoldFont().deriveFont(11f);
				g2.setFont(markerFont);
				String marker = "*";
				java.awt.FontMetrics fm = g2.getFontMetrics();
				int x = getWidth() - fm.stringWidth(marker) - 2;
				int y = fm.getAscent();
				// A thin dark outline keeps the marker legible over a bright item icon.
				g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
				g2.drawString(marker, x - 1, y);
				g2.drawString(marker, x + 1, y);
				g2.setColor(ColorScheme.BRAND_ORANGE);
				g2.drawString(marker, x, y);
			}
			finally
			{
				g2.dispose();
			}
		}
	}

	/** Bare icon-toggle button (border/background styling, no icon yet). */
	private HintableToggleButton newToggle(String tooltip)
	{
		HintableToggleButton button = new HintableToggleButton();
		button.setToolTipText(tooltip);
		button.setFocusPainted(false);
		button.setMargin(new Insets(0, 0, 0, 0));
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setPreferredSize(new Dimension(40, SLOT_H));

		Border selectedBorder = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE);
		Border unselectedBorder = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR);
		Runnable restyle = () ->
		{
			button.setBorder(button.isSelected() ? selectedBorder : unselectedBorder);
			button.setBackground(button.isSelected()
				? ColorScheme.MEDIUM_GRAY_COLOR
				: ColorScheme.DARKER_GRAY_COLOR);
		};
		restyle.run();
		button.addItemListener(e -> restyle.run());
		return button;
	}

	/**
	 * An icon-only toggle button whose sprite loads via the async, EDT-safe
	 * {@code ItemManager.getImage(int)}.
	 */
	private HintableToggleButton iconToggle(int itemId, String tooltip)
	{
		HintableToggleButton button = newToggle(tooltip);
		if (itemManager != null)
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			button.setIcon(new ImageIcon(image));
			image.onLoaded(() ->
			{
				button.setIcon(new ImageIcon(image));
				button.repaint();
			});
		}
		return button;
	}

	/**
	 * Builds a right-click swap menu that rebuilds its items from {@code
	 * populate} on every open (via the {@code PopupMenuListener} below), so it
	 * always reflects whatever combat style is CURRENTLY selected rather than
	 * whatever it happened to show last time it was opened. Shared scaffold
	 * for both {@link #buildPotionVariantPopup} and {@link
	 * #buildPrayerVariantPopup} — they differ only in which style-keyed map
	 * a pick writes into.
	 */
	private javax.swing.JPopupMenu buildVariantPopup(java.util.function.Consumer<javax.swing.JPopupMenu> populate)
	{
		javax.swing.JPopupMenu menu = new javax.swing.JPopupMenu();
		menu.addPopupMenuListener(new javax.swing.event.PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent e)
			{
				populate.accept(menu);
			}

			@Override
			public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent e)
			{
			}

