		CombatStyle style = selectedStyle != null ? selectedStyle.type() : null;
		String styleKey = styleKeyFor(style);
		OffensivePrayer[] variants = CombatIcons.prayerVariantsFor(style);
		for (OffensivePrayer variant : variants)
