/**
 * Loot feed: a "Loot Tracker"-style list grouped by source (boss/NPC/activity),
 * each source header itself collapsible. Collapsed section summary shows total
 * loot value.
 *
 * <p>Each source header carries an XP-Tracker-style right-click menu (see
 * {@code com.ospulse.ui.category.CategoryContextMenu}, ported from RuneLite's
 * XP Tracker plugin). Loot sources are aggregated by the single {@code
 * SessionEngine} accumulator rather than each having independent state, so
 * "Reset"/"Reset others"/"Reset all" here hide the source(s) from this
 * section's display (a UI-level filter) rather than clearing any
 * engine-level totals; "Pause" freezes a source's row at its last-seen
 * figures instead of stopping the engine from tallying new loot from it.
 */
public final class LootSection extends CollapsibleSection
{
	public static final String KEY = "loot";
	private static final int LOOT_ROW_CAP = 30;
	private static final int ICON_GRID_COLUMNS = 5;

	private final OSPulseConfig config;
	private final ItemManager itemManager;
	private final CategorySectionSupport categorySupport;

	private final JLabel totalValue;
	private final JPanel lootListPanel;

	/** Latest source-grouped loot, retained so header clicks can re-render. */
	private List<SourceLoot> lastLootSources = List.of();
	/** Sources the user has collapsed (by name); persists across updates. */
	private final Set<String> collapsedSources = new HashSet<>();
	/** Sources hidden via "Reset"/"Reset others"/"Reset all" (by category id). */
	private final Set<String> hiddenSources = new HashSet<>();
	/**
	 * Last-seen SourceLoot per category id, retained so a paused row keeps
	 * showing its frozen figures. ConcurrentHashMap because the canvas overlay's
	 * line supplier reads this on the CLIENT (render) thread while section
	 * rebuilds mutate it on the EDT — a plain HashMap can corrupt / CME under
	 * that concurrent get/put.
	 */
	private final Map<String, SourceLoot> lastSeenBySource = new ConcurrentHashMap<>();
	/**
	 * "Hide item" / "Hide loot" state: persistent hides distinct from {@link
	 * #hiddenSources}' reset-until-next-pickup semantics. See {@link
	 * LootHiddenState} javadoc.
	 */
	private final LootHiddenState hiddenState = new LootHiddenState();

	/**
	 * Whether the grayed "hidden items" tray is revealed at the bottom of the
	 * feed. Toggled by a source menu's "View hidden items" — a clickable toggle
	 * rather than a submenu list, so restoring an item is a single ✕ click on
	 * its grayed icon.
	 */
	private boolean showHiddenTray = false;
	/**
	 * Signature of the last rendered feed. A matching signature short-circuits
	 * {@link #rebuild} so an idle snapshot (identical loot) doesn't tear down
	 * and recreate every cell under the mouse — which previously made a hovered
	 * tooltip flicker/regenerate and often fail to appear at all.
	 */
	private String lastRenderSignature = null;

	private long total;

	public LootSection(CollapseStore store, OSPulseConfig config, ItemManager itemManager,
		Plugin plugin, Client client, OverlayManager overlayManager)
	{
		super(KEY, "Loot feed", store);
		this.config = config;
		this.itemManager = itemManager;
		this.categorySupport = new CategorySectionSupport(plugin, client, overlayManager);

		totalValue = PanelWidgets.statRow(body(), "Total value");
		lootListPanel = new JPanel();
		lootListPanel.setLayout(new javax.swing.BoxLayout(lootListPanel, javax.swing.BoxLayout.Y_AXIS));
		lootListPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		lootListPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		body().add(lootListPanel);
	}

	private static String categoryId(String source)
	{
		return "loot:" + source;
	}

	/** Reset-epoch last observed per category id, so a "Reset" click is detected exactly once. */
	private final Map<String, Integer> lastSeenEpoch = new HashMap<>();

	@Override
	public void apply(SessionSnapshot snapshot)
	{
		List<SourceLoot> sources = snapshot.getLootSources();
		for (SourceLoot src : sources == null ? List.<SourceLoot>of() : sources)
		{
			String catId = categoryId(src.getSource());
			detectReset(catId);
			if (!categorySupport.controller().isPaused(catId))
			{
				lastSeenBySource.put(catId, src);
			}
			// Register/refresh the canvas line supplier for this source
			// every apply, since sources can appear mid-session (XP Tracker
			// instead pre-registers one per Skill; loot sources are dynamic,
			// so we lazily register here).
			categorySupport.setLinesSupplier(catId, () -> canvasLines(catId));
		}
		rebuild(sources);
	}

	/** Marks {@code catId} hidden the moment its reset epoch advances (a "Reset"/"Reset others"/"Reset all" click). */
	private void detectReset(String catId)
	{
		int epoch = categorySupport.controller().resetEpoch(catId);
		Integer lastEpoch = lastSeenEpoch.get(catId);
		if (lastEpoch == null)
		{
			lastSeenEpoch.put(catId, epoch);
			return;
		}
		if (epoch != lastEpoch)
		{
			hiddenSources.add(catId);
			lastSeenEpoch.put(catId, epoch);
		}
	}

	/** Re-applies the latest known sources, e.g. after a collapse-toggle click that doesn't change reset/pause state. */
	private void applyResetsThenRebuild()
	{
		rebuild(lastLootSources);
	}

	private List<CategoryOverlay.Line> canvasLines(String catId)
	{
		SourceLoot src = lastSeenBySource.get(catId);
		if (src == null)
		{
			return List.of();
		}
		return List.of(new CategoryOverlay.Line("Value", GpFormat.format(src.getTotalValue())));
	}

	/** One source's resolved display model for a render pass (post source/item hides). */
	private static final class DisplaySource
	{
		final SourceLoot src;
		final long shownValue;
		final boolean collapsed;

		DisplaySource(SourceLoot src, long shownValue, boolean collapsed)
		{
			this.src = src;
			this.shownValue = shownValue;
			this.collapsed = collapsed;
		}
	}

	private void rebuild(List<SourceLoot> sources)
	{
		lastLootSources = sources == null ? List.of() : sources;

		// Tolerate a null config the same way the pre-two-pass render did (it
		// only read config inside the non-empty branch) — some section tests
		// construct the feed without one.
		int minLootValue = config != null ? config.minLootValue() : 0;

		// ---- Pass 1: resolve the display model + a render signature WITHOUT
		// touching Swing. Paused sources are frozen at their last-seen figures;
		// reset/manually-hidden sources are dropped. Per-item "Hide item" hides
		// are subtracted from BOTH the grid and the value, so hiding an item
		// recalculates the loot value rather than only removing its icon.
		List<DisplaySource> display = new ArrayList<>();
		long newTotal = 0L;
		StringBuilder sig = new StringBuilder("min=").append(minLootValue)
			.append(";tray=").append(showHiddenTray).append(';');
		for (SourceLoot src : lastLootSources)
		{
			String source = src.getSource();
			String catId = categoryId(source);
			if (hiddenSources.contains(catId) || hiddenState.isSourceHidden(catId))
			{
				continue;
			}
			SourceLoot toShow = categorySupport.controller().isPaused(catId)
				? lastSeenBySource.getOrDefault(catId, src)
				: src;

			long hiddenValue = 0L;
			for (ItemStack item : toShow.getItems())
			{
				if (hiddenState.isItemFiltered(item))
				{
					hiddenValue += item.value();
				}
			}
			long shownValue = toShow.getTotalValue() - hiddenValue;
			boolean collapsed = collapsedSources.contains(source);

			display.add(new DisplaySource(toShow, shownValue, collapsed));
			newTotal += shownValue;

			sig.append(source).append('#').append(toShow.getCount())
				.append('|').append(shownValue).append('|').append(collapsed ? 'C' : 'E').append('|');
			if (!collapsed)
			{
				for (ItemStack item : toShow.getItems())
				{
					if (item.value() < minLootValue || hiddenState.isItemFiltered(item))
					{
						continue;
					}
					sig.append(item.getId()).append('x').append(item.getQuantity())
						.append('=').append(item.value()).append(',');
				}
			}
			sig.append(';');
		}
		if (showHiddenTray)
		{
			sig.append("hiddenItems=").append(hiddenState.hiddenItems().keySet())
				.append(";hiddenSrc=").append(hiddenState.hiddenSources().keySet());
		}

		// ---- Short-circuit: nothing visible changed, so leave the existing
		// components (and any hovered tooltip) exactly as they are.
		String signature = sig.toString();
		if (signature.equals(lastRenderSignature))
		{
			return;
		}
		lastRenderSignature = signature;

		// ---- Pass 2: render.
		total = newTotal;
		totalValue.setText(GpFormat.format(total));
		lootListPanel.removeAll();

		boolean trayHasContent = showHiddenTray && !hiddenState.isEmpty();
		if (display.isEmpty() && !trayHasContent)
		{
			lootListPanel.add(PanelWidgets.emptyRowLabel("No loot yet."));
		}
		else
		{
			for (DisplaySource ds : display)
			{
				lootListPanel.add(sourceHeaderRow(ds.src, ds.shownValue));
				if (ds.collapsed)
				{
					continue;
				}

				JPanel grid = new JPanel(new GridLayout(0, ICON_GRID_COLUMNS, 2, 2));
				grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				grid.setAlignmentX(Component.LEFT_ALIGNMENT);

				int shown = 0;
				for (ItemStack item : ds.src.getItems())
				{
					if (item.value() < minLootValue || hiddenState.isItemFiltered(item))
					{
						continue;
					}
					grid.add(iconCell(item));
					shown++;
					if (shown >= LOOT_ROW_CAP)
					{
						break;
					}
				}

				if (shown > 0)
				{
					// Don't let BoxLayout stretch the grid to fill leftover
					// vertical space (which would stretch every cell with it).
					grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, grid.getPreferredSize().height));
					lootListPanel.add(grid);
				}
			}

			if (showHiddenTray)
			{
				appendHiddenTray();
			}
		}

		lootListPanel.revalidate();
		lootListPanel.repaint();
		refreshSummary();
	}

	/**
	 * A single loot-tracker-style icon cell: just the item sprite with its
	 * stack quantity overlaid (RuneLite draws the overlay for us via
	 * {@link ItemManager#getImage(int, int, boolean)}). Full details (name,
	 * quantity, GE value, and HA value where available) show as a tooltip on
	 * hover, since the icon alone has no room for them.
	 */
	private JLabel iconCell(ItemStack item)
	{
		JLabel icon = new JLabel();
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setVerticalAlignment(SwingConstants.CENTER);

		if (itemManager != null && item.getId() > 0)
		{
			int quantity = (int) item.getQuantity();
			itemManager.getImage(item.getId(), quantity, quantity > 1).addTo(icon);
		}

		// Format: "[ITEM NAME] x [qty]" / "GE: total (each ea)" / "HA: total (each ea)".
		long qty = item.getQuantity();
		StringBuilder tooltip = new StringBuilder("<html><b>")
			.append(item.getName())
			.append("</b> x ")
			.append(String.format("%,d", qty))
			.append("<br>GE: ")
			.append(GpFormat.format(item.value()))
			.append(" (").append(GpFormat.format(item.getUnitValue())).append(" ea)");

		// HA price is precomputed on the client thread (see SessionTracker.mergeItem);
		// -1 means it couldn't be resolved. Never call getItemComposition here — this
		// runs on the EDT and that method asserts the client thread.
		if (item.getHaPrice() >= 0)
		{
			long haEach = item.getHaPrice();
			tooltip.append("<br>HA: ").append(GpFormat.format(haEach * qty))
				.append(" (").append(GpFormat.format(haEach)).append(" ea)");
		}
		tooltip.append("</html>");
		icon.setToolTipText(tooltip.toString());

		icon.setComponentPopupMenu(buildItemMenu(item));

		return icon;
	}

	/** Right-click menu for a single item cell: just "Hide item". */
	private JPopupMenu buildItemMenu(ItemStack item)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));

		JMenuItem hideItem = new JMenuItem("Hide item");
		hideItem.addActionListener(e ->
		{
			hiddenState.hideItem(item);
			applyResetsThenRebuild();
		});
		menu.add(hideItem);

		return menu;
	}

	/**
	 * A clickable collapsible header for one loot source, e.g.
	 * "▾ Cerberus x206 … 24m". Clicking toggles the source's expanded state.
	 */
	private JPanel sourceHeaderRow(SourceLoot src, long shownValue)
	{
		boolean collapsed = collapsedSources.contains(src.getSource());
		String triangle = collapsed ? "▸" : "▾";
		String left = triangle + " " + src.getSource()
			+ (src.getCount() > 1 ? " x" + String.format("%,d", src.getCount()) : "");

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(3, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		JLabel leftLabel = new JLabel(left);
		leftLabel.setForeground(ColorScheme.BRAND_ORANGE);
		leftLabel.setFont(FontManager.getRunescapeSmallFont());

		// Value shown excludes any per-item "Hide item" hides in this source.
		JLabel rightLabel = new JLabel(GpFormat.format(shownValue));
		rightLabel.setForeground(Color.WHITE);
		rightLabel.setFont(FontManager.getRunescapeSmallFont());
		rightLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		row.add(leftLabel, BorderLayout.CENTER);
		row.add(rightLabel, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));

		final String source = src.getSource();
		final String catId = categoryId(source);

		JPopupMenu popupMenu = buildSourceMenu(catId, source);
		row.setComponentPopupMenu(popupMenu);
		leftLabel.setComponentPopupMenu(popupMenu);
		rightLabel.setComponentPopupMenu(popupMenu);

		// Attach the collapse toggle to the labels as well as the row: the
		// labels fill the whole header (BorderLayout CENTER/EAST) and, because
		// they carry a component popup menu, Swing delivers their mouse events
		// to them rather than bubbling to the parent row — so a listener only on
		// `row` never fires on a click over the label text (that was the "can't
		// minimize" regression). Mirror the popup-menu attachment: all three.
		MouseAdapter collapseToggle = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				// Right-click (popup trigger) opens the context menu instead
				// of toggling collapse - matches XpInfoBox, where the
				// right-click menu and left-click collapse toggle coexist on
				// the same component.
				if (e.isPopupTrigger() || javax.swing.SwingUtilities.isRightMouseButton(e))
				{
					return;
				}
				if (!collapsedSources.remove(source))
				{
					collapsedSources.add(source);
				}
				applyResetsThenRebuild();
			}
		};
		row.addMouseListener(collapseToggle);
		leftLabel.addMouseListener(collapseToggle);
		rightLabel.addMouseListener(collapseToggle);
		return row;
	}

	/**
	 * Loot-tailored right-click menu for a source header: "Hide loot",
	 * "Reset", "View hidden items", and "Add to canvas"/"Remove from
	 * canvas". Deliberately does not reuse {@code categorySupport.buildMenu}
	 * (the generic XP-Tracker-style menu) since "Open Wise Old Man", "Reset
	 * others", "Reset all" and "Pause" don't fit a loot source.
	 */
	private JPopupMenu buildSourceMenu(String catId, String source)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));

		JMenuItem hideLoot = new JMenuItem("Hide loot");
		hideLoot.addActionListener(e ->
		{
			hiddenState.hideSource(catId, source);
			applyResetsThenRebuild();
		});
		menu.add(hideLoot);

		JMenuItem reset = new JMenuItem("Reset");
		reset.addActionListener(e -> categorySupport.controller().reset(catId, System.currentTimeMillis()));
		menu.add(reset);

		// A clickable toggle (not a submenu list): reveals/hides the grayed
		// "hidden items" tray at the bottom of the feed, where each hidden item
		// is a grayed icon carrying a ✕ that adds it straight back to the feed.
		JMenuItem viewHidden = new JMenuItem(showHiddenTray ? "Hide hidden items" : "View hidden items");
		viewHidden.addActionListener(e ->
		{
			showHiddenTray = !showHiddenTray;
			applyResetsThenRebuild();
		});
		menu.add(viewHidden);

		JMenuItem canvas = new JMenuItem(
			categorySupport.controller().isOnCanvas(catId) ? "Remove from canvas" : "Add to canvas");
		canvas.addActionListener(e ->
			categorySupport.controller().setOnCanvas(catId, !categorySupport.controller().isOnCanvas(catId)));
		menu.add(canvas);

		menu.addPopupMenuListener(new javax.swing.event.PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent e)
			{
				canvas.setText(categorySupport.controller().isOnCanvas(catId)
					? "Remove from canvas" : "Add to canvas");
			}

			@Override
			public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent e)
			{
			}

			@Override
			public void popupMenuCanceled(javax.swing.event.PopupMenuEvent e)
			{
			}
		});

		return menu;
	}

	/** RuneLite item sprite footprint; the grayed tray cells are sized to it. */
	private static final int ITEM_SPRITE_W = 36;
	private static final int ITEM_SPRITE_H = 32;

	/**
	 * Appends the grayed "hidden items" tray to the bottom of the feed: one
	 * grayed icon per "Hide item" hide (a top-right ✕ adds it straight back to
	 * the feed) plus a ✕ chip per "Hide loot" source hide. Shown only while
	 * {@link #showHiddenTray} is on (toggled from a source's "View hidden
	 * items"). Item names are the retained last-seen names from {@link
	 * LootHiddenState} — never re-resolved via {@code
	 * ItemManager#getItemComposition}, which asserts the client thread (see the
	 * warning in {@link #iconCell}).
	 */
	private void appendHiddenTray()
	{
		JLabel heading = PanelWidgets.emptyRowLabel("Hidden items");
		heading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		heading.setToolTipText("Items hidden from the feed — click a ✕ to add one back");
		heading.setBorder(new EmptyBorder(4, 0, 1, 0));
		lootListPanel.add(heading);

		Map<Integer, String> items = hiddenState.hiddenItems();
		Map<String, String> srcs = hiddenState.hiddenSources();
		if (items.isEmpty() && srcs.isEmpty())
		{
			lootListPanel.add(PanelWidgets.emptyRowLabel("Nothing hidden."));
			return;
		}

		if (!items.isEmpty())
		{
			JPanel grid = new JPanel(new GridLayout(0, ICON_GRID_COLUMNS, 2, 2));
			grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			grid.setAlignmentX(Component.LEFT_ALIGNMENT);
			for (Map.Entry<Integer, String> entry : items.entrySet())
			{
				int itemId = entry.getKey();
				String name = entry.getValue() == null || entry.getValue().isEmpty()
					? ("Item #" + itemId) : entry.getValue();
				grid.add(buildHiddenItemCell(itemId, name));
			}
			grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, grid.getPreferredSize().height));
			lootListPanel.add(grid);
		}

		for (Map.Entry<String, String> entry : srcs.entrySet())
		{
			lootListPanel.add(buildHiddenSourceChip(entry.getKey(), entry.getValue()));
		}
	}

	/**
	 * One grayed icon cell for the hidden-items tray: the item sprite dimmed by
	 * a translucent overlay (marking it removed from the feed) with a small ✕
	 * pinned top-right (via {@link OverlayLayout}) that un-hides it. Mirrors the
	 * excluded-gear viewer's cell in {@code GearSection}.
	 */
	private JPanel buildHiddenItemCell(int itemId, String name)
	{
		JLabel icon = new JLabel();
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setVerticalAlignment(SwingConstants.CENTER);
		icon.setAlignmentX(0.5f);
		icon.setAlignmentY(0.5f);
		if (itemManager != null && itemId > 0)
		{
			itemManager.getImage(itemId, 1, false).addTo(icon);
		}

		// A translucent gray panel the size of the sprite, painted over it so
		// the hidden item reads as grayed-out regardless of async image load.
		JPanel dim = new JPanel()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				g.setColor(new Color(30, 30, 30, 150));
				g.fillRect(0, 0, getWidth(), getHeight());
			}
		};
		dim.setOpaque(false);
		dim.setAlignmentX(0.5f);
		dim.setAlignmentY(0.5f);
		dim.setPreferredSize(new Dimension(ITEM_SPRITE_W, ITEM_SPRITE_H));
		dim.setMaximumSize(new Dimension(ITEM_SPRITE_W, ITEM_SPRITE_H));

		JButton restore = new JButton("✕");
		restore.setFont(FontManager.getRunescapeSmallFont());
		restore.setFocusPainted(false);
		restore.setBorder(null);
		restore.setMargin(new Insets(0, 0, 0, 0));
		restore.setContentAreaFilled(false);
		restore.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		restore.setToolTipText("Add " + name + " back to the loot feed");
		restore.addActionListener(e ->
		{
			hiddenState.unhideItem(itemId);
			applyResetsThenRebuild();
		});

		JPanel topRight = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		topRight.setOpaque(false);
		topRight.add(restore);

		JPanel overlay = new JPanel(new BorderLayout());
		overlay.setOpaque(false);
		overlay.setAlignmentX(0.5f);
		overlay.setAlignmentY(0.5f);
		overlay.setPreferredSize(new Dimension(ITEM_SPRITE_W, ITEM_SPRITE_H));
		overlay.setMaximumSize(new Dimension(ITEM_SPRITE_W, ITEM_SPRITE_H));
		overlay.setToolTipText(name + " — hidden from the loot feed");
		overlay.add(topRight, BorderLayout.NORTH);

		JPanel cell = new JPanel();
		cell.setLayout(new OverlayLayout(cell));
		cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Added front-to-back: ✕ overlay on top, dim over the icon, sprite below.
		cell.add(overlay);
		cell.add(dim);
		cell.add(icon);
		return cell;
	}

	/**
	 * A single ✕ chip for a whole hidden loot source ("Hide loot"), restoring
	 * the entire source to the feed on click. Sources have no single icon, so
	 * they render as a grayed name row rather than an icon cell.
	 */
	private JPanel buildHiddenSourceChip(String catId, String name)
	{
		JPanel chip = new JPanel(new BorderLayout(4, 0));
		chip.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		chip.setBorder(new EmptyBorder(1, 0, 1, 0));
		chip.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel label = new JLabel(name);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());

		JButton restore = new JButton("✕");
		restore.setFont(FontManager.getRunescapeSmallFont());
		restore.setFocusPainted(false);
		restore.setBorder(null);
		restore.setMargin(new Insets(0, 0, 0, 0));
		restore.setContentAreaFilled(false);
		restore.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		restore.setToolTipText("Add the " + name + " loot back to the feed");
		restore.addActionListener(e ->
		{
			hiddenState.unhideSource(catId);
			applyResetsThenRebuild();
		});

		chip.add(label, BorderLayout.CENTER);
		chip.add(restore, BorderLayout.EAST);
		chip.setMaximumSize(new Dimension(Integer.MAX_VALUE, chip.getPreferredSize().height));
		return chip;
	}

	/**
	 * Clears every "Hide item" / "Hide loot" hide, e.g. as part of a
	 * panel-wide full reset. Does not affect {@link #hiddenSources} (the
	 * separate Reset/Reset-others/Reset-all "hidden until next pickup" set).
	 */
	public void clearHidden()
	{
		hiddenState.clear();
	}

	@Override
	public void removeAllCategoryOverlays()
	{
		categorySupport.removeAllOverlays();
	}

	/**
	 * Full panel reset (feature 11): clears every retained loot state — the
	 * "hidden until next pickup" source set, the persistent "Hide item"/"Hide
	 * loot" hides, collapsed-source and frozen paused-figure maps, the reset
	 * epochs and the running total — and re-renders an empty feed. The next
	 * snapshot repopulates it from scratch, so nothing stays hidden or frozen
	 * across a reset.
	 */
	@Override
	public void resetState()
	{
		hiddenSources.clear();
		collapsedSources.clear();
		lastSeenBySource.clear();
		lastSeenEpoch.clear();
		hiddenState.clear();
		showHiddenTray = false;
		lastRenderSignature = null;
		total = 0;
		categorySupport.clearAll();
		rebuild(List.of());
	}

	@Override
	protected String summaryText()
	{
		return GpFormat.format(total);
	}

	// ------------------------------------------------- test seams (package)

	boolean isSourceHiddenForTest(String source)
	{
		return hiddenSources.contains(categoryId(source));
	}

	boolean hasHiddenItemsForTest()
	{
		return !hiddenState.isEmpty();
	}

	/** Simulates "Reset"-ing a source (the "hidden until next pickup" set) plus collapsing it. */
	void hideSourceForTest(String source)
	{
		hiddenSources.add(categoryId(source));
		collapsedSources.add(source);
		categorySupport.controller().setPaused(categoryId(source), true);
	}

	/** Simulates the per-item "Hide item" action (the persistent hide set). */
	void hideItemForTest(int itemId, String name)
	{
		hiddenState.hideItem(new com.ospulse.model.ItemStack(itemId, name, 1, 0L));
	}

	int lootListRowCountForTest()
	{
		return lootListPanel.getComponentCount();
	}
}

package com.ospulse.ui;

/**
 * Pure, side-effect-free builder for the "cent" number styling used across
 * the panel — "cent" here as in the fractional/decimal part of a number, by
 * analogy with money cents being the fraction of a currency unit after the
 * decimal point: an integer part and any trailing suffix (k/m/b, %, s, ...)
 * render bright in a context colour, while only the decimal point and its
 * fractional digits (the "cents") are dimmed to a duller colour, so the
 * integer magnitude reads at a glance (the "1.98 read as 198" misread this
 * treatment exists to prevent) without shrinking anything to a
 * harder-to-read size.
 *
 * <p>Shared by {@link GpFormat} (gp values in the wealth/session panels) and
 * {@code GearSection}'s DPS/Accuracy/Avg-hit/TTK/Overkill readouts so every
 * "cent" number in the plugin gets the exact same treatment from one place.
 * Kept dependency-free (no Swing/RuneLite imports) so it's trivially
 * unit-testable and easy to split into its own module later.
 *
 * <p>No {@code size} attribute is emitted at all: every run renders at the
 * label's normal font size, and only the {@code color} changes between the
 * bright integer/suffix spans and the dim decimal span.
 */
public final class CentFormat
{
	private CentFormat()
	{
	}

	/** Default context colour for the integer part — plain white. */
	public static final String WHITE = "#FFFFFF";
	/** Default de-emphasised colour for the fractional (decimal) part — dim grey. */
	public static final String GREY = "#8C8C8C";

	/**
	 * The green used for a positive "vs worn"/gp-gain delta — mirrors
	 * {@code ColorScheme.PROGRESS_COMPLETE_COLOR} (#37F046), which is also
	 * {@code GearSection.DELTA_UP_COLOR} and the colour
	 * {@code PanelWidgets.setSignedGpLabel} already applies to non-negative
	 * gp deltas.
	 */
	public static final String GREEN = "#37F046";

	/**
	 * The red used for a negative "vs worn"/gp-loss delta — mirrors
	 * {@code ColorScheme.PROGRESS_ERROR_COLOR} (#E61E1E), which is also
	 * {@code GearSection.DELTA_DOWN_COLOR} and the colour
	 * {@code PanelWidgets.setSignedGpLabel} already applies to negative gp
	 * deltas.
	 */
	public static final String RED = "#E61E1E";

	/**
	 * Duller/darker decimal companions for {@link #GREEN}/{@link #RED},
	 * produced by {@link #dim(String)} — see there for the exact ratio.
	 */
	public static final String GREEN_DIM = dim(GREEN);
	public static final String RED_DIM = dim(RED);

	/**
	 * Darkens a {@code "#RRGGBB"} colour to the dim companion a "cent"
	 * fragment uses for its de-emphasised part, by scaling each channel to
	 * the same ~55% ratio the existing grey decimal colour already sits at
	 * relative to white ({@code 0x8C / 0xFF ≈ 0.549}):
	 * {@code round(channel * 0.55)}. The single source of truth for that
	 * ratio — {@link #GREEN_DIM}/{@link #RED_DIM} are just {@code dim(GREEN)}/
	 * {@code dim(RED)}, and any caller with its own integer colour (e.g. a
	 * highlighted row's own accent colour) can derive a matching dim decimal
	 * the same way instead of hand-picking one.
	 */
	public static String dim(String hexColor)
	{
		int r = Integer.parseInt(hexColor.substring(1, 3), 16);
		int g = Integer.parseInt(hexColor.substring(3, 5), 16);
		int b = Integer.parseInt(hexColor.substring(5, 7), 16);
		return String.format("#%02X%02X%02X",
			Math.round(r * 0.55f), Math.round(g * 0.55f), Math.round(b * 0.55f));
	}

	/**
	 * Splits {@code formatted} (e.g. {@code "1.5m"}, {@code "100k"},
	 * {@code "1,234"}, a signed value, or a plain integer) into an integer
	 * part (see {@link #integerEnd}), an optional decimal part (a
	 * {@code .} plus its fractional digits, if present right after the
	 * integer part), and a trailing suffix (k/m/b, %, s, ...). The integer
	 * and suffix render in {@code intColor}; only the decimal part — if any —
	 * renders dimmed in {@code decimalColor}. Nothing changes size. Returns a
	 * bare fragment (no surrounding {@code <html>} tags) so callers can
	 * compose it with other fragments (e.g. a "before -&gt; after" comparison
	 * in one label).
	 */
	public static String fragment(String formatted, String intColor, String decimalColor)
	{
		int intEnd = integerEnd(formatted);
		int decimalEnd = intEnd;
		if (decimalEnd < formatted.length() && formatted.charAt(decimalEnd) == '.')
		{
			decimalEnd++;
			while (decimalEnd < formatted.length() && Character.isDigit(formatted.charAt(decimalEnd)))
			{
				decimalEnd++;
			}
		}

		if (decimalEnd == intEnd)
		{
			// No decimal part: integer and suffix are the same colour, so
			// merge them into a single <font> tag instead of two adjacent
			// identical ones.
			return "<font color='" + intColor + "'>" + formatted + "</font>";
		}

		String integerPart = formatted.substring(0, intEnd);
		String decimalPart = formatted.substring(intEnd, decimalEnd);
		String suffixPart = formatted.substring(decimalEnd);

		StringBuilder result = new StringBuilder();
		result.append("<font color='").append(intColor).append("'>").append(integerPart).append("</font>");
		result.append("<font color='").append(decimalColor).append("'>").append(decimalPart).append("</font>");
		if (!suffixPart.isEmpty())
		{
			result.append("<font color='").append(intColor).append("'>").append(suffixPart).append("</font>");
		}
		return result.toString();
	}

	/**
	 * Index where the whole-number part of {@code formatted} ends: the first
	 * character that isn't part of the integer magnitude reading (i.e. not a
	 * digit, a leading sign, or a grouping comma). Everything from there on is
	 * a decimal point and fractional digits (dimmed) and/or a trailing
	 * {@code k}/{@code m}/{@code b} (or {@code %}/{@code s}/…) suffix (bright,
	 * same colour as the integer). Equals the string length for a bare
	 * integer such as {@code "1,234"} or a round abbreviation such as
	 * {@code "100k"} (nothing to dim).
	 */
	private static int integerEnd(String formatted)
	{
		int i = 0;
		while (i < formatted.length())
		{
			char c = formatted.charAt(i);
			if ((c >= '0' && c <= '9') || c == '-' || c == ',')
			{
				i++;
			}
			else
			{
				break;
			}
		}
		return i;
	}

	/** {@link #fragment(String, String, String)} using the default white-integer / grey-decimal pairing. */
	public static String fragment(String formatted)
	{
		return fragment(formatted, WHITE, GREY);
	}

	/**
	 * {@link #fragment(String, String, String)} with the integer (and suffix)
	 * in {@code color} and the decimal in {@link #dim(String) dim(color)} —
	 * for a context colour that isn't one of the standing {@link #GREEN}/
	 * {@link #RED} pairings (e.g. a highlighted/best row rendered in the
	 * panel's brand accent colour, which must still dim its decimals rather
	 * than hard-coding white).
	 */
	public static String fragment(String formatted, String color)
	{
		return fragment(formatted, color, dim(color));
	}

	/** {@link #fragment(String, String, String)} using the green-integer / dull-green-decimal pairing (positive delta). */
	public static String greenFragment(String formatted)
	{
		return fragment(formatted, GREEN, GREEN_DIM);
	}

	/** {@link #fragment(String, String, String)} using the red-integer / dull-red-decimal pairing (negative delta). */
	public static String redFragment(String formatted)
	{
		return fragment(formatted, RED, RED_DIM);
	}

	/** {@link #fragment(String, String, String)} wrapped in standalone {@code <html>} tags. */
	public static String html(String formatted, String intColor, String decimalColor)
	{
		return "<html>" + fragment(formatted, intColor, decimalColor) + "</html>";
	}

	/** {@link #fragment(String)} wrapped in standalone {@code <html>} tags. */
	public static String html(String formatted)
	{
		return "<html>" + fragment(formatted) + "</html>";
	}
}

package com.ospulse.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.AbstractButton;
import javax.swing.Icon;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/**
 * A small, self-drawn tick box, sized to sit flush on a text line.
 *
 * <p><b>Why not just style a JCheckBox.</b> The stock box is sized by the
 * look-and-feel, and the LAF is NOT the same everywhere this code runs:
 * RuneLite ships <b>FlatLaf</b>, but a unit-test JVM with no LAF installed
 * gets <b>Metal</b>. Measured (2026-07-15):
 *
 * <pre>
 *                          Metal      FlatLaf (RuneLite)
 *   default box            21x21      19x19
 *   margins/border zeroed  13x13      17x17
 *   stat-row text line     12         12
 * </pre>
 *
 * Zeroing the margin therefore looks like a big win under Metal (21->13) and
 * is nearly worthless under FlatLaf (19->17) — which is how a toggle row
 * shipped ~5px taller than the stat rows around it while a Metal-based test
 * asserted it was within 1px. A test that measures a different LAF from the
 * client is not measuring anything.
 *
 * <p>Drawing the box ourselves removes the LAF from the question entirely:
 * the size is exactly what we pass in, in every JVM, so the test and the
 * client agree. Pass the row's text height ({@code 12}) and the toggle row
 * ends up the same height as a plain stat row — which is what "equal spacing"
 * actually requires.
 *
 * <p>Set via {@code checkbox.setIcon(...)} only: {@link #paintIcon} reads the
 * button's own selected/enabled state, so one icon instance covers every
 * state and no {@code setSelectedIcon} is needed.
 */
public final class SmallCheckBoxIcon implements Icon
{
	/** Matches the 12px RuneScape-small text line the stat rows use. */
	public static final int DEFAULT_SIZE = 12;

	private final int size;

	public SmallCheckBoxIcon(int size)
	{
		this.size = size;
	}

	@Override
	public int getIconWidth()
	{
		return size;
	}

	@Override
	public int getIconHeight()
	{
		return size;
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		boolean selected = c instanceof AbstractButton && ((AbstractButton) c).isSelected();
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

			int box = size - 1;
			// An unchecked box must still read as a control, so the outline is
			// always drawn — only the fill/tick carry the state.
			g2.setColor(ColorScheme.DARK_GRAY_COLOR);
			g2.fillRoundRect(x, y, box, box, 3, 3);
			g2.setColor(selected ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR);
			g2.drawRoundRect(x, y, box, box, 3, 3);

			if (selected)
			{
				g2.setColor(c.isEnabled() ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
				g2.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				// Tick drawn proportionally so it stays centred at any size.
				g2.drawLine(x + Math.round(size * 0.26f), y + Math.round(size * 0.52f),
					x + Math.round(size * 0.44f), y + Math.round(size * 0.72f));
				g2.drawLine(x + Math.round(size * 0.44f), y + Math.round(size * 0.72f),
					x + Math.round(size * 0.76f), y + Math.round(size * 0.28f));
			}
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.ospulse.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.JComponent;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;

/**
 * A slim, flat horizontal progress bar in the RuneLite side-panel style: a dark
 * track with a coloured fill from the left, its width proportional to a 0..1
 * progress value. No text, no border chrome — meant to sit under a labelled row
 * (a GE offer, an XP-to-level row).
 *
 * <p>Shared by the Grand Exchange and XP sections so both render an identical
 * bar. Set the fill colour with {@link #setForeground(Color)} and the progress
 * with {@link #setProgress(double)}.
 */
public final class ThinProgressBar extends JComponent
{
	private static final int DEFAULT_HEIGHT = 5;

	private final int barHeight;
	private double progress;

	public ThinProgressBar()
	{
		this(DEFAULT_HEIGHT);
	}

	public ThinProgressBar(int barHeight)
	{
		this.barHeight = barHeight;
		setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		Dimension size = new Dimension(0, barHeight);
		setPreferredSize(size);
		setMinimumSize(new Dimension(0, barHeight));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, barHeight));
	}

	/** Progress in the range [0, 1]; values outside are clamped. */
	public void setProgress(double progress)
	{
		double clamped = Math.max(0.0, Math.min(1.0, progress));
		if (clamped != this.progress)
		{
			this.progress = clamped;
			repaint();
		}
	}

	public double getProgress()
	{
		return progress;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		int w = getWidth();
		int h = barHeight;

		g.setColor(getBackground());
		g.fillRect(0, 0, w, h);

		int fill = (int) Math.round(w * progress);
		if (fill > 0)
		{
			g.setColor(getForeground());
			g.fillRect(0, 0, fill, h);
		}
	}
}

package com.ospulse.ui;

import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.Box;
import javax.swing.ImageIcon;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Image;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Shared, stateless builders for the small labelled rows used across every
 * panel section. Extracted from the original monolithic {@code OSPulsePanel} so
 * each {@link CollapsibleSection} can reuse the exact same row styling.
 */
public final class PanelWidgets
{
	private PanelWidgets()
	{
	}

	/**
	 * Adds a "label ........ value" row to {@code container} and returns the
	 * value label so the caller can mutate it on each update.
	 */
	public static JLabel statRow(JPanel container, String labelText)
	{
		return statRow(container, labelText, null);
	}

	/**
	 * Same as {@link #statRow(JPanel, String)}, but also attaches {@code
	 * popupMenu} to the row (via {@code setComponentPopupMenu}) when
	 * non-null, e.g. for an XP-Tracker-style right-click reset/pause/canvas
	 * menu on a per-stat basis.
	 */
	public static JLabel statRow(JPanel container, String labelText, javax.swing.JPopupMenu popupMenu)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel label = new JLabel(labelText);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());

		JLabel value = new JLabel("-");
		value.setForeground(Color.WHITE);
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setHorizontalAlignment(SwingConstants.RIGHT);

		row.add(label, BorderLayout.WEST);
		row.add(value, BorderLayout.EAST);
		if (popupMenu != null)
		{
			row.setComponentPopupMenu(popupMenu);
			value.setComponentPopupMenu(popupMenu);
		}
		container.add(row);
		return value;
	}

	/**
	 * A row pairing a {@link #statRow(JPanel, String)}-styled "label ........
	 * value" row with a leading {@link JCheckBox} the caller can read/set to
	 * include or exclude the row from a computed total — e.g. the session
	 * panel's "GE positions"/"Bank" include/exclude toggles. Bundled together
	 * so callers get both live components from one call.
	 */
	public static final class ToggleRow
	{
		public final JCheckBox checkbox;
		public final JLabel value;

		ToggleRow(JCheckBox checkbox, JLabel value)
		{
			this.checkbox = checkbox;
			this.value = value;
		}
	}

	/** Gap in px between the end of a toggle row's name and its tick box. */
	private static final int TOGGLE_NAME_BOX_GAP = 4;

	/**
	 * A bare, tightly-packed tick box (no text of its own — the name is a
	 * separate {@link JLabel} so it can left-align with the plain
	 * {@link #statRow} names).
	 *
	 * <p>The box is drawn by {@link SmallCheckBoxIcon} rather than the
	 * look-and-feel. Zeroing the margin alone is NOT enough: it only shrinks
	 * the LAF box to 17x17 under RuneLite's FlatLaf (vs a 12px text line), so
	 * the row still stood ~5px taller than the stat rows around it. Owning the
	 * icon pins it to the text height in every LAF — see that class's javadoc
	 * for the measurements.
	 */
	private static JCheckBox toggleCheckBox()
	{
		JCheckBox checkbox = new JCheckBox("", true);
		checkbox.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		checkbox.setIcon(new SmallCheckBoxIcon(SmallCheckBoxIcon.DEFAULT_SIZE));
		checkbox.setMargin(new Insets(0, 0, 0, 0));
		checkbox.setBorder(new EmptyBorder(0, 0, 0, 0));
		checkbox.setBorderPainted(false);
		checkbox.setFocusPainted(false);
		return checkbox;
	}

	/**
	 * Adds a "label ... [x]" row with NO value column — the display-only
	 * toggles (e.g. "Show breakdown") that sit alongside
	 * {@link #toggleStatRow}s. Shares the same name column so every tick box
	 * in the section lines up on one x.
	 */
	public static JCheckBox toggleOnlyRow(JPanel container, String labelText, int nameColumnWidth)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JCheckBox checkbox = toggleCheckBox();
		row.add(nameColumn(labelText, nameColumnWidth, checkbox, null), BorderLayout.WEST);
		container.add(row);
		return checkbox;
	}

	/**
	 * The shared "name ..... [x]" column: the name flush left, the tick box
	 * right-aligned at a fixed width so every row's box shares one x.
	 *
	 * @param tooltip tooltip for the box, or null for none.
	 */
	private static JPanel nameColumn(String labelText, int nameColumnWidth, JCheckBox checkbox, String tooltip)
	{
		JPanel namePanel = new JPanel(new BorderLayout(TOGGLE_NAME_BOX_GAP, 0));
		namePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel label = new JLabel(labelText);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		namePanel.add(label, BorderLayout.CENTER);

		if (tooltip != null)
		{
			checkbox.setToolTipText(tooltip);
		}
		namePanel.add(checkbox, BorderLayout.EAST);

		// The box carries no text of its own any more, so without this the
		// clickable area would have shrunk from "box + name" to just the box.
		MouseAdapter toggleOnClick = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				checkbox.doClick();
			}
		};
		label.addMouseListener(toggleOnClick);
		namePanel.addMouseListener(toggleOnClick);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		namePanel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		// Pin the column so every row's box shares one x. Height stays the
		// panel's natural height so the row never grows taller than a statRow.
		Dimension column = new Dimension(nameColumnWidth, namePanel.getPreferredSize().height);
		namePanel.setPreferredSize(column);
		namePanel.setMinimumSize(column);
		namePanel.setMaximumSize(column);
		return namePanel;
	}

	/**
	 * The width of the shared name column for a set of {@link #toggleStatRow}
	 * rows: the widest name, plus the gap and the tick box itself.
	 *
	 * <p>Pass the SAME value to every {@code toggleStatRow} in one section so
	 * the tick boxes all land on one x (right-aligned at the column's edge)
	 * while the names stay flush-left with the section's plain stat rows.
	 * Measured from the real font + a real checkbox rather than hard-coded, so
	 * it cannot drift when a label is renamed or the LAF's box size changes.
	 */
	public static int toggleNameColumnWidth(String... labelTexts)
	{
		JLabel probe = new JLabel();
		probe.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = probe.getFontMetrics(probe.getFont());
		int widest = 0;
		for (String text : labelTexts)
		{
			widest = Math.max(widest, metrics.stringWidth(text));
		}
		return widest + TOGGLE_NAME_BOX_GAP + toggleCheckBox().getPreferredSize().width;
	}

	/**
	 * Adds a "label ... [x] ........ value" row to {@code container}, checked
	 * by default, and returns the checkbox + value label so the caller can
	 * read the toggle state and mutate the value on each update.
	 *
	 * <p>The name leads and the tick box FOLLOWS it, right-aligned inside a
	 * fixed-width name column ({@code nameColumnWidth}, from
	 * {@link #toggleNameColumnWidth}). That keeps this row's name flush-left
	 * with the plain {@link #statRow} names above it — a leading checkbox used
	 * to indent the name by the box's width, so toggle and non-toggle names
	 * never lined up — while still aligning the boxes with each other.
	 *
	 * @param nameColumnWidth shared column width; pass the same value for
	 *                        every toggle row in a section.
	 */
	public static ToggleRow toggleStatRow(JPanel container, String labelText, int nameColumnWidth)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JCheckBox checkbox = toggleCheckBox();
		row.add(nameColumn(labelText, nameColumnWidth, checkbox,
			"Include " + labelText + " in the total"), BorderLayout.WEST);

		JLabel value = new JLabel("-");
		value.setForeground(Color.WHITE);
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(value, BorderLayout.EAST);

		container.add(row);
		return new ToggleRow(checkbox, value);
	}

	/** A "left ........ right" row (no icon), pinned right. */
	public static JPanel listRow(String left, String right)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel leftLabel = new JLabel(left);
		leftLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		leftLabel.setFont(FontManager.getRunescapeSmallFont());

		JLabel rightLabel = new JLabel(right);
		rightLabel.setForeground(Color.WHITE);
		rightLabel.setFont(FontManager.getRunescapeSmallFont());
		rightLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		row.add(leftLabel, BorderLayout.WEST);
		row.add(rightLabel, BorderLayout.EAST);
		return row;
	}

	/**
	 * A "left ........ ±right" row (no icon), like {@link #listRow(String,
	 * String)} but the right-hand side is a signed gp figure rendered via
	 * {@link #setSignedGpLabel(JLabel, long)} — green for a gain (or an
	 * exact-zero result), red for a loss. Exists so per-row dynamic content
	 * (e.g. one row per active GE offer, rebuilt from scratch on every
	 * update) can get the same signed-gp treatment as the static stat rows
	 * without hand-rolling its own colour logic.
	 */
	public static JPanel signedListRow(String left, long value)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel leftLabel = new JLabel(left);
		leftLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		leftLabel.setFont(FontManager.getRunescapeSmallFont());

		JLabel rightLabel = new JLabel();
		rightLabel.setFont(FontManager.getRunescapeSmallFont());
		rightLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		setSignedGpLabel(rightLabel, value);

		row.add(leftLabel, BorderLayout.WEST);
		row.add(rightLabel, BorderLayout.EAST);
		return row;
	}

	/**
	 * A list row with the item's sprite left of {@code leftText}, and
	 * {@code rightText} pinned right. The icon loads asynchronously via
	 * {@link ItemManager} and repaints when ready.
	 *
	 * <p>The text sits in {@code CENTER} so it takes the leftover width and
	 * ellipsizes long names instead of pushing the row (and the whole panel)
	 * wider than the fixed side-panel width.
	 */
	public static JPanel iconRow(ItemManager itemManager, int itemId, String leftText,
		String rightText, Color leftColor)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (itemManager != null && itemId > 0)
		{
			JLabel iconLabel = new JLabel();
			itemManager.getImage(itemId).addTo(iconLabel);
			row.add(iconLabel, BorderLayout.WEST);
		}

		JLabel textLabel = new JLabel(leftText);
		textLabel.setForeground(leftColor);
		textLabel.setFont(FontManager.getRunescapeSmallFont());
		row.add(textLabel, BorderLayout.CENTER);

		JLabel rightLabel = new JLabel(rightText);
		rightLabel.setForeground(Color.WHITE);
		rightLabel.setFont(FontManager.getRunescapeSmallFont());
		rightLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		rightLabel.setBorder(new EmptyBorder(0, 4, 0, 0));
		row.add(rightLabel, BorderLayout.EAST);

		// Don't let the row stretch vertically under BoxLayout.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/**
	 * A row with a ready {@link Image} (e.g. a skill icon) left of
	 * {@code leftText}, and {@code rightText} pinned right. Unlike the item
	 * {@link #iconRow(ItemManager, int, String, String, Color)} overload, this
	 * takes an already-loaded image rather than an async item sprite.
	 */
	public static JPanel iconRow(Image image, String leftText, String rightText, Color leftColor)
	{
		return iconRow(image, leftText, rightText, leftColor, null);
	}

	/**
	 * Same as {@link #iconRow(Image, String, String, Color)}, but also
	 * attaches {@code popupMenu} to the row when non-null, e.g. for an
	 * XP-Tracker-style right-click reset/pause/canvas menu.
	 */
	public static JPanel iconRow(Image image, String leftText, String rightText, Color leftColor,
		javax.swing.JPopupMenu popupMenu)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (image != null)
		{
			row.add(new JLabel(new ImageIcon(image)), BorderLayout.WEST);
		}

		JLabel textLabel = new JLabel(leftText);
		textLabel.setForeground(leftColor);
		textLabel.setFont(FontManager.getRunescapeSmallFont());
		row.add(textLabel, BorderLayout.CENTER);

		JLabel rightLabel = new JLabel(rightText);
		rightLabel.setForeground(Color.WHITE);
		rightLabel.setFont(FontManager.getRunescapeSmallFont());
		rightLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		rightLabel.setBorder(new EmptyBorder(0, 4, 0, 0));
		row.add(rightLabel, BorderLayout.EAST);

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		if (popupMenu != null)
		{
			row.setComponentPopupMenu(popupMenu);
			textLabel.setComponentPopupMenu(popupMenu);
			rightLabel.setComponentPopupMenu(popupMenu);
		}
		return row;
	}

	public static JLabel emptyRowLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	public static Component spacer()
	{
		return Box.createRigidArea(new Dimension(0, 6));
	}

	public static void setSignedGpLabel(JLabel label, long value)
	{
		label.setText(value >= 0
			? GpFormat.centHtml(value, CentFormat.GREEN, CentFormat.GREEN_DIM)
			: GpFormat.centHtml(value, CentFormat.RED, CentFormat.RED_DIM));
		label.setForeground(value >= 0
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.PROGRESS_ERROR_COLOR);
	}

	public static void gpLabel(JLabel label, long value)
	{
		label.setText(GpFormat.centHtml(value));
		resetLabelColor(label);
	}

	public static void resetLabelColor(JLabel label)
	{
		label.setForeground(Color.WHITE);
	}

	public static String formatElapsed(long elapsedMs)
	{
		long totalSeconds = Math.max(0, elapsedMs) / 1000;
		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;
		long seconds = totalSeconds % 60;
		return String.format("%d:%02d:%02d", hours, minutes, seconds);
	}
}

package com.ospulse.ui;

import java.awt.Dimension;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;

/**
 * A {@link JPanel} for use as a {@link JScrollPane} view that never lays out
 * WIDER than the viewport, so content can only ever scroll vertically and can
 * never be clipped off the right-hand edge.
 *
 * <p><b>The bug this exists to prevent.</b> A plain {@code JPanel} does not
 * implement {@link Scrollable}, so {@code JScrollPane} sizes the view to the
 * view's own <i>preferred</i> width. If that preferred width exceeds the
 * viewport — either because the content is intrinsically wide, or because a
 * vertical scrollbar appeared and stole ~15px of viewport width — the overflow
 * hangs off the right. With {@code HORIZONTAL_SCROLLBAR_NEVER} there is no
 * scrollbar to reach it, so it is silently <i>clipped</i>, not scrolled. Any
 * child pinned to {@code BorderLayout.EAST} is exactly what disappears. This
 * shipped as the attack-styles list rendering "5." instead of "5.23" (the DPS
 * label vanishing under the scroll pane's right edge, 2026-07-14).
 *
 * <p>Returning {@code true} from {@link #getScrollableTracksViewportWidth()}
 * forces the view's width to the viewport's, so the layout manager must fit
 * its children into the visible width instead of overflowing it.
 *
 * <p><b>Gotcha — this takes over the scrollbar's unit increment.</b> Once the
 * view is {@code Scrollable}, {@code JScrollPane}'s scrollbar consults
 * {@link #getScrollableUnitIncrement} and IGNORES any
 * {@code getVerticalScrollBar().setUnitIncrement(n)} the caller set. That is
 * why the increment is a constructor parameter: pass the row height so
 * one wheel/arrow click still steps exactly one row.
 */
public class WidthTrackingPanel extends JPanel implements Scrollable
{
	private final int unitIncrement;

	/**
	 * @param unitIncrement pixels to scroll per unit (arrow click / wheel
	 *                      notch) — pass the list's row height so one click
	 *                      steps one row.
	 */
	public WidthTrackingPanel(int unitIncrement)
	{
		this.unitIncrement = Math.max(1, unitIncrement);
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return unitIncrement;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		// A page = a viewport-full, less one row of overlap for context.
		return Math.max(unitIncrement, visibleRect.height - unitIncrement);
	}

	/** Always true — the whole point of this class: fit the width, never clip it. */
	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	/** False, so taller-than-viewport content still scrolls vertically as normal. */
	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}
}

package com.ospulse.ui.category;

/**
 * Per-category resettable/pausable state, adapted from RuneLite's own XP
 * Tracker plugin ({@code net.runelite.client.plugins.xptracker.XpStateSingle}
 * — BSD-2-Clause, see repo {@code NOTICE}).
 *
 * <p>The key architectural lesson borrowed from XP Tracker: don't bolt
 * per-category reset onto one monolithic accumulator ({@link
 * com.ospulse.session.SessionEngine} is exactly that kind of accumulator).
 * Instead, each independently resettable/pausable thing on the panel (a
 * session stat, a loot source, an XP skill) gets its own small state object
 * that can be reset or paused without disturbing its siblings.
 *
 * <p>Unlike {@code XpStateSingle}, this class carries no domain data itself
 * (no XP counters) — the actual figures always come fresh from the latest
 * {@link com.ospulse.session.SessionSnapshot}. What this tracks is purely the
 * user-facing controls XP Tracker's {@code XpInfoBox} exposes per skill:
 * whether the category is paused, and a reset "epoch" that callers can use to
 * decide whether to keep displaying data gained before the last reset.
 *
 * <p>Not thread-safe; intended for exclusive use on the Swing EDT, matching
 * every other {@code CollapsibleSection}.
 */
public final class CategoryState
{
	private final String id;
	private boolean paused;
	/**
	 * Incremented on every {@link #reset()}. Sections that want "reset"
	 * semantics for values derived from session-lifetime data (rather than
	 * genuinely per-category accumulators) can snapshot this alongside the
	 * baseline value at reset time and subtract it back out when rendering.
	 */
	private int resetEpoch;
	private long resetAtMs;

	public CategoryState(String id)
	{
		this.id = id;
	}

	public String getId()
	{
		return id;
	}

	public boolean isPaused()
	{
		return paused;
	}

	public void setPaused(boolean paused)
	{
		this.paused = paused;
	}

	public void togglePaused()
	{
		this.paused = !this.paused;
	}

	/** Marks this category as reset at {@code tsMs}, bumping its reset epoch. */
	public void reset(long tsMs)
	{
		this.resetEpoch++;
		this.resetAtMs = tsMs;
	}

	public int getResetEpoch()
	{
		return resetEpoch;
	}

	public long getResetAtMs()
	{
		return resetAtMs;
	}
}

package com.ospulse.ui.category;

import net.runelite.client.util.LinkBrowser;

import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.event.PopupMenuEvent;
import javax.swing.event.PopupMenuListener;
import javax.swing.border.EmptyBorder;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

/**
 * Builds the per-row right-click {@link JPopupMenu} that RuneLite's own XP
 * Tracker plugin shows on each skill box ({@code
 * net.runelite.client.plugins.xptracker.XpInfoBox}, constructor body around
 * the {@code openXpTracker}/{@code reset}/{@code resetOthers}/{@code
 * pauseSkill}/{@code canvasItem} menu items — BSD-2-Clause, see repo {@code
 * NOTICE}), generalised from "one menu per {@code Skill}" to "one menu per
 * arbitrary category id" so the same builder attaches to session-stat rows,
 * loot-source rows and XP-skill rows.
 *
 * <p>Differences from the original:
 * <ul>
 *   <li>"Reset/hr" is folded into plain "Reset" — our categories don't track
 *   a separate per-hour-only counter the way {@code XpStateSingle} does.
 *   <li>"Pause all" is exposed as its own menu item rather than only via a
 *   panel-level control, since each section builds its own menu instance.
 *   <li>The Wise Old Man link takes an arbitrary RSN + optional metric
 *   instead of being skill-specific, so loot/session categories can link to
 *   the player's overall WOM profile.
 * </ul>
 */
public final class CategoryContextMenu
{
	private CategoryContextMenu()
	{
	}

	/** Supplies the RSN to use for the "Open Wise Old Man" link; may return null/blank if unknown. */
	public interface RsnSupplier
	{
		String getRsn();
	}

	/**
	 * Builds a popup menu wired to {@code controller} for the single category
	 * {@code categoryId}. The caller (a {@code CollapsibleSection} row) is
	 * responsible for attaching it via {@code JComponent#setComponentPopupMenu}.
	 *
	 * @param controller   the shared registry backing reset/pause/canvas state
	 * @param categoryId   the category this menu instance controls
	 * @param rsnSupplier  provides the current player's RSN for the WOM link
	 * @param womMetric    optional Wise Old Man metric segment (e.g. a skill
	 *                     name like {@code "woodcutting"}); {@code null} or
	 *                     blank links to the player's overall gains instead
	 * @param nowMs        current time, stamped on reset actions
	 */
	public static JPopupMenu build(CategoryController controller, String categoryId,
		RsnSupplier rsnSupplier, String womMetric, java.util.function.LongSupplier nowMs)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));

		JMenuItem openWom = new JMenuItem("Open Wise Old Man");
		openWom.addActionListener(e -> LinkBrowser.browse(buildWiseOldManUrl(
			rsnSupplier == null ? null : rsnSupplier.getRsn(), womMetric)));
		menu.add(openWom);

		JMenuItem reset = new JMenuItem("Reset");
		reset.addActionListener(e -> controller.reset(categoryId, nowMs.getAsLong()));
		menu.add(reset);

		JMenuItem resetOthers = new JMenuItem("Reset others");
		resetOthers.addActionListener(e -> controller.resetOthers(categoryId, nowMs.getAsLong()));
		menu.add(resetOthers);

		JMenuItem resetAll = new JMenuItem("Reset all");
		resetAll.addActionListener(e -> controller.resetAll(nowMs.getAsLong()));
		menu.add(resetAll);

		JMenuItem pause = new JMenuItem(controller.isPaused(categoryId) ? "Unpause" : "Pause");
		pause.addActionListener(e -> controller.setPaused(categoryId, !controller.isPaused(categoryId)));
		menu.add(pause);

		JMenuItem pauseAll = new JMenuItem("Pause all");
		pauseAll.addActionListener(e -> controller.setPausedAll(true));
		menu.add(pauseAll);

		JMenuItem canvas = new JMenuItem(
			controller.isOnCanvas(categoryId) ? "Remove from canvas" : "Add to canvas");
		canvas.addActionListener(e -> controller.toggleOnCanvas(categoryId));
		menu.add(canvas);

		// Refresh the toggle-style labels (Pause/Unpause, Add/Remove canvas)
		// each time the menu is about to show, exactly as XpInfoBox's
		// PopupMenuListener refreshes canvasItem's text on
		// popupMenuWillBecomeVisible - state can change between menu opens
		// without the menu itself being rebuilt.
		menu.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent e)
			{
				pause.setText(controller.isPaused(categoryId) ? "Unpause" : "Pause");
				canvas.setText(controller.isOnCanvas(categoryId) ? "Remove from canvas" : "Add to canvas");
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
			{
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent e)
			{
			}
		});

		return menu;
	}

	/**
	 * Builds a wiseoldman.net gains URL for {@code rsn}, adapted from {@code
	 * XpPanel#buildXpTrackerUrl} (BSD-2-Clause) but without the seasonal/league
	 * host switch, since that requires a {@code Client} world-type read the
	 * generic category menu doesn't have; players on a league world simply
	 * get linked to the normal wiseoldman.net host instead of league.wiseoldman.net.
	 * Returns {@code ""} if {@code rsn} is null/blank (mirrors the null-player
	 * case in the original, which also returns "").
	 */
	static String buildWiseOldManUrl(String rsn, String metric)
	{
		if (rsn == null || rsn.trim().isEmpty())
		{
			return "";
		}
		String encodedName = URLEncoder.encode(rsn.trim(), StandardCharsets.UTF_8);
		String metricParam = metric == null || metric.trim().isEmpty()
			? "overall"
			: URLEncoder.encode(metric.trim().toLowerCase(java.util.Locale.ROOT), StandardCharsets.UTF_8);
		return "https://wiseoldman.net/players/" + encodedName + "/gained"
			+ "?metric=" + metricParam + "&period=week";
	}
}

package com.ospulse.ui.category;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.function.Consumer;

/**
 * Registry of {@link CategoryState}s plus the reset/pause/canvas actions XP
 * Tracker's right-click menu exposes, ported from
 * {@code net.runelite.client.plugins.xptracker.XpTrackerPlugin}'s
 * {@code resetSkillState}/{@code resetOtherSkillState}/{@code pauseSkill}/
 * {@code pauseAllSkills}/{@code addOverlay}/{@code removeOverlay} family
 * (BSD-2-Clause, see repo {@code NOTICE}) — generalised from "one registry
 * entry per {@code Skill}" to "one entry per arbitrary category id" so the
 * same controller backs session-stat rows, loot-source rows and XP-skill rows
 * alike.
 *
 * <p>This is the plain-Java half of the port: no Swing, no RuneLite overlay
 * types, so it is unit-testable on its own. The Swing side ({@code
 * CategoryContextMenu}) and the canvas side ({@code CategoryOverlay}) call
 * into this for state changes and register/unregister canvas membership via
 * {@link #setOnCanvas}.
 */
public final class CategoryController
{
	private final Map<String, CategoryState> states = new LinkedHashMap<>();
	private final Map<String, Boolean> onCanvas = new LinkedHashMap<>();

	/** Fired whenever canvas membership changes for a category, so the owning section can (de)register an overlay. */
	private Consumer<CanvasChange> canvasListener = change -> {};

	/** One canvas-membership change: which category, and whether it should now be shown on the canvas. */
	public static final class CanvasChange
	{
		public final String categoryId;
		public final boolean onCanvas;

		CanvasChange(String categoryId, boolean onCanvas)
		{
			this.categoryId = categoryId;
			this.onCanvas = onCanvas;
		}
	}

	public void setCanvasListener(Consumer<CanvasChange> listener)
	{
		this.canvasListener = listener == null ? change -> {} : listener;
	}

	/** Returns the state for {@code categoryId}, creating it (not paused, epoch 0) on first use. */
	public CategoryState stateFor(String categoryId)
	{
		Objects.requireNonNull(categoryId, "categoryId");
		return states.computeIfAbsent(categoryId, CategoryState::new);
	}

	public boolean isPaused(String categoryId)
	{
		CategoryState state = states.get(categoryId);
		return state != null && state.isPaused();
	}

	/** The reset epoch for {@code categoryId} (0 if never reset / unknown). */
	public int resetEpoch(String categoryId)
	{
		CategoryState state = states.get(categoryId);
		return state == null ? 0 : state.getResetEpoch();
	}

	/**
	 * Resets one category. Mirrors {@code XpTrackerPlugin#resetSkillState}:
	 * bumps the category's reset epoch and drops any canvas overlay for it
	 * (a reset category showing stale canvas figures would be confusing).
	 */
	public void reset(String categoryId, long tsMs)
	{
		stateFor(categoryId).reset(tsMs);
		setOnCanvas(categoryId, false);
	}

	/**
	 * Resets every known category except {@code exceptCategoryId}. Mirrors
	 * {@code XpTrackerPlugin#resetOtherSkillState}.
	 */
	public void resetOthers(String exceptCategoryId, long tsMs)
	{
		for (String id : states.keySet().toArray(new String[0]))
		{
			if (!id.equals(exceptCategoryId))
			{
				reset(id, tsMs);
			}
		}
	}

	/** Resets every known category, including {@code exceptCategoryId}-style callers with none to exempt. */
	public void resetAll(long tsMs)
	{
		for (String id : states.keySet().toArray(new String[0]))
		{
			reset(id, tsMs);
		}
	}

	/**
	 * Drops every category's pause/reset/canvas state back to just-constructed
	 * (feature 11: panel-wide full reset). Unlike {@link #resetAll} — which only
	 * bumps each category's reset epoch and leaves the {@code states} entries in
	 * place — this forgets the categories entirely, so a paused/reset row starts
	 * fresh (not paused, epoch 0) on the next snapshot. Does NOT fire the canvas
	 * listener: callers that own overlays must drop them first (the section's
	 * {@code CategorySectionSupport.clearAll} does exactly that).
	 */
	public void clearAll()
	{
		states.clear();
		onCanvas.clear();
	}

	/** Sets pause on one category. Mirrors {@code XpTrackerPlugin#pauseSkill}. */
	public void setPaused(String categoryId, boolean paused)
	{
		stateFor(categoryId).setPaused(paused);
	}

	/** Sets pause on every known category. Mirrors {@code XpTrackerPlugin#pauseAllSkills}. */
	public void setPausedAll(boolean paused)
	{
		for (CategoryState state : states.values())
		{
			state.setPaused(paused);
		}
	}

	/** Whether {@code categoryId} currently has a canvas overlay. Mirrors {@code XpTrackerPlugin#hasOverlay}. */
	public boolean isOnCanvas(String categoryId)
	{
		return onCanvas.getOrDefault(categoryId, Boolean.FALSE);
	}

	/**
	 * Adds/removes {@code categoryId} from the canvas and notifies the
	 * registered listener so the caller can add/remove the actual {@code
	 * Overlay} via {@code OverlayManager}. Mirrors {@code
	 * XpTrackerPlugin#addOverlay}/{@code removeOverlay}.
	 */
	public void setOnCanvas(String categoryId, boolean show)
	{
		boolean was = isOnCanvas(categoryId);
		onCanvas.put(categoryId, show);
		if (was != show)
		{
			canvasListener.accept(new CanvasChange(categoryId, show));
		}
	}

	public void toggleOnCanvas(String categoryId)
	{
		setOnCanvas(categoryId, !isOnCanvas(categoryId));
	}
}

