/**
 * A generic, positionable game-canvas overlay for one panel category — the
 * "Add to canvas" counterpart to a {@code CollapsibleSection} row, adapted
 * from RuneLite's own XP Tracker plugin's {@code XpInfoBoxOverlay} (which
 * pops one skill's XP progress out onto the canvas; BSD-2-Clause, see repo
 * {@code NOTICE}).
 *
 * <p>Unlike {@code XpInfoBoxOverlay}, this isn't specialised to skill XP: it
 * renders a title plus an arbitrary list of label/value lines supplied by a
 * {@link Supplier}, so the same overlay class serves session stats, loot
 * sources and XP skills alike — each {@code CollapsibleSection} decides what
 * lines to show and re-supplies them live (the overlay re-reads the supplier
 * on every render, i.e. every frame, same as {@code XpInfoBoxOverlay} reads
 * live plugin state).
 *
 * <p>Movable via the standard RuneLite overlay drag handling: constructing
 * with the owning {@link Plugin} (rather than the no-arg constructor) opts
 * into the default draggable/{@link OverlayPosition#DETACHED} behaviour once
 * the user drags it, matching every other movable RuneLite overlay including
 * XP Tracker's.
 */
public class CategoryOverlay extends OverlayPanel
{
	/** One label/value row on the overlay, e.g. ("Profit", "1.2m"). */
	public static final class Line
	{
		public final String label;
		public final String value;

		public Line(String label, String value)
		{
			this.label = label;
			this.value = value;
		}
	}

	/**
	 * Everything the XP-skill flavour of this overlay needs to render like
	 * RuneLite's own {@code XpInfoBoxOverlay}: the skill icon (drawn instead of
	 * a text title), the skill colour (progress-bar fill), two stat lines shown
	 * beside the icon, and the level/percent/next-level labels drawn under the
	 * bar. Supplied fresh each render so figures stay live.
	 */
	public static final class XpModel
	{
		public final BufferedImage icon;
		public final Color skillColor;
		public final String line1Left;
		public final String line1Right;
		public final String line2Left;
		public final String line2Right;
		public final String leftLevel;
		public final String centerPercent;
		public final String rightLevel;
		public final double progress;

		public XpModel(BufferedImage icon, Color skillColor,
			String line1Left, String line1Right, String line2Left, String line2Right,
			String leftLevel, String centerPercent, String rightLevel, double progress)
		{
			this.icon = icon;
			this.skillColor = skillColor;
			this.line1Left = line1Left;
			this.line1Right = line1Right;
			this.line2Left = line2Left;
			this.line2Right = line2Right;
			this.leftLevel = leftLevel;
			this.centerPercent = centerPercent;
			this.rightLevel = rightLevel;
			this.progress = progress;
		}
	}

	private final String categoryId;
	private final String title;
	private final Supplier<List<Line>> linesSupplier;
	/** Optional 0.0-1.0 progress source; {@code null} renders no bar (backward-compatible default). */
	private final Supplier<Double> progressSupplier;
	/**
	 * Optional RuneLite-XpInfoBox-style model source; when set and returning
	 * non-null, the overlay renders the skill-icon + stats + skill-coloured bar
	 * layout instead of the generic title/lines/bar. Null for loot/session
	 * categories, which keep the generic look.
	 */
	private final Supplier<XpModel> xpModelSupplier;

	/** Reused across renders (RuneLite does the same) — the icon+stats sub-panel for the XP layout. */
	private final PanelComponent iconXpPanel = new PanelComponent();

	/**
	 * @param plugin        the owning plugin, so RuneLite's overlay drag/reset
	 *                      machinery can find it (matches every {@code
	 *                      OverlayPanel(Plugin)} subclass in RuneLite core)
	 * @param categoryId    stable id for this category, used for equality by
	 *                      {@code CategoryController#isOnCanvas}/{@code
	 *                      removeOverlay}-style lookups done by the owning
	 *                      section
	 * @param title         header line shown at the top of the overlay
	 * @param linesSupplier called on every render; returning an up-to-date
	 *                      list of label/value lines to draw
	 */
	public CategoryOverlay(Plugin plugin, String categoryId, String title, Supplier<List<Line>> linesSupplier)
	{
		this(plugin, categoryId, title, linesSupplier, null, null);
	}

	/**
	 * Same as {@link #CategoryOverlay(Plugin, String, String, Supplier)}, but
	 * with an optional progress bar rendered below the label/value lines —
	 * matching RuneLite's own XP Tracker {@code XpInfoBoxOverlay}, which
	 * shows a progress-to-next-level bar under its lines.
	 *
	 * @param progressSupplier called on every render, returning progress in
	 *                         [0, 1] to fill the bar; pass {@code null} (or
	 *                         use the shorter constructor) to render without
	 *                         a bar at all, e.g. for loot/session categories
	 *                         that have no single "progress" concept.
	 */
	public CategoryOverlay(Plugin plugin, String categoryId, String title, Supplier<List<Line>> linesSupplier,
		Supplier<Double> progressSupplier)
	{
		this(plugin, categoryId, title, linesSupplier, progressSupplier, null);
	}

	/**
	 * Full constructor. When {@code xpModelSupplier} is non-null and returns a
	 * non-null {@link XpModel}, the overlay renders RuneLite's XpInfoBox look
	 * (skill icon + stats + skill-coloured bar) instead of the generic
	 * title/lines/bar; the {@code linesSupplier}/{@code progressSupplier} are
	 * then ignored in favour of the model.
	 */
	public CategoryOverlay(Plugin plugin, String categoryId, String title, Supplier<List<Line>> linesSupplier,
		Supplier<Double> progressSupplier, Supplier<XpModel> xpModelSupplier)
	{
		super(plugin);
		this.categoryId = categoryId;
		this.title = title;
		this.linesSupplier = linesSupplier;
		this.progressSupplier = progressSupplier;
		this.xpModelSupplier = xpModelSupplier;
		// Use RuneLite's snap-corner system (like the real XpInfoBoxOverlay, which
		// leaves the default TOP_LEFT position) rather than DETACHED: the renderer
		// then auto-stacks each overlay in the corner BELOW any existing info/
		// overlays there, so multiple "Add to canvas" boxes form a tidy column
		// instead of piling up at (0,0) over the top-left info. Still movable —
		// the user can drag any of them wherever they like.
		setPosition(OverlayPosition.TOP_LEFT);
	}

	public String getCategoryId()
	{
		return categoryId;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		XpModel xp = xpModelSupplier != null ? xpModelSupplier.get() : null;
		if (xp != null)
		{
			return renderXp(graphics, xp);
		}
		return renderGeneric(graphics);
	}

	/** The generic look (session stats, loot sources): a text title, label/value lines, optional thin bar. */
	private Dimension renderGeneric(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text(title).build());

		List<Line> lines = linesSupplier.get();
		if (lines != null)
		{
			for (Line line : lines)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(line.label)
					.right(line.value)
					.build());
			}
		}

		if (progressSupplier != null)
		{
			Double progress = progressSupplier.get();
			if (progress != null)
			{
				double clamped = Math.max(0.0, Math.min(1.0, progress));
				ThinProgressBar progressBar = new ThinProgressBar();
				progressBar.value = clamped;
				progressBar.centerLabel = String.format(Locale.ROOT, "%.1f%%", clamped * 100.0);
				panelComponent.getChildren().add(progressBar);
			}
		}

		return super.render(graphics);
	}

	/**
	 * The XP-skill look, a near-verbatim port of RuneLite's {@code
	 * XpInfoBoxOverlay}: the skill icon on the left with two stat lines beside
	 * it (via {@link SplitComponent}), then the skill-coloured progress bar — but
	 * with our two tweaks, i.e. the bar is thin and its current-level / % /
	 * next-level labels render BELOW it rather than inside. No text title (the
	 * icon identifies the skill), matching XpInfoBoxOverlay.
	 */
	private Dimension renderXp(Graphics2D graphics, XpModel xp)
	{
		// Small font so the overlay stays compact — XpInfoBoxOverlay does the same.
		graphics.setFont(FontManager.getRunescapeSmallFont());

		panelComponent.getChildren().clear();
		panelComponent.setGap(new Point(0, 2));

		final LineComponent line1 = LineComponent.builder().left(xp.line1Left).right(xp.line1Right).build();
		final LineComponent line2 = LineComponent.builder().left(xp.line2Left).right(xp.line2Right).build();
		final SplitComponent stats = SplitComponent.builder()
			.first(line1)
			.second(line2)
			.orientation(ComponentOrientation.VERTICAL)
			.build();

		final LayoutableRenderableEntity iconAndStats;
		if (xp.icon != null)
		{
			iconAndStats = SplitComponent.builder()
				.first(new ImageComponent(xp.icon))
				.second(stats)
				.orientation(ComponentOrientation.HORIZONTAL)
				.gap(new Point(4, 0))
				.build();
		}
		else
		{
			iconAndStats = stats;
		}

		iconXpPanel.getChildren().clear();
		iconXpPanel.setBackgroundColor(null);
		iconXpPanel.setBorder(new Rectangle(2, 1, 4, 0));
		iconXpPanel.getChildren().add(iconAndStats);
		panelComponent.getChildren().add(iconXpPanel);

		final ThinProgressBar bar = new ThinProgressBar();
		bar.value = xp.progress;
		if (xp.skillColor != null)
		{
			bar.foregroundColor = xp.skillColor;
		}
		bar.leftLabel = xp.leftLevel;
		bar.centerLabel = xp.centerPercent;
		bar.rightLabel = xp.rightLevel;
		panelComponent.getChildren().add(bar);

		return super.render(graphics);
	}

	/**
	 * A slim RuneLite-style progress bar for the overlay: a dark trough with a
	 * coloured fill, with the current-level / % / next-level labels rendered
	 * BELOW the bar (left / centred / right, at RuneLite's {@code SIDE_LABEL_OFFSET})
	 * rather than inside it. RuneLite's stock {@link
	 * net.runelite.client.ui.overlay.components.ProgressBarComponent} can't do
	 * either — it clamps its height to a minimum of 16px and always draws its
	 * labels inside the bar — so this reimplements the same {@link
	 * LayoutableRenderableEntity} contract (default colours matched to
	 * XpInfoBoxOverlay's bar: {@code (61,56,49)} trough, {@code (82,161,82)}
	 * fill) with the two requested tweaks: thinner, and text below.
	 */
	private static final class ThinProgressBar implements LayoutableRenderableEntity
	{
		private static final int BAR_HEIGHT = 5;
		/** Vertical gap between the bar and the label row below it. */
		private static final int TEXT_GAP = 2;
		/** Left/right label inset from the bar edges (matches ProgressBarComponent). */
		private static final int SIDE_LABEL_OFFSET = 4;

		/** Fill fraction, 0..1. */
		private double value;
		/** Labels drawn below the bar (left-aligned / centred / right-aligned); empty draws nothing. */
		private String leftLabel = "";
		private String centerLabel = "";
		private String rightLabel = "";
		private Color foregroundColor = new Color(82, 161, 82);
		private Color backgroundColor = new Color(61, 56, 49);
		private Color fontColor = Color.WHITE;
		private Point preferredLocation = new Point();
		private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);
		private final Rectangle bounds = new Rectangle();

		@Override
		public Dimension render(Graphics2D graphics)
		{
			final FontMetrics metrics = graphics.getFontMetrics();
			final int x = preferredLocation.x;
			final int y = preferredLocation.y;
			final int width = preferredSize.width;
			final double pc = Math.max(0.0, Math.min(1.0, value));
			final int fill = (int) (width * pc);

			// Thin bar: trough first, coloured fill from the left over it.
			graphics.setColor(backgroundColor);
			graphics.fillRect(x, y, width, BAR_HEIGHT);
			graphics.setColor(foregroundColor);
			graphics.fillRect(x, y, fill, BAR_HEIGHT);

			int totalHeight = BAR_HEIGHT;
			final boolean hasText = notEmpty(leftLabel) || notEmpty(centerLabel) || notEmpty(rightLabel);
			if (hasText)
			{
				final int textY = y + BAR_HEIGHT + TEXT_GAP + metrics.getAscent();
				if (notEmpty(leftLabel))
				{
					drawText(graphics, leftLabel, x + SIDE_LABEL_OFFSET, textY);
				}
				if (notEmpty(centerLabel))
				{
					drawText(graphics, centerLabel, x + (width - metrics.stringWidth(centerLabel)) / 2, textY);
				}
				if (notEmpty(rightLabel))
				{
					drawText(graphics, rightLabel, x + width - metrics.stringWidth(rightLabel) - SIDE_LABEL_OFFSET, textY);
				}
				totalHeight = BAR_HEIGHT + TEXT_GAP + metrics.getHeight();
			}

			final Dimension dimension = new Dimension(width, totalHeight);
			bounds.setLocation(preferredLocation);
			bounds.setSize(dimension);
			return dimension;
		}

		private void drawText(Graphics2D graphics, String text, int x, int y)
		{
			final TextComponent component = new TextComponent();
			component.setPosition(x, y);
			component.setColor(fontColor);
			component.setText(text);
			component.render(graphics);
		}

		private static boolean notEmpty(String s)
		{
			return s != null && !s.isEmpty();
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point location)
		{
			this.preferredLocation = location;
		}

		@Override
		public void setPreferredSize(Dimension dimension)
		{
			this.preferredSize = dimension;
		}
	}

	@Override
	public String getName()
	{
		return super.getName() + ":" + categoryId;
	}

	/** Convenience for building a {@link Line} list without importing the inner type everywhere. */
	public static List<Line> lines()
	{
		return new ArrayList<>();
	}
}

package com.ospulse.ui.category;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.swing.JPopupMenu;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

/**
 * Wires a {@link CategoryController} to {@link CategoryOverlay}s and {@link
 * CategoryContextMenu}s for one {@code CollapsibleSection}, so each section
 * (session stats, loot sources, XP skills) doesn't have to hand-roll the
 * "Add to canvas" -&gt; create-and-register-an-{@code Overlay},
 * "Remove from canvas" -&gt; unregister-it plumbing itself. This is the bit
 * that corresponds to {@code XpTrackerPlugin#addOverlay}/{@code
 * removeOverlay} in the original (BSD-2-Clause) — see repo {@code NOTICE}.
 *
 * <p>Not thread-safe; construct and use on the Swing EDT only, same as the
 * {@code CollapsibleSection}s that own an instance of this.
 */
public final class CategorySectionSupport
{
	private final Plugin plugin;
	private final Client client;
	private final OverlayManager overlayManager;
	private final CategoryController controller = new CategoryController();
	private final Map<String, CategoryOverlay> activeOverlays = new LinkedHashMap<>();

	public CategorySectionSupport(Plugin plugin, Client client, OverlayManager overlayManager)
	{
		this.plugin = plugin;
		this.client = client;
		this.overlayManager = overlayManager;
		this.controller.setCanvasListener(this::onCanvasChange);
	}

	public CategoryController controller()
	{
		return controller;
	}

	/**
	 * Builds a right-click popup menu for {@code categoryId}, wired to this
	 * support's controller. {@code womMetric} is an optional Wise Old Man
	 * metric segment (e.g. a skill name); pass {@code null} to link to the
	 * player's overall gains.
	 */
	public JPopupMenu buildMenu(String categoryId, String womMetric)
	{
		return CategoryContextMenu.build(controller, categoryId, this::currentRsn, womMetric,
			System::currentTimeMillis);
	}

	private String currentRsn()
	{
		if (client == null)
		{
			return null;
		}
		// Read the local player exactly once: this runs on the Swing EDT (fired
		// from the "Open Wise Old Man" menu item) while the client thread can
		// null/replace getLocalPlayer() on logout/world-hop. Re-reading it for
		// the name after a separate null check is a TOCTOU that intermittently
		// NPEs; snapshot the reference and derive the name from that.
		Player local = client.getLocalPlayer();
		return local == null ? null : local.getName();
	}

	private void onCanvasChange(CategoryController.CanvasChange change)
	{
		if (overlayManager == null)
		{
			return;
		}
		if (change.onCanvas)
		{
			addOverlay(change.categoryId);
		}
		else
		{
			removeOverlay(change.categoryId);
		}
	}

	private void addOverlay(String categoryId)
	{
		removeOverlay(categoryId);
		CategoryOverlay overlay = new CategoryOverlay(plugin, categoryId, categoryId,
			lineSuppliers.getOrDefault(categoryId, List::of),
			progressSuppliers.get(categoryId),
			xpModelSuppliers.get(categoryId));
		activeOverlays.put(categoryId, overlay);
		overlayManager.add(overlay);
	}

	private void removeOverlay(String categoryId)
	{
		CategoryOverlay overlay = activeOverlays.remove(categoryId);
		if (overlay != null)
		{
			overlayManager.remove(overlay);
		}
	}

	/**
	 * Per-category line suppliers, registered by the owning section so the
	 * overlay (created lazily on "Add to canvas") always renders the latest
	 * figures. Must be set before the user can add that category to canvas.
	 */
	private final Map<String, Supplier<List<CategoryOverlay.Line>>> lineSuppliers = new LinkedHashMap<>();

	public void setLinesSupplier(String categoryId, Supplier<List<CategoryOverlay.Line>> supplier)
	{
		lineSuppliers.put(categoryId, supplier);
	}

	/**
	 * Optional 0.0-1.0 progress source for {@code categoryId}'s canvas
	 * overlay, e.g. an XP skill's progress to next level. Categories with no
	 * supplier registered (the default) render without a progress bar,
	 * matching every caller before this existed.
	 */
	private final Map<String, Supplier<Double>> progressSuppliers = new LinkedHashMap<>();

	public void setProgressSupplier(String categoryId, Supplier<Double> supplier)
	{
		progressSuppliers.put(categoryId, supplier);
	}

	/**
	 * Optional RuneLite-XpInfoBox-style model source for {@code categoryId}'s
	 * canvas overlay (skill icon + stats + skill-coloured bar). Registered by
	 * the XP section only; categories without one (loot/session) render the
	 * generic title/lines/bar look. When set, it takes precedence over the
	 * lines/progress suppliers for that overlay.
	 */
	private final Map<String, Supplier<CategoryOverlay.XpModel>> xpModelSuppliers = new LinkedHashMap<>();

	public void setXpModelSupplier(String categoryId, Supplier<CategoryOverlay.XpModel> supplier)
	{
		xpModelSuppliers.put(categoryId, supplier);
	}

	/** Removes every active canvas overlay this support instance has registered. Idempotent. */
	public void removeAllOverlays()
	{
		for (String categoryId : activeOverlays.keySet().toArray(new String[0]))
		{
			removeOverlay(categoryId);
			controller.setOnCanvas(categoryId, false);
		}
	}

	/**
	 * Full reset (feature 11): drop every registered canvas overlay AND clear
	 * all per-category pause/reset state, so the owning section returns to its
	 * just-constructed category state. Overlays are removed first (so the actual
	 * {@code Overlay} objects leave the {@code OverlayManager}) before the
	 * controller forgets the categories. Idempotent.
	 */
	public void clearAll()
	{
		removeAllOverlays();
		controller.clearAll();
	}
}

package com.ospulse.ui;

import com.ospulse.OSPulseConfig;
import com.ospulse.integration.PriceTrendService;
import com.ospulse.session.SessionListener;
import com.ospulse.session.SessionSnapshot;
import com.ospulse.ui.sections.GearSection;
import com.ospulse.ui.sections.GeSection;
import com.ospulse.ui.sections.HoldingsSection;
import com.ospulse.ui.sections.LootSection;
import com.ospulse.ui.sections.SessionSection;
import com.ospulse.ui.sections.WealthSection;
import com.ospulse.ui.sections.XpSection;

import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Read-side view of the session tracker: a RuneLite side panel showing the
 * current session's profit, net-worth breakdown, loot feed, XP gains, Grand
 * Exchange offers and top holdings — each in a {@link CollapsibleSection} the
 * user can minimize.
 *
 * <p>This class is a thin assembler: it builds the sections once, owns the
 * scroll/empty-state chrome, persists which sections are collapsed via
 * {@link ConfigManager}, and on every snapshot dispatches to each section's
 * {@link CollapsibleSection#apply(SessionSnapshot)} on the Swing EDT.
 */
public class OSPulsePanel extends PluginPanel implements SessionListener
{
	/** Config key (raw, not declared on the interface) for collapsed sections. */
	private static final String COLLAPSED_KEY = "collapsedSections";

	private final OSPulseConfig config;
	private final ConfigManager configManager;

	private final JPanel emptyStatePanel;
	private final JPanel contentPanel;
	private final CardHolder cardHolder;

	/** Every section, always constructed (order = display order). Visibility is a
	 *  layout decision, not a construction one — see {@link #rebuildSectionsColumn()}. */
	private final List<CollapsibleSection> sectionList = new ArrayList<>();

	/** The BoxLayout column that holds the currently-visible sections + spacers. */
	private final JPanel sectionsColumn;

	/** Most recent snapshot, retained so a section turned on live can be fed at once. */
	private SessionSnapshot lastSnapshot;

	/** Retained (not just in {@link #sectionList}) so {@link #setBankHighlighter} has a typed target to forward to. */
	private final GearSection gearSection;

	/** Retained so the panel-showing hook can suspend/restore the bank filter (B8-8). */
	private com.ospulse.integration.BankRecommendationHighlighter bankHighlighter;

	private Runnable resetCallback = () -> {};

	public OSPulsePanel(OSPulseConfig config, ItemManager itemManager, ConfigManager configManager,
		PriceTrendService priceTrendService, SkillIconManager skillIconManager,
		net.runelite.client.game.SpriteManager spriteManager,
		Plugin plugin, Client client, OverlayManager overlayManager,
		GearSection.OptimizerPriceResolver optimizerPriceResolver)
	{
		super(false);
		Objects.requireNonNull(config, "config");
		this.config = config;
		this.configManager = configManager;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(8, 8, 8, 8));

		add(buildHeader(), BorderLayout.NORTH);

		emptyStatePanel = buildEmptyState();

		CollapsibleSection.CollapseStore store = new ConfigCollapseStore();

		// Feature: hideable panel sections (OSPulseConfig "Panel sections"). Every
		// section is constructed unconditionally (construction is inert — no
		// threads/overlays), so a config toggle is purely a layout decision that
		// {@link #applySectionVisibility()} can apply live without destroying any
		// section's retained state. Which ones are actually shown is decided by
		// {@link #rebuildSectionsColumn()} reading the {@code show*Section} flags.
		sectionList.add(new SessionSection(store, plugin, client, overlayManager));
		sectionList.add(new LootSection(store, config, itemManager, plugin, client, overlayManager));
		sectionList.add(new XpSection(store, skillIconManager, plugin, client, overlayManager));
		gearSection = new GearSection(store, itemManager, skillIconManager, spriteManager, configManager,
			optimizerPriceResolver);
		sectionList.add(gearSection);
		sectionList.add(new GeSection(store, itemManager));
		sectionList.add(new WealthSection(store));
		sectionList.add(new HoldingsSection(store, itemManager, config, priceTrendService, configManager, client));

		// A width-tracking column so nothing is laid out wider than the fixed
		// side-panel width; the widest row ellipsizes within its row instead of
		// pushing content past the (horizontally non-scrolling) viewport edge.
		sectionsColumn = new ScrollablePanel();
		sectionsColumn.setLayout(new BoxLayout(sectionsColumn, BoxLayout.Y_AXIS));
		sectionsColumn.setBackground(ColorScheme.DARK_GRAY_COLOR);
		rebuildSectionsColumn();

		JScrollPane scrollPane = new JScrollPane(sectionsColumn);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		// Never scroll horizontally — the side panel has a fixed width; rows must
		// fit and long names truncate rather than push the panel wider.
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);

		contentPanel = new JPanel(new BorderLayout());
		contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		contentPanel.add(scrollPane, BorderLayout.CENTER);

		cardHolder = new CardHolder(this, emptyStatePanel, contentPanel);
		showEmptyState();
	}

	/**
	 * Wires the Reset button to {@code resetCallback}. Defaults to a no-op; the
	 * plugin assembles this to the tracker's {@code resetSession()}.
	 */
	public void setResetCallback(Runnable resetCallback)
	{
		this.resetCallback = resetCallback == null ? () -> {} : resetCallback;
	}

	/** Pass-through to {@link GearSection#refreshIronmanOwnedOnlyMode} — see {@code OSPulsePlugin#onConfigChanged} (issue #11 P2 fix). */
	public void refreshIronmanOwnedOnlyMode()
	{
		gearSection.refreshIronmanOwnedOnlyMode();
	}

	/** Pass-through to {@link GearSection#setBankHighlighter} — the panel doesn't otherwise know about bank tags. */
	public void setBankHighlighter(com.ospulse.integration.BankRecommendationHighlighter bankHighlighter)
	{
		this.bankHighlighter = bankHighlighter;
		gearSection.setBankHighlighter(bankHighlighter);

		// B8-8: when the user switches away from the OSPulse side panel to another
		// plugin (e.g. Inventory Setups), hide the bank filter without disarming,
		// and restore it when they switch back. PluginPanel exposes no activate
		// hook in this client, so drive it off Swing's on-screen showing state.
		addHierarchyListener(e ->
		{
			if ((e.getChangeFlags() & java.awt.event.HierarchyEvent.SHOWING_CHANGED) == 0
				|| this.bankHighlighter == null)
			{
				return;
			}
			if (isShowing())
			{
				this.bankHighlighter.resume();
			}
			else
			{
				this.bankHighlighter.suspend();
			}
		});
	}

	/**
	 * Feature 11 — full Reset. Wipes every section's retained UI state
	 * <em>first</em> (baselines, frozen/hidden figures, what-if/optimiser
	 * selections), then runs the engine {@link #resetCallback} which re-anchors
	 * the session and pushes a fresh snapshot. Order matters: clearing the
	 * section baselines before the re-anchored snapshot arrives is what stops
	 * the stale-baseline "phantom profit" (see {@code SessionSection.resetState}).
	 * Runs on the Swing EDT (the button's action); the engine reset marshals its
	 * snapshot back to the EDT later, by which point the baselines are already
	 * cleared.
	 */
	void onReset()
	{
		resetSections();
		resetCallback.run();
	}

	/** Dispatches {@link CollapsibleSection#resetState()} to every section. */
	private void resetSections()
	{
		for (CollapsibleSection section : sectionList)
		{
			section.resetState();
		}
	}

	/** Whether {@code section} is switched on by its {@code show*Section} config flag. */
	private boolean isSectionEnabled(CollapsibleSection section)
	{
		if (section instanceof SessionSection)
		{
			return config.showSessionSection();
		}
		if (section instanceof LootSection)
		{
			return config.showLootSection();
		}
		if (section instanceof XpSection)
		{
			return config.showXpSection();
		}
		if (section instanceof GearSection)
		{
			return config.showGearSection();
		}
		if (section instanceof GeSection)
		{
			return config.showGeSection();
		}
		if (section instanceof WealthSection)
		{
			return config.showWealthSection();
		}
		if (section instanceof HoldingsSection)
		{
			return config.showHoldingsSection();
		}
		return true;
	}

	/**
	 * (Re)populates {@link #sectionsColumn} with only the enabled sections, in
	 * {@link #sectionList} order, spacer-separated. Sections are re-parented, not
	 * recreated, so their retained UI state survives a toggle. Must run on the EDT.
	 */
	private void rebuildSectionsColumn()
	{
		sectionsColumn.removeAll();
		boolean first = true;
		for (CollapsibleSection section : sectionList)
		{
			if (!isSectionEnabled(section))
			{
				continue;
			}
			if (!first)
			{
				sectionsColumn.add(PanelWidgets.spacer());
			}
			first = false;
			sectionsColumn.add(section);
		}
	}

	/**
	 * Live-applies the {@code show*Section} toggles without a plugin restart:
	 * re-lays-out the visible sections and feeds any newly-shown section the last
	 * snapshot so it isn't blank until the next game tick. Called from the plugin's
	 * {@code onConfigChanged}. Runs on the EDT.
	 */
	public void applySectionVisibility()
	{
		rebuildSectionsColumn();
		if (lastSnapshot != null)
		{
			for (CollapsibleSection section : sectionList)
			{
				if (isSectionEnabled(section))
				{
					section.apply(lastSnapshot);
				}
			}
		}
		sectionsColumn.revalidate();
		sectionsColumn.repaint();
	}

	/**
	 * Removes every category canvas overlay any section has added (via its
	 * "Add to canvas" menu item), so a plugin toggle or client shutdown
	 * doesn't leak stale XP-Tracker-style overlays. Delegates to each
	 * section that owns a {@link com.ospulse.ui.category.CategoryController}.
	 */
	public void removeAllCategoryOverlays()
	{
		for (CollapsibleSection section : sectionList)
		{
			section.removeAllCategoryOverlays();
		}
	}

	/**
	 * Flushes any section-owned persisted state on plugin shutdown.
	 * {@link HoldingsSection#shutdown()} is currently a no-op (the "since last
	 * login" Unrealized P/L snapshot it used to persist was removed along with
	 * the session-wide Unrealized P/L stat row), but the call stays so a
	 * future section-owned persisted value has somewhere to flush from.
	 */
	public void persistState()
	{
		for (CollapsibleSection section : sectionList)
		{
			if (section instanceof HoldingsSection)
			{
				((HoldingsSection) section).shutdown();
			}
		}
	}

	@Override
	public void onSessionUpdate(SessionSnapshot snapshot)
	{
		// Called on the RuneLite client thread; marshal to the EDT before
		// touching any Swing component.
		SwingUtilities.invokeLater(() -> applySnapshot(snapshot));
	}

	private void applySnapshot(SessionSnapshot snapshot)
	{
		lastSnapshot = snapshot;
		if (snapshot == null)
		{
			showEmptyState();
			return;
		}

		showContent();
		for (CollapsibleSection section : sectionList)
		{
			// Skip hidden sections: a disabled section stays inert (e.g. Holdings
			// must not prefetch prices while switched off).
			if (isSectionEnabled(section))
			{
				section.apply(snapshot);
			}
		}
	}

	private void showEmptyState()
	{
		cardHolder.show(emptyStatePanel);
	}

	private void showContent()
	{
		cardHolder.show(contentPanel);
	}

	// --------------------------------------------------------------- helpers

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new EmptyBorder(0, 0, 8, 0));

		JLabel title = new JLabel("OSPulse");
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		header.add(title, BorderLayout.WEST);

		JButton resetButton = new JButton("Reset");
		resetButton.setFont(FontManager.getRunescapeSmallFont());
		resetButton.addActionListener(e -> onReset());
		header.add(resetButton, BorderLayout.EAST);

		return header;
	}

	private JPanel buildEmptyState()
	{
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel label = new JLabel("<html><div style='text-align:center;'>Log in to start tracking.</div></html>");
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeFont());
		label.setHorizontalAlignment(SwingConstants.CENTER);
		panel.add(label, BorderLayout.NORTH);

		return panel;
	}

	/**
	 * A {@link CollapsibleSection.CollapseStore} backed by a single comma-joined
	 * config value, so the set of collapsed sections survives a client restart.
	 */
	private final class ConfigCollapseStore implements CollapsibleSection.CollapseStore
	{
		private final Set<String> collapsed;

		private ConfigCollapseStore()
		{
			this.collapsed = load();
		}

		private Set<String> load()
		{
			Set<String> result = new LinkedHashSet<>();
			if (configManager == null)
			{
				return result;
			}
			String raw = configManager.getConfiguration(OSPulseConfig.GROUP, COLLAPSED_KEY);
			if (raw != null && !raw.isEmpty())
			{
				result.addAll(Arrays.stream(raw.split(","))
					.map(String::trim)
					.filter(s -> !s.isEmpty())
					.collect(Collectors.toList()));
			}
			return result;
		}

		@Override
		public boolean isCollapsed(String key)
		{
			return collapsed.contains(key);
		}

		@Override
		public void setCollapsed(String key, boolean isCollapsed)
		{
			boolean changed = isCollapsed ? collapsed.add(key) : collapsed.remove(key);
			if (!changed || configManager == null)
			{
				return;
			}
			configManager.setConfiguration(OSPulseConfig.GROUP, COLLAPSED_KEY,
				String.join(",", collapsed));
		}
	}

	/**
	 * A {@link BoxLayout} column that reports it tracks the scroll viewport's
	 * width, clamping every row to the fixed side-panel width so long names
	 * ellipsize instead of being clipped past the (non-scrolling) edge.
	 */
	private static final class ScrollablePanel extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	/**
	 * Minimal two-card switcher. {@link java.awt.CardLayout} requires a fixed
	 * container to hold both cards; this keeps that container private to the
	 * panel while exposing a simple {@code show} call.
	 */
	private static final class CardHolder
	{
		private final OSPulsePanel owner;
		private final JPanel empty;
		private final JPanel content;
		private Component current;

		private CardHolder(OSPulsePanel owner, JPanel empty, JPanel content)
		{
			this.owner = owner;
			this.empty = empty;
			this.content = content;
		}

		private void show(Component toShow)
		{
			if (current == toShow)
			{
				return;
			}
			if (current != null)
			{
				owner.remove(current);
			}
			owner.add(toShow, BorderLayout.CENTER);
			current = toShow;
			owner.revalidate();
			owner.repaint();
		}
	}
}

package com.ospulse.ui;

/**
 * Pure, side-effect-free formatter for gp (game-point / coin) quantities used
 * throughout {@link OSPulsePanel}. Kept separate from the panel so it can be
 * unit-tested without any Swing or RuneLite UI dependencies.
 */
public final class GpFormat
{
	private static final String[] SUFFIXES = {"", "k", "m", "b"};
	private static final long COMMA_THRESHOLD = 100_000L;

	private GpFormat()
	{
	}

	/**
	 * Formats a gp amount for display, e.g. {@code 1234 -> "1,234"},
	 * {@code 1_500_000 -> "1.5m"}, {@code 2_000_000_000 -> "2b"}. Negative
	 * values keep their sign (e.g. {@code -1_500_000 -> "-1.5m"}).
	 */
	public static String format(long value)
	{
		if (value == 0)
		{
			return "0";
		}

		String sign = value < 0 ? "-" : "";
		long abs = Math.abs(value);

		if (abs < COMMA_THRESHOLD)
		{
			return sign + String.format("%,d", abs);
		}

		int magnitude = 0;
		double scaled = abs;
		while (scaled >= 1000 && magnitude < SUFFIXES.length - 1)
		{
			scaled /= 1000.0;
			magnitude++;
		}

		double rounded = Math.round(scaled * 10) / 10.0;
		if (rounded >= 1000 && magnitude < SUFFIXES.length - 1)
		{
			rounded = Math.round((rounded / 1000.0) * 10) / 10.0;
			magnitude++;
		}

		String numberPart = rounded == Math.floor(rounded)
			? String.valueOf((long) rounded)
			: String.valueOf(rounded);

		return sign + numberPart + SUFFIXES[magnitude];
	}

	/**
	 * Renders a gp amount using the "cent" number styling: unbolded
	 * whole-number part in the default white, with the decimal point,
	 * fractional digits and k/m/b suffix (if any) dimmed grey and half-size.
	 * Delegates to {@link CentFormat} so wealth/session-panel rows share the
	 * exact same misread-resistant treatment as {@code GearSection}'s
	 * DPS/Accuracy/Avg-hit/TTK/Overkill readouts. Built on top of
	 * {@link #format(long)} — the sign stays with the integer part.
	 */
	public static String centFragment(long gp)
	{
		return CentFormat.fragment(format(gp));
	}

	/**
	 * {@link #centFragment(long)}, but with an explicit integer/decimal
	 * colour pairing — e.g. {@link CentFormat#GREEN}/{@link
	 * CentFormat#GREEN_DIM} for a positive gp delta, or {@link
	 * CentFormat#RED}/{@link CentFormat#RED_DIM} for a negative one.
	 */
	public static String centFragment(long gp, String intColor, String decimalColor)
	{
		return CentFormat.fragment(format(gp), intColor, decimalColor);
	}

	/** {@link #centFragment(long)} as a standalone HTML label string. */
	public static String centHtml(long gp)
	{
		return "<html>" + centFragment(gp) + "</html>";
	}

	/** {@link #centFragment(long, String, String)} as a standalone HTML label string. */
	public static String centHtml(long gp, String intColor, String decimalColor)
	{
		return "<html>" + centFragment(gp, intColor, decimalColor) + "</html>";
	}
}

package com.ospulse.ui;

import com.ospulse.session.SessionSnapshot;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * A titled panel section that the user can collapse by clicking its header.
 *
 * <p>When expanded it shows a {@linkplain #body() body} panel; when collapsed
 * the body is hidden and a one-line summary (supplied by {@link #summaryText()})
 * is shown on the right of the header instead. Collapsed state is persisted via
 * the injected {@link CollapseStore}, so it survives a client restart.
 *
 * <p>Subclasses build their body in their constructor (adding to
 * {@link #body()}), refresh their labels in {@link #apply(SessionSnapshot)}, and
 * must call {@link #refreshSummary()} at the end of {@code apply} so the
 * collapsed header stays current even while hidden. This mirrors the
 * collapsible loot-source idiom the panel already used, generalised to whole
 * sections (feature 4: minimize-all).
 */
public abstract class CollapsibleSection extends JPanel
{
	/** Persistence hook for which sections the user has collapsed. */
	public interface CollapseStore
	{
		boolean isCollapsed(String key);

		void setCollapsed(String key, boolean collapsed);
	}

	private final String key;
	private final CollapseStore store;
	private final JLabel triangleLabel;
	private final JLabel summaryLabel;
	private final JPanel body;
	private boolean collapsed;

	protected CollapsibleSection(String key, String title, CollapseStore store)
	{
		this.key = key;
		this.store = store;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(5, 6, 5, 6));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(new EmptyBorder(0, 0, 4, 0));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		triangleLabel = new JLabel();
		triangleLabel.setForeground(ColorScheme.BRAND_ORANGE);
		triangleLabel.setFont(FontManager.getRunescapeBoldFont());

		JLabel titleLabel = new JLabel(title);
		titleLabel.setForeground(ColorScheme.BRAND_ORANGE);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());

		JPanel left = new JPanel(new BorderLayout(4, 0));
		left.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		left.add(triangleLabel, BorderLayout.WEST);
		left.add(titleLabel, BorderLayout.CENTER);

		summaryLabel = new JLabel();
		summaryLabel.setForeground(Color.WHITE);
		summaryLabel.setFont(FontManager.getRunescapeSmallFont());
		summaryLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		header.add(left, BorderLayout.CENTER);
		header.add(summaryLabel, BorderLayout.EAST);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				toggle();
			}
		});
		add(header);

		body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(body);

		collapsed = store != null && store.isCollapsed(key);
		applyCollapsedState();
	}

	/** The container subclasses add their content to. */
	protected final JPanel body()
	{
		return body;
	}

	/**
	 * The one-line summary shown on the header when collapsed. Called both on
	 * toggle and after every {@link #apply(SessionSnapshot)} via
	 * {@link #refreshSummary()}. May return {@code "-"} before any data.
	 */
	protected abstract String summaryText();

	/** Refresh this section's labels from a new snapshot. */
	public abstract void apply(SessionSnapshot snapshot);

	/**
	 * Removes any game-canvas overlays this section's categories may have
	 * added (see {@code com.ospulse.ui.category.CategoryController}'s
	 * "Add to canvas" action). No-op by default; sections that wire up
	 * per-category canvas overlays override this so a plugin toggle or
	 * shutdown doesn't leak overlays. Called from the Swing EDT.
	 */
	public void removeAllCategoryOverlays()
	{
	}

	/**
	 * Wipes any state this section has <em>retained across snapshots</em> — the
	 * accumulating maps, cached baselines, "last seen" anchors, frozen values
	 * and hidden/collapsed selections that {@link #apply(SessionSnapshot)}
	 * carries forward — back to its just-constructed state. No-op by default;
	 * sections that retain such state override this (feature 11: full Reset).
	 *
	 * <p>Called on the Swing EDT from {@link OSPulsePanel}'s Reset button
	 * <em>before</em> the tracker's {@code resetSession()} fires the fresh
	 * post-reset snapshot, so the next {@code apply} recomputes deltas against a
	 * cleared baseline rather than showing a phantom carry-over.
	 */
	public void resetState()
	{
	}

	/** Subclasses MUST call this at the end of {@link #apply}. */
	protected final void refreshSummary()
	{
		if (collapsed)
		{
			summaryLabel.setText(summaryText());
		}
	}

	private void toggle()
	{
		collapsed = !collapsed;
		if (store != null)
		{
			store.setCollapsed(key, collapsed);
		}
		applyCollapsedState();
	}

	private void applyCollapsedState()
	{
		triangleLabel.setText(collapsed ? "▸" : "▾"); // ▸ / ▾
		body.setVisible(!collapsed);
		summaryLabel.setText(collapsed ? summaryText() : "");
		revalidate();
		repaint();
	}
}

package com.ospulse.integration;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.util.Text;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;

/**
 * Filters the open bank down to a set of recommended items using RuneLite's
 * Bank Tags system (same mechanism as the Inventory Setups plugin), arranged in
 * the in-game equipment grid via a Bank Tags <em>layout</em>. Owns a single
 * reserved hidden tag + its layout so the user's own tags are never touched.
 */
public class BankRecommendationHighlighter
{
    public static final String RESERVED_TAG = "ospulse-recommended";

    private static final String BANKTAGS_GROUP = "banktags";
    private static final String LAYOUT_KEY = "layout_" + Text.standardize(RESERVED_TAG);

    // NO_LAYOUT is deliberately absent so openBankTag renders our equipment grid.
    private static final int OPEN_OPTIONS = BankTagsService.OPTION_HIDE_TAG_NAME;

    // ---- Bank Tag Layouts (hub plugin) interop --------------------------------
    // If the popular "Bank Tag Layouts" hub plugin is installed, it re-lays-out
    // any open bank tag it considers "layout-enabled" AFTER the core Bank Tags
    // LayoutManager has drawn ours (it subscribes to ScriptPostFired
    // BANKMAIN_BUILD at priority -1, while core layouts render in ScriptPreFired
    // BANKMAIN_FINISHBUILDING, which is nested inside bankmain_build) — so it
    // always wins, repacking the items densely from slot 0 and persisting that
    // dense order to its own banktaglayouts.layout_<tag> config. It only backs
    // off a core layout when the tag has a real TagTab (tabManager.find(tag) !=
    // null in its isVanillaLayoutEnabled) — our reserved tag is hidden and
    // never in banktags.tagtabs, so it fails that check and hijacks the grid.
    // Its documented escape hatch is writing the literal marker "DISABLED" into
    // its layout_<tag> key (BankTagLayoutsPlugin.LAYOUT_EXPLICITLY_DISABLED):
    // hasLayoutEnabled()/getBankOrder() then return null and it leaves the tag
    // entirely to core Bank Tags. Writing the marker is inert when the plugin
    // isn't installed, and also overwrites any dense layout it already saved.
    private static final String BTL_GROUP = "banktaglayouts";
    private static final String BTL_LAYOUT_KEY = "layout_" + Text.standardize(RESERVED_TAG);
    private static final String BTL_LAYOUT_DISABLED = "DISABLED";

    /** Bank grid width (items per row) that the Bank Tags layout array is indexed against. */
    private static final int BANK_COLS = 8;
    /** Flat layout array length — index 34 (ring) is the last equipment cell. */
    private static final int LAYOUT_SIZE = 35;
    /** First flat index of the row immediately beneath the equipment block (row 5). */
    private static final int CONSUMABLES_START = 5 * BANK_COLS;

    /**
     * Equipment slot ordinal -> flat bank-grid index (row*8 + col), mirroring the
     * in-game equipment layout Inventory Setups uses:
     * row1 col2 helmet; row2 cape/amulet/ammo; row3 weapon/chest/shield;
     * row4 legs; row5 gloves/boots/ring.
     */
    private static final Map<Integer, Integer> SLOT_TO_GRID = new LinkedHashMap<>();
    static
    {
        SLOT_TO_GRID.put(0, 0 * BANK_COLS + 1);   // HEAD   -> (1,2) = 1
        SLOT_TO_GRID.put(1, 1 * BANK_COLS + 0);   // CAPE   -> (2,1) = 8
        SLOT_TO_GRID.put(2, 1 * BANK_COLS + 1);   // AMULET -> (2,2) = 9
        SLOT_TO_GRID.put(13, 1 * BANK_COLS + 2);  // AMMO   -> (2,3) = 10
        SLOT_TO_GRID.put(3, 2 * BANK_COLS + 0);   // WEAPON -> (3,1) = 16
        SLOT_TO_GRID.put(4, 2 * BANK_COLS + 1);   // BODY   -> (3,2) = 17
        SLOT_TO_GRID.put(5, 2 * BANK_COLS + 2);   // SHIELD -> (3,3) = 18
        SLOT_TO_GRID.put(7, 3 * BANK_COLS + 1);   // LEGS   -> (4,2) = 25
        SLOT_TO_GRID.put(9, 4 * BANK_COLS + 0);   // GLOVES -> (5,1) = 32
        SLOT_TO_GRID.put(10, 4 * BANK_COLS + 1);  // BOOTS  -> (5,2) = 33
        SLOT_TO_GRID.put(12, 4 * BANK_COLS + 2);  // RING   -> (5,3) = 34
    }

    private final BankTagsService bankTags;      // nullable
    private final TagManager tagManager;         // nullable
    private final ConfigManager configManager;   // nullable
    private final ClientThread clientThread;

    // slot ordinal -> item id. Written on the EDT, read on the client thread.
    private Map<Integer, Integer> current = new LinkedHashMap<>();
    // Consumable item ids (potions etc.) to tag/lay out beneath the equipment
    // grid — order-preserving, deduplicated, and disjoint from current's
    // values (see showInBank). Written on the EDT, read on the client thread.
    private List<Integer> currentConsumables = new ArrayList<>();
    // Written on the EDT (showInBank/clear), read on the client thread (reapplyIfArmed).
    private volatile boolean armed;
    // Written on the EDT (suspend/resume via the panel's HierarchyListener), read on
    // the client thread (reapplyIfArmed) — true while the OSPulse panel is not showing.
    private volatile boolean suspended;

    public BankRecommendationHighlighter(BankTagsService bankTags, TagManager tagManager,
                                         ConfigManager configManager, ClientThread clientThread)
    {
        this.bankTags = bankTags;
        this.tagManager = tagManager;
        this.configManager = configManager;
        this.clientThread = clientThread;
    }

    public boolean isArmed()
    {
        return armed;
    }

    /**
     * Show the given recommended items, keyed by equipment slot ordinal so they
     * can be laid out in the equipment grid. Equivalent to calling the
     * consumables-aware overload with an empty list.
     */
    public void showInBank(Map<Integer, Integer> slotToItemId)
    {
        showInBank(slotToItemId, null);
    }

    /**
     * Show the given recommended equipment (keyed by slot ordinal, laid out in
     * the equipment grid as before) plus a "don't forget" consumables list
     * (e.g. an antifire potion) tagged and placed on a fresh row beneath the
     * equipment block. Layout contract: equipment always occupies the fixed
     * grid rows (indices 0–34 via {@link #SLOT_TO_GRID}); consumables start at
     * the first cell of the next full row after that block (index {@code 5 *
     * BANK_COLS}) and fill left-to-right, never touching an equipment cell.
     * Only the equipment-bearing subset of a monster's consumables reminder
     * can ever appear here — prose-only reminders (e.g. Zulrah's antivenom
     * note) carry no item ids and so have nothing to pass.
     */
    public void showInBank(Map<Integer, Integer> slotToItemId, List<Integer> consumableItemIds)
    {
        if (bankTags == null || tagManager == null || configManager == null
            || clientThread == null || slotToItemId == null)
        {
            return;
        }
        Map<Integer, Integer> snapshot = new LinkedHashMap<>();
        for (Map.Entry<Integer, Integer> e : slotToItemId.entrySet())
        {
            if (e.getKey() != null && e.getValue() != null && e.getValue() > 0)
            {
                snapshot.put(e.getKey(), e.getValue());
            }
        }
        List<Integer> consumablesSnapshot = new ArrayList<>();
        if (consumableItemIds != null)
        {
            java.util.Set<Integer> seen = new LinkedHashSet<>();
            for (Integer id : consumableItemIds)
            {
                if (id != null && id > 0 && !snapshot.containsValue(id) && seen.add(id))
                {
                    consumablesSnapshot.add(id);
                }
            }
        }
        armed = true;
        suspended = false;
        clientThread.invoke(() ->
        {
            current = snapshot;
            currentConsumables = consumablesSnapshot;
            applyReserved();
        });
    }

    /**
     * Re-open the filtered grid if armed (bank re-open, or OSPulse panel
     * re-activated). Refuses to re-open while {@link #suspended} — i.e. while
     * the OSPulse panel isn't the active side panel. While suspended it
     * defensively re-closes the tag on every bank-open instead of doing
     * nothing: {@link #suspend()}'s {@code closeBankTag()} only clears core
     * Bank Tags' own active-tag bookkeeping ({@code TabInterface.closeTag}
     * hard-codes {@code relayout=false}, skipping the bank-search relayout),
     * so the next full bank rebuild can re-surface the stale filtered view for
     * one frame, entirely outside this {@code suspended} check. Re-closing on
     * every suspended bank-open stomps that out immediately instead of letting
     * it flicker back once (item #5).
     */
    public void reapplyIfArmed()
    {
        if (!armed || bankTags == null || tagManager == null || configManager == null || clientThread == null)
        {
            return;
        }
        if (suspended)
        {
            clientThread.invoke(bankTags::closeBankTag);
            return;
        }
        clientThread.invoke(this::applyReserved);
    }

    /**
     * Hide the filtered view WITHOUT disarming, so re-activating the OSPulse
     * panel (or re-opening the bank) restores it — used when the user switches
     * to another side-panel plugin (e.g. Inventory Setups). Also records the
     * suspended state so {@link #reapplyIfArmed()} refuses to re-show the
     * filtered grid on a bank re-open while the panel is inactive (B8-8 follow-up).
     */
    public void suspend()
    {
        suspended = true;
        if (armed && bankTags != null && clientThread != null)
        {
            clientThread.invoke(bankTags::closeBankTag);
        }
    }

    /**
     * Re-activate after {@link #suspend()} — called when the OSPulse panel
     * becomes the shown side panel again. Clears the suspended state and, if
     * still armed, re-applies the filtered grid immediately.
     */
    public void resume()
    {
        suspended = false;
        reapplyIfArmed();
    }

    public void clear()
    {
        armed = false;
        suspended = false;
        if (tagManager == null || bankTags == null || configManager == null || clientThread == null)
        {
            return;
        }
        clientThread.invoke(() ->
        {
            current = new LinkedHashMap<>();
            currentConsumables = new ArrayList<>();
            tagManager.removeTag(RESERVED_TAG);
            configManager.unsetConfiguration(BANKTAGS_GROUP, LAYOUT_KEY);
            configManager.unsetConfiguration(BTL_GROUP, BTL_LAYOUT_KEY);
            bankTags.closeBankTag();
        });
    }

    private void applyReserved()
    {
        tagManager.removeTag(RESERVED_TAG);              // reset — never accumulate
        tagManager.setHidden(RESERVED_TAG, true);
        for (int id : current.values())
        {
            tagManager.addTag(id, RESERVED_TAG, false);
        }
        for (int id : currentConsumables)
        {
            tagManager.addTag(id, RESERVED_TAG, false);
        }
        writeLayout();
        // Keep Bank Tag Layouts (if installed) off our reserved tag — see the
        // BTL_* constants. Must precede openBankTag so the first rebuild after
        // opening already sees the marker.
        configManager.setConfiguration(BTL_GROUP, BTL_LAYOUT_KEY, BTL_LAYOUT_DISABLED);
        bankTags.openBankTag(RESERVED_TAG, OPEN_OPTIONS);
    }

    /**
     * Persist the equipment-grid layout, plus any consumables on a fresh row
     * beneath it, as the banktags {@code layout_<tag>} CSV the client
     * auto-loads.
     */
    private void writeLayout()
    {
        int size = currentConsumables.isEmpty()
            ? LAYOUT_SIZE
            : CONSUMABLES_START + currentConsumables.size();
        int[] grid = new int[size];
        Arrays.fill(grid, -1);                            // -1 = empty cell
        for (Map.Entry<Integer, Integer> e : current.entrySet())
        {
            Integer idx = SLOT_TO_GRID.get(e.getKey());
            if (idx != null && idx >= 0 && idx < grid.length)
            {
                grid[idx] = e.getValue();
            }
        }
        for (int i = 0; i < currentConsumables.size(); i++)
        {
            grid[CONSUMABLES_START + i] = currentConsumables.get(i);
        }
        StringBuilder csv = new StringBuilder();
        for (int i = 0; i < grid.length; i++)
        {
            if (i > 0)
            {
                csv.append(',');
            }
            csv.append(grid[i]);
        }
        configManager.setConfiguration(BANKTAGS_GROUP, LAYOUT_KEY, csv.toString());
    }
}

package com.ospulse.integration;

/**
 * Pure arithmetic for the tracked-wealth value still <em>locked in</em> the
 * Grand Exchange for an active offer. No RuneLite imports, so it's directly
 * unit-testable.
 *
 * <p>The guiding rule is conservative: only count value that has definitively
 * left your inventory/bank and cannot already be sitting there again. We
 * therefore never count the "collectable" side of an offer — bought items or
 * sale proceeds waiting in the collection box — because RuneLite gives us no
 * way to tell whether the player has already collected it into their
 * inventory. (A partial collect does not change the offer's
 * {@code quantitySold}/{@code spent}, so it is invisible to us.) Counting the
 * collectable side would double-count anything already collected and invent
 * net worth that does not exist — the one error a wealth tracker must never
 * make. Counting only the still-locked side can transiently <em>under</em>-count
 * uncollected winnings, but that self-corrects the instant they are collected
 * (they reappear in the inventory) and never shows a phantom gain.
 *
 * <p><b>BUY offer:</b> coins are escrowed up-front for the whole order; as items
 * are bought, the coins for that portion turn into items (plus any price-
 * improvement refund) that sit in the collection box — or get collected into
 * the inventory, indistinguishable to us. Only the escrow for the
 * not-yet-bought quantity is still definitively locked:
 * {@code price * (totalQuantity - quantitySold)}. A fully-bought offer is
 * therefore worth 0 here (everything is collectable).
 *
 * <p><b>SELL offer:</b> the unsold items are still locked in the exchange,
 * valued at current market price: {@code unitValue * (totalQuantity -
 * quantitySold)}. Proceeds from the sold portion are collectable and so are
 * <em>not</em> counted here.
 *
 * <p><b>Cancelled offers</b> hold nothing locked — the unbought coins / unsold
 * items are returned to the collection box awaiting collection — so the caller
 * values them at 0 (see {@code SessionTracker}); they too self-correct on
 * collect.
 */
public final class GeValuation
{
	private GeValuation()
	{
	}

	/**
	 * Coins still escrowed for the not-yet-bought portion of a buy offer.
	 * {@code quantitySold} is the amount bought so far; anything already bought
	 * is collectable and deliberately excluded.
	 */
	public static long buyOfferValue(long pricePerItem, long totalQuantity, long quantitySold)
	{
		long remaining = totalQuantity - quantitySold;
		if (remaining < 0)
		{
			remaining = 0;
		}
		return pricePerItem * remaining;
	}

	/**
	 * Current market value of the unsold portion still locked in a sell offer.
	 * Proceeds already received ({@code spent}) are collectable and deliberately
	 * excluded.
	 */
	public static long sellOfferValue(long unitValue, long totalQuantity, long quantitySold)
	{
		long remaining = totalQuantity - quantitySold;
		if (remaining < 0)
		{
			remaining = 0;
		}
		return unitValue * remaining;
	}
}

