	// ------------------------------------------------------------- internals

	private void bootstrapSession(long ts)
	{
		loadBankCache();
		xpTracker.start(captureXpBaseline());
		lootBySource.clear();
		// Round-2 bot-review Finding A: same rationale as resetSession() — a
		// genuine login must not carry a stale pre-login receipt forward to
		// silently swallow a fresh-session pickup that happens to land within
		// OUTSTANDING_RECEIPT_WINDOW_MS of it.
		outstandingReceipts.clear();
		geReconciler.reset();
		// Restore the GE cost-basis ledger immediately after the reset, so a buy
		// made in an earlier session (before this relog/login) still has its
		// cost basis when it's eventually sold — otherwise the reset above would
		// wipe it and a weeks-old buy sold after this relog would credit zero
		// flip P&L instead of the correct sale-minus-basis-minus-tax profit.
		loadGeLedger();
		// A genuine login (not a mere zone hop, and not the panel's manual
		// session-value reset — see resetSession()'s javadoc) is the only point
		// the barrel's inferred contents should be wiped: unlike bank/pouches,
		// there's no server-side state to re-derive them from afterwards, so
		// starting "unknown" is safer than carrying over a stale guess from a
		// different login. Prime its inventory/equipment shadow copies from the
		// live containers immediately after, so the first onItemContainerChanged
		// diff is against real contents rather than empty maps.
		fishBarrelTracker.reset();
		fishBarrelTracker.primeContainers();
		// Start the fresh session with an empty signal builder (see #refresh).
		pendingSignals = MovementSignals.builder();
		primeGeOffers();
		WealthSnapshot initial = buildWealth(ts);
		engine.startSession(initial, ts);
		started = true;
		publish(buildSnapshot(initial, ts, true));
	}

	/**
	 * Recompute + publish the panel snapshot for responsiveness WITHOUT advancing
	 * the engine baseline or draining movement signals — used on eager
	 * container-change / loot events that can fire several times within one game
	 * tick.
	 */
	private void previewRefresh(long ts)
	{
		refresh(ts, false);
	}

	/**
	 * Drive the engine forward.
	 *
	 * <p>Only the authoritative per-tick call ({@code commit == true}, from
	 * {@link #onTick()}) drains the tick's accumulated {@link MovementSignals} and
	 * advances the engine baseline — i.e. books exactly ONE economic transaction
	 * per game tick. Eager container/loot events ({@code commit == false}) only
	 * recompute a read-only preview snapshot; they must not commit, because a
	 * single tick's inventory effects can span several {@code ItemContainerChanged}
	 * events (die-then-reclaim, search-all bird nests, drop/destroy across ticks).
	 * Committing per-event fragmented one transaction into several, draining the
	 * {@code died}/drop signals on the first event and snapping the baseline
	 * forward so later events (e.g. reclaimed gear) mis-booked as fresh loot. This
	 * mirrors the barrel-signal discipline already documented in {@link #onTick()}.
	 */
	private void refresh(long ts, boolean commit)
	{
		WealthSnapshot current = buildWealth(ts);
		if (commit)
		{
			// Let overdue GE attribution expectations lapse before the engine
			// consumes from the ledger; the ledger itself persists across ticks
			// so a collection landing seconds (or minutes) after its offer
			// filled is still attributed to the GE instead of booking as loot.
			geReconciler.expireAttributions(ts);
			// Keep the engine's verbose-diagnostics flag current so the config
			// toggle takes effect live (no restart) for the per-update log.
			engine.setVerboseDiagnostics(config.verboseDiagnostics());
			// The production animation is a per-tick STATE, not an event: it is
			// read here rather than accumulated in the builder, because
			// AnimationChanged fires on transitions only and a bulk craft holds
			// one animation across many ticks — an event-only signal would go
			// quiet mid-episode and let it idle shut under the player.
			if (ProductionActivity.isProductionAnimation(currentAnimationId))
			{
				pendingSignals.productionAnimation();
			}
			// Drain this tick's accumulated Drop/Destroy/Death signals (see
			// #recordDrop / #recordDestroy / #recordDeath) into the engine, then
			// reset the builder so the next tick starts empty.
			MovementSignals signals = pendingSignals.build();
			pendingSignals = MovementSignals.builder();
			engine.update(current, geReconciler, signals, ts);
			attributeDiffLoot(ts, signals, engine.lastUpdateDiffLoot());
		}
		publish(buildSnapshot(current, ts, commit));
	}

	/**
	 * Seeds the GE reconciler's per-slot incremental tracking from the live
	 * offers at session start (fresh login, world hop, manual reset), so the
	 * already-transacted portion of a pre-session offer is never re-counted
	 * as new session movement. Without this, the first offer event after a
	 * reset reads the offer's whole cumulative fill as a fresh increment —
	 * resurrecting pre-session flip P&amp;L and planting phantom collection
	 * expectations that could swallow genuine loot. MUST be called on the
	 * client thread, right after {@link GeReconciler#reset()}.
	 */
	private void primeGeOffers()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		for (int slot = 0; slot < offers.length; slot++)
		{
			GrandExchangeOffer offer = offers[slot];
			if (offer == null)
			{
				continue;
			}
			geReconciler.primeCollectable(slot, GeOfferStateMapper.map(offer.getState()),
				offer.getItemId(), offer.getQuantitySold(), offer.getSpent(), offer.getPrice());
		}
	}

	/**
	 * Builds the published snapshot: the engine's wealth/loot view decorated
	 * with the per-skill XP progress views and overall XP rate computed from
	 * the {@link XpTracker} and the {@link LevelTable}.
	 *
	 * <p>Review finding 5: {@code commit} is forwarded to {@link
	 * SessionEngine#snapshot(WealthSnapshot, long, List, List, Map, long, long, boolean)}
	 * unchanged — {@code false} (an eager, non-committing preview — see
	 * {@link #previewRefresh}) must not let the engine advance its
	 * bookkeeping (start net worth / baseline / stale-bank-drop tracking /
	 * diagnostic log baseline) ahead of the tick's one authoritative commit.
	 */
	private SessionSnapshot buildSnapshot(WealthSnapshot current, long ts, boolean commit)
	{
		SessionSnapshot base = engine.snapshot(current, geReconciler.realizedPnl(),
			buildGeOffers(), buildLootSources(), xpTracker.gained(), xpTracker.totalGained(), ts, commit);

		long elapsedMs = base.getElapsedMs();
		long overallXpPerHour = elapsedMs > 0
			? base.getXpTotal() * 3_600_000L / elapsedMs
			: 0L;

		return new SessionSnapshot(
			base.getStartMs(),
			elapsedMs,
			base.getLootValue(),
			base.getProfitPerHour(),
			base.getGeRealizedPnl(),
			base.getNetWorthDelta(),
			base.isBankKnown(),
			base.getLoot(),
			base.getXpGained(),
			base.getXpTotal(),
			base.getWealth(),
			base.getGeOffers(),
			base.getLootSources(),
			buildXpSkillViews(base.getXpGained(), elapsedMs),
			overallXpPerHour,
			buildGear(),
			base.getUnrealizedPnl(),
			base.getHoldingPnls(),
			base.getSuppliesUsed(),
			base.getGePositions(),
			base.getBankDelta());
	}

	/**
	 * Builds a fresh {@link GearSnapshot} from the live client state: worn
	 * equipment ids (by {@link EquipmentInventorySlot} ordinal — the
	 * EQUIPMENT container's slot index matches the ordinal), boosted+base
	 * combat levels, and active offensive prayers. MUST be called on the
	 * client thread (mirrors {@link #buildWealth(long)}).
	 *
	 * <p>Reuses the existing EQUIPMENT container read ({@link #buildWealth}
	 * already reads it for gp value) but keeps per-slot item ids instead of
	 * just summing value.
	 */
	private GearSnapshot buildGear()
	{
		int[] equippedItemIds = new int[EquipmentInventorySlot.values().length];
		java.util.Arrays.fill(equippedItemIds, -1);

		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment != null)
		{
			Item[] items = equipment.getItems();
			for (int slot = 0; slot < items.length && slot < equippedItemIds.length; slot++)
			{
				Item item = items[slot];
				if (item != null && item.getId() > 0 && item.getQuantity() > 0)
				{
					equippedItemIds[slot] = item.getId();
				}
			}
		}

		Set<OffensivePrayer> activePrayers = EnumSet.noneOf(OffensivePrayer.class);
		for (OffensivePrayer prayer : OffensivePrayer.values())
		{
			// Names are shared 1:1 between com.ospulse.combat.OffensivePrayer and
			// net.runelite.api.Prayer for every offensive prayer we model (verified
			// against the resolved 1.12.31.1 client jar).
			try
			{
				Prayer runeLitePrayer = Prayer.valueOf(prayer.name());
				if (client.isPrayerActive(runeLitePrayer))
				{
					activePrayers.add(prayer);
				}
			}
			catch (IllegalArgumentException e)
			{
				// No matching RuneLite prayer for this name - skip.
			}
		}

		GearMapper.SlotStatsLookup lookup = this::lookupSlotStats;
		EquipmentStats equipmentStats = GearMapper.buildEquipmentStats(
			equippedItemIds, EquipmentInventorySlot.WEAPON.ordinal(), lookup,
			BlowpipeDart.fromConfig(configManager).rangedStrength());

		// The player's set autocast spell, as the game's internal autocast id
		// (VarbitID.AUTOCAST_SPELL, 276). We don't yet have the value->Spell
		// mapping (it's cache data), so capture the raw value on the snapshot and
		// log it: an in-client pass that autocasts each spell reveals the mapping,
		// which then lets the magic readout show the actual current cast instead
		// of the next-best-DPS fallback (GearSection secondary readout TODO).
		int autocastSpellId = client.getVarbitValue(net.runelite.api.gameval.VarbitID.AUTOCAST_SPELL);
		if (log.isDebugEnabled())
		{
			log.debug("[autocast] varbit276={} spellbook={} weaponId={}",
				autocastSpellId,
				client.getVarbitValue(net.runelite.api.gameval.VarbitID.SPELLBOOK),
				equippedItemIds[EquipmentInventorySlot.WEAPON.ordinal()]);
		}

		return GearSnapshot.builder()
			.equippedItemIds(equippedItemIds)
			.attack(client.getRealSkillLevel(Skill.ATTACK), client.getBoostedSkillLevel(Skill.ATTACK))
			.strength(client.getRealSkillLevel(Skill.STRENGTH), client.getBoostedSkillLevel(Skill.STRENGTH))
			.defence(client.getRealSkillLevel(Skill.DEFENCE), client.getBoostedSkillLevel(Skill.DEFENCE))
			.ranged(client.getRealSkillLevel(Skill.RANGED), client.getBoostedSkillLevel(Skill.RANGED))
			.magic(client.getRealSkillLevel(Skill.MAGIC), client.getBoostedSkillLevel(Skill.MAGIC))
			.prayer(client.getRealSkillLevel(Skill.PRAYER), client.getBoostedSkillLevel(Skill.PRAYER))
			.hitpoints(client.getRealSkillLevel(Skill.HITPOINTS), client.getBoostedSkillLevel(Skill.HITPOINTS))
			.slayer(client.getRealSkillLevel(Skill.SLAYER), client.getBoostedSkillLevel(Skill.SLAYER))
			.agility(client.getRealSkillLevel(Skill.AGILITY), client.getBoostedSkillLevel(Skill.AGILITY))
			.activePrayers(activePrayers)
			// TODO Phase 2+: on-task Slayer detection has no confirmed live read yet.
			.onSlayerTask(false)
			.equipmentStats(equipmentStats)
			.autocastSpellId(autocastSpellId)
			.build();
	}

	/**
	 * Real {@link ItemManager}-backed lookup for {@link GearMapper#buildEquipmentStats}.
	 * MUST be called on the client thread — {@link ItemManager#getItemStats(int)}
	 * internally calls {@code getItemComposition}, which asserts the client
	 * thread and throws if invoked from the EDT (this is exactly what {@link
	 * #buildGear()} exists to avoid: it runs here, on the client thread, once
	 * per tick, so the UI layer never needs to call this itself).
	 */
	private GearMapper.SlotStats lookupSlotStats(int itemId)
	{
		if (itemManager == null || itemId <= 0)
		{
			return null;
		}

		// Numeric bonuses come from the bundled clean-room cache data
		// ({@link EquipmentStatsRepository}) — licence-free and shareable with a
		// future non-RuneLite build. RuneLite's wiki-derived getItemStats() is
		// retained only for the two-handed flag (not cache-derivable) and as the
		// fallback for the rare item absent from the cache data.
		EquipmentStatsRepository.Stats cache = EquipmentStatsRepository.getInstance().statsFor(itemId);

		ItemStats stats = itemManager.getItemStats(itemId);
		ItemEquipmentStats eq = (stats != null && stats.isEquipable()) ? stats.getEquipment() : null;

		if (cache != null)
		{
			boolean isTwoHanded = eq != null && eq.isTwoHanded();
			return new GearMapper.SlotStats(
				cache.astab(), cache.aslash(), cache.acrush(), cache.amagic(), cache.arange(),
				cache.dstab(), cache.dslash(), cache.dcrush(), cache.dmagic(), cache.drange(),
				cache.str(), cache.rstr(), cache.mdmg(), cache.prayer(), cache.aspeed(), isTwoHanded);
		}

		// Cache miss — fall back to RuneLite's wiki-derived numbers (unchanged behaviour).
		if (eq == null)
		{
			return null;
		}
		return new GearMapper.SlotStats(
			eq.getAstab(), eq.getAslash(), eq.getAcrush(), eq.getAmagic(), eq.getArange(),
			eq.getDstab(), eq.getDslash(), eq.getDcrush(), eq.getDmagic(), eq.getDrange(),
			eq.getStr(), eq.getRstr(), eq.getMdmg(), eq.getPrayer(), eq.getAspeed(), eq.isTwoHanded());
	}

	/**
	 * Computes the RuneLite-xptracker-style per-skill views for every skill
	 * with a positive gain this session, ordered by XP gained descending.
	 * Actions-left uses the XP of the most recently observed gain event as the
	 * per-action size, so it reads -1 (unknown) until the first action of the
	 * session has been seen for that skill.
	 *
	 * <p>Once a skill reaches real level 99, progress keeps going via {@link
	 * VirtualLevelTable}'s virtual levels (100..126) instead of flatlining at
	 * 99, matching RuneLite's own tracker.
	 */
	private List<XpSkillView> buildXpSkillViews(Map<String, Long> gained, long elapsedMs)
	{
		List<XpSkillView> views = new ArrayList<>();
		for (Map.Entry<String, Long> entry : gained.entrySet())
		{
			String skill = entry.getKey();
			long skillGained = entry.getValue();
			long xpPerHour = elapsedMs > 0 ? skillGained * 3_600_000L / elapsedMs : 0L;
			long currentXp = xpTracker.currentXp(skill);
			int level = LevelTable.levelForXp(currentXp);

			long xpLeft;
			long actionsLeft;
			double progress;
			if (level >= LevelTable.MAX_LEVEL)
			{
				// Past 99: keep climbing via virtual levels, up to the 126 cap.
				level = VirtualLevelTable.levelForXp(currentXp);
				if (level >= VirtualLevelTable.MAX_LEVEL)
				{
					xpLeft = 0L;
					actionsLeft = -1L;
					progress = 1.0;
				}
				else
				{
					long levelFloor = VirtualLevelTable.xpForLevel(level);
					long levelCeiling = VirtualLevelTable.xpForLevel(level + 1);
					xpLeft = levelCeiling - currentXp;
					progress = (double) (currentXp - levelFloor) / (levelCeiling - levelFloor);
					long lastActionXp = xpTracker.lastActionXp(skill);
					actionsLeft = lastActionXp > 0
						? (xpLeft + lastActionXp - 1) / lastActionXp
						: -1L;
				}
			}
			else
			{
				long levelFloor = LevelTable.xpForLevel(level);
				long levelCeiling = LevelTable.xpForLevel(level + 1);
				xpLeft = levelCeiling - currentXp;
				progress = (double) (currentXp - levelFloor) / (levelCeiling - levelFloor);
				long lastActionXp = xpTracker.lastActionXp(skill);
				actionsLeft = lastActionXp > 0
					? (xpLeft + lastActionXp - 1) / lastActionXp
					: -1L;
			}

			views.add(new XpSkillView(skill, skillGained, xpPerHour, currentXp,
				level, xpLeft, actionsLeft, progress));
		}
		views.sort((a, b) -> Long.compare(b.getGained(), a.getGained()));
		return views;
	}

	private void publish(SessionSnapshot snapshot)
	{
		this.latest = snapshot;
		for (SessionListener listener : listeners)
		{
			listener.onSessionUpdate(snapshot);
		}
	}

	private Map<String, Long> captureXpBaseline()
	{
		Map<String, Long> baseline = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			// OVERALL is a pseudo-skill (sum of all others); it has no
			// meaningful independent xp reading for baselining.
			if (skill == Skill.OVERALL)
			{
				continue;
			}
			baseline.put(skill.name(), (long) client.getSkillExperience(skill));
		}
		return baseline;
	}

	/**
	 * Builds a fresh {@link WealthSnapshot} from the live client state.
	 * MUST be called on the client thread.
	 */
	private WealthSnapshot buildWealth(long tsMs)
	{
		Map<Integer, ItemStack> tracked = new LinkedHashMap<>();
		Map<Integer, ItemStack> allHoldings = new LinkedHashMap<>();

		long inventoryValue = accumulateContainer(
			client.getItemContainer(InventoryID.INVENTORY), tracked, allHoldings, null);
		long equipmentValue = accumulateContainer(
			client.getItemContainer(InventoryID.EQUIPMENT), tracked, allHoldings, null);

		// The bank container is only readable while the bank is open. When it is,
		// capture its contents (for the panel AND the per-account cache); when it
		// isn't, fall back to the cached contents so the bank value and top
		// holdings survive relogs without the player reopening the bank. Bank
		// contents feed topHoldings only, never trackedItems.
		ItemContainer bankContainer = client.getItemContainer(InventoryID.BANK);
		long bankValue;
		if (bankContainer != null)
		{
			Map<Integer, ItemStack> liveBank = new LinkedHashMap<>();
			bankValue = accumulateContainer(bankContainer, null, allHoldings, liveBank);
			cachedBankItems = liveBank;
			lastKnownBankValue = bankValue;
			bankEverSeen = true;
		}
		else if (!cachedBankItems.isEmpty())
		{
			// Re-price the cached bank from live GE prices and fold it into the
			// top holdings so the panel shows the bank even while it's closed.
			long total = 0L;
			for (ItemStack stack : cachedBankItems.values())
			{
				long unit = valuation.unitValue(stack.getId());
				total += unit * stack.getQuantity();
				mergeItem(allHoldings, stack.getId(), stack.getName(), stack.getQuantity(), unit);
			}
			bankValue = total;
			lastKnownBankValue = total;
			bankEverSeen = true;
		}
		else
		{
			bankValue = lastKnownBankValue;
		}

		long geValue = accumulateGrandExchange();
		// Sale proceeds / bought goods sitting in the GE collection box, awaiting
		// collection. Folded into tracked wealth so net worth doesn't dip the
		// instant a sell fills and only recover when the coins are collected (the
		// still-locked geValue drops to 0 on a full fill; this replaces it until
		// the goods land in the inventory). See GeReconciler#collectableValue.
		long geCollectableValue = geReconciler.collectableValue(valuation::unitValue);

		long pouchValue = 0L;
		if (config.includePouches())
		{
			pouchValue = accumulateRunePouch(tracked, allHoldings);
			pouchValue += accumulateEssencePouches(tracked, allHoldings);
		}
		// TODO pouch valuation: looting bag contents are not reliably
		// readable client-side and are intentionally skipped.
		//
		// Fish-barrel contents are deliberately NOT folded into tracked wealth
		// here: they are booked as storage-routed loot in #onTick (see
		// FishBarrelTracker#drainCaughtToBarrel), so the engine's stored-loot
		// ledger lifts both Loot and net worth without a separate net-worth row.

		List<ItemStack> topHoldings = new ArrayList<>(allHoldings.values());
		topHoldings.sort((a, b) -> Long.compare(b.value(), a.value()));
		if (topHoldings.size() > TOP_HOLDINGS_LIMIT)
		{
			topHoldings = topHoldings.subList(0, TOP_HOLDINGS_LIMIT);
		}

		return WealthSnapshot.builder()
			.inventoryValue(inventoryValue)
			.equipmentValue(equipmentValue)
			.geInFlightValue(geValue)
			.geCollectableValue(geCollectableValue)
			.pouchValue(pouchValue)
			.bankValue(bankValue)
			.bankKnown(bankEverSeen)
			.timestampMs(tsMs)
			.topHoldings(topHoldings)
			.trackedItems(tracked)
			// The FULL owned-item map (inventory + equipment + bank + pouches),
			// untruncated — the gear optimiser's membership-based ownership
			// source (a 0-value untradeable in the bank never makes the top-50
			// cut but is still owned).
			.allHoldings(allHoldings)
			.build();
	}

	/**
	 * Sums the value of a container's items, merging each into
	 * {@code allHoldings} (and {@code trackedOrNull}, if non-null) keyed by
	 * canonical item id.
	 */
	private long accumulateContainer(
		ItemContainer container, Map<Integer, ItemStack> trackedOrNull,
		Map<Integer, ItemStack> allHoldings, Map<Integer, ItemStack> captureOrNull)
	{
		if (container == null)
		{
			return 0L;
		}

		long total = 0L;
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}

			int itemId = item.getId();
			if (valuation.isPlaceholder(itemId))
			{
				continue; // bank placeholder: reserved empty slot, not actually owned
			}
			long qty = item.getQuantity();
			int canonicalId = valuation.canonical(itemId);
			long unit = valuation.unitValue(itemId);
			String name = valuation.name(itemId);

			total += unit * qty;
			if (trackedOrNull != null)
			{
				mergeItem(trackedOrNull, canonicalId, name, qty, unit);
			}
			if (captureOrNull != null)
			{
				mergeItem(captureOrNull, canonicalId, name, qty, unit);
			}
			mergeItem(allHoldings, canonicalId, name, qty, unit);
		}
		return total;
	}

	/**
	 * Values active Grand Exchange offers by the wealth still <em>locked in</em>
	 * the exchange (see {@link GeValuation} for the conservative rule) and folds
	 * the still-locked sell items into {@code allHoldings}. GE items are never
	 * added to trackedItems (loot diffing excludes them;
	 * {@link GeReconciler#drainAttributedItemIds()} handles that instead).
	 *
	 * <p>Only the not-yet-filled portion of an offer is counted, never the
	 * collectable side (bought items / sale proceeds), because a partial collect
	 * is invisible to us and counting it would double-count anything already
	 * pulled back into the inventory. Consequently a fully-bought/-sold or
	 * cancelled offer contributes 0 here: its value is sitting in the collection
	 * box and is picked up again as soon as the player collects it.
	 *
	 * <p>GE offers are shown in their own "Grand Exchange" breakdown (see
	 * {@link #buildGeOffers()}) and are deliberately NOT folded into the top
	 * holdings, so holdings reflects only inventory/equipment/bank/pouch items.
	 */
	private long accumulateGrandExchange()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return 0L;
		}

		long total = 0L;
		for (GrandExchangeOffer offer : offers)
		{
			if (offer == null)
			{
				continue;
			}

			GeOfferState state = GeOfferStateMapper.map(offer.getState());
			if (state == GeOfferState.EMPTY)
			{
				continue;
			}

			int itemId = offer.getItemId();
			long unit = valuation.unitValue(itemId);

			switch (state)
			{
				case BUYING:
				case BOUGHT:
					// Only the coins escrowed for the not-yet-bought quantity are
					// still locked; bought items are collectable.
					total += GeValuation.buyOfferValue(
						offer.getPrice(), offer.getTotalQuantity(), offer.getQuantitySold());
					break;
				case SELLING:
				case SOLD:
					// The unsold items are still locked in the exchange; proceeds
					// from the sold portion are collectable and not counted.
					total += GeValuation.sellOfferValue(
						unit, offer.getTotalQuantity(), offer.getQuantitySold());
					break;
				case CANCELLED_BUY:
				case CANCELLED_SELL:
				default:
					// Nothing is locked any more: the returned coins / unsold items
					// sit in the collection box awaiting collection, at which point
					// they reappear in the inventory. Counting them here would risk
					// double-counting an already-collected amount.
					break;
			}
		}
		return total;
	}

	/**
	 * Builds the per-slot Grand Exchange breakdown shown in the panel: every
	 * non-empty offer, with its buy/sell direction, quantity progress and gp
	 * progress (gp moved so far out of the gp a full fill would move). Purely a
	 * display view — it does not affect wealth or loot maths. MUST be called on
	 * the client thread.
	 */
	private List<GeOfferView> buildGeOffers()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return List.of();
		}

		List<GeOfferView> views = new ArrayList<>();
		for (int slot = 0; slot < offers.length; slot++)
		{
			GrandExchangeOffer offer = offers[slot];
			if (offer == null)
			{
				continue;
			}

			GeOfferState state = GeOfferStateMapper.map(offer.getState());
			if (state == GeOfferState.EMPTY)
			{
				continue;
			}

			boolean buying = state == GeOfferState.BUYING
				|| state == GeOfferState.BOUGHT
				|| state == GeOfferState.CANCELLED_BUY;

			long price = offer.getPrice();
			long totalQty = offer.getTotalQuantity();
			long transacted = offer.getQuantitySold();

			views.add(new GeOfferView(
				buying,
				offer.getItemId(),
				valuation.name(offer.getItemId()),
				totalQty,
				transacted,
				price,
				offer.getSpent(),
				price * totalQty,
				// Absent for a buy offer or a dump (no GE cost basis matched);
				// present (possibly a small negative, the GE sales tax) for a
				// genuine flip — see GeReconciler#slotRealizedPnl.
				geReconciler.slotRealizedPnl(slot)));
		}
		return views;
	}

	/**
	 * Rune pouch valuation across all six type/amount varbit slots (covers the
	 * regular, divine and expanded pouches; unused slots read 0 and are skipped).
	 *
	 * <p>Critically, the {@code RUNE_POUCH_RUNE*} varbits do NOT hold an item id —
	 * they hold a KEY into the {@link EnumID#RUNEPOUCH_RUNE} game enum, which maps
	 * to the actual rune item id. Treating the raw varbit value as an item id
	 * (as an earlier version did) mis-identifies and mis-prices the rune, which
	 * is how a handful of runes turned into a multi-billion "pouch" holding. This
	 * mirrors RuneLite's own {@code RunepouchOverlay}.
	 */
	private long accumulateRunePouch(Map<Integer, ItemStack> tracked, Map<Integer, ItemStack> allHoldings)
	{
		EnumComposition runepouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runepouchEnum == null)
		{
			return 0L;
		}

		int[] runeVarbits = {
			Varbits.RUNE_POUCH_RUNE1, Varbits.RUNE_POUCH_RUNE2, Varbits.RUNE_POUCH_RUNE3,
			Varbits.RUNE_POUCH_RUNE4, Varbits.RUNE_POUCH_RUNE5, Varbits.RUNE_POUCH_RUNE6,
		};
		int[] amountVarbits = {
			Varbits.RUNE_POUCH_AMOUNT1, Varbits.RUNE_POUCH_AMOUNT2, Varbits.RUNE_POUCH_AMOUNT3,
			Varbits.RUNE_POUCH_AMOUNT4, Varbits.RUNE_POUCH_AMOUNT5, Varbits.RUNE_POUCH_AMOUNT6,
		};

		long total = 0L;
		for (int i = 0; i < runeVarbits.length; i++)
		{
			int runeKey = client.getVarbitValue(runeVarbits[i]);
			int amount = client.getVarbitValue(amountVarbits[i]);
			if (runeKey <= 0 || amount <= 0)
			{
				continue;
			}

			int itemId = runepouchEnum.getIntValue(runeKey);
			if (itemId <= 0)
			{
				continue;
			}

			int canonicalId = valuation.canonical(itemId);
			long unit = valuation.unitValue(itemId);
			String name = valuation.name(itemId);

			total += unit * amount;
			mergeItem(tracked, canonicalId, name, amount, unit);
			mergeItem(allHoldings, canonicalId, name, amount, unit);
		}
		return total;
	}

	/**
	 * Essence-pouch capacities (small/medium/large/giant/colossal), each keyed to
	 * its held-amount varbit. There is no per-slot rune/type varbit to resolve
	 * here (unlike the rune pouch) — a pouch just holds a count of essence.
	 */
	private enum EssencePouch
	{
		SMALL(Varbits.ESSENCE_POUCH_SMALL_AMOUNT),
		MEDIUM(Varbits.ESSENCE_POUCH_MEDIUM_AMOUNT),
		LARGE(Varbits.ESSENCE_POUCH_LARGE_AMOUNT),
		GIANT(Varbits.ESSENCE_POUCH_GIANT_AMOUNT),
		COLOSSAL(Varbits.ESSENCE_POUCH_COLOSSAL_AMOUNT);

		private final int amountVarbit;

		EssencePouch(int amountVarbit)
		{
			this.amountVarbit = amountVarbit;
		}

		int amountVarbit()
		{
			return amountVarbit;
		}
	}

	/**
	 * Essence-pouch contents are readable client-side via the pouch amount varbits
	 * (small/medium/large/giant/colossal), so their held essence is folded into
	 * tracked wealth rather than being invisible until emptied. Mirrors
	 * {@link #accumulateRunePouch}. Returns the total essence value added.
	 *
	 * <p><b>Limitation:</b> pouches don't expose a per-slot type varbit the way
	 * the rune pouch does, and the essence-type encoding (pure vs regular vs
	 * daeyalt) is not currently confirmed in-client, so all pouch contents are
	 * priced as pure essence ({@link ItemID#BLANKRUNE_HIGH}) regardless of what
	 * is actually stored. This keeps the common case (pure essence, which is
	 * what most players store and what nearly all pouches hold post-Priff)
	 * correct and empty-neutral; a pouch filled with regular or daeyalt essence
	 * may not net perfectly neutral on empty until the type varbit is confirmed
	 * and this is refined to price per-slot like the rune pouch does.
	 */
	private long accumulateEssencePouches(Map<Integer, ItemStack> tracked, Map<Integer, ItemStack> allHoldings)
	{
		long total = 0L;
		for (EssencePouch pouch : EssencePouch.values())
		{
			int amount = client.getVarbitValue(pouch.amountVarbit());
			if (amount <= 0)
			{
				continue;
			}

			int canonicalId = valuation.canonical(ItemID.BLANKRUNE_HIGH);
			long unit = valuation.unitValue(ItemID.BLANKRUNE_HIGH);
			String name = valuation.name(ItemID.BLANKRUNE_HIGH);

			total += unit * amount;
			mergeItem(tracked, canonicalId, name, amount, unit);
			mergeItem(allHoldings, canonicalId, name, amount, unit);
		}
		return total;
	}

	/**
	 * How long an unmatched, sourced loot receipt stays eligible to net against
	 * a later tick's inventory diff (see {@link #outstandingReceipts}). An
	 * ordinary ground drop is picked up on foot, which takes at least one tick
	 * and often several more — but a dropped item stays private to (and
	 * pickup-able by) the player who earned it for roughly a minute in live
	 * OSRS. This window is comfortably inside that "still plausibly the same
	 * physical drop" period, while short enough that it cannot silently net
	 * out a genuinely new, unrelated appearance of the same item id much later
	 * in the session.
	 */
	private static final long OUTSTANDING_RECEIPT_WINDOW_MS = 20_000L;

	/**
	 * Sourced receipts ({@link com.ospulse.session.LootReceipt#source} != null)
	 * not yet matched by an inventory diff, keyed by canonical item id and kept
	 * oldest-first so a later tick's pickup can still net against a receipt
	 * booked several ticks earlier. See {@link #attributeDiffLoot}. The FIFO
	 * netting/expiry logic itself lives in {@link
	 * com.ospulse.session.OutstandingReceiptLedger}, shared with {@link
	 * com.ospulse.session.SessionEngine}'s equivalent cross-tick problem for
	 * its episode-output crediting (round-2 bot-review Finding C) — this
	 * tracker's instance is separate (different quantities, different
	 * clearing points), only the mechanism is shared.
	 */
	private final com.ospulse.session.OutstandingReceiptLedger outstandingReceipts =
		new com.ospulse.session.OutstandingReceiptLedger(OUTSTANDING_RECEIPT_WINDOW_MS);

	/**
	 * Feeds this tick's inventory-diff loot into the per-source feed, so the feed
	 * reports what the player's inventory actually did rather than only what
	 * RuneLite's Loot Tracker chose to announce. Trigger-agnostic by construction:
	 * it watches the inventory, so it cannot care whether a bird nest was searched
	 * by a menu click or by anything else.
	 *
	 * <p><b>Why this cannot double-count.</b> An ordinary NPC kill is seen twice —
	 * {@link #onLootReceived} already booked its feed row, and the engine's diff
	 * (whichever tick it eventually lands on) books the same items again as LOOT
	 * residue. So each appearance is netted against the quantity a receipt has
	 * already booked, and only the shortfall is added. A kill nets to zero and
	 * adds nothing; a nest that fired no event nets against nothing and is added
	 * in full.
	 *
	 * <p><b>Why netting cannot be same-tick-only.</b> RuneLite's {@code
	 * LootReceived} for an ordinary NPC kill fires as soon as the loot is known
	 * (at the kill), not when the player later walks over and picks it up — the
	 * inventory diff for that pickup can land several ticks after the receipt.
	 * A receipt that isn't matched on its own tick is therefore not stale; it is
	 * parked in {@link #outstandingReceipts} and stays eligible to net against
	 * the diff whenever the pickup actually happens, up to {@link
	 * #OUTSTANDING_RECEIPT_WINDOW_MS}. Past that window it is dropped: either it
	 * was never picked up (looted by someone else, despawned) or matching it
	 * this late would risk swallowing a genuinely new, unrelated appearance.
	 *
	 * <p>Netting is per-quantity on the canonical item id, NOT all-or-nothing on an
	 * exact (id, quantity, unitValue) tuple. Two reasons. A tick can carry both a
	 * receipted kill and an unreceipted search of the same id, so the diff's
	 * quantity legitimately exceeds the receipt's and the remainder is real; an
	 * exact-tuple match would fail and book the whole appearance a second time.
	 * And {@code unitValue} is deliberately out of the key: both sides derive it
	 * from the same valuation for the same id, so it adds no discrimination within
	 * a tick, but the receipt is priced at event time and the diff at commit time —
	 * a price refresh in between would break a tuple match and double-count the
	 * kill, which is the exact failure this netting exists to prevent.
	 *
	 * <p>Only receipts carrying a source ({@link com.ospulse.session.LootReceipt#source})
	 * net, because those are precisely the ones {@code onLootReceived} booked a
	 * feed row for. A sourceless receipt (the fish barrel's inferred catches) never
	 * touched this feed, so netting against it would silently swallow a genuine
	 * full-barrel overflow catch that did land in the inventory.
	 */
	private void attributeDiffLoot(long ts, MovementSignals signals, List<com.ospulse.session.DiffLoot> diffLoot)
	{
		outstandingReceipts.pruneExpired(ts);

		// Fold this tick's sourced receipts into the outstanding pool BEFORE
		// netting below, so a same-tick kill+pickup still nets in full (as
		// before); a receipt with no diff this tick simply joins the pool and
		// waits for whichever later tick the pickup actually lands on.
		for (com.ospulse.session.LootReceipt r : signals.lootReceipts())
		{
			if (r.source == null)
			{
				continue;
			}
			outstandingReceipts.record(r.itemId, r.quantity, ts);
		}

		if (diffLoot.isEmpty())
		{
			return;
		}

		// One SourceAgg for the whole tick: the key must stay stable (it is the
		// panel's persisted collapse/hide identity — see UNATTRIBUTED_LOOT_SOURCE),
		// and the tick counts as a single "drop" no matter how many ids it carried.
		SourceAgg agg = null;
		for (com.ospulse.session.DiffLoot d : diffLoot)
		{
			long remaining = outstandingReceipts.claim(d.itemId, d.quantity);
			if (remaining <= 0)
			{
				continue;
			}
			if (agg == null)
			{
				agg = lootBySource.computeIfAbsent(UNATTRIBUTED_LOOT_SOURCE, k -> new SourceAgg());
				agg.count++;
				agg.lastSeq = ++lootSeq;
			}
			mergeItem(agg.items, d.itemId, d.name, remaining, d.unitValue);
		}
	}

	/**
	 * Snapshots the per-source loot aggregate into immutable {@link SourceLoot}
	 * views: items within each source sorted by value descending, and sources
	 * themselves ordered most-recently-updated first (newest drops at the top of
	 * the feed) via each source's {@link SourceAgg#lastSeq} recency stamp.
	 */
	private List<SourceLoot> buildLootSources()
	{
		// Order sources by recency (newest drop first) rather than by value, so a
		// fresh kill always appears at the top instead of being buried under an
		// older, higher-value source.
		List<Map.Entry<String, SourceAgg>> entries = new ArrayList<>(lootBySource.entrySet());
		entries.sort((a, b) -> Long.compare(b.getValue().lastSeq, a.getValue().lastSeq));

		List<SourceLoot> out = new ArrayList<>();
		for (Map.Entry<String, SourceAgg> e : entries)
		{
			List<ItemStack> items = new ArrayList<>(e.getValue().items.values());
			items.sort((a, b) -> Long.compare(b.value(), a.value()));
			long total = 0L;
			for (ItemStack s : items)
			{
				total += s.value();
			}
			out.add(new SourceLoot(e.getKey(), total, e.getValue().count, items));
		}
		return out;
	}

	private void mergeItem(Map<Integer, ItemStack> map, int canonicalId, String name, long qty, long unitValue)
	{
		ItemStack existing = map.get(canonicalId);
		long newQty = qty + (existing == null ? 0L : existing.getQuantity());
		// HA price resolved here on the client thread (getItemComposition asserts
		// it) so the EDT-side loot tooltip can read it without threading errors.
		map.put(canonicalId, new ItemStack(canonicalId, name, newQty, unitValue, valuation.haPrice(canonicalId)));
	}

	// --------------------------------------------------------- bank persistence

	/**
	 * Restores the per-account bank cache into memory at the start of a session,
	 * re-pricing every line from live GE prices so a stale cache is still valued
	 * correctly. Resets to "unknown" first so switching accounts never leaks the
	 * previous account's bank. Keyed automatically to the logged-in RS profile.
	 */
	private void loadBankCache()
	{
		cachedBankItems = new LinkedHashMap<>();
		lastKnownBankValue = 0L;
		bankEverSeen = false;

		if (configManager == null || gson == null || client.getAccountHash() == -1L)
		{
			return;
		}

		try
		{
			String json = configManager.getRSProfileConfiguration(OSPulseConfig.GROUP, BANK_CACHE_KEY);
			if (json == null || json.isEmpty())
			{
				return;
			}

			BankCache cache = gson.fromJson(json, BankCache.class);
			if (cache == null || cache.getItems().isEmpty())
			{
				return;
			}

			long total = 0L;
			for (BankCache.Entry e : cache.getItems())
			{
				if (e.getId() <= 0 || e.getQuantity() <= 0)
				{
					continue;
				}
				int canonicalId = valuation.canonical(e.getId());
				long unit = valuation.unitValue(e.getId());
				String name = valuation.name(e.getId());
				mergeItem(cachedBankItems, canonicalId, name, e.getQuantity(), unit);
				total += unit * e.getQuantity();
			}

			lastKnownBankValue = total;
			bankEverSeen = !cachedBankItems.isEmpty();
		}
		catch (Exception ex)
		{
			// Corrupt/incompatible cache — treat the bank as unknown until the
			// player next opens it, rather than failing the session bootstrap.
			log.debug("Failed to load OSPulse bank cache; ignoring", ex);
			cachedBankItems = new LinkedHashMap<>();
			lastKnownBankValue = 0L;
			bankEverSeen = false;
		}
	}

	/** Persists the current bank contents to the logged-in account's RS profile. */
	private void saveBankCache()
	{
		if (configManager == null || gson == null
			|| client.getAccountHash() == -1L || cachedBankItems.isEmpty())
		{
			return;
		}

		try
		{
			BankCache cache = new BankCache(System.currentTimeMillis(), cachedBankItems.values());
			configManager.setRSProfileConfiguration(OSPulseConfig.GROUP, BANK_CACHE_KEY, gson.toJson(cache));
		}
		catch (Exception ex)
		{
			log.debug("Failed to save OSPulse bank cache", ex);
		}
	}

	// ------------------------------------------------------ GE ledger persistence

	/**
	 * Restores the GE cost-basis buy ledger (see
	 * {@link GeReconciler#exportCostBasis()}) into the reconciler at the start
	 * of a session. Keyed automatically to the logged-in RS profile, mirroring
	 * {@link #loadBankCache()}. MUST be called right after
	 * {@link GeReconciler#reset()} so the restore isn't immediately wiped.
	 */
	private void loadGeLedger()
	{
		if (configManager == null || gson == null || client.getAccountHash() == -1L)
		{
			return;
		}

		try
		{
			String json = configManager.getRSProfileConfiguration(OSPulseConfig.GROUP, GE_LEDGER_KEY);
			if (json == null || json.isEmpty())
			{
				return;
			}

			Type type = new TypeToken<Map<Integer, GeReconciler.CostBasisSnapshot>>()
			{
			}.getType();
			Map<Integer, GeReconciler.CostBasisSnapshot> snapshot = gson.fromJson(json, type);
			geReconciler.importCostBasis(snapshot);
		}
		catch (Exception ex)
		{
			// Corrupt/incompatible ledger — treat as empty (no restored cost basis)
			// rather than failing session bootstrap; the reconciler was just reset
			// so this is a no-op, not a data loss beyond what a fresh session has.
			log.debug("Failed to load OSPulse GE cost-basis ledger; ignoring", ex);
		}
	}

	/**
	 * Persists the reconciler's current GE cost-basis buy ledger to the
	 * logged-in account's RS profile, mirroring {@link #saveBankCache()}. Not
	 * gated on the ledger being non-empty (unlike the bank cache): a ledger
	 * that has genuinely gone to zero (every open position sold) is a real
	 * state and must overwrite a stale non-empty cache.
	 */
	private void saveGeLedger()
	{
		if (configManager == null || gson == null || client.getAccountHash() == -1L)
		{
			return;
		}

		try
		{
			Map<Integer, GeReconciler.CostBasisSnapshot> snapshot = geReconciler.exportCostBasis();
			configManager.setRSProfileConfiguration(OSPulseConfig.GROUP, GE_LEDGER_KEY, gson.toJson(snapshot));
		}
		catch (Exception ex)
		{
			log.debug("Failed to save OSPulse GE cost-basis ledger", ex);
		}
	}
}

package com.ospulse.integration;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses the fish barrel's "Check" interface text (interface 193, component 2)
 * into a per-species item id -&gt; quantity breakdown.
 *
 * <p>Adapted from the community "Fish Barrel" plugin by molo-pl
 * (BSD-2-Clause, https://github.com/molo-pl/runelite-plugins, branch
 * {@code fish-barrel}) — see {@code NOTICE}. That plugin's parser only sums a
 * total fish count; this version additionally resolves each entry's species
 * name against {@link FishBarrelTracker}'s catch-message fish map so
 * {@link FishBarrelTracker} can restore an exact per-item breakdown (needed
 * to price the barrel's contents), not just a headline total.
 *
 * <p>Pure/stateless: safe to unit test without a game client.
 */
final class FishBarrelWidgetParser
{
	private static final String EMPTY_MESSAGE = "The barrel is empty.";
	private static final String MESSAGE_ENTRY_REGEX = "([0-9]+) x ([a-zA-Z ]+),? ?";
	private static final Pattern MESSAGE_ENTRY_PATTERN = Pattern.compile(MESSAGE_ENTRY_REGEX);
	private static final Pattern FULL_MESSAGE_PATTERN =
		Pattern.compile("^The barrel contains: (" + MESSAGE_ENTRY_REGEX + ")+$");

	private FishBarrelWidgetParser()
	{
	}

	/**
	 * @param message        the widget's raw text (may contain {@code <br>} line breaks)
	 * @param fishTypesByName catch-message fish name -&gt; item id map (singular form,
	 *                        e.g. "shark", "anglerfish") used to resolve each entry's
	 *                        plural display name (e.g. "Raw sharks") back to an item id
	 * @return item id -&gt; quantity, or {@code null} if the message couldn't be parsed
	 *         (unrecognised format, or an entry names a fish not in {@code fishTypesByName})
	 */
	static Map<Integer, Integer> parse(String message, Map<String, Integer> fishTypesByName)
	{
		if (message == null || message.isBlank())
		{
			return null;
		}
		String normalized = message.replace("<br>", " ").trim();

		if (EMPTY_MESSAGE.equals(normalized))
		{
			return Map.of();
		}

		if (!FULL_MESSAGE_PATTERN.matcher(normalized).matches())
		{
			return null;
		}

		Map<Integer, Integer> result = new LinkedHashMap<>();
		Matcher matcher = MESSAGE_ENTRY_PATTERN.matcher(normalized);
		while (matcher.find())
		{
			int qty;
			try
			{
				qty = Integer.parseInt(matcher.group(1));
			}
			catch (NumberFormatException e)
			{
				return null;
			}

			Integer itemId = resolveFishId(matcher.group(2), fishTypesByName);
			if (itemId == null)
			{
				// Unrecognised species text — don't silently drop it into an
				// "unknown fish" bucket; fail the whole parse so the caller keeps
				// its previous (still-attributed) state instead of a partial one.
				return null;
			}
			result.merge(itemId, qty, Integer::sum);
		}

		return result;
	}

	/**
	 * Resolves a widget entry's display name (e.g. "Raw sharks", "Raw shrimps")
	 * to an item id by matching it against the singular catch-message names in
	 * {@code fishTypesByName}, tolerating the "Raw " prefix and a trailing "s".
	 */
	private static Integer resolveFishId(String displayName, Map<String, Integer> fishTypesByName)
	{
		String cleaned = displayName.trim().toLowerCase(Locale.ROOT);
		if (cleaned.startsWith("raw "))
		{
			cleaned = cleaned.substring(4);
		}

		Integer exact = lookupCaseInsensitive(fishTypesByName, cleaned);
		if (exact != null)
		{
			return exact;
		}

		// Widget entries are pluralised (e.g. "sharks", "anglerfish" is already
		// invariant); try stripping a trailing 's' against the singular map.
		if (cleaned.endsWith("s"))
		{
			Integer singular = lookupCaseInsensitive(fishTypesByName, cleaned.substring(0, cleaned.length() - 1));
			if (singular != null)
			{
				return singular;
			}
		}

		return null;
	}

	private static Integer lookupCaseInsensitive(Map<String, Integer> map, String key)
	{
		Integer direct = map.get(key);
		if (direct != null)
		{
			return direct;
		}
		for (Map.Entry<String, Integer> entry : map.entrySet())
		{
			if (entry.getKey().toLowerCase(Locale.ROOT).equals(key))
			{
				return entry.getValue();
			}
		}
		return null;
	}
}

package com.ospulse.integration;

import com.ospulse.ge.GeOfferState;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Maps RuneLite's {@link GrandExchangeOfferState} onto the pure domain
 * {@link GeOfferState}. The two enums currently have identical members, but
 * this mapping is kept explicit (rather than {@code Enum#valueOf} by name)
 * so a RuneLite-side rename or addition doesn't silently break the domain
 * engine.
 */
public final class GeOfferStateMapper
{
	private GeOfferStateMapper()
	{
	}

	public static GeOfferState map(GrandExchangeOfferState state)
	{
		if (state == null)
		{
			return GeOfferState.EMPTY;
		}
		switch (state)
		{
			case BUYING:
				return GeOfferState.BUYING;
			case BOUGHT:
				return GeOfferState.BOUGHT;
			case SELLING:
				return GeOfferState.SELLING;
			case SOLD:
				return GeOfferState.SOLD;
			case CANCELLED_BUY:
				return GeOfferState.CANCELLED_BUY;
			case CANCELLED_SELL:
				return GeOfferState.CANCELLED_SELL;
			case EMPTY:
			default:
				return GeOfferState.EMPTY;
		}
	}
}

package com.ospulse.integration;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Infers the contents of an OPEN {@code Fish barrel} / {@code Fish sack barrel}
 * from chat messages, XP drops and inventory deltas, since a barrel toggled
 * open auto-stores caught fish directly without ever passing through the
 * inventory or firing a {@code LootReceived} event, and there is no official
 * varbit exposing its contents.
 *
 * <p>Detection approach adapted from the community "Fish Barrel" plugin by
 * molo-pl (BSD-2-Clause, https://github.com/molo-pl/runelite-plugins, branch
 * {@code fish-barrel}) — see {@code NOTICE} for the full attribution. That
 * plugin only tracks a running total fish count; this tracker additionally
 * resolves WHICH fish was caught (via the same catch-message fish-name map)
 * because OSPulse needs a priced, per-item breakdown to fold into tracked
 * wealth/net worth, not just a headline count.
 *
 * <p>All public methods must be called on the RuneLite client thread — this
 * mirrors every other live-state reader in this package (see
 * {@link SessionTracker}'s class javadoc) since {@link #onWidgetLoaded} reads
 * a widget's text, which is only safe there.
 */
public class FishBarrelTracker
{
	/** Max fish the barrel can hold, matching the in-game "barrel is full" cap. */
	public static final int CAPACITY = 28;

	private static final Collection<Integer> BARREL_IDS = List.of(
		ItemID.FISH_BARREL_CLOSED,
		ItemID.FISH_BARREL_OPEN,
		ItemID.FISH_SACK_BARREL_CLOSED,
		ItemID.FISH_SACK_BARREL_OPEN);

	private static final Collection<Integer> OPEN_BARREL_IDS = List.of(
		ItemID.FISH_BARREL_OPEN,
		ItemID.FISH_SACK_BARREL_OPEN);

	/** Matches "You catch a/an/some X[.!]" possibly followed by the ice gloves suffix. */
	private static final Pattern FISH_CAUGHT_MESSAGE = Pattern.compile(
		"^You catch (an?|some)(?: raw)? ([a-zA-Z ]+)[.!]?"
			+ "( It hardens as you handle it with your ice gloves\\.)?$");

	private static final String RADA_DOUBLE_CATCH_MESSAGE =
		"Rada's blessing enabled you to catch an extra fish.";
	private static final String FLAKES_DOUBLE_CATCH_MESSAGE =
		"The spirit flakes enabled you to catch an extra fish.";
	private static final String CORMORANT_CATCH_MESSAGE = "Your cormorant returns with its catch.";

	private static final String BANK_FULL_MESSAGE = "Your bank could not hold your fish.";
	private static final String BARREL_FULL_MESSAGE = "The barrel is full. It may be emptied at a bank.";
	private static final String BANK_EMPTY_MESSAGE = "You empty all of your containers into the bank.";
	private static final String CONTAINERS_EMPTY_MESSAGE = "Your containers are already empty.";

	/** Fish name (as it appears in the catch chat message) -&gt; item id. */
	private static final Map<String, Integer> FISH_TYPES_BY_NAME = ImmutableMap.<String, Integer>builder()
		// singular 'shrimp' may occur when fishing for Karambwanji
		.put("shrimp", ItemID.RAW_SHRIMP)
		.put("shrimps", ItemID.RAW_SHRIMP)
		.put("sardine", ItemID.RAW_SARDINE)
		.put("herring", ItemID.RAW_HERRING)
		.put("anchovies", ItemID.RAW_ANCHOVIES)
		.put("mackerel", ItemID.RAW_MACKEREL)
		.put("trout", ItemID.RAW_TROUT)
		.put("cod", ItemID.RAW_COD)
		.put("pike", ItemID.RAW_PIKE)
		.put("slimy swamp eel", ItemID.MORT_SLIMEY_EEL)
		.put("salmon", ItemID.RAW_SALMON)
		.put("tuna", ItemID.RAW_TUNA)
		.put("rainbow fish", ItemID.HUNTING_RAW_FISH_SPECIAL)
		.put("cave eel", ItemID.RAW_CAVE_EEL)
		.put("lobster", ItemID.RAW_LOBSTER)
		.put("bass", ItemID.RAW_BASS)
		.put("leaping trout", ItemID.BRUT_SPAWNING_TROUT)
		.put("swordfish", ItemID.RAW_SWORDFISH)
		.put("lava eel", ItemID.RAW_LAVA_EEL)
		.put("leaping salmon", ItemID.BRUT_SPAWNING_SALMON)
		.put("monkfish", ItemID.RAW_MONKFISH)
		.put("Karambwan", ItemID.TBWT_RAW_KARAMBWAN)
		.put("leaping sturgeon", ItemID.BRUT_STURGEON)
		.put("shark", ItemID.RAW_SHARK)
		.put("infernal eel", ItemID.INFERNAL_EEL)
		.put("anglerfish", ItemID.RAW_ANGLERFISH)
		.put("dark crab", ItemID.RAW_DARK_CRAB)
		.put("sacred eel", ItemID.SNAKEBOSS_EEL)
		.put("swordtip squid", ItemID.RAW_SWORDTIP_SQUID)
		.put("jumbo squid", ItemID.RAW_JUMBO_SQUID)
		.build();

	/** Fish caught with a cormorant on Molch island — no catch message names them individually. */
	private static final Set<Integer> MOLCH_ISLAND_FISH_TYPES = ImmutableSet.of(
		ItemID.AERIAL_FISHING_BLUEGILL,
		ItemID.AERIAL_FISHING_COMMON_TENCH,
		ItemID.AERIAL_FISHING_MOTTLED_EEL,
		ItemID.AERIAL_FISHING_GREATER_SIREN);

	/** Other fish that aren't directly caught but can still be deposited into the barrel. */
	private static final Set<Integer> OTHER_FISH_TYPES = ImmutableSet.of(
		ItemID.RAW_SEATURTLE,
		ItemID.RAW_MANTARAY);

	private static final Set<Integer> ALL_FISH_TYPES = ImmutableSet.<Integer>builder()
		.addAll(FISH_TYPES_BY_NAME.values())
		.addAll(MOLCH_ISLAND_FISH_TYPES)
		.addAll(OTHER_FISH_TYPES)
		.build();

	private static final int CHECK_WIDGET_INTERFACE = 193;
	private static final int CHECK_WIDGET_COMPONENT = 2;

	/** Barrel "Check"/"Fill"/"Empty" menu-click timeout, in game ticks. */
	private static final int ACTION_TICK_MARGIN = 3;

	private final Client client;

	/** Fish itemId -> quantity currently believed to be in the barrel. */
	private final Map<Integer, Integer> holding = new LinkedHashMap<>();
	/** Total fish held (sum of {@link #holding} values), tracked in lockstep for capacity checks. */
	private int totalHolding;
	/**
	 * True once tracking has lost confidence in {@link #holding} (e.g. the bank
	 * couldn't take all the fish, or the barrel filled with fish whose exact
	 * type split we can't attribute). Kept accurate so the capacity/full
	 * inference in {@link #addToBarrel} — which decides whether a catch is
	 * barrel-routed (booked as loot) or overflows to the inventory — stays
	 * correct; a Check-widget resync (see {@link #onWidgetLoaded}) restores a
	 * known state.
	 */
	private boolean unknown = true;

	private final Map<Integer, Integer> inventoryItems = new HashMap<>();
	private final Map<Integer, Integer> equipmentItems = new HashMap<>();

	/** Most recent fish name resolved per pending catch message this tick, in order. */
	private final List<Integer> fishCaughtThisTick = new ArrayList<>();
	private int newFishInInventoryThisTick;
	private int cookingXpDropsThisTick;

	/**
	 * Per-species count of fish actually stored INTO the barrel from catches since
	 * the last {@link #drainCaughtToBarrel()} — cook-adjusted, capacity-capped, and
	 * only ever populated by {@link #addToBarrel} (never a Fill of pre-owned
	 * inventory fish, nor catches that overflowed to the inventory). The session
	 * tracker drains this once per tick to book barrel catches as storage-routed
	 * loot, so Loot and net worth rise together with no separate net-worth row.
	 */
	private final Map<Integer, Integer> caughtToBarrelThisTick = new LinkedHashMap<>();

	/**
	 * Per-species fish emptied OUT of the barrel straight into the bank since the
	 * last {@link #drainEmptied()} (a bank/deposit-box "Empty" — barrel fish never
	 * pass through the inventory). Drained once per tick so the session tracker can
	 * tell the engine exactly which stored-loot entries materialise in the bank,
	 * instead of leaving it to attribute an id-blind bank-value rise.
	 */
	private final Map<Integer, Integer> emptiedThisTick = new LinkedHashMap<>();

	private final Map<BarrelAction, Integer> lastActionTick = new HashMap<>();

	private enum BarrelAction
	{
		FILL, EMPTY, CHECK
	}

	public FishBarrelTracker(Client client)
	{
		this.client = client;
	}

	/** Snapshot of fish itemId -> quantity currently believed held in the barrel. */
	public Map<Integer, Integer> holdingSnapshot()
	{
		return new LinkedHashMap<>(holding);
	}

	/**
	 * Returns and clears the per-species fish stored into the barrel from catches
	 * since the last call, so the caller can book them as storage-routed loot.
	 * Call once per game tick, immediately after {@link #onTick()}. Excludes Fill
	 * (pre-owned inventory fish moved in), infernal-harpoon-cooked fish, and any
	 * catch that overflowed into the inventory — none of those reach
	 * {@link #addToBarrel}, so they are booked by the normal inventory diff instead.
	 */
	public Map<Integer, Integer> drainCaughtToBarrel()
	{
		Map<Integer, Integer> out = new LinkedHashMap<>(caughtToBarrelThisTick);
		caughtToBarrelThisTick.clear();
		return out;
	}

	/**
	 * Returns and clears the per-species fish emptied from the barrel into the
	 * bank since the last call. Call once per game tick, immediately after
	 * {@link #onTick()} (alongside {@link #drainCaughtToBarrel()}).
	 */
	public Map<Integer, Integer> drainEmptied()
	{
		Map<Integer, Integer> out = new LinkedHashMap<>(emptiedThisTick);
		emptiedThisTick.clear();
		return out;
	}

	/**
	 * Snapshots the current {@link #holding} into {@link #emptiedThisTick} before
	 * an Empty clears it, so the exact materialised contents survive for the
	 * session tracker to drain. Idempotent: once holding is cleared, a second
	 * empty signal the same tick adds nothing.
	 */
	private void captureEmptied()
	{
		for (Map.Entry<Integer, Integer> e : holding.entrySet())
		{
			emptiedThisTick.merge(e.getKey(), e.getValue(), Integer::sum);
		}
	}

	/**
	 * True while tracking has lost confidence in the exact barrel contents.
	 * Callers should freeze the barrel's wealth contribution at its last-known
	 * value rather than let it jump, to avoid a phantom profit/loss spike.
	 */
	public boolean isUnknown()
	{
		return unknown;
	}

	/** Resets all tracked state — call on a genuine login (not a zone hop). */
	public void reset()
	{
		holding.clear();
		totalHolding = 0;
		unknown = true;
		inventoryItems.clear();
		equipmentItems.clear();
		fishCaughtThisTick.clear();
		newFishInInventoryThisTick = 0;
		cookingXpDropsThisTick = 0;
		caughtToBarrelThisTick.clear();
		emptiedThisTick.clear();
		lastActionTick.clear();
	}

	/**
	 * Seeds the inventory/equipment shadow copies from the live client state.
	 * MUST be called on the client thread; call once after {@link #reset()} on
	 * login so the first {@link #onItemContainerChanged} diff is against real
	 * baseline contents rather than empty maps.
	 */
	public void primeContainers()
	{
		copyContainer(client.getItemContainer(InventoryID.INVENTORY), inventoryItems);
		copyContainer(client.getItemContainer(InventoryID.EQUIPMENT), equipmentItems);
	}

	public void onChatMessage(ChatMessageType type, String message)
	{
		if (message == null)
		{
			return;
		}

		if (type == ChatMessageType.GAMEMESSAGE && hasAnyBarrel())
		{
			if (BANK_FULL_MESSAGE.equals(message))
			{
				// Couldn't deposit all the fish into the bank — we no longer know
				// exactly how many (if any) remain in the barrel vs. the inventory.
				unknown = true;
			}
			else if (BARREL_FULL_MESSAGE.equals(message))
			{
				// Full, but we don't know the exact type breakdown from this message
				// alone; a subsequent Check resync will restore per-type confidence.
				capAtFull();
			}
			else if (BANK_EMPTY_MESSAGE.equals(message) || CONTAINERS_EMPTY_MESSAGE.equals(message))
			{
				captureEmptied();
				holding.clear();
				totalHolding = 0;
				unknown = false;
			}
			return;
		}

		if (type == ChatMessageType.SPAM && hasAnyOpenBarrel())
		{
			Matcher matcher = FISH_CAUGHT_MESSAGE.matcher(message);
			if (matcher.matches())
			{
				String fishName = matcher.group(2);
				Integer fishId = FISH_TYPES_BY_NAME.get(fishName);
				if (fishId != null)
				{
					fishCaughtThisTick.add(fishId);
				}
			}
			else if (RADA_DOUBLE_CATCH_MESSAGE.equals(message) || FLAKES_DOUBLE_CATCH_MESSAGE.equals(message))
			{
				// Bonus catch is the same species as the most recent resolved catch
				// this tick (Rada's blessing / spirit flakes double an existing
				// catch, they don't introduce a new species).
				if (!fishCaughtThisTick.isEmpty())
				{
					fishCaughtThisTick.add(fishCaughtThisTick.get(fishCaughtThisTick.size() - 1));
				}
				else
				{
					// No resolved species to duplicate (shouldn't normally happen —
					// the bonus message follows the catch message) — we can't
					// attribute this extra fish to a specific item, so mark unknown
					// rather than silently drop it.
					unknown = true;
				}
			}
			else if (CORMORANT_CATCH_MESSAGE.equals(message))
			{
				// Molch island cormorant catches are one of several species with no
				// distinguishing chat text — the exact species can't be attributed
				// from chat alone, so flag unknown; a Check resync recovers it.
				unknown = true;
			}
		}
	}

	public void onItemContainerChanged(int containerId, ItemContainer container)
	{
		if (containerId == InventoryID.INVENTORY.getId())
		{
			if (!hasAnyBarrel())
			{
				copyContainer(container, inventoryItems);
				return;
			}

			Map<Integer, Integer> previous = new HashMap<>(inventoryItems);
			copyContainer(container, inventoryItems);

			for (Map.Entry<Integer, Integer> entry : inventoryItems.entrySet())
			{
				int itemId = entry.getKey();
				if (!ALL_FISH_TYPES.contains(itemId))
				{
					continue;
				}
				int before = previous.getOrDefault(itemId, 0);
				int after = entry.getValue();
				if (after > before)
				{
					newFishInInventoryThisTick += (after - before);
				}
			}

			int removedFish = 0;
			for (Map.Entry<Integer, Integer> entry : previous.entrySet())
			{
				int itemId = entry.getKey();
				if (!ALL_FISH_TYPES.contains(itemId))
				{
					continue;
				}
				int before = entry.getValue();
				int after = inventoryItems.getOrDefault(itemId, 0);
				if (after < before)
				{
					removedFish += (before - after);
				}
			}

			if (removedFish > 0 && recentlyActioned(BarrelAction.FILL))
			{
				boolean anyFishLeft = inventoryItems.entrySet().stream()
					.anyMatch(e -> ALL_FISH_TYPES.contains(e.getKey()) && e.getValue() > 0);
				if (anyFishLeft)
				{
					// Barrel couldn't take everything — full, but we don't know the
					// exact species split that ended up inside.
					capAtFull();
				}
				else
				{
					// Nothing left in inventory: the removed fish are exactly what
					// went into the barrel — but a plain inventory diff during a
					// "Fill" doesn't tell us their species breakdown (multiple
					// species may have been removed at once), so mark unknown until
					// a Check resync (see #onWidgetLoaded) recovers it. Mirrors
					// molo-pl's total-only tracking for the Fill path.
					unknown = true;
				}
			}
		}
		else if (containerId == InventoryID.EQUIPMENT.getId())
		{
			copyContainer(container, equipmentItems);
		}
	}

	public void onCookingXpGained()
	{
		cookingXpDropsThisTick++;
	}

	/**
	 * Records a barrel "Fill"/"Empty"/"Empty to bank"/"Check" menu click, keyed
	 * by the current game tick so {@link #recentlyActioned} can correlate it
	 * with the container/widget change that follows within a few ticks.
	 */
	public void onBarrelMenuAction(int itemId, String menuOption)
	{
		if (!BARREL_IDS.contains(itemId) || menuOption == null)
		{
			return;
		}
		BarrelAction action;
		if ("Fill".equalsIgnoreCase(menuOption))
		{
			action = BarrelAction.FILL;
		}
		else if ("Empty".equalsIgnoreCase(menuOption) || "Empty to bank".equalsIgnoreCase(menuOption))
		{
			action = BarrelAction.EMPTY;
		}
		else if ("Check".equalsIgnoreCase(menuOption))
		{
			action = BarrelAction.CHECK;
		}
		else
		{
			return;
		}
		lastActionTick.put(action, client.getTickCount());
	}

	/**
	 * Drains this tick's accumulated catch-message / inventory-delta / cooking-xp
	 * signals into the barrel state. Call once per game tick (mirrors {@link
	 * SessionTracker#onTick}'s per-tick drain of {@code MovementSignals}).
	 */
	public void onTick()
	{
		if (!fishCaughtThisTick.isEmpty())
		{
			if (newFishInInventoryThisTick == 0)
			{
				// All of this tick's catches went straight to the barrel. An
				// infernal harpoon can auto-cook a subset of them (each such fish
				// fires a cooking XP drop instead of landing raw), so subtract those
				// off before crediting the barrel — matches molo-pl's handling.
				//
				// Deliberately does NOT clear #unknown here, mirroring molo-pl's
				// own FishBarrelPlugin#onGameTick: a clean per-tick credit only
				// tells us the DELTA is right, not that the running total is —
				// #unknown is reserved for signals that positively confirm the
				// whole barrel (Check resync, Empty, hitting Full), so a fresh
				// login stays "unknown" until one of those actually happens,
				// however many clean catches occur in between.
				int cookedAway = Math.min(cookingXpDropsThisTick, fishCaughtThisTick.size());
				List<Integer> toCredit = cookedAway > 0
					? fishCaughtThisTick.subList(0, fishCaughtThisTick.size() - cookedAway)
					: fishCaughtThisTick;
				for (int fishId : toCredit)
				{
					addToBarrel(fishId, 1);
				}
			}
			else
			{
				// Some catches landed in the inventory instead — the barrel is full
				// and we don't know which species make up the remainder.
				capAtFull();
			}
		}
		else if (recentlyActioned(BarrelAction.EMPTY))
		{
			captureEmptied();
			holding.clear();
			totalHolding = 0;
			unknown = false;
		}

		fishCaughtThisTick.clear();
		newFishInInventoryThisTick = 0;
		cookingXpDropsThisTick = 0;
	}

	/**
	 * Parses the "Check" interface's widget text (interface 193, component 2)
	 * to resynchronise the exact per-species barrel contents, restoring
	 * {@link #isUnknown()} to {@code false} on a successful parse. MUST be
	 * called on the client thread.
	 */
	public void onWidgetLoaded(int groupId)
	{
		if (groupId != CHECK_WIDGET_INTERFACE || !recentlyActioned(BarrelAction.CHECK))
		{
			return;
		}

		Widget widget = client.getWidget(CHECK_WIDGET_INTERFACE, CHECK_WIDGET_COMPONENT);
		if (widget == null)
		{
			return;
		}

		Map<Integer, Integer> parsed = FishBarrelWidgetParser.parse(widget.getText(), FISH_TYPES_BY_NAME);
		if (parsed != null)
		{
			holding.clear();
			holding.putAll(parsed);
			totalHolding = parsed.values().stream().mapToInt(Integer::intValue).sum();
			unknown = false;
		}
	}

	private void addToBarrel(int fishId, int qty)
	{
		if (totalHolding >= CAPACITY)
		{
			return;
		}
		int room = CAPACITY - totalHolding;
		int add = Math.min(room, qty);
		holding.merge(fishId, add, Integer::sum);
		totalHolding += add;
		if (add > 0)
		{
			caughtToBarrelThisTick.merge(fishId, add, Integer::sum);
		}
		if (add < qty)
		{
			// Ran out of room mid-credit: the barrel is now full but we can't be
			// sure the overflow species is what actually got left out.
			unknown = true;
		}
	}

	/**
	 * Records that the barrel is known to be at capacity, but not necessarily
	 * with the exact species split we're currently holding — always marks
	 * {@link #unknown} until a Check resync (see {@link #onWidgetLoaded})
	 * restores the exact per-species breakdown. Existing per-species entries are
	 * kept as-is (not wiped) so the resync has a sane multiset to replace rather
	 * than an empty one.
	 */
	private void capAtFull()
	{
		totalHolding = CAPACITY;
		unknown = true;
	}

	private boolean recentlyActioned(BarrelAction action)
	{
		Integer tick = lastActionTick.get(action);
		if (tick != null && tick > client.getTickCount() - ACTION_TICK_MARGIN)
		{
			lastActionTick.remove(action);
			return true;
		}
		return false;
	}

	private boolean hasAnyBarrel()
	{
		return containsAny(BARREL_IDS);
	}

	private boolean hasAnyOpenBarrel()
	{
		return containsAny(OPEN_BARREL_IDS);
	}

	private boolean containsAny(Collection<Integer> itemIds)
	{
		for (int itemId : itemIds)
		{
			if (inventoryItems.getOrDefault(itemId, 0) > 0 || equipmentItems.getOrDefault(itemId, 0) > 0)
			{
				return true;
			}
		}
		return false;
	}

	private static void copyContainer(ItemContainer container, Map<Integer, Integer> target)
	{
		target.clear();
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			target.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
	}

	/** Catch-message fish name -&gt; item id map, exposed package-private for tests. */
	static Map<String, Integer> fishTypesByName()
	{
		return FISH_TYPES_BY_NAME;
	}
}

package com.ospulse.integration;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.ospulse.OSPulseConfig;

import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import java.io.IOException;
import java.util.Collection;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalDouble;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

/**
 * Optional, off-by-default source of per-item price trend percentages, backed
 * by the OSRS Wiki prices API's 24h timeseries endpoint.
 *
 * <p>Entirely opt-in: while {@link OSPulseConfig#priceTrendEnabled()} is
 * {@code false} this class performs no HTTP calls at all and every lookup
 * returns {@link OptionalDouble#empty()}. When enabled, fetches are async
 * (okhttp {@code enqueue}, never {@code execute}) so nothing ever blocks the
 * RuneLite client/EDT thread, results are cached per item id with a ~1h TTL,
 * and in-flight requests are de-duplicated so pagination or repeated
 * {@link #prefetch(Collection)} calls don't pile up duplicate requests.
 *
 * <p>All failure modes (disabled config, network errors, malformed JSON,
 * non-2xx responses) degrade to "no trend" for that item; nothing here ever
 * throws back into the caller.
 */
@Slf4j
public final class PriceTrendService
{
	private static final long CACHE_TTL_MS = TimeUnit.HOURS.toMillis(1);
	private static final String USER_AGENT = "OSPulse RuneLite plugin (github.com/jonathanavis96/ospulse)";
	private static final String ENDPOINT =
		"https://prices.runescape.wiki/api/v1/osrs/timeseries?timestep=24h&id=";

	private final OkHttpClient httpClient;
	private final OSPulseConfig config;
	private final Gson gson;

	private final Map<Integer, CacheEntry> cache = new ConcurrentHashMap<>();
	private final Set<Integer> inFlight = ConcurrentHashMap.newKeySet();
	private final Set<Call> activeCalls = ConcurrentHashMap.newKeySet();

	private volatile Runnable onUpdate = () -> {};
	private volatile boolean stopped;

	public PriceTrendService(OkHttpClient httpClient, OSPulseConfig config, Gson gson)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	/**
	 * Registers the (single) callback to invoke after a fetch completes,
	 * success or failure, so a UI observer can re-render. Called from
	 * whichever thread the underlying HTTP callback lands on; the caller is
	 * responsible for hopping back to the EDT if it touches Swing.
	 */
	public void setOnUpdate(Runnable r)
	{
		this.onUpdate = r == null ? () -> {} : r;
	}

	/**
	 * Kicks off async fetches for any of {@code itemIds} that aren't already
	 * cached (and fresh) or already in flight. No-ops entirely - no HTTP -
	 * while price trends are disabled.
	 */
	public void prefetch(Collection<Integer> itemIds)
	{
		if (!config.priceTrendEnabled() || itemIds == null || itemIds.isEmpty())
		{
			return;
		}

		long now = System.currentTimeMillis();
		for (Integer itemId : itemIds)
		{
			if (itemId == null || itemId <= 0)
			{
				continue;
			}

			CacheEntry entry = cache.get(itemId);
			if (entry != null && now - entry.fetchedAtMs < CACHE_TTL_MS)
			{
				continue;
			}

			if (!inFlight.add(itemId))
			{
				// Already being fetched by another prefetch() call.
				continue;
			}

			fetch(itemId);
		}
	}

	/**
	 * The cached trend percentage for {@code itemId}, or empty when price
	 * trends are disabled, the item is unknown, the fetch is still in
	 * flight, or the last fetch failed.
	 */
	public OptionalDouble getTrendPercent(int itemId)
	{
		if (!config.priceTrendEnabled())
		{
			return OptionalDouble.empty();
		}

		CacheEntry entry = cache.get(itemId);
		return entry == null ? OptionalDouble.empty() : entry.value;
	}

	private void fetch(int itemId)
	{
		Request request = new Request.Builder()
			.url(ENDPOINT + itemId)
			.header("User-Agent", USER_AGENT)
			.build();

		Call call = httpClient.newCall(request);
		activeCalls.add(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				activeCalls.remove(call);
				log.debug("Price trend fetch failed for item {}", itemId, e);
				completeWith(itemId, OptionalDouble.empty());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				activeCalls.remove(call);
				OptionalDouble trend = OptionalDouble.empty();
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						trend = parseTrend(r.body().string());
					}
					else
					{
						log.debug("Price trend fetch got non-2xx for item {}: {}", itemId, r.code());
					}
				}
				catch (IOException e)
				{
					log.debug("Price trend fetch failed reading body for item {}", itemId, e);
				}
				catch (Exception e)
				{
					// Malformed JSON etc. - never let a parse failure propagate.
					log.debug("Price trend parse failed for item {}", itemId, e);
				}
				completeWith(itemId, trend);
			}
		});
	}

	private void completeWith(int itemId, OptionalDouble trend)
	{
		cache.put(itemId, new CacheEntry(trend, System.currentTimeMillis()));
		inFlight.remove(itemId);
		// Don't fire the UI callback after shutdown(): a late okhttp completion
		// must not run Swing work (HoldingsSection::render) against a panel that
		// has already been detached by the plugin's shutDown().
		if (!stopped)
		{
			onUpdate.run();
		}
	}

	/**
	 * Cancels every in-flight fetch and permanently stops firing the update
	 * callback, so a late HTTP completion after the plugin's {@code shutDown()}
	 * never touches a detached panel. Idempotent; the plugin calls this from
	 * {@code shutDown()}.
	 */
	public void shutdown()
	{
		stopped = true;
		for (Call call : activeCalls)
		{
			call.cancel();
		}
		activeCalls.clear();
		inFlight.clear();
	}

	/**
	 * {@code mid = avg(avgHighPrice, avgLowPrice)} (skipping nulls) for the
	 * latest point, versus the point closest to the configured window's
	 * start, expressed as a percentage change.
	 */
	private OptionalDouble parseTrend(String body)
	{
		if (body == null || body.isEmpty())
		{
			return OptionalDouble.empty();
		}

		JsonObject root = gson.fromJson(body, JsonObject.class);
		if (root == null || !root.has("data") || !root.get("data").isJsonArray())
		{
			return OptionalDouble.empty();
		}

		JsonArray data = root.getAsJsonArray("data");
		if (data.size() == 0)
		{
			return OptionalDouble.empty();
		}

		long windowDays = Math.max(1, config.priceTrendWindow().days());
		long nowSec = System.currentTimeMillis() / 1000L;
		long targetSec = nowSec - TimeUnit.DAYS.toSeconds(windowDays);

		Double latestMid = null;
		Double windowStartMid = null;
		long bestDeltaSec = Long.MAX_VALUE;

		for (int i = 0; i < data.size(); i++)
		{
			if (!data.get(i).isJsonObject())
			{
				continue;
			}
			JsonObject point = data.get(i).getAsJsonObject();
			Double mid = mid(point);
			if (mid == null)
			{
				continue;
			}

			// Data is ascending by timestamp, so the last valid mid we see is
			// the latest one.
			latestMid = mid;

			long ts = numeric(point, "timestamp") == null ? 0L : numeric(point, "timestamp").longValue();
			long deltaSec = Math.abs(ts - targetSec);
			if (deltaSec < bestDeltaSec)
			{
				bestDeltaSec = deltaSec;
				windowStartMid = mid;
			}
		}

		if (latestMid == null || windowStartMid == null || windowStartMid == 0.0)
		{
			return OptionalDouble.empty();
		}

		double pct = (latestMid - windowStartMid) / windowStartMid * 100.0;
		return OptionalDouble.of(pct);
	}

	private static Double mid(JsonObject point)
	{
		Double high = numeric(point, "avgHighPrice");
		Double low = numeric(point, "avgLowPrice");
		if (high != null && low != null)
		{
			return (high + low) / 2.0;
		}
		return high != null ? high : low;
	}

	private static Double numeric(JsonObject point, String key)
	{
		if (!point.has(key) || point.get(key).isJsonNull())
		{
			return null;
		}
		try
		{
			return point.get(key).getAsDouble();
		}
		catch (Exception e)
		{
			return null;
		}
	}

	private static final class CacheEntry
	{
		private final OptionalDouble value;
		private final long fetchedAtMs;

		private CacheEntry(OptionalDouble value, long fetchedAtMs)
		{
			this.value = value;
			this.fetchedAtMs = fetchedAtMs;
		}
	}
}

package com.ospulse.integration;

import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/**
 * Thin wrapper around RuneLite's {@link ItemManager} that canonicalizes item
 * ids before pricing/naming them, so noted and placeholder variants of an
 * item price identically to the base item.
 */
public class RuneLiteItemValuation
{
	private final ItemManager itemManager;

	public RuneLiteItemValuation(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * GE unit price for the given item, canonicalized first, or 0 for
	 * untradeable items (they contribute 0 to tradeable wealth).
	 *
	 * <p>The untradeable guard is load-bearing: {@link ItemManager#getItemPrice(int)}
	 * routes trouver-locked untradeables (e.g. Fire cape (l), Dragon defender (l))
	 * through the {@code ITEM_TROUVER_PARCHMENT} GE mapping and returns ~1,000,000gp
	 * rather than 0, which would otherwise inflate wealth and produce phantom
	 * ~1M loot/loss entries the moment such an item enters or leaves the player's
	 * containers. Because it reads {@link ItemManager#getItemComposition(int)} it
	 * asserts the RuneLite client thread — every caller (SessionTracker's
	 * accumulate* methods and OSPulsePlugin's clientThread.invoke-wrapped optimizer
	 * resolver) already runs there.
	 */
	public long unitValue(int itemId)
	{
		int canonicalId = itemManager.canonicalize(itemId);
		ItemComposition comp = itemManager.getItemComposition(canonicalId);
		if (comp == null || !comp.isTradeable())
		{
			return 0L;
		}
		return itemManager.getItemPrice(canonicalId);
	}

	public String name(int itemId)
	{
		int canonicalId = itemManager.canonicalize(itemId);
		return itemManager.getItemComposition(canonicalId).getName();
	}

	/**
	 * The canonicalized id for {@code itemId} (noted/placeholder variants
	 * resolve to their base item id), used to key tracked items so noted and
	 * unnoted stacks of the same item merge together.
	 */
	public int canonical(int itemId)
	{
		return itemManager.canonicalize(itemId);
	}

	/** True if this item id is a bank placeholder (empty reserved slot, not owned). */
	public boolean isPlaceholder(int itemId)
	{
		return itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1;
	}

	/**
	 * True if the item can be traded (GE/player trade), canonicalized first.
	 * Calls {@link ItemManager#getItemComposition(int)}, which asserts it is
	 * running on the RuneLite client thread — callers must never invoke this
	 * from the Swing EDT or a background search thread; precompute the answers
	 * into a plain map on the client thread instead (see
	 * {@code OSPulsePlugin}'s optimizer price resolver).
	 */
	public boolean isTradeable(int itemId)
	{
		int canonicalId = itemManager.canonicalize(itemId);
		ItemComposition comp = itemManager.getItemComposition(canonicalId);
		return comp != null && comp.isTradeable();
	}

	/**
	 * Per-unit High Alchemy price for the given item, canonicalized first, or
	 * {@code -1} if no composition is available. Calls
	 * {@link ItemManager#getItemComposition(int)}, which asserts it is running
	 * on the RuneLite client thread — callers must never invoke this from the
	 * Swing EDT.
	 */
	public long haPrice(int itemId)
	{
		int canonicalId = itemManager.canonicalize(itemId);
		ItemComposition comp = itemManager.getItemComposition(canonicalId);
		return comp == null ? -1L : comp.getHaPrice();
	}
}

package com.ospulse.ge;

import lombok.EqualsAndHashCode;
import lombok.Getter;

import java.util.OptionalLong;

/**
 * Immutable, read-only view of a single active Grand Exchange offer slot, for
 * display in the panel's "Grand Exchange" breakdown. Pure domain type: no
 * RuneLite imports, unit-testable without a game client.
 *
 * <p>Mirrors what the in-game GE interface shows per slot: the item, whether
 * it is a buy or sell, how far the offer has progressed (quantity transacted
 * out of the total ordered), and the gp moved so far out of the gp the offer
 * would move if fully filled.
 */
@Getter
@EqualsAndHashCode
public final class GeOfferView
{
	private final boolean buying;
	private final int itemId;
	private final String itemName;
	private final long totalQuantity;
	private final long quantityTransacted;
	private final long pricePerItem;
	/** gp moved so far: spent (buy) or received (sell). */
	private final long gpProgress;
	/** gp the offer would move if fully filled: pricePerItem * totalQuantity. */
	private final long gpPotential;
	/**
	 * Realised flip P&amp;L accumulated so far for this offer's slot (see
	 * {@link GeReconciler#slotRealizedPnl(int)}), or {@link
	 * OptionalLong#empty()} if this offer isn't a flip — a still-open buy
	 * offer, or a sell that only dumped items with no GE cost basis. Absent
	 * vs. a present {@code 0} is deliberate: a dump shows no P&amp;L at all,
	 * while a flip that broke exactly even (net of GE sales tax) still shows
	 * a real, present figure.
	 */
	private final OptionalLong realizedPnl;

	public GeOfferView(
		boolean buying,
		int itemId,
		String itemName,
		long totalQuantity,
		long quantityTransacted,
		long pricePerItem,
		long gpProgress,
		long gpPotential,
		OptionalLong realizedPnl)
	{
		this.buying = buying;
		this.itemId = itemId;
		this.itemName = itemName;
		this.totalQuantity = totalQuantity;
		this.quantityTransacted = quantityTransacted;
		this.pricePerItem = pricePerItem;
		this.gpProgress = gpProgress;
		this.gpPotential = gpPotential;
		this.realizedPnl = realizedPnl == null ? OptionalLong.empty() : realizedPnl;
	}

	@Override
	public String toString()
	{
		return "GeOfferView{"
			+ (buying ? "BUY " : "SELL ") + itemName
			+ " " + quantityTransacted + "/" + totalQuantity
			+ " @ " + pricePerItem
			+ " gp " + gpProgress + "/" + gpPotential
			+ (realizedPnl.isPresent() ? " pnl " + realizedPnl.getAsLong() : "")
			+ '}';
	}
}

package com.ospulse.ge;

/**
 * A Grand Exchange sale of items the player did NOT buy on the GE (looted or
 * previously owned): the after-tax proceeds to realise into the session Loot
 * figure. A sale matched against a GE buy basis is a flip and never produces one.
 */
public final class LootSale
{
	public final int itemId;
	public final long quantity;
	public final long netProceeds;

	public LootSale(int itemId, long quantity, long netProceeds)
	{
		this.itemId = itemId;
		this.quantity = quantity;
		this.netProceeds = netProceeds;
	}
}

package com.ospulse.ge;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;
import java.util.Set;

/**
 * Pure reconciler for Grand Exchange offers.
 *
 * <p>Maintains a per-item weighted-average-cost ledger so it can compute
 * realised flip P&amp;L, and a quantity-accurate expectation ledger (see
 * {@link GeAttributions}) of tracked-item movements the GE accounts for, so
 * the session engine can exclude them from the loot/supplies feeds
 * (buying/selling isn't loot).
 *
 * <p>The expectation ledger exists because a GE trade's goods do NOT enter
 * the inventory when the offer fills: they sit in the collection box —
 * potentially indefinitely — until the player collects them. Each fill
 * therefore records an expected ARRIVAL (bought items; sale proceeds net of
 * tax; buy-refund coins when a buy filled under the offer price;
 * cancellation refunds), and each sell-offer placement records an expected
 * REMOVAL (the offered stack leaves the inventory at placement). Arrivals
 * persist while their offer still occupies its slot; once the slot clears
 * (the player collected — to inventory or straight to bank) any remainder is
 * only kept for a short settle window, so a stale expectation can never
 * swallow genuine loot of the same item id much beyond the collection
 * moment.
 *
 * <p>Mutable, single-threaded use only. Not thread-safe.
 */
public final class GeReconciler implements GeAttributions
{
	/** Canonical item id of coins (sale proceeds / escrow refunds). */
	public static final int COINS_ITEM_ID = 995;

	/**
	 * How long (ms) an expectation stays consumable once its settling
	 * inventory movement is due "now": for an arrival, measured from the
	 * moment its offer's slot clears (the collection instant — the matching
	 * inventory rise lands within a tick or two unless the player collected
	 * to bank, in which case it never lands and the leftover must die); for a
	 * removal, measured from the sell-offer placement that removed the stack
	 * in the same tick batch. Mirrors the engine's bank-side settle window:
	 * generous against event-ordering lag, small enough to bound how long
	 * genuine same-id loot could be misattributed.
	 */
	private static final long ATTRIBUTION_SETTLE_WINDOW_MS = 10_000L;

	private static final class SlotTracker
	{
		int itemId;
		long lastQuantityTransacted;
		long lastGpTransacted;
		GeOfferState lastState;
	}

	/**
	 * Expected inventory arrival from GE activity: items bought, coin
	 * proceeds of a sale, or a cancellation/underprice refund — awaiting
	 * collection. {@code deadlineMs} is 0 while the offer still occupies its
	 * slot (the collection box holds goods indefinitely); once the slot
	 * clears it is stamped with a settle deadline (see
	 * {@link #ATTRIBUTION_SETTLE_WINDOW_MS}).
	 */
	private static final class ExpectedArrival
	{
		final int slot;
		final int itemId;
		long quantity;
		long deadlineMs;

		ExpectedArrival(int slot, int itemId, long quantity)
		{
			this.slot = slot;
			this.itemId = itemId;
			this.quantity = quantity;
		}
	}

	/**
	 * Expected inventory removal from GE activity: a sell offer's stack
	 * leaving the inventory at placement (observed in the same tick batch as
	 * the placement event, so a short settle window suffices).
	 */
	private static final class ExpectedRemoval
	{
		final int itemId;
		long quantity;
		final long tsMs;

		ExpectedRemoval(int itemId, long quantity, long tsMs)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.tsMs = tsMs;
		}
	}

	private static final class CostBasis
	{
		long qty;
		long avgUnitCost;
	}

	/**
	 * Per-slot realised flip P&amp;L accumulator, keyed by GE slot — backs
	 * {@link #slotRealizedPnl(int)} for the panel's per-offer signed P&amp;L
	 * row. {@code hasFlip} is the "not a flip" vs "a flip that happens to be
	 * exactly zero" flag: it is set {@code true} the instant {@link
	 * #applySell} matches ANY quantity against a cost basis, independent of
	 * what {@code pnl} nets out to, so a break-even flip (present, {@code 0})
	 * stays distinguishable from a pure dump (absent) or an unsold buy offer
	 * (absent).
	 */
	private static final class SlotPnl
	{
		long pnl;
		boolean hasFlip;
	}

	/**
	 * Plain, serializable snapshot of one item's cost-basis ledger entry —
	 * returned by {@link #exportCostBasis()} and accepted by {@link
	 * #importCostBasis(Map)} so a caller (e.g. {@code SessionTracker}) can
	 * persist the buy ledger (JSON via Gson) across a relog without this class
	 * needing to know anything about {@code ConfigManager}/{@code Client}.
	 */
	public static final class CostBasisSnapshot
	{
		public final long qty;
		public final long avgUnitCost;

		public CostBasisSnapshot(long qty, long avgUnitCost)
		{
			this.qty = qty;
			this.avgUnitCost = avgUnitCost;
		}
	}

	/**
	 * Per-item Grand Exchange sales tax, matching the live game: 2% of the sale
	 * price per item (raised from 1% on 29 May 2025), rounded down, capped at
	 * {@link #GE_TAX_CAP_PER_ITEM} gp per item. Because it rounds down, any item
	 * sold below 50 gp incurs less than 1 gp of tax and so pays nothing — that
	 * threshold falls out of the integer division and needs no special case.
	 * Integer {@code price / 50} is exactly {@code floor(price * 0.02)} and
	 * avoids floating-point drift on large prices.
	 */
	private static final long GE_TAX_DIVISOR = 50L; // 1/50 == 2%
	private static final long GE_TAX_CAP_PER_ITEM = 5_000_000L;

	/**
	 * Items the Grand Exchange never taxes regardless of price. The full live
	 * list (OSRS Wiki "Items exempt from Grand Exchange tax" category) is large
	 * and grows over time — mostly cheap, high-volume items (runes, food, early
	 * ammo, tools) where 2% is negligible to flip P&amp;L. This curated set
	 * carries the only items where omitting the exemption would be materially
	 * wrong: the Old school bond (id 13190), a routinely-flipped ~8M item.
	 * Extend with one id per entry if other high-value exempt items appear.
	 */
	private static final Set<Integer> TAX_EXEMPT_ITEM_IDS = new HashSet<>(Arrays.asList(
		13190 // Old school bond (tradeable)
	));

	private final Map<Integer, SlotTracker> slots = new HashMap<>();
	private final Map<Integer, CostBasis> costBasis = new HashMap<>();
	/** Per-slot flip P&amp;L accumulator — see {@link SlotPnl}. */
	private final Map<Integer, SlotPnl> slotPnl = new HashMap<>();
	/** FIFO expectation ledgers — see {@link ExpectedArrival}/{@link ExpectedRemoval}. */
	private final List<ExpectedArrival> expectedArrivals = new ArrayList<>();
	private final List<ExpectedRemoval> expectedRemovals = new ArrayList<>();
	private long realizedPnl;
	/** Loot-sales (non-flip sells) observed since the last drain. */
	private final List<LootSale> lootSales = new ArrayList<>();

	/**
	 * The per-item GE sales tax on a sale of {@code itemId} at
	 * {@code pricePerItem}: 2% floored, capped at 5M/item, zero for tax-exempt
	 * items and for anything whose 2% rounds down to nothing (sub-50 gp).
	 */
	static long saleTaxPerItem(int itemId, long pricePerItem)
	{
		if (pricePerItem <= 0 || TAX_EXEMPT_ITEM_IDS.contains(itemId))
		{
			return 0L;
		}
		return Math.min(pricePerItem / GE_TAX_DIVISOR, GE_TAX_CAP_PER_ITEM);
	}

	/**
	 * Feeds an offer update into the reconciler.
	 *
	 * @param slot                the GE offer slot index (0-7 typically)
	 * @param state                current lifecycle state of the offer
	 * @param itemId               item id being traded
	 * @param itemName             item name (unused for math, kept for API symmetry)
	 * @param totalQuantity        total quantity of the offer (unused for math, kept for API symmetry)
	 * @param quantityTransacted   cumulative quantity transacted so far on this offer
	 * @param gpTransacted         cumulative gp transacted so far (unused; pricePerItem drives the ledger)
	 * @param pricePerItem         price per item for this offer
	 * @param tsMs                 event timestamp (unused for math, kept for API symmetry)
	 */
	public void onOfferUpdate(
		int slot,
		GeOfferState state,
		int itemId,
		String itemName,
		long totalQuantity,
		long quantityTransacted,
		long gpTransacted,
		long pricePerItem,
		long tsMs)
	{
		if (state == GeOfferState.EMPTY)
		{
			// The slot cleared: whatever this offer still had awaiting
			// collection has just been claimed (to inventory, whose arrival
			// lands within the settle window, or straight to bank, in which
			// case no tracked arrival will ever come and the leftover must
			// expire rather than linger to swallow genuine loot).
			stampSlotCleared(slot, tsMs);
			slots.remove(slot);
			// The slot's offer is gone: its flip P&L must not leak into
			// whatever offer eventually reuses this slot.
			slotPnl.remove(slot);
			return;
		}

		SlotTracker tracker = slots.get(slot);
		boolean newOffer = tracker == null
			|| tracker.itemId != itemId
			// quantityTransacted never regresses within one offer, so a
			// regression means the slot was cleared and reused for a new
			// offer of the same item without an observed EMPTY in between.
			|| quantityTransacted < tracker.lastQuantityTransacted;
		if (newOffer)
		{
			if (tracker != null)
			{
				// Slot reused without an observed EMPTY: the previous
				// offer's collectables were claimed at some earlier instant.
				stampSlotCleared(slot, tsMs);
			}
			tracker = new SlotTracker();
			tracker.itemId = itemId;
			tracker.lastQuantityTransacted = 0L;
			tracker.lastGpTransacted = 0L;
			slots.put(slot, tracker);
			// Brand new offer in this slot (whether or not an EMPTY was
			// observed in between — see the quantityTransacted-regression
			// case above): its predecessor's flip P&L, if any, must not
			// carry forward.
			slotPnl.remove(slot);
			if (state == GeOfferState.SELLING || state == GeOfferState.SOLD)
			{
				// Sell placement: the whole offered stack left the inventory
				// the instant the offer went up (observed in the same tick
				// batch as this event) — that removal is a GE transfer, not
				// supplies consumed.
				addRemoval(itemId, totalQuantity, tsMs);
			}
		}

		long incremental = quantityTransacted - tracker.lastQuantityTransacted;
		if (incremental < 0)
		{
			// Defensive: never seen going backwards in practice, but don't
			// let it corrupt the ledger.
			incremental = 0;
		}
		long incrementalGp = gpTransacted - tracker.lastGpTransacted;
		if (incrementalGp < 0)
		{
			incrementalGp = 0;
		}
		tracker.lastQuantityTransacted = Math.max(tracker.lastQuantityTransacted, quantityTransacted);
		tracker.lastGpTransacted = Math.max(tracker.lastGpTransacted, gpTransacted);
		GeOfferState previousState = tracker.lastState;
		tracker.lastState = state;

		if (incremental > 0)
		{
			switch (state)
			{
				case BUYING:
				case BOUGHT:
					applyBuy(itemId, incremental, pricePerItem);
					addArrival(slot, itemId, incremental);
					// A buy that filled under the offer price refunds the
					// difference in coins (collectable alongside the items).
					// Only trusted when the event carries real gp movement —
					// a zero gpTransacted must not fabricate a full-escrow
					// coin expectation.
					long refund = incremental * pricePerItem - incrementalGp;
					if (incrementalGp > 0 && refund > 0)
					{
						addArrival(slot, COINS_ITEM_ID, refund);
					}
					break;
				case SELLING:
				case SOLD:
					long matched = applySell(slot, itemId, incremental, pricePerItem, incrementalGp);
					// The collectable proceeds are the gp actually transacted (a
					// sell can fill ABOVE the offer price) minus the per-item
					// tax.
					long gross = incrementalGp > 0 ? incrementalGp : incremental * pricePerItem;
					long netProceeds = gross - saleTaxPerItem(itemId, gross / incremental) * incremental;
					if (netProceeds > 0)
					{
						addArrival(slot, COINS_ITEM_ID, netProceeds);
					}
					// Any quantity sold beyond the GE buy basis is a loot-sale:
					// surface its proportional after-tax proceeds to realise into Loot.
					long lootQty = incremental - matched;
					if (lootQty > 0)
					{
						long lootProceeds = Math.round((double) netProceeds * lootQty / incremental);
						lootSales.add(new LootSale(itemId, lootQty, lootProceeds));
					}
					break;
				default:
					// Any quantity actually filled before cancellation was
					// already handled on the BUYING/SELLING updates that
					// carried it; cancellation itself fills nothing further.
					break;
			}
		}

		// Cancellation returns the unfilled remainder to the collection box:
		// the escrowed coins of a buy, the unsold items of a sell. Attributed
		// exactly once, on the transition into the cancelled state.
		if (state == GeOfferState.CANCELLED_BUY && previousState != GeOfferState.CANCELLED_BUY)
		{
			long refund = Math.max(0L, totalQuantity - quantityTransacted) * pricePerItem;
			if (refund > 0)
			{
				addArrival(slot, COINS_ITEM_ID, refund);
			}
		}
		else if (state == GeOfferState.CANCELLED_SELL && previousState != GeOfferState.CANCELLED_SELL)
		{
			long remaining = Math.max(0L, totalQuantity - quantityTransacted);
			if (remaining > 0)
			{
				addArrival(slot, itemId, remaining);
			}
		}
	}

	/**
	 * Seeds a slot's incremental tracking from an offer that predates the
	 * session (login burst / session reset while offers are live) WITHOUT
	 * recording any attribution or flip P&amp;L for its already-transacted
	 * portion: pre-session fills are not session activity, and attributing
	 * them would both resurrect pre-session realised P&amp;L and plant
	 * phantom arrival expectations that could swallow genuine loot.
	 */
	public void primeSlot(int slot, GeOfferState state, int itemId, long quantityTransacted, long gpTransacted)
	{
		if (state == null || state == GeOfferState.EMPTY)
		{
			slots.remove(slot);
			slotPnl.remove(slot);
			return;
		}
		SlotTracker tracker = new SlotTracker();
		tracker.itemId = itemId;
		tracker.lastQuantityTransacted = Math.max(0L, quantityTransacted);
		tracker.lastGpTransacted = Math.max(0L, gpTransacted);
		tracker.lastState = state;
		slots.put(slot, tracker);
		// Priming never records flip P&L (see the class-level Javadoc above),
		// so this slot starts fresh here too.
		slotPnl.remove(slot);
	}

	/**
	 * Primes a pre-session offer AND records its outstanding collectable as an
	 * expected arrival, so collecting pre-session proceeds/goods after the session
	 * starts is attributed as a GE transfer (excluded from loot) and is counted in
	 * {@link #collectableValue} in the meantime.
	 *
	 * <p>Restricted to COMPLETED offers ({@link GeOfferState#BOUGHT} /
	 * {@link GeOfferState#SOLD}): a non-EMPTY completed slot means the goods are
	 * definitively still in the collection box (collecting a completed offer takes
	 * everything and empties the slot), so there is no risk of over-recording an
	 * already-collected partial. In-progress offers (BUYING/SELLING) can be
	 * partially collected pre-session and so are left as a bare {@link #primeSlot}.
	 *
	 * <p>Records NO flip P&amp;L — pre-session activity is not session activity —
	 * exactly like {@link #primeSlot}, which it delegates the slot seeding to.
	 */
	public void primeCollectable(int slot, GeOfferState state, int itemId,
		long quantityTransacted, long gpTransacted, long pricePerItem)
	{
		primeSlot(slot, state, itemId, quantityTransacted, gpTransacted);
		if (quantityTransacted <= 0)
		{
			return;
		}
		if (state == GeOfferState.BOUGHT)
		{
			addArrival(slot, itemId, quantityTransacted);
			// A buy that filled under the offer price left refund coins collectable
			// alongside the items (only when real gp movement is known).
			long refund = quantityTransacted * pricePerItem - gpTransacted;
			if (gpTransacted > 0 && refund > 0)
			{
				addArrival(slot, COINS_ITEM_ID, refund);
			}
		}
		else if (state == GeOfferState.SOLD)
		{
			long gross = gpTransacted > 0 ? gpTransacted : quantityTransacted * pricePerItem;
			long netProceeds = gross - saleTaxPerItem(itemId, gross / quantityTransacted) * quantityTransacted;
			if (netProceeds > 0)
			{
				addArrival(slot, COINS_ITEM_ID, netProceeds);
			}
		}
	}

	private void applyBuy(int itemId, long qty, long pricePerItem)
	{
		CostBasis basis = costBasis.computeIfAbsent(itemId, k -> new CostBasis());
		long newQty = basis.qty + qty;
		if (newQty <= 0)
		{
			basis.qty = 0;
			basis.avgUnitCost = 0;
			return;
		}
		basis.avgUnitCost = (basis.qty * basis.avgUnitCost + qty * pricePerItem) / newQty;
		basis.qty = newQty;
	}

	private long applySell(int slot, int itemId, long qty, long pricePerItem, long incrementalGp)
	{
		CostBasis basis = costBasis.get(itemId);
		if (basis == null || basis.qty <= 0)
		{
			// Selling with no GE cost basis (dumping looted or previously
			// owned items, not flipping) is not a flip: nothing matched, and
			// slotPnl is deliberately left untouched (no entry created) so
			// slotRealizedPnl keeps reporting absent for this slot rather
			// than a misleading present zero.
			return 0L;
		}

		// Only the quantity actually bought via the GE counts as a flip.
		long matched = Math.min(qty, basis.qty);

		// The realized price is what the GE actually paid, not the offer's
		// listed (minimum) price — a sell can fill ABOVE that price, exactly
		// like the collectable-proceeds calc just above this call at the call
		// site. Falling back to pricePerItem only when a zero incrementalGp
		// means no real gp movement is known yet (mirrors every other
		// incrementalGp > 0 ? ... : ... fallback in this class).
		long actualPricePerItem = incrementalGp > 0 ? incrementalGp / qty : pricePerItem;

		// The seller nets the actual sale price minus the GE's per-item sales tax.
		long netProceedsPerItem = actualPricePerItem - saleTaxPerItem(itemId, actualPricePerItem);
		long delta = (netProceedsPerItem - basis.avgUnitCost) * matched;
		realizedPnl += delta;

		// Mirror the same delta into this slot's own accumulator so the panel
		// can show a per-offer figure without recomputing from the (already
		// mutated below) live cost basis — see slotRealizedPnl's Javadoc.
		SlotPnl sp = slotPnl.computeIfAbsent(slot, k -> new SlotPnl());
		sp.pnl += delta;
		sp.hasFlip = true;

		basis.qty -= matched;
		if (basis.qty == 0)
		{
			basis.avgUnitCost = 0;
		}
		return matched;
	}

	/**
	 * Total realised flip P&amp;L across all items observed so far.
	 */
	public long realizedPnl()
	{
		return realizedPnl;
	}

	/**
	 * Realised flip P&amp;L accumulated so far for the offer currently (or
	 * most recently) occupying {@code slot}, or {@link OptionalLong#empty()}
	 * if that offer has never matched any quantity against a GE cost basis —
	 * i.e. a still-open buy offer, or a sell that only dumped items with no
	 * GE cost basis (see {@link #applySell}).
	 *
	 * <p>Absent vs. present-zero is deliberate and load-bearing for the panel:
	 * absent means "not a flip, don't show a P&amp;L figure at all"; a
	 * present {@code 0L} (or any other value) means "a flip, and this is its
	 * net result" — which can legitimately be a small loss (a break-even sale
	 * still pays the GE's sales tax). Overloading a bare {@code 0L} to mean
	 * both would make a dump indistinguishable from a break-even flip.
	 *
	 * <p>Reset to absent whenever the slot's offer changes underneath it (a
	 * genuinely new offer, or the same slot reused without an observed
	 * transition) or the slot empties — see the {@code slotPnl.remove} calls
	 * in {@link #onOfferUpdate} — so a reused slot never inherits the
	 * previous offer's number.
	 *
	 * <p>Computed incrementally at the same point {@link #realizedPnl} is
	 * (inside {@link #applySell}, before the cost basis is mutated for the
	 * matched quantity), NOT recomputed from the live cost basis afterwards —
	 * recomputing post-hoc would be wrong for a partially filled offer, since
	 * each fill already consumes its matched slice of the basis.
	 */
	public OptionalLong slotRealizedPnl(int slot)
	{
		SlotPnl sp = slotPnl.get(slot);
		return (sp == null || !sp.hasFlip) ? OptionalLong.empty() : OptionalLong.of(sp.pnl);
	}

	/**
	 * Returns and clears the loot-sales observed since the last call — see
	 * {@link LootSale}.
	 */
	@Override
	public List<LootSale> drainLootSales()
	{
		if (lootSales.isEmpty())
		{
			return java.util.Collections.emptyList();
		}
		List<LootSale> out = new ArrayList<>(lootSales);
		lootSales.clear();
		return out;
	}

	/**
	 * Total value still awaiting collection in the Grand Exchange collection box:
	 * the sum of every live expected arrival (bought items, sale-proceed coins,
	 * under-price/cancellation refunds) whose offer slot is still occupied
	 * ({@code deadlineMs == 0}), valued via {@code unitValue} (coins are valued at
	 * 1 gp each regardless of what the lookup returns).
	 *
	 * <p>This is the wealth that has definitively left the inventory/bank into a
	 * sell offer (or the escrow of a buy) and is now sitting as collectable goods
	 * or proceeds — value the {@link com.ospulse.integration.GeValuation}
	 * "still-locked" number deliberately omits, which is why net worth otherwise
	 * dips the instant a sell fills and only recovers when the coins are collected.
	 * Folding it back into tracked wealth closes that gap.
	 *
	 * <p>Counting only slot-occupied ({@code deadlineMs == 0}) arrivals is what
	 * keeps this double-count-free: the moment a slot clears (the player
	 * collected — see {@link #stampSlotCleared}) its arrivals are stamped with a
	 * settle deadline and drop out of this total, handing the value straight back
	 * to inventory/bank accounting. Because each arrival is also decremented by
	 * the actual observed inventory arrival ({@link #attributeArrival}), a partial
	 * collect is reflected the instant it lands. The only residual overlap is the
	 * single tick on which a collected stack is already in the inventory container
	 * but its arrival has not yet been consumed by the engine's per-tick diff — a
	 * benign transient that self-corrects on the next tick (the engine re-anchors
	 * its baseline every tick), never a persistent phantom gain.
	 *
	 * @param unitValue itemId -&gt; gp value per unit
	 */
	public long collectableValue(java.util.function.IntToLongFunction unitValue)
	{
		long total = 0L;
		for (ExpectedArrival e : expectedArrivals)
		{
			if (e.deadlineMs != 0 || e.quantity <= 0)
			{
				continue;
			}
			long unit = e.itemId == COINS_ITEM_ID ? 1L : unitValue.applyAsLong(e.itemId);
			total += e.quantity * unit;
		}
		return total;
	}

	/**
	 * Clears all per-session state (open-slot tracking, cost-basis ledger,
	 * expectation ledgers and realised P&amp;L) so a new tracking window
	 * starts from zero. Must be called whenever the session is reset or
	 * re-bootstrapped (manual reset button, login/relogin) — otherwise
	 * realised flip P&amp;L carries over into the "new" session and keeps
	 * accumulating, unlike every other per-session stat. Live offers should
	 * be re-seeded via {@link #primeSlot} right after, so their pre-session
	 * fills are never re-counted as fresh movement.
	 */
	public void reset()
	{
		slots.clear();
		costBasis.clear();
		expectedArrivals.clear();
		expectedRemovals.clear();
		realizedPnl = 0L;
		lootSales.clear();
		slotPnl.clear();
	}

	/**
	 * Exports a plain, serializable snapshot of the cost-basis buy ledger only —
	 * itemId -&gt; {@link CostBasisSnapshot} for every item still holding an open
	 * (unsold) GE-bought quantity. Deliberately excludes {@link #realizedPnl}
	 * (must stay per-session — see {@link #reset()}) and the transient GE slot /
	 * expectation state ({@code slots}, {@code expectedArrivals},
	 * {@code expectedRemovals}, {@code lootSales} — re-primed from live offers
	 * each session via {@link #primeSlot}/{@link #primeCollectable}).
	 *
	 * <p>Intended to be persisted (e.g. as JSON by the caller) and fed back into
	 * a fresh instance via {@link #importCostBasis(Map)} after a relog, so a
	 * buy made in an earlier session still has its cost basis when sold later —
	 * crediting the flip P&amp;L to whichever session the sell happens in.
	 */
	public Map<Integer, CostBasisSnapshot> exportCostBasis()
	{
		Map<Integer, CostBasisSnapshot> out = new HashMap<>();
		for (Map.Entry<Integer, CostBasis> e : costBasis.entrySet())
		{
			CostBasis basis = e.getValue();
			if (basis.qty > 0)
			{
				out.put(e.getKey(), new CostBasisSnapshot(basis.qty, basis.avgUnitCost));
			}
		}
		return out;
	}

	/**
	 * Restores the cost-basis ledger from a snapshot previously produced by
	 * {@link #exportCostBasis()} (typically loaded from persisted per-account
	 * config after a relog). Replaces whatever is currently in the ledger —
	 * call right after {@link #reset()}, before any live offer events are fed
	 * in, so the restore isn't immediately wiped. Entries that are {@code null}
	 * or non-positive quantity are ignored. Touches ONLY {@code costBasis}:
	 * {@link #realizedPnl} and all transient slot/expectation state are left
	 * alone (per-session, re-primed separately).
	 */
	public void importCostBasis(Map<Integer, CostBasisSnapshot> snapshot)
	{
		costBasis.clear();
		if (snapshot == null)
		{
			return;
		}
		for (Map.Entry<Integer, CostBasisSnapshot> e : snapshot.entrySet())
		{
			CostBasisSnapshot s = e.getValue();
			if (s == null || s.qty <= 0)
			{
				continue;
			}
			CostBasis basis = new CostBasis();
			basis.qty = s.qty;
			basis.avgUnitCost = s.avgUnitCost;
			costBasis.put(e.getKey(), basis);
		}
	}

	/**
	 * Drops expectations whose settle window has lapsed: arrivals whose slot
	 * cleared more than {@link #ATTRIBUTION_SETTLE_WINDOW_MS} ago (collected
	 * to bank, or an estimate's residue), and removals older than the same
	 * window (the placement-time inventory drop either arrived long ago or
	 * never will). Call once per tick, before the engine consumes.
	 */
	public void expireAttributions(long tsMs)
	{
		Iterator<ExpectedArrival> arrivals = expectedArrivals.iterator();
		while (arrivals.hasNext())
		{
			ExpectedArrival e = arrivals.next();
			if (e.deadlineMs != 0 && tsMs > e.deadlineMs)
			{
				arrivals.remove();
			}
		}
		Iterator<ExpectedRemoval> removals = expectedRemovals.iterator();
		while (removals.hasNext())
		{
			if (tsMs - removals.next().tsMs > ATTRIBUTION_SETTLE_WINDOW_MS)
			{
				removals.remove();
			}
		}
	}

	@Override
	public long attributeArrival(int itemId, long quantity)
	{
		long consumed = 0L;
		Iterator<ExpectedArrival> it = expectedArrivals.iterator();
		while (it.hasNext() && consumed < quantity)
		{
			ExpectedArrival e = it.next();
			if (e.itemId != itemId)
			{
				continue;
			}
			long take = Math.min(e.quantity, quantity - consumed);
			e.quantity -= take;
			consumed += take;
			if (e.quantity == 0)
			{
				it.remove();
			}
		}
		return consumed;
	}

	@Override
	public long attributeRemoval(int itemId, long quantity)
	{
		long consumed = 0L;
		Iterator<ExpectedRemoval> it = expectedRemovals.iterator();
		while (it.hasNext() && consumed < quantity)
		{
			ExpectedRemoval e = it.next();
			if (e.itemId != itemId)
			{
				continue;
			}
			long take = Math.min(e.quantity, quantity - consumed);
			e.quantity -= take;
			consumed += take;
			if (e.quantity == 0)
			{
				it.remove();
			}
		}
		return consumed;
	}

	/**
	 * Adds (or merges into this slot's live entry for the item) an expected
	 * GE arrival — see {@link ExpectedArrival}.
	 */
	private void addArrival(int slot, int itemId, long quantity)
	{
		if (quantity <= 0)
		{
			return;
		}
		for (ExpectedArrival e : expectedArrivals)
		{
			if (e.slot == slot && e.itemId == itemId && e.deadlineMs == 0)
			{
				e.quantity += quantity;
				return;
			}
		}
		expectedArrivals.add(new ExpectedArrival(slot, itemId, quantity));
	}

	private void addRemoval(int itemId, long quantity, long tsMs)
	{
		if (quantity <= 0)
		{
			return;
		}
		expectedRemovals.add(new ExpectedRemoval(itemId, quantity, tsMs));
	}

	/**
	 * Marks every still-live arrival expectation of {@code slot} as
	 * collected NOW: the goods were just claimed somewhere, so the matching
	 * inventory arrival must land within the settle window or never will.
	 */
	private void stampSlotCleared(int slot, long tsMs)
	{
		for (ExpectedArrival e : expectedArrivals)
		{
			if (e.slot == slot && e.deadlineMs == 0)
			{
				e.deadlineMs = tsMs + ATTRIBUTION_SETTLE_WINDOW_MS;
			}
		}
	}
}

package com.ospulse;

/**
 * Lookback window used when computing a per-item price trend percentage from
 * the OSRS Wiki prices API's 24h timeseries endpoint. Selectable via
 * {@link OSPulseConfig#priceTrendWindow()}.
 */
public enum PriceTrendWindow
{
	DAY("24h", 1),
	WEEK("7d", 7),
	MONTH("30d", 30);

	private final String displayName;
	private final int days;

	PriceTrendWindow(String displayName, int days)
	{
		this.displayName = displayName;
		this.days = days;
	}

	/** Number of days back from now the trend is measured over. */
	public int days()
	{
		return days;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.ospulse;

/**
 * Build-time constants.
 *
 * <p>The default committed value ships with the Plugin Hub build, whose name is
 * "OSPulse". A local sideloaded testing build ({@code ./gradlew -Pdev shadowJar})
 * replaces this class from a generated source dir so the plugin name is suffixed
 * " (dev)" and is distinguishable from the live Plugin Hub copy in the client's
 * plugin list (see {@code generateBuildInfo} in build.gradle).
 *
 * <p>It is a plain committed source file (not generated on the Hub build) so the
 * Plugin Hub packager, which compiles only {@code src/main/java} and does not run
 * custom Gradle tasks, resolves {@link #PLUGIN_NAME} at compile time.
 */
public final class BuildInfo
{
