		return suppliesUsed;
	}
}

package com.ospulse.session;

/**
 * Immutable per-holding unrealized P/L row: one currently-held tracked item,
 * its session cost basis (what the held quantity was "paid" for — live price
 * when first seen this session, averaged across later acquisitions), its
 * current live value, and the paper gain/loss between the two. Pure domain
 * type: no RuneLite imports, unit-testable without a game client.
 */
public final class HoldingPnl
{
	private final int itemId;
	private final String name;
	private final long quantity;
	/** Total cost basis of the held quantity, in gp. */
	private final long costBasis;
	/** Current live value of the held quantity, in gp. */
	private final long currentValue;

	public HoldingPnl(int itemId, String name, long quantity, long costBasis, long currentValue)
	{
		this.itemId = itemId;
		this.name = name;
		this.quantity = quantity;
		this.costBasis = costBasis;
		this.currentValue = currentValue;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getName()
	{
		return name;
	}

	public long getQuantity()
	{
		return quantity;
	}

	public long getCostBasis()
	{
		return costBasis;
	}

	public long getCurrentValue()
	{
		return currentValue;
	}

	/** Paper gain (positive) or loss (negative) on this holding, in gp. */
	public long unrealized()
	{
		return currentValue - costBasis;
	}

	@Override
	public String toString()
	{
		return "HoldingPnl{"
			+ "itemId=" + itemId
			+ ", name='" + name + '\''
			+ ", quantity=" + quantity
			+ ", costBasis=" + costBasis
			+ ", currentValue=" + currentValue
			+ '}';
	}
}

package com.ospulse.session;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parsed "<base> (<dose>)" shape of a dose-suffixed item name (potions,
 * brews, restores — anything named "...(1)" through "...(4)"), used only
 * to pair a dose-down within the same update (see {@link SessionEngine#update}).
 * Not related to {@link SupplyClassifier}'s broader consumable matching.
 */
final class DoseName
{
	private static final Pattern PATTERN =
		Pattern.compile("^(?<base>.+?)\\s*\\((?<dose>[1-4])\\)$", Pattern.CASE_INSENSITIVE);

	final String base;
	final int dose;

	private DoseName(String base, int dose)
	{
		this.base = base;
		this.dose = dose;
	}

	/** @return the parsed base/dose, or {@code null} if not dose-suffixed. */
	static DoseName parse(String name)
	{
		if (name == null)
		{
			return null;
		}
		Matcher m = PATTERN.matcher(name.trim());
		if (!m.matches())
		{
			return null;
		}
		return new DoseName(m.group("base").trim().toLowerCase(Locale.ROOT),
			Integer.parseInt(m.group("dose")));
	}
}

