	 * Sanguine scythe of vitur (25739, 25741).
	 *
	 * <p><b>The uncharged ids belong in this set.</b> Charging a scythe buys
	 * STATS ONLY, not the cascade: the OSRS Wiki's Scythe of vitur page
	 * states "While the scythe can be used uncharged, it is drastically
	 * stronger by charging it; once charged, it gains +20 stab/crush, +50
	 * slash attack bonus, +4 slash and +10 crush defence bonus and +25
	 * strength bonus" — an exhaustive list of what charging grants, and the
	 * size-scaled multi-hit passive is not on it (the page describes that
	 * passive in a separate sentence, unconditioned on charge state). Those
	 * deltas are exactly what the bundled {@code equipment_stats.min.json}
	 * already carries (22325 stab/slash/crush/str 70/125/30/75 vs 22486's
	 * 50/75/10/50), so the uncharged form's weaker DPS falls out of its own
	 * stats — it is NOT inflated by keeping the cascade here. Dropping these
	 * three ids would instead UNDER-model them, silently reverting an
	 * uncharged scythe to a single hit it does not actually lose. Pinned by
	 * {@code GearVariantsTest#scytheChargeState_unchargedKeepsCascadeAndIsWeakerOnStatsAlone}.
	 * (Reviewed twice, PR #24 rounds 4 and 5.)
	 */
	private static final Set<Integer> SCYTHE_OF_VITUR = setOf(
		22325, 22486, // Scythe of vitur
		25736, 25738, // Holy scythe of vitur
		25739, 25741  // Sanguine scythe of vitur
	);

	/** True when the worn weapon is any Scythe of Vitur variant (its size-scaled multi-hit cascade applies). */
	static boolean isScytheOfVitur(int weaponItemId)
	{
		return SCYTHE_OF_VITUR.contains(weaponItemId);
	}

	// ==== Colossal blade (flat target-size max-hit bonus) =================================

	/** Colossal blade — id 27021, verified against the bundled equipment_index.min.json 2026-07-26. */
	private static final int COLOSSAL_BLADE = 27021;

	/** True when the worn weapon is the Colossal blade (its flat +2*min(size,5) max-hit bonus applies). */
	static boolean isColossalBlade(int weaponItemId)
	{
		return weaponItemId == COLOSSAL_BLADE;
	}

	// ==== Keris partisan family (vs-Kalphite/Scarabite damage + triple-roll) ==============

	/**
	 * The five Keris partisan family ids, verified against the bundled
	 * {@code equipment_index.min.json} 2026-07-26: Keris partisan (25979),
	 * Keris partisan of amascut (30891, Tombs of Amascut reward), Keris
	 * partisan of breaching (25981 — the only variant with the additional
	 * vs-Kalphite accuracy bonus), Keris partisan of corruption (27287),
	 * Keris partisan of the sun (27291).
	 */
	private static final Map<Integer, KerisPartisan> KERIS_PARTISAN_IDS = new HashMap<>();
	static
	{
		KERIS_PARTISAN_IDS.put(25979, KerisPartisan.PARTISAN);
		KERIS_PARTISAN_IDS.put(30891, KerisPartisan.OF_AMASCUT);
		KERIS_PARTISAN_IDS.put(25981, KerisPartisan.OF_BREACHING);
		KERIS_PARTISAN_IDS.put(27287, KerisPartisan.OF_CORRUPTION);
		KERIS_PARTISAN_IDS.put(27291, KerisPartisan.OF_THE_SUN);
	}

	/** Maps a worn WEAPON-slot item id to its {@link KerisPartisan} variant ({@link KerisPartisan#NONE} if not a Keris). */
	public static KerisPartisan kerisPartisanFor(int weaponItemId)
	{
		return KERIS_PARTISAN_IDS.getOrDefault(weaponItemId, KerisPartisan.NONE);
	}

	// ==== Revenant weapons (Wilderness-only +50% accuracy/damage) ========================

	/**
	 * ONLY the CHARGED id of each revenant-cave weapon belongs in this map.
	 * The OSRS Wiki is explicit that the +50% Wilderness accuracy/damage
	 * passive requires the weapon to be charged with revenant ether — e.g.
	 * "When an ursine chainmace is charged with revenant ether, an
	 * additional 50% melee accuracy and damage boost is applied when
	 * attacking any NPC in the Wilderness" (same wording, mutatis mutandis,
	 * for Accursed sceptre / magic and Webweaver bow / ranged). The
	 * Uncharged id of each pair carries NO such bonus and must map to
	 * {@link RevenantWeapon#NONE}.
	 *
	 * <p>Crucially, the Uncharged and Charged forms of each weapon have
	 * IDENTICAL combat stats in the bundled {@code equipment_stats.min.json}
	 * (the only differing field is the trailing slot-hint, -1 vs 3, which is
	 * not a combat stat) — verified 2026-07-27. So nothing else absorbs the
	 * missing bonus for an uncharged id: mapping one here would be a straight
	 * +50% over-credit, not a harmless approximation.
	 *
	 * <p>Upgrade/Uncharged→Charged id pairs (both ids verified against the
	 * bundled {@code equipment_index.min.json} 2026-07-27; only the second id
	 * of each pair is mapped below):
	 * <ul>
	 * <li>Craw's bow: 22547 (uncharged) / 22550 (charged) — {@link RevenantWeapon#CRAWS_BOW}</li>
	 * <li>Webweaver bow: 27652 (uncharged) / 27655 (charged) — {@link RevenantWeapon#CRAWS_BOW} (ranged)</li>
	 * <li>Viggora's chainmace: 22542 (uncharged) / 22545 (charged) — {@link RevenantWeapon#VIGGORAS_CHAINMACE}</li>
	 * <li>Ursine chainmace: 27657 (uncharged) / 27660 (charged) — {@link RevenantWeapon#VIGGORAS_CHAINMACE} (melee)</li>
	 * <li>Thammaron's sceptre: 22552 (uncharged) / 22555 (charged) — {@link RevenantWeapon#THAMMARONS_SCEPTRE}</li>
	 * <li>Thammaron's sceptre (a): 27785 (uncharged) / 27788 (charged) — {@link RevenantWeapon#THAMMARONS_SCEPTRE}</li>
	 * <li>Accursed sceptre: 27662 (uncharged) / 27665 (charged) — {@link RevenantWeapon#THAMMARONS_SCEPTRE} (magic)</li>
	 * <li>Accursed sceptre (a): 27676 (uncharged) / 27679 (charged) — {@link RevenantWeapon#THAMMARONS_SCEPTRE}</li>
	 * </ul>
	 */
	/**
	 * <b>Known limitation — the optimiser cannot recommend BUYING one of these.</b>
	 * Only charged ids appear above (correctly: the passive needs ether). The
	 * charged forms are not purchasable, and the tradeable uncharged forms
	 * deliberately carry no passive, so a Wilderness optimisation can rank a
	 * revenant weapon below alternatives for a player who does not already own
	 * one — even though they could buy the uncharged item and charge it.
	 *
	 * <p>This is a MISSING FEATURE, not a regression. Mapping the uncharged ids
	 * would "fix" it only by reintroducing the defect this branch removed:
	 * granting +50% to a genuinely uncharged worn weapon. The real fix is an
	 * acquisition/state model in the optimiser — price a charged candidate from
	 * its tradeable base plus ether, while still scoring a worn uncharged item
	 * without the passive. That is general (scythe, Sanguinesti, tridents and
	 * the blowpipe all have the same buy-then-charge shape), so it belongs at
	 * the optimiser's pricing layer rather than in this id map. Raised on PR #24
	 * review round 13.
	 */
	private static final Map<Integer, RevenantWeapon> REVENANT_WEAPON_IDS = new HashMap<>();
	static
	{
		REVENANT_WEAPON_IDS.put(22550, RevenantWeapon.CRAWS_BOW);
		REVENANT_WEAPON_IDS.put(27655, RevenantWeapon.CRAWS_BOW);
		REVENANT_WEAPON_IDS.put(22545, RevenantWeapon.VIGGORAS_CHAINMACE);
		REVENANT_WEAPON_IDS.put(27660, RevenantWeapon.VIGGORAS_CHAINMACE);
		REVENANT_WEAPON_IDS.put(22555, RevenantWeapon.THAMMARONS_SCEPTRE);
		REVENANT_WEAPON_IDS.put(27788, RevenantWeapon.THAMMARONS_SCEPTRE);
		REVENANT_WEAPON_IDS.put(27665, RevenantWeapon.THAMMARONS_SCEPTRE);
		REVENANT_WEAPON_IDS.put(27679, RevenantWeapon.THAMMARONS_SCEPTRE);
	}

	/** Maps a worn WEAPON-slot item id to its {@link RevenantWeapon} ({@link RevenantWeapon#NONE} if not one). */
	public static RevenantWeapon revenantWeaponFor(int weaponItemId)
	{
		return REVENANT_WEAPON_IDS.getOrDefault(weaponItemId, RevenantWeapon.NONE);
	}

	// ==== Crystal armour set + crystal bow / Bow of Faerdhinen set effect =================

	/**
	 * ACTIVE (charged, fully-statted), OVERWORLD-usable Crystal helm ids —
	 * verified against the bundled {@code equipment_stats.min.json}
	 * 2026-07-26 by checking every combat-bonus field is nonzero: the
	 * pre-rework single "Crystal helm" (23971), the "beta" leftover
	 * (25495), and each of the seven Elf clan cosmetic recolours that got an
	 * armour reskin — Hefin/Ithell/Iorwerth/Trahaearn/Cadarn/Crwys/Amlodd
	 * (27705/27717/27729/27741/27753/27765/27777) plus the deadman-mode
	 * cosmetic (33031). Meilyr has NO armour recolour in the bundled data
	 * (only a weapon one) — verified, not assumed. The INACTIVE
	 * (uncharged/broken, all-zero-stat) counterpart of every one of these —
	 * a SEPARATE id sharing the identical display name — is deliberately
	 * EXCLUDED: crediting a zero-stat inactive piece with the active set
	 * bonus is exactly the prior P1-class defect the design spec warns
	 * about for this mechanic.
	 *
	 * <p><b>The basic/attuned/perfected tier ids (23886-23888) are
	 * deliberately EXCLUDED here too</b> — per review finding, these are The
	 * Gauntlet's INSTANCE-ONLY crystal equipment (see {@link
	 * com.ospulse.ui.sections.gear.ItemEligibility#isGauntletOnlyItem}'s own
	 * javadoc: "made from crystal shards in the instance, unusable/lost the
	 * moment the player leaves"), not the overworld Crystal armour set this
	 * mechanic models. {@code ItemEligibility} already treats the whole
	 * 23840-23903 range as Gauntlet-only for optimiser-candidate purposes;
	 * crediting them here as well — even from a LIVE equipped-gear read
	 * while literally inside the Gauntlet — would apply the overworld set's
	 * +15%/+30% bonus to gear that cannot exist outside that instance. The
	 * Gauntlet's own basic/attuned/perfected tiers have their own (unrelated,
	 * unmodelled) mechanics — out of scope here, not silently approximated.
	 */
	private static final Set<Integer> ACTIVE_CRYSTAL_HELM = setOf(
		23971, 25495,
		27705, 27717, 27729, 27741, 27753, 27765, 27777, 33031
	);

	/** ACTIVE, overworld-usable Crystal body ids — same provenance/exclusion notes as {@link #ACTIVE_CRYSTAL_HELM}. */
	private static final Set<Integer> ACTIVE_CRYSTAL_BODY = setOf(
		23975, 25496,
		27697, 27709, 27721, 27733, 27745, 27757, 27769, 33023
	);

	/** ACTIVE, overworld-usable Crystal legs ids — same provenance/exclusion notes as {@link #ACTIVE_CRYSTAL_HELM}. */
	private static final Set<Integer> ACTIVE_CRYSTAL_LEGS = setOf(
		23979, 25497,
		27701, 27713, 27725, 27737, 27749, 27761, 27773, 33027
	);

	/**
	 * ACTIVE, overworld-usable Crystal bow AND Bow of Faerdhinen ids —
	 * verified the same way as the armour pieces: the pre-rework single
	 * "Crystal bow" (23983), charged Bow of Faerdhinen (25865) and every one
	 * of its "(c)" cosmetic recolours (25867 plain, 25884 Ithell, 25886
	 * Iorwerth, 25888 Trahaearn, 25890 Cadarn, 25892 Crwys, 25894 Meilyr,
	 * 25896 Amlodd, 33021 deadman). The UNCHARGED Bow of Faerdhinen (25862,
	 * all-zero stats) is deliberately EXCLUDED — same "don't credit the
	 * inactive piece" reasoning. The basic/attuned/perfected Crystal bow
	 * tier ids (23901-23903) are ALSO deliberately excluded — same
	 * Gauntlet-instance-only reasoning as {@link #ACTIVE_CRYSTAL_HELM}.
	 */
	private static final Set<Integer> ACTIVE_CRYSTAL_BOW = setOf(
		23983,
		25865, 25867, 25884, 25886, 25888, 25890, 25892, 25894, 25896, 33021
	);

	/**
	 * True when the HEAD/BODY/LEGS slots all carry an ACTIVE Crystal armour
	 * piece — the "full armour set" half of the §9f condition; see {@link
	 * #isActiveCrystalBowOrFaerdhinen} for the weapon half. Both must hold
	 * for the set's +15% damage/+30% accuracy bonus to apply (see {@code
	 * DpsCalculator#computeRanged}).
	 *
	 * <p><b>Modelled as all-or-nothing</b>, mirroring {@link VoidSet}'s own
	 * all-or-nothing precedent — the OSRS Wiki documents the 30%/15% total
	 * as a sum of PER-PIECE contributions (helm 5%/2.5%, body 15%/7.5%, legs
	 * 10%/5%), so a partial set (e.g. body+legs but no helm) technically
	 * grants a partial bonus in-game. That per-piece partial credit is NOT
	 * modelled here — only the full-set case the design spec explicitly
	 * calls out ("Full set: +15% damage/+30% accuracy") — a disclosed,
	 * deliberate simplification, not an oversight.
	 */
	public static boolean isActiveCrystalArmourSet(int headItemId, int bodyItemId, int legsItemId)
	{
		return ACTIVE_CRYSTAL_HELM.contains(headItemId)
			&& ACTIVE_CRYSTAL_BODY.contains(bodyItemId)
			&& ACTIVE_CRYSTAL_LEGS.contains(legsItemId);
	}

	/** True when the worn weapon is an ACTIVE Crystal bow or Bow of Faerdhinen variant. */
	public static boolean isActiveCrystalBowOrFaerdhinen(int weaponItemId)
	{
		return ACTIVE_CRYSTAL_BOW.contains(weaponItemId);
	}

	// ==== Blowpipe (loads darts internally, ignores worn ammo) ============================

	/**
	 * True when {@code weaponItemId} is any blowpipe variant (Toxic/Blazing/
	 * Drygore/Camphor/Ironwood/Rosewood blowpipe, including future variants).
	 * Resolved via the bundled {@link EquipmentIndexRepository} display name
	 * rather than a hard-coded id list, since every current and future
	 * blowpipe variant's name contains "blowpipe" (verified against the
	 * bundled equipment_index.min.json 2026-07-04: Toxic/Blazing/Drygore/
	 * Camphor/Ironwood/Rosewood blowpipe, each with 1-2 ids per variant).
	 */
	public static boolean isBlowpipe(int weaponItemId)
	{
		EquipmentIndexRepository.Entry entry = EquipmentIndexRepository.getInstance().entryFor(weaponItemId);
		return entry != null && entry.name().toLowerCase(Locale.ROOT).contains("blowpipe");
	}

	private static Set<Integer> setOf(int... ids)
	{
		Set<Integer> set = new HashSet<>(ids.length * 2);
		for (int id : ids)
		{
			set.add(id);
		}
		return set;
	}
}

package com.ospulse.session;

import com.ospulse.combat.EquipmentStats;
import com.ospulse.combat.OffensivePrayer;

import lombok.Getter;
import lombok.experimental.Accessors;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;

/**
 * Immutable, live snapshot of the player's combat-relevant state: worn gear
 * (by item id, one slot per {@code net.runelite.api.EquipmentInventorySlot}
 * ordinal) plus base/boosted skill levels and active offensive prayers.
 *
 * <p>Deliberately has zero RuneLite dependency — {@code com.ospulse.integration.SessionTracker}
 * (on the client thread) is the only place that reads the live {@code Client}
 * and builds one of these, including resolving {@link #equipmentStats()} via
 * {@code ItemManager.getItemStats} <b>on the client thread</b> (that call
 * internally asserts the client thread and must never be made from the EDT);
 * {@code com.ospulse.ui.sections.GearSection} (on the EDT) only ever reads
 * the precomputed fields of this snapshot to drive the
 * {@code com.ospulse.combat} DPS engine. This keeps the gear-&gt;DPS mapping
 * pure and unit-testable without a running game client.
 */
@Accessors(fluent = true)
public final class GearSnapshot
{
	/** {@code net.runelite.api.EquipmentInventorySlot.values().length} — kept in sync manually since this class has no RuneLite dependency. */
	public static final int EQUIPMENT_SLOT_COUNT = 14;

	private static final GearSnapshot EMPTY = builder().build();

	private final int[] equippedItemIds;
	@Getter
	private final int baseAttack;
	@Getter
	private final int boostedAttack;
	@Getter
	private final int baseStrength;
	@Getter
	private final int boostedStrength;
	@Getter
	private final int baseDefence;
	@Getter
	private final int boostedDefence;
	@Getter
	private final int baseRanged;
	@Getter
	private final int boostedRanged;
	@Getter
	private final int baseMagic;
	@Getter
	private final int boostedMagic;
	@Getter
	private final int basePrayer;
	@Getter
	private final int boostedPrayer;
	@Getter
	private final int baseHitpoints;
	@Getter
	private final int boostedHitpoints;
	@Getter
	private final int baseSlayer;
	@Getter
	private final int boostedSlayer;
	@Getter
	private final int baseAgility;
	@Getter
	private final int boostedAgility;
	@Getter
	private final Set<OffensivePrayer> activePrayers;
	/**
	 * TODO Phase 2+: on-task Slayer detection is not wired to a live client
	 * read yet (no confirmed API in the design brief's integration section);
	 * always {@code false} for now, so Slayer helm(i)/black mask(i) on-task
	 * bonuses never apply until this is read live.
	 */
	@Getter
	private final boolean onSlayerTask;
	/**
	 * Pre-summed loadout-wide {@link EquipmentStats}, resolved once on the
	 * client thread by {@code SessionTracker.buildGear()} (via {@code
	 * GearMapper.buildEquipmentStats} + {@code ItemManager.getItemStats}) —
	 * never on the EDT. {@code null} for {@link #empty()} / whenever no live
	 * gear has been resolved yet.
	 */
	private final EquipmentStats equipmentStats;
	/**
	 * Raw value of the in-game autocast-spell varbit ({@code
	 * gameval.VarbitID.AUTOCAST_SPELL}, id 276): the spell the player has set to
	 * auto-cast, as the game's internal autocast id. This is NOT one of our
	 * {@link com.ospulse.combat.Spell} ids — the value-&gt;spell mapping is cache
	 * data that must be captured in-client (see {@code SessionTracker.buildGear}'s
	 * debug log) before the magic readout can resolve it. {@code -1} (or {@code 0})
	 * means no autocast spell is set. Exposed so the {@code GearSection} secondary
	 * readout can eventually show the actual current cast instead of the
	 * next-best-DPS fallback.
	 */
	private final int autocastSpellId;

	private GearSnapshot(Builder b)
	{
		this.equippedItemIds = normalizeSlots(b.equippedItemIds);
		this.baseAttack = b.baseAttack;
		this.boostedAttack = b.boostedAttack;
		this.baseStrength = b.baseStrength;
		this.boostedStrength = b.boostedStrength;
		this.baseDefence = b.baseDefence;
		this.boostedDefence = b.boostedDefence;
		this.baseRanged = b.baseRanged;
		this.boostedRanged = b.boostedRanged;
		this.baseMagic = b.baseMagic;
		this.boostedMagic = b.boostedMagic;
		this.basePrayer = b.basePrayer;
		this.boostedPrayer = b.boostedPrayer;
		this.baseHitpoints = b.baseHitpoints;
		this.boostedHitpoints = b.boostedHitpoints;
		this.baseSlayer = b.baseSlayer;
		this.boostedSlayer = b.boostedSlayer;
		this.baseAgility = b.baseAgility;
		this.boostedAgility = b.boostedAgility;
		this.activePrayers = b.activePrayers.isEmpty()
			? Collections.emptySet()
			: Collections.unmodifiableSet(EnumSet.copyOf(b.activePrayers));
		this.onSlayerTask = b.onSlayerTask;
		this.equipmentStats = b.equipmentStats;
		this.autocastSpellId = b.autocastSpellId;
	}

	private static int[] normalizeSlots(int[] raw)
	{
		if (raw == null)
		{
			int[] empty = new int[EQUIPMENT_SLOT_COUNT];
			Arrays.fill(empty, -1);
			return empty;
		}
		return Arrays.copyOf(raw, raw.length);
	}

	/** Shared empty instance: no gear, all levels 0, no active prayers. Used as the default before the first live snapshot. */
	public static GearSnapshot empty()
	{
		return EMPTY;
	}

	public static Builder builder()
	{
		return new Builder();
	}

	/**
	 * Worn item id per {@code EquipmentInventorySlot} ordinal (0=HEAD .. 13=AMMO);
	 * {@code -1} (or {@code 0}) means the slot is empty.
	 */
	public int[] equippedItemIds()
	{
		return Arrays.copyOf(equippedItemIds, equippedItemIds.length);
	}

	public int itemIdAt(int slotOrdinal)
	{
		return slotOrdinal >= 0 && slotOrdinal < equippedItemIds.length ? equippedItemIds[slotOrdinal] : -1;
	}

	/**
	 * Pre-summed loadout-wide equipment bonuses, or {@code null} if not yet
	 * resolved (e.g. {@link #empty()}). Safe to read on any thread, including
	 * the EDT — all the client-thread-only resolution already happened when
	 * this snapshot was built.
	 */
	public EquipmentStats equipmentStats()
	{
		return equipmentStats;
	}

	/**
	 * Raw in-game autocast-spell varbit value (id 276); {@code -1}/{@code 0} =
	 * none set. See the field javadoc — this is the game's internal autocast id,
	 * not a {@link com.ospulse.combat.Spell} id, and needs an in-client-captured
	 * mapping before it can be resolved to a named spell.
	 */
	public int autocastSpellId()
	{
		return autocastSpellId;
	}

	public static final class Builder
	{
		private int[] equippedItemIds;
		private int baseAttack;
		private int boostedAttack;
		private int baseStrength;
		private int boostedStrength;
		private int baseDefence;
		private int boostedDefence;
		private int baseRanged;
		private int boostedRanged;
		private int baseMagic;
		private int boostedMagic;
		private int basePrayer;
		private int boostedPrayer;
		private int baseHitpoints;
		private int boostedHitpoints;
		private int baseSlayer;
		private int boostedSlayer;
		private int baseAgility;
		private int boostedAgility;
		private Set<OffensivePrayer> activePrayers = EnumSet.noneOf(OffensivePrayer.class);
		private boolean onSlayerTask;
		private EquipmentStats equipmentStats;
		private int autocastSpellId = -1;

		private Builder()
		{
		}

		public Builder equippedItemIds(int[] ids)
		{
			this.equippedItemIds = ids;
			return this;
		}

		public Builder attack(int base, int boosted)
		{
			this.baseAttack = base;
			this.boostedAttack = boosted;
			return this;
		}

		public Builder strength(int base, int boosted)
		{
			this.baseStrength = base;
			this.boostedStrength = boosted;
			return this;
		}

		public Builder defence(int base, int boosted)
		{
			this.baseDefence = base;
			this.boostedDefence = boosted;
			return this;
		}

		public Builder ranged(int base, int boosted)
		{
			this.baseRanged = base;
			this.boostedRanged = boosted;
			return this;
		}

		public Builder magic(int base, int boosted)
		{
			this.baseMagic = base;
			this.boostedMagic = boosted;
			return this;
		}

		public Builder prayer(int base, int boosted)
		{
			this.basePrayer = base;
			this.boostedPrayer = boosted;
			return this;
		}

		public Builder hitpoints(int base, int boosted)
		{
			this.baseHitpoints = base;
			this.boostedHitpoints = boosted;
			return this;
		}

		public Builder slayer(int base, int boosted)
		{
			this.baseSlayer = base;
			this.boostedSlayer = boosted;
			return this;
		}

		public Builder agility(int base, int boosted)
		{
			this.baseAgility = base;
			this.boostedAgility = boosted;
			return this;
		}

		public Builder activePrayers(Set<OffensivePrayer> prayers)
		{
			this.activePrayers = (prayers == null || prayers.isEmpty())
				? EnumSet.noneOf(OffensivePrayer.class)
				: EnumSet.copyOf(prayers);
			return this;
		}

		public Builder onSlayerTask(boolean value)
		{
			this.onSlayerTask = value;
			return this;
		}

		public Builder equipmentStats(EquipmentStats equipmentStats)
		{
			this.equipmentStats = equipmentStats;
			return this;
		}

		/** Raw autocast-spell varbit value (id 276); {@code -1}/{@code 0} = none. */
		public Builder autocastSpellId(int id)
		{
			this.autocastSpellId = id;
			return this;
		}

		public GearSnapshot build()
		{
			return new GearSnapshot(this);
		}
	}
}

package com.ospulse.session;

import com.ospulse.model.ItemStack;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Loot aggregated by its <em>source</em> (the NPC / boss / activity that
 * produced it), mirroring how the Loot Tracker plugin groups drops. One
 * {@code SourceLoot} = one collapsible group in the panel: a source name, how
 * many times loot was received from it this session ({@link #getCount()}), the
 * summed value, and the per-item rows (already sorted by value descending).
 *
 * <p>Pure domain type: no RuneLite imports, unit-testable without a game client.
 */
public final class SourceLoot
{
	private final String source;
	private final long totalValue;
	private final long count;
	private final List<ItemStack> items;

	public SourceLoot(String source, long totalValue, long count, List<ItemStack> items)
	{
		this.source = source;
		this.totalValue = totalValue;
		this.count = count;
		this.items = items == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(items));
	}

	public String getSource()
	{
		return source;
	}

	public long getTotalValue()
	{
		return totalValue;
	}

	/** Number of loot drops received from this source this session (e.g. kill count). */
	public long getCount()
	{
		return count;
	}

	public List<ItemStack> getItems()
	{
		return items;
	}
}

package com.ospulse.session;

/**
 * Read-side seam over the live session tracker. The integration layer
 * implements this; the panel UI and the sync/persistence layers consume it,
 * so neither depends on RuneLite-specific wiring.
 */
public interface SessionService
{
	/**
	 * The most recent snapshot, or {@code null} if no snapshot has been
	 * produced yet (e.g. before login / first tick).
	 */
	SessionSnapshot getLatest();

	/** Registers a listener to be notified on each new snapshot. */
	void addListener(SessionListener listener);

	/** Removes a previously-registered listener. */
	void removeListener(SessionListener listener);
}

package com.ospulse.session;

/**
 * Notified whenever the tracked session produces a fresh {@link SessionSnapshot}.
 *
 * <p>Called on whatever thread the integration layer computes snapshots on
 * (typically the RuneLite client thread). Listeners that touch Swing must
 * marshal to the EDT themselves.
 */
@FunctionalInterface
public interface SessionListener
{
	void onSessionUpdate(SessionSnapshot snapshot);
}

package com.ospulse.session;

import com.ospulse.ge.GeOfferView;
import com.ospulse.wealth.WealthSnapshot;
import com.ospulse.xp.XpSkillView;

import lombok.Getter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Immutable output DTO summarising the current state of a tracked session.
 * The {@link #getLoot()} list is aggregated per item and ordered by total
 * value descending (index 0 = most valuable item this session).
 */
public final class SessionSnapshot
{
	@Getter
	private final long startMs;
	@Getter
	private final long elapsedMs;
	/**
	 * Session "Loot": gp value of items actually picked up — realised wealth
	 * gains with GE flip P&amp;L removed (flips are surfaced on their own line
	 * via {@link #getGeRealizedPnl()} and would otherwise double-count). Distinct
	 * from {@link #getLoot()}, which is the itemised loot FEED (all drops,
	 * event-based) and need not equal this value: looting nothing leaves this at
	 * zero even when the feed shows drops. Selling looted items is not a flip, so
	 * that value stays here.
	 */
	@Getter
	private final long lootValue;
	@Getter
	private final long profitPerHour;
	@Getter
	private final long geRealizedPnl;
	/**
	 * "Net worth change" — the LOCKED session-panel model: the SUM of {@code
	 * getNetProfit()} (Loot − Supplies), {@link #getGeRealizedPnl()} (GE flip),
	 * {@link #getGePositions()} (GE positions) and {@link #getBankDelta()}
	 * (Bank). Held/worn/inventory gear price drift deliberately contributes to
	 * none of the four and so never shows here — it is zeroed until the item
	 * transacts (sold via GE, banked, or consumed/looted). Always the FULL,
	 * untoggled sum; a session-panel include/exclude toggle on GE positions or
	 * Bank (default both on) is display-only and subtracts the relevant raw
	 * component when rendering, never mutating this value.
	 */
	@Getter
	private final long netWorthDelta;
	@Getter
	private final boolean bankKnown;
	/**
	 * Loot aggregated per item (one row per distinct item, quantities and
	 * values summed across the session), ordered by total value descending.
	 */
	@Getter
	private final List<LootEntry> loot;
	@Getter
	private final Map<String, Long> xpGained;
	@Getter
	private final long xpTotal;
	@Getter
	private final WealthSnapshot wealth;
	/**
	 * Active Grand Exchange offers (buy/sell), for the panel's GE breakdown.
	 * Empty when there are no active offers.
	 */
	@Getter
	private final List<GeOfferView> geOffers;
	/**
	 * Loot grouped by source (NPC/boss/activity), ordered by total value
	 * descending — the collapsible Loot-Tracker-style feed. Empty when nothing
	 * has been looted yet this session.
	 */
	@Getter
	private final List<SourceLoot> lootSources;
	/**
	 * Per-skill XP progress views (gained, rate, xp/actions left, level
	 * progress), ordered by XP gained descending. Empty until the integration
	 * layer supplies them (e.g. before the first XP gain of the session).
	 */
	@Getter
	private final List<XpSkillView> xpSkills;
	/** Overall XP gained per hour across all skills; 0 while elapsed is 0. */
	@Getter
	private final long xpPerHour;
	/**
	 * Live worn gear + boosted levels + active prayers for the Gear/DPS
	 * calculator section. Never {@code null} — defaults to
	 * {@link GearSnapshot#empty()} for snapshots built before that plumbing
	 * existed (older constructors) or before the first live read.
	 */
	@Getter
	private final GearSnapshot gear;
	/**
	 * Total unrealized P/L: current holdings valued at live price minus their
	 * session cost basis. Pure price drift on held items moves this figure —
	 * never {@link #getLootValue()}, which is realised activity only.
	 */
	@Getter
	private final long unrealizedPnl;
	/**
	 * Per-holding unrealized P/L breakdown (cost basis vs current value per
	 * held item), ordered by absolute unrealized amount descending — the rows
	 * sum to {@link #getUnrealizedPnl()}. Empty when nothing is held or the
	 * engine predates cost-basis tracking (older constructors).
	 */
	@Getter
	private final List<HoldingPnl> holdingPnls;
	/**
	 * Running session total (gp value) of consumable supplies used
	 * (potions/food/ammo/runes drained from inventory while away from the
	 * bank and not attributable to a GE sale). This spend is excluded from
	 * {@link #getLootValue()} — consuming a supply neither gains nor loses
	 * loot value, it just moves value from "held" to "used" — so this figure is
	 * the dedicated place that spend is visible, not a duplicate of a
	 * reduction already visible in loot value. Zero for snapshots built before
	 * this tracking existed (older constructors).
	 */
	@Getter
	private final long suppliesUsed;
	/**
	 * "GE positions" — the LOCKED session-panel model's unrealised
	 * mark-to-market on open/collectable Grand Exchange offers: current pool
	 * value ({@code geInFlight + geCollectable}) minus the pool's cost basis.
	 * Moving the player's own coins/items into an offer never moves this figure
	 * (entries are added to the cost basis at the same live value that left
	 * tracked wealth); only genuine repricing while the value sits in the GE
	 * (a favourable/unfavourable fill, a sell offer's unsold remainder
	 * repricing) does. One of the four components summed into {@link
	 * #getNetWorthDelta()}; a session-panel toggle (default on) may exclude it
	 * from the displayed "Net worth change" without affecting this raw value.
	 */
	@Getter
	private final long gePositions;
	/**
	 * "Bank" — the LOCKED session-panel model's bank component: current bank
	 * value minus the session's Bank-line anchor. A deposit/withdrawal (the
	 * player's own money moving in/out) cancels to zero here; price wobble on
	 * ALREADY-banked contents (a GE price reload while the bank sits closed)
	 * shows through, since that is real wealth movement on cold storage. One of
	 * the four components summed into {@link #getNetWorthDelta()}; a
	 * session-panel toggle (default on) may exclude it from the displayed "Net
	 * worth change" without affecting this raw value.
	 */
	@Getter
	private final long bankDelta;
	/**
	 * Session-cumulative profit/loss of skilling episodes: what conversion
	 * activity (Herblore/Crafting/Fletching/Smithing/Cooking) did to wealth,
	 * net of any loot booked during those windows. Negative when you craft at a
	 * loss. Folded into {@link #getNetProfit()}; exposed separately for
	 * diagnostics and display, NOT as a fifth net-worth component.
	 */
	@Getter
	private final long episodePnl;

	/**
	 * Backward-compatible constructor: no active-offer / source-loot breakdown.
	 * Delegates to the full constructor with empty lists.
	 */
	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth)
	{
		this(startMs, elapsedMs, lootValue, profitPerHour, geRealizedPnl, netWorthDelta,
			bankKnown, loot, xpGained, xpTotal, wealth, Collections.emptyList(),
			Collections.emptyList());
	}

	/**
	 * Backward-compatible constructor: no per-skill XP views / overall XP rate.
	 * Delegates to the full constructor with empty defaults.
	 */
	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth,
		List<GeOfferView> geOffers,
		List<SourceLoot> lootSources)
	{
		this(startMs, elapsedMs, lootValue, profitPerHour, geRealizedPnl, netWorthDelta,
			bankKnown, loot, xpGained, xpTotal, wealth, geOffers, lootSources,
			Collections.emptyList(), 0L);
	}

	/**
	 * Backward-compatible constructor: no {@link GearSnapshot}. Delegates to the
	 * full constructor with {@code gear = null}, which is normalised to
	 * {@link GearSnapshot#empty()}.
	 */
	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth,
		List<GeOfferView> geOffers,
		List<SourceLoot> lootSources,
		List<XpSkillView> xpSkills,
		long xpPerHour)
	{
		this(startMs, elapsedMs, lootValue, profitPerHour, geRealizedPnl, netWorthDelta,
			bankKnown, loot, xpGained, xpTotal, wealth, geOffers, lootSources,
			xpSkills, xpPerHour, null);
	}

	/**
	 * Backward-compatible constructor: no unrealized-P/L figures. Delegates to
	 * the full constructor with {@code unrealizedPnl = 0} and no per-holding
	 * breakdown.
	 */
	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth,
		List<GeOfferView> geOffers,
		List<SourceLoot> lootSources,
		List<XpSkillView> xpSkills,
		long xpPerHour,
		GearSnapshot gear)
	{
		this(startMs, elapsedMs, lootValue, profitPerHour, geRealizedPnl, netWorthDelta,
			bankKnown, loot, xpGained, xpTotal, wealth, geOffers, lootSources,
			xpSkills, xpPerHour, gear, 0L, Collections.emptyList());
	}

	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth,
		List<GeOfferView> geOffers,
		List<SourceLoot> lootSources,
		List<XpSkillView> xpSkills,
		long xpPerHour,
		GearSnapshot gear,
		long unrealizedPnl,
		List<HoldingPnl> holdingPnls)
	{
		this(startMs, elapsedMs, lootValue, profitPerHour, geRealizedPnl, netWorthDelta,
			bankKnown, loot, xpGained, xpTotal, wealth, geOffers, lootSources,
			xpSkills, xpPerHour, gear, unrealizedPnl, holdingPnls, 0L);
	}

	/**
	 * Backward-compatible constructor: no GE-positions / Bank component
	 * breakdown. Delegates to the full constructor with both zeroed.
	 */
	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth,
		List<GeOfferView> geOffers,
		List<SourceLoot> lootSources,
		List<XpSkillView> xpSkills,
		long xpPerHour,
		GearSnapshot gear,
		long unrealizedPnl,
		List<HoldingPnl> holdingPnls,
		long suppliesUsed)
	{
		this(startMs, elapsedMs, lootValue, profitPerHour, geRealizedPnl, netWorthDelta,
			bankKnown, loot, xpGained, xpTotal, wealth, geOffers, lootSources,
			xpSkills, xpPerHour, gear, unrealizedPnl, holdingPnls, suppliesUsed, 0L, 0L);
	}

	/**
	 * Full constructor including {@code suppliesUsed} — the running session
	 * total (gp value) of consumable supplies (potions/food/ammo/runes)
	 * consumed, as distinct from {@code lootValue} (unchanged: realised
	 * activity only) — and the LOCKED session-panel model's {@code
	 * gePositions} / {@code bankDelta} components, whose sum with {@code
	 * lootValue - suppliesUsed} and {@code geRealizedPnl} defines {@code
	 * netWorthDelta} ("Net worth change" — see {@link SessionEngine#snapshot}).
	 */
	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth,
		List<GeOfferView> geOffers,
		List<SourceLoot> lootSources,
		List<XpSkillView> xpSkills,
		long xpPerHour,
		GearSnapshot gear,
		long unrealizedPnl,
		List<HoldingPnl> holdingPnls,
		long suppliesUsed,
		long gePositions,
		long bankDelta)
	{
		this(startMs, elapsedMs, lootValue, profitPerHour, geRealizedPnl, netWorthDelta,
			bankKnown, loot, xpGained, xpTotal, wealth, geOffers, lootSources,
			xpSkills, xpPerHour, gear, unrealizedPnl, holdingPnls, suppliesUsed,
			gePositions, bankDelta, 0L);
	}

	/**
	 * Full constructor including {@code episodePnl} — the session-cumulative
	 * profit/loss of skilling episodes (see {@link SessionEngine}'s episode
	 * ledger). It is a component of {@link #getNetProfit() Profit}, NOT a fifth
	 * component of the LOCKED net-worth model: crafting is neither loot nor a
	 * GE flip nor a bank movement, it is realised activity, and Profit is where
	 * realised activity belongs.
	 */
	public SessionSnapshot(
		long startMs,
		long elapsedMs,
		long lootValue,
		long profitPerHour,
		long geRealizedPnl,
		long netWorthDelta,
		boolean bankKnown,
		List<LootEntry> loot,
		Map<String, Long> xpGained,
		long xpTotal,
		WealthSnapshot wealth,
		List<GeOfferView> geOffers,
		List<SourceLoot> lootSources,
		List<XpSkillView> xpSkills,
		long xpPerHour,
		GearSnapshot gear,
		long unrealizedPnl,
		List<HoldingPnl> holdingPnls,
		long suppliesUsed,
		long gePositions,
		long bankDelta,
		long episodePnl)
	{
		this.startMs = startMs;
		this.elapsedMs = elapsedMs;
		this.lootValue = lootValue;
		this.profitPerHour = profitPerHour;
		this.geRealizedPnl = geRealizedPnl;
		this.netWorthDelta = netWorthDelta;
		this.bankKnown = bankKnown;
		this.loot = loot == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(loot));
		this.xpGained = xpGained == null
			? Collections.emptyMap()
			: Collections.unmodifiableMap(new LinkedHashMap<>(xpGained));
		this.xpTotal = xpTotal;
		this.wealth = wealth;
		this.geOffers = geOffers == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(geOffers));
		this.lootSources = lootSources == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(lootSources));
		this.xpSkills = xpSkills == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(xpSkills));
		this.xpPerHour = xpPerHour;
		this.gear = gear == null ? GearSnapshot.empty() : gear;
		this.unrealizedPnl = unrealizedPnl;
		this.holdingPnls = holdingPnls == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(holdingPnls));
		this.suppliesUsed = suppliesUsed;
		this.gePositions = gePositions;
		this.bankDelta = bankDelta;
		this.episodePnl = episodePnl;
	}

	/**
	 * Session net profit: {@link #getLootValue() loot value}, minus the
	 * {@link #getSuppliesUsed() consumable spend} burned to earn it, plus the
	 * {@link #getEpisodePnl() episode P&L} of any skilling done. This is the
	 * true bottom line — what you actually walked away with — whereas
	 * {@code getLootValue()} is gross loot before supply cost.
	 * {@link #getProfitPerHour()} is the hourly extrapolation of THIS figure,
	 * so an hour that nets negative after supplies reads negative here too.
	 *
	 * <p>The episode term is what stops crafting at a loss from reading as pure
	 * upside. Bottom-up accounting can only see loot and recognised consumables,
	 * so an unrecognised input (a herb: not a potion, not food, never looted)
	 * used to cost nothing while its output credited at full value.
	 */
	public long getNetProfit()
	{
		return lootValue - suppliesUsed + episodePnl;
	}
}

package com.ospulse.session;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

/**
 * A per-item-id FIFO of not-yet-matched receipted quantity, aging toward
 * expiry — the shared cross-tick netting seam behind two independent
 * consumers that both need exactly the same guarantee.
 *
 * <p><b>Why this exists.</b> RuneLite's {@code LootReceived} for an ordinary
 * NPC kill fires as soon as the loot is known — at the NPC's death — not when
 * the player later walks over and picks it up; the inventory diff for that
 * pickup can land several ticks after the receipt (confirmed by decompiling
 * {@code client-1.12.33.jar}: the event is raised from the death/loot-roll
 * code path, never from the ground-item pickup path). A receipt that isn't
 * matched on its own tick is therefore not stale; it stays eligible to net
 * against the diff whenever the pickup actually happens, up to the
 * configured window. Past that window it is dropped: either it was never
 * picked up (looted by someone else, despawned) or matching it this late
 * would risk swallowing a genuinely new, unrelated appearance of the same id.
 *
 * <p>Two independent consumers need exactly this:
 * <ul>
 *   <li>{@code com.ospulse.integration.SessionTracker}'s loot feed: a
 *       receipted kill must not double-count as {@code Inventory
 *       (unattributed)} when its pickup is only observed on a later tick.</li>
 *   <li>{@link SessionEngine}'s episode ledger: an unvouched appearance
 *       during an open production episode is credited as manufactured output
 *       only up to the value of inputs actually charged — a receipted
 *       appearance must still be recognised as genuine loot (not manufactured
 *       output) even when the receipt fired several ticks before the pickup
 *       landed.</li>
 * </ul>
 *
 * <p>Each consumer owns its own instance — they track different quantities
 * for different purposes and clear at different points in their own
 * lifecycle — but the FIFO netting and age-based expiry are identical, so
 * that logic lives once here rather than being maintained twice.
 *
 * <p>Mutable, single-threaded use only. Not thread-safe.
 */
public final class OutstandingReceiptLedger
{
	/** One not-yet-matched slice of a receipt, aging toward expiry. */
	private static final class Entry
	{
		long quantity;
		final long tsMs;

		Entry(long quantity, long tsMs)
		{
			this.quantity = quantity;
			this.tsMs = tsMs;
		}
	}

	private final long windowMs;
	private final Map<Integer, Deque<Entry>> pool = new HashMap<>();

	/**
	 * @param windowMs how long an entry stays eligible to net against a later
	 *                  claim before {@link #pruneExpired} drops it as stale.
	 */
	public OutstandingReceiptLedger(long windowMs)
	{
		this.windowMs = windowMs;
	}

	/** Records {@code quantity} of {@code itemId} as an outstanding, not-yet-matched receipt. */
	public void record(int itemId, long quantity, long tsMs)
	{
		if (quantity <= 0)
		{
			return;
		}
		pool.computeIfAbsent(itemId, k -> new ArrayDeque<>()).addLast(new Entry(quantity, tsMs));
	}

	/**
	 * Nets {@code quantity} of {@code itemId} against the oldest outstanding
	 * entries first (FIFO), consuming/removing them as they're used up.
	 * Returns whatever quantity is left unmatched — the genuine, never-
	 * receipted remainder. Does NOT prune by age itself; call {@link
	 * #pruneExpired} first (once per tick/update, not once per item, for
	 * efficiency) so an expired entry is never netted against.
	 */
	public long claim(int itemId, long quantity)
	{
		Deque<Entry> pending = pool.get(itemId);
		if (pending == null)
		{
			return quantity;
		}
		long remaining = quantity;
		while (remaining > 0 && !pending.isEmpty())
		{
			Entry head = pending.peekFirst();
			long netted = Math.min(remaining, head.quantity);
			head.quantity -= netted;
			remaining -= netted;
			if (head.quantity <= 0)
			{
				pending.pollFirst();
			}
		}
		if (pending.isEmpty())
		{
			pool.remove(itemId);
		}
		return remaining;
	}

	/**
	 * Drops every entry older than the configured window (across all ids) so
	 * an item that was never picked up cannot sit around indefinitely and
	 * wrongly net out an unrelated later find.
	 */
	public void pruneExpired(long tsMs)
	{
		Iterator<Map.Entry<Integer, Deque<Entry>>> it = pool.entrySet().iterator();
		while (it.hasNext())
		{
			Deque<Entry> pending = it.next().getValue();
			while (!pending.isEmpty() && tsMs - pending.peekFirst().tsMs > windowMs)
			{
				pending.pollFirst();
			}
			if (pending.isEmpty())
			{
				it.remove();
			}
		}
	}

	/** Clears all state — for a new session/login, so a stale entry never survives into a fresh one. */
	public void clear()
	{
		pool.clear();
	}
}

package com.ospulse.session;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Immutable per-tick bundle of deliberate item-movement signals fed to {@link SessionEngine#update}. */
public final class MovementSignals
{
	public static final MovementSignals NONE = builder().build();

	private final Set<Integer> droppedItemIds;
	private final Set<Integer> destroyedItemIds;
	private final boolean diedThisTick;
	private final List<LootReceipt> lootReceipts;
	private final Map<Integer, Long> storageEmptied;
	private final boolean productionXp;
	private final boolean productionAnimation;

	private MovementSignals(Builder b)
	{
		this.droppedItemIds = Collections.unmodifiableSet(new HashSet<>(b.droppedItemIds));
		this.destroyedItemIds = Collections.unmodifiableSet(new HashSet<>(b.destroyedItemIds));
		this.diedThisTick = b.diedThisTick;
		this.lootReceipts = Collections.unmodifiableList(new ArrayList<>(b.lootReceipts));
		this.storageEmptied = Collections.unmodifiableMap(new LinkedHashMap<>(b.storageEmptied));
		this.productionXp = b.productionXp;
		this.productionAnimation = b.productionAnimation;
	}

	public Set<Integer> droppedItemIds() { return droppedItemIds; }
	public Set<Integer> destroyedItemIds() { return destroyedItemIds; }
	public boolean diedThisTick() { return diedThisTick; }
	public List<LootReceipt> lootReceipts() { return lootReceipts; }

	/**
	 * XP was gained this tick in a production skill (see
	 * {@link ProductionActivity#isProductionSkill}).
	 */
	public boolean productionXp() { return productionXp; }

	/**
	 * The player was performing a production animation this tick (see
	 * {@link ProductionActivity#isProductionAnimation}).
	 *
	 * <p>Kept SEPARATE from {@link #productionXp()} rather than pre-OR-ed by
	 * the caller, because the two are not interchangeable: herblore's unf-making
	 * step grants no XP at all, so animation is the only signal that sees it.
	 * Keeping them distinct lets that case be tested in isolation, which is the
	 * exact hole an XP-only trigger leaves open.
	 */
	public boolean productionAnimation() { return productionAnimation; }

	/**
	 * Exact contents (item id → quantity) emptied from a tracked storage
	 * container straight into the bank this tick (a fish barrel emptied at a
	 * bank/deposit box — fish never touch the inventory). Lets the engine draw
	 * the precise ledger entries that materialise in the bank instead of
	 * attributing an id-blind bank-value rise (see
	 * {@link SessionEngine} stored-loot materialisation).
	 */
	public Map<Integer, Long> storageEmptied() { return storageEmptied; }

	public static Builder builder() { return new Builder(); }

	public static final class Builder
	{
		private final Set<Integer> droppedItemIds = new HashSet<>();
		private final Set<Integer> destroyedItemIds = new HashSet<>();
		private boolean diedThisTick;
		private final List<LootReceipt> lootReceipts = new ArrayList<>();
		private final Map<Integer, Long> storageEmptied = new LinkedHashMap<>();
		private boolean productionXp;
		private boolean productionAnimation;

		public Builder dropped(int itemId) { droppedItemIds.add(itemId); return this; }
		public Builder destroyed(int itemId) { destroyedItemIds.add(itemId); return this; }
		public Builder died(boolean died) { this.diedThisTick = died; return this; }
		public Builder lootReceived(LootReceipt r) { lootReceipts.add(r); return this; }

		/** Records that a production skill gained XP this tick. */
		public Builder productionXp() { this.productionXp = true; return this; }

		/** Records that a production animation was playing this tick. */
		public Builder productionAnimation() { this.productionAnimation = true; return this; }

		/** Records {@code qty} of {@code itemId} emptied from a storage container into the bank this tick. */
		public Builder storageEmptied(int itemId, long qty)
		{
			if (qty > 0)
			{
				storageEmptied.merge(itemId, qty, Long::sum);
			}
			return this;
		}

		public MovementSignals build() { return new MovementSignals(this); }
	}
}

package com.ospulse.session;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Bottom-up accounting for the Session panel's "Loot" line: the value of items
 * the player gained this session, held at pickup value and swapped to the actual
 * after-tax Grand Exchange sale proceeds once sold.
 *
 * <p>Location-independent: a looted item counts as held whether it sits in the
 * inventory or the bank, so banking is a no-op here. Consuming a looted item is
 * also a no-op — it stays counted as loot and its spend surfaces via
 * {@code suppliesUsed}, so Profit = Loot - Supplies nets it out.
 *
 * <p>Mutable, single-threaded use only. Not thread-safe.
 */
public final class LootLedger
{
	/** Held (looted, not-yet-sold) quantity of an item and the pickup value of that quantity. */
	private static final class Held
	{
		long quantity;
		long value;
	}

	private final Map<Integer, Held> held = new LinkedHashMap<>();
	private long realised;

	/** Records a classified loot gain of {@code quantity} units at {@code unitPickupValue} each. */
	public void recordLoot(int itemId, long quantity, long unitPickupValue)
	{
		if (quantity <= 0)
		{
			return;
		}
		Held h = held.computeIfAbsent(itemId, k -> new Held());
		h.quantity += quantity;
		h.value += quantity * unitPickupValue;
	}

	/**
	 * Reverses up to {@code quantity} units of previously recorded loot (a drop,
	 * equip-transient, or returned-stack reversal), removing value at the current
	 * average and dropping the entry once empty. Returns the quantity actually
	 * reversed — 0 if none of it was held as loot (e.g. dropping a never-looted,
	 * pre-owned item) — so a caller can restore exactly that much if the units
	 * legitimately return.
	 */
	public long reverseLoot(int itemId, long quantity)
	{
		if (quantity <= 0)
		{
			return 0L;
		}
		Held h = held.get(itemId);
		if (h == null || h.quantity <= 0)
		{
			return 0L;
		}
		long remove = Math.min(quantity, h.quantity);
		long removeValue = Math.round((double) h.value * remove / h.quantity);
		h.quantity -= remove;
		h.value -= removeValue;
		if (h.quantity <= 0)
		{
			held.remove(itemId);
		}
		return remove;
	}

	/**
	 * Realises a Grand Exchange loot-sale: {@code quantity} units of {@code itemId}
	 * sold for {@code netProceeds} gp total (after GE tax). Caps at the held
	 * quantity so selling more than was looted (pre-owned excess) never inflates
	 * loot; only the looted portion's proportional proceeds are realised.
	 */
	public void realiseSale(int itemId, long quantity, long netProceeds)
	{
		if (quantity <= 0)
		{
			return;
		}
		Held h = held.get(itemId);
		if (h == null || h.quantity <= 0)
		{
			return;
		}
		long realiseQty = Math.min(quantity, h.quantity);
		long removeValue = Math.round((double) h.value * realiseQty / h.quantity);
		h.quantity -= realiseQty;
		h.value -= removeValue;
		realised += Math.round((double) netProceeds * realiseQty / quantity);
		if (h.quantity <= 0)
		{
			held.remove(itemId);
		}
	}

	/** The Loot number: still-held loot at pickup value + realised after-tax sale proceeds. */
	public long lootValue()
	{
		long total = realised;
		for (Held h : held.values())
		{
			total += h.value;
		}
		return total;
	}

	/** Clears all state for a new session. */
	public void reset()
	{
		held.clear();
		realised = 0L;
	}
}

package com.ospulse.session;

import java.util.regex.Pattern;

/**
 * Classifies tracked items as "supplies" (consumables typically burned through
 * during a session: potions, food, ammunition, runes, fishing bait) using a
 * small, data-light set of name patterns rather than a large hardcoded item-id
 * list.
 *
 * <p>This is deliberately a heuristic, not an exhaustive taxonomy:
 * <ul>
 *   <li>Potions/food/ammo/runes are common enough, and named consistently
 *       enough, that regex matching on the item name catches the vast
 *       majority without needing per-item ids.</li>
 *   <li>False negatives (a consumable this doesn't recognise) are NOT merely
 *       cosmetic. This comment used to claim they "still reduce profit as
 *       before, just without a line item" — true under the old top-down model,
 *       which measured wealth change directly and so caught every cost whether
 *       or not it was named. Under the bottom-up model (Profit = Loot −
 *       Supplies, see {@code SessionEngine#snapshot}) profit is BUILT from what
 *       is recognised, so an unrecognised input that was never looted has
 *       nothing to charge against and its cost is silently discarded — the
 *       value lands in the "Bank" residual instead. A miss here is a real
 *       accounting hole, not a missing line item.</li>
 *   <li>The episode ledger ({@code SessionEngine}'s skilling P&L) closes that
 *       hole for the case it was actually costing money — production skilling,
 *       where inputs like "Clean toadflax" or "Toadflax potion(unf)" match
 *       nothing here — by valuing the whole conversion rather than relying on
 *       this classifier to name its inputs. Outside an episode the hole above
 *       still applies, so adding a genuinely-missing pattern is still worth
 *       doing.</li>
 *   <li>False positives are guarded against by keeping the patterns narrow
 *       (e.g. "rune" alone would match "runite ore"/"rune platebody"; we
 *       require a known rune-name prefix instead).</li>
 * </ul>
 *
 * <p>To extend: add a new pattern (or a name) to the relevant list below.
 * Keep patterns anchored/specific enough to avoid catching gear or raw
 * materials that merely share a substring with a consumable name.
 */
public final class SupplyClassifier
{
	/** Potions: "<name> potion(#)", "<name> mix(#)", "<name> flask(#)", etc. */
	private static final Pattern POTION_PATTERN = Pattern.compile(
		"(?i).*\\b(potion|mix|flask|brew|barbarian mix)\\s*\\(?\\d?\\)?$");

	/** Ammunition: arrows, bolts, darts, javelins, thrown knives/axes, cannonballs, and tips. */
	private static final Pattern AMMO_PATTERN = Pattern.compile(
		"(?i).*\\b(arrow|bolts?|dart|javelin|throwing knife|thrown knife|"
			+ "chinchompa|bolt tips?|dragonfire|knife|cannonball)s?$");

	/** Runes: elemental/catalytic/combination runes by their canonical names. */
	private static final Pattern RUNE_PATTERN = Pattern.compile(
		"(?i)^(air|water|earth|fire|mind|body|cosmic|chaos|nature|law|death|"
			+ "blood|soul|astral|wrath|mist|dust|smoke|steam|lava|"
			+ "old school)\\s+rune$");

	/**
	 * Food: broad net of common consumable-food name patterns. Kept separate
	 * from potions since food names don't share the "(N)" dose suffix.
	 */
	private static final Pattern FOOD_PATTERN = Pattern.compile(
		"(?i).*\\b(shark|lobster|swordfish|monkfish|karambwan|anglerfish|"
			+ "manta ray|tuna|salmon|trout|pike|herring|sardine|shrimp|"
			+ "anchovies|cake|pie|stew|bread|cheese|tomato|potato|"
			+ "kebab|jug of wine|pizza|curry|crab|mackerel|cod|bass|"
			+ "meat|rocktail|cooked)s?$");

	/**
	 * Teleport tablets and other single-use teleport consumables: single-charge
	 * items burned on use exactly like a potion dose or a piece of food (e.g.
	 * "Teleport to house", "Varrock teleport", "Ardougne teleport", "Teleport to
	 * target"). Deliberately requires the "teleport" word itself so it doesn't
	 * catch teleport jewellery (rings/amulets/capes), which are equipped gear
	 * with charges, not a tracked-wealth item whose whole stack is consumed the
	 * way a tablet is; those are out of scope for this classifier the same way
	 * other equippable-with-charges items are.
	 */
	private static final Pattern TELEPORT_PATTERN = Pattern.compile(
		"(?i)^(teleport to [\\w' ]+|[\\w' ]+ teleport)\\s*(tablet)?$");

	/**
	 * Fishing bait and other single-use fishing consumables burned per catch:
	 * feathers (incl. coloured fletching feathers, all consumed the same way),
	 * fishing bait, sandworms, fish offcuts and raw karambwanji. Anchored at the
	 * word end so it catches "Stripy feather" but not fishing TOOLS ("Fishing
	 * rod", "Small fishing net", "Dragon harpoon") which merely share a theme.
	 */
	private static final Pattern BAIT_PATTERN = Pattern.compile(
		"(?i).*\\b(feathers?|fishing bait|sandworms?|fish offcuts|raw karambwanji)$");

	/**
	 * Generic fallback for any 1-4 dose consumable (potions, brews, restores,
	 * etc.) whose base name isn't otherwise recognised by {@link
	 * #POTION_PATTERN}. Bounded to doses 1-4 deliberately: charged jewellery
	 * (e.g. "Amulet of glory(6)", "Ring of dueling(8)") uses higher charge
	 * counts in the same "(n)" suffix position and must NOT be swept up here —
	 * those are equippable gear with charges, not a consumed tracked-wealth
	 * stack.
	 */
	private static final Pattern DOSE_PATTERN = Pattern.compile("(?i).*\\([1-4]\\)$");

	private SupplyClassifier()
	{
	}

	/**
	 * @return true if {@code itemName} looks like a consumable supply item
	 *         (potion, food, ammunition, rune, fishing bait or teleport tablet)
	 *         worth tracking as "supplies used" when its quantity decreases.
	 */
	public static boolean isConsumable(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		String trimmed = itemName.trim();
		return POTION_PATTERN.matcher(trimmed).matches()
			|| AMMO_PATTERN.matcher(trimmed).matches()
			|| RUNE_PATTERN.matcher(trimmed).matches()
			|| FOOD_PATTERN.matcher(trimmed).matches()
			|| BAIT_PATTERN.matcher(trimmed).matches()
			|| TELEPORT_PATTERN.matcher(trimmed).matches()
			|| DOSE_PATTERN.matcher(trimmed).matches();
	}
}

package com.ospulse.session;

/** A single item gained via a RuneLite LootReceived event this tick. */
public final class LootReceipt
{
	public final int itemId;
	public final long quantity;
	public final long unitValue;
	/**
	 * True when this receipt is already known to route to a non-readable storage
	 * container that never touches the inventory diff — the fish barrel's inferred
	 * catches (see {@code FishBarrelTracker}), which fire no real LootReceived
	 * event. Such a receipt is eligible for the stored-loot ledger regardless of
	 * {@code SessionEngine.SACK_ROUTED_ITEM_IDS}; a plain (false) receipt for a
	 * non-sack id is not, so an over-reported quantity can never seed a phantom
	 * balance. The same-tick inventory-landing check still applies as a safety net.
	 */
	public final boolean storageRouted;
	/**
	 * What RuneLite said produced this loot (NPC/boss/activity name), or null
	 * when the receipt has no source — an inferred receipt (the fish barrel) or
	 * an event RuneLite raised with an empty source. Carried so a caller
	 * reconciling the inventory diff against this tick's receipts can tell a
	 * matched appearance apart from one nothing reported, and name it accordingly.
	 */
	public final String source;

	public LootReceipt(int itemId, long quantity, long unitValue)
	{
		this(itemId, quantity, unitValue, false, null);
	}

	public LootReceipt(int itemId, long quantity, long unitValue, boolean storageRouted)
	{
		this(itemId, quantity, unitValue, storageRouted, null);
	}

	public LootReceipt(int itemId, long quantity, long unitValue, boolean storageRouted, String source)
	{
		this.itemId = itemId;
		this.quantity = quantity;
		this.unitValue = unitValue;
		this.storageRouted = storageRouted;
		this.source = source;
	}
}

